/* Generated by tools/editorial/compile_main_story_k.cjs from tools/editorial/main_story_k/*.md. Do not edit by hand. */
(function(root){root.CRPGMainStoryK={"version":1,"chains":[{"id":"ISK_L01_K","entry":"ISK_L01_K_001","items":[{"k":"keep","id":"ISK_L01_K_001","text":"성문 밖의 길은 멀리서 볼 때보다 좁았다. 어깨끈을 당겼다가, 진이 보고 있다는 걸 알고 아무렇지 않은 척 손을 내렸다."},{"k":"line","id":"PRO_L01K_depart_001","speaker":"진","text":"잠깐만요. 가방끈이 뒤집혔어요. 그대로 걸으면 어깨가 쓸립니다.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_002","text":"잠깐. 가방끈이 뒤집혔어. 그대로 걸으면 어깨 쓸려."}},{"k":"line","id":"PRO_L01K_depart_003","speaker":"나","text":"출발도 전에 들켰네요. 사실 알고 있었는데 고치기 귀찮았어요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_004","speaker":"진","text":"솔직한 건 좋은데, 먼 길에서는 그 귀찮음이 제일 비쌉니다. 내려 보세요.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_005","text":"솔직한 건 좋은데, 먼 길에선 그 귀찮음이 제일 비싸. 내려 봐."}},{"k":"line","id":"PRO_L01K_depart_006","speaker":"","text":"진은 천을 접어 끈 아래에 받쳐 주었다. 다시 멘 가방은 거짓말처럼 가벼웠다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_007","speaker":"나","text":"와. 단장님, 기사단 그만두시면 가방 가게 하세요. 제가 첫 손님 할게요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_008","speaker":"진","text":"그 전에 첫 손님이 리월에 무사히 도착해야겠죠. 편지 주세요. 맛있는 것 얘기는 그다음 줄에 써도 됩니다.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_009","text":"그 전에 첫 손님이 리월에 무사히 도착해야지. 편지 보내. 맛있는 거 얘기는 그다음 줄에 써도 돼."}},{"k":"line","id":"PRO_L01K_depart_010","speaker":"","text":"발길을 떼려다 멈췄다. 죽어 있던 드발린. 그 모습이 아직 눈에 남아 있었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_011","speaker":"나","text":"단장님. 드발린이 죽어 있었던 거, 기록에 남겨 주세요. 제가 잘못 본 게 아니니까요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_012","speaker":"진","text":"남깁니다. 저도 그 자리에 있었어요. 죽은 것도, 다시 날아오른 것도요.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_013","text":"남길게. 나도 그 자리에 있었잖아. 죽은 것도, 다시 날아오른 것도."}},{"k":"line","id":"PRO_L01K_depart_014","speaker":"나","text":"……그 말이면 됐어요. 다녀올게요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_depart_015","speaker":"진","text":"필요하면 연락하세요. 몬드에서 겪은 일은 제가 증언합니다. 오늘은 도착해서 쉴 곳부터 찾으시고요.","map":"MAP_MOND_CITY","alt":{"id":"PRO_L01K_depart_016","text":"필요하면 연락해. 몬드에서 겪은 일은 내가 증언할게. 오늘은 도착해서 쉴 곳부터 찾고."}},{"k":"line","id":"PRO_L01K_depart_017","speaker":"","text":"진은 손을 들어 배웅한 뒤 성안으로 돌아갔다. 한 번 돌아보고, 두 번째는 참았다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_road_001","speaker":"","text":"성벽이 손톱만 해질 때까지 걸었다. 걷는 건 여전히 귀찮았다. 그래도 경치가 좋으니 반쯤은 참을 만했다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_road_002","speaker":"","text":"그 반을 다 쓰기도 전에 풀숲이 흔들렸다. 가면 쓴 머리가 셋. 츄츄족이었다. 이 세계는 길에서 쉬는 걸 허락하지 않는 모양이었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_road_003","speaker":"나","text":"안녕하세요. 지나가는 사람인데요. 돈 없고, 먹을 것도 없고……","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_road_004","speaker":"","text":"대답은 곤봉이었다.","map":"MAP_MOND_CITY"},{"k":"combat","id":"PRO_L01K_road_005","group":"EG_MOND_HILI_PATROL","text":"길을 막은 츄츄족 순찰대. 리월로 가는 길은 지나가야 열린다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_road_006","speaker":"","text":"마지막 한 마리가 풀숲으로 달아났다. 숨을 고르며 가방을 고쳐 멨다. 진이 받쳐 준 천은 그 와중에도 제자리에 있었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_L01K_road_007","speaker":"나","text":"……가방 가게, 진심으로 추천이네.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_L01_K_016","text":"해가 기울 무렵 망서 객잔의 기둥이 보였다. 반가움은 짧았다. 객잔 아래 짐을 올리는 승강기가 한쪽으로 기울어 있었고, 끊어질 듯한 줄 끝에 짐꾼 하나가 매달려 있었다. 두 사람이 그 아래로 달려왔다."},{"k":"line","id":"PRO_L01K_wangshu_001","speaker":"","text":"상자를 치운 자리로 줄이 또 한 뼘 미끄러졌다. 위에서 짐꾼이 숨을 들이켰다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_wangshu_002","options":[{"label":"받침목 여기 있어요! 제가 끼울 테니 자리만 짚어 줘요!","keep":"REV02_K_LIFT_C1","items":[{"k":"line","id":"PRO_L01K_wangshu_003","speaker":"중운","text":"거기! 바퀴 뒤쪽! 더 깊이!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_004","speaker":"","text":"받침목이 들어가자 승강기가 덜컥 멈췄다. 행추가 줄을 당겨 짐꾼을 끌어올렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_005","speaker":"행추","text":"자네, 손이 빠르군. 받침 자리를 한 번에 찍었어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_006","speaker":"나","text":"운이야. 두 번째였으면 손 떨려서 못 했어.","map":"MAP_LIYUE_PLAINS"}]},{"label":"줄은 못 버텨요! 이 천 펴요! 거기 두 분, 구경 말고 모서리 좀!","keep":"REV02_K_LIFT_C2","items":[{"k":"line","id":"PRO_L01K_wangshu_007","speaker":"","text":"구경꾼 둘이 얼떨결에 천을 잡았다. 줄이 끊어진 건 그 직후였다. 짐꾼은 천 위로 떨어져 한 바퀴 굴렀고, 나는 그 반동에 엉덩방아를 찧었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_008","speaker":"중운","text":"다친 사람 없지? 없으면 다들 숨 한 번씩!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_009","speaker":"행추","text":"줄이 못 버틴다는 걸 먼저 본 사람은 자네뿐이었네.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_010","speaker":"나","text":"칭찬은 내 허리한테 해 줘. 바닥이 생각보다 딱딱해.","map":"MAP_LIYUE_PLAINS"}]},{"label":"손이 모자라잖아요! 저도 줄 잡을게요! 저까지 딸려가면 잡아 줘요!","keep":"REV02_K_LIFT_C3","items":[{"k":"line","id":"PRO_L01K_wangshu_011","speaker":"","text":"줄을 잡은 순간 발이 바닥에서 떴다. 중운이 내 허리띠를 잡아 끌어내렸고, 그 사이 행추가 짐꾼을 받쳐 올렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_012","speaker":"중운","text":"딸려가면 잡아 달라더니 진짜 딸려가는 사람은 처음 봤다!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_013","speaker":"행추","text":"그래도 줄이 멈췄네. 자네 몸무게가 받침목 몫을 했어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_014","speaker":"나","text":"그 말 칭찬 맞지? 일단 받아 둘게. 다음엔 받침목 들게.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_wangshu_015","speaker":"","text":"짐꾼은 땅에 내려서자마자 쭈그려 앉아 허리를 두드렸다. 한참 뒤에야 우리 쪽을 올려다봤다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_016","speaker":"짐꾼","text":"사람 셋이 달라붙어서 간신히 내린 게 이 몸뚱이 하나라니. 짐은 떨어졌소?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_017","speaker":"중운","text":"짐보다 아저씨가 먼저죠!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_018","speaker":"짐꾼","text":"짐이 떨어지면 내 품삯이 떨어지는 거라오. 어쨌든…… 고맙소. 셋 다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_019","speaker":"","text":"'셋'이라고 셀 때 내 쪽도 한 번 보았다. 묘하게 뿌듯했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_020","speaker":"행추","text":"우리는 객잔에 짐을 올려 두고 바로 떠나야 하네. 자네는?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_021","speaker":"나","text":"오늘은 여기서 자. 내일 리월항으로 가고. 가서 할 일이 있어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_022","speaker":"행추","text":"그럼 항구 근처에서 다시 보겠군. 요즘 그쪽이 조금 시끄러워서 말이야. 중운, 가자.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_023","speaker":"중운","text":"아까 그 책, 먼저 주워 두라고 했잖아!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_024","speaker":"","text":"두 사람이 멀어진 뒤에도 승강기 줄은 바람에 흔들렸다. 그때 등 뒤에서 목소리가 들렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_025","speaker":"소","text":"움직이지 마.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_026","speaker":"","text":"돌아보자 지붕 위에 창을 든 사람이 서 있었다. 가면은 없었지만 눈빛만으로 알 수 있었다. 소. 이 객잔을 지키는 선인.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_027","speaker":"소","text":"네 주변에서 낯선 냄새가 난다. 죽음과 생명의 냄새가 함께. 사람 하나에게서 나기엔 이상한 조합이지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_028","speaker":"나","text":"……저 오늘 씻긴 했는데요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_029","speaker":"소","text":"농담할 상대를 잘못 골랐다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_030","speaker":"나","text":"죄송합니다. 무서우면 입이 먼저 나가서요. 제가 뭘 한 건 아니에요. 적어도 제가 아는 한은요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_031","speaker":"소","text":"그렇게 보인다. 네가 남을 해쳤다는 징후는 없어. 하지만 마신을 미워하는 기척이 네 곁을 스쳤다. 네 것인지, 네가 지나온 곳의 것인지는 모른다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_032","speaker":"나","text":"그럼 저는 어떡해야 합니까?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_033","speaker":"소","text":"이상을 느끼면 모르는 척하지 마. 그 정도다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_034","speaker":"","text":"다음 질문을 꺼내기 전에 지붕 위는 비어 있었다. 바람 소리만 남았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_001","speaker":"","text":"객잔 종업원이 방 열쇠와 함께 따뜻한 물을 내줬다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_002","speaker":"객잔 종업원","text":"승강기 일은 들었어요. 오늘은 그냥 쉬세요. 지붕 위 그분 말씀, 무서워도 틀린 적은 없거든요. 그러니까 더 쉬셔야 하고요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_003","speaker":"나","text":"그분이 말 거는 거, 흔한 일은 아니죠?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_004","speaker":"객잔 종업원","text":"저는 여기 삼 년째인데 처음 봐요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_005","speaker":"나","text":"……그 말은 안 해 주셔도 됐는데.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_006","speaker":"","text":"누워도 죽음과 생명의 냄새라는 말이 천장에 붙어 있었다. 드발린의 식은 몸, 다시 날아오르던 모습. 잠은 늦게 왔다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_064","text":"아침 길에 어제의 짐꾼을 다시 만났다. 어제 떨어질 뻔한 포대를 등에 얹고 있었다. 돕겠다고 손을 뻗자 먼저 내 신발부터 내려다봤다."},{"k":"line","id":"PRO_L01K_wangshu_night_007","speaker":"짐꾼","text":"그 신발로 내 짐까지 들면 리월에는 발바닥만 도착하겠네. 옆에서 길이나 봐 주시오. 수레 오면 소리 지르고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_008","speaker":"나","text":"그 정도는 자신 있어요. 소리 지르는 건 제 특기거든요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_009","speaker":"짐꾼","text":"어제 봤소. 리월항까지 가지? 같이 가지. 혼자 걷는 길은 길어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_wangshu_night_010","speaker":"","text":"그렇게 동행이 생겼다. 그는 이름을 말하지 않았고, 나도 묻지 않았다. 아직은 짐꾼과 손님으로 충분했다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_069","text":"귀리 평원으로 접어들자 오래된 돌무더기가 길 양쪽에 늘어났다. 폐허는 오래 보지 않았다. 드발린이 떨어졌을 때의 울림이 이런 돌벽에서 쉽게 떠올랐다."},{"k":"line","id":"PRO_L01K_guili_001","speaker":"짐꾼","text":"자네, 어제 지붕 위 그분하고 말했지? 뭐라던가?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_002","speaker":"나","text":"제 주변에 이상한 게 있다고요. 뭔지는 자기도 모른다고 했어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_003","speaker":"짐꾼","text":"그러면 모르는 거지. 선인이 모르는 걸 자네가 밤새 고민해서 알겠소.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_004","speaker":"나","text":"아저씨, 그거 지금 제가 들은 말 중에 제일 위로가 되는 말이에요. 조금 슬프네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_005","speaker":"짐꾼","text":"위로하려고 한 말은 아니오.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_006","speaker":"","text":"앞줄이 멈출 때마다 그는 포대를 내려놓고, 나는 앞을 보러 갔다. 짐은 그가, 길은 내가 살폈다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_007","speaker":"","text":"세 번째로 앞을 보러 갔을 때, 폐허 그늘에서 사람 셋이 나왔다. 짐꾼들의 수레를 노리는 눈이었다. 보물 사냥단. 이름만 거창하고 하는 짓은 날강도였다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_008","speaker":"보물 사냥단","text":"짐은 두고 가. 다치고 싶지 않으면.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_009","speaker":"나","text":"저 짐 아니에요. 저는 그냥 길 보는 사람인데요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_010","speaker":"보물 사냥단","text":"그럼 넌 길 보다가 다치는 거지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_011","speaker":"나","text":"아, 그렇게 되는 거구나.","map":"MAP_LIYUE_PLAINS"},{"k":"combat","id":"PRO_L01K_guili_012","group":"EG_TREASURE_PATROL","text":"귀리 평원의 보물 사냥단 습격조. 짐꾼의 수레를 지켜야 한다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_013","speaker":"","text":"사냥단이 폐허 너머로 흩어졌다. 돌아보니 짐꾼은 포대 위에 앉아 구경하고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_014","speaker":"짐꾼","text":"길 봐 달라고 했더니 길을 아주 깨끗하게 치워 놓는구먼.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_015","speaker":"나","text":"손뼉이라도 쳐 주세요. 품삯은 안 받을 테니까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_guili_016","speaker":"짐꾼","text":"품삯은 내가 못 받고 있소.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_075","text":"리월항 입구는 수레와 사람으로 막혀 있었다. 차단선 옆에서 보라색 머리의 여자가 직접 포대를 옮기고 있었다. 각청. 칠성이 여기서 짐을 나르고 있을 줄은 몰랐다. 눈이 마주쳤다."},{"k":"line","id":"PRO_L01K_blockade_001","speaker":"각청","text":"구경할 힘은 남았나 보네. 그 줄 좀 잡아 줘. 이야기는 사람들이 그늘로 옮겨 간 다음에.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_002","speaker":"나","text":"저 방금 도착했는데요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_003","speaker":"각청","text":"그래서 힘이 남았잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_004","speaker":"","text":"반박할 말이 없었다. 그늘막 줄을 잡고 한 시간이 지났다. 각청은 접수대 위에 두 장의 표를 나란히 놓았다. 같은 짐인데, 아래 붙은 설명이 서로 달랐다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_005","speaker":"각청","text":"이건 물건을 넘겼다는 확인서. 이쪽은 같은 짐을 받지 못했다는 신고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_006","speaker":"나","text":"같은 짐인데요? 그럼 누가 거짓말을……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_007","speaker":"각청","text":"몰라. 기억이 끊긴 사람도 있거든. 검사했다는 표식은 있는데 검사한 기억이 없대.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_008","speaker":"나","text":"……그건 무섭네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_009","speaker":"각청","text":"무서워. 그래서 아무도 못 들여보내고 있는 거야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_010","speaker":"","text":"각청은 뒤쪽 수레가 밀려오지 않도록 손을 들었다. 기다리라는 말을 들은 수레는 짐꾼의 것이었다. 그 옆의 병사는 아까부터 표찰만 들여다보고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_011","speaker":"나","text":"저 병사, 아까부터 표만 보고 있는데요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_012","speaker":"각청","text":"봤어. 내가 물어볼게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_013","speaker":"","text":"각청은 병사에게 표를 받아 글씨가 보이도록 돌려 주었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_014","speaker":"각청","text":"어디까지 확인했어? 마지막으로 본 짐을 짚어 줘.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_015","speaker":"천암군 병사","text":"그게…… 잠시만요. 다시 보면 알 수 있을 것 같습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_016","speaker":"","text":"병사의 손가락이 같은 줄을 몇 번이나 오갔다. 각청은 재촉하지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_017","speaker":"천암군 병사","text":"죄송합니다. 한 번만 더……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_018","speaker":"각청","text":"사과부터 할 필요 없어. 교대하고 물 좀 마셔. 이 표는 내가 볼게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_019","speaker":"","text":"병사가 자리를 뜨자 각청은 표를 접수대 한쪽에 따로 놓았다. 서류 밑에 들어가지 않도록 모서리를 밖으로 빼 두었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_020","speaker":"나","text":"못 떠올리는 사람만 잘못한 것 같아지네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_blockade_021","speaker":"각청","text":"그래서 내가 여기 있는 거야. 사람 하나 쥐어짜서 끝낼 거면 칠성이 짐 나를 필요 없지.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_105","text":"접수대 뒤 공고를 다시 보았다. 송신의례. 내가 아는 이야기에서 이 시기에 열리는 것은 청신의례였다. 글자 하나가 다른데, 그 하나가 어떤 뜻인지는 알 수 없었다. 그때 봉쇄선 밖에서 아는 목소리가 들렸다."},{"k":"line","id":"PRO_L01K_desk_001","speaker":"","text":"돌아오자 각청이 접수대 한쪽을 비워 주었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_002","speaker":"각청","text":"더 알릴 일 있어? 직접 본 거든 들은 거든.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_desk_003","options":[{"label":"확실하지 않은 얘기도 해도 돼요?","id":"PRO_L01K_desk_004","items":[{"k":"line","id":"PRO_L01K_desk_005","speaker":"각청","text":"확실하지 않다고 말하면 돼. 판단은 내가 해.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_006","speaker":"나","text":"그럼, 좀 이상하게 들려도 끝까지 들어 주세요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_007","speaker":"각청","text":"오늘 들은 이상한 얘기 중에 네 게 제일 이상할 것 같진 않아. 해 봐.","map":"MAP_LIYUE_PLAINS"}]},{"label":"잠깐만요. 어디서부터 말해야 할지……","id":"PRO_L01K_desk_008","items":[{"k":"line","id":"PRO_L01K_desk_009","speaker":"각청","text":"급하게 맞추지 마. 생각나는 것부터.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_010","speaker":"","text":"각청은 펜을 내려놓고 뒤에 선 사람을 옆 접수대로 보냈다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_desk_011","speaker":"나","text":"……네. 잠깐만요.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_desk_012","speaker":"","text":"입을 열려다 어젯밤의 경고가 떠올랐다. 내 주위에서 죽음의 냄새가 난다는 말. 옆에서는 짐꾼이 같은 포대의 끈을 다시 풀고 있었다. 교대한 병사가 또 그 포대를 세고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_001","options":[{"label":"제 얘기부터 할게요. 어젯밤 소에게 경고를 들었어요.","keep":"ISK_L01_K_1_CHOOSE","items":[{"k":"line","id":"PRO_L01K_fork_002","speaker":"","text":"소의 이름에 각청이 고개를 들었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_003","speaker":"각청","text":"호법야차님이? 너한테 직접?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_004","speaker":"나","text":"망서 객잔 지붕에서요. 제 주위에…… 죽음과 생명의 냄새가 같이 난댔어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_005","speaker":"각청","text":"……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_006","speaker":"각청","text":"너 대체 뭘 하고 다닌 거야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_007","speaker":"나","text":"가방끈 고치고, 승강기 받치고, 걸었어요. 그게 다예요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_008","speaker":"","text":"각청은 줄 선 사람들을 돌아본 뒤 접수대 옆으로 자리를 옮겼다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_009","speaker":"각청","text":"이쪽에서 하자. 그분이 네 몸에서 난다고 하셨어?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_010","speaker":"나","text":"모르겠대요. 마신을 미워하는 기척도 있다는데, 전 마신한테 감정 없어요. 만난 적도 없고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_011","speaker":"각청","text":"알았어. 그 말만으로 널 어떻게 할 생각은 없어. 그렇다고 그냥 넘길 수도 없고.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_012","options":[{"label":"저도…… 저 병사처럼 될까요?","id":"PRO_L01K_fork_013","items":[{"k":"line","id":"PRO_L01K_fork_014","speaker":"각청","text":"아직 그렇게 볼 근거는 없어. 오늘 온 길은 기억나?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_015","speaker":"나","text":"네. 다만 어젯밤에…… 잠을 거의 못 잤어요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"말 안 하면 더 불안할 것 같았어요.","id":"PRO_L01K_fork_016","items":[{"k":"line","id":"PRO_L01K_fork_017","speaker":"각청","text":"잘 말했어. 몸은? 빠진 기억이나 이상한 데는?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_018","speaker":"나","text":"몸은 괜찮아요. 잠을 좀 설쳤어요.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_fork_019","speaker":"각청","text":"잠 설친 건 그렇게 적을게. 다른 걸로 바꿔 적진 않아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_020","speaker":"","text":"각청은 들은 경고와 지금 대답을 따로 적고, 종이를 이쪽으로 돌려 빠진 말이 없는지 짚어 주었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_021","speaker":"나","text":"이상한 사람 취급할 줄 알았는데.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_022","speaker":"각청","text":"불안해서 찾아온 사람한테 겁 더 줘서 뭐 해. 넌 지금 손 떨고 있어. 알아?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_023","speaker":"나","text":"……몰랐어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_024","speaker":"","text":"그때 차단선 쪽에서 쇠 부딪히는 소리가 났다. 교대한 병사가 수레를 통과시키려 차단봉을 올리고 있었다. 봉 아래에는 아직 짐꾼이 포대를 묶고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_025","options":[{"label":"잠깐만요! 아래에 아직 사람 있어요! 통과 취소!","keep":"REV02_K1_REPEAT_C1","items":[{"k":"line","id":"PRO_L01K_fork_026","speaker":"","text":"수레가 멈췄다. 병사는 봉을 올린 자기 손을 내려다보더니, 왜 올렸는지 모르겠다는 얼굴로 굳었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_027","speaker":"각청","text":"봉 내려. 천천히. 그대로 두고 물러서.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_028","speaker":"짐꾼","text":"……자네 목소리 큰 줄은 알았지만 이 정도일 줄은. 덕분에 머리가 붙어 있소.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_029","speaker":"나","text":"특기라고 했잖아요. 목은 좀 아프네요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"방금 하신 것부터 같이 봐요. 수레가 지나가기 전에 봉을 올리셨어요. 지금 손부터 빼요.","keep":"REV02_K1_REPEAT_C2","items":[{"k":"line","id":"PRO_L01K_fork_030","speaker":"","text":"병사는 내 말을 듣고서야 자기 손을 보았다. 봉이 내려왔고, 수레는 그 앞에 섰다. 짐꾼은 그제야 머리 위에 무엇이 있었는지 알았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_031","speaker":"각청","text":"봉이 먼저야, 수레가 먼저야?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_032","speaker":"나","text":"봉이요. 통과하라는 말은 없었어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_033","speaker":"각청","text":"적을게. 네가 본 순서대로.","map":"MAP_LIYUE_PLAINS"}]},{"label":"이거부터 올리면 되잖아! 잠깐, 왜 더 내려가…… 각청, 나 이거 잘못 잡았어!","keep":"REV02_K1_REPEAT_C3","items":[{"k":"line","id":"PRO_L01K_fork_034","speaker":"","text":"봉을 붙잡았는데 반대쪽이 올라갔다. 각청이 뛰어와 내 손 위에 손을 얹었다. 봉이 제자리에 멈췄다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_035","speaker":"각청","text":"손 떼지 말고 그대로. 됐어. 이제 떼.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_036","speaker":"짐꾼","text":"구해 주려던 건 알겠는데, 다음엔 소리만 지르시오.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_037","speaker":"나","text":"……네. 손이 먼저 나갔어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_038","speaker":"각청","text":"손이 먼저 나가는 건 좋은데 방향은 좀 보고 나가.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_fork_039","speaker":"","text":"병사는 자기가 봉을 올렸다는 사실을 끝까지 떠올리지 못했다. 짧은 빈틈. 각청이 말한 것이 이거였다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_120","text":"각청은 범인을 묻지 않았다. 대신 어느 대목에 다른 사람이 함께 있었는지 물었다. 소의 경고, 그리고 방금 본 일. 내 이름 옆에 두 줄이 적혔다."},{"k":"line","id":"PRO_L01K_fork_040","speaker":"각청","text":"네 자리는 저쪽 그늘이야. 바깥쪽 별도 대기 자리. 어디 갈 땐 옆 병사한테 방향만 알려 줘.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_041","speaker":"나","text":"물 마시러 가는 것도요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_042","speaker":"각청","text":"그건 그냥 가. 그런 것까지 허락받으면 너부터 이상해져.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_043","speaker":"각청","text":"다음 교대 때 같은 질문 또 할 거야. 그전에 몸이 이상하면 먼저 말해. 해 지도록 혼자 두진 않을게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_044","speaker":"","text":"각청은 자리를 뜨기 전에 물을 놓아 주었다. 붙잡혔다고 하기에는 친절했고, 안심하기에는 모르는 것이 너무 많았다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_1_END","text":"리월항 밖 별도 대기 자리. 각청에게 소의 경고와 드발린의 죽음·부활을 보았다는 사실을 알렸다. 통행은 닫혀 있고, 옥경대로 가는 별도 길은 안내만 받았다."}]},{"label":"저 포대부터 봐 주세요. 아까 풀려 있던 끈을 봤어요.","keep":"ISK_L01_K_2_CHOOSE","items":[{"k":"line","id":"PRO_L01K_fork_045","speaker":"각청","text":"어느 포대? 건드리지 말고, 본 자리부터.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_046","speaker":"","text":"색이 다른 끈을 가리키자 각청이 수레 앞에 멈췄다. 짐꾼이 접힌 표를 내밀었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_047","speaker":"짐꾼","text":"아까 여기서 풀고 다시 묶었습니다. 또 풀라니…… 이 포대만 몇 번째인지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_048","speaker":"천암군 병사","text":"표시는 있습니다. 하지만 제가 안을 본 기억이 없어서……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_049","speaker":"나","text":"끈이 바닥에 풀린 건 봤어요. 밟을 뻔했거든요. 안쪽까지 본 건 아니고요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_050","speaker":"각청","text":"그 정도면 됐어. 끈 풀린 거랑 검사 끝난 건 따로 볼게.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_051","options":[{"label":"제가 서 있던 곳에서 보여 드릴까요?","id":"PRO_L01K_fork_052","items":[{"k":"line","id":"PRO_L01K_fork_053","speaker":"각청","text":"좋아. 넌 그대로 서 있어. 내가 움직일게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_054","speaker":"","text":"각청이 수레 옆으로 돌아서자, 아까 발을 피했던 자리를 가리켰다.","map":"MAP_LIYUE_PLAINS"}]},{"label":"포대는 그대로 두고, 표부터 같이 봐요.","id":"PRO_L01K_fork_055","items":[{"k":"line","id":"PRO_L01K_fork_056","speaker":"각청","text":"그러자. 또 풀면 남은 흔적도 바뀌니까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_057","speaker":"","text":"각청이 표를 펼쳤다. 짐꾼은 풀려던 끈에서 손을 뗐다.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_fork_058","speaker":"각청","text":"다음 짐은 잠깐 세워 줘. 옆 수레 것하고 섞이면 다시 봐야 해.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_059","speaker":"천암군 병사","text":"예. 수레를 비켜 두겠습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_060","speaker":"","text":"병사가 수레를 비키려 손잡이를 잡았다. 그 순간 수레가 비탈 쪽으로 미끄러졌다. 짐꾼의 손은 아직 포대 끈 사이에 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L01K_fork_061","options":[{"label":"짧은 손잡이부터 잠글게요. 쐐기는 그다음! 아저씨 손 들어가 있으면 수레 움직이지 마요!","keep":"REV02_K2_BRAKE_C1","items":[{"k":"line","id":"PRO_L01K_fork_062","speaker":"","text":"손잡이 옆 쇠고리를 당기자 바퀴가 잠겼다. 수레는 반 바퀴 돌고 멈췄다. 쐐기는 각청이 발로 밀어 넣었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_063","speaker":"짐꾼","text":"……어제는 사람 받침목, 오늘은 수레 받침목이구먼.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_064","speaker":"각청","text":"잠그는 법은 어디서 배웠어?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_065","speaker":"나","text":"어제 객잔 승강기에서요. 한 번 보면 잊기 어렵더라고요. 제 허리가 기억해요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"설명은 들었는데 제가 하면 하나는 틀릴 것 같아요. 직접 잠가 주세요. 저는 받침 가져올게요!","keep":"REV02_K2_BRAKE_C2","items":[{"k":"line","id":"PRO_L01K_fork_066","speaker":"","text":"각청이 두 걸음에 수레를 잡고 손잡이를 잠갔다. 내가 받침을 끌어와 바퀴 앞에 끼울 때쯤 수레는 이미 멈춰 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_067","speaker":"각청","text":"모르는 걸 모른다고 하는 건 빠르네. 받침은 잘 끼웠어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_068","speaker":"짐꾼","text":"둘이 그렇게 척척 맞으면 내 손은 어디다 쓰나.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_069","speaker":"나","text":"아저씨 손은 포대 끈에서 빼는 데 쓰세요. 아직 안 뺐잖아요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"긴 줄을 느슨하게 하면 빠지지 않을까? ……아니네, 이거 풀면 전부 쏟아지네!","keep":"REV02_K2_BRAKE_C3","items":[{"k":"line","id":"PRO_L01K_fork_070","speaker":"","text":"줄을 잡은 손을 급히 멈췄다. 그 사이 각청이 손잡이를 잠갔다. 포대 하나가 기울었지만 떨어지진 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_071","speaker":"각청","text":"손 멈춘 게 잘한 거야. 그 줄은 짐 전체를 묶는 줄이었어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_072","speaker":"나","text":"……하나 더 풀었으면 큰일 났겠네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_073","speaker":"짐꾼","text":"큰일은 내 허리가 났겠지. 그래도 멈춘 사람은 자네니까 됐소.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L01K_fork_074","speaker":"","text":"짐꾼이 끈 사이에서 손을 빼고 길게 숨을 내쉬었다. 각청은 포대를 봉하고 운송 기록을 따로 챙겼다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_153","text":"세 사람은 서로 다른 자리에서 같은 포대를 보았다. 병사의 기억이 돌아온 것은 아니었다. 그래도 새로 움직인 물건이 없다는 사실만은 그 자리에서 함께 확인할 수 있었다."},{"k":"line","id":"PRO_L01K_fork_075","speaker":"각청","text":"네 증언은 네가 본 것만 적었어. 더 넓히지도, 줄이지도 않았어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_076","speaker":"나","text":"그 정도면 충분해요. 저도 본 것만 말했으니까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_077","speaker":"짐꾼","text":"이 포대는 당분간 못 들어가겠지. 나도, 자네도.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_078","speaker":"각청","text":"물자 대기 구역에 자리를 마련할게요. 품삯 문제는 제가 확인하겠습니다. 두 번 일했다는 말로 끝나게 두지는 않을게요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L01K_fork_079","speaker":"","text":"각청이 짐꾼에게는 말을 높였다. 짐꾼은 처음으로 허리가 아닌 다른 이유로 고개를 숙였다. 어젯밤의 경고는 아직 말하지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L01_K_2_END","text":"리월항 밖 물자 대기 줄. 직접 본 인계의 흔적만 각청에게 증언하고 확인을 기다린다. 소의 경고는 아직 말하지 않았다. 항구는 봉쇄 상태다."}]}]}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L01_K_016_2","text":"나도 뭐든 할게! 도착하자마자 사람 떨어지는 거 구경할 생각은 없어."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_016_3","text":"그럼 아래를 맡아 줘. 난 행추, 저 친구는 중운. 소개가 좀 흔들리는군!"},{"k":"text","id":"V141_BEFORE_ISK_L01_K_016_4","text":"둘은 익숙하게 자리를 나눴다. 나는 팽팽한 줄을 피해 승강기 아래로 들어갔다. 받침목을 끼울 자리에 부서진 상자가 박혀 있었다."},{"k":"text","id":"V141_AFTER_ISK_L01_K_016_3","text":"소개 잘 들었어. 둘이 평소에도 이래? 대답은 저분 내려온 다음에!"},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_0","text":"잠깐. 본인이 검사했다는 표식은 있는데, 검사한 기억은 없다? 내가 잘못 들었으면 지금 끊어 줘."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_1","text":"어제 그 친구군! 하루 만에 다시 보다니. 저 짐꾼 아저씨도. 사라진 기억과 남겨진 화물이라…… 흥미로운 사건이네."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_2","text":"책 제목은 사건 끝난 뒤에 지어. 지금 저 병사는 잘못한 게 없어도 일자리를 잃을 수 있고, 저 아저씨는 품삯을 못 받아."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_3","text":"……그건 내가 가벼웠네. 비운 상회 쪽 인계 장소는 내가 안내할 수 있어."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_4","text":"행추, 어제는 고마웠어. 이쪽은…… 연비 맞지? 이름은 들어 봤어."},{"k":"text","id":"V141_BEFORE_ISK_L01_K_105_5","text":"응, 법률 자문. 지금은 비용보다 현장이 사라지는 게 급해. 저 짐이 어디서 인계됐는지, 귀리 평원의 짐터부터 같이 보자."},{"k":"text","id":"V141_AFTER_ISK_L01_K_105_0","text":"증거를 모으면 단번에 풀릴 줄 알았는데, 물어볼 사람이 늘었군."},{"k":"text","id":"V141_AFTER_ISK_L01_K_105_1","text":"그래서 결말을 먼저 쓰면 안 된다는 거야. 이건 내가 맡아 둘게. 넌 아까 그 병사한테 해고된 거 아니라고 전해 줘."},{"k":"text","id":"V141_AFTER_ISK_L01_K_105_2","text":"그 말은 내가 할게. 기다리는 입장이 얼마나 피곤한지 조금 알 것 같아서."}]},{"id":"ISK_L02_K1","entry":"ISK_L02_K1_001","items":[{"k":"keep","id":"ISK_L02_K1_001","text":"별도로 마련된 대기 자리는 생각보다 사람들의 왕래와 가까웠다. 소에게 들은 말을 각청에게 전한 뒤부터, 나는 남이 아니라 내 몸에서 먼저 이상을 찾게 되었다. 그 아침, 공고를 든 채 멍하니 앉아 있는 나에게 누군가 다가왔다."},{"k":"line","id":"PRO_L02K1_wait_001","speaker":"","text":"첫날 오후, 각청이 돌아왔을 때 나는 두 손가락을 손목 안쪽에 대고 있었다. 처음엔 맥박을 재려던 거였는데, 어느새 뛰고 있다는 걸 계속 확인해야만 손을 뗄 수 있었다. 각청은 그 손을 먼저 보았다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"REV02_K1_REPEAT_CALLBACK_1","text":"어제 소리쳐 사람들을 멈춰 세운 뒤로 목이 조금 쉬었다. 적어도 그때 내가 외쳤다는 건 기억했다. 손목에서 확인하려는 건 그보다 단순한 사실이었다."},{"k":"keep","id":"REV02_K1_REPEAT_CALLBACK_2","text":"어제 병사에게 손을 빼라고 말해 준 일이 떠올랐다. 이제는 내 손목을 놓아도 된다고 누가 말해 줬으면 했다. 남의 불안을 짚어 주는 건 내 손을 멈추는 것보다 쉬웠다."},{"k":"keep","id":"REV02_K1_REPEAT_CALLBACK_3","text":"어제 각청이 잘못 잡은 봉에서 내 손을 떼어 놓던 순간이 떠올랐다. 위험한 건 내 몸 안에서만 벌어지는 일이 아니었다."},{"k":"line","id":"PRO_L02K1_wait_002","speaker":"각청","text":"손목 왜 그래. 어디 아파?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_003","speaker":"나","text":"아뇨. 뛰고 있나 확인 중이에요. 자기 맥박한테 출석 부르는 중이라고 할까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_004","speaker":"각청","text":"……출석은 잘 나오고?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_005","speaker":"나","text":"아직 결석은 없어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_006","speaker":"각청","text":"그럼 그만 봐. 그 선인이 말한 건 네 주변 기척이지, 네가 죽었다는 판정이 아니야. 멀쩡한 사람이 자기 손목이나 보고 있으면 내가 더 불안해.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_007","speaker":"나","text":"머리로는 알아요. 그런데 옆 사람이 뭘 잊기라도 하면, 내가 너무 가까이 앉았나부터 생각하게 돼요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_008","speaker":"각청","text":"그래서 네가 오기 전 일하고 온 다음 일을 따로 보고 있는 거야. 네가 지나간 자리만 모으면 네가 범인이라는 얘기밖에 안 나와. 그건 조사가 아니라 핑계 찾기지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_009","speaker":"","text":"각청은 천막의 접힌 부분을 올려 바깥길이 보이게 했다. 밖이 보이자 숨겨진 사람처럼 앉아 있을 필요가 없어졌다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K1_wait_010","options":[{"label":"하루 종일 앉아 있으면 없는 증상도 만들어 낼 것 같아요. 좀 걸어도 돼요?","id":"PRO_L02K1_wait_011","items":[{"k":"line","id":"PRO_L02K1_wait_012","speaker":"각청","text":"걸어. 어디 가는지만 알려 주고. 널 가둬 두려고 만든 자리 아니야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_013","speaker":"나","text":"갇힌 게 아니라는 말이 듣고 싶었나 봐요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_014","speaker":"각청","text":"갇혔으면 천막 물이나 빼게 뒀겠어?","map":"MAP_LIYUE_PLAINS"}]},{"label":"확인할 때마다 저한테도 결과 알려 주세요. 뭘 적는지 모르고 앉아 있으면 괜찮다는 말도 무섭거든요.","id":"PRO_L02K1_wait_015","items":[{"k":"line","id":"PRO_L02K1_wait_016","speaker":"각청","text":"그건 당연히 해. 네 얘기는 네 앞에서 정리할게. 다른 병사 사정까지 다 보여 줄 순 없지만.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_wait_017","speaker":"나","text":"그거면 돼요. 고마워요.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K1_rain_001","speaker":"","text":"둘째 날에는 비가 들이쳤다. 내 자리 천막 끝으로 물이 몰리자, 각청이 직접 받침을 옮겨 천을 들어 올렸다. 손을 보태려 일어서자 그녀가 손가락부터 가리켰다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_002","speaker":"각청","text":"줄 당기는 사람하고 받침 미는 사람을 나눠. 둘이 같이 힘주면 기둥만 넘어가.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K1_rain_003","options":[{"label":"리월 칠성하고 천막 물 빼는 중이네요. 나중에 누가 대접 잘 받았냐고 물으면 뭐라고 하죠?","id":"PRO_L02K1_rain_004","items":[{"k":"line","id":"PRO_L02K1_rain_005","speaker":"각청","text":"따뜻한 데 앉혀 주려다 물길을 잘못 잡았다고 해. 왼쪽 조금만 더. 그렇게 세게 잡으면 천 찢어져!","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_006","speaker":"나","text":"제가 도움받는 쪽인지 작업 지시받는 쪽인지 잠깐 헷갈렸어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_007","speaker":"각청","text":"둘 다야. 항의는 손에 걸린 거 빼고 해.","map":"MAP_LIYUE_PLAINS"}]},{"label":"왼쪽을 조금씩 당길게요. 어디까지인지는 보는 쪽에서 말해 줘요.","id":"PRO_L02K1_rain_008","items":[{"k":"line","id":"PRO_L02K1_rain_009","speaker":"각청","text":"그 속도가 낫겠어. 세게 당긴다고 물이 빨리 빠지는 게 아니니까. 거기. 멈춰.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_010","speaker":"나","text":"리월 칠성이 천막 물 빼는 걸 직접 가르쳐 주는 날이 올 줄은 몰랐어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_011","speaker":"각청","text":"나도 네가 이렇게 말 잘 듣는 사람일 줄은 몰랐어.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K1_rain_012","speaker":"","text":"물이 한꺼번에 빠지며 두 사람의 신발을 적셨다. 각청의 신발까지 젖은 걸 보고 참던 웃음이 터졌다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_013","speaker":"각청","text":"뭐가 웃겨.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_014","speaker":"나","text":"아뇨. 아무것도.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_015","speaker":"각청","text":"……내 신발이지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_016","speaker":"나","text":"네.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rain_017","speaker":"","text":"각청은 더 묻지 않고 마른 자리를 발끝으로 확인한 뒤 의자를 그쪽으로 옮겼다. 그날 저녁부터, 나를 실험대 위의 물건처럼 상상하는 횟수가 조금 줄었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_001","speaker":"","text":"셋째 날과 넷째 날에도 병사들의 기억 이상은 풀리지 않았다. 나와 멀리 떨어진 자리에서도 보고가 들어왔고, 내 곁에서 이야기한 사람이 그 대화를 기억하고 돌아오기도 했다. 내가 무관하다고 확정할 수는 없었다. 다만 내가 입을 열면 누군가 반드시 잊는다는 두려움에는 맞지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_002","speaker":"각청","text":"네가 설산에서 봤다는 구슬, 지금 안 갖고 있는 거지? 의심해서 묻는 거 아니야. 가진 사람하고 본 사람은 따로 적어야 해서.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_003","speaker":"나","text":"없어요. 제 짐 다 뒤져도 안 나와요. 나오는 건 빨랫감뿐이에요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_004","speaker":"각청","text":"그럼 본 사람으로만 적을게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_005","speaker":"나","text":"의례 때는 저도 올라갈 수 있는 거죠? 여기까지 와서 지붕만 보다 돌아가면 너무 억울한데.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_006","speaker":"각청","text":"행사 통로는 열어. 옥경대 올라갔다가 같은 길로 내려오는 거야. 네가 대기 자리에 있다고 참관을 막진 않아. 대신 거기서 아무나 붙잡고 얘기할 수 있다는 뜻은 아니야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_007","speaker":"나","text":"아무나 안 붙잡을게요. 한 명만 붙잡을 거예요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_008","speaker":"각청","text":"그 한 명이 누군지 벌써 불안하네.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_days_009","speaker":"","text":"내가 기억하는 이야기에서는 신이 하늘에서 떨어지고, 그 뒤는 살아 있는 신의 계획으로 이어졌다. 공고의 송신의례라는 이름은 여전히 기억과 맞지 않았다. 드발린의 죽음 뒤로 나는 순서를 확신할 수 없었다. 그래도 미리 안다고 믿는 부분이 하나 있다는 사실에 자꾸 기대고 싶었다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_029","text":"닷새가 지난 아침, 천막 사이로 사람들의 발걸음이 일찍부터 이어졌다. 내 자리의 천을 정리하고 나섰다. 돌아오면 다시 그 자리에 앉을 것이라는 생각이 아주 자연스러웠다."},{"k":"keep","id":"ISK_L02_K1_030","text":"옥경대로 향하는 길 앞에서 안내 병사가 사람들을 나누어 보냈다. 길목 옆의 거리는 여전히 막혀 있었다. 내게 허용된 것은 도시 입장이 아니라 의례 참관이었다."},{"k":"line","id":"PRO_L02K1_rite_001","speaker":"안내 병사","text":"올라갈 때는 오른쪽, 내려올 때는 맞은편 줄입니다. 길을 벗어나시면 다시 바깥으로 안내합니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_rite_002","speaker":"나","text":"네. 이 길로만 올라갔다가 이 길로만 내려올게요. 저 길 잘 외워요.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_033","text":"줄을 따라 올라가는 동안 항구의 소리는 가까워졌다가 벽 뒤로 멀어졌다. 나들이처럼 옷깃을 정리하는 사람도 있었고, 기억을 잃은 병사들의 이야기를 낮은 목소리로 주고받는 사람도 있었다."},{"k":"line","id":"PRO_L02K1_rite_003","speaker":"","text":"옥경대에 도착하자 가장 먼저 내려가는 길의 위치를 확인했다. 도망칠 생각이라기보다, 모르는 군중 속에 들어왔을 때 몸이 먼저 하는 일이었다. 각청은 통로가 꺾이는 곳에서 병사에게 지시하고 있었다. 눈이 마주치자 짧게 고개를 끄덕였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_004","speaker":"각청","text":"올라오는 데 문제없었어?","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L02K1_rite_005","options":[{"label":"오늘은 제 몸 말고 의례 쪽 봐요. 저도 가끔은 구경 온 사람처럼 서 있고 싶어요.","id":"PRO_L02K1_rite_006","items":[{"k":"line","id":"PRO_L02K1_rite_007","speaker":"각청","text":"좋아. 줄이 움직이면 가운데로 밀리지 말고 이쪽 가장자리로 와.","map":"MAP_LIYUE_HARBOR"}]},{"label":"괜찮아요. 이상해지면 묻기 전에 제가 먼저 말할게요.","id":"PRO_L02K1_rite_008","items":[{"k":"line","id":"PRO_L02K1_rite_009","speaker":"각청","text":"그래 주면 나도 다른 쪽을 볼 수 있지. 줄이 움직이면 이쪽 가장자리로 와.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L02_K1_038","text":"의례가 시작되었다. 시선들이 한꺼번에 높은 곳으로 향했다. 나도 고개를 들었다가, 하늘을 가르며 내려오는 거대한 몸을 보았다. 예상하고 있었다는 말은 충돌음 앞에서 아무 쓸모가 없었다. 모락스의 시신이 의례 한복판에 떨어져 있었다."},{"k":"line","id":"PRO_L02K1_rite_010","speaker":"","text":"질문들이 한꺼번에 터졌다. 원작을 떠올리려 했지만 눈앞의 먼지와 떨리는 목소리들이 그 위를 덮었다. 화면 속 장면에는 나를 밀치는 사람의 팔꿈치가 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_011","speaker":"응광","text":"뒤쪽 통로를 비워. 쓰러진 사람부터 확인하고, 단상으로 접근하는 사람은 막아. 추측을 사실처럼 옮기지 마.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_012","speaker":"","text":"각청은 밀려오는 줄을 멈추고 넘어진 사람이 일어설 공간을 만들었다. 나에게도 자리를 지키라고 손짓했다. 그러나 나는 알고 있었다. 이 뒤에 무엇이 오는지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_013","speaker":"나","text":"각청, 응광하고 따로 얘기하게 해 줘요. 잠깐이면 돼요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_014","speaker":"각청","text":"지금은 안 돼. 널 의심해서가 아니야. 현장 책임자를 지금 빼낼 수가 없어. 급하면 나한테 말해.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L02K1_rite_015","options":[{"label":"모락스의 죽음이 사람들이 생각하는 그대로가 아닐 수도 있어요.","id":"PRO_L02K1_rite_016","items":[{"k":"line","id":"PRO_L02K1_rite_017","speaker":"각청","text":"그래서 아직 아무것도 발표 안 했어. 아는 게 있으면 뭘 보고 알았는지부터 말해. 여기서 더 크게 말하진 말고.","map":"MAP_LIYUE_HARBOR"}]},{"label":"기억을 잃는 일하고 이번 일이 겹쳤잖아요. 제가 몬드에서 본 것도 죽었다가 다시 움직이는 일이었어요.","id":"PRO_L02K1_rite_018","items":[{"k":"line","id":"PRO_L02K1_rite_019","speaker":"각청","text":"기억해. 하지만 드발린 일을 여기 그대로 붙일 순 없어. 먼저 사람들 안 다치게 길부터 비켜 줘.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L02K1_rite_020","speaker":"","text":"다시 응광을 찾았다. 그녀는 이미 다른 쪽으로 이동하고 있었다. 옷자락이 잠깐 보였고, 곧 사라졌다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_021","speaker":"나","text":"가 버렸잖아요. 나중에 전해 준다는 게 얼마나 나중인지도 모르는데……","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_rite_022","speaker":"각청","text":"나도 네가 답답한 건 알아. 그래도 이 선은 못 넘게 해. 내가 여기서 듣고 있잖아. 지금 위험한 게 뭔지부터—","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_001","speaker":"","text":"각청의 말이 중간에서 끊겼다. 숨을 고르려는 멈춤과는 달랐다. 손이 공중에 남은 채 힘을 잃었고, 몸이 무너졌다. 내가 손을 뻗는 동안 옆의 병사도 쓰러졌다. 비명을 지르던 사람의 입이 열린 그대로 조용해졌다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_002","speaker":"","text":"각청의 어깨를 받치려다 함께 주저앉았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_003","speaker":"나","text":"각청.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_004","speaker":"나","text":"장난 아니잖아. 눈 떠.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_005","speaker":"나","text":"하던 말 끝내. 듣고 있으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K1_056","text":"손목을 더듬었다. 닷새 내내 내 손목에서 찾았던 박동이 이번에는 없었다. 잡는 위치를 틀렸다고 생각해 손가락을 옮겼다. 얼굴을 가까이 대어도 숨이 닿지 않았다. 옆 병사도 같았다. 이곳에서 살아 움직이는 것은 나뿐이었다."},{"k":"line","id":"PRO_L02K1_death_006","speaker":"","text":"내 가슴만 뛰었다. 그게 견딜 수 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_007","speaker":"나","text":"누구든…… 아무나 대답해요. 여기 사람들 쓰러졌어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K1_death_008","speaker":"나","text":"제발.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K1_059","text":"대답 대신 바닥에 떨어진 물건이 굴러와 발끝에 닿았다. 그것을 밟지 않으려 발을 옮기다가 뒤로 물러섰다. 각청을 놓고 일어나 버렸다는 것을 알아차렸지만 다시 앉지 못했다. 더 가까이 가면 안 될 것 같았다. 근거는 없었다. 도망칠 방향을 정하기에는 충분했다."},{"k":"line","id":"PRO_L02K1_death_009","speaker":"","text":"계단을 내려갔다. 사람을 밟을까 봐 발을 고르다 벽에 부딪쳤고, 그래도 멈추지 않았다. 등 뒤에서 누가 붙잡아 주기를 바라면서도 뒤를 볼 수 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K1_061","text":"올라올 때 확인해 둔 길이 몸을 이끌었다. 행사 통로를 벗어나 외곽의 흙길을 밟았을 때에도 한참 더 달렸다. 사람이 있을 만한 길목이 보이면 옆으로 피했다."},{"k":"line","id":"PRO_L02K1_death_010","speaker":"","text":"발이 더 나가지 않는 곳에서 길가의 바위에 기대었다. 손바닥에 묻은 흙이 보였다. 각청의 어깨를 받칠 때 묻었는지, 계단에서 넘어졌을 때 묻었는지 알 수 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_death_011","speaker":"","text":"몬드로 돌아가 진에게 알리는 길이 떠올랐다. 그러나 가는 동안 또 사람이 죽으면. 이번에는 내 옆에 있던 사람들만 죽었다면. 그 생각을 지울 근거가 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_death_012","speaker":"나","text":"……선인한테 가자. 류운차풍진군. 적어도 내가 본 걸 끝까지는 들어 주겠지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_death_013","speaker":"나","text":"겁나서 산으로 숨는 거여도, 가서 말할 사람은 있어야지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_death_014","speaker":"","text":"말로 목적지를 정하자 흩어지던 생각이 한 방향으로 모였다. 소는 지금 어디 있는지 몰랐다. 류운차풍진군에게는 찾아갈 거처가 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_066","text":"평야에서 산으로 빠지는 갈림길을 한 번 지나쳤다. 되돌아왔을 때 해의 위치가 바뀌어 있었다. 머릿속 지도에는 내 가쁜 숨이 표시되어 있지 않았다."},{"k":"line","id":"PRO_L02K1_mountain_001","speaker":"","text":"바위 사이 좁은 길에서 돌이 굴렀다. 내가 찬 게 아니었다. 바위 색 비늘, 작은 뿔. 새끼 용 도마뱀 셋이 길 한가운데서 나를 보고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_002","speaker":"나","text":"……비켜 줄 생각은 없지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_003","speaker":"","text":"없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"combat","id":"PRO_L02K1_mountain_004","group":"EG_LIYUE_VISHAP","text":"산길을 막은 새끼 용 도마뱀 무리. 지나가지 않으면 오장산에 닿을 수 없다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_005","speaker":"","text":"마지막 한 마리가 바위 틈으로 들어갔다. 손이 떨렸다. 싸움 때문인지, 싸우는 동안만큼은 아무 생각도 안 해도 돼서 그런 건지 몰랐다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_006","speaker":"","text":"한쪽으로 몸을 기울여 통과해야 하는 구간에서 벽을 등지고 오래 서 있었다. 추락하면 누군가 살아 돌아오는 기적이 내게도 일어날지. 그 생각이 스친 것만으로 속이 울렁거렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_007","speaker":"나","text":"……죽었다 살아나는 걸 두 번 기대하는 건 염치없지. 살아서 올라가자.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_008","speaker":"","text":"눈을 감으면 각청이 말을 끝내지 못하던 입 모양이 떠올라서, 눈을 뜬 채 발끝만 보았다. 새가 날고 바람이 나뭇잎을 흔들었다. 그 소리를 확인할 때마다 다시 걸을 수 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_009","speaker":"","text":"거처에 이르렀을 때 문은 닫혀 있었다. 산을 올라오기만 하면 다음 장면이 시작될 줄 알았다. 문은 사람의 도착을 알아서 헤아려 주지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K1_mountain_010","options":[{"label":"류운차풍진군을 뵈러 왔습니다. 아래에서 큰일이 났어요. 예는 잘 못 갖췄는데, 일부러 그런 건 아닙니다.","id":"PRO_L02K1_mountain_011","items":[{"k":"line","id":"PRO_L02K1_mountain_012","speaker":"","text":"대답은 없었다. 공양 절차를 떠올렸다가 빈손을 내려다보았다. 문을 두드리면 무례일까 고민하다가, 무례가 두려워 돌아갈 상황이 아니라는 생각에 손을 들었다. 손끝이 닿기 전에 안쪽에서 목소리가 들렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_013","speaker":"류운차풍진군","text":"문을 부술 생각으로 손을 드는 것이라면 내려놓게. 자네가 이곳까지 허둥지둥 올라온 사정은 무엇인가?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_014","speaker":"나","text":"들으셨으면 조금만 빨리 대답해 주시지…… 죄송합니다. 투정 부릴 때가 아닌 건 알아요.","map":"MAP_LIYUE_PLAINS"}]},{"label":"(문 옆에 서서 기다린다.)","id":"PRO_L02K1_mountain_015","items":[{"k":"line","id":"PRO_L02K1_mountain_016","speaker":"","text":"문 옆으로 비켜서서 숨을 골랐다. 안에 아무도 없다면 소용없고, 안에 있는데 예를 모르니 돌려보낸 것일 수도 있었다. 한참 뒤 안쪽에서 목소리가 들렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_017","speaker":"류운차풍진군","text":"문을 두드리지도, 돌아가지도 않는군. 그 정도 참을성이면 들을 만하겠지. 자네가 이곳까지 허둥지둥 올라온 사정은 무엇인가?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_018","speaker":"나","text":"기다리는 건 닷새 동안 연습했거든요. ……죄송합니다. 농담할 때가 아닌데.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K1_mountain_019","speaker":"나","text":"아래에서 모락스의 시신이 떨어졌습니다. 그리고 사람들이 죽었어요. 제가 있던 곳에서, 저만 빼고 전부요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_020","speaker":"","text":"안쪽의 기척이 멈췄다. 더 말하려다 숨이 목에 걸렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_021","speaker":"류운차풍진군","text":"제군의 일과 사람들의 죽음을 한숨에 묶어 말하지 말게. 언제, 어디서, 무엇을 보았는지 차례로 답할 수 있겠나. 이 몸이 듣고 있으니 호흡부터 고르게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_022","speaker":"나","text":"차례대로 말할 수 있어요. 대신 문에 대고 말하는 건 여기까지 했으면 해요. 문에 대고 말하니까…… 진짜 혼자 남은 것 같아서요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_023","speaker":"","text":"문이 열렸다. 안쪽에 모습을 드러낸 학이 나를 바라보았다. 그림으로 기억하던 자태와 달리, 눈앞의 존재는 가만히 서 있는 것만으로 내가 걸어온 거리를 작게 만들었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_024","speaker":"류운차풍진군","text":"들어오게. 자네가 무엇인지 이 몸이 벌써 판단한 것은 아니니, 그 표정으로 스스로 판결을 내리지는 말거라. 저 돌턱은 낮아 보이지만 발이 걸리기 쉽다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_025","speaker":"나","text":"……네. 안 걸릴게요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_mountain_026","speaker":"","text":"걸렸다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_audience_001","speaker":"","text":"지정받은 자리에 앉았다. 무릎이 굽혀지자 올라오는 동안 참았던 통증이 한꺼번에 느껴졌다. 류운차풍진군은 내가 허리를 펴기도 전에 질문을 이어가지 않았다. 그 짧은 기다림 때문에 오히려 먼저 입을 열 수 있었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_002","speaker":"나","text":"리월항은 며칠 전부터 막혀 있었어요. 천암군 일부가 조금 전 일을 기억하지 못해서요. 저는 항구 밖에서 닷새를 기다렸고, 오늘 의례 길이 열려서 옥경대로 올라갔습니다. 시작하자마자 모락스의 몸이 떨어졌어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_003","speaker":"류운차풍진군","text":"떨어진 것을 직접 보았고, 그 몸을 제군의 시신이라 여겼다는 말이군. 자네가 그 자리에서 죽음을 확인한 사람은 또 누구인가?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_004","speaker":"나","text":"각청이요. 바로 앞에서 말하다가 쓰러져서 제가 받쳤어요. 숨이 없었고 맥박도 없었어요. 다른 사람도 같았고요. 계속 불렀는데…… 아무도요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_005","speaker":"","text":"말을 끝내자 처음으로 각청의 이름을 부르는 일이 견딜 만해졌다. 류운차풍진군은 곧바로 위로하지 않았다. 대신 내가 직접 본 범위와 보지 못한 범위를 하나씩 짚었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_006","speaker":"류운차풍진군","text":"응광은 그 전에 자리를 떠났고, 자네는 그 뒤의 행방을 보지 못했다. 그렇다면 그 사람의 생사까지 같은 말로 묶지는 않겠네. 어디까지 알며 어디서부터 모르는지가 분명해야, 이 몸도 움직일 방향을 정할 수 있지.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_007","speaker":"","text":"맞는 말이었다. 못 본 사람까지 죽었다고 할 수는 없었다. 그리고 여기까지 온 이유가 하나 더 있었다. 숨을 고르고 고개를 들었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"choice","group":"G_PRO_L02K1_audience_008","options":[{"label":"믿기 힘드실 텐데, 이건 모락스의 계략이에요. 리월이 스스로 버틸 수 있는지 보려는 계획. 오셀이 나올 수 있으니 막을 준비를 하셔야 해요.","keep":"ISK_L02_K1_086","items":[]}]},{"k":"line","id":"PRO_L02K1_audience_009","speaker":"","text":"류운차풍진군의 시선이 달라졌다. 놀라서 물러나는 반응이 아니었다. 내가 해서는 안 될 이름을 우연히 입에 담았는지, 아니면 그 무게를 알고 있는지 가늠하는 침묵이었다. 그 침묵을 견디면서 손가락을 무릎 위에 펼쳤다. 다시 맥박을 찾기 시작하면 말을 잇지 못할 것 같았다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_010","speaker":"류운차풍진군","text":"자네가 말하는 계략에 방금 죽었다는 사람들까지 포함되어 있나? 그리고 오셀이라는 이름은 어디에서 들었지?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_011","speaker":"나","text":"아니요. 사람들이 죽는 건 제가 알던 일에 없었어요. ……제가 살던 곳에서, 이곳의 일을 이야기로 알고 있었어요. 당신이 계신 곳도 그래서 떠올렸고요. 그런데 여기서는 드발린이 진짜로 죽었다가 살아났고, 오늘은 제 눈앞에서 사람들이 죽었습니다. 제가 알던 이야기만 믿고 괜찮을 거라 말할 수는 없어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_012","speaker":"류운차풍진군","text":"그렇다면 먼저 그 두 가지를 나누게. 자네가 가지고 온 옛 지식과, 오늘 자기 눈으로 본 일. 앞의 것이 맞는지 확인하는 동안 뒤의 것을 버릴 필요는 없지. 허나 앞의 것으로 뒤의 일을 설명했다고 여겨서도 안 되네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"choice","group":"G_PRO_L02K1_audience_013","options":[{"label":"제 말을 다 믿지 않으셔도 돼요. 바다 쪽만 봐 주세요. 제가 틀리면 민망한 걸로 끝나지만, 맞는데 준비가 없으면 사람이 더 죽잖아요.","id":"PRO_L02K1_audience_014","items":[{"k":"line","id":"PRO_L02K1_audience_015","speaker":"류운차풍진군","text":"민망함의 크기를 재러 온 자리가 아니니 그 허세는 내려놓게. 다만 위험의 이름을 구체적으로 말했고 현장의 사정을 함께 가져온 점은 가볍게 듣지 않았네.","map":"MAP_LIYUE_MOUNTAINS"}]},{"label":"다 맞힐 자신은 없어요. 그래도 모르는 척하고 내려가면 각청 앞에서 하던 일을 또 하는 것 같아서요. 중요한 얘기가 있다고만 하고 끝까지 말하지 못했거든요.","id":"PRO_L02K1_audience_016","items":[{"k":"line","id":"PRO_L02K1_audience_017","speaker":"류운차풍진군","text":"이미 끝난 대화를 이 자리에서 다시 이기려 하지 말게. 지금 할 일은 그 사람에게 하지 못한 말로 자신을 벌주는 것이 아니라, 아직 전할 수 있는 말을 빠뜨리지 않는 것이야. 계속해 보게.","map":"MAP_LIYUE_MOUNTAINS"}]}]},{"k":"line","id":"PRO_L02K1_audience_018","speaker":"","text":"더 전할 것이 있는지 생각하자 망서 객잔의 소가 떠올랐다. 그 말을 꺼내면 내가 원인일지 모른다는 두려움까지 드러날 것이다. 그래도 감춘 채 판단을 구하고 싶지는 않았다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_019","speaker":"나","text":"망서 객잔에서 소를 만났어요. 제 주변에 죽음과 생명의 냄새가 같이 나고, 마신을 미워하는 기척도 느껴진다고요. 그분도 원인은 모른다고 했어요. 그래서 사람 없는 길로 왔습니다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_020","speaker":"나","text":"혹시 제가 원인이면…… 당신도 만나면 안 되는 거였나 싶은데. 그럼 저는 어디 가서 누구한테 말해야 하죠?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_021","speaker":"류운차풍진군","text":"자네 혼자 살아남았다는 것과 자네가 죽였다는 것은 같은 말이 아니네. 이 몸 앞에서 벌을 달라고 해도 그 빈칸을 대신 채워 줄 생각은 없어. 소의 말도 들었네. 허나 그 말만으로 자네 곁에 선 존재는 모두 죽는다고 결론 내릴 수는 없지.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_022","speaker":"","text":"아무 일도 없을 것이라는 약속이 아니었다. 그것을 알아들었다. 어깨가 내려가자 의례장을 나온 뒤 처음으로 숨이 끝까지 들어왔다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_023","speaker":"나","text":"여기서 잠깐 쉬어도 될까요? 일어서려고 하니까 다리가 말을 안 듣네요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_024","speaker":"류운차풍진군","text":"앉아 있으라 했으면 쉬어도 된다는 뜻이지. 발목을 그렇게 비틀고 있으면 일어날 때 더 아플 테니 곧게 놓게. 인간의 몸은 쓰러지기 직전까지 버틴다고 더 오래 가는 물건이 아니야.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_025","speaker":"나","text":"……지금 잔소리 들은 거 맞죠?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_026","speaker":"류운차풍진군","text":"충고네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_027","speaker":"나","text":"네. 충고요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_028","speaker":"","text":"자세를 고쳐 앉자 그녀는 한 차례 더 발목을 살피고서야 눈을 돌렸다. 누군가 내 다음 걸음을 실제로 걱정한다는 사실만 남았다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_029","speaker":"류운차풍진군","text":"이 몸도 항구 쪽 사정을 확인하겠네. 자네의 이야기를 그대로 받아 적고 끝낼 일은 아니니. 다만 자네가 산을 내려가는 동안 모든 길이 안전해진다고 생각하지는 말게.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_030","speaker":"나","text":"알겠습니다. 내려가면 제가 도망친 길부터 다시 볼게요. 사람을 만나면 피하지 않고요. 다만 지금 바로 뛰어 내려가라고는 하지 말아 주세요. 의욕이 아니라 다리 문제예요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_audience_031","speaker":"류운차풍진군","text":"이제야 두 가지를 제대로 나누는군. 쉬었다 가게. 자네가 가져온 이야기는 이 몸이 들었으니, 문밖에서 다시 외칠 필요도 없네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K1_return_001","speaker":"","text":"몸을 추스르고 밖으로 나왔을 때 산의 빛은 이미 낮과 달랐다. 어둠이 깊어지는 구간에서는 바람을 피할 만한 곳에서 기다렸다. 눈을 감는 일은 여전히 어려웠다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"keep","id":"ISK_L02_K1_108","text":"밤이 지나 길의 모양이 다시 보이자 산 아래로 향했다. 오를 때 지나친 갈림길에서 한동안 멈췄다. 도망칠 때의 나는 리월에서 멀어지기만 하면 된다고 생각했다. 돌아가는 지금의 나에게는 확인할 곳이 있었다. 각청을 놓고 일어난 자리였다."},{"k":"line","id":"PRO_L02K1_return_002","speaker":"","text":"리월항 외곽의 길에는 사람의 소리가 있었다. 화물 때문에 다투는 목소리, 길을 비켜 달라는 말, 바퀴가 돌을 넘는 소리. 그것들이 옥경대에 두고 온 사람들을 설명해 주지는 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_110","text":"봉쇄선은 남아 있었다. 병사들은 오가는 사람을 확인했고, 옆길로 들어서려는 행렬을 바깥으로 돌렸다. 사람들 사이에서 각청의 목소리를 들었다. 처음에는 비슷한 음성이라고 생각했다. 얼굴을 본 뒤에는 그 생각조차 할 수 없었다."},{"k":"line","id":"PRO_L02K1_return_003","speaker":"","text":"각청은 서 있었다. 어깨를 펴고 상대의 설명을 들으며, 필요한 대목에서 질문하고 있었다. 내 손 안에서 무게만 남았던 몸이 스스로 움직였다. 그녀가 고개를 돌렸을 때 나도 모르게 앞으로 나섰다가 멈췄다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_return_004","speaker":"나","text":"각청.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_return_005","speaker":"나","text":"너…… 어떻게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K1_return_006","speaker":"나","text":"내가 봤는데. 손도 잡고, 숨도 확인했는데.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_113","text":"각청은 내 얼굴을 바라보았다. 닷새 동안 상태를 묻고, 비 새는 천막을 함께 들어 올리고, 의례장 가장자리를 알려 주었던 사람이었다. 그러나 그 얼굴에, 알아본 사람에게만 잠깐 생기는 반응이 없었다. 시선은 낯선 이의 다친 손과 흐트러진 차림을 살핀 뒤 다시 눈으로 돌아왔다."},{"k":"line","id":"PRO_L02K1_return_007","speaker":"각청","text":"잠깐. 내 이름을 부르는 건 알겠는데, 우리 어디서 만났지? 너, 나를 알아?","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K1_END","text":"리월항 외곽 봉쇄선. 이야기는 살아 있는 각청의 질문 앞에서 멈춘다."}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L02_K1_001_0","text":"송신의례라는 공고를 보여 주자 그녀는 답 대신 반송된 보고통을 꺼냈다. 고운각의 경계대가 보낸 통이었다. 안에는 종이가 없었다."},{"k":"text","id":"V141_BEFORE_ISK_L02_K1_001_1","text":"처음 뵙겠습니다. 월해정 비서 감우입니다. 각청 님께 말씀은 들었어요. 그 공고를 들고 저를 찾아오신 분은 당신이 처음이네요."},{"k":"text","id":"V141_BEFORE_ISK_L02_K1_001_4","text":"저도 갈게요. 앉아서 아는 척만 하는 건 이제 질렸어요. 지금 일어나는 일을 보러 가고 싶어요."},{"k":"text","id":"V141_BEFORE_ISK_L02_K1_001_6","text":"그 말은 보고통 찾아온 다음에 해. 네가 밤새 혼자 찾는 동안 우리 둘이 멀쩡히 쉴 수 있을 것 같아? 이 사람은 대기 자리에서 벗어난다고 병사한테 말해 두면 돼."},{"k":"text","id":"V141_AFTER_ISK_L02_K1_001_3","text":"해안 경계를 바꾸고, 배를 확인하고. 좋아요. 이제 저도 할 수 있는 말이 생겼네요. 불길하다는 말 말고요."}]},{"id":"ISK_L02_K2","entry":"ISK_L02_K2_001","items":[{"k":"keep","id":"ISK_L02_K2_001","text":"다음 날에도 짐은 봉쇄선 밖에 남아 있었다. 한 번 이야기하면 집에 갈 수 있을 줄 알았던 짐꾼은 내 옆에 쪼그려 앉아 손바닥의 굳은살을 문질렀다. 같은 아침을 또 시작한 것 같았다. 그때 아는 얼굴이 수레 사이로 나타났다."},{"k":"line","id":"PRO_L02K2_wait_001","speaker":"짐꾼","text":"당신은 갈 데 있으면 가도 되오. 본 것까지 말해 줬는데 여기 붙들어 놓으면 내가 미안해지지.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"REV02_K2_BRAKE_CALLBACK_1","text":"짐꾼은 쪼그려 앉기 전에 받침 수레의 짧은 손잡이를 한 번 더 눌렀다. 어제 내가 잠갔던 것과 같은 장치였다. 이제 확인표에 체크가 있어도 손으로 확인하지 않고는 떠나지 못하는 모양이었다."},{"k":"keep","id":"REV02_K2_BRAKE_CALLBACK_2","text":"어제 내가 끌어온 받침은 병사가 다시 정리해 두었다. 짐꾼이 나를 붙잡아 두기 미안해하는 것과, 어제 일을 고마워하는 것은 다른 일이었다."},{"k":"keep","id":"REV02_K2_BRAKE_CALLBACK_3","text":"나는 긴 짐끈에 손대지 않고 받침 수레의 잠금부터 살폈다. 어제 한 번 식은땀을 흘렸다고 전문가가 되지는 않았다."},{"k":"line","id":"PRO_L02K2_wait_002","speaker":"나","text":"갈 데가 있으면 이 포대 옆에서 먼지를 털고 있겠어요? 나중에 손해 났다고 반씩 내자는 말만 안 하시면 조금 더 있어 드릴게요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_wait_003","speaker":"짐꾼","text":"반씩 낼 사람이 있었으면 당신부터 안 골랐을 거요. 얼굴에 돈 아깝다는 소리가 아주 잘 쓰여 있으니까.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_wait_004","speaker":"나","text":"그거 지워지는 건가요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_wait_005","speaker":"짐꾼","text":"밥 먹으면 좀 옅어지더군.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_wait_006","speaker":"","text":"웃음이 사라진 뒤 그는 다시 짐을 보았다. 넘겼다고 할 수도, 넘기지 않았다고 할 수도 없는 일 사이에서, 포대의 무게를 계속 자기 어깨에 얹고 있는 사람처럼 앉아 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_001","speaker":"","text":"해가 기울 무렵 각청이 돌아왔다. 짐꾼이 일어서자 그녀가 앉아 계시라는 손짓을 했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_002","speaker":"각청","text":"짐부터 볼게요. 제가 확인한 뒤에 옮기지는 않으셨죠?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_003","speaker":"짐꾼","text":"그대로 뒀소. 풀지도 않았고. 다음 사람이 오면 또 풀자고 하겠지만……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_004","speaker":"각청","text":"그 '다음 사람'은 제가 막을게요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_005","speaker":"","text":"각청은 포대의 묶인 부분을 살핀 뒤 병사를 불렀다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_006","speaker":"각청","text":"이 짐은 따로 맡아 줘. 다음 담당자가 와도 풀기 전에 이 표부터 보여 주고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_007","speaker":"짐꾼","text":"그럼 오늘은 어디까지 된 거요? 같은 설명만 하다가 해가 졌소.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_008","speaker":"각청","text":"오늘 안에 끝난다고는 못 해요. 대신 처음부터 다시 설명하는 일은 없게 할게요. 그것까지 못 막으면 제가 여기 서 있을 이유가 없죠.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K2_evening_009","options":[{"label":"저 때문에 더 늦어진 건 아니죠?","id":"PRO_L02K2_evening_010","items":[{"k":"line","id":"PRO_L02K2_evening_011","speaker":"각청","text":"아니. 덕분에 짐 더 섞기 전에 멈췄잖아. 뒷일은 내가 해.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_012","speaker":"나","text":"다행이네요. 일만 벌여 놓고 가는 것 같아서.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_013","speaker":"각청","text":"벌인 건 맞아. 그래도 좋은 쪽으로.","map":"MAP_LIYUE_PLAINS"}]},{"label":"다음에도 처음부터 설명해야 해요?","id":"PRO_L02K2_evening_014","items":[{"k":"line","id":"PRO_L02K2_evening_015","speaker":"각청","text":"아니. 더 물을 게 생기면 어느 부분인지 내가 짚어서 물어볼게.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_016","speaker":"","text":"각청은 병사가 든 표의 아래쪽을 짚어 이미 확인한 내용을 구분해 주었다.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K2_evening_017","speaker":"각청","text":"잠깐 자리 비우실 땐 이 병사한테 말씀해 주세요. 짐은 두고 다녀오셔도 됩니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_018","speaker":"짐꾼","text":"그 말이면 됐소. 어디까지 가도 되는지 몰라서 꼼짝을 못 했지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_019","speaker":"","text":"짐꾼이 굳은 허리를 폈다. 각청은 그가 지나가도록 옆으로 비켜섰다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_020","speaker":"나","text":"각청 씨도 쉬러 가요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_021","speaker":"각청","text":"다음 교대한테 전할 거 전하고. 그래야 아저씨가 내일 아침에 또 같은 질문 안 듣지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_022","speaker":"나","text":"그럼…… 고맙습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_023","speaker":"각청","text":"……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_024","speaker":"각청","text":"인사는 들었으니까 이제 진짜 가서 쉬어. 서서 조는 사람 처음 봐.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_025","speaker":"나","text":"안 졸았어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_evening_026","speaker":"각청","text":"눈 감고 있었어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_001","speaker":"","text":"이튿날에는 짐꾼이 자리를 비웠다가 해가 기울기 전에 돌아왔다. 그가 돌아와 가장 먼저 확인한 것은 짐의 수가 아니라 내가 아직 거기 있다는 사실이었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_002","speaker":"짐꾼","text":"설마 내가 도망쳤다고 생각한 건 아니겠지? 볼일이 길어졌소.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K2_days_003","options":[{"label":"도망칠 거면 짐 두고 간다고 친절하게 말하진 않았겠죠. 모르는 사람들 틈보다 이미 제 형편을 낮게 평가한 사람 옆이 편해서요.","id":"PRO_L02K2_days_004","items":[{"k":"line","id":"PRO_L02K2_days_005","speaker":"짐꾼","text":"높게 평가해 달라는 말로 들리는군. 그런데 걸어오는 꼴부터 불안하오. 오늘은 짐 들어 주겠단 말 하지 마시오. 당신까지 들고 가야 하면 곤란하니.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_006","speaker":"","text":"입을 열었다가 닫았다. 정확히 그 말을 하려던 참이었다.","map":"MAP_LIYUE_PLAINS"}]},{"label":"무거운 건 안 맡을게요. 대신 옆에서 눈으로 볼 일이 있으면 하죠.","id":"PRO_L02K2_days_007","items":[{"k":"line","id":"PRO_L02K2_days_008","speaker":"짐꾼","text":"자기 상태를 알고 말하면 다행이오. 도와주겠다는 사람까지 눕히는 일은 피하고 싶으니.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_009","speaker":"나","text":"어제 승강기에서 딸려 올라간 사람한테 그 말은 좀 아프네요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_010","speaker":"짐꾼","text":"그러니까 하는 말이오.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K2_days_011","speaker":"","text":"짐꾼이 앉을 자리를 비워 주었다. 대화는 인계가 어디서 막혔는지에서 오늘 바람이 어느 쪽으로 부는지로, 다시 어디까지 걸어가면 줄이 덜 붐비는지로 옮겨 갔다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_012","speaker":"","text":"셋째 날, 같은 병사가 익숙한 글씨를 앞에 놓고 한동안 말을 하지 못했다. 자기가 적은 건 알겠는데 그때 한 일이 떠오르지 않는다고 했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_013","speaker":"나","text":"생각 안 나면 거기까지만 말해도 돼요. 저도 끈 풀린 것밖에 못 봤어요. 반쪽짜리 둘 붙인다고 하나가 되진 않잖아요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_014","speaker":"검수 병사","text":"고맙습니다. 그런데 제가 모른다고 하면 다른 사람이 또 멈추니까요. 제가 제일 큰 걸림돌이 된 기분입니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_015","speaker":"짐꾼","text":"당신이 오늘 새로 멈춘 건 아니오. 멈춰야 할 데를 이제 안 거지. 모르는 걸 안다고 하고 넘겼다가 나중에 사라지면, 그땐 셋 다 거짓말쟁이가 되지 않겠소.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_016","speaker":"","text":"짐꾼을 보았다. 첫날에는 병사의 대답을 재촉하던 사람이었다. 여전히 기다리는 시간을 아까워하고 끈을 볼 때마다 한숨을 쉬었다. 다만 그 시간을 누구한테 화내서 되찾을 수 있는지에 대해서는 생각이 달라진 듯했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_017","speaker":"","text":"넷째 날에는 의례 날의 동선 안내가 다시 돌았다. 물자가 들어가는 길과 참관객이 올라가는 길은 다르다는 설명에, 짐꾼은 한동안 먼 곳을 바라보았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_018","speaker":"짐꾼","text":"짐은 병사한테 위치 확인받고 그대로 둘 거요. 나도 잠깐 올라갔다 오려고. 신 앞에서 이러고 기다리는 사람 있다는 얘기라도 해 볼까 해서. 당신도 갈 거면 같이 가겠소?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_019","speaker":"나","text":"가죠. 신한테 사정해서 될 일이면 저도 한마디 보탤게요. 줄 서서 옆 사람한테 투덜거리는 건 제 전문이고요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_020","speaker":"짐꾼","text":"말만 들으면 아주 큰 선행을 하는 것 같군. 올라가다 힘들다고 먼저 주저앉지만 마시오. 별것도 없는 짐 들고 와 놓고 걸핏하면 어깨를 주무르더구먼.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_021","speaker":"나","text":"그건 체질이에요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_022","speaker":"짐꾼","text":"게으른 체질이지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_days_023","speaker":"","text":"웃었다. 상대가 내일도 나를 같은 사람으로 기억할 거라고 당연히 믿을 수 있는 대화였다. 그 당연함이 얼마나 드문 일인지, 나는 얼마 뒤에야 알게 된다. 소의 말은 여전히 각청에게 전하지 않은 채였다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_033","text":"닷새가 지난 아침, 두 사람은 짐의 위치가 확인되는 것을 지켜본 뒤 행사 길 쪽으로 향했다. 짐꾼은 돌아왔을 때 어느 자리에서 다시 만나면 되는지까지 정해 두었다."},{"k":"keep","id":"ISK_L02_K2_034","text":"행사 통로가 열려 있었다. 짐꾼은 평소라면 짐을 싣고 향했을 길을 한 번 보고 돌아섰다."},{"k":"line","id":"PRO_L02K2_rite_001","speaker":"안내 병사","text":"의례가 끝나면 이 길로 돌아오십시오. 동행과 떨어져도 옆길로 찾으러 가시면 안 됩니다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K2_rite_002","options":[{"label":"이분 잃어버리면 화물 있는 데서 찾으면 되겠네요. 그 자리는 잊고 싶어도 못 잊겠어요.","id":"PRO_L02K2_rite_003","items":[{"k":"line","id":"PRO_L02K2_rite_004","speaker":"짐꾼","text":"잃어버린다니, 내가 당신 짐이오? 걱정되면 당신이 뒤처지지 말고 따라오시오.","map":"MAP_LIYUE_PLAINS"}]},{"label":"서로 놓치면 화물 있는 쪽에서 만나요. 제가 뒤처지면 한 번만 불러 주세요.","id":"PRO_L02K2_rite_005","items":[{"k":"line","id":"PRO_L02K2_rite_006","speaker":"짐꾼","text":"찾을 곳 정하는 건 좋소. 다만 부르는 소리 들릴 만큼은 따라와야겠지.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"keep","id":"ISK_L02_K2_038","text":"두 사람은 앞서거니 뒤서거니 하며 올라갔다. 며칠 함께 기다렸다고 가까운 친구가 되는 것은 아니었다. 그래도 짐꾼이 사람들 사이에서 한쪽 어깨를 낮추고 걷는 버릇을 알게 되었다. 짐이 없을 때도 몸은 무거운 것을 피해 지나갈 틈부터 찾았다."},{"k":"line","id":"PRO_L02K2_rite_007","speaker":"","text":"옥경대에서는 시선이 한곳으로 모였다. 공고의 의례 이름과 내 기억 사이의 어긋남을 생각했다. 이름만 바뀐 건지, 일이 다른 순서로 일어나는 건지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_008","speaker":"짐꾼","text":"고개를 그렇게 내밀면 앞사람과 부딪히오. 이쪽에 서시오. 나는 저 위까지 훤히 안 보여도 괜찮으니.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_009","speaker":"나","text":"오늘은 제가 가려지는 쪽이네요. 고마워요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_010","speaker":"짐꾼","text":"키 얘기는 안 했소.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_011","speaker":"나","text":"했어요, 방금.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K2_042","text":"말이 끝나고 얼마 지나지 않아 의례가 시작되었다. 하늘로 향하던 시선 앞에서 거대한 몸이 떨어졌다. 짐꾼이 본능적으로 내 팔을 잡아당겼다. 충격이 발바닥을 타고 올라왔고, 모여 있던 사람들이 뒤로 밀렸다. 먼지가 가라앉는 자리에는 모락스의 시신이 놓여 있었다."},{"k":"line","id":"PRO_L02K2_rite_012","speaker":"","text":"짐꾼이 잡은 팔을 바로 빼지 못했다. 두 사람 모두 시신에서 눈을 떼지 못했다. 신마저 죽었다는 말이 가까이에서 튀어나왔다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_013","speaker":"응광","text":"그 자리에서 서로 밀지 마. 천암군은 통로를 확보하고, 들리는 말을 그대로 옮기지 마라.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_014","speaker":"","text":"각청이 통로 가장자리로 와서 사람들을 물렸다. 짐꾼은 앞에 넘어진 사람을 일으켰고, 나도 손을 뻗어 설 자리를 만들었다. 틈 사이로 응광이 보였다. 나는 알고 있었다. 이 뒤에 무엇이 오는지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_015","speaker":"나","text":"각청, 저 응광하고 따로 얘기해야겠어요. 잠깐만요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_016","speaker":"각청","text":"지금은 안 돼. 네가 물자 일에 협조한 건 알아. 그래도 그걸로 의례 현장을 마음대로 다닐 순 없어. 급하면 내가 들을게.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L02K2_rite_017","options":[{"label":"자격을 써먹겠다는 게 아니에요. 제군에 관한 일이고, 그 다음에 벌어질 일 얘기예요.","id":"PRO_L02K2_rite_018","items":[{"k":"line","id":"PRO_L02K2_rite_019","speaker":"각청","text":"그럼 더더욱 네가 어떻게 아는지부터 들어야지. 다음 일을 안다는 말만으로 현장 책임자를 데려올 순 없어. 옆에 넘어진 사람부터.","map":"MAP_LIYUE_HARBOR"}]},{"label":"그럼 최소한 제 얘기가 있다는 건 전해 줘요. 출처를 설명하려면 오래 걸려요.","id":"PRO_L02K2_rite_020","items":[{"k":"line","id":"PRO_L02K2_rite_021","speaker":"각청","text":"전할 게 있다는 건 알겠어. 하지만 출처 설명이 어렵다는 말이 출처를 건너뛰어도 된다는 뜻은 아니야. 본 것부터.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L02K2_rite_022","speaker":"","text":"다시 고개를 돌렸을 때 응광은 현장을 떠나고 있었다. 옷자락이 보였다가 사라졌다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_023","speaker":"짐꾼","text":"아는 게 있으면 지금 이분한테 말하시오. 사람 가려 가며 할 때가 아닌 것 같은데. 당신, 본 것과 안 본 것은 잘 나누더니 오늘은 말 앞에서 자꾸 머뭇거리는군.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_rite_024","speaker":"나","text":"……맞아요. 이상하게 들릴까 봐 순서만 찾고 있었어요. 각청, 들어 줘요. 이건 제가 전에—","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_001","speaker":"","text":"짐꾼의 손이 내 팔에서 떨어졌다. 헛디딘 줄 알고 옷깃을 잡았다. 각청도 동시에 무릎이 꺾였다. 옆의 병사가 창을 놓쳤고, 군중의 소리가 중간에서 뚝 끊겼다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_002","speaker":"","text":"짐꾼을 끌어안은 채 주저앉았다. 가벼울 거라던 몸이 갑자기 움직일 수 없는 무게가 되었다. 이름 대신 아는 호칭을 불렀다. 닷새를 같이 있었는데 이름보다 짐꾼이라는 말이 먼저 나왔다는 사실이 뒤늦게 나를 찔렀다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_003","speaker":"나","text":"아저씨.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_004","speaker":"나","text":"일어나요. 말하라면서요. 말할게요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_005","speaker":"나","text":"들어요. 제발.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K2_062","text":"몸을 돌려 각청에게 손을 뻗었다. 도움을 청하려 이름을 부르다가 그녀도 같은 상태라는 것을 깨달았다. 손목에도, 목 가까이에도 뛰는 것이 없었다. 짐꾼도 병사도 같았다. 현장의 사람들은 모두 죽었다. 그 가운데 나만 살아 있었다."},{"k":"line","id":"PRO_L02K2_death_006","speaker":"","text":"짐꾼의 몸을 다시 당겼다. 조금 옮기는 것만으로 손이 미끄러졌다. 도와 달라고 고개를 들었다가 그 말마저 삼켰다. 사람은 가득한데 부를 사람이 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_007","speaker":"나","text":"왜…… 아까 다 살아 있었잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L02K2_death_008","speaker":"나","text":"누가 좀. 여기 혼자 두지 말아요.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K2_065","text":"짐꾼을 바닥에 눕히고 한 발 뒤로 물러났다. 다시 들면 될 것 같아서 손을 뻗었지만, 닿기 전에 팔이 굳었다. 시신이 무서운 것인지 다음 순간 내게 무슨 일이 생길지가 무서운 것인지 구분할 수 없었다. 계단 쪽으로 몸을 돌렸을 때 비명이 터졌다."},{"k":"line","id":"PRO_L02K2_death_009","speaker":"","text":"내려가는 길에서 몇 번이나 돌아서려 했다. 물건을 두고 온 것처럼. 그러나 돌아갈 곳에 무엇이 있는지 떠올릴 때마다 다리가 먼저 달렸다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L02_K2_067","text":"행사 통로 밖으로 빠져나온 뒤에도 길을 고를 여유가 없었다. 내 발소리가 겹쳐 들릴 때마다 누가 따라오는 줄 알았다. 물자 구역으로 향하던 발은 중간에 멈췄다. 그곳에 가면 짐꾼이 돌아올 자리가 보일 것이었다."},{"k":"line","id":"PRO_L02K2_death_010","speaker":"","text":"길가에 엎드리듯 앉았다. 아직 짐꾼의 소매를 쥐고 있는 줄 알고 손을 폈다. 아무것도 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_death_011","speaker":"나","text":"……내가 본 건 내가 말해야지. 저 사람들은 이제 못 하잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_death_012","speaker":"나","text":"사람 있는 데로 가자. 이번엔 순서 찾다가 놓치지 말고.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_death_013","speaker":"","text":"말을 알아들어 줄 사람을 생각하자 선인들이 떠올랐다. 소는 어디 있는지 몰랐다. 거처와 산의 모습을 가장 선명하게 기억하는 이름을 붙들었다. 류운차풍진군.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_001","speaker":"","text":"머릿속에서는 간단했다. 절운간 쪽으로 가서 오장산에 오르고, 거처를 찾아 소식을 전한다. 실제로는 어느 길이 산을 돌아 올라가고 어느 길이 절벽 아래에서 끊기는지부터 알아내야 했다. 처음 택한 오르막은 능선에 닿지 않았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_002","speaker":"나","text":"길을 안다고 한 적은 없지. 장소를 안다고만 했지. ……산한테 면담 거절당하고 끝낼 수는 없어.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_073","text":"산으로 들어가는 길을 다시 골랐다. 짐꾼이 무거운 것을 든 몸으로 사람 사이의 틈을 찾던 모습이 떠올랐다. 곧장 가는 길이 항상 몸을 가장 적게 쓰는 길은 아니라는 것을, 그의 걸음에서 조금 배웠던 것 같다."},{"k":"line","id":"PRO_L02K2_mountain_003","speaker":"","text":"바위가 많은 비탈에서 돌이 굴렀다. 내가 찬 게 아니었다. 바위 색 비늘, 작은 뿔. 새끼 용 도마뱀 셋이 길 한가운데서 나를 보고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_004","speaker":"나","text":"지금 나 건드리면 안 되는데.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_005","speaker":"","text":"알아들었을 리 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"combat","id":"PRO_L02K2_mountain_006","group":"EG_LIYUE_VISHAP","text":"산길을 막은 새끼 용 도마뱀 무리. 지나가지 않으면 오장산에 닿을 수 없다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_007","speaker":"","text":"마지막 한 마리가 바위 틈으로 들어갔다. 숨이 거칠었다. 싸우는 동안만큼은 짐꾼의 얼굴이 떠오르지 않았다. 그게 미안했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_008","speaker":"","text":"높이 오를수록 사람 소리가 멀어졌다. 머릿속에서 짐꾼은 여전히 나에게 본 것과 안 본 것을 나누라고 말하고 있었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_009","speaker":"","text":"거처 앞에 도착했을 때 문을 향해 곧장 걸어갔다가 제자리로 돌아왔다. 숨이 거칠어 첫마디를 끝내지 못할 것 같았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_010","speaker":"나","text":"류운차풍진군. 리월항에서 왔습니다. 제군의 시신이 떨어진 것을 봤고, 그 뒤 현장에 있던 사람들이 죽었습니다. 저는 살아 나왔어요. 문을 여실 수 없으면 듣고 계신지만 알려 주십시오.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_011","speaker":"","text":"대답이 없었다. 다시 부르고 싶은 마음을 누르며 문 옆으로 비켜섰다.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L02K2_mountain_012","options":[{"label":"제가 모르는 절차가 있으면 말씀해 주세요. 음식을 갖추라고 하셔도 지금은 없습니다. 있는 척할 수는 없잖아요.","id":"PRO_L02K2_mountain_013","items":[{"k":"line","id":"PRO_L02K2_mountain_014","speaker":"류운차풍진군","text":"갖추지 못한 예물을 핑계로 들어 달라는 것인지, 들은 뒤에 예물을 요구하지 말라는 것인지. 인간의 말은 참으로 돌아가는 길이 많군. 이름을 밝히고 용건을 말하게.","map":"MAP_LIYUE_PLAINS"}]},{"label":"급한 소식을 전하러 왔지만, 문 앞 예절까지 안다고 할 수는 없습니다. 이름과 용건부터 말씀드려도 될까요?","id":"PRO_L02K2_mountain_015","items":[{"k":"line","id":"PRO_L02K2_mountain_016","speaker":"류운차풍진군","text":"모르는 순서를 묻는 것은 허물이 아니지. 다만 급하다는 말로 다른 설명을 덮지는 말게. 이름을 밝히고 용건을 말하게.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L02K2_mountain_017","speaker":"나","text":"(자신의 이름을 밝힌다.) 몬드에서 왔습니다. 리월항 밖에서 기다리다가 오늘 의례를 보러 올라갔고요. 들어도 모르실 이름이지만, 제 이름 걸고 말씀드리겠습니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_018","speaker":"류운차풍진군","text":"의례를 보러 간 사람이 제군의 시신을 보고 돌아왔다. 그 뒤 사람들이 죽었다는 말은, 모두가 흩어져 보이지 않았다는 뜻이 아니겠지?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_019","speaker":"나","text":"없어진 게 아니에요. 제 앞에 남아 있었어요. 같이 올라간 사람을 잡고 있었는데 힘이 빠졌고, 불러도 대답하지 않았습니다. 각청도 바로 거기서 죽었어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_020","speaker":"","text":"문이 열렸다. 학의 눈이 내 차림보다 얼굴에 오래 머물렀다. 마침내 내 증언이 살아 있는 상대에게 도착했다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_021","speaker":"류운차풍진군","text":"발부터 들이밀 생각은 접고 잠깐 서 있게. 바닥의 높이가 달라 몸이 앞으로 쏠릴 것이야.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_022","speaker":"나","text":"알겠습니다. 제가 아무 데서나 넘어지는 사람이 된 건 오늘만 그런 겁니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_023","speaker":"류운차풍진군","text":"어제는 아니었다는 말인가?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_mountain_024","speaker":"나","text":"……어제도 조금요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_audience_001","speaker":"","text":"말한 것만큼 조심해서 들어갔다. 류운차풍진군은 나를 앉혔다. 문밖에서 정리한 순서는 앉는 순간 다시 흐트러졌다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_002","speaker":"류운차풍진군","text":"함께 올라갔다는 이는 자네의 오랜 벗인가?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_003","speaker":"나","text":"아니요. 닷새 같이 기다린 사람이에요. 화물이 막힌 짐꾼이었고…… 망서 객잔 승강기에서 떨어질 뻔한 걸 같이 끌어올린 사람이기도 해요. 이름도 못 물어봤어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_004","speaker":"류운차풍진군","text":"그 사람이 죽은 뒤 자네는 무엇을 했나. 이 몸에게 잘 보일 일을 골라 말하라는 뜻이 아니야.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_005","speaker":"나","text":"깨우려고 했고, 끌고 가려고 했어요. 안 됐어요. 각청한테 도와 달라고 하려다가 그 사람도 죽은 걸 확인했고요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_006","speaker":"나","text":"그러고는…… 놔두고 도망쳤습니다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_007","speaker":"","text":"마지막 대답을 할 때 고개를 들었다. 짐꾼에게 본 것만 말하겠다고 했던 사람이, 그를 두고 나온 장면만 다른 모양으로 바꿀 수는 없었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_008","speaker":"류운차풍진군","text":"구할 수 있었는데 하지 않았다는 것과, 구하려 했으나 손이 닿지 않았다는 것은 다르지. 이 몸이 그 자리에 없었으니 어느 쪽이라고 대신 판정하지는 않겠네. 다만 업고 오지 못했다고 해서 가져온 소식까지 버릴 이유는 없네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_009","speaker":"","text":"그분이 여기 있었다면 내 말이 길다고 했을 것이다. 아는 게 있다고만 하지 말고 그냥 말하라고. 그래서 이번에는 먼저 말했다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"choice","group":"G_PRO_L02K2_audience_010","options":[{"label":"모락스의 계략입니다. 자신의 죽음을 계기로 리월이 스스로 위기를 넘기는지 보려는 거예요. 오셀이 나올 수 있으니, 막을 준비를 하셔야 합니다.","keep":"ISK_L02_K2_094","items":[]}]},{"k":"line","id":"PRO_L02K2_audience_011","speaker":"류운차풍진군","text":"자네가 방금 붙인 이름이 얼마나 무거운지 알고 하는 말인가. 누구에게 들었는가? 그 말을 전한 사람이 오늘 그곳에 있었나?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_012","speaker":"나","text":"이곳 사람한테 들은 게 아닙니다. 제가 살던 곳에서, 이곳의 일을 이야기처럼 알고 있었어요. 제가 여기 온 것부터 설명이 안 된다는 건 알아요. 그런데 오셀 이름을 아는 이유도, 당신을 찾아올 생각을 한 이유도 그겁니다. 거짓말을 덧대서 더 그럴듯하게 만들 수는 없어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_013","speaker":"류운차풍진군","text":"자네가 알고 있었다는 이야기에는 오늘 함께 갔던 이의 죽음도 있었나?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_014","speaker":"나","text":"없었어요. 병사들이 기억을 잃는 일도, 제 눈앞에서 모두가 죽는 일도요. 그러니까 계략이라는 건 제가 아는 원래 이야기의 설명이고, 오늘 이 죽음의 이유까지 안다는 뜻은 아니에요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_015","speaker":"류운차풍진군","text":"아는 이야기가 있으니 모르는 일이 벌어져도 그 안에 들어갈 것이라고 기대하고 있지 않은가. 이미 자네는 그 이야기에 없던 죽음을 두 번 보았네. 그런데도 더 오래 알고 있던 쪽에 모든 판단을 맡길 셈인가?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_016","speaker":"","text":"반박할 말은 많아 보였다. 어느 반박도 짐꾼을 다시 일으켜 세우지는 못했다. 무릎 위의 손을 풀었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"choice","group":"G_PRO_L02K2_audience_017","options":[{"label":"그래도 경고는 하겠습니다. 미래를 다 안다는 말은 거둘게요. 오셀에 대비해 달라는 말은 거두지 않겠습니다.","id":"PRO_L02K2_audience_018","items":[{"k":"line","id":"PRO_L02K2_audience_019","speaker":"류운차풍진군","text":"그 두 말을 구분할 수 있다면 이 몸도 다르게 듣겠네. 자네의 확신을 증거로 삼지는 않겠으나, 구체적인 위협을 경계할 이유로는 검토하지.","map":"MAP_LIYUE_MOUNTAINS"}]},{"label":"아는 줄 알았던 데 매달린 건 맞아요. 아무것도 모르겠다고 하면 도망갈 데도 없어질 것 같았거든요. 그래도 직접 확인하러 가 주시면 안 될까요?","id":"PRO_L02K2_audience_020","items":[{"k":"line","id":"PRO_L02K2_audience_021","speaker":"류운차풍진군","text":"확인할 필요는 충분히 들었네. 자네를 달래려 나서는 것이 아니라 리월에 일어난 일을 살피러 가는 것이야. 그 차이가 서운하더라도 받아들이게.","map":"MAP_LIYUE_MOUNTAINS"}]}]},{"k":"line","id":"PRO_L02K2_audience_022","speaker":"","text":"아직 말하지 않은 것이 남아 있었다. 망서 객잔에서 소에게 들었던 말. 각청에게는 끝내 전하지 못했다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_023","speaker":"나","text":"한 가지 더요. 소를 만났을 때 제 주변에 죽음과 생명의 냄새가 같이 난다고 했습니다. 마신을 미워하는 기척도요. 저는 그런 마음 없어요. 그분도 누구 건지까지는 말하지 않았고요. 각청한테는…… 못 전했어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_024","speaker":"류운차풍진군","text":"그 말을 듣고 난 뒤 자네에게 달라진 점이 있었나?","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_025","speaker":"나","text":"딱히요. 오늘 일을 전부 그 말에 붙이면 설명한 것 같겠지만, 그럴 근거는 없잖아요. 그냥 저만 남았어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_026","speaker":"나","text":"그게 지금 제일 무서워요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_027","speaker":"류운차풍진군","text":"이 몸은 소가 전한 말을 가볍게 여기지 않네. 그렇다고 들은 말 하나로 지금의 모든 죽음에 주인을 정해 주지도 않을 것이야. 모르는 것을 견디지 못해 아무 답이나 붙잡으면, 다음에 보는 것도 그 답에 맞춰 바꾸게 되지.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_028","speaker":"나","text":"닷새 동안 남한테는 모르면 모른다고 해도 된다고 해 놓고, 정작 제가 모르겠다는 건 이렇게 못 견디네요. 말로 남 도와주는 건 참 편했어요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_029","speaker":"류운차풍진군","text":"누군가에게 해 준 말이 이제 자네에게도 필요한 때가 온 것이겠지. 그 말이 거짓이 되는 건 아니네. 허나 자네를 위로하는 일만 하고 있을 수는 없어. 이 몸은 항구 쪽 사정을 살피겠네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_030","speaker":"","text":"그녀는 자신이 무엇을 이미 알고 있는지 풀어놓지 않았다. 원작의 장면을 맞혀 보이는 손님이 아니라, 실제 현장에서 소식을 가져온 사람으로 대우받고 있다는 것을 느꼈다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_031","speaker":"나","text":"저도 내려가겠습니다. 그분 짐이 있던 곳으로요. 집이 어딘지, 기다리는 사람이 누군지는 모르지만…… 물을 사람이 있으면 제가 대답해야죠.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_032","speaker":"류운차풍진군","text":"지금 내려가겠다고 벌떡 일어나지는 말게. 산길은 자네가 후회하는 만큼 짧아지는 것이 아니야. 빛이 남은 구간만 움직이게. 소식을 전하려거든 소식을 가진 몸부터 무사히 데려가야 하네.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_033","speaker":"나","text":"들을수록 제가 되게 관리 안 된 짐짝 같네요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_034","speaker":"류운차풍진군","text":"자네가 그렇게 말했네. 이 몸은 아니야.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_035","speaker":"나","text":"……네. 안 떨어뜨리고 내려가 볼게요.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_audience_036","speaker":"류운차풍진군","text":"해 보겠다는 말은 장담이 아니니 마음에 드는군. 앉아 있을 수 있을 때는 더 앉아 있게.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"line","id":"PRO_L02K2_return_001","speaker":"","text":"조금 더 앉아 있었다. 무언가를 해야 한다는 마음과 몸이 움직일 수 있다는 사실을 처음으로 따로 생각했다. 나를 재촉할 짐꾼은 없었다.","map":"MAP_LIYUE_MOUNTAINS"},{"k":"keep","id":"ISK_L02_K2_123","text":"해가 진 뒤에는 길을 확인할 수 없는 비탈을 포기하고 바위 아래에 머물렀다. 눈을 감으면 짐꾼의 몸을 놓는 순간이 떠올랐다. 몇 번을 다시 보아도 다음 장면은 달라지지 않았다. 다시 밝아진 뒤에야 외곽으로 발걸음을 이었다."},{"k":"line","id":"PRO_L02K2_return_002","speaker":"","text":"항구로 향하는 길에서 먼 곳의 수레를 먼저 보았다. 사람이 끌고 있었다. 살아 있는 사람이 일하고 있었다. 다행이라고 생각하는 순간, 두고 온 사람들만 다시 떠올리는 것이 미안해졌다.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_125","text":"도시는 여전히 통제되어 있었다. 물자를 기다리는 사람들이 병사 앞에서 설명하고 있었다. 그 가운데 익숙한 옷차림을 보았다. 각청이었다. 그녀가 걸음을 옮기자 주변 사람들이 자연스럽게 길을 비켜 주었다."},{"k":"line","id":"PRO_L02K2_return_003","speaker":"","text":"잘못 보았다고 생각하려 했다. 그러나 눈앞의 각청은 자기 이름을 부르는 사람에게 돌아보았고, 질문에 대답했다. 살아 있었다. 의례장에서 확인한 손목의 침묵과 이곳에서 움직이는 손이 한 사람의 것이었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_return_004","speaker":"나","text":"각청.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_return_005","speaker":"나","text":"너 어떻게…… 나야. 포대 끈 봤다던 사람.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L02K2_return_006","speaker":"나","text":"너 죽었잖아. 내가 확인했는데.","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_128","text":"각청은 즉시 대답하지 않았다. 그녀가 잠깐 멈춘 것을 나는 알아보았다는 신호로 받아들이려 했다. 그러나 다음 시선은 알고 있는 사람의 말을 기다리는 시선이 아니었다. 혼란스러운 말을 늘어놓는 낯선 사람이 자신을 어디에서 보았을지 살피는 눈이었다."},{"k":"line","id":"PRO_L02K2_return_007","speaker":"각청","text":"내가 죽었다고? 진정하고 처음부터 말해 봐. 그 전에 하나만. 너 누구야? 나를 알아?","map":"MAP_LIYUE_PLAINS"},{"k":"keep","id":"ISK_L02_K2_END","text":"리월항 외곽 봉쇄선. 이야기는 살아 있는 각청의 질문 앞에서 멈춘다."}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L02_K2_001_0","text":"짐꾼은 같은 일을 두 번 했다는 확인 때문에 품삯을 받지 못했다. 그런데 행추가 들고 온 인계표를 보니, 그가 옮긴 자루에는 서로 다른 두 항구의 번호가 붙어 있었다."},{"k":"text","id":"V141_BEFORE_ISK_L02_K2_001_6","text":"둘이 밥 맡으면 나는 짐표 맡을게. 아저씨, 다녀와서 또 세라고 하면 그땐 제가 대신 화낼 거예요."},{"k":"text","id":"V141_AFTER_ISK_L02_K2_001_2","text":"고마워. 이건 내가 전할게. 행추, 나중에 저 아저씨를 못 찾게 되면…… 이번에는 짐 말고 사람부터 찾아 줘."}]},{"id":"ISK_L03_K1","entry":"ISK_L03_K1_001","items":[{"k":"keep","id":"ISK_L03_K1_001","text":"각청이 누구냐고 묻자 나는 대답 대신 그녀의 손목을 보았다. 살아 있다는 사실이 눈앞에 있는데도 손끝으로 다시 확인해야 할 것 같았다. 각청은 그 시선을 따라 자기 팔을 한 번 보더니, 뒤에서 다가오던 병사에게 기다리라고 손짓했다. 익숙한 동작이었다."},{"k":"line","id":"PRO_L03K1_stranger_001","speaker":"나","text":"알아. 닷새 동안 저쪽 천막에 같이 있었어. 내가 자꾸 맥박 재니까 네가 그만 보라고 했고, 비 오던 날엔 둘이 천막 물도 뺐어. 네 신발 젖었잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_002","speaker":"각청","text":"……그 천막이 어딘지는 알아. 네가 말한 일은 기억에 없어. 내가 너를 조사했다면 담당 병사도 있었겠지. 그 사람부터 찾자. 손은 언제 다쳤어?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_003","speaker":"","text":"손바닥을 뒤집었다. 산을 오르다 긁힌 자국과 말라붙은 흙. 그녀를 붙들던 손이었고, 놓고 도망쳤던 손이었다. 각청은 병사에게 씻을 물이 있는 곳을 묻고 나에게 길옆의 낮은 자리를 가리켰다. 그 배려마저 익숙해서 앉을 수 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_004","speaker":"나","text":"상처는 나중에. 의례 말해 줘. 모락스의 시신이 떨어졌잖아. 응광이 지시하고, 네가 사람들 물리고. 그것도 기억 안 나?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_005","speaker":"각청","text":"제군의 시신? 의례에 간 건 기억해. 그런 일이 있었으면 내가 지금 여기서 수레나 세고 있겠어? 천천히. 뭘 봤는지부터.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_006","speaker":"","text":"뒤의 병사도 그날 안내를 맡았다고 했지만 하늘에서 떨어진 거대한 몸은 기억하지 못했다. 다른 참관객을 불러도 답은 같았다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_007","speaker":"참관객","text":"사람이 많아서 앞은 안 보였어요. 그런데 그런 일이 났으면 소리라도 들었겠죠. 저는 그냥…… 잠깐 정신이 없었던 것 같은데. 왜 그렇게 보세요? 숨기는 거 없어요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K1_stranger_008","speaker":"나","text":"숨겼다고 안 했어요. 다들 그 부분만 없다고 하니까…… 어디에다 대고 말해야 하나 싶어서요.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L03K1_stranger_009","options":[{"label":"나 못 믿어도 돼. 대신 내가 가리키는 자리까지 같이 가 줘. 없는 일 우긴 거면 돌아오는 길에 나한테 화내도 돼.","id":"PRO_L03K1_stranger_010","items":[{"k":"line","id":"PRO_L03K1_stranger_011","speaker":"각청","text":"없는 일인지 보려고 가는 거야. 화낼 이유를 미리 만들 생각은 없어. 혼자 통제선 넘으면 그 자리 가기도 전에 붙잡혀. 내 옆에서 움직여.","map":"MAP_LIYUE_PLAINS"}]},{"label":"네가 날 기억 못 하는 건 억지로 받아들여 볼게. 그래도 의례장까지 없어지진 않았잖아. 거기서부터 보자.","id":"PRO_L03K1_stranger_012","items":[{"k":"line","id":"PRO_L03K1_stranger_013","speaker":"각청","text":"현장 다시 보자는 데는 동의해. 걷는 동안 물은 마셔. 목소리만 높이면 네 다리가 못 버텨.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"keep","id":"ISK_L03_K1_016","text":"각청은 신뢰한다는 선언 대신 길을 열었다. 그 뒤를 따르다 천막 끝을 보았다. 비를 빼던 날 접어 둔 천이 여전히 같은 방향으로 말려 있었다. 흔적은 남았는데 사람을 알아보던 눈길만 사라져 있었다."},{"k":"keep","id":"ISK_L03_K1_017","text":"두 사람은 행사 때 이용했던 계단을 다시 올랐다. 각청이 앞서가다 돌아볼 때마다 그녀가 쓰러졌던 순간이 지금의 몸에 겹쳤다. 계단 중간에서 한 번 멈춰 숨을 골랐고, 각청은 재촉하지 않았다."},{"k":"line","id":"PRO_L03K1_empty_001","speaker":"","text":"사람이 쓰러졌던 곳을 먼저 보았다. 제례에 쓴 물건이 정리되어 있었고, 줄은 한쪽으로 걷혀 있었다. 각청을 받쳤던 자리를 찾아 멈췄다가, 시선을 더 안으로 옮겼다. 가장 큰 것이 없었다. 모락스의 시신이 사라져 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_002","speaker":"나","text":"여기 있었잖아. 저기서 떨어져서 이쪽으로. 네가 이 앞에 섰고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_003","speaker":"현장 병사","text":"저희가 넘겨받을 때는 그런 시신이 없었습니다. 큰 물건을 옮겼다는 인계도 없고요. 응광 님께도 전했습니다만, 제군께 그런 일이 있었다는 기억이 없다고 하셨습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_004","speaker":"","text":"응광까지. 그 거대한 몸 앞에서 냉정하게 사람을 움직이던 여자가, 이제는 시신을 옮기라고 했는지조차 말해 줄 수 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_005","speaker":"나","text":"그럼 끝이야? 기억 없고 넘겨받은 것도 없으니까 원래 없었던 걸로?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_006","speaker":"나","text":"저게 주머니에 넣고 갈 물건이야? 사람이 죽고, 너도 죽고, 시신까지 없어졌는데 왜 나만 찾고 있냐고!","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_007","speaker":"","text":"마지막 말은 각청을 향해 튀어나왔다. 소리를 지른 뒤에야 그녀가 한 발도 피하지 않았다는 것을 보았다. 병사가 말리려 팔을 내밀자 각청이 그 앞을 막았다. 살아 돌아온 사람에게 왜 죽었느냐고 따지고 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_008","speaker":"각청","text":"네 말이 맞으면 난 모르는 사이에 죽었다가 지금 여기 서 있는 거겠지. 설명 못 해 주는 건 미안해. 그런데 기억 없다고 나까지 손 놓은 사람으로 만들지는 마. 지금 네 옆에 서 있잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_009","speaker":"나","text":"……알아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_010","speaker":"나","text":"네가 너무 멀쩡해서 화가 나. 미안.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_011","speaker":"각청","text":"화내. 대신 걸으면서 내. 시신이 없어졌으면 옮긴 길이 있어. 기억이 없다고 길까지 없어지진 않아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_012","speaker":"","text":"각청은 곧장 병사 둘을 나누어 보냈다. 큰 몸을 숨길 수 있는 장소, 제군의 힘을 노리고 접근할 사람. 이름 하나가 머릿속을 차갑게 가로질렀다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_013","speaker":"나","text":"타르탈리아. 우인단 집행관. 그 사람 리월에 와 있지? 황금옥부터 봐야 해.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_014","speaker":"각청","text":"그 이름은 알아. 그런데 왜 그 사람이야? 가져갔다는 목격이 있어?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_empty_015","speaker":"나","text":"본 건 아니야. 내가 알던 이야기에서는 그가 황금옥에서 신의 심장을 노려. 거기서 뜻대로 안 되면 일이 바다까지 번져. 다 그 사람 짓이라는 게 아니라, 더 큰 사고가 날 곳을 하나 아는 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K1_031","text":"각청은 황금옥이라는 말에서 옆에 있던 병사를 불렀다. 그때 계단 쪽에서 숨이 찬 목소리가 올라왔다. 감우와 연비였다. 두 사람은 의례장에 없었다. 그러니 기억도 그대로였다."},{"k":"line","id":"PRO_L03K1_adepti_001","speaker":"","text":"돌바닥 위로 긴 그림자가 드리웠다. 바람이 제례용 천을 뒤집었고, 병사들의 시선이 한꺼번에 하늘로 올라갔다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_002","speaker":"류운차풍진군","text":"이 몸이 항구의 사정을 살피겠다고 한 것이 그저 자네를 돌려보내려는 말로 들렸나? 돌아오자마자 목이 쉬도록 외쳐 대고 있으니 산에서 쉬게 한 보람이 없군. 자네가 말한 각청이 이 사람인가?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_003","speaker":"","text":"류운차풍진군이 내려앉는 동안 먼 지붕 위로 또 다른 선인의 형체가 멈췄다. 소는 소란의 가운데로 들어오지 않은 채 각청과 나 사이에 시선을 멈췄다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_004","speaker":"나","text":"맞아요. 제 앞에서 죽었는데 지금은 살아 있어요. 시신도 없어졌고, 각청도 응광도 기억 못 한대요. 제가 거짓말한다고 생각하실까 봐…… 아니, 그거 걱정할 때가 아니네요. 타르탈리아가 황금옥에 있을 수 있어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_005","speaker":"류운차풍진군","text":"산에서 들은 말을 이 몸이 잊지 않았네. 자네가 눈앞의 사람을 보고 말을 바꾼 것이 아니라는 뜻이지. 칠성이 제군의 일을 모른다 하니, 이 몸도 당사자에게 직접 물을 말이 있어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_006","speaker":"각청","text":"응광에게 자리를 마련하라고 전하겠습니다. 다만 선인께서 함께 들으신다는 것과 제가 현장을 확인할 책임은 같이 갑니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_007","speaker":"류운차풍진군","text":"이 몸이 자네에게 손을 놓으라 하였나? 움직일 마음이 있다면 길부터 열게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_008","speaker":"","text":"각청의 눈썹이 움직였지만 그녀는 돌아서서 길을 지시했다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K1_adepti_009","options":[{"label":"오셨으니까 말씀드리는데, 이 사람은 제 말 안 믿겨도 현장까지 같이 와 줬어요. 저 때문에 서로 화내지 마세요.","id":"PRO_L03K1_adepti_010","items":[{"k":"line","id":"PRO_L03K1_adepti_011","speaker":"류운차풍진군","text":"자네는 목 아끼라는 충고는 들을 생각이 없으면서 남의 언성은 걱정하는군. 좋네. 따질 말은 당사자 앞에서 하겠어.","map":"MAP_LIYUE_HARBOR"}]},{"label":"같이 가 주셔야겠어요. 제가 혼자 모락스의 계획이라는 말을 꺼내면 의자에 앉기도 전에 끌려나올 것 같습니다.","id":"PRO_L03K1_adepti_012","items":[{"k":"line","id":"PRO_L03K1_adepti_013","speaker":"류운차풍진군","text":"산에서는 문밖에 앉을 자리라도 있었지. 여기서는 서서 고함만 지를 작정이었나 보군. 이 몸이 함께 듣겠네. 틀리면 틀렸다고 할 사람도 필요할 테니.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K1_adepti_014","speaker":"소","text":"네가 서 있던 곳은 내가 보겠다. 바다 쪽도. 너는 살아 있는 사람 붙들고 죽었던 순간만 묻지 마. 그다음에 뭘 할지도 들어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_015","speaker":"나","text":"……알겠어요. 그런데 망서 객잔에서 하신 말이 아직 걸려요. 지금도 제가 사람들하고 같이 있어도 되는 겁니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_016","speaker":"소","text":"답할 단서는 아직 없다. 그래서 보고 있는 거야. 두려워서 혼자 움직이다 죽을 이유도 없다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_adepti_017","speaker":"","text":"소는 더 설명하지 않고 현장 바깥으로 움직였다. 나를 무해하다고 선언한 것은 아니었다. 그래도 혼자 사라지지 말라는 말은 들었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K1_049","text":"군옥각으로 향하는 동안 각청은 먼저 보낸 병사들의 보고를 받았다. 황금옥 쪽에 우인단이 드나든 흔적이 있고, 안쪽과 연락이 원활하지 않다는 소식이었다. 군옥각에 오른 뒤, 나는 아래로 멀어지는 거리보다 문 안에서 기다리는 사람을 먼저 보았다."},{"k":"line","id":"PRO_L03K1_palace_001","speaker":"","text":"응광은 긴 탁자 곁에 서 있었다. 손님용 잔과 항구 지도가 함께 놓여 있었다. 그녀의 눈길이 내 흙 묻은 신발, 갈라진 입술, 선인 앞에서도 물러서지 않는 각청을 차례로 훑었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_002","speaker":"응광","text":"며칠 바깥에서 기다리던 손님이 선인들을 데리고 올라올 줄은 몰랐네. 나한테 따로 할 말이 있었다지? 들을 사람은 다 모였어. 급한 것부터.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_003","speaker":"나","text":"먼저 확인할게요. 의례에서 모락스의 시신이 떨어졌고, 당신은 사람들을 물린 다음 현장을 떠났어요. 저는 각청한테 당신을 만나게 해 달라고 했고요. 하나도 기억 안 나세요?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_004","speaker":"응광","text":"의례를 준비하고 올라간 건 기억해. 네가 말하는 제군의 죽음은 없어. 자리를 떠난 뒤 누구에게 뭘 맡겼는지 물으면, 그 사이가 분명하지 않아. 마음에 안 드는 대답이겠지만 없는 기억을 만들어 줄 수는 없잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_005","speaker":"류운차풍진군","text":"제군께 일이 생겼다는 증언을 이 몸이 들었고 다른 선인들에게도 전했네. 그런데 와 보니 제군의 몸은 없고, 칠성마저 당시를 기억하지 못한다 하는군. 이 일을 장부 한 장 빠진 정도로 취급할 수는 없어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_006","speaker":"응광","text":"가볍게 봤으면 지도를 펴 두지 않았겠죠. 기억이 없다는 말과 손을 놓았다는 말은 달라요. 지금도 이동로와 황금옥을 확인하고 있어요. 바다와 항구 밖은 선인들께서 봐 주실 수 있겠죠.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_007","speaker":"나","text":"그래서 말씀드려요. 제가 알고 있던 이야기에서 이건 모락스의 계획이었어요. 죽은 모습을 보이고, 자기 없는 리월이 어떻게 버티는지 보려는 계획. 타르탈리아가 신의 심장을 찾아 황금옥으로 가고, 결국 오셀이 나타납니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_008","speaker":"","text":"잔을 옮기던 사람의 손이 멈췄다. 이름 하나가 방의 무게를 바꾸었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_009","speaker":"응광","text":"제군의 계획을 안다는 말은 가벼운 패가 아니야. 그분이 직접 알려 줬어? 아니면 네가 본다는 그 이야기에, 지금 이 방 사람들의 결정까지 적혀 있었니?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_010","speaker":"나","text":"직접 들은 적은 없어요. 다른 세계에서 이곳의 일을 이야기로 봤습니다. 그런데 이번에는 사람들까지 죽었어요. 제가 알던 계획에 그런 건 없었습니다. 그것까지 모락스가 했다고 우기는 게 아니라, 제가 아는 다음 위험을 말하는 거예요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_011","speaker":"각청","text":"앞에서 맞는 게 있었다고 뒤를 전부 믿을 순 없어. 그래도 대비 안 할 이유도 없지. 네가 아는 거, 바다랑 타르탈리아 막는 데 도움이 돼?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_012","speaker":"","text":"군옥각의 안쪽을 보았다. 멀리서는 거대한 이야기 속 무대였지만 지금은 누군가 오래 모은 물건들이 놓인 집이었다. 그것을 잃으라고 말할 차례가 다가오자, 머릿속에서 쉬웠던 공략이 갑자기 남의 삶을 처분하는 말이 되었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_013","speaker":"나","text":"오셀이 정말 나오고 제가 아는 대로 흘러가면…… 이 군옥각을 포기해야 합니다. 바다에 떨어뜨려서 막는 거예요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_014","speaker":"나","text":"당신이 이걸 얼마나 아끼는지 알아요. 그래서 돌려 말하고 싶지 않아요. 당신 집을 잃는 이야기입니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_015","speaker":"응광","text":"내 집을 얼마나 아끼는지 안다는 손님이, 처음 올라온 자리에서 버리라고 권하네. 재미있는 방문이야. 그런데 넌 지금 내 결정을 알려 주는 거니, 아니면 그 상황을 막아 달라는 거니? 둘은 값이 많이 달라.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K1_palace_016","options":[{"label":"막을 수 있으면 막고 싶어요. 그래서 황금옥으로 가겠다는 거고요. 제가 못 막으면, 아무 준비 없이 그 순간을 맞게 하고 싶지 않아요.","id":"PRO_L03K1_palace_017","items":[{"k":"line","id":"PRO_L03K1_palace_018","speaker":"응광","text":"그럼 순서가 바뀌었네. 나는 지금 군옥각을 버리기로 결정하지 않아. 먼저 바다를 늦추고, 해안의 사람을 물리고, 이곳을 어떻게 쓸지 계산할 거야. 마지막에 내놓아야 하면 그때 내가 결정해. 네 기억 속 장면에 맞추려고 미리 지붕을 떼어 버릴 생각은 없어.","map":"MAP_LIYUE_HARBOR"}]},{"label":"제가 기억하는 결말은 경고로만 받아 주세요. 재현하자는 게 아니에요. 해안 사람들을 먼저 옮길 수 있는지 봐 주세요.","id":"PRO_L03K1_palace_019","items":[{"k":"line","id":"PRO_L03K1_palace_020","speaker":"응광","text":"경고와 결정은 구분하지. 네가 알려 준 위험을 지금 이곳의 조건으로 다시 계산할 거야. 언제 포기할지는 내가 판단해. 누구 이야기 속 장면을 완성하려고 버리지는 않아.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K1_palace_021","speaker":"류운차풍진군","text":"그 판단에 선인들의 힘도 계산해 넣게. 인간의 건물 하나를 떨어뜨릴 때까지 구경만 할 셈으로 온 것이 아니니.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_022","speaker":"각청","text":"해안부터 움직이겠습니다. 선인들이 바다를 맡아 주시면 안쪽 통로는 제가 열겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_023","speaker":"","text":"논쟁이 끝났다는 선언은 없었지만 할 일이 갈라졌다. 내 말이 받아들여지면 홀가분할 줄 알았다. 실제로는 내 말 때문에 사람들이 움직이기 시작한 것이 더 무거웠다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K1_palace_024","options":[{"label":"한 가지만요. 제가 안 돌아오더라도 황금옥은 꼭 한 번 더 봐 주세요. 소식 끊긴 사람이 또 생기면, 이번에도 저 혼자 기억하는 일로 끝날 것 같아서요.","id":"PRO_L03K1_palace_025","items":[{"k":"line","id":"PRO_L03K1_palace_026","speaker":"응광","text":"안 돌아올 생각부터 하고 나가는 손님은 대접하기 어렵지. 바깥 연락선은 남겨 둘게. 돌아와서 직접 보고하는 편이 나한테도 훨씬 값진 일이야.","map":"MAP_LIYUE_HARBOR"}]},{"label":"군옥각 지키면 나중에 여기서 밥 한 번 먹어도 됩니까? 돌아올 핑계가 하나쯤 있으면 좋겠어요.","id":"PRO_L03K1_palace_027","items":[{"k":"line","id":"PRO_L03K1_palace_028","speaker":"응광","text":"이 방까지 와서 밥값부터 걱정하는 사람은 드문 편이야. 식탁을 차릴 만큼 시간이 남도록 만드는 게 먼저겠지. 그때 메뉴는 내가 고를게.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K1_palace_029","speaker":"나","text":"그럼 저는 타르탈리아 막으러 갈게요. 제군의 시신이 거기 있는지도 보고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_palace_030","speaker":"응광","text":"병사들이 바깥까지 안내할 거야. 네가 알던 상대만 만나리라고 기대하지 마. 지금 네 이야기에서 가장 확실해 보이는 것조차 이미 여러 번 달라졌으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K1_078","text":"그 말은 내가 나 자신에게 해 주지 못했던 충고였다. 잔에 남은 물을 다 마셨다. 군옥각을 희생해야 한다는 말을 들은 직후에도 응광의 손은 흔들리지 않았다. 대신 창밖을 보는 시간이 아주 잠깐 길어졌다."},{"k":"keep","id":"ISK_L03_K1_079","text":"군옥각을 내려와 길을 나누는 곳에서 각청이 나를 잠깐 세웠다. 앞서 보낸 병사가 황금옥의 안쪽 문이 제대로 열리지 않는다고 보고하고 있었다. 서둘러 걸음을 옮기려다 각청이 내민 물통을 보고 멈췄다."},{"k":"line","id":"PRO_L03K1_water_001","speaker":"각청","text":"마시고 돌려줘. 가는 길에 쓰러지면 네가 하겠다는 일 아무도 못 이어받아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_002","speaker":"나","text":"……말하는 건 진짜 그대로네. 기억만 없는 게 이렇게 서운할 줄 몰랐다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_003","speaker":"나","text":"나중에 생각나면, 내가 천막 당기는 힘 조절은 좀 나아졌다고 해 줘.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_004","speaker":"각청","text":"기억 안 나는 걸 기억난다고 약속은 못 해. 대신 네가 돌아오는 건 기다릴 수 있어. 네가 봤다는 나하고 지금의 나를 자꾸 시합시키지 마. 둘 다 나야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_005","speaker":"나","text":"……알았어. 물통은 돌려줄게. 그건 기억해 둬.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_006","speaker":"각청","text":"그건 기억해. 비싼 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K1_water_007","speaker":"","text":"물통을 돌려주며 처음으로 그녀의 얼굴을 제대로 보았다. 죽어 있던 얼굴과 겹쳐 보지 않고, 지금 나에게 화를 내지 않으려 애쓰는 사람을 보았다. 각청은 곧 해안 쪽으로 돌아섰다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K1_084","text":"황금옥 방면 통행은 별도로 허가되었다. 호위 병사들은 길목의 수레를 다른 곳으로 돌리고, 안쪽에 남은 일꾼을 데리고 나오기 위해 연락을 이어 갔다. 나에게 열린 길은 위험이 보고된 건물로 가는 길 하나였고, 그 사실이 이상할 만큼 마음을 단순하게 만들었다."},{"k":"keep","id":"ISK_L03_K1_085","text":"언덕 쪽으로 오르는 동안 손가락을 펴고 오므렸다. 무기를 쥘 때 갈라진 곳이 당겼지만 손목은 움직였다. 황금빛 건물이 가까워질수록 안에서는 아무 소리도 들리지 않았다. 그 고요를 의례장의 고요와 같은 것으로 만들지 않으려고, 발밑의 자갈 소리에 귀를 기울였다."},{"k":"line","id":"PRO_L03K1_golden_001","speaker":"","text":"황금옥 외부에서는 마지막 일꾼 둘이 병사의 부축을 받아 나오고 있었다. 안쪽 통로에서 큰 소리가 난 뒤 문짝 하나가 비틀렸고, 관리 구역을 거쳐 돌아 나왔다는 설명이었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_002","speaker":"","text":"그리고 그 통로 앞에 회색 외투가 둘 서 있었다. 우인단. 일꾼들을 내보내 준 게 아니라, 들어갈 사람을 고르고 있었던 것이다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_003","speaker":"우인단 병사","text":"여기서부터는 집행관의 영역이다. 돌아가.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_004","speaker":"나","text":"저 집행관한테 할 말 있어서 왔는데요. 약속은 안 했지만.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_005","speaker":"우인단 병사","text":"약속 없는 손님은 받지 않는다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_006","speaker":"나","text":"그쪽도 리월에 약속하고 온 건 아니잖아요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_007","speaker":"","text":"대답 대신 얼음이 튀었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"combat","id":"PRO_L03K1_golden_008","group":"EG_FATUI_PATROL","text":"황금옥 관리 통로를 막은 우인단 전투조. 안으로 들어가려면 뚫어야 한다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_009","speaker":"","text":"마지막 병사가 무릎을 꿇었다. 호위 병사들이 달려와 그를 끌어냈다. 통로는 비어 있었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_010","speaker":"나","text":"저는 저 통로로 들어갈게요. 안에 있는 사람이 나오면 붙잡으려고 몰려들지 마세요. 타르탈리아면 출구 막는 쪽이 더 위험해요. 사람들 먼저 멀리 보내고, 제가 나오면 이쪽이 비어 있게 해 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_011","speaker":"호위 병사","text":"무작정 쫓아가진 않겠습니다. 대신 방향을 바꾸시면 소리를 내십시오. 출구를 비우는 것과 당신이 어디 있는지 모르게 되는 건 다른 일입니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K1_089","text":"틈을 지나 안으로 들어갔다. 천장과 기둥 사이의 먼지가 아주 가늘게 떠 있었다. 모락스의 시신은 보이지 않았다. 그보다 먼저, 넓은 공간 한가운데 서 있는 붉은 머리의 남자가 눈에 들어왔다. 타르탈리아였다."},{"k":"line","id":"PRO_L03K1_golden_012","speaker":"타르탈리아","text":"오는 데 시간이 걸렸네. 길을 못 찾은 건 아닐 테고, 만나고 싶은 사람이 많았나 봐. 여기까지 왔으니 할 말은 있겠지?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_013","speaker":"","text":"말투는 가벼웠다. 그 뒤에 당연히 따라올 호기심을 기다렸다. 어디서 왔는지, 얼마나 싸울 수 있는지. 그러나 타르탈리아의 시선은 내 얼굴, 손, 문, 다시 얼굴 순으로 움직였다. 사람을 반기는 눈길인지, 무언가가 도착했는지 살피는 눈길인지 알 수 없었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L03K1_golden_014","options":[{"label":"시신부터 내놔. 네가 가져갔다면 어디 있는지 말하고, 아니라면 뭘 하러 왔는지 말해.","id":"PRO_L03K1_golden_015","items":[{"k":"line","id":"PRO_L03K1_golden_016","speaker":"타르탈리아","text":"빈자리를 보고 바로 나를 찾아왔군. 네가 찾는 게 원래 여기 있었는지는 확인했어? 아니면 내가 여기 있어야 한다고 생각해서 온 건가?","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"네가 여기 있다는 것과 시신을 옮겼다는 건 따로 묻겠어. 뭘 찾으러 왔고, 도착했을 때 여기엔 뭐가 있었지?","id":"PRO_L03K1_golden_017","items":[{"k":"line","id":"PRO_L03K1_golden_018","speaker":"타르탈리아","text":"내가 여기 있다는 이유만으로 빈칸을 다 채우지는 않겠다는 건가. 그럼 네가 확인한 것부터 따져 보자고. 내가 여기 있어야 한다고 생각해서 온 거잖아?","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L03K1_golden_019","speaker":"나","text":"질문으로 되받는 솜씨는 알겠는데 칭찬해 줄 여유는 없어. 신의 심장 찾으러 왔으면 그만둬. 못 얻었다고 바다 쪽으로 일 벌일 생각도 말고.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_020","speaker":"","text":"타르탈리아의 입가에 엷은 웃음이 걸렸다. 예상한 말을 들은 사람처럼 놀라지 않는 반응이 등을 서늘하게 했다. 눈앞의 남자는 신의 심장이라는 말보다 내가 어디까지 다가왔는지에 더 관심이 있는 것처럼 보였다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_021","speaker":"타르탈리아","text":"내가 뭘 할지 많이 생각했구나. 그러고도 혼자 이 앞까지 들어왔어. 바깥 사람들을 물린 건 잘했어.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_022","speaker":"나","text":"보통 그런 말은 부하들 상태부터 보고 하지 않나? 밖에 네 사람들 쓰러져 있는데.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_023","speaker":"타르탈리아","text":"지금 내 앞에 있는 건 너잖아. 싸우러 왔으면 움직여. 네가 어디서 멈추는지 보고 싶네.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_024","speaker":"","text":"무기를 고쳐 쥐었다. 기억 속 타르탈리아라면 그 말에 자신이 먼저 들떠 있을 것 같았다. 눈앞의 남자는 웃고 있었지만 재촉하지 않았다. 시작보다 끝에 관심이 있는 사람처럼 기다렸다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L03K1_golden_025","options":[{"label":"어디서 멈추는지 궁금하면 네 발부터 움직여. 밖에서 기다리는 사람들 있으니까 오래 끌 생각은 없어.","id":"PRO_L03K1_golden_026","items":[{"k":"line","id":"PRO_L03K1_golden_027","speaker":"타르탈리아","text":"기다리는 사람. 그래, 돌아가야 할 이유가 있겠지. 그 이유만큼 움직여 봐.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"내가 아는 너는 싸움 앞에서 그렇게 심심한 얼굴 안 했어. 기분이 나쁜 건지 원래 이랬던 건지 모르겠지만, 확인할 시간도 없네.","id":"PRO_L03K1_golden_028","items":[{"k":"line","id":"PRO_L03K1_golden_029","speaker":"타르탈리아","text":"사람을 안다는 자신감은 편리하지. 처음 보는 내 표정보다 네 기억을 먼저 믿게 해 주니까. 가까이 와서 확인하면 더 빨리 끝나겠네.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L03K1_golden_030","speaker":"","text":"물이 칼날의 모양으로 빛났다. 반사적으로 몸을 옆으로 던졌고, 뒤의 돌에 날카로운 자국이 생겼다. 첫 공격은 대화를 이어 갈 틈을 잘라 냈다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K1_107","text":"황금옥 내부에서 타르탈리아와의 전투가 시작된다."},{"k":"line","id":"PRO_L03K1_golden_031","speaker":"","text":"기둥 뒤로 물러났을 때 발밑의 돌판이 내려앉았다. 타르탈리아가 따라 들어오다 자세를 낮췄다. 손아귀가 풀려 무기를 놓칠 뻔했다. 그래도 밖으로 이어지는 길을 그냥 내줄 수는 없었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_032","speaker":"나","text":"여기서 끝내. 바다도, 밖의 사람들도 건드리지 마.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_033","speaker":"","text":"타르탈리아가 고개를 들었다. 다음 공격을 준비하는 대신 내 어깨 너머를 보았다. 그 시선이 어디에 닿았는지 확인하지 못했다. 승기를 붙잡았다고 생각한 바로 그 순간, 발밑에서 낮은 파열음이 났다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_034","speaker":"","text":"바닥의 금이 발끝을 지나 기둥 아래로 달렸다. 위에서 먼저 먼지가 쏟아지고, 이어 돌을 잇던 구조물이 굉음과 함께 어긋났다. 출구 쪽으로 몸을 틀었다. 늦었다. 무너져 내리는 들보가 시야를 가렸고, 틈 너머로 보이던 타르탈리아의 모습도 먼지 속에 사라졌다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K1_golden_035","speaker":"나","text":"밖으로 물러나요! 문 앞에 서 있지 말고, 멀리—!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K1_113","text":"외침은 건물이 내려앉는 소리에 묻혔다. 충격이 어깨와 등을 차례로 때렸다. 쏟아진 돌과 들보가 몸을 눌렀다. 빛이 가늘어졌다. 황금옥이 무너졌고, 나는 그 아래에 깔렸다."},{"k":"keep","id":"ISK_L03_K1_END","text":"황금옥 잔해가 나를 덮친 순간에서 멈춘다. 구조 여부와 부상 상태는 아직 밝혀지지 않는다."}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L03_K1_031_0","text":"각청 님, 고운각에서 가져온 보고와 같은 배가 다시 보였답니다. 경계대를 더 보내고 있어요. 그리고…… 이분. 공고를 들고 저를 찾아오셨던 분이에요. 며칠 전에 저와 함께 고운각에 가셨어요."},{"k":"text","id":"V141_BEFORE_ISK_L03_K1_031_1","text":"……네가 이 사람을 알아? 감우, 그 보고 찾은 게 언제야. 황금옥 확인하고 해안 경계도 같이 진행해. 하나 끝날 때까지 기다리지 말고."},{"k":"text","id":"V141_BEFORE_ISK_L03_K1_031_2","text":"회수한 원본은 여기 있어. 이 사람 이름도 적혀 있지. 각청, 네가 기억 못 하는 건 네 잘못이 아니지만, 이 사람이 거짓말을 한 것도 아니야."},{"k":"text","id":"V141_BEFORE_ISK_L03_K1_031_3","text":"……두 사람이 기억하고 있을 줄은 몰랐어. 그 보고 못 찾았으면 또 나만 아는 얘기로 끝났겠네. 고마워. 진짜로."}]},{"id":"ISK_L03_K2","entry":"ISK_L03_K2_001","items":[{"k":"keep","id":"ISK_L03_K2_001","text":"각청이 누구냐고 묻는 동안 나는 그녀의 등 뒤로 시선을 보냈다. 포대를 올려 두던 자리, 손바닥으로 허리를 두드리던 짐꾼의 모습이 차례로 떠올랐다. 각청이 살아 있다면 그 사람도 있을 수 있었다. 반가움이 생기기도 전에 몸이 먼저 움직였다."},{"k":"line","id":"PRO_L03K2_stranger_001","speaker":"나","text":"……각청? 너, 살아 있었어?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_002","speaker":"각청","text":"네가 누군지는 모르겠는데, 다짜고짜 살아 있었냐니. 칠성한테 하는 인사치곤 꽤 무례한걸?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_003","speaker":"나","text":"진짜 기억 안 나? 끈 풀린 포대. 같이 봤잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_004","speaker":"각청","text":"그 포대 일은 알아. 그런데 너랑 같이 있었다고? ……우선 무슨 일인지부터.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_005","speaker":"","text":"낯선 사람을 보는 눈빛에 다가가던 발이 멎었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_006","speaker":"나","text":"그럼 그 짐꾼은? 허리 아프다던 분. 나랑 같이 있었잖아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_007","speaker":"각청","text":"허리 아픈 짐꾼? 이 근처에서 본 기억은 없는데. 그 사람을 찾는 거야?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_008","speaker":"나","text":"응. 이름은 못 들었어. 얼굴은 알아.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_009","speaker":"각청","text":"그럼 마지막으로 본 곳부터.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_010","speaker":"나","text":"의례장. 모락스의 시신이 떨어지고…… 사람들이 전부 쓰러졌어. 너도, 그 사람도.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_011","speaker":"각청","text":"……제군의 시신이 떨어졌다고? 그런 건 기억에 없어.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_012","speaker":"나","text":"데리고 나오려고 했는데 못 했어. 네가 살아 있으니까, 그분도 혹시……","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L03K2_stranger_013","options":[{"label":"그분이 돌아왔는지 같이 찾아봐 줘.","id":"PRO_L03K2_stranger_014","items":[{"k":"line","id":"PRO_L03K2_stranger_015","speaker":"각청","text":"알겠어. 짐 맡겨 둔 곳으로 가자. 거기 병사라면 알 수도 있어.","map":"MAP_LIYUE_PLAINS"}]},{"label":"나부터 기억해 달라는 게 아니야. 그분만 찾아 주면 돼.","id":"PRO_L03K2_stranger_016","items":[{"k":"line","id":"PRO_L03K2_stranger_017","speaker":"각청","text":"널 기억 못 한다고 안 찾아 줄 것 같아? 가자.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"line","id":"PRO_L03K2_stranger_018","speaker":"","text":"각청이 앞장서 수레 사이로 길을 잡았다. 맡겨 둔 짐은 그대로였지만 그 곁에 짐꾼은 없었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_019","speaker":"각청","text":"이 사람과 같이 왔던 짐꾼, 어디 있는지 알아?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_020","speaker":"검수 병사","text":"아, 그때 그분이군요. 두 분이 함께 계셨던 건 기억합니다. 짐도 여기 있고요.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_021","speaker":"나","text":"그럼 그분은요? 돌아온 거 봤어요?","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_022","speaker":"검수 병사","text":"자리를 비우신 건 아는데…… 돌아오셨는지는 기억이 안 납니다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_023","speaker":"각청","text":"의례장에 다녀온 사람도 불러 줘. 제군의 시신이 떨어졌다는 말을 들은 적 있는지.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_024","speaker":"","text":"병사가 불러온 두 사람도 고개를 저었다.","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_025","speaker":"나","text":"짐은 여기 있는데. 사람만 어디로……","map":"MAP_LIYUE_PLAINS"},{"k":"line","id":"PRO_L03K2_stranger_026","speaker":"각청","text":"마지막으로 본 자리가 남았잖아. 같이 갈게.","map":"MAP_LIYUE_PLAINS"},{"k":"choice","group":"G_PRO_L03K2_stranger_027","options":[{"label":"그분 짐 잠깐 맡아 달라고만 해 줘. 돌아올 사람이 살아 있다면, 남의 짐까지 없어져 있으면 안 되잖아.","id":"PRO_L03K2_stranger_028","items":[{"k":"line","id":"PRO_L03K2_stranger_029","speaker":"각청","text":"원래도 인계가 안 끝난 물건이야. 주인 확인 없이 안 옮기게 해 둘게. 가자.","map":"MAP_LIYUE_PLAINS"}]},{"label":"그분이 오면 내가 찾았다고 말해 줘. 이름도 모르면서 아는 척하는 사람 있었다고.","id":"PRO_L03K2_stranger_030","items":[{"k":"line","id":"PRO_L03K2_stranger_031","speaker":"각청","text":"그렇게는 안 전해. 함께 의례에 갔던 사람이 돌아와 찾고 있다고 할 거야. 네가 싫어할 말을 굳이 보탤 필요는 없잖아.","map":"MAP_LIYUE_PLAINS"}]}]},{"k":"keep","id":"ISK_L03_K2_017","text":"짐이 놓인 곳을 마지막으로 보았다. 남겨 둔 물건이 기다리는 사람을 증명해 주지는 않았지만, 돌아와 다시 일할 자리가 있다는 것만은 지우고 싶지 않았다. 돌아갈 곳은 그 사람을 두고 온 의례장이었다."},{"k":"keep","id":"ISK_L03_K2_018","text":"옥경대로 올라가는 동안 각청에게 온 전갈은 상황을 더 이상하게 만들었다. 응광도 제군의 죽음을 기억하지 못했다. 병사의 말을 끊지 않으려고 턱에 힘을 주었다. 그 힘이 풀리면 다시 소리를 지르게 될 것 같았다."},{"k":"line","id":"PRO_L03K2_empty_001","speaker":"","text":"도착하자마자 짐꾼이 쓰러졌던 곳으로 갔다. 짐꾼도, 모락스의 거대한 몸도 보이지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_002","speaker":"나","text":"없어? 분명히 저기 있었잖아. 누가 옮긴 거야!","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_003","speaker":"현장 병사","text":"옮기라는 명령도, 인계받은 곳도 찾지 못했습니다. 여기 남은 사람들도 본 적이 없다고 합니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_004","speaker":"각청","text":"남은 사람만 물어본 거야? 그날 일하고 돌아간 사람들도 찾아봐.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_005","speaker":"나","text":"그 짐꾼도…… 없어. 여기엔 있을 줄 알았는데.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_006","speaker":"","text":"짐꾼을 끌어안았던 팔이 떨렸다. 각청이 병사에게 잠시 기다리라는 손짓을 했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_007","speaker":"나","text":"내가 여기 두고 갔어. 조금만 더 끌어 봤으면……","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_008","speaker":"각청","text":"그건 모르는 일이잖아. 어디까지 옮겼는지 보여 줘.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_009","speaker":"나","text":"……여기. 돌아오면 같이 짐 확인하자고 했는데.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_010","speaker":"","text":"각청이 몸을 낮춰 살폈다. 끌고 왔다는 방향까지 확인하고 병사를 불렀다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_011","speaker":"각청","text":"부두 검수 병사에게 사람 보내. 맡겨 둔 짐으로 신원 알아보고, 같이 일한 사람들도 찾아. 부상자 옮긴 곳도.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_012","speaker":"나","text":"이름도 못 들었어. 얼굴은 알아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_013","speaker":"각청","text":"그럼 넌 얼굴을 봐 줘. 이름은 검수 병사한테 물으면 돼. 방법이 없는 게 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_014","speaker":"","text":"병사를 보낸 각청은 내 곁에 남았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_015","speaker":"나","text":"……도와주는 거야? 내 말이 맞는지도 모르면서?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_016","speaker":"각청","text":"그러니까 확인하는 거야. 기억 안 난다고 네가 틀린 건 아니잖아. 사람 사라졌다는 말을 그냥 넘기는 칠성이 어디 있어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_017","speaker":"나","text":"찾으면 꼭 알려 줘. 다쳤으면 내가 갈게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_018","speaker":"각청","text":"알았어. 그때까진 내 옆에 있어. 지금 혼자 뛰어다닐 상태 아니야. 너 지금 서 있는 것도 비뚤어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_019","speaker":"","text":"각청은 보폭을 늦춰 걸음을 맞추고, 남은 병사에게 의례장 밖을 가리켰다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_020","speaker":"각청","text":"제군의 몸을 옮긴 흔적도 찾아봐. 큰 수레가 나갈 만한 길부터.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_empty_021","speaker":"","text":"각청이 짚은 길을 보다가, 내가 알던 이야기에서 제군의 몸을 옮겨 두었던 곳이 떠올랐다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K2_empty_022","options":[{"label":"타르탈리아야. 저걸 가져가는 걸 본 건 아닌데…… 그 사람이 황금옥으로 가. 신의 심장을 찾으러. 응광을 만나야겠어. 이번에는 진짜로.","id":"PRO_L03K2_empty_023","items":[{"k":"line","id":"PRO_L03K2_empty_024","speaker":"각청","text":"우인단 집행관. 황금옥은 살피게 할게. 그런데 왜 그렇게 예상하는지는 설명해야 해. 이름 하나로 응광 앞에 세울 순 없어.","map":"MAP_LIYUE_HARBOR"}]},{"label":"황금옥부터 확인해 줘. 내가 아는 이야기대로면 타르탈리아가 신의 심장을 찾으러 갈 수 있어. 시신 옮긴 걸 봤다는 건 아니야.","id":"PRO_L03K2_empty_025","items":[{"k":"line","id":"PRO_L03K2_empty_026","speaker":"각청","text":"예상이랑 목격을 나눈 건 알겠어. 황금옥은 살피게 할게. 근거는 응광 앞에서 설명해.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K2_empty_027","speaker":"나","text":"설명할게. 모락스의 계획하고, 그 뒤에 일어날 일을 알아. 산에 가서 류운차풍진군한테도 먼저 말했어. 그분한테 확인하면 돼. 이번에는 나만 기억하는 말이 아닐 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K2_030","text":"각청이 병사를 보내는 사이, 계단 아래에서 숨 가쁜 발소리가 올라왔다. 행추와 연비였다. 두 사람은 의례장에 없었다. 그러니 기억도 그대로였다."},{"k":"line","id":"PRO_L03K2_adepti_001","speaker":"","text":"그 순간 공기가 달라졌다. 병사들이 한꺼번에 자세를 바로잡았고, 높은 곳에 선 그림자가 내려왔다. 류운차풍진군이었다. 산의 문밖에서 목이 쉬도록 불렀던 상대가 이번에는 먼저 찾아왔다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_002","speaker":"류운차풍진군","text":"이 몸에게 확인하면 된다더니, 정작 이 몸이 와도 인사할 숨은 남겨 두지 않았군. 자네가 말한 사람들 가운데 이 여인이 있었지?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_003","speaker":"나","text":"네. 살아 있어요. 그런데 저를 기억 못 하고, 응광도 모락스가 쓰러진 걸 기억 못 한답니다. 시신은 없어졌고요. 같이 갔던 짐꾼은 아직 못 찾았어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_004","speaker":"류운차풍진군","text":"살아 있는 사람을 보고 다른 살아 있을 사람을 찾는 것이 잘못은 아니지. 다만 이 몸도 없는 사람을 이 자리에 곧장 데려다줄 수는 없네. 제군께 관한 일은 칠성과 직접 이야기하겠네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_005","speaker":"","text":"선인들을 보며 처음으로 산길에서 한 일이 헛되지 않았다는 것을 실감했다. 짐꾼을 데려오지 못했지만 이야기는 전달했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_006","speaker":"각청","text":"자리를 마련하겠습니다. 황금옥에도 사람을 보냈고요. 확인되지 않은 일을 확인된 것처럼 말씀드릴 수는 없지만, 없는 기억을 핑계로 기다리고 있지는 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_007","speaker":"류운차풍진군","text":"그 마음가짐은 좋네. 그렇다면 길을 여는 데 오래 걸릴 이유도 없겠지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_008","speaker":"","text":"소는 선인들 뒤에서 나를 잠깐 살폈다. 망서 객잔에서와 같은 간결한 눈길이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_009","speaker":"나","text":"황금옥에 가려면 응광을 먼저 만나야겠어요. 바다 쪽도 함께 봐 주실 수 있습니까? 제가 타르탈리아 막는 동안 다른 쪽이 먼저 터지면 저 혼자 뛰어간 의미가 없어져요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_adepti_010","speaker":"소","text":"바다는 우리가 보겠다. 네가 안다는 상대에게만 눈을 두지 마. 도망칠 길이 막혔는지도 봐라. 사람 하나 더 두고 돌아왔다고 후회할 필요는 없으니.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K2_adepti_011","options":[{"label":"사람 하나 더는 저 말씀이시죠? 다들 저를 배달할 짐처럼 다루시는데, 솔직히 지금은 안내가 있는 쪽이 좋습니다.","id":"PRO_L03K2_adepti_012","items":[{"k":"line","id":"PRO_L03K2_adepti_013","speaker":"류운차풍진군","text":"자네는 짐짝이라는 비유를 좀처럼 놓지 못하는군. 그 짐은 말이 너무 많다는 흠도 있겠어. 따라오게. 다리가 풀리면 허세 부리지 말고 멈췄다고 말하고.","map":"MAP_LIYUE_HARBOR"}]},{"label":"제가 먼저 말을 꺼내겠습니다. 응광이 화를 내면 중간에서 들어만 주세요. 혼자 우기는 사람으로 끝내고 싶지 않습니다.","id":"PRO_L03K2_adepti_014","items":[{"k":"line","id":"PRO_L03K2_adepti_015","speaker":"류운차풍진군","text":"화내는 사람 하나 견디지 못하면서 제군의 계획을 논하러 갈 셈인가. 말할 것은 말하게. 이 몸이 들은 부분은 이 몸이 대답할 테니.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K2_adepti_016","speaker":"","text":"응광의 답은 오래 걸리지 않았다. 그사이 황금옥으로 보낸 병사가 되돌아와 안쪽 연락이 끊기고 우인단이 드나들었다고 보고했다. 각청은 즉시 대피와 외곽 통제를 지시했다. 내가 짐작하던 장소가 실제로 문제가 벌어진 장소가 되어 가고 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K2_047","text":"군옥각으로 이동하는 동안 아래쪽의 물자 대기 구역을 찾았다. 멀리서는 수레도 포대도 구별되지 않았다. 누군가의 하루를 닷새나 묶어 둔 짐이 이 높이에서는 점 하나도 되지 않는다는 사실이 마음에 들지 않았다. 응광에게 말할 때 그 사람을 큰 계획의 작은 피해로 줄여 부르지 않기로 했다."},{"k":"line","id":"PRO_L03K2_palace_001","speaker":"","text":"응광은 내가 앉을 의자를 미리 비워 두었다. 흙 묻은 옷 때문에 망설이자 그녀는 손으로 자리를 가리켰다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_002","speaker":"응광","text":"내 앞에 오기 위해 먼저 산을 다녀온 손님이네. 평소라면 기다린 값부터 물었을 텐데 오늘은 시간이 없겠지. 제군 일과 황금옥 일, 모두 네가 꺼낸 이야기라고 들었어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_003","speaker":"나","text":"그 전에 직접 물을게요. 의례에서 모락스의 시신이 떨어진 거, 정말 기억이 없습니까? 당신이 떠난 뒤에 사람들이 죽었어요. 저하고 같이 온 짐꾼도요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_004","speaker":"응광","text":"기억에 없어. 그 시간이 매끄럽게 이어지지 않는다는 건 나도 알아. 함께 간 이의 행방은 찾았니?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_005","speaker":"나","text":"아직요. 짐만 그대로 있어요. 그러니까 지금부터 하는 말이 맞든 틀리든 그분 찾는 일도 계속해 주세요. 큰일 앞에서 작은 일 됐다고 넘어가지 말고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_006","speaker":"응광","text":"사람 하나를 찾는 일과 항구를 지키는 일은 서로 깎아야 값이 맞는 거래가 아니야. 각청이 이미 사람을 붙였다고 들었어. 보고는 계속 받겠어. 이제 네가 여기까지 와서 하려던 말을 들어 보자.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_007","speaker":"","text":"찾았다는 약속도 위로도 아니었다. 그러나 처음으로 내 부탁을 손에서 놓을 수 있었다. 누군가가 계속 들고 있겠다고 말했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_008","speaker":"나","text":"제가 알고 있던 이야기에서 모락스의 죽음은 계획이었습니다. 리월이 제군 없이 설 수 있는지 보기 위한 거였어요. 타르탈리아가 황금옥에서 신의 심장을 찾고, 뜻대로 되지 않으면 오셀을 불러옵니다. 저는 그걸 막으려고 해요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_009","speaker":"각청","text":"제군이 우리를 시험한다는 뜻이야? 기억이 끊겨서 누구 말을 믿을지도 흔들리는 사람들이 있어. 그 고통까지 계획이라면 못 받아들여.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_010","speaker":"나","text":"그건 아니야. 내가 알던 이야기엔 기억상실도, 사람들이 죽는 일도 없었어. 그래서 나도 화가 나. 아는 줄 알고 왔는데, 그 사이에서 사람이 죽었는데, 큰 계획이 있겠지 하고 기다릴 순 없잖아. 아는 위험이라도 먼저 막자는 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_011","speaker":"류운차풍진군","text":"산에서도 그와 같이 말했네. 제군의 계획이라는 말과 자신이 설명하지 못하는 참사를 나누어 이야기했지. 이 몸이 그 해석을 모두 받아들였다는 뜻은 아니네. 허나 오셀을 경계하라는 말을 듣고도 손 놓고 있을 이유는 없었어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_012","speaker":"응광","text":"내가 궁금한 건 네가 왜 그 이야기의 다음 일을 믿느냐는 거야. 앞에서 틀린 게 이렇게 많았다면 타르탈리아도 네 예상대로 움직이지 않을 수 있어. 그를 막는 데 사람을 보내는 동안 바다가 먼저 움직이면?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_013","speaker":"나","text":"그래서 선인들께 바다를 부탁한 겁니다. 저는 황금옥으로 가고요. 전부 제 말 한 줄에 걸라고는 못 해요. 하지만 저기서 위험을 막을 기회가 있는데, 어긋날 수도 있다는 이유로 기다리는 건 못 하겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_014","speaker":"","text":"응광은 지도의 해안선을 짚었다. 류운차풍진군은 바다를 맡을 선인들의 움직임을, 각청은 사람을 빼낼 순서를 짚었다. 서로의 판단을 다 좋아하지는 않아도 손은 같은 지도 위에서 움직였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_015","speaker":"응광","text":"황금옥은 확인할 거야. 네가 가겠다는 것도 들었고. 그 전에, 네가 아는 이야기에서 오셀은 어떻게 막았니? 그 얼굴을 보니 답이 마음에 안 드는 모양인데.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_016","speaker":"나","text":"군옥각입니다. 제가 아는 대로 가면 오셀을 막으려고 이걸 포기해야 해요. 바다에 떨어뜨려야 합니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_017","speaker":"나","text":"처음 온 사람이 집을 버리라고 하는 게 얼마나 뻔뻔한지 알아요. 그래도 말 안 하고 가면 더 비겁할 것 같아서요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_018","speaker":"","text":"방의 소리가 멎었다. 응광은 바로 답하지 않았다. 창 너머로 항구가 펼쳐져 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_019","speaker":"응광","text":"네가 그 이야기를 알았다고 내 군옥각에 대한 권리까지 얻은 건 아니야. 그렇지만 손해 날 수 있다는 말을 듣기 싫어서 숨기는 사람도 아니지. 내가 알고 싶은 건 그 순간까지 뭘 해 볼 수 있느냐는 거야. 떨어뜨리기 전까지는 아주 쓸모 있는 곳이거든.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K2_palace_020","options":[{"label":"마지막 수가 있다고 다른 방법을 덜 찾으면 안 된다는 거죠. 그래서 타르탈리아 쪽을 먼저 끊고 싶어요. 그게 되면 여기서 무슨 차를 마실지도 고민할 수 있겠죠.","id":"PRO_L03K2_palace_021","items":[{"k":"line","id":"PRO_L03K2_palace_022","speaker":"응광","text":"차는 나중에 골라. 지금은 비울 사람과 남을 사람부터 정할 거야. 언제 포기할지는 내가 판단해. 누구 이야기 속 장면을 완성하려고 버리지는 않아.","map":"MAP_LIYUE_HARBOR"}]},{"label":"다른 방법을 먼저 찾죠. 마지막 수단이 있다는 이유로 사람을 옮기거나 바다를 늦출 기회까지 줄이고 싶지는 않아요.","id":"PRO_L03K2_palace_023","items":[{"k":"line","id":"PRO_L03K2_palace_024","speaker":"응광","text":"그래. 할 수 있는 일을 다 세어 본 뒤에야 마지막이라는 말을 쓸 수 있겠지. 언제 포기할지는 내가 판단해. 누구 이야기 속 장면을 완성하려고 버리지는 않아.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K2_palace_025","speaker":"류운차풍진군","text":"좋은 건물은 쓰임이 많지. 바다의 경계는 맡겠네. 인간들의 준비가 늦어져 싸움터에 사람이 남는 일은 없도록 하게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_026","speaker":"각청","text":"그건 저희가 하겠습니다. 다만 대피 중인 길 위로 싸움이 밀려오면 즉시 알려 주세요.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L03K2_palace_027","options":[{"label":"그분을 찾으면 제가 도망친 얘기를 먼저 하셔도 됩니다. 변명 안 할게요. 대신 제가 다시 돌아와 찾았다는 것도 같이 전해 주세요.","id":"PRO_L03K2_palace_028","items":[{"k":"line","id":"PRO_L03K2_palace_029","speaker":"응광","text":"전할 수 있게 되면 함께 전하겠어. 다만 네가 지금도 살아 있다는 말까지 붙일 수 있도록 행동해. 상대에게 할 말을 남겨 두고 사라지는 건 거래를 끝내는 좋은 방법이 아니니까.","map":"MAP_LIYUE_HARBOR"}]},{"label":"나중에 일이 끝나면 이 방에서 아무 일 없는 얘기도 한 번 하고 싶어요. 밥 늦게 나왔다고 불평하는 정도로요. 지금은 그게 되게 사치스럽네요.","id":"PRO_L03K2_palace_030","items":[{"k":"line","id":"PRO_L03K2_palace_031","speaker":"응광","text":"그런 불평은 평소에도 충분히 들어. 그래도 네가 직접 돌아와서 한다면 한 번쯤은 시간을 내 주지. 그때는 귀한 방에 들어왔다는 이유로 억지 칭찬부터 늘어놓지 말고.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L03K2_palace_032","speaker":"나","text":"좋아요. 저는 타르탈리아를 막으러 황금옥으로 가겠습니다. 제군의 시신이 왜 사라졌는지 단서도 찾을 수 있으면 찾을게요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_palace_033","speaker":"응광","text":"황금옥 바깥에 병사를 남겨 둘게. 네가 가져올 답은 네가 돌아와야 나한테 닿으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K2_079","text":"응광은 다음 지시를 내리기 전 내가 일어서는 모습을 지켜보았다. 다리에 힘이 늦게 들어가 잠깐 의자 끝을 붙잡았지만 넘어지지 않았다. 류운차풍진군이 무슨 말을 하려다 멈췄고, 나는 굳이 못 본 척하지 않았다. 아직 몸을 챙기라는 잔소리를 들을 사람이 있다는 사실이 나쁘지 않았다."},{"k":"keep","id":"ISK_L03_K2_080","text":"군옥각에서 내려온 뒤 각청은 황금옥으로 가는 호위 병사들에게 나를 인계했다. 물자 구역의 답도 하나 도착해 있었다. 짐꾼은 아직 찾지 못했고 그의 물건은 그대로 보관 중이었다."},{"k":"line","id":"PRO_L03K2_water_001","speaker":"나","text":"고마워. 못 찾았다는 말이 이렇게 아픈데, 그래도 아무 말 없이 잊히는 것보다는 낫네. 돌아오면 그것부터 물어볼 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_002","speaker":"각청","text":"물어봐. 내가 바쁜 척해도 붙잡고 물어. 닷새는 못 돌려주지만 아저씨 찾는 건 내가 해. 오늘부터 내 일이야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_003","speaker":"나","text":"네 일 많잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_004","speaker":"각청","text":"하나 더 늘었다고 안 죽어. 너야말로 황금옥 가서 죽지 마. 남의 일 늘리지 말고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_005","speaker":"나","text":"……그 말투, 진짜 그대로다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_006","speaker":"각청","text":"뭐가.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_007","speaker":"나","text":"아니. 좋은 뜻이야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_008","speaker":"","text":"그 말을 듣자 각청에게 예전 일을 다시 증명하려던 마음을 조금 내려놓았다. 그녀는 닷새를 돌려줄 수 없었지만 새로운 일을 맡을 수 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_009","speaker":"나","text":"그럼 나도 내 몫 하러 갈게. 남의 짐 대신 드는 재주는 없는데 남의 일에 끼어드는 재주만 자꾸 느네. 끝까지 끼어들고 돌아올 테니까 저쪽 자리 하나는 비워 둬.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L03K2_water_010","speaker":"각청","text":"자리는 있어. 그리고 할 일이 생겼다고 안 다치는 몸이 된 건 아니야. 무리하면 물러서.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L03_K2_086","text":"각청이 해안의 대피 상황을 보러 돌아서는 동안 황금옥 쪽 병사들이 앞장섰다. 익숙한 포대와 수레들이 길옆으로 물러나 있었다. 이번에는 사람이 먼저 빠져나간 자리를 지나고 있다는 것을 확인했다."},{"k":"keep","id":"ISK_L03_K2_087","text":"황금옥으로 향하는 길은 생각보다 길었다. 누구도 짐꾼처럼 걸음이 짧다고 놀리지 않았다. 그 침묵이 더 낯설어 나는 길의 모양을 외우기 시작했다. 돌아올 때 헤매지 않는 것부터 하기로 했다."},{"k":"line","id":"PRO_L03K2_golden_001","speaker":"","text":"황금옥 앞에서는 일꾼들이 밖으로 빠져나오고 있었다. 안쪽에서 충격이 난 뒤 주 출입문이 비틀려 관리 통로로 우회했다는 말이었다. 길목을 보았다. 큰 수레를 세우면 문을 가릴 위치였다. 닷새 동안 물자 구역에서 익힌 감각이 엉뚱한 곳에서 도움이 되었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_002","speaker":"나","text":"저 수레는 문 앞에서 옆으로 빼 주세요. 사람이 급하게 나오면 바퀴에 걸려요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_003","speaker":"","text":"수레가 비켜나자 그 뒤에 서 있던 회색 외투 둘이 드러났다. 우인단. 일꾼들을 내보내 준 게 아니라, 들어갈 사람을 고르고 있었던 것이다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_004","speaker":"우인단 병사","text":"여기서부터는 집행관의 영역이다. 돌아가.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_005","speaker":"나","text":"저 집행관한테 할 말이 있어서 왔는데요. 약속은 안 했지만.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_006","speaker":"우인단 병사","text":"약속 없는 손님은 받지 않는다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_007","speaker":"나","text":"그쪽도 리월에 약속하고 온 건 아니잖아요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_008","speaker":"","text":"대답 대신 얼음이 튀었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"combat","id":"PRO_L03K2_golden_009","group":"EG_FATUI_PATROL","text":"황금옥 관리 통로를 막은 우인단 전투조. 안으로 들어가려면 뚫어야 한다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_010","speaker":"","text":"마지막 병사가 무릎을 꿇었다. 호위 병사들이 달려와 그를 끌어냈다. 통로는 비어 있었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_011","speaker":"나","text":"저는 안으로 들어가겠습니다. 타르탈리아가 나오면 앞을 막고 싸우려 하지 말고, 사람들 쪽으로 못 가게만 떨어져 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_012","speaker":"호위 병사","text":"안에서 길이 막히면 무리해서 넘어가지 마십시오. 돌아올 수 있는 틈이 있을 때 돌아오셔야 합니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K2_091","text":"주머니에 무엇이 있는지 무의식중에 확인하다 손을 뗐다. 설산에서 본 구슬은 여기 없었다. 꺼내서 앞길을 바꾸어 줄 물건도 없었다. 무기를 잡고 통로로 들어갔다."},{"k":"line","id":"PRO_L03K2_golden_013","speaker":"","text":"넓은 공간에 이르자 발소리가 길게 돌아왔다. 모락스의 시신은 보이지 않았다. 대신 타르탈리아가 서 있었다. 내가 상상한 상대는 무언가를 찾고 있거나 뜻대로 되지 않아 불쾌해하고 있을 것 같았다. 눈앞의 남자는 빈 공간에서 기다리는 데 익숙해 보였다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_014","speaker":"타르탈리아","text":"들어오기 전에 바깥을 제법 정리했더군. 나갈 때도 그 길을 쓸 생각인가 봐. 준비성 좋은 손님은 싫지 않아. 날 찾아온 거지?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L03K2_golden_015","options":[{"label":"그래. 제군의 시신 찾으러 온 거면 헛걸음한 것 같네. 나도 없어서 여기까지 왔거든. 신의 심장 찾겠다고 다른 일 벌일 생각이면 그것부터 접고.","id":"PRO_L03K2_golden_016","items":[{"k":"line","id":"PRO_L03K2_golden_017","speaker":"타르탈리아","text":"찾으러 온 사람이 둘이라. 그럼 너는 나에게서 뭘 얻으려고 싸울 셈이지? 이미 없다는 걸 확인한 물건? 아니면 네가 생각한 순서대로 흘러가지 않는 일의 답?","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"나도 시신을 못 찾아서 왔어. 네가 가져갔다면 어디 있는지 묻겠지만, 아니라면 여기서 무슨 계획을 세웠는지 말해.","id":"PRO_L03K2_golden_018","items":[{"k":"line","id":"PRO_L03K2_golden_019","speaker":"타르탈리아","text":"내 계획과 네가 찾는 답을 한꺼번에 묻는군. 그럼 너는 나에게서 뭘 얻으려고 싸울 셈이지? 이미 없다는 걸 확인한 물건? 아니면 네가 생각한 순서대로 흘러가지 않는 일의 답?","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L03K2_golden_020","speaker":"","text":"미간을 좁혔다. 시신과 신의 심장을 동시에 들은 사람의 얼굴치고는 놀라움이 너무 적었다. 그는 이곳에 온 이유를 따지는 대신 내가 어디까지 버틸지 보고 있는 것처럼 보였다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_021","speaker":"나","text":"질문 잘하네. 그럼 내 질문에도 답해 봐. 너, 지금 싸우고 싶어? 내가 아는 너라면 여기까지 온 상대 보고 좀 더 들떠야 할 것 같은데. 아까부터 내가 뭘 할지만 기다리고 있잖아.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_022","speaker":"타르탈리아","text":"네가 아는 나라는 말이 재미있군. 나는 아직 네 이야기를 많이 듣지 못했는데. 그렇게 확신한다면 먼저 보여 줘. 내가 어떤 반응을 할지도 알고 있을 테니까.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_023","speaker":"","text":"한 발 움직이자 타르탈리아의 시선은 무기가 아니라 발이 놓인 곳으로 잠깐 내려갔다. 전투에서 위치를 보는 것은 이상한 일이 아니었다. 그런데 그 짧은 시선이 이상하게 오래 남았다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_024","speaker":"나","text":"밖에 네 사람들 쓰러져 있어. 안쪽 연락도 끊겼다던데, 찾아볼 생각은 없어? 난 여기까지 오는 길에 남의 짐꾼 한 사람 못 찾았다는 얘기만 들었는데도 계속 걸렸거든.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_025","speaker":"타르탈리아","text":"그래서 네가 여기 온 건 아니잖아. 못 찾은 사람 얘기로 시간을 벌려고? 네가 막겠다고 한 일을 막아 봐. 다른 사람은 네가 돌아간 다음에 찾아도 늦지 않을지 모르지.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_026","speaker":"","text":"손에 힘이 들어갔다. 도발하고 흡족해하는 기색도 없었다. 그저 아픈 지점을 짚고 다음 반응을 기다렸다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L03K2_golden_027","options":[{"label":"그 사람 얘기는 네가 입에 올릴 농담거리가 아니야. 나도 내가 아는 너를 앞세워 방심하지 않을게. 지금 내 앞에서 하는 짓만 보고 상대하겠어.","id":"PRO_L03K2_golden_028","items":[{"k":"line","id":"PRO_L03K2_golden_029","speaker":"타르탈리아","text":"그편이 너에게도 편하겠지. 기억해 둔 상대와 눈앞의 상대를 번갈아 보면 손이 늦어질 테니까. 이제 네가 멈추려는 일을 행동으로 보여 줘.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"그래, 돌아가서 찾아야지. 그러려면 너하고 말만 주고받을 수는 없겠네. 문 앞 수레 치워 달라고 한 이유가 도망갈 때 걸리기 싫어서만은 아니거든.","id":"PRO_L03K2_golden_030","items":[{"k":"line","id":"PRO_L03K2_golden_031","speaker":"타르탈리아","text":"돌아갈 자리를 남겨 둔 건 좋은 생각이야. 그 자리를 다시 밟을 수 있을지는 네가 얼마나 움직이느냐에 달렸겠지. 시작하자.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L03K2_golden_032","speaker":"","text":"타르탈리아가 손을 움직였고 물빛 날이 번쩍였다. 바닥을 박차며 몸을 피했다. 칼날이 지나간 기둥에서 돌가루가 떨어졌다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K2_110","text":"황금옥 내부에서 타르탈리아와의 전투가 시작된다."},{"k":"line","id":"PRO_L03K2_golden_033","speaker":"","text":"몇 번이나 넘어질 뻔하며 뒤로 물러났다. 내가 디딘 금 간 돌판을 타르탈리아도 피하려 몸을 틀었다. 무기를 고쳐 쥐자 손끝이 아팠다. 멋있는 싸움은 아니었다. 아직 여기서 끝낼 수 없다는 고집만 남아 있었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_034","speaker":"나","text":"그만해. 네가 뭘 하려고 했든 여기서 끝내. 나는 돌아가서 찾을 사람이 있어.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_035","speaker":"","text":"타르탈리아는 답하지 않았다. 시선이 내 무기 끝에서 벗어났지만, 무엇을 보았는지 확인하기 전에 몸이 앞으로 나갔다. 마지막 틈이라고 판단했다. 결정타를 날리려 팔을 뻗는 순간, 발밑의 감각이 통째로 내려앉았다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_036","speaker":"","text":"기둥의 장식이 떨어지며 바닥을 부쉈고, 천장을 가로지르는 들보가 뒤틀렸다. 출구 방향을 기억해 몸을 틀었다. 바깥의 수레를 치워 두었다는 생각이 스쳤다. 길은 열어 두었다. 그러나 그 길에 닿을 시간이 남은 것은 아니었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L03K2_golden_037","speaker":"나","text":"황금옥 무너져요! 문에서 떨어져! 들어오지 마요!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L03_K2_116","text":"무너진 돌이 어깨를 때렸고 다리가 꺾였다. 이어 떨어진 들보가 몸을 덮쳤다. 타르탈리아는 먼지에 가려 보이지 않았다. 남의 몸을 들어 올리려다 놓쳤던 팔이 이번에는 제 몸 위의 무게를 밀어내지 못했다. 황금옥이 내려앉으며 나를 잔해 아래에 묻었다."},{"k":"keep","id":"ISK_L03_K2_END","text":"내가 무너진 황금옥에 깔리는 순간에서 멈춘다. 구조 여부와 부상 상태는 아직 밝혀지지 않는다."}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L03_K2_030_0","text":"자네! 살아 있었군. 물자 구역에 짐만 남았다고 해서 얼마나…… 아저씨는? 아저씨는 같이 안 왔나?"},{"k":"text","id":"V141_BEFORE_ISK_L03_K2_030_1","text":"행추, 숨 좀 쉬고 말해. 각청, 이 사람은 내가 알아. 고운각에서 회수한 인계표에 이 사람과 짐꾼 둘 다 적혀 있어. 네가 기억 못 하는 건 네 잘못이 아니지만, 이 사람이 꾸며 낸 것도 아니야."},{"k":"text","id":"V141_BEFORE_ISK_L03_K2_030_2","text":"……둘이 이 사람을 안다는 거지. 알겠어. 지우지 않아. 찾을 사람을 늘릴게. 너는 선인께 무슨 말을 했는지 계속 설명해 줘."},{"k":"text","id":"V141_BEFORE_ISK_L03_K2_030_3","text":"……행추, 연비. 아저씨는 못 찾았어. 내가 두고 왔어. 찾았다는 소식 오면 나부터 불러 줘. 밥 먹었는지도 물어봐 주고."}]},{"id":"ISK_L04_K1","entry":"ISK_L04_K1_001","items":[{"k":"keep","id":"ISK_L04_K1_001","hold":true,"text":"눈을 떴는지 감고 있는지 한동안 알 수 없었다. 입 안에 먼지가 씹혔고 숨을 들이마실 때마다 어깨가 아팠다. 들보는 기울어진 석재에 받쳐 있었고, 그 아래 생긴 비좁은 틈에 등이 눌려 있었다. 숨이 드나들 공간이 있다는 사실부터 붙잡았다."},{"k":"line","id":"PRO_L04K1_rubble_001","speaker":"","text":"팔을 비틀어 손목을 만졌다. 박동이 있었다. 각청에게서 찾지 못했던 것을 내 몸에서 찾자 안심과 죄책감이 함께 올라왔다. 타르탈리아가 움직이는 소리는 들리지 않았다. 대신 멀리서 돌 구르는 소리와 사람의 목소리가 났다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_002","speaker":"나","text":"여기 사람 있어요! 관리 통로로 들어간 사람, 아직 살아 있어요!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_003","speaker":"호위 병사","text":"들립니다! 위치 찾았으니 계속 소리 지르지 마십시오. 앞이 막혔습니다. 손은 움직입니까?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K1_rubble_004","options":[{"label":"손은 움직여요. 그런데 위에 들보가 걸려 있어요. 돌부터 막 치우지 마요. 이거 내려앉으면 대답 못 해요.","id":"PRO_L04K1_rubble_005","items":[{"k":"line","id":"PRO_L04K1_rubble_006","speaker":"호위 병사","text":"바깥에서도 들보가 보입니다. 먼저 받침을 넣겠습니다. 안에서는 손 닿는 작은 돌만 옆으로 밀어 주십시오.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"어깨하고 허벅지가 눌렸어요. 손은 움직이고 다리 감각도 있어요. 어떻게 하면 돼요?","id":"PRO_L04K1_rubble_007","items":[{"k":"line","id":"PRO_L04K1_rubble_008","speaker":"호위 병사","text":"그 정도면 됩니다. 억지로 빼지 마십시오. 받침 넣는 동안 손 닿는 작은 돌만 옆으로 밀어 숨 쉴 틈을 넓혀 두세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"thru","id":"ISK_L04_K1_001"},{"k":"line","id":"PRO_L04K1_rubble_009","speaker":"","text":"틈으로 빛이 들어왔을 때 병사는 곧장 팔을 잡아당기지 않았다. 숨을 쉬는지 묻고, 몸이 어디에 걸렸는지 살핀 뒤 다른 이들과 무게를 나누었다. 나를 찾는 목소리가 실제로 돌아왔다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_010","speaker":"나","text":"옆에 있던 남자는요? 붉은 머리, 회색 옷. 저랑 싸우다 같이 안에 있었어요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_011","speaker":"호위 병사","text":"나오는 사람은 보지 못했습니다. 지금 열린 틈에서도 당신뿐입니다. 안쪽 전체를 확인한 건 아닙니다. 먼저 당신부터 꺼냅니다. 고개 이쪽으로.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L04_K1_008","text":"몸이 잔해에서 빠져나오자 바람이 젖은 옷 안으로 들어왔다. 시원하다고 생각하기도 전에 통증이 밀려왔다. 무릎을 세우려다 옆으로 기울었고 병사가 받쳐 주었다. 무너진 황금옥은 내가 들어갔던 건물과 다른 모양이었다. 어디에도 타르탈리아는 보이지 않았다."},{"k":"line","id":"PRO_L04K1_rubble_012","speaker":"군의관","text":"제 말을 들으면서 손가락을 펴 보세요. 이번엔 발. 어깨와 허벅지가 심하게 눌렸지만 지금 보이는 출혈은 막을 수 있습니다. 숨이 더 차거나 가슴이 아프면 바로 말하세요. 멀쩡히 말한다고 안쪽까지 괜찮은 건 아닙니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K1_rubble_013","options":[{"label":"치료받을게요. 혼자 멀쩡하다고 우겨 봐야 걷다가 또 업혀 갈 것 같네요.","keep":"ISK_L04_K1_010","items":[{"k":"line","id":"PRO_L04K1_rubble_014","speaker":"군의관","text":"그 말이면 됩니다. 아픈 곳은 참지 말고 바로 말하세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"keep","id":"ISK_L04_K1_011","text":"병사들이 구조 지점 옆으로 구호 물자를 가져왔다. 군의관은 내 동의를 듣고 처치 자리를 마련했다. 어떻게 살아남았는지를 다 설명할 수는 없어도, 지금 치료할 사람이 이곳에 있다는 것은 분명했다."},{"k":"line","id":"PRO_L04K1_rubble_015","speaker":"","text":"군의관은 찢어진 옷을 걷어 상처를 씻고 눌러 지혈한 뒤 붕대를 감았다. 혼자 서 보겠다는 말을 삼켰다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K1_rubble_016","options":[{"label":"저 살아 있는 거 맞죠? 웃긴 질문인 건 아는데, 요 며칠 제가 확인한 것들이 자꾸 뒤집혀서요.","id":"PRO_L04K1_rubble_017","items":[{"k":"line","id":"PRO_L04K1_rubble_018","speaker":"군의관","text":"숨 쉬고, 대답하고, 피 납니다. 여기까지는 제가 확인했습니다. 살아 있다는 것과 뛰어도 된다는 건 다른 말이고요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_019","speaker":"나","text":"피 나는 걸 확인 항목에 넣는 건 처음 보네요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_020","speaker":"군의관","text":"죽은 사람은 피가 안 납니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_021","speaker":"나","text":"……아, 네.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"붕대 감는 솜씨가 너무 익숙해서 고마우면서도 좀 무섭네요. 조금만 덜 아프게 안 될까요?","id":"PRO_L04K1_rubble_022","items":[{"k":"line","id":"PRO_L04K1_rubble_023","speaker":"군의관","text":"아프다고 말하는 건 잘하셨습니다. 조금 조절하죠. 다만 출혈 막을 만큼은 감아야 합니다. 이 악물고 괜찮다고만 하는 환자보다는 낫군요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"keep","id":"ISK_L04_K1_019","text":"처치가 끝나기 전에 바다 쪽에서 소리가 왔다. 바람 소리와 달랐다. 먼 하늘이 검게 꺾이고, 수평선 위로 거대한 물줄기가 솟았다. 보고하러 달려온 병사의 얼굴을 본 군의관이 설명을 멈췄다. 바다에 나타난 것이 항구 쪽으로 움직이고 있었다."},{"k":"line","id":"PRO_L04K1_rubble_024","speaker":"나","text":"오셀이야. 막으려고 했는데 결국 나왔어.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_025","speaker":"나","text":"타르탈리아는…… 아니, 지금 그걸 찾고 앉아 있을 때가 아니지. 군옥각으로 가야 해요. 응광한테 제가 살아 나왔고 황금옥은 무너졌다고 전해 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_026","speaker":"군의관","text":"걸을 수 있다는 확인이 전투 허락은 아닙니다. 혼자 달려가면 도중에 다시 업어 와야 합니다. 병사들과 같이 가세요. 호흡이 바뀌면 멈추고요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K1_rubble_027","speaker":"","text":"황금옥을 돌아보았다. 내가 기억하는 타르탈리아는 싸움을 즐겼다. 안에서 만난 상대는 끝나는 순간만 기다리는 듯했다. 의문은 살아서 나중에 붙잡아야 했다. 병사가 내민 팔을 붙들었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L04_K1_023","text":"호위대는 구조 지점을 표시하고 추가 수색 인원에게 인계했다. 안전한 길까지 부축받고, 완만한 구간에서는 직접 걸었다. 먼 바다에서 솟아난 형체를 보았다. 이야기 속에서 알고 있던 이름이 실제 도시보다 크게 일어섰다. 미리 경고했다는 사실이 그 크기를 줄여 주지는 않았다."},{"k":"keep","id":"ISK_L04_K1_024","text":"항구로 돌아오는 길에는 대피한 사람들이 이어졌다. 병사들이 어느 쪽을 비워 달라고 외치면 사람들은 움직였다. 그 작은 질서가 무너진 도시를 붙들고 있었다."},{"k":"line","id":"PRO_L04K1_harbor_001","speaker":"","text":"사람들이 빠져나간 거리 한쪽에서 비명이 났다. 빈 가게였다. 닫힌 문이 안쪽에서 부서지고, 보물 사냥단 셋이 자루를 메고 나왔다. 바다가 일어선 날에도 남의 물건부터 챙기는 사람은 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_002","speaker":"보물 사냥단","text":"비켜. 다리도 성치 않은 게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_003","speaker":"나","text":"그 말은 맞는데요. 손은 멀쩡해요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_004","speaker":"","text":"옆의 호위 병사가 창을 내렸다. 나도 무기를 들었다. 다친 어깨가 당겼다. 참을 만했다.","map":"MAP_LIYUE_HARBOR"},{"k":"combat","id":"PRO_L04K1_harbor_005","group":"EG_TREASURE_PATROL","text":"대피로 비어 버린 거리를 터는 보물 사냥단 습격조. 지나가는 길이니 비켜 세울 수밖에 없다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_006","speaker":"","text":"자루가 바닥에 떨어지고 사냥단은 골목으로 흩어졌다. 병사가 자루를 가게 안으로 던져 넣고 문을 닫았다. 다시 걸었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_007","speaker":"","text":"한참 뒤 방어 인원이 오가는 항구의 집결지에 닿았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_008","speaker":"각청","text":"살아 돌아왔네. 황금옥 무너졌다는 보고가 먼저 와서 사람을 더 보내려던 참이야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_009","speaker":"각청","text":"왜 그렇게 서 있어. 다친 쪽에 힘 빼. 보고는 앉아서 해도 들려.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_010","speaker":"나","text":"돌아오면 기다리겠다며. 지키러 왔는데 시작부터 자세 지적이네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_011","speaker":"나","text":"타르탈리아하고 싸웠고, 끝낼 수 있을 것 같던 순간에 건물이 무너졌어. 그 사람은 못 찾았대. 시신도 안에 없었어. 바다 막는 쪽에 나도 보태 줘.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_012","speaker":"각청","text":"어디에 붙일지는 네 몸부터 보고. 여기서 쓰러지면 널 지키느라 또 사람이 빠져. 팔 들었을 때 어디가 아픈지 말해.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_harbor_013","speaker":"","text":"팔을 천천히 들자 붕대가 당겼다. 각청은 그 범위를 보고 칼을 크게 휘두르는 자리 대신 방어선 안쪽을 가리켰다. 부상자를 옮기고, 장치로 이어지는 길을 막는 자리였다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_harbor_014","options":[{"label":"뒤쪽도 괜찮아. 앞으로 나가야 도움 된다는 고집은 황금옥 밑에 놓고 왔어.","id":"PRO_L04K1_harbor_015","items":[{"k":"line","id":"PRO_L04K1_harbor_016","speaker":"각청","text":"잘 놓고 왔네. 올라가는 동안 난간 잡고, 손에 힘 빠지면 옆 사람 불러. 살려 놓은 사람 다시 잃고 싶지 않아.","map":"MAP_LIYUE_HARBOR"}]},{"label":"솔직히 앞에 서고 싶었는데, 네 말대로 할게. 물통 돌려주러 온 사람이 또 깔리면 체면이 없잖아.","id":"PRO_L04K1_harbor_017","items":[{"k":"line","id":"PRO_L04K1_harbor_018","speaker":"각청","text":"체면 때문이라도 말 들으면 됐어. 난간 잡고, 손에 힘 빠지면 옆 사람 불러. 살려 놓은 사람 다시 잃고 싶지 않아.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K1_031","text":"방어 지점으로 가는 통로가 열렸다. 일반 대피 인원과 방어에 합류하는 인원이 갈라졌고, 나는 각청이 지정한 조를 따라 움직였다."},{"k":"keep","id":"ISK_L04_K1_032","text":"군옥각에 오르는 길은 전과 달랐다. 아래에서는 마지막 대피 인원이 길을 건넜고, 위에서는 선인들의 힘이 바다를 향해 뻗었다. 발을 디뎠을 때 그곳은 차를 마시며 지도를 펼쳤던 집이 아니라 도시 앞에 놓인 방어 진지가 되어 있었다."},{"k":"line","id":"PRO_L04K1_osial_001","speaker":"응광","text":"황금옥에서 바로 내 집까지 무너뜨리러 온 건 아니겠지? 살아 돌아온 건 환영이야. 환영할 형편이 아닐 뿐이지. 네 덕에 대피를 먼저 시작했어. 이제 그 시간을 더 벌어야 해.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K1_osial_002","options":[{"label":"앞 건물은 제가 부순 걸로 계산하지 말아 주세요. 다음 건물도 가능하면 남기고 싶습니다.","id":"PRO_L04K1_osial_003","items":[{"k":"line","id":"PRO_L04K1_osial_004","speaker":"응광","text":"달라진 건 이미 있어. 아래에 남을 뻔한 사람들이 빠져나갔어. 하지만 상대가 작아지진 않았네. 선인들이 전면을 맡는 동안 뒤로 들어오는 적을 막아 줘.","map":"MAP_OSIAL_BATTLE"}]},{"label":"어디를 맡으면 앞에서 싸우는 사람들 손이 덜 묶일까요? 제가 안다던 순서대로 가지도 않으니, 지금 필요한 일부터 듣겠습니다.","id":"PRO_L04K1_osial_005","items":[{"k":"line","id":"PRO_L04K1_osial_006","speaker":"응광","text":"그렇게 물어 주는 편이 지금은 훨씬 도움이 돼. 선인들이 전면을 맡는 동안 뒤로 들어오는 적을 막아 줘. 그들이 힘을 돌리면 바다 쪽이 비어.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K1_osial_007","speaker":"","text":"류운차풍진군이 고개를 돌렸다. 깔렸다 나온 몸으로 또 높은 곳에 섰다는 말을 하려는 듯하다가, 다친 어깨와 옆에 선 병사를 보고 말을 줄였다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_008","speaker":"류운차풍진군","text":"살아 돌아온 것은 잘했네. 그렇다고 기둥 아래서 버텼다는 이유로 파도 앞에서도 버틸 몸이 되었다고 착각하지 말게. 장치 뒤쪽 연결로를 지키게.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_009","speaker":"나","text":"알겠습니다. 저 거대한 머리랑 눈 마주칠 생각은 없어요. 크기 비교해 보니까 협상할 여지가 없더라고요.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_010","speaker":"","text":"바다에서 솟은 물줄기가 방어의 빛을 때렸다. 허리를 낮추고 난간을 잡았다. 뒤쪽으로 스며든 습격자들이 좁은 연결로를 향해 달려왔다. 각청이 앞의 공격을 끊어 냈고, 나는 내가 맡은 틈으로 다가오는 적을 향해 무기를 들었다.","map":"MAP_OSIAL_BATTLE"},{"k":"keep","id":"ISK_L04_K1_040","text":"오셀에 맞선 공동 방어가 이어지는 동안, 군옥각 후방 연결로를 지키는 방어전이 시작된다."},{"k":"line","id":"PRO_L04K1_osial_011","speaker":"","text":"연결로에 밀려들던 적의 마지막 공격이 끊겼다. 길은 지켰다. 그러나 바다의 형체가 다시 몸을 일으키자 방어 장치 위로 균열이 번졌고, 선인들이 힘을 밀어 넣던 자리가 통째로 흔들렸다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_012","speaker":"각청","text":"뒤쪽 인원부터 내려보내! 장치 붙들려고 남지 마! 너도 그 부상자 데리고 안쪽으로!","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_013","speaker":"나","text":"이 사람 다리에 힘이 안 들어가. 반대쪽 어깨 잡아 줘!","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_014","speaker":"","text":"병사 하나와 부상자를 사이에 두고 옮겼다. 팔이 떨렸지만 놓지 않았다. 각청이 다가와 무게를 받아 주자 숨이 터졌다. 전에는 손에 남은 사람을 놓고 도망쳤다. 지금은 누군가가 그 무게를 나누어 들었다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_015","speaker":"","text":"응광은 무너진 방어 지점과 바다를 번갈아 보았다. 류운차풍진군은 장치를 다시 이어도 오래 버티기 어렵다고 말했다. 응광은 창 안쪽을 한 번 보았다. 급히 챙겨 나온 문서와 물건들. 그녀는 더 가져오라는 명령을 내리지 않았다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_016","speaker":"응광","text":"결정할 때네. 군옥각을 포기하겠어. 바다에 떨어뜨려 그 틈을 막을 거야. 남은 사람을 모두 옮겨. 내 물건 때문에 누가 마지막까지 여기 남는 일은 없게.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K1_osial_017","options":[{"label":"정말 다른 방법이 없는 겁니까? 제가 먼저 말한 건 알아요. 그런데 당신이 지켜 온 걸 직접 보니까, 알고 있었으니 괜찮다는 말은 못 하겠네요.","id":"PRO_L04K1_osial_018","items":[{"k":"line","id":"PRO_L04K1_osial_019","speaker":"응광","text":"괜찮을 필요 없어. 아깝고, 화나고, 다시 지을 생각 하면 벌써 손이 많이 가. 그래도 아래 도시를 남길 수 있다면 선택은 분명해. 네가 말했기 때문이 아니라 내가 지금 보고 정한 거야. 그러니 내 표정 살필 시간에 사람을 옮겨.","map":"MAP_OSIAL_BATTLE"}]},{"label":"……알겠습니다. 제가 먼저 꺼낸 얘기라서 지금은 아무 말도 안 하는 게 예의 같네요.","id":"PRO_L04K1_osial_020","items":[{"k":"line","id":"PRO_L04K1_osial_021","speaker":"응광","text":"그 예의는 받아 두지. 하지만 네가 말했기 때문에 하는 결정이 아니야. 내가 지금 보고 정한 거야. 내 표정 살필 시간에 사람을 옮겨.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K1_osial_022","speaker":"류운차풍진군","text":"이 몸이 길을 열겠네. 소, 남은 자들을 살피게. 이 건물을 떨어뜨리는 것만으로 끝내서는 안 되니, 닿는 순간까지 빈틈을 남기지 말게.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_023","speaker":"","text":"각청은 마지막 명단을 확인하는 사람 곁에서 직접 머릿수를 세었다. 난간에 걸린 천을 걷어 발이 걸리지 않게 한 뒤, 뒤를 돌아보며 따라오는 사람을 재촉했다. 비 새는 천막을 둘이 들어 올리던 일이 떠올랐다. 이번에는 물을 빼는 대신 집을 두고 떠나야 했다.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K1_osial_024","options":[{"label":"천막에서는 왼쪽 당기라더니 오늘은 오른쪽으로 빠지라네. 알았어, 이번에도 네 말 들을게. 대신 너 마지막까지 남아서 혼자 확인하지 마.","id":"PRO_L04K1_osial_025","items":[{"k":"line","id":"PRO_L04K1_osial_026","speaker":"각청","text":"천막 얘기는 모르겠지만, 네가 먼저 가면 나도 바로 따라가. 여기 남은 사람은 확인했어. 자꾸 뒤돌아보다가 발 헛디디지 마.","map":"MAP_OSIAL_BATTLE"}]},{"label":"남은 사람 없지? 한 번 놓고 나온 사람을 자꾸 다시 찾는 버릇이 생겨서 그래. 너 살아 있는 건 이번엔 안 놓쳐.","id":"PRO_L04K1_osial_027","items":[{"k":"line","id":"PRO_L04K1_osial_028","speaker":"각청","text":"남은 인원 확인했어. 네가 모든 사람을 혼자 기억해야 하는 자리 아니야. 병사들도, 나도 보고 있어. 발판 건너. 바로 뒤에 있어.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K1_osial_029","speaker":"","text":"발판이 기울자 몸을 낮췄다. 소가 마지막으로 주변을 살핀 뒤 남은 이들을 이끌었고, 선인들의 힘이 부서지는 가장자리에서 사람들을 떼어 냈다. 발밑에 있던 군옥각이 멀어졌다. 응광은 마지막까지 바다를 보며 힘을 내렸고, 거대한 건물이 빛을 안은 채 아래로 향했다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K1_osial_030","speaker":"","text":"바다와 하늘 사이가 눈부시게 터졌다. 차가 놓여 있던 방, 지도가 펼쳐졌던 탁자, 손님에게 비워 주었던 의자가 모두 빛과 물 아래로 사라졌다. 솟아 있던 거대한 형체도 그 아래로 가라앉았다.","map":"MAP_OSIAL_BATTLE"},{"k":"keep","id":"ISK_L04_K1_059","text":"안전한 지점에 내려선 뒤에도 다리가 흔들렸다. 군옥각은 돌아오지 않았다. 사람들은 환호하다가 누가 없는지 확인했고, 누군가는 앉아서 울었다. 응광을 찾았다. 그녀는 자신이 잃은 쪽보다 사람들이 모인 쪽을 먼저 보고 있었다."},{"k":"keep","id":"ISK_L04_K1_060","text":"해안의 감시 인원이 바다의 거대한 위협이 가라앉았다는 보고를 전했다. 군옥각을 희생해 마지막 틈을 막았고, 선인과 칠성이 함께 지켜 낸 도시가 뒤에 남았다."},{"k":"line","id":"PRO_L04K1_osial_031","speaker":"나","text":"일 끝나면 같이 밥 한 번 먹고 싶어요. 식탁은 잃었어도 같이 앉을 자리까지 없어진 건 아니라고 생각하고 싶어서요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_osial_032","speaker":"응광","text":"밥 한 끼 먹을 곳도 못 남겼으면 오늘 선택은 실패였겠지. 다행히 아래에 도시가 남았네. 너는 먼저 치료부터 받아. 손님을 식탁에서 쓰러지게 하는 건 내 취향이 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_osial_033","speaker":"","text":"웃으려다 갈비뼈 근처가 당겨 얼굴을 찡그렸다. 각청이 그 표정을 놓치지 않았다. 그녀는 군의관을 불렀고, 나는 이번에는 바다를 핑계로 일어서지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_064","text":"대피소의 치료 구역에서 군의관은 젖은 붕대를 풀었다. 멍이 번진 부위를 다시 살피고 상처를 씻었다. 침상에 누워 처음으로 천장이 움직이지 않는다는 사실을 오래 바라보았다."},{"k":"line","id":"PRO_L04K1_rest_001","speaker":"군의관","text":"다시 벌어진 곳은 처치했습니다. 오늘은 쉬십시오. 밤에 숨이 가빠지면 곁의 사람을 부르세요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_rest_002","speaker":"나","text":"걷는 범위를 남이 정해 주는 생활에 아주 익숙해지고 있네요. 도시 구해야 한다는 핑계도 다 썼으니 얌전히 누워 있을게요. 물 좀 가까이 놔 주실 수 있어요?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_rest_003","speaker":"","text":"그날 밤은 짧게 끊겼다. 돌이 쏟아지는 소리에 놀라 깼다고 생각했지만 옆 침상의 사람이 물그릇을 떨어뜨린 소리였다. 손목을 찾았다가 멈췄다. 방 안에는 숨 쉬는 사람이 여럿 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_068","text":"이틀 동안 치료와 휴식이 이어졌다. 통증과 피로는 남았지만 다시 일어서서 식사를 하러 갈 수 있었다. 그동안 해안의 급한 정리는 끝났고, 항구는 피해 구역을 제외한 통행을 순서대로 되돌리고 있었다."},{"k":"line","id":"PRO_L04K1_rest_004","speaker":"","text":"각청이 찾아왔을 때 나는 침상 가장자리에 앉아 밥을 먹고 있었다. 그녀는 빈 그릇부터 확인했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_rest_005","speaker":"각청","text":"오늘부터 리월항 일반 봉쇄를 해제해. 황금옥 잔해랑 해안 파손 구역만 계속 막아 둘 거야. 멀리 가지 말라는 건 군의관 지시니까 내가 취소 못 해 주고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_rest_006","speaker":"나","text":"보고 없이 뛰어나갈 생각 없으니까 수상한 환자 보듯 보지 마.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_rest_007","options":[{"label":"그런데 너, 오늘 내가 뭘 먹었는지는 기억해 줄 수 있지? 나중에 똑같은 것만 가져오지 말라고 미리 부탁하게.","id":"PRO_L04K1_rest_008","items":[{"k":"line","id":"PRO_L04K1_rest_009","speaker":"각청","text":"오늘 일은 기억해. 네가 빈 그릇 앞에 두고 다음 메뉴부터 요구한 것도. 네가 말한 닷새는 아직 안 떠올라. 그걸 대신 채워 주진 못해도, 네가 얄미운 말 하는 건 지금부터 충분히 남길 수 있겠네.","map":"MAP_LIYUE_HARBOR"}]},{"label":"오늘 먹은 거하고 걸은 거리는 같이 기억해 두자. 지난 닷새 억지로 떠올려 달라는 건 아니야. 지금부터 남길 수 있는 건 남기고 싶어서.","id":"PRO_L04K1_rest_010","items":[{"k":"line","id":"PRO_L04K1_rest_011","speaker":"각청","text":"그건 할 수 있어. 오늘 내가 본 거랑 아직 안 떠오르는 걸 따로 말해 줄게. 네가 빈 그릇 앞에 앉아 있던 것부터 시작이네.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K1_073","text":"그 대답을 듣고 소리 없이 웃었다. 각청도 아주 잠깐 입가를 움직였다. 둘이 같은 일을 기억하며 웃는 순간이 새로 생겼다. 사라진 닷새를 돌려받은 것은 아니었다. 그래도 잃은 시간만 세느라 그 뒤에 생긴 시간을 놓칠 필요는 없었다."},{"k":"keep","id":"ISK_L04_K1_074","text":"며칠 전 지도를 펼쳤던 이들이 이번에는 땅 위의 임시 집무 공간에 모였다. 응광은 남의 책상에서도 자기 물건을 쓰는 것처럼 자연스러웠고, 류운차풍진군은 낮은 처마를 잠깐 올려다보았다. 소는 열린 문 바깥에 서 있었다."},{"k":"line","id":"PRO_L04K1_council_001","speaker":"류운차풍진군","text":"군옥각이 사라졌다고 회의할 자리까지 없어지지는 않았군. 이 몸은 칠성의 판단을 가볍게 보지 않겠네. 허나 함께 막아 냈다고 바다와 산의 경계를 풀어도 된다는 뜻은 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_002","speaker":"각청","text":"필요할 때 도움을 청하는 것과 결정을 전부 맡기는 건 다르다고 생각합니다. 저희가 맡은 곳에서 이상이 생기면 숨기지 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_003","speaker":"응광","text":"같은 탁자에 앉았다고 생각이 같아질 필요는 없죠. 서로 지키려는 걸 직접 봤으니 다음 대화는 조금 덜 돌아가도 되겠네요.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_council_004","options":[{"label":"저는 산길을 덜 돌아가면 좋겠습니다. 그때 문 앞까지 올라가다가 다리가 먼저 포기할 뻔했거든요.","id":"PRO_L04K1_council_005","items":[{"k":"line","id":"PRO_L04K1_council_006","speaker":"류운차풍진군","text":"이 몸이 모든 방문객의 식사를 맡을 생각은 없네. 다만 제대로 소식을 가져온 사람이 문밖에서 쓰러져도 좋다는 뜻도 아니지. 다음에는 숨 고를 여유가 있을 때 올라오게.","map":"MAP_LIYUE_HARBOR"}]},{"label":"다음에 급히 전할 일이 생기면 문 앞에서 쓰러지기 전에 부를 방법부터 알려 주세요. 소식 전하러 왔다가 제가 구조 대상이 되는 건 서로 번거롭잖아요.","id":"PRO_L04K1_council_007","items":[{"k":"line","id":"PRO_L04K1_council_008","speaker":"류운차풍진군","text":"자기 숨부터 살피겠다는 뜻이라면 제법 배웠군. 길은 이 몸이 일러 두겠네.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_council_009","speaker":"","text":"농담 뒤에는 의례장의 이야기가 남았다. 각청도 응광도 모락스가 쓰러지던 순간을 되찾지 못했고, 나는 사람들의 실제 죽음을 기억했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_010","speaker":"나","text":"바다가 잠잠해진 건 다행인데, 제가 의례에서 본 일은 그대로예요. 각청이 죽었던 것도, 사람들이 한꺼번에 쓰러진 것도요. 없던 일로 넘기지는 말아 주세요. 황금옥에서 만난 타르탈리아도 제가 알던 성격과 달랐습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_011","speaker":"응광","text":"전투가 끝났다고 조사를 끝내진 않아. 다만 살아 있는 사람들한테 네가 본 죽음을 날마다 증명하라고 할 수도 없지. 남은 문제는 따로 추적할 거야. 다시 물어야 할 때는 사람을 보내겠어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_012","speaker":"소","text":"네 기억을 버릴 필요는 없어. 그렇다고 그 기억 때문에 지금 숨 쉬는 사람을 못 보면 안 된다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_council_013","speaker":"","text":"소의 말을 듣고 각청 쪽을 보았다. 그녀는 고개를 끄덕여 주지 않았다. 이미 오늘의 자신으로 옆에 앉아 있었다. 그걸로 충분했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_001","speaker":"","text":"집무 공간을 나온 뒤 길가의 긴 의자에 잠깐 앉았다. 멀리서 한 남자가 걸어왔다. 단정한 옷차림과 낮은 목소리. 종려였다. 알고 있던 이름을 처음 실제로 부르게 되는 순간이었다. 손을 흔들지는 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_002","speaker":"종려","text":"부상이 있는데도 오늘 여러 사람을 만났다고 들었네. 왕생당의 객경, 종려라고 하네. 잠깐 함께 앉아도 괜찮겠나?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_003","speaker":"나","text":"앉으세요. 성함은 알고 있습니다. 처음 뵙는데 안다고 말하는 게 여기 와서 버릇이 됐네요. 어떤 분인지 안다고 생각했다가 몇 번 크게 틀렸으니, 이번에는 직접 듣겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_004","speaker":"종려","text":"남의 이야기로 아는 것과 직접 마주한 것은 서로를 완전히 대신하지 못하지. 자네가 선인들에게 전한 경고가 도움이 되었다고 들었네. 다만 자네도 예상하지 못한 일을 많이 겪은 모양이군.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_zhongli_005","options":[{"label":"도움이 됐다고는 하는데, 결국 군옥각은 사라졌어요. 황금옥도요. 사람들 먼저 옮긴 게 다행인 건 알아요. 그래도 안다는 말에 너무 기대 버린 것 같네요.","id":"PRO_L04K1_zhongli_006","items":[{"k":"line","id":"PRO_L04K1_zhongli_007","speaker":"종려","text":"남은 사람들을 사소한 결과로 여기지 말게. 한 사람의 하루가 이어지는 일은 그 사람에게 결코 작은 일이 아니네. 그렇다고 잃은 것을 아쉬워하지 말라는 뜻도 아니야. 둘을 함께 보아야 다음 선택이 가벼워지지 않겠지.","map":"MAP_LIYUE_HARBOR"}]},{"label":"알고 있던 결말하고 비교하느라 오늘 실제로 도운 사람들을 자꾸 빠뜨리는 것 같아요. 그렇다고 잃은 걸 잘됐다고 할 수도 없고요.","id":"PRO_L04K1_zhongli_008","items":[{"k":"line","id":"PRO_L04K1_zhongli_009","speaker":"종려","text":"하나를 인정하기 위해 다른 하나를 지울 필요는 없네. 지켜 낸 것과 잃은 것을 함께 보아야 다음 선택이 가벼워지지 않겠지.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_zhongli_010","speaker":"","text":"종려는 군옥각이 사라진 하늘을 바라보았다. 제군이라는 호칭을 길 한가운데 던지면 곁을 지나가는 사람들의 이야기도 바뀔 수 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_011","speaker":"나","text":"따로 묻고 싶은 게 있어요. 제가 알고 있는 당신 일이요. 여기서 소리 높여 꺼내진 않겠습니다. 조용히 얘기할 자리 있어요?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_012","speaker":"종려","text":"마침 약속된 일을 마무리하러 가는 길이네. 북국은행에서 만나지. 답할 수 있는 것도, 없는 것도 있을 걸세. 그 차이는 그곳에서 말해 주겠네.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_101","text":"북국은행으로 가는 길에는 다시 가게를 여는 사람들이 있었다. 은행 안으로 들어가자 종려와 시뇨라가 먼저 보였다. 그 옆에 서 있는 타르탈리아를 본 순간 발이 멈췄다. 황금옥의 먼지 속으로 사라졌던 얼굴이 너무 멀쩡하게 그곳에 있었다."},{"k":"line","id":"PRO_L04K1_zhongli_013","speaker":"시뇨라","text":"몬드의 그 방해꾼이잖아. 여기까지 기어왔어?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_014","speaker":"시뇨라","text":"끼어들 생각이면 지금 말해. 참아 줄 생각은 없으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_015","speaker":"나","text":"안 끼어듭니다. 당신들 계약을 제가 뒤집을 수 있다고 생각하지도 않아요. 끝난 뒤에 묻고 싶은 것만 묻겠습니다. 저쪽에 멀쩡하게 서 있는 사람한테도요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_016","speaker":"","text":"타르탈리아가 그 시선을 받고 눈썹을 올렸다. 낯선 적을 경계하는 것과 자신을 아는 상대를 흥미로워하는 기색이 섞여 있었다. 황금옥에서 보았던, 끝을 기다리는 듯한 눈길과 달랐다. 무기에 손을 댔다가 거두었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_017","speaker":"종려","text":"얼음의 여왕과 맺은 계약에 따라 약속한 것을 이행하겠네. 나의 신의 심장은 자네가 받아 전하게. 대가와 조건 역시 계약에 따라 지켜지기를 바라네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_018","speaker":"","text":"종려가 내민 신의 심장을 시뇨라가 받았다. 알고 있던 일이 눈앞에서 행동으로 확인되고 있었다. 거리에서는 여전히 물건 값을 흥정하는 소리가 들렸다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_019","speaker":"타르탈리아","text":"결국 나는 바깥에서 한참 뛰고, 마지막 얘기는 두 사람이 다 알고 있었던 거네요. 종려 씨, 숨겨 둔 패가 많은 건 알겠는데 이번엔 설명을 듣고 싶어지는군요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_020","speaker":"시뇨라","text":"네가 알아야 할 만큼은 알았어. 결과도 봤고. 여기서 네 기분까지 풀어 주는 건 내 일이 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_021","speaker":"","text":"타르탈리아는 불쾌한 듯 웃었다. 자신만 모른 일에 짜증을 내면서도 대화를 놓치지 않는 반응. 그 모습에 더 불편해졌다. 이제야 내가 기억하던 타르탈리아와 닮아 보였기 때문이다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_022","speaker":"나","text":"종려 씨. 왜 그런 계약을 맺은 겁니까? 신의 심장을 넘길 만큼 뭘 받았어요?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_023","speaker":"종려","text":"모두 답할 수는 없네. 계약에는 비밀을 지킨다는 약속도 들어 있어. 자네가 겪은 위험을 가볍게 여겨서 말을 아끼는 것은 아니네.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_zhongli_024","options":[{"label":"위험은 밖에서 몸으로 치르고, 값이 어떻게 정해졌는지는 못 듣는다는 게 참 기분 나쁘네요. 약속 어기라고 떼쓰진 않을게요. 그래도 제가 납득했다고 듣진 마세요.","id":"PRO_L04K1_zhongli_025","items":[{"k":"line","id":"PRO_L04K1_zhongli_026","speaker":"종려","text":"그러겠네. 침묵을 받아들였다는 것과 그 침묵에 만족한다는 것은 다른 일이니. 말할 수 없는 것을 다른 말로 꾸며 납득을 구하지도 않겠네.","map":"MAP_LIYUE_HARBOR"}]},{"label":"그럼 약속 하나만 받을게요. 계약 때문에 말 못 하는 부분을 제 기억 탓으로 돌리지는 마세요. 요즘 제 기억만 남는 일이 너무 많아서요.","id":"PRO_L04K1_zhongli_027","items":[{"k":"line","id":"PRO_L04K1_zhongli_028","speaker":"종려","text":"자네가 기억한다고 말한 일을 내 편의를 위해 지우지는 않겠네. 다만 자네의 기억과 내가 말할 수 있는 사실 사이의 빈칸을 채웠다고 가장할 수도 없지.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_zhongli_029","speaker":"","text":"시뇨라는 받은 물건을 확인하고 몸을 돌렸다. 타르탈리아는 내 다친 팔을 살피다가 먼저 말을 걸었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_030","speaker":"타르탈리아","text":"나한테도 할 말 있다고 했지. 그런데 그 표정은 처음 만난 사람한테 인사하는 표정이 아닌데. 그 상처하고 내가 무슨 관계야?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_031","speaker":"나","text":"황금옥에서 너하고 싸웠어. 네가 밀리고, 내가 끝내려는 순간 건물이 무너졌지. 나는 돌에 깔렸고 병사들이 꺼냈어. 넌 사라졌고. 기억해?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_032","speaker":"타르탈리아","text":"황금옥에서 너랑? 잠깐, 그건 내가 아는 일이 아닌데. 그 시간이 매끄럽지 않은 건 맞아. 하지만 너랑 칼 맞댄 기억은 없어. 이렇게 적의를 받는데 재미있게 싸웠다는 기억도 없다니, 나한테도 손해네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_033","speaker":"","text":"손이 굳었다. 각청에게 들었던 말이 다른 얼굴에서 돌아왔다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_zhongli_034","options":[{"label":"그때 너는 싸움이 즐거워 보이지 않았어. 끝나는 순간만 기다리는 것 같았고. 그런데 지금은 내가 알던 얼굴을 하네. 이걸 기억 못 한다는 말 하나로 넘기라고?","id":"PRO_L04K1_zhongli_035","items":[{"k":"line","id":"PRO_L04K1_zhongli_036","speaker":"타르탈리아","text":"넘기라고는 안 했어. 나도 누가 내 이름으로 네게 그런 기억을 남겼는지 알고 싶으니까. 그래도 없는 기억을 있는 척하진 않아. 칼로 확인하고 싶으면 상처부터 낫고 와.","map":"MAP_LIYUE_HARBOR"}]},{"label":"황금옥에서 우리가 싸웠다는 말 자체가 처음이야, 아니면 그때만 기억이 끊긴 거야? 둘을 같은 말로 넘기고 싶진 않아.","id":"PRO_L04K1_zhongli_037","items":[{"k":"line","id":"PRO_L04K1_zhongli_038","speaker":"타르탈리아","text":"그 시간만 끊겨 있어. 기억 못 한다는 말로 네가 겪은 일까지 없애려는 건 아니야. 그렇다고 맞장구칠 수도 없고. 칼로 확인하고 싶으면 상처부터 낫고 와.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_zhongli_039","speaker":"나","text":"칼로 알 수 있는 일이었으면 황금옥에서 끝났겠지. 됐어. 기억나는 게 생기면 숨기지 마. 나도 본 걸 거짓말로 바꿔서 편해질 생각 없으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_040","speaker":"타르탈리아","text":"그 정도면 얘기할 여지는 있네. 다 낫고 나면 한 판 하자. 잊은 싸움으로만 평가받는 건 재미없거든.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_zhongli_041","speaker":"나","text":"환자 앞에서 재경기 예약부터 잡는 거 봐. 지금은 예약 안 받아. 내 다음 목표는 밥집까지 안 업히고 가는 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_128","text":"종려는 두 사람의 말을 듣고 있었다. 내가 돌아보자 그는 고개를 아주 조금 저었다. 모든 현상을 한마디로 설명할 답을 내놓지는 않았다. 계약을 아는 사람과 지금 벌어진 이상을 전부 아는 사람은 같지 않을 수 있었다."},{"k":"line","id":"PRO_L04K1_depart_001","speaker":"","text":"은행 밖으로 나오자 햇빛이 눈에 들어왔다. 도시를 구한 뒤에는 답이 이어질 줄 알았다. 손에 남은 것은 더 정확해진 질문들이었다. 모락스의 계획만으로 설명되지 않는 죽음, 살아 돌아온 사람들의 빈 기억, 내가 알던 사람과 달랐던 상대.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_002","speaker":"나","text":"이나즈마로 가 보자. 다음에 무슨 일이 있는지 안다고 자신할 생각은 없어. 그래도 이 세계가 내가 알던 이야기와 어디서 달라지는지 보려면 계속 움직여야지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_003","speaker":"나","text":"이번엔 '아는데'라는 말부터 좀 줄이고.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_131","text":"그 결심을 입 밖에 낸 뒤 곧장 항구로 뛰어가지 않았다. 치료소에 돌아가 군의관에게 장거리 이동을 준비하고 싶다고 말할 차례였다. 목적지를 정하는 것과 당장 갈 수 있다는 것은 다르다는 정도는 이제 몸으로 알았다."},{"k":"line","id":"PRO_L04K1_depart_004","speaker":"나","text":"이나즈마로 갈 생각입니다. 바로는 아니고, 배편 알아보는 동안 치료 계속 받을게요. 중간에 건물 무너지는 일정은 제가 안 잡겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_005","speaker":"군의관","text":"그 일정은 앞으로도 잡지 마십시오. 이틀마다 상처 확인하고, 무거운 짐은 한쪽 어깨에 걸지 마세요. 항해 날짜가 정해지면 그 전에 다시 오십시오.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_006","speaker":"","text":"각청은 해안 통행을 확인하러 가는 길에 나를 만났다. 처음처럼 내가 누구인지 묻지 않았다. 오늘 약속한 사람이 어느 자리에 앉아 있는지 알고 찾아왔다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_007","speaker":"나","text":"나, 다음엔 이나즈마로 가려고. 그리고 진한테 내가 살아 있고 리월 위기는 일단 막았다고 알려야겠어. 치료 중이라는 말도 넣고. 다음 소식이 수색 요청이면 너무 미안하잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_008","speaker":"각청","text":"길드 정규 전달편에 맡기면 돼. 네가 본 이상한 일은 짧게 따로 적어. 추측까지 진이 본 사실처럼 쓰진 말고.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_137","text":"치료소 책상에서 편지를 적었다. 살아남았고 치료 중이라는 소식, 바다의 위기를 막았다는 일, 다음 목적지를 알아보고 있다는 계획이었다. 길드 창구에 맡겼고 몬드행 전달편에 접수되었다는 답을 받았다."},{"k":"line","id":"PRO_L04K1_depart_009","speaker":"각청","text":"배편은 남십자 함대 쪽에도 물어봐. 만나면 황금옥에서 살아 나왔다는 얘기부터 자랑하지 마. 네 몸 상태를 과장하면 배에 태우는 사람도 곤란해져.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_depart_010","options":[{"label":"알았어. 선장한테는 얌전히 소개부터 할게. 너한테는…… 고마웠어. 내가 기억하는 닷새의 너한테도, 그걸 기억 못 하면서 다시 도와준 지금의 너한테도.","id":"PRO_L04K1_depart_011","items":[{"k":"line","id":"PRO_L04K1_depart_012","speaker":"각청","text":"둘을 따로 세워 두지 말라니까. 그 고맙다는 말은 지금 내가 들었어. 그걸로 됐어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_013","speaker":"각청","text":"돌아오면 그냥 이름 불러. 그때 내가 \"우리 어디서 만났지?\" 하면 그땐 진짜 화내도 돼.","map":"MAP_LIYUE_HARBOR"}]},{"label":"돌아오면 그냥 이름 부를게. 네가 모르는 닷새를 내가 매번 설명하면서 처음부터 다시 만나는 건 이제 그만하고 싶어.","id":"PRO_L04K1_depart_014","items":[{"k":"line","id":"PRO_L04K1_depart_015","speaker":"각청","text":"그래. 설명 안 해도 돼. 그 닷새는 네가 갖고 있어. 나는 오늘부터 생긴 걸 갖고 있을게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_016","speaker":"각청","text":"그때 내가 \"우리 어디서 만났지?\" 하면 그땐 진짜 화내도 돼.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K1_depart_017","speaker":"","text":"한동안 답하지 않고 웃었다. 돌아오라는 명령도, 머무르라는 부탁도 아니었다. 다시 만났을 때 서로 아는 사람으로 서고 싶다는 말이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K1_142","text":"다음 날 항구에 마련된 남십자 함대의 연락 장소로 갔다. 선장은 아직 만나지 못했고, 창구의 선원 역시 초면이었다. 이나즈마 방면의 출항 안내를 기다리는 사람들 곁에 서자 다음 여정을 준비하고 있다는 실감이 났다."},{"k":"line","id":"PRO_L04K1_depart_018","speaker":"나","text":"각청한테 남십자 함대 쪽에 물어보라고 소개받았습니다. 이나즈마 방면 운항하고 승선 상담 부탁드려요. 지금 치료 중이라 출발 전에 몸 상태도 다시 볼 거고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_019","speaker":"남십자 선원","text":"신청은 전하겠습니다. 선장님이 직접 물으실 겁니다. 출발 날짜가 정해진 걸로 생각하진 마십시오. 연락은 치료소로 드리면 됩니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_020","speaker":"나","text":"네. 당분간 거기 있어요. 돌아갈 곳을 알려 두는 게 생각보다 중요하더라고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_021","speaker":"","text":"치료소에 돌아오자 칠성 쪽의 정산 담당자가 기다리고 있었다. 끝낸 일의 몫을 실제로 돌려받는 자리였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K1_depart_022","speaker":"정산 담당자","text":"지급액은 1,800모라, 영웅의 경험 두 개와 모험가의 경험 세 개입니다. 리월 방어에 참여하고 위험을 전달한 공적에 대한 정산입니다. 확인하신 뒤 받아 주십시오.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K1_depart_023","options":[{"label":"확인했습니다. 1,800모라에 영웅의 경험 두 개, 모험가의 경험 세 개. 받을게요. 다음엔 돈 쓸 일이 치료보다 밥하고 배편 쪽에 많았으면 좋겠네요.","keep":"ISK_L04_K1_149","items":[{"k":"line","id":"PRO_L04K1_depart_024","speaker":"정산 담당자","text":"기록에 남겼습니다. 다음 몫도 밥값으로 쓰이기를 바라겠습니다.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K1_150","text":"치료소 창 너머의 바다 위에는 군옥각이 없었다. 잠깐 그 하늘을 올려다본 뒤 침상 곁의 여행 준비 메모로 눈을 내렸다. 이나즈마로 떠날 준비는 시작되었고, 아직 풀리지 않은 질문들은 함께 가지고 갈 것이었다."},{"k":"keep","id":"ISK_L04_K1_END"}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L04_K1_001_0","text":"바깥을 향해 손을 뻗었다. 큰 들보는 건드리지 않았다. 손끝에 닿는 작은 돌부터 옆으로 밀었다."},{"k":"text","id":"V141_AFTER_ISK_L04_K1_001_0","text":"작은 돌이 옆으로 굴렀다. 좁은 틈으로 빛이 들어오고, 바깥에서 받침을 부르는 소리가 가까워졌다. 이번에는 혼자 대답을 기다리는 시간이 아니었다."},{"k":"text","id":"V141_BEFORE_ISK_L04_K1_073_0","text":"감우와 연비가 치료소를 찾아왔다. 고운각에서 함께 보고를 찾던 두 사람이, 이번에는 보고 대신 밥을 들고 왔다."}]},{"id":"ISK_L04_K2","entry":"ISK_L04_K2_001","items":[{"k":"keep","id":"ISK_L04_K2_001","hold":true,"text":"들보가 다리를 누르고 있었다. 몸을 일으키려 하자 통증에 숨이 턱 막혔다."},{"k":"line","id":"PRO_L04K2_rubble_001","speaker":"나","text":"……아, 안 돼. 다리가 안 빠져.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_002","speaker":"","text":"출구가 있던 쪽에서 돌 구르는 소리가 들렸다. 손에 잡힌 파편으로 바닥을 두드렸다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_003","speaker":"나","text":"거기…… 사람 있어요? 여기 있어요!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_004","speaker":"천암군","text":"들립니다! 들어가신 통로를 따라왔습니다. 그 자리에서 움직이지 마세요!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_005","speaker":"천암군","text":"앞이 막혔습니다. 목소리는 잘 들립니다. 손을 움직일 수 있습니까?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K2_rubble_006","options":[{"label":"손은 움직여요. 이쪽이에요. 소리 들려요?","id":"PRO_L04K2_rubble_007","items":[{"k":"line","id":"PRO_L04K2_rubble_008","speaker":"","text":"손에 쥔 파편으로 다시 두드렸다. 이번에는 바로 가까운 곳에서 대답이 돌아왔다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_009","speaker":"천암군","text":"들립니다. 그쪽부터 열겠습니다. 손은 잠깐 뒤로 빼 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"다리가 눌렸어요. 여기, 더 무너지는 건 아니죠?","id":"PRO_L04K2_rubble_010","items":[{"k":"line","id":"PRO_L04K2_rubble_011","speaker":"천암군","text":"바깥에서도 들보가 보입니다. 먼저 받치겠습니다. 혼자 다리를 빼려 하지 마세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_012","speaker":"","text":"바깥에서 받침을 부르는 소리가 이어졌다. 꽉 쥐었던 파편을 내려놓았다.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"line","id":"PRO_L04K2_rubble_013","speaker":"천암군","text":"손앞의 작은 파편부터 치우겠습니다. 몸을 누르는 들보는 건드리지 마세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_014","speaker":"나","text":"……이 작은 것만요. 손은 닿아요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"thru","id":"ISK_L04_K2_001"},{"k":"line","id":"PRO_L04K2_rubble_015","speaker":"천암군","text":"보입니다! 뒤쪽, 받쳐! 조금만 더……","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_016","speaker":"나","text":"아……! 잠깐, 다리가……!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_017","speaker":"천암군","text":"멈춰! 받침 그대로 잡아. 더 들지 마!","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_018","speaker":"","text":"움직임이 멎었다. 천암군이 다시 신호를 맞추자 다리를 누르던 무게가 조금씩 줄었다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_019","speaker":"나","text":"……타르탈리아는요? 그 사람은 나왔어요?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_020","speaker":"천암군","text":"우인단 집행관 말입니까? 안에 같이 있었습니까?","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_021","speaker":"나","text":"네. 무너지기 전엔 바로 앞에 있었는데……","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_022","speaker":"천암군","text":"바깥에도 전하겠습니다. 먼저 손을 이쪽으로 뻗어 보십시오.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_023","speaker":"","text":"돌 틈을 더듬던 손이 천암군에게 붙잡혔다. 미끄러질까 봐 손가락에 힘을 줬다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_024","speaker":"나","text":"……잡았어요. 놓지 마요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_025","speaker":"천암군","text":"놓지 않습니다. 여기 있으니 제 목소리를 듣고 계세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L04_K2_007","text":"손이 팔 아래로 들어왔다. 병사 둘이 같은 속도로 몸을 끌어내자 거친 바닥이 옷을 긁었다. 바깥의 빛을 본 뒤에도 한동안 눈을 제대로 뜨지 못했다. 공기를 들이마시자 가슴이 들썩였고, 그 움직임이 아직 내 것이라는 사실이 이상했다. 타르탈리아가 있을 자리는 보이지 않았다."},{"k":"line","id":"PRO_L04K2_rubble_026","speaker":"군의관","text":"다리를 펴려고 힘주지 마세요. 눌렸던 곳부터 확인하겠습니다. 제가 만지는 곳이 느껴지면 말해 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"choice","group":"G_PRO_L04K2_rubble_027","options":[{"label":"받을게요. 치료해 주세요. 두 번 꺼내게 할 생각은 없습니다.","keep":"ISK_L04_K2_009","items":[{"k":"line","id":"PRO_L04K2_rubble_028","speaker":"군의관","text":"살아 있으니 치료하는 겁니다. 그 이상의 뜻은 나중에 생각하셔도 됩니다. 다리부터 보겠습니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"keep","id":"ISK_L04_K2_010","text":"군의관은 구호 상자를 열고 지혈에 쓸 천과 약품을 꺼냈다. 호흡과 눈의 반응을 살피고 눌린 다리의 감각을 확인한 뒤 상처를 씻었다. 잔해에서 꺼낸 몸은 살아 있었고 치료에 반응했다. 내가 왜 살아남았는지는 이 짧은 진찰만으로 알아낼 수 없었다."},{"k":"choice","group":"G_PRO_L04K2_rubble_029","options":[{"label":"바지 자르셔도 됩니다. 어차피 오늘 옷은 끝났어요. 옷값보다 다리값이 비싸다는 정도는 저도 압니다.","id":"PRO_L04K2_rubble_030","items":[{"k":"line","id":"PRO_L04K2_rubble_031","speaker":"군의관","text":"그렇게 말씀하시면 처치하기 편합니다. 다리값 아는 분이 처치 끝나자마자 뛰어가겠다고 하지만 않으면 됩니다.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_032","speaker":"나","text":"그 말이 복선처럼 들리는 건 왜일까요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_033","speaker":"군의관","text":"그런 분을 많이 봤으니까요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]},{"label":"저 다리 움직일 수 있을까요? 잘 걷겠다는 말은 아니고, 옆에서 받쳐 주면 어디까지 되는지 알고 싶어요.","id":"PRO_L04K2_rubble_034","items":[{"k":"line","id":"PRO_L04K2_rubble_035","speaker":"군의관","text":"감각과 움직임은 확인되고 있습니다. 처치한 뒤 부축받으며 천천히 서 보겠습니다. 걸을 수 있는 만큼과 버티고 싶은 만큼을 헷갈리지만 마세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"}]}]},{"k":"keep","id":"ISK_L04_K2_017","text":"붕대가 감기는 동안 먼 바다에서 일어난 거대한 움직임이 공기와 땅을 울렸다. 호위 병사 하나가 언덕 끝을 보고 돌아와, 항구에서 오셀에 맞선 방어가 시작되었다는 급한 연락을 전했다. 일어서려다 군의관의 손에 어깨를 눌렸다."},{"k":"line","id":"PRO_L04K2_rubble_036","speaker":"나","text":"알아요, 갑자기 일어나지 말라는 거죠. 그런데 저쪽은 가야 해요. 황금옥에서 막을 줄 알았는데 결국 바다가 움직였어요. 응광하고 각청한테 저 살아 나왔고 타르탈리아는 안 보인다고 전해 주세요.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_037","speaker":"군의관","text":"호위대와 함께 이동하십시오. 다리를 끌면서 혼자 따라가는 건 허락하지 않겠습니다. 복선 맞았죠.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"line","id":"PRO_L04K2_rubble_038","speaker":"나","text":"……네.","map":"MAP_LIYUE_GOLDEN_HOUSE"},{"k":"keep","id":"ISK_L04_K2_020","text":"병사의 어깨를 빌려 일어섰다. 안에서 만난 타르탈리아가 떠올랐다. 누군가를 찾는다는 말에도, 부하들의 상태에도 무심하던 얼굴이었다. 그러나 지금 그 얼굴을 붙잡으려 무너진 안으로 돌아가는 것은 사람들을 다시 위험 속에 세우는 일이었다. 바다를 향한 길을 골랐다."},{"k":"keep","id":"ISK_L04_K2_021","text":"병사들은 길의 완만한 부분을 골라 이동했다. 자꾸 부축을 받는 것이 미안했지만 그때마다 거절하면 오히려 더 늦어졌다. 한참 뒤 대피한 사람들이 모이는 항구 외곽의 넓은 길에 닿았다."},{"k":"line","id":"PRO_L04K2_porter_001","speaker":"","text":"사람들이 빠져나간 거리 한쪽에서 유리 깨지는 소리가 났다. 빈 가게였다. 보물 사냥단 셋이 자루를 메고 나왔다. 바다가 일어선 날에도 남의 물건부터 챙기는 사람은 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_002","speaker":"보물 사냥단","text":"비켜. 다리도 성치 않은 게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_003","speaker":"나","text":"그 말은 맞는데요. 비킬 다리가 없어서요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_004","speaker":"","text":"호위 병사가 창을 내렸다. 나도 무기를 들었다. 다리 대신 팔로 하는 싸움이면 할 수 있었다.","map":"MAP_LIYUE_HARBOR"},{"k":"combat","id":"PRO_L04K2_porter_005","group":"EG_TREASURE_PATROL","text":"대피로 비어 버린 거리를 터는 보물 사냥단 습격조. 길을 막고 서 있으니 치울 수밖에 없다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_006","speaker":"","text":"자루가 바닥에 떨어지고 사냥단은 골목으로 흩어졌다. 병사가 자루를 가게 안으로 던져 넣고 문을 닫았다. 다시 걸었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_007","speaker":"","text":"집결지 앞에서 수레 하나가 길을 가로막고 있었다. 사람을 태우려고 짐을 내린 수레였다. 앞쪽에서 누군가 끈을 당기는 병사에게 매듭을 너무 깊게 넣지 말라고 핀잔을 주었다. 걸음이 멎었다. 닷새 동안 들어 귀에 익은 목소리였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_008","speaker":"짐꾼","text":"다시 풀어야 하는 매듭인데 그렇게 꽉 묶으면 칼로 끊어야 하잖소. 손 이쪽으로 빼고…… 거기, 당신 왜 그렇게 보고 있소? 어디 갔다가 그런 꼴로 돌아왔소? 같이 내려오기로 해 놓고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_009","speaker":"","text":"살아 있었다. 내가 들어 올리려다 끝내 두고 온 사람이 자기 발로 서서 남의 일을 거들고 있었다. 이름을 부를 수 없어서 그대로 앞으로 다가갔다. 짐꾼은 다친 다리를 보고 손을 내밀었다. 그 손을 잡자 어깨가 무너졌다. 차가웠던 몸과 따뜻한 손이 같은 사람의 것이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_010","speaker":"나","text":"……살아 계셨네요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_011","speaker":"나","text":"저, 당신을 거기 두고 나왔어요. 들려고 했는데 안 됐고, 무서워서 도망쳤어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_012","speaker":"짐꾼","text":"두고 나왔다니 어디서? 의례에 같이 간 건 기억하오. 그다음에 정신 차리니까 길 옆이었고, 내가 왜 거기 있는지 모르겠더군. 병사들이 쉬라고 했는데 바다가 난리라 여기로 옮겼소. 당신이 나를 찾는다는 말은 아까 들었는데, 대피하는 사이에 엇갈린 모양이오.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_027","text":"더 세게 손을 잡으려다가 놓았다. 손에 붕대를 감은 나를 보고 짐꾼이 얼굴을 찌푸렸기 때문이다. 의례에서 분명 이 사람의 죽음을 확인했다. 지금의 대답이 그 사실을 지우지는 않았다. 대신 죽었던 사람에게도 설명할 수 없는 시간이 있고, 그 뒤에 다시 시작된 하루가 있다는 것을 눈앞에서 보았다."},{"k":"choice","group":"G_PRO_L04K2_porter_013","options":[{"label":"자세한 건 나중에 해도 될까요? 지금은 당신이 여기 계신 것부터 좀 믿고 싶어요.","id":"PRO_L04K2_porter_014","items":[{"k":"line","id":"PRO_L04K2_porter_015","speaker":"짐꾼","text":"내가 설명할 수 있었으면 벌써 했겠지. 당신은 나를 두고 도망쳤다고 하고, 나는 돌아와서 나를 찾는 사람을 보고 있소. 둘 다 할 말이 많아 보이는데 바다가 잠잠해진 다음에 하오.","map":"MAP_LIYUE_HARBOR"}]},{"label":"각청은 저를 기억 못 해요. 당신은…… 닷새 동안 같이 있던 거, 기억하세요?","id":"PRO_L04K2_porter_016","items":[{"k":"line","id":"PRO_L04K2_porter_017","speaker":"짐꾼","text":"기억하오. 매듭 못 묶던 사람이 닷새째 되니까 포대는 안 떨어뜨리더군. 의례 다음부터가 비어 있는 거요. 그러니 지금 앞에 있는 사람부터 보시오. 할 말은 바다가 잠잠해진 다음에 하고.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_porter_018","speaker":"","text":"웃으려다가 울음처럼 숨을 뱉었다. 각청에게서 잃은 닷새가 이 사람에게는 남아 있었다. 그 차이를 단서라고 부르고 싶지 않았다. 살아 있는 사람이 먼저였다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_porter_019","options":[{"label":"저는 군옥각 쪽으로 가요. 위에서 막는 동안 길을 지켜야 해요. 당신은 대피하는 사람들하고 같이 나가 주세요. 이번엔 자기 몸 하나만 챙기세요.","id":"PRO_L04K2_porter_020","items":[{"k":"line","id":"PRO_L04K2_porter_021","speaker":"짐꾼","text":"그 몸으로 또 가겠다고? 말리면 들을 얼굴도 아니군. 그럼 당신도 약속은 지키시오. 내려와서 짐 어찌 됐는지 같이 보기로 했잖소. 이번에는 끝까지 보고 나서 헤어지자고.","map":"MAP_LIYUE_HARBOR"}]},{"label":"저는 군옥각 쪽 길을 지키러 가요. 짐 확인하러 만날 때까지 둘 다 멀쩡히 돌아오는 거, 먼저 약속해요.","id":"PRO_L04K2_porter_022","items":[{"k":"line","id":"PRO_L04K2_porter_023","speaker":"짐꾼","text":"그 약속이면 나도 할 수 있소. 짐 때문에 남으라는 부탁 안 하는 건 고맙군. 내려와서 짐 어찌 됐는지 같이 보기로 한 것도 잊지 마시오. 이번에는 끝까지 보고 나서 헤어지자고.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_porter_024","speaker":"","text":"각청이 보낸 병사가 수색 보고를 가지고 다가왔다. 이번에는 찾았다는 소식이 실제로 목적지에 닿아야 했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_025","speaker":"나","text":"찾았어요. 제가 찾던 분 맞고 살아 계세요. 각청한테도 그렇게 전해 주세요. 이분 대피하는 길부터 안내해 주시고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_026","speaker":"","text":"병사는 대피 조에 짐꾼을 인계하고 발견 소식을 각청에게 전했다. 그가 걸어가는 뒷모습을 오래 보지 않았다. 이번에는 어디로 가는지 알고 있었고, 다시 만날 일을 남겨 두었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_027","speaker":"각청","text":"찾았다는 보고 받았어. 다행이네. 수색 인원은 대피 쪽에 붙일게. 네 상태는 군의관한테 들었고. 정면에서 뛰어다닐 생각이면 지금 돌려보낸다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_028","speaker":"나","text":"정면으로 뛸 기운은 없어. 그래도 길 하나는 지킬 수 있으니까 맡겨 줘. 사람 찾았다고 나만 앉아 있기엔 저 바다가 너무 시끄럽잖아.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_029","speaker":"각청","text":"군옥각 연결 지점. 선인들이 정면 막는 동안 뒤에서 장치 노리는 적을 끊어. 혼자 멀리 쫓아갔다가 다리 풀리면 네 몸 내가 들고 내려와야 돼. 그건 좀 싫어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_porter_030","speaker":"나","text":"솔직해서 좋네.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_039","text":"각청은 나를 전투 인원에게 넘기며 다친 쪽을 분명히 알렸다. 누구도 그것을 듣고 도움이 안 된다고 말하지 않았다. 작은 몫을 실제로 끝내는 편이 큰일을 하겠다며 쓰러지는 것보다 나았다."},{"k":"keep","id":"ISK_L04_K2_040","text":"군옥각 위에서는 바람이 얼굴을 때렸다. 응광과 선인들의 힘이 바다를 향해 이어졌고, 그 빛 뒤로 병사들이 움직였다. 물결이 부딪칠 때마다 바닥이 흔들렸지만 곧바로 부서지지는 않았다."},{"k":"line","id":"PRO_L04K2_osial_001","speaker":"응광","text":"황금옥에서 살아 나온 손님이 돌아왔군. 지금은 의자를 내줄 수 없어. 뒤쪽 길을 부탁할게.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_002","speaker":"나","text":"의자는 나중에 빌리겠습니다. 먼저 하나만요. 짐꾼 찾았어요. 살아 있고 대피 중입니다. 사람 붙여 주신 거 잊지 않을게요.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_003","speaker":"응광","text":"좋은 소식 하나는 가져왔네. 그렇다고 다친 몸까지 잊지는 마. 네가 선 자리를 비우지 않는 게 지금 제일 큰 도움이야.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_004","speaker":"류운차풍진군","text":"이 몸이 바다를 막는 사이 연결 장치에 손을 대려는 것들이 있네. 장치를 살피겠다고 함부로 선 밖으로 나가지 말게.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_005","speaker":"나","text":"알겠습니다. 오늘은 혼자 더 들겠다고 고집부리는 사람이 제일 먼저 지치는 날 같아서요. 저는 벌써 한 번 지쳤으니 자격이 있습니다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_006","speaker":"","text":"금속 부딪치는 소리가 뒤에서 울렸다. 연결로 끝에 나타난 습격자들이 방어 인원을 밀어내며 안쪽을 노렸다. 옆의 병사가 방패를 세웠고, 각청이 앞을 막는 동안 나는 그 틈으로 파고드는 적에게 무기를 겨누었다.","map":"MAP_OSIAL_BATTLE"},{"k":"keep","id":"ISK_L04_K2_047","text":"선인과 칠성이 오셀의 압력을 막는 동안, 군옥각의 연결 지점과 진법을 지키는 방어전이 시작된다."},{"k":"line","id":"PRO_L04K2_osial_007","speaker":"","text":"연결 지점을 향하던 적의 움직임이 마침내 꺾였다. 그러나 바다의 힘이 다시 장치를 덮치자 선인들이 펼친 방어가 크게 휘었고, 건물 아래로 떨어진 파편이 돌아오지 않는 깊이까지 내려갔다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_008","speaker":"류운차풍진군","text":"연결부가 더 버티지 못하겠네. 이 몸이 받아 낼 테니 안쪽 인원부터 물리게. 장치 붙잡으려고 남으면 구해야 할 사람만 느네!","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_009","speaker":"","text":"응광은 남은 대피 인원과 손상된 지점을 빠르게 확인했다. 비서가 들고 가려던 상자에 시선이 갔다. 큰 상자는 두 사람이 들어야 했다. 그 곁에 서지 못하는 부상자가 있었다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_010","speaker":"나","text":"상자는 여기 놔요. 저 사람 먼저. 어깨 이쪽으로 잡아 주세요.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_011","speaker":"","text":"비서는 상자를 내려놓았다. 의례장에서 짐꾼을 혼자 들어 올리려다 실패한 팔이었다. 이번에는 혼자가 아니었고, 들어야 할 사람도 숨을 쉬며 발을 움직이려 애썼다. 그 숨소리에 보폭을 맞췄다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_012","speaker":"응광","text":"군옥각을 포기하겠어. 남은 힘을 모아 바다로 떨어뜨릴 거야. 사람은 모두 옮겨. 가져갈 수 없는 물건은 두고 가. 여기 남는 건 내가 책임질 손해니까, 누구도 그것 때문에 목숨 걸 필요 없어.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K2_osial_013","options":[{"label":"아깝지 않다는 얼굴 안 하셔도 됩니다. 제가 먼저 버리라고 한 말 때문에 하는 선택처럼 남기지는 않을게요.","id":"PRO_L04K2_osial_014","items":[{"k":"line","id":"PRO_L04K2_osial_015","speaker":"응광","text":"이미 알고 있군. 그럼 두 번 말할 필요 없겠네. 내 결정을 네가 대신 짊어지려고 하지 마. 너는 네가 받친 사람을 놓지 않는 쪽에 힘을 써. 그게 내 집을 가장 값있게 떠나는 방법이야.","map":"MAP_OSIAL_BATTLE"}]},{"label":"제가 챙길 수 있는 사람부터 데리고 나갈게요. 나중에 제가 결단한 것처럼 말하지도 않겠습니다.","id":"PRO_L04K2_osial_016","items":[{"k":"line","id":"PRO_L04K2_osial_017","speaker":"응광","text":"그 말은 받아 두지. 설명은 살아서 내려간 뒤에도 할 수 있어. 네가 받친 사람을 놓지 않는 쪽에 힘을 써.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K2_osial_018","speaker":"","text":"선인들이 힘을 모으자 바람의 방향이 바뀌었다. 지나가다 문턱에 걸린 끈을 손으로 걷어 냈다. 풀어야 하는 매듭을 너무 깊게 넣지 말라던 목소리가 떠올랐다. 떠나야 할 때 붙잡는 것은 좋은 매듭이 아니었다.","map":"MAP_OSIAL_BATTLE"},{"k":"choice","group":"G_PRO_L04K2_osial_019","options":[{"label":"뒤쪽 상자는 놔두고 왔어. 주인 허락받았으니까 물건 찾으러 돌아갈 사람 없게 해 줘. 이제 우리도 빠지면 되는 거지?","id":"PRO_L04K2_osial_020","items":[{"k":"line","id":"PRO_L04K2_osial_021","speaker":"각청","text":"맞아. 더 돌아갈 이유 없어. 부상자는 저쪽이 받았으니 네 손도 빼. 사람 다 내보내고 너만 뒤에 남으면 그게 끝난 거야? 아니지.","map":"MAP_OSIAL_BATTLE"}]},{"label":"내가 맡은 사람은 넘겼어. 이제 나도 좀 부축받아도 되겠지? 괜찮은 척하는 재주가 늘어서 그게 제일 걱정이야.","id":"PRO_L04K2_osial_022","items":[{"k":"line","id":"PRO_L04K2_osial_023","speaker":"각청","text":"그 말은 잘했어. 팔 이쪽으로 걸어. 다리에 힘 없으면 그만큼 내가 받으면 돼. 너 생각보다 무겁진 않네.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_024","speaker":"나","text":"그건 칭찬이야?","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_025","speaker":"각청","text":"보고야.","map":"MAP_OSIAL_BATTLE"}]}]},{"k":"line","id":"PRO_L04K2_osial_026","speaker":"","text":"소가 남은 사람들의 위치를 확인하고 선인들이 빠져나갈 길을 붙들었다. 바닥이 기울면서 발이 미끄러졌지만 옆의 손이 나를 잡았다. 응광이 힘을 내려 보내는 순간 군옥각은 도시를 받치던 높이를 버리고 바다를 향해 떨어졌다.","map":"MAP_OSIAL_BATTLE"},{"k":"line","id":"PRO_L04K2_osial_027","speaker":"","text":"거대한 충격이 하늘과 물을 갈랐다. 조금 전까지 사람을 들고 나오던 문과, 그 뒤에 두고 온 상자와, 손님을 위해 비워졌던 의자가 하나의 빛 속으로 사라졌다. 오래 도시를 위협하던 울림이 마침내 잦아들었다.","map":"MAP_OSIAL_BATTLE"},{"k":"keep","id":"ISK_L04_K2_065","text":"안전지대에 내려왔을 때 나는 한동안 팔을 둥글게 든 채 있었다. 이미 다른 인원에게 넘긴 부상자의 무게가 아직 몸에 남아 있었다. 각청이 어깨에서 손을 빼도 된다고 말하자 그제야 팔을 내렸다. 살아 있는 이들의 이름을 부르는 소리가 올라왔다."},{"k":"keep","id":"ISK_L04_K2_066","text":"해안의 급한 대피는 멈췄고 전투 인원은 남은 사람을 확인하기 시작했다. 군옥각을 잃었지만 도시 전체가 그 뒤를 따라 가라앉지는 않았다. 서로의 빈자리를 받치며 버틴 끝에, 응광과 선인들이 마지막 결정을 실행한 결과였다."},{"k":"line","id":"PRO_L04K2_osial_028","speaker":"나","text":"끝났다는 게 이런 소리였구나. 나 잠깐 앉을게. 이번에는 어디 안 가. 다리가 더는 내 의견을 안 받아 줘.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_osial_029","speaker":"각청","text":"앉아. 군의관 올 거야. 어디 안 간다는 말은 여기 있는 사람들 다 들었으니까 혼자 일어나지 마. 네가 찾던 사람도 대피소 도착한 거 확인됐어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_osial_030","speaker":"나","text":"……고마워.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_osial_031","speaker":"각청","text":"그 말 하려고 그 얼굴 하는 거야? 쉬고 나서 해.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_069","text":"치료 구역에서 군의관은 다시 벌어진 상처를 살피고 붕대를 갈았다. 다친 다리에 과하게 힘을 준 탓에 붓기가 늘었지만 감각과 움직임은 남아 있었다. 아픈 곳을 아프다고 말하는 일이 오히려 쉬워졌다."},{"k":"line","id":"PRO_L04K2_name_001","speaker":"나","text":"이번엔 정말 쉬겠습니다. 다만 사람 하나가 찾아오면 저 여기 있다고 알려 주세요. 짐꾼이고, 의례 전에 저하고 같이 지냈던 분이에요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_002","speaker":"군의관","text":"접수 담당자에게 말해 두겠습니다. 사람 만나면 설명하느라 흥분해서 일어나지 마세요. 오늘은 치료받는 역할입니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_003","speaker":"나","text":"역할 배정이 확실하네요. 대본대로 할게요.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_072","text":"누워서 천막 위를 보았다. 짐꾼이 언제 올지 기다리는 동안 잠이 들었다. 깨어났을 때는 낮이 지나 있었고, 침상 옆의 의자에 익숙한 사람이 앉아 있었다. 의례장에서 내려놓았던 몸이 이번에는 제 팔을 무릎 위에 얹고 꾸벅꾸벅 졸고 있었다."},{"k":"line","id":"PRO_L04K2_name_004","speaker":"나","text":"의자 불편하면 깨우시지 그랬어요. 그렇게 자면 허리 더 아프잖아요. 그런데…… 다시 와 주셨네요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_005","speaker":"짐꾼","text":"누운 사람 깨워 놓고 나 쉬겠다고 할 수는 없잖소. 당신이 먼저 찾아오겠다더니 몸을 그 꼴로 만들어 놓아서 내가 왔지. 내려오면 이야기하자던 약속은 지켜야 하니.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_006","speaker":"","text":"짐꾼이 살아 있는지 다시 손목을 확인하지 않았다. 잠에서 깬 사람이 뻣뻣해진 허리를 펴고 물을 찾는 모습을 보았다. 닷새 동안 너무 흔해서 흘려보냈던 행동들이 전부 선명했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_007","speaker":"나","text":"제대로 말할게요. 의례에서 사람들이 한꺼번에 죽었어요. 당신 숨도 맥박도 없었고, 제가 들어 올리려다 못 했어요. 당신이 잘못 기억한다는 말은 아니에요. 제가 왜 그렇게 굴었는지 알아 주셨으면 해서요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_008","speaker":"짐꾼","text":"그 말을 들으니 당신 얼굴은 이해가 되오. 나는 내가 그렇게 됐다는 감각이 없소. 안다고 거짓말해 줄 수도 없고. 그래도 당신이 찾으러 돌아왔다는 건 알지. 당신이 나를 두고 왔다고 계속 자기를 붙들면, 지금 찾아온 나는 어디 서 있어야 하오?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_009","speaker":"","text":"시선을 내렸다가 다시 들었다. 죽음을 기억하는 사람만 대화의 중심에 두면 살아 돌아온 사람이 자기 이야기를 할 자리가 없었다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_name_010","options":[{"label":"그러네요. 이름부터 알려 주세요. 닷새를 같이 있었는데 짐꾼이라고만 부른 게 이제 와서 너무 미안해요.","id":"PRO_L04K2_name_011","items":[{"k":"line","id":"PRO_L04K2_name_012","speaker":"짐꾼","text":"미안할 일까지는 아니오. 일터에서는 늘 그렇게 불리니. 그래도 이름을 묻는 건 좋군. 적어 주겠소. 당신도 적어 주시오. 다음에 누가 찾으러 와도 서로 설명하기 편하게.","map":"MAP_LIYUE_HARBOR"}]},{"label":"그럼 오늘은 제가 설명하는 쪽을 줄일게요. 당신이 정신 차린 다음 얘기를 듣고 싶어요. 누가 물 줬는지 같은 것부터요.","id":"PRO_L04K2_name_013","items":[{"k":"line","id":"PRO_L04K2_name_014","speaker":"짐꾼","text":"길가에 앉아 있는데 한 아주머니가 물을 줬소. 내가 짐부터 찾겠다고 일어나니까 당신하고 똑같이 고집부린다고 핀잔도 주고. 이름은 못 물었지. 그러고 보니 당신한테도 내 이름을 말한 적이 없군. 적어 주겠소. 당신도 적어 주시오.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_name_015","speaker":"","text":"짐꾼은 종이에 자기 이름과 찾을 수 있는 작업 구역을 적어 주었다. 종이를 받아 이름을 읽고서 짐꾼의 얼굴을 다시 보았다. 장록. 닷새 동안 포대 뒤에 가려져 있던 이름이 두 글자로 손 안에 놓였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_016","speaker":"나","text":"장록 씨.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_017","speaker":"나","text":"……이제야 부르네요. 제 이름하고 지금 머무는 곳도 적어 드릴게요. 몸 좀 나아지면 포대 확인하러 같이 가요. 이번엔 끝나는 것까지 옆에서 볼게요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_018","speaker":"장록","text":"그렇게 불리니까 일터가 아니라 집 같군. 됐소, 포대는 안 도망가오. 당신 다리가 먼저지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_019","speaker":"","text":"나도 내 이름과 당분간 머무는 치료소를 적어 건넸다. 서로를 부르는 데 더는 막연한 설명이 필요하지 않았다. 그 종이가 사라진 시간을 되돌리지는 않았지만 다음 만남을 마련하는 데는 도움이 되었다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_088","text":"다음 이틀 동안 재진료를 받으며 짧게 걷는 연습을 했다. 장록은 자신의 작업 구역과 치료소를 오가며 필요한 소식을 전했다. 그가 겪은 빈 시간은 돌아오지 않았지만, 지금 어디에 머무는지 모르는 사람으로 다시 사라지지는 않았다."},{"k":"line","id":"PRO_L04K2_name_020","speaker":"각청","text":"오늘 리월항 일반 봉쇄 해제해. 황금옥 잔해랑 해안 파손 구역만 계속 막고. 너희가 기다리던 포대도 상대랑 검수 인원 불러서 확인할 거야. 이번엔 기억 말고 실제 물건을 같이 보면 돼.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_021","speaker":"나","text":"좋아. 지난번에 내가 본 건 끈 풀린 것까지였고 안에 뭐가 있었는지는 못 봤어. 그건 그대로 말할게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_022","speaker":"각청","text":"그리고 천천히 걸어. 끝까지 같이라고 해 놓고 중간에 또 쓰러지면 그 아저씨가 널 들고 가야 되잖아. 허리 아프시다며.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_023","speaker":"나","text":"소문이 빠르네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_name_024","speaker":"각청","text":"치료소 전부가 알아.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_091","text":"각청은 통행을 재개한 길을 안내하고 검수 인원에게 시간을 알렸다. 나와 장록은 그 길을 함께 걸었다. 전에 기다리던 자리에 포대가 있었고, 물건을 넘겨받을 담당자가 도착해 있었다. 끈을 풀고 내용물과 수량을 확인하는 동안 나는 옆에서 지켜보았다. 지금 새로 인계할 수 있게 된 자리였다."},{"k":"keep","id":"ISK_L04_K2_092","text":"상대가 물건을 확인하고 인수 증서를 건넸다. 장록은 서명을 마친 뒤 증서와 빈손을 번갈아 보았다. 누구의 기억이 옳았는지 싸우느라 멈춰 있던 일이, 현재의 물건을 함께 확인하는 일로 마침내 끝났다. 장록은 어깨를 한 번 크게 돌리고 내 쪽으로 몸을 돌렸다."},{"k":"line","id":"PRO_L04K2_cargo_001","speaker":"장록","text":"끝났군. 이거 하나 내려놓는 데 무슨 일이 이렇게 많았는지. 당신이 내 짐을 대신 든 건 없지만, 끝까지 같이 본 사람은 됐소. 그건 기억할 수 있겠지.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_cargo_002","options":[{"label":"대신 안 들어도 한몫은 했네요. 그럼 이제 제 다리 핑계로 밥집까지는 장록 씨가 천천히 걸어 주세요. 비싼 집 고르자는 뜻은 아니고요.","id":"PRO_L04K2_cargo_003","items":[{"k":"line","id":"PRO_L04K2_cargo_004","speaker":"장록","text":"말은 여전히 뻔뻔하군. 됐소, 길가에서 먹을 만한 데는 알아. 먹고 나면 나는 집에 소식부터 보낼 거요. 당신도 기다리는 사람 있으면 알리시오. 없다 해도 돌아올 곳은 하나쯤 적어 두고.","map":"MAP_LIYUE_HARBOR"}]},{"label":"밥 먹고 나면 서로 소식 보낼 곳부터 정리하죠. 살아 있다고 알리는 걸 저는 자꾸 일이 다 끝난 다음으로 미뤘거든요.","id":"PRO_L04K2_cargo_005","items":[{"k":"line","id":"PRO_L04K2_cargo_006","speaker":"장록","text":"좋은 순서군. 배부터 채우고, 기다리는 사람한테도 밥이 넘어갈 만한 소식을 보내자고. 길가에서 먹을 만한 데는 알아.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K2_096","text":"두 사람은 길가의 식당에서 천천히 한 끼를 먹었다. 장록은 다음에 맡을 일과 집에 보낼 소식을 이야기했고, 나는 듣다가 내 몫의 국물을 마셨다. 의례장에서 두고 온 사람의 이야기가 그 장면에서 멈추지 않았다. 지금의 그는 다음 일을 고르는 사람이었다."},{"k":"keep","id":"ISK_L04_K2_097","text":"응광과 선인들을 다시 만난 것은 그날 늦은 오후였다. 군옥각 대신 임시로 마련한 공간에서 피해 보고와 이후의 경계를 논하고 있었다. 전투의 규모에 비하면 작은 이야기였지만, 이번에는 스스로 작은 말로 줄이지 않기로 했다."},{"k":"line","id":"PRO_L04K2_council_001","speaker":"나","text":"찾던 분은 살아 계시고 화물 인계도 끝났습니다. 장록이라는 분이에요. 의례 그 순간은 기억 못 하지만 저랑 기다리던 닷새는 기억하세요. 수색 계속해 주신 덕분이에요. 바다 얘기에 묻히기 전에 직접 전하고 싶었습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_002","speaker":"응광","text":"잘 전해 줬어. 도시를 지킨 뒤 남겨야 할 게 거대한 승리 이야기만은 아니니까. 다만 기억의 빈칸은 계속 남아 있군. 네가 본 것과 그 사람이 기억하는 것을 따로 적어 두겠어.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_003","speaker":"류운차풍진군","text":"산에서 자네가 그 사람을 두고 왔다며 괴로워하던 모습을 기억하네. 다시 만났으니 이 몸도 다행이라 생각하네. 허나 기쁜 일과 설명할 일을 한데 섞어 억지 답을 만들지는 말게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_004","speaker":"나","text":"처음에는 살아 있는 사람만 보면 어떻게 살아 있냐고 붙들었는데, 그분이 그러더라고요. 그렇게만 묻고 있으면 지금 찾아온 자기는 어디 서 있느냐고. 좀 부끄러웠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_005","speaker":"각청","text":"그래서 지금 할 수 있는 일을 다시 정하는 거예요. 바다 경계는 선인들께 도움받아 계속하고, 통행이랑 생활은 저희가 돌려놓겠습니다. 선언보다 매일 그 일을 끝내는 쪽이 보여 주는 게 더 많겠죠.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_006","speaker":"류운차풍진군","text":"자네의 뜻은 들었네. 이번에는 직접 지키고 직접 내놓는 것을 보았지. 서로 확인할 길을 남겨 두는 편이 낫겠군.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_007","speaker":"응광","text":"연락할 길은 열어 둘게요. 군옥각을 잃었다고 리월의 결정까지 공중에 매달려 사라진 건 아니니까요.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_council_008","options":[{"label":"저도 리월에서 더 할 일 있으면 알려 주세요. 다만 군의관이 무거운 짐은 아직 들지 말랬어요. 산 뛰어 올라가는 일은 며칠만 뒤로 미뤄 주시면 좋겠습니다.","id":"PRO_L04K2_council_009","items":[{"k":"line","id":"PRO_L04K2_council_010","speaker":"류운차풍진군","text":"이 몸이 자네를 급한 전갈에만 쓰려고 기다리는 줄 아는가. 자네 다리가 낫는 동안에도 날 수 있는 자들은 있네. 몸부터 돌보게.","map":"MAP_LIYUE_HARBOR"}]},{"label":"몸이 나을 때까지는 전달이나 설명 정도로 돕겠습니다. 할 수 있는 범위를 먼저 말씀드리는 게 낫겠죠.","id":"PRO_L04K2_council_011","items":[{"k":"line","id":"PRO_L04K2_council_012","speaker":"류운차풍진군","text":"그 범위를 아는 것도 책임이지. 의지가 있다는 이유로 몸의 상태를 지울 수는 없네. 몸부터 돌보게.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_council_013","speaker":"","text":"그 잔소리를 다시 들을 수 있다는 사실이 나에게는 위로였다. 소는 문밖에서 시선을 돌려 나를 보았다. 황금옥으로 가기 전 돌아올 길을 보라고 했던 사람이었다. 이번에는 고개를 숙여 인사했다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_014","speaker":"나","text":"그때 돌아올 길 보라고 하신 말씀, 도움이 됐어요. 관리 통로로 들어간 걸 병사들한테 남겼고, 그 길을 기억해서 저를 찾았대요. 저 혼자 잘해서 나온 건 아니었습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_council_015","speaker":"소","text":"살아 돌아왔으면 됐어. 다음에도 길을 남겨. 너를 찾는 사람도 생겼으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_001","speaker":"","text":"면담이 끝난 뒤 임시 집무 공간을 나서자 종려가 길가에서 기다리고 있었다. 그의 얼굴을 알아보았지만 다가가며 오래된 친구처럼 부르지는 않았다. 류운차풍진군은 두 사람을 잠깐 보고 먼저 다른 선인들과 이동했다. 옛 인연을 설명하는 말은 남기지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_002","speaker":"종려","text":"나는 왕생당의 객경, 종려라고 하네. 자네가 리월에서 겪은 일이 적지 않다고 들었어. 몸이 괜찮다면 잠깐 이야기를 나누고 싶군. 다리가 불편하면 앉을 곳부터 찾지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_003","speaker":"나","text":"종려 씨. 성함은 알고 있습니다. 어디부터 물어야 할지 모르는 사람을 길가에서 만나니까 이상하네요. 우선 앉자는 데는 전적으로 동의합니다.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_114","text":"두 사람은 가까운 차 자리로 옮겼다. 종려는 내가 자세를 잡은 뒤 차를 권했다. 의례와 폐허 사이를 오간 뒤 처음으로 누군가와 뜨거운 잔이 식기를 기다리는 시간이 생겼다."},{"k":"line","id":"PRO_L04K2_zhongli_004","speaker":"나","text":"사람들이 제군 없이 리월을 지켰다고 하더라고요. 맞는 말인데 화가 납니다. 시험당한 사람들은 시험이라고 들은 적이 없잖아요. 하루 벌어 먹고살던 사람은 그날도 짐 들러 나온 거였고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_005","speaker":"종려","text":"사람의 하루는 더 큰 목적이 있다는 이유로 가벼워지지 않네. 자네가 화를 내는 것은 이해하네. 하지만 리월 사람들이 이번에 한 선택까지 다른 누군가의 생각 속으로 돌려놓을 필요는 없을 걸세.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_zhongli_006","options":[{"label":"그건 알아요. 응광이 군옥각을 포기한 건 직접 고른 일이었어요. 그래서 더 묻고 싶어요. 누군가는 얼마나 알고 있었고, 누군가는 왜 아무것도 모른 채 버텨야 했는지.","id":"PRO_L04K2_zhongli_007","items":[{"k":"line","id":"PRO_L04K2_zhongli_008","speaker":"종려","text":"자네가 나에 대해 알고 있다고 여기는 부분도 있겠군. 여기서 이름을 크게 확인하려 하지 않는 걸 보니 어디까지 말할지는 생각하고 온 모양이네. 답할 수 있는 일은 직접 답하겠어. 다만 모든 질문에 같은 범위의 대답을 줄 수는 없지.","map":"MAP_LIYUE_HARBOR"}]},{"label":"사람들이 무슨 위험을 감수하는지 알고 선택할 기회는 있었는지 묻고 싶어요. 제가 아는 이름 확인받는 것보다 그게 더 걸립니다.","id":"PRO_L04K2_zhongli_009","items":[{"k":"line","id":"PRO_L04K2_zhongli_010","speaker":"종려","text":"책임의 범위를 묻는 질문으로 듣겠네. 답할 수 있는 일은 직접 답하겠어. 모든 질문에 같은 범위의 대답을 줄 수는 없지.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_zhongli_011","speaker":"나","text":"그럼 하나만요. 의례에서 사람들이 실제로 죽고 다시 나타난 일, 그것도 당신이 의도한 겁니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_012","speaker":"종려","text":"자네가 겪었다는 그 죽음과 기억의 빈자리를 내가 계획한 시험의 결과라고 말해 줄 수는 없네. 내가 설명할 수 있는 계획이 있다는 이유로 그 밖의 모든 현상을 거기에 넣어서는 안 되지. 자네가 본 일은 그 자체로 살펴야 할 일이네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_013","speaker":"","text":"잔을 내려놓았다. 모든 일이 하나의 손에서 나왔다고 들으면 미워할 사람을 정하기는 쉬웠을 것이다. 그러나 그 대답은 내가 아는 이야기와 지금 벌어진 일 사이에 다시 경계를 그었다. 답답했지만 없는 다리를 밟고 건너가는 것보다는 나았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_014","speaker":"나","text":"그럼 남은 질문은 계약 쪽이겠네요. 물을 수 있는 자리에서 직접 묻고 싶습니다. 당신 가는 곳에 따라가도 됩니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_015","speaker":"종려","text":"북국은행에서 마무리할 일이 있네. 그곳으로 오게. 다만 자네가 내 답에 만족할 것이라고 미리 약속할 수는 없겠군.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_zhongli_016","options":[{"label":"솔직한 초대네요. 대답이 마음에 안 들어도 컵은 안 던질게요. 치료비 내고 나면 남의 그릇값까지 물 여유가 없어서요.","id":"PRO_L04K2_zhongli_017","items":[{"k":"line","id":"PRO_L04K2_zhongli_018","speaker":"종려","text":"그릇을 지켜 준다니 다행이군. 불만은 말로 전하게. 적어도 무엇이 답답한지는 더 분명히 들을 수 있을 테니.","map":"MAP_LIYUE_HARBOR"}]},{"label":"알겠습니다. 다만 제 말이 거칠어져도 못 배운 사람 취급은 하지 마세요. 오늘은 모르는 값이 좀 컸습니다.","id":"PRO_L04K2_zhongli_019","items":[{"k":"line","id":"PRO_L04K2_zhongli_020","speaker":"종려","text":"질문이 거칠다는 이유로 그 안의 일을 못 들은 척하지는 않겠네. 자네도 대답을 듣기 전에 정한 결론이 있다면 잠깐 내려놓고 오게.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K2_130","text":"북국은행에 들어섰을 때 시뇨라를 먼저 보았다. 옆에 선 타르탈리아가 고개를 돌렸다. 멀쩡한 얼굴이었다. 붕대 아래 손가락을 움켜쥐었다. 잔해와 함께 사라진 상대가 살아 있는 사람들 사이에서 대화를 나누고 있었다."},{"k":"line","id":"PRO_L04K2_zhongli_021","speaker":"시뇨라","text":"몬드의 그 방해꾼이잖아. 리월까지 기어왔어? 그 다리는 또 어디서 나서다 얻은 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_022","speaker":"시뇨라","text":"끼어들 생각이면 지금 말해. 참아 줄 생각은 없으니까.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_023","speaker":"나","text":"안 끼어듭니다. 계약 자리에 주먹부터 들이밀러 온 건 아니에요. 다만 그 계약 때문에 묻고 싶은 게 있고, 저 사람한테도 할 말이 있습니다. 끝나면 제 차례도 좀 남겨 주세요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_024","speaker":"타르탈리아","text":"나한테? 시뇨라한테 한 소리 듣고도 눈은 계속 이쪽이네. 종려 씨 거래부터 끝내는 게 좋겠군요. 나도 그 설명 기다리던 중이라서.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_025","speaker":"","text":"그 말투에 눈을 가늘게 떴다. 기분이 나빠도 상대와 한 번 부딪쳐 보고 싶어 하는 온도가 있었다. 황금옥에서는 같은 입가의 웃음이 비어 보였다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_026","speaker":"종려","text":"얼음의 여왕과 맺은 계약에 따라 나의 신의 심장을 넘기겠네. 시뇨라, 자네가 받아 전하게. 약속한 대가와 조건도 그대로 지켜져야 하겠지.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_027","speaker":"","text":"시뇨라가 신의 심장을 받았다. 종려가 모락스라는 사실은 알고 있었지만, 그 힘의 상징이 다른 손으로 넘어가는 일은 처음 보는 현실이었다. 문밖을 향해 누구의 이름도 외치지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_028","speaker":"타르탈리아","text":"나는 내 방식대로 움직이고 있다고 생각했는데, 뒤에서는 이미 합의가 돼 있었던 거군요. 적어도 언제부터 어디까지 알고 있었는지는 들을 수 있겠죠?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_029","speaker":"시뇨라","text":"네가 알아야 할 만큼은 알았어. 결과도 봤고. 여기서 네 기분까지 풀어 주는 건 내 일이 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_030","speaker":"나","text":"그 불만은 저도 있어요. 종려 씨, 왜 그 계약을 맺은 겁니까? 신의 심장을 넘길 만큼 뭘 받았어요?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_031","speaker":"종려","text":"이번 계약에는 그 이유와 내용을 밖에 밝히지 않겠다는 약속도 들어 있네. 자네가 겪은 위험을 가볍게 여겨서 말을 아끼는 것은 아니야.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_zhongli_032","options":[{"label":"그러면 저는 끝까지 모르는 채로 아픈 기억만 들고 나가겠네요. 그렇다고 제가 이해했다거나 괜찮다고는 말하지 않겠습니다. 그건 제 입으로도 거짓말이니까요.","id":"PRO_L04K2_zhongli_033","items":[{"k":"line","id":"PRO_L04K2_zhongli_034","speaker":"종려","text":"그렇게 받아들이겠네. 자네에게 없는 납득을 만들어 달라고 요구할 수는 없지. 다만 자네가 리월을 지키기 위해 한 일에 대한 감사까지 비밀로 둘 이유는 없네.","map":"MAP_LIYUE_HARBOR"}]},{"label":"지금 답 못 하는 질문은 그대로 남겨 둘게요. 설명 못 들은 자리에 제가 멋대로 이유를 채워 넣지는 않겠습니다. 대신 아직 납득 안 했다는 것도 같이 기억해 주세요.","id":"PRO_L04K2_zhongli_035","items":[{"k":"line","id":"PRO_L04K2_zhongli_036","speaker":"종려","text":"답을 얻지 못했다는 사실을 정확히 남기는 것도 중요하지. 침묵을 동의로 받아들이지는 않겠네. 자네가 리월을 지키기 위해 한 일에 대한 감사까지 비밀로 둘 이유는 없네.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_zhongli_037","speaker":"나","text":"타르탈리아, 황금옥에서 있었던 일 기억해? 나하고 싸웠고, 네가 밀리다가 바닥이 무너졌어. 너는 먼지 속으로 사라졌고 나는 깔렸다가 병사들이 꺼냈어. 그중에 기억나는 거 있어?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_038","speaker":"타르탈리아","text":"네가 황금옥에서 나와 싸웠다고? 처음 듣는 얘기야. 그 무렵이 끊겨 있는 건 나도 알아. 하지만 너랑 싸운 장면은 없어. 내가 밀렸다는 말까지 붙으니 더 직접 확인하고 싶어지는군. 다친 몸을 지금 상대하겠다는 뜻은 아니고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_039","speaker":"나","text":"그때 너는 내가 찾는 짐꾼 얘기를 해도 아무 관심이 없었어. 싸움을 즐기는 게 아니라 내가 어디까지 오는지만 기다리는 것 같았어. 지금 너는 그때하고 느낌이 달라. 본인도 모른다는 거야?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_040","speaker":"타르탈리아","text":"없는 기억을 꾸며서 맞장구쳐 줄 수는 없지. 네가 묘사하는 내가 좀 기분 나쁜 상대라는 건 알겠어. 누가 내 일에 손을 댄 건지, 내가 놓친 게 있는지부터 알아봐야겠군.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_041","speaker":"","text":"기억이 없다는 사람에게 기억하라고 소리쳐도 답이 생기지 않는다는 것은 이미 배웠다. 장록 앞에서 들은 말을 적 앞에서도 써야 한다는 사실이 썩 반갑지는 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_042","speaker":"나","text":"좋아. 기억나는 게 생기면 사람 보내. 나도 본 걸 안 봤다고 바꾸지는 않을 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_043","speaker":"타르탈리아","text":"그 정도면 얘기할 여지는 있네. 다 낫고 나면 한 판 하자. 잊은 싸움으로만 평가받는 건 재미없거든.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_zhongli_044","speaker":"나","text":"환자 앞에서 재경기 예약부터 잡는 거 봐. 지금은 예약 안 받아. 내 다음 목표는 밥집까지 내 다리로 가는 거야.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_152","text":"타르탈리아가 웃었다. 그 웃음을 보면서도 손을 내밀지는 않았다. 지금의 가벼움과 황금옥의 낯섦은 둘 다 기억해 두기로 했다. 오늘 당장 대답이 나올 질문을 모두 썼다는 것을 알았다."},{"k":"line","id":"PRO_L04K2_depart_001","speaker":"","text":"북국은행을 나와 사람들 사이에 섞여 천천히 걸었다. 이곳에서 같은 질문을 반복한다고 모든 답이 열릴 것 같지는 않았다. 내가 아는 이야기와 실제로 벌어진 일의 차이는 한 도시에서 시작해 한 도시에서 끝나는 것처럼 보이지 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_002","speaker":"나","text":"다음엔 이나즈마로 가야겠어. 거기서 답이 나온다고 장담은 못 하지만, 신을 만나 물을 길도 더 찾아봐야지. 이번엔 가기 전에 어디로 가는지도 남기고.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_003","speaker":"나","text":"'아는데'라는 말도 좀 줄이고.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_155","text":"바로 배를 찾아 달려가지 않았다. 치료소로 돌아와 여행 준비를 하고 싶다는 말을 군의관에게 먼저 꺼낼 차례였다. 황금옥에서 살아 나왔다고 그 뒤의 위험이 모두 나를 비껴가는 것은 아니었다."},{"k":"line","id":"PRO_L04K2_depart_004","speaker":"나","text":"이나즈마행 배편을 알아보려고요. 당장 떠나겠다는 건 아니에요. 항해 전에 어디까지 회복돼야 하는지 알려 주세요. 몸 괜찮다는 말을 제가 혼자 먼저 정하지는 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_005","speaker":"군의관","text":"그렇게 준비하시면 됩니다. 무거운 짐 메지 말고, 걷다가 어지럽거나 다리 감각이 달라지면 바로 돌아오세요. 출항 날짜가 정해지면 그 전에 다시 진료받으십시오.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_158","text":"장록에게는 다음 날 만나는 자리에서 여행할 뜻을 전하기로 했다. 그는 이제 기다릴 화물이 없는 사람이었고, 나는 새로 챙길 짐이 생긴 사람이었다. 서로의 일이 끝나야만 헤어질 수 있다고 붙들 이유는 없어졌지만, 말 없이 사라질 이유도 없었다."},{"k":"line","id":"PRO_L04K2_depart_006","speaker":"나","text":"저는 이나즈마 쪽으로 갈 준비를 하려고요. 아직 배도 안 정해졌고 들어갈 수 있는지도 알아봐야 해요. 당분간은 치료소에서 찾으시면 되고, 출항할 수 있게 되면 다시 인사드릴게요. 이번엔 소리 소문 없이 없어지지 않겠습니다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_007","speaker":"장록","text":"갈 곳을 정했군. 여기서 알아낸 게 다 끝났다는 얼굴은 아니지만, 붙잡고 있을 이유만 찾다 보면 평생 짐을 못 내리는 법이오. 내가 줄 만한 대단한 물건은 없소. 대신 배에 가져갈 짐은 한쪽으로 쏠리지 않게 싸시오. 그 어깨로 욕심내지 말고.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_depart_008","options":[{"label":"대단한 물건보다 그 말이 저한테는 더 필요한 것 같네요. 장록 씨도 다음 일 시작하기 전에 쉬세요. 허리 아픈 사람 둘이 서로 걱정하는 모양새가 됐네.","id":"PRO_L04K2_depart_009","items":[{"k":"line","id":"PRO_L04K2_depart_010","speaker":"장록","text":"허리는 내가 선배지. 당신은 다리부터 챙기시오. 다음에 리월 오면 물자 구역에 와서 이름 부르시오. 포대 뒤에서라도 대답할 테니.","map":"MAP_LIYUE_HARBOR"}]},{"label":"이름을 알고 헤어지니까 이상하게 덜 무섭네요. 또 아무 말 없이 사라지는 사람이 될까 봐 그게 제일 싫었거든요.","id":"PRO_L04K2_depart_011","items":[{"k":"line","id":"PRO_L04K2_depart_012","speaker":"장록","text":"이름 적은 종이 잃어버리지 마시오. 그거 하나면 어디서든 찾아올 수 있잖소. 다음에 리월 오면 물자 구역에 와서 이름 부르시오. 포대 뒤에서라도 대답할 테니.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"line","id":"PRO_L04K2_depart_013","speaker":"","text":"장록은 웃으며 어깨를 한 번 두드리려다 다친 곳을 보고 손을 거두었다. 대신 멀쩡한 쪽 팔을 가볍게 잡았다. 서로가 살아 돌아온 이유는 알지 못했다. 그러나 누가 먼저 찾았는지, 다음에는 어디서 부르면 되는지는 알고 있었다. 그 정도를 가진 채 헤어지는 것도 가능한 일이었다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_014","speaker":"","text":"각청은 남십자 함대가 이나즈마 방면 항해를 상의할 수 있는 창구를 알려 주었다. 먼저 몬드에도 소식을 남겨 두기로 했다.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_depart_015","options":[{"label":"진한테 편지 보낼게. 리월 위기는 막았고 나는 살아서 치료 중이라고. 황금옥 일하고 기억 공백은 내가 본 범위만 적을게. 범인 알아낸 것처럼은 안 보내.","id":"PRO_L04K2_depart_016","items":[{"k":"line","id":"PRO_L04K2_depart_017","speaker":"각청","text":"길드 전달편에 접수하면 돼. 너 기다리는 사람한테는 먼저 알려 주는 게 좋지. 네가 여기서 사람 못 찾아서 답답했던 거 생각하면.","map":"MAP_LIYUE_HARBOR"}]},{"label":"편지 첫 줄은 살아 있고 치료받고 있다는 말로 할게. 그다음에 실제로 본 일만 적고. 다음 행선지 알아보는 중이라는 걸 벌써 출항한 것처럼 보내지는 않을 거야.","id":"PRO_L04K2_depart_018","items":[{"k":"line","id":"PRO_L04K2_depart_019","speaker":"각청","text":"그렇게 구분해서 적으면 받는 쪽도 네가 어디 있는지 알겠지. 회신 받을 주소도 빠뜨리지 마. 길드 전달편에 접수하면 돼.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K2_166","text":"길드에서 편지를 작성해 맡겼다. 전하려던 소식과 당분간 연락받을 치료소를 적었고, 전달 담당자가 몬드행으로 접수했다. 이번에는 어디로 갔는지도 모를 사람으로 남지 않도록 내 쪽에서 할 일을 마쳤다."},{"k":"line","id":"PRO_L04K2_depart_020","speaker":"나","text":"네가 나를 처음 못 알아봤을 때 되게 억울했어. 내가 겪은 일을 나만 떠안은 것 같아서. 그런데 그 뒤에 사람도 찾아 줬고 내 말 듣고 움직였잖아. 고마워, 각청.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_021","speaker":"각청","text":"그렇게 말해 주면 나도 듣기 편하지. 그 닷새는 못 돌려줘. 대신 오늘부터 생긴 건 내가 갖고 있을게.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_022","speaker":"각청","text":"그러니까 돌아오면 그냥 이름 불러. 그때 내가 \"우리 어디서 만났지?\" 하면 그땐 진짜 화내도 돼.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_023","speaker":"나","text":"그 말 녹음해 두고 싶네.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_024","speaker":"각청","text":"뭐?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_025","speaker":"나","text":"아니야. 알았어. 이름 부를게.","map":"MAP_LIYUE_HARBOR"},{"k":"keep","id":"ISK_L04_K2_169","text":"내 이름을 다시 소개하지 않았다. 각청이 이미 알고 있는 이름으로 고개를 끄덕였다. 잊힌 인연을 처음부터 되돌릴 수는 없었어도 다음에 만날 사람으로 남을 수는 있었다. 그녀는 도시의 일로 돌아갔고, 나는 항구의 연락 창구로 향했다."},{"k":"line","id":"PRO_L04K2_depart_026","speaker":"나","text":"이나즈마 방면 배편을 상담하고 싶습니다. 각청한테 이쪽으로 문의하라고 소개받았어요. 지금 치료 중이고요. 출항 일정하고 승선 조건을 먼저 듣고, 입국 문제도 어떻게 준비해야 하는지 알고 싶어요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_027","speaker":"남십자 선원","text":"뜻은 선장님께 전달하겠습니다. 다만 배에 자리가 있는 것과 이나즈마에 들어갈 수 있는 것은 별개입니다. 일정이 정해지면 어디로 연락드리면 됩니까?","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_028","speaker":"나","text":"항구 치료소요. 연락 오기 전에 무작정 배에 올라가 자리 맡지는 않을게요. 남의 짐처럼 실려 가고 싶지도 않고요.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_029","speaker":"","text":"접수가 끝난 것을 확인하고 치료소로 돌아왔다. 길에서 군옥각이 있던 하늘을 보았다. 그 빈자리는 도시를 구한 값이 무엇인지 기억하게 했지만, 남아 있는 길과 사람까지 가리지는 않았다.","map":"MAP_LIYUE_HARBOR"},{"k":"line","id":"PRO_L04K2_depart_030","speaker":"정산 담당자","text":"돌아오셨군요. 리월 방어에 참여하고 위험을 전달한 공적에 대한 정산입니다. 1,800모라, 영웅의 경험 두 개와 모험가의 경험 세 개를 지급합니다. 확인하고 받아 주십시오.","map":"MAP_LIYUE_HARBOR"},{"k":"choice","group":"G_PRO_L04K2_depart_031","options":[{"label":"확인했습니다. 1,800모라, 영웅의 경험 두 개, 모험가의 경험 세 개. 받겠습니다. 남의 화물 끝나는 걸 보고 왔더니 이제 제 몫 확인할 차례네요.","keep":"ISK_L04_K2_176","items":[{"k":"line","id":"PRO_L04K2_depart_032","speaker":"정산 담당자","text":"수령 기록에 남겼습니다. 인계 끝나는 걸 지켜본 분이니 절차는 익숙하시겠군요.","map":"MAP_LIYUE_HARBOR"}]}]},{"k":"keep","id":"ISK_L04_K2_177","text":"받은 물품을 치료소의 짐 옆에 정리했다. 장록은 자기 일을 마쳤고, 각청은 도시를 되돌리고 있었으며, 응광과 선인들은 다음 경계를 맡았다. 나도 이곳에 남길 연락처와 떠날 이유를 정했다. 죽음과 기억의 의문은 풀리지 않았다. 그러나 리월에서 해야 했던 일은 사람들을 살아 있는 다음 하루로 돌려놓는 곳까지 왔다. 다음 행선지는 이나즈마였다."},{"k":"keep","id":"ISK_L04_K2_END"}],"edits":[{"k":"text","id":"V141_BEFORE_ISK_L04_K2_001_0","text":"손앞의 작은 파편에 손가락을 걸었다. 들보는 건드리지 않았다."},{"k":"text","id":"V141_AFTER_ISK_L04_K2_001_0","text":"파편이 옆으로 굴렀다. 좁은 틈으로 빛이 들고, 흙 묻은 손 하나가 나타났다."},{"k":"text","id":"V141_BEFORE_ISK_L04_K2_091_0","text":"향릉과 행추가 소식을 듣고 물자 구역까지 찾아왔다. 지금 나눌 이야기는 남은 짐의 수량보다, 함께 겪고 돌아온 일이었다."},{"k":"text","id":"V141_AFTER_ISK_L04_K2_091_0","text":"자, 이건 기다리지 말고 지금 먹기! 아저씨 것도 있어요!"},{"k":"text","id":"V141_AFTER_ISK_L04_K2_091_1","text":"자네가 끝까지 봤다는 그 짐, 내용물이 책이면 한 권 빌려도 되겠나?"},{"k":"text","id":"V141_AFTER_ISK_L04_K2_091_2","text":"그건 주인한테 말해. 난 이름 제대로 물어본 것만으로 오늘 할 일 다 했어."}]},{"id":"ISK_M01","entry":"ISK_M01_E001","items":[{"k":"keep","id":"ISK_M01_E001"},{"k":"keep","id":"ISK_M01_E002","text":"눈을 뜨자 하늘이 너무 파랬다. 천장이 있어야 할 자리에 구름이 지나간다. 등 밑에는 풀. 손끝에는 이슬."},{"k":"line","id":"PRO_M01_깨어남_001","speaker":"","text":"월요일 아침이면 들려야 할 알람 소리가 없다. 대신 멀리서 풍차 돌아가는 소리가 난다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_002","speaker":"나","text":"…알람 안 울렸네. 지각이다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_003","speaker":"","text":"몸을 일으켜 주위를 본다. 호수, 언덕, 길. 그림엽서 같은 풍경이 사방으로 펼쳐져 있다. 생각을 정리하기도 전에 수풀이 흔들렸다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_004","speaker":"","text":"둥글고 끈적한 것이 풀 사이에서 튀어나왔다. 뒤이어 나무 가면을 쓴 작은 녀석이 소리를 지르며 곤봉을 들어 올린다.","map":"MAP_MOND_PLAINS"},{"k":"choice","group":"G_PRO_M01_깨어남_005","options":[{"label":"뭐야, 귀엽네. 만져도 되는 거야?","keep":"ISK_M01_M002","items":[{"k":"line","id":"PRO_M01_깨어남_006","speaker":"","text":"손을 뻗었다. 가면 쪽에서 곤봉이 날아왔다. 간신히 손을 거뒀다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_007","speaker":"나","text":"아, 안 되는 거구나. 알았어, 알았어.","map":"MAP_MOND_PLAINS"}]},{"label":"저거… 지금 진짜로 움직이는 거지?","keep":"ISK_M01_M003","items":[{"k":"line","id":"PRO_M01_깨어남_008","speaker":"","text":"다리가 먼저 뒷걸음질쳤다. 머리는 아직 이불 속에 있고, 몸만 여기 있다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_009","speaker":"나","text":"그래, 알았어. 진짜구나. 진짜네.","map":"MAP_MOND_PLAINS"}]},{"label":"일단 떨어지자. 저 눈, 나 보고 있는 거 맞지?","keep":"ISK_M01_M004","items":[{"k":"line","id":"PRO_M01_깨어남_010","speaker":"","text":"거리를 벌리며 뒤로 물러났다. 뒤는 비탈이었다. 더 물러날 곳이 없다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_011","speaker":"나","text":"비탈이야. 이건 좀 치사하잖아.","map":"MAP_MOND_PLAINS"}]}]},{"k":"line","id":"PRO_M01_깨어남_012","speaker":"","text":"곤봉이 머리 위로 올라오는 순간, 어디선가 바람을 가르는 소리가 났다. 불붙은 화살이 가면 바로 앞 땅에 박히고, 녀석은 비명을 지르며 달아났다. 끈적한 것은 한 번 더 튀어 오르다가 두 번째 화살에 터졌다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_013","speaker":"엠버","text":"괜찮아요? 다친 데 없죠? 저쪽으로 더 가면 안 돼요, 거기 비탈이거든요!","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_014","speaker":"","text":"붉은 옷에 활을 든 사람이 언덕을 뛰어 내려왔다. 머리에 묶은 리본, 허리에 매달린 토끼 인형, 토끼 백작. 불붙은 화살을 쏘는 사람치고는 얼굴이 너무 밝았다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_015","speaker":"엠버","text":"페보니우스 기사단 정찰기사 엠버! 이 근처는 요즘 마물이 늘어서 순찰 중이었어요. 운이 좋았네요. 일어날 수 있어요?","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_016","speaker":"나","text":"일어날 수는 있는데… 여기 어디예요? 제가 사는 데서는 저런 게 길에서 안 튀어나와서요.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_017","speaker":"엠버","text":"네, 몬드 성 바로 앞 평원이에요. 어디서 오셨어요? 옷차림이 이 근처 사람 같지는 않은데.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_018","speaker":"","text":"대답이 바로 나오지 않았다. 회사 이름을 대 봐도 알아들을 사람이 없다. 입을 열었다가 다시 다물었다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_019","speaker":"엠버","text":"음, 많이 놀라셨나 보다. 천천히 해도 돼요. 그럼 이름부터! 뭐라고 부르면 돼요?","map":"MAP_MOND_PLAINS"},{"k":"keep","id":"ISK_M01_NAME_INPUT","as":"NARRATION","text":"이름을 말했다. 엠버는 한 번 따라 말하고, 고개를 끄덕였다."},{"k":"line","id":"PRO_M01_깨어남_020","speaker":"엠버","text":"{PLAYER_NAME}. 좋아, 외웠어요. 그리고 말 편하게 해도 돼요. 나도 그럴게. 성까지 같이 가자, 여기 서 있으면 또 와.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_021","speaker":"","text":"엠버가 앞장서서 길로 내려간다. 걷는 동안 그녀는 자꾸 뒤를 돌아본다. 넘어질 사람처럼 보이는 모양이다. 틀린 판단은 아니다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_022","speaker":"엠버","text":"그래서, 어디서 온 거야? 리월? 아니면 더 먼 데? 배 타고 왔으면 항구 쪽에 짐이 있을 텐데.","map":"MAP_MOND_PLAINS"},{"k":"choice","group":"G_PRO_M01_깨어남_023","options":[{"label":"다른 세계에서 온 것 같아. 원래는 회사 다녔는데.","keep":"ISK_M01_A017","items":[{"k":"line","id":"PRO_M01_깨어남_024","speaker":"엠버","text":"다른… 세계? 음. 그게 어디쯤이야? 스네즈나야보다 멀어?","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_025","speaker":"나","text":"어디든 거기보단 멀 거야. 월급은 더 적고.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_026","speaker":"엠버","text":"뭔지는 몰라도 좋은 데는 아니었나 보다. 알았어, 일단 그렇게 적어 둘게. 머릿속에.","map":"MAP_MOND_PLAINS"}]},{"label":"어떻게 왔는지만 기억이 없어. 저 언덕에서 깼어.","keep":"ISK_M01_A018","items":[{"k":"line","id":"PRO_M01_깨어남_027","speaker":"엠버","text":"저기서? 밤새 저기 누워 있었던 거면 큰일 날 수도 있었어. 다른 건 기억나?","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_028","speaker":"나","text":"다른 건 다 기억나. 그래서 더 이상해.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_029","speaker":"엠버","text":"그럼 다행인 쪽이야. 머리 다친 사람은 보통 반대거든.","map":"MAP_MOND_PLAINS"}]},{"label":"나도 아직 설명을 못 하겠어. 조금만 있다 말해도 될까?","keep":"ISK_M01_A019","items":[{"k":"line","id":"PRO_M01_깨어남_030","speaker":"엠버","text":"그래, 괜찮아. 무리해서 말할 필요 없어. 성에 가서 물 좀 마시고 나서 해.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_031","speaker":"나","text":"그 물, 공짜지?","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_032","speaker":"엠버","text":"그 정도는 기사단이 사 줄게!","map":"MAP_MOND_PLAINS"}]}]},{"k":"line","id":"PRO_M01_깨어남_033","speaker":"","text":"길이 꺾이는 곳에서 성벽이 보였다. 멀리 풍차와 성당 지붕. 걸음이 저절로 멎었다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_034","speaker":"엠버","text":"저게 몬드 성이야. 처음 보는 사람은 다들 저기서 한 번 멈춰. 아까 몬드라고 했을 때 표정이 좀 이상하던데, 들어 본 이름이야?","map":"MAP_MOND_PLAINS"},{"k":"choice","group":"G_PRO_M01_깨어남_035","options":[{"label":"몬드… 그 이름, 알아.","keep":"ISK_M01_A031","items":[{"k":"line","id":"PRO_M01_깨어남_036","speaker":"","text":"아는 정도가 아니다. 저 성당 앞 광장에서 몇 번이나 뛰어다녔는지 셀 수도 없다. 다만 그때는 손가락으로 움직였고, 지금은 다리로 서 있다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_037","speaker":"나","text":"알아. 아는데… 아는 거랑 여기 서 있는 건 꽤 다른 일이구나.","map":"MAP_MOND_PLAINS"}]},{"label":"몬드? 처음 듣는 이름인데.","keep":"ISK_M01_A030","items":[{"k":"line","id":"PRO_M01_깨어남_038","speaker":"","text":"정말 처음 듣는 이름이었다. 세상 도시 이름을 다 아는 건 아니지만, 저런 풍차가 있는 도시라면 어디서든 한 번쯤 사진으로 봤을 것이다. 못 봤다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_039","speaker":"나","text":"처음 들어. 유명한 데야? 미안, 지리는 원래 자신 없었어.","map":"MAP_MOND_PLAINS"}]}]},{"k":"keep","id":"ISK_M01_O001","text":"그럴 수 있지! 몬드는 바람과 자유의 도시… 라고 해도 모르겠구나. 좋아, 안내는 내가 할게. 성까지 가면서 하나씩. 뭐부터 알고 싶어?"},{"k":"keep","id":"ISK_M01_K001","text":"아는 이름이야? 그런데 안다는 사람 얼굴이 왜 더 하얘지는데. 어디서 들었어?"},{"k":"keep","id":"ISK_M01_O002","text":"엠버가 걸음을 늦추고 길 가장자리로 자리를 옮겼다. 활을 등에 걸치면서 대답을 기다린다. 재촉하지는 않는다."},{"k":"choice","group":"G_PRO_M01_깨어남_040","options":[{"label":"우리 세계에선 여기가 게임이었어. 「원신」이라고.","keep":"ISK_M01_K002","items":[{"k":"line","id":"PRO_M01_깨어남_041","speaker":"엠버","text":"게임? 사람들이 놀이로 하는 그 게임? 몬드가 거기 나와?","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_042","speaker":"나","text":"나오지. 너도 나와. 토끼 백작까지 그대로야.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_043","speaker":"엠버","text":"토끼 백작까지?! …그건 좀 소름 돋는데. 아니, 잠깐. 그럼 내가 다음에 뭐 할지도 알아?","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_044","speaker":"나","text":"대충은. 그런데 방금 나한테 활 쏴 준 건 몰랐어. 거기선 그 장면 없거든.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_045","speaker":"엠버","text":"그럼 그 게임이 다 아는 건 아니네. 좋아, 그렇게 생각할게. 나는 내 마음대로 움직일 거니까.","map":"MAP_MOND_PLAINS"}]},{"label":"그건 조금만 있다 말할게. 나도 정리가 안 돼서.","keep":"ISK_M01_K003","items":[{"k":"line","id":"PRO_M01_깨어남_046","speaker":"엠버","text":"알았어. 억지로 묻진 않을게. 대신 위험한 걸 알고 있으면 그것만은 바로 말해 줘.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_047","speaker":"나","text":"그건 약속할 수 있어. 위험한 건 나도 싫거든.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_048","speaker":"엠버","text":"그거면 충분해.","map":"MAP_MOND_PLAINS"}]},{"label":"이름만 기억나. 자세한 건 흐릿해.","keep":"ISK_M01_K009","items":[{"k":"line","id":"PRO_M01_깨어남_049","speaker":"엠버","text":"이름만? 음, 그래도 아는 게 하나 있는 거네. 처음 오는 사람보단 나아.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_050","speaker":"나","text":"그래. 처음 오는 사람보다 아주 조금 나은 사람. 그게 나야.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_051","speaker":"엠버","text":"그 조금을 늘려 보자. 안내는 내가 할게.","map":"MAP_MOND_PLAINS"}]},{"freeze":"ISK_M01_K010"},{"label":"기사단은 어떤 곳이야? 그런 것부터 알려 줘.","keep":"ISK_M01_O003","items":[{"k":"line","id":"PRO_M01_깨어남_052","speaker":"엠버","text":"페보니우스 기사단! 몬드를 지키는 기사들이야. 성 안팎을 순찰하고, 마물을 쫓고, 곤란한 사람을 돕지. 방금 내가 한 것처럼!","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_053","speaker":"나","text":"그럼 아까 그건 업무였구나. 고맙다는 말 대신 평가서라도 써 줄까.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_054","speaker":"엠버","text":"평가서는 됐고, 별 다섯 개만 기억해 둬. 문제 생기면 이 표식 달린 사람한테 말 걸면 돼.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_055","speaker":"","text":"엠버가 옷의 기사단 표식을 짚어 보였다. 낯선 이름 하나가 처음으로 쓸모를 가졌다. 곤란하면 찾을 표시.","map":"MAP_MOND_PLAINS"},{"k":"keep","id":"ISK_M01_J001R","text":"성문으로 이어지는 길에서 들꽃이 흔들렸다. 멀리 바위 위에 가면 쓴 그림자가 둘. 아까 그것들이다."},{"k":"line","id":"PRO_M01_깨어남_056","speaker":"엠버","text":"아, 또 나왔네. 괜찮아. 저 거리면 쫓아오지도 않아.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_057","speaker":"","text":"엠버가 활을 들어 바위 위를 겨눴다. 쏘지는 않았다. 그림자들이 먼저 사라졌다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_058","speaker":"나","text":"쏘지도 않았는데 가네. 평판이 좋구나.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_059","speaker":"엠버","text":"가면 쓴 애들도 눈치는 있어. 자, 성문이 코앞이야. 오늘은 더 안 뛰어도 돼.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M01_깨어남_060","speaker":"나","text":"그 말, 꼭 지켜 줘.","map":"MAP_MOND_PLAINS"},{"k":"keep","id":"ISK_M01_UT001","text":"성문 안으로 들어서자 빵 냄새와 수레바퀴 소리가 밀려왔다. 높은 풍차 아래로 가게와 집이 이어지고, 계단 위로 또 지붕이 겹친다. 간판은 하나도 못 읽겠는데 빵 냄새만은 알겠다."},{"k":"line","id":"PRO_M01_성문_U_001","speaker":"엠버","text":"어때? 바깥보다 훨씬 북적이지?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_U_002","speaker":"나","text":"북적이는 건 알겠어. 그런데 간판 글자, 저거 내가 못 읽는 거야, 아니면 원래 저렇게 생긴 거야?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_U_003","speaker":"엠버","text":"…원래 저렇게 생겼어. 괜찮아, 길 잃으면 위만 보고 올라가지 말고 기사단 표식 찾아서 물어봐.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_U_004","speaker":"","text":"엠버가 광장 한쪽의 기사에게 손을 들었다. 기사는 이쪽의 낯선 차림을 한 번 보고 엠버에게 고개를 끄덕였다. 아는 사람이 한 명뿐인 채로 도시에 들어왔다. 그 한 명이 바빠 보여서 더 불안했다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_U_005","speaker":"엠버","text":"먼저 본부에 가자. 네가 깨어난 자리도 알려 둘 거야. 다른 순찰대가 뭔가 봤을 수도 있잖아. 돌아갈 길을 찾아 준다고 약속은 못 하지만, 혼자 언덕을 뒤지게 두지는 않을게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_U_006","speaker":"나","text":"그 말 녹음해 두고 싶네.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_U_007","speaker":"엠버","text":"녹음이 뭔지는 모르겠지만, 두 번 말해 줄 수는 있어.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_001","speaker":"","text":"긴 계단 끝에 엠버의 옷에서 본 표식이 다시 나타났다. 기사단 본부. 안으로 들어서자 푸른 머리에 안대를 한 남자가 복도 기둥에 기대 있다가 이쪽을 봤다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_002","speaker":"케이아","text":"엠버, 오늘은 돌아오는 길에 손님까지 모셔 왔네. 음… 짐보다 질문이 더 많아 보이는 손님인데.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_003","speaker":"엠버","text":"케이아 선배! 들어오자마자 그러지 마세요. 아까 진짜 위험했단 말이에요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_004","speaker":"케이아","text":"그랬어? 그럼 인사부터 하지. 페보니우스 기사단 기병대장 케이아. 안으로 들어와. 엠버가 보고하는 동안 앉아서 쉬어.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_005","speaker":"","text":"케이아는 웃고 있었지만 시선은 흙 묻은 소매와 걸음걸이를 짧게 훑었다. 면접관 눈이다. 어디서든 저런 눈은 알아본다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_006","speaker":"나","text":"질문이 많아 보인다는 건 맞아요. 첫 질문은 「의자 어디 있어요」고요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_007","speaker":"케이아","text":"합격이야. 저기 앉아.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M01_UT_ORIGIN_REAL","text":"케이아 선배, 이쪽은 {PLAYER_NAME}. 외곽에서 슬라임한테 쫓기고 있었어요. 다른 세계에서 왔다는데, 어떻게 왔는지는 기억이 없대요. 여기 사정도 전혀 모르고요."},{"k":"keep","id":"ISK_M01_UT_ORIGIN_GAP","text":"케이아 선배, 이쪽은 {PLAYER_NAME}. 외곽에서 구조했어요. 여기까지 온 과정만 기억이 없대요. 여기 사정은 전혀 몰라요."},{"k":"keep","id":"ISK_M01_UT_ORIGIN_DEFER","text":"케이아 선배, 이쪽은 {PLAYER_NAME}. 외곽에서 슬라임한테 쫓기던 걸 도왔어요. 출신 얘기는 아직 정리가 안 됐대요. 여기 사정도 모르는 것 같아서 데려왔어요."},{"k":"keep","id":"ISK_M01_EX_U_ORIGIN_REAL","text":"다른 세계라… 몬드보다 훨씬 먼 데서 헤매다 왔군. 오는 길이 기억 안 나면 돌아가는 길도 곤란하겠어. 지금 다그쳐 봐야 소용없겠네."},{"k":"keep","id":"ISK_M01_EX_U_ORIGIN_GAP","text":"오는 과정만 비었다… 엠버, 발견한 자리는 따로 알려 줘. 그 근처를 지난 순찰이 있었는지 알아볼게."},{"k":"keep","id":"ISK_M01_EX_U_ORIGIN_DEFER","text":"말하기 어려운 사정은 누구에게나 있지. 다만 누가 뒤쫓고 있다면 그건 미리 말해 줘. 이 문 앞에서 마주치고 싶진 않거든."},{"k":"line","id":"PRO_M01_본부_U_008","speaker":"케이아","text":"알겠어. 오늘 하루에 대해 아직 말할 수 있는 게 많지 않은 모양이군. 그럼 쉬운 것부터. 물은 마셨어?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_009","speaker":"엠버","text":"제가 가져올게요. 그동안 어려운 질문 하지 마세요!","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_010","speaker":"케이아","text":"물어볼 것도 물 한 잔 뒤로 미뤘잖아. 나도 손님 대접 정도는 한다고.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_011","speaker":"","text":"엠버가 복도 끝으로 사라지자 케이아는 의자 옆 서류 뭉치를 치워 자리를 넓혔다. 능청스러운 말투와 달리 손은 빨랐다. 종이에는 모르는 지명과 길을 잇는 선이 빼곡했다. 하나도 못 읽었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_012","speaker":"","text":"열린 문 안에서 금발의 여성이 기사를 배웅하고 있었다. 돌아오는 엠버를 불러 짧게 듣고는 이쪽으로 걸어온다. 시선이 낯선 옷보다 먼저 긁힌 손바닥에 멎었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_013","speaker":"진","text":"단장 대행 진입니다. 엠버에게 들었습니다. 밖에서 위험한 일을 겪으셨군요. 손은 괜찮으신가요?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_014","speaker":"나","text":"손은 괜찮아요. 안 괜찮은 건 나머지 전부고요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_015","speaker":"진","text":"그럼 나머지부터 여쭤보죠. {PLAYER_NAME} 님, 지금 가장 곤란한 것은 무엇인가요? 기억나지 않는 일을 억지로 설명하실 필요는 없습니다.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M01_본부_U_016","options":[{"label":"돌아갈 길도 막막하지만, 당장 밥이랑 잘 곳부터요. 빈손이라서요.","keep":"ISK_M01_EX_U_HQ_C1","items":[{"k":"line","id":"PRO_M01_본부_U_017","speaker":"진","text":"우선 오늘 쉴 곳을 알아보겠습니다. 돌아갈 방법은 식사를 하고 몸을 추스른 뒤에 찾아도 늦지 않아요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_018","speaker":"케이아","text":"순서가 분명해서 좋네. 엠버가 경치부터 소개했으면 배만 더 고플 뻔했군.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_019","speaker":"엠버","text":"성부터 들어와야 밥도 먹죠! …그래도 걸으면서 물어볼 걸 그랬네. 배고프면 참지 말고 말해.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_020","speaker":"나","text":"참을 생각 없었어. 지금 말하는 거야.","map":"MAP_MOND_CITY"}]},{"label":"여긴 다들 싸울 줄 알아요? 저는 평범하게 일만 했는데. 검 쥐여 주시면 꽤 곤란할 것 같아서요.","keep":"ISK_M01_EX_U_HQ_C2","items":[{"k":"line","id":"PRO_M01_본부_U_021","speaker":"케이아","text":"그랬다면 우리 일이 훨씬 줄었겠지. 빵집 주인도, 꽃 파는 사람도 각자 할 일이 있어. 여기 산다고 다 검을 드는 건 아니야.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_022","speaker":"엠버","text":"나도 활을 이렇게 쓰기까지 연습 많이 했어. 처음 만난 슬라임한테까지 실력 증명하려고 덤빌 필요는 없어!","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_023","speaker":"진","text":"무기부터 권하지는 않겠습니다. 무엇을 하실 수 있는지 천천히 알아봐도 괜찮습니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_024","speaker":"나","text":"다행이네요. 잘하는 게 복사기 고치기랑 야근인데, 둘 다 여기선 쓸모가 없을 것 같아서.","map":"MAP_MOND_CITY"}]}]},{"k":"line","id":"PRO_M01_본부_U_025","speaker":"엠버","text":"이름을 한꺼번에 너무 많이 들었지? 진 단장, 케이아 선배, 그리고 나. 나머지는 천천히 외워도 돼.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_026","speaker":"케이아","text":"길을 잃으면 엠버 이름은 기억해 두는 게 좋을 거야. 몬드에서 이만큼 열심히 안내해 줄 사람도 드물거든.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_027","speaker":"엠버","text":"그런 칭찬을 하면서 또 안내 일을 떠넘기려는 건 아니죠?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_028","speaker":"케이아","text":"들켰나.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_029","speaker":"","text":"탁자 위 물잔에 가느다란 물결이 생겼다. 진이 말을 멈췄다. 복도를 달리던 발소리가 급해지고, 창밖의 햇빛이 거대한 그림자 아래로 사라졌다. 창틀이 안쪽으로 휘는 듯 울렸다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_030","speaker":"진","text":"창문에서 떨어지세요. 케이아, 바깥 상황을 확인해. 엠버는 이분과 복도 안쪽으로.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_031","speaker":"","text":"창 너머로 비늘과 날개가 스쳤다. 건물보다 큰 것이 하늘을 막았다. 걸음이 멎었다. 엠버가 팔을 잡아끌어서야 발이 떨어졌다. 문밖에서 「드발린」이라는 외침이 터졌다. 뭔지 모르는 이름이었다. 소매를 붙잡은 손에 저절로 힘이 들어갔다.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M01_본부_U_032","options":[{"label":"저게 뭐야? 성 안으로 들어오는 거야? 설명은 나중에 들을 테니까 지금 어디로 가야 하는지만 말해 줘. 네 소매는 잠깐 빌릴게.","keep":"ISK_M01_UT010_SAY","items":[]}]},{"k":"line","id":"PRO_M01_본부_U_033","speaker":"엠버","text":"저 용은 드발린이야. 설명은 나중에. 지금은 이쪽, 창문 없는 벽으로. 천천히 숨 쉬어. 나 따라 하면 돼.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M01_본부_U_034","options":[{"label":"여기 있으면… 밖보다는 안전한 거지?","keep":"ISK_M01_UT012","items":[{"k":"line","id":"PRO_M01_본부_U_035","speaker":"엠버","text":"응, 바깥보다 안전해. 벽도 두껍고, 더 안쪽으로 옮길 길도 있어. 움직여야 하면 내가 먼저 말할게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_036","speaker":"","text":"엠버가 가리킨 복도 안쪽을 눈으로 확인했다. 도망칠 길을 알자 붙잡을 것이 하나 생긴 것 같았다. 그래도 벽이 울릴 때마다 어깨가 저절로 움츠러들었다.","map":"MAP_MOND_CITY"}]},{"label":"엠버. 지금은 혼자 두지 마.","keep":"ISK_M01_UT013","items":[{"k":"line","id":"PRO_M01_본부_U_037","speaker":"엠버","text":"안 가. 여기 있을게. 내 목소리 들리지? 나 보고 숨 쉬어. 한 번에 크게 들이마시지 말고.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_038","speaker":"","text":"엠버가 옆에 쪼그려 앉았다. 창문이 흔들리는 소리보다 가까운 목소리에 집중했다. 쥐고 있던 소매를 조금씩 놓았지만, 손끝의 떨림은 멎지 않았다.","map":"MAP_MOND_CITY"}]}]},{"k":"line","id":"PRO_M01_본부_U_039","speaker":"","text":"케이아가 웃음기 없는 얼굴로 복도 끝을 가리키고, 진은 뛰어 들어온 기사의 말을 듣자마자 다른 사람을 불렀다. 조금 전까지 농담하던 세 사람의 목소리가 지시로 바뀌었다. 그 목소리가 또렷해서, 그걸 세는 것으로 버텼다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_040","speaker":"케이아","text":"정문 앞에 사람 세우지 마. 안으로 들여보내고, 복도는 비워 둬. 창문 깨진 쪽은 아무도 접근시키지 말고.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_041","speaker":"진","text":"외곽에서 들어오는 사람도 받아 줘. 다친 사람이 있으면 먼저 알려. 엠버, 그쪽은?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_042","speaker":"엠버","text":"괜찮아요! 여기서 기다리고 있어요!","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_043","speaker":"","text":"엠버가 다시 이쪽을 보고 웃어 보이려다, 벽이 또 울리자 시선이 위로 갔다. 그녀도 소리를 세고 있었다. 그래서 그다음 말이 그냥 위로가 아니라는 걸 알았다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_044","speaker":"엠버","text":"방금보다 가까워졌어. 몸 더 낮추자. 괜찮아, 내가 보고 있어.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_045","speaker":"","text":"벽에 등을 붙이고 웅크렸다. 발소리, 짧은 지시, 문 닫히는 소리. 밖에서 뭔가 무너지는 소리. 이 사람들은 그걸 하나씩 해내며 바깥의 굉음을 견뎠다. 나는 숫자만 셌다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_046","speaker":"","text":"소란이 잦아들어도 아무도 곧바로 일어나라고 하지 않았다. 한참 뒤 바깥을 확인한 기사가 진에게 보고했다. 그제야 복도에서 낮은 숨소리가 몇 번 새어 나왔다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_047","speaker":"진","text":"드발린은 성 상공에서 물러났습니다. 파손된 건물과 통행로를 확인하고 있어요. 밖으로 나가는 건 확인이 끝난 뒤에 하죠.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M01_EX_U_FEAR_RECALL_A","text":"손 조금만 펴 봐. …응, 천천히. 아까 나가는 길을 먼저 봐 뒀지? 겁이 나도 어디로 움직일지 확인한 건 잘한 거야. 다음에도 그렇게 하면 돼."},{"k":"keep","id":"ISK_M01_EX_U_FEAR_RECALL_B","text":"손 조금만 펴 봐. …응, 천천히. 당연히 옆에 있어야지. 네가 내 소매를 꽉 잡고 있는데 혼자 나갈 수도 없었어. 이제 손에 힘 좀 빼도 돼."},{"k":"line","id":"PRO_M01_본부_U_048","speaker":"","text":"엠버가 빈 잔을 가져가 새 물을 채웠다. 받아 쥐자 손바닥에 남은 손톱 자국이 보였다. 물을 마셨다. 문이 조금 크게 닫힐 때마다 몸이 먼저 굳었다. 진이 책상으로 돌아오자 잔을 내려놓고 그녀를 봤다.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M01_본부_U_049","options":[{"label":"방금 그 용, 또 와요? 다들 어디로 뛰어야 할지 아는 걸 보니 처음도 아닌 것 같은데. 경보 울리면 어디로 피하는지부터 알려 주세요. 다음엔 멍하니 하늘 보고 서 있긴 싫어요.","keep":"ISK_M01_UT022_SAY","items":[]}]},{"k":"line","id":"PRO_M01_본부_U_050","speaker":"케이아","text":"첫날부터 이렇게 요란한 환영을 할 생각은 없었는데. …괜찮아, 억지로 웃을 필요는 없어. 나도 방금 그 소리는 반갑지 않았으니까.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_051","speaker":"엠버","text":"드발린은 원래 몬드를 지키던 용이야. 그러니까… 원래부터 저렇게 성을 공격하던 건 아니야.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_052","speaker":"진","text":"왜 이런 일이 벌어지는지 알아보고 있습니다. 약속드릴 수 있는 건 조사를 멈추지 않겠다는 것, 그리고 다시 위험해지면 사람들을 보호하겠다는 것입니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_053","speaker":"나","text":"도시를 지키던 용이 도시를 부순다. …여기선 그게 보통인 거예요, 아니면 여기서도 이상한 거예요?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_054","speaker":"진","text":"이상한 겁니다. 그래서 알아보고 있습니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_055","speaker":"나","text":"다행이네요. 이게 보통이면 오늘 밤은 안 잘 생각이었어요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_056","speaker":"엠버","text":"몬드가 매일 이렇진 않아. 오늘 좋은 데부터 보여 주고 싶었는데… 순서가 좀 엉망이 됐네.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_057","speaker":"진","text":"통행할 수 있는 길이 확인됐습니다. 다만 오늘은 성 밖으로 나가지 않는 편이 좋겠어요. 갈 곳이 없다고 들었습니다. 우선 기사단에서 1,000모라를 지원해 드리겠습니다. 오늘 필요한 식사와 몸을 보호할 것부터 마련하세요.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M01_EX_U_AID_PRACTICAL","text":"아까 말씀하신 식사와 잠자리도 엠버와 함께 알아보세요. 돌아갈 길을 찾는 동안 버틸 곳이 있어야 하니까요."},{"k":"keep","id":"ISK_M01_EX_U_AID_CAUTIOUS","text":"싸울 줄 모른다고 하셨으니 당분간 성 안에서 생활하실 방법부터 찾겠습니다. 토벌 임무를 맡기려고 드리는 돈이 아닙니다."},{"k":"line","id":"PRO_M01_본부_U_058","speaker":"케이아","text":"받고 나서 토벌 명단에 이름 올라갈까 걱정할 필요는 없어. 빌려주는 돈도 아니니까 상환일도 찾지 말고. 오늘은 자네가 다시 제 발로 다닐 수 있게 쓰면 돼.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_059","speaker":"나","text":"공짜 돈이라는 말은 전 직장에서 한 번도 못 들어 봤는데.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_060","speaker":"케이아","text":"공짜는 아니야. 살아서 다음에 또 오는 게 조건이지.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_061","speaker":"진","text":"앞으로 할 일은 모험가 길드에서 상담해 보시길 권합니다. 모험가라는 이름 때문에 걱정되실 수 있지만, 처음부터 전투를 해야 하는 건 아니에요. 성 안에서 맡을 수 있는 일부터 물어보세요.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M01_본부_U_062","options":[{"label":"고마워요. 등록해서 제 밥값은 벌어 볼게요. 처음 맡을 일은 할 수 있는지 꼼꼼히 고르고요.","keep":"ISK_M01_UT026","items":[{"k":"line","id":"PRO_M01_본부_U_063","speaker":"진","text":"네. 당장 모든 문제를 해결하려 하지 않으셔도 됩니다. 오늘은 식사를 하고, 내일 할 일을 알아보는 정도면 충분해요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_064","speaker":"케이아","text":"밥값 직접 벌겠다는 사람을 말릴 수는 없지. 다만 첫날부터 야외 의뢰 잡아 와서 우리 놀라게 하진 마.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_065","speaker":"나","text":"야외는 오늘로 충분해요. 당분간 실내 전문으로 갈게요.","map":"MAP_MOND_CITY"}]},{"label":"용 상대하는 일만 아니면… 한번 가 볼게요.","keep":"ISK_M01_UT027","items":[{"k":"line","id":"PRO_M01_본부_U_066","speaker":"케이아","text":"그건 당분간 우리가 맡지. 길드에는 물건 나르거나 수량 세는 의뢰도 있어. 접수할 때 할 수 있는 일과 못 하는 일을 솔직히 말하면 돼.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_067","speaker":"엠버","text":"응. 오늘은 성 밖으로 안 나가. 내가 옆에서 같이 볼 테니까 어려운 말 나오면 바로 물어봐.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_068","speaker":"나","text":"못 하는 일 목록이 더 길 텐데, 종이 큰 걸로 주세요.","map":"MAP_MOND_CITY"}]}]},{"k":"line","id":"PRO_M01_본부_U_069","speaker":"","text":"진이 서류를 내밀었다. 엠버에게 말한 이름을 적었다. 물잔을 잡을 때보다 손이 덜 떨렸다. 글자는 못 읽어도 이름 쓰는 칸이 어디인지는 엠버가 짚어 줬다.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M01_UT_AID"},{"k":"line","id":"PRO_M01_본부_U_070","speaker":"진","text":"받으실 금액을 확인해 주세요. 엠버, 안전이 확인된 길로 안내해 줘. {PLAYER_NAME} 님도 필요한 일이 생기면 기사단에 말씀해 주세요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_071","speaker":"케이아","text":"다음에 올 땐 문 앞에서 이름을 말해. 의자는 비워 둘게. 오늘보다 덜 흔들리는 날에 얘기를 이어 가자고.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_072","speaker":"엠버","text":"그때는 어려운 질문 전에 물부터 주세요, 선배.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_본부_U_073","speaker":"케이아","text":"대접 순서까지 정해졌네. 알았어. 둘 다 조심해서 가.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_001","speaker":"","text":"본부를 나서자 계단 아래에 바람에 날려 온 잎과 기왓조각이 모여 있었다. 거리에서는 사람들이 차양을 접고 떨어진 물건을 주워 담았다. 아무도 울지 않았다. 그게 더 무서웠다. 익숙하다는 뜻이니까.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_002","speaker":"엠버","text":"걸을 만해? 저 초록색 표식이 모험가 길드야. 기사단과는 다른 곳이지만, 몬드에서 일어나는 일을 돕는 건 비슷해.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_003","speaker":"","text":"접수처 뒤에서 머리를 단정하게 묶은 접수원이 사람들에게 출발을 미뤄 달라고 안내하고 있었다. 차례가 오자 그녀가 고개를 들었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_004","speaker":"캐서린","text":"별과 심연을 향해! 모험가 길드에 온 걸 환영해. 나는 안내원 캐서린이야. 엠버, 이쪽은 같이 온 사람이니?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_005","speaker":"엠버","text":"응, {PLAYER_NAME}이야. 오늘 몬드에 처음 왔어. 진 단장이 여기서 할 일을 알아보라고 하셨어.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_006","speaker":"캐서린","text":"그랬구나. 많이 놀랐겠네. 길드는 의뢰한 사람과 그 일을 맡을 모험가를 연결해 줘. 어떤 일인지 알려 주고, 마친 뒤엔 보고와 보수를 확인하지.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_007","speaker":"나","text":"그러니까 인력 사무소네요. 별과 심연이라는 간판만 빼면.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_008","speaker":"캐서린","text":"…비슷해. 지금 가장 걱정되는 게 있니? 먼저 알려 주면 어떤 의뢰를 안내할지 정하기 쉬워.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M01_길드_U_009","options":[{"label":"오늘 용을 봤거든. 당분간 위험한 일은 사양할게.","keep":"ISK_M01_EX_U_GUILD_C1","items":[{"k":"line","id":"PRO_M01_길드_U_010","speaker":"캐서린","text":"알겠어. 등록했다고 위험한 의뢰를 받아야 하는 건 아니야. 성 안의 일부터 보자.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_011","speaker":"엠버","text":"나도 그렇게 말했어. 용 보고 바로 모험 떠날 기운이 생기는 쪽이 더 신기하지.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_012","speaker":"나","text":"그런 사람도 있어? 나중에 멀리서 구경만 할게.","map":"MAP_MOND_CITY"}]},{"label":"하나씩 알려 줘. 메모는 잘해. 대신 모르는 말 나오면 바로 물을 테니까 너무 빨리 넘기지 말고.","keep":"ISK_M01_EX_U_GUILD_C2","items":[{"k":"line","id":"PRO_M01_길드_U_013","speaker":"캐서린","text":"좋아. 의뢰를 고를 땐 목적지와 맡을 분량부터 확인해. 장소 이름이 낯설면 여기서 물어보면 돼. 출발하고 나서 다른 곳인 걸 알면 서로 곤란하잖아.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_014","speaker":"엠버","text":"길은 내가 옆에서 볼게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_015","speaker":"","text":"종이 여백에 들은 순서를 옮겨 적었다. 글자는 몰라도 네모 치고 번호 매기는 건 몸에 남아 있다. 캐서린이 다음 칸을 가리키기 전에 펜이 먼저 갔다.","map":"MAP_MOND_CITY"}]}]},{"k":"line","id":"PRO_M01_길드_U_016","speaker":"","text":"등록 신청서에 이름을 적었다. 활동 지역 칸에서 펜이 멈췄다. 엠버가 종이에 그려진 성벽 안쪽을 짚어 줬다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_017","speaker":"엠버","text":"우선 여기. 성 안이야. 문 밖도 몬드이긴 한데, 오늘 갈 수 있는 곳은 아니니까.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_018","speaker":"캐서린","text":"다른 칸도 지금 적을 수 있는 것만 쓰면 돼. 전투 경험이 없으면 없다고 적고.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_019","speaker":"나","text":"「없음」. 이 칸은 자신 있게 쓸 수 있네.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M01_UT_REG"},{"k":"line","id":"PRO_M01_길드_U_020","speaker":"캐서린","text":"등록 끝났어, {PLAYER_NAME}. 등록 비용은 없어. 첫 의뢰를 고를 준비가 되면 다시 와. 오늘 여기서 한 말도 기억해 둘게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_길드_U_021","speaker":"엠버","text":"해냈네! 이제 모르는 걸 물어볼 데가 하나 더 생겼어. 다음은 장비. 비싼 거 고를 필요 없어. 처음부터 무거운 걸 잔뜩 사면 내가 짐꾼까지 해야 할걸.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_001","speaker":"","text":"장비 상인은 가게 앞에 떨어진 나무판을 치우고 있었다. 엠버가 영업하냐고 묻자 그는 안쪽의 외투를 가리켰다. 몸에 맞는 것을 걸치고 끈을 꿰는데, 팔을 들 때마다 한쪽 옷깃이 목을 잡아당겼다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_002","speaker":"장비 상인","text":"거긴 끈이 나오는 자리야. 안쪽으로 한 번 더 돌려야지. 새 옷 입었다고 몸까지 묶어 둘 필요는 없잖아.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_003","speaker":"엠버","text":"잠깐, 끈이 네 팔을 이기고 있잖아. 풀어 줄게. …이렇게 한 번 더 돌리면 돼. 자, 팔 올려 봐.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_004","speaker":"나","text":"넥타이는 십 년을 맸는데 이건 왜 안 되지.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_005","speaker":"엠버","text":"넥타이가 뭔지는 모르겠지만, 이건 반대로 돌리는 거야.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_006","speaker":"","text":"다시 묶고 팔을 들자 이번에는 옷이 따라 올라왔다. 상인이 낮은 선반에서 활을 꺼내 놓았다. 쥐어 보니 나무의 무게가 손목에 고스란히 실렸다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_007","speaker":"엠버","text":"탄궁이야. 활을 배울 거면 이걸로 시작할 수 있어. 하지만 여기서 시위 당기지는 마. 잡는 법부터 내가 봐 줘야 하니까.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_008","speaker":"장비 상인","text":"여행자 외투는 {STARTER_COAT_PRICE}모라, 탄궁은 {STARTER_BOW_PRICE}모라. 둘이면 {STARTER_KIT_COST}모라야. 크기 한 번 더 보고 결정해.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_009","speaker":"엠버","text":"둘 다 사면 {STARTER_KIT_REMAINING_MORA}모라가 남아. 밥값까지 써 버리면 안 돼. 외투는 지금 입고, 활은 메고 다니자. 안전한 데서 내가 가르쳐 줄게.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M01_장비_U_010","options":[{"label":"둘 다 살게요. 외투 묶는 법은 배웠으니, 혼자 묶어도 멀쩡한지만 한 번 더 봐 주세요.","keep":"ISK_M01_UT042","items":[{"k":"line","id":"PRO_M01_장비_U_011","speaker":"엠버","text":"벌써 한 가지 배웠네! 다음엔 네가 묶고 내가 검사하는 걸로. 활도 그렇게 하나씩 익히면 돼.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_012","speaker":"","text":"서툰 손으로 한 번 풀었다 다시 묶었다. 엠버가 고개를 끄덕였다. 장비를 계산대에 올렸다.","map":"MAP_MOND_CITY"}]},{"label":"{STARTER_KIT_COST}모라죠? 좋아요. 남은 건 식비라서 거스름돈까지 정확히 셀게요.","keep":"ISK_M01_UT043","items":[{"k":"line","id":"PRO_M01_장비_U_013","speaker":"장비 상인","text":"맞아. 장비는 멀쩡한데 사람이 굶으면 곤란하지. 거스름돈도 직접 확인해 봐.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_014","speaker":"","text":"낼 돈과 남길 돈을 따로 셌다. 동전 크기가 낯설어 두 번 셌지만, 엠버 도움 없이 끝냈다. 경리 일을 괜히 한 게 아니다.","map":"MAP_MOND_CITY"}]}]},{"k":"keep","id":"ISK_M01_UT_KIT"},{"k":"line","id":"PRO_M01_장비_U_015","speaker":"장비 상인","text":"계산 끝. 외투는 그대로 입고 가. 활은 사람 지나는 데서 당기지 말고. 끈이 불편하면 다시 들러.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_016","speaker":"","text":"가게를 나서다 등에 멘 활 끝이 문설주에 걸렸다. 엠버가 끝을 받쳐 줘서 간신히 뺐다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_017","speaker":"엠버","text":"천천히! 이제 네 뒤에 활 길이만큼 더 있다고 생각해야 해. …응, 그렇게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_018","speaker":"나","text":"오늘 배운 거. 끈 묶기, 문 통과하기, 용 나오면 벽에 붙기. 입사 첫날치고 알차네.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_019","speaker":"엠버","text":"알차다고 할 일이야?! …아니, 그렇게 받아 주면 나도 좀 편하긴 하다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_020","speaker":"","text":"길가 낮은 돌턱에 앉았다. 등에서 활의 무게가 빠지자 그제야 허기가 또렷해졌다. 아침인지도 모를 풀밭에서 눈을 뜬 뒤 처음으로 어깨를 늘어뜨렸다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_021","speaker":"엠버","text":"많이 피곤하지? 다음은 식사. 그다음엔 잘 곳. 등록이랑 장비까지 끝냈는데 마지막에 밥을 빼먹으면 안 되잖아.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_022","speaker":"엠버","text":"그리고 첫 의뢰는 나랑 같이 해 보자. 순찰 길과 겹치면 알려 줄 게 많아. 언제까지나 옆에서 끈만 묶어 줄 순 없으니까, 혼자 할 수 있는 것부터 하나씩 늘리는 거야. 어때?","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M01_장비_U_023","options":[{"label":"좋아, 같이 가자. 물어볼 거 엄청 많을 텐데 괜찮겠어? 질문 많다고 중간에 두고 가기 없기야.","keep":"ISK_M01_UT052","items":[{"k":"line","id":"PRO_M01_장비_U_024","speaker":"엠버","text":"괜찮아! 대신 한 번에 하나씩. 내가 모르면 아는 사람한테 같이 물어보면 되지. 오늘도 그렇게 여기까지 왔잖아.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_025","speaker":"","text":"엠버가 내민 손을 잡았다. 오늘 처음 들은 이름이 어느새 도움을 청할 사람의 이름이 됐다. 물어볼 건 한참 남았지만, 그게 아까처럼 혼자 남겨진 기분으로 이어지진 않았다.","map":"MAP_MOND_CITY"}]},{"label":"같이 가자. 대신 외투는 다음번에 내가 먼저 묶어 볼게. 네 손만 기다리다간 평생 못 배우겠어.","keep":"ISK_M01_UT053","items":[{"k":"line","id":"PRO_M01_장비_U_026","speaker":"엠버","text":"그럼 다음번엔 네가 먼저 묶어 봐. 내가 옆에서 보기만 할게. 제대로 되면 그다음은 활 잡는 법! 할 일이 벌써 생겼네.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_027","speaker":"","text":"엠버가 웃으며 손을 내밀었다. 악수하고 일어나자 등의 활이 다시 기울었다. 이번에는 스스로 끈을 당겨 바로잡았다. 엠버는 도와주려던 손을 거두고 고개를 끄덕였다.","map":"MAP_MOND_CITY"}]}]},{"k":"goto","id":"ISK_M01_T_JOIN"}]},{"label":"성부터 가자. 설명은 걸으면서 들어도 되지? 여기 서 있다가 아까 그 녀석들 또 만나기는 싫거든.","keep":"ISK_M01_O004","items":[{"k":"line","id":"PRO_M01_장비_U_028","speaker":"엠버","text":"맞는 말이야. 걸으면서 하자. 질문은 하나씩, 내가 숨 쉴 틈은 주고!","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_029","speaker":"나","text":"첫 질문. 저 성에 침대 있어?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_장비_U_030","speaker":"엠버","text":"…있어. 그건 내가 보장할게.","map":"MAP_MOND_CITY"},{"k":"goto","id":"ISK_M01_J001R"}]}]},{"k":"line","id":"PRO_M01_성문으로_K__001","speaker":"","text":"엠버가 걸음을 옮기자 바람이 등을 밀었다. 성문까지 이어지는 길에서는 들꽃이 흔들리고, 길가 바위 위에서 두 사람을 노려보는 것들이 있었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문으로_K__002","speaker":"엠버","text":"아, 또 나왔네. 괜찮아, 저 정도는 내가 잡아. 뒤에 서 있다가 내가 부르면 같이 뛰어.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문으로_K__003","speaker":"나","text":"뛰는 건 자신 있어. 도망치는 쪽으로.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문으로_K__004","speaker":"엠버","text":"그것도 중요한 능력이야!","map":"MAP_MOND_CITY"},{"k":"combat","id":"PRO_M01_성문으로_K__005","group":"EG_MOND_HILI_PATROL","text":"성문으로 가는 길목을 막은 츄츄족. 엠버와 함께 길을 연다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문으로_K__006","speaker":"","text":"마지막 녀석이 달아나자 엠버가 활시위를 내리고 손을 흔들었다. 땀이 났다. 화면 속에선 한 번도 나지 않던 땀이다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문으로_K__007","speaker":"엠버","text":"봤지? 뛰라고 하기 전에 뛰었잖아. 그것도 재능이야. 자, 성문이 코앞이야!","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M01_KT001","text":"성문 아래 그늘을 벗어나자 햇빛이 돌바닥에 쏟아졌다. 풍차, 붉은 지붕, 높이 솟은 성당. 알던 윤곽 그대로다. 그런데 성당이 너무 크다. 화면 한 칸에 들어가던 광장이 걸어서 몇 분이다. 목이 아프게 올려다보다가, 사람들과 부딪힐 뻔해서 고개를 내렸다."},{"k":"line","id":"PRO_M01_성문_001","speaker":"엠버","text":"어때? 알던 거랑 같아?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_002","speaker":"나","text":"같아. 크기만 빼고 전부. 이거 걸어서 다 돌려면 하루는 걸리겠는데.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_003","speaker":"엠버","text":"하루는 안 걸려! …반나절 정도? 그래서 뭐부터 할래? 구경? 아니면 당장 필요한 거부터?","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M01_성문_004","options":[{"label":"이렇게 넓었어? 구경하다간 끝이 없겠네. 일단 모험가 등록부터 하자.","keep":"ISK_M01_KT003","items":[{"k":"line","id":"PRO_M01_성문_005","speaker":"엠버","text":"좋아, 그게 제일 빨라. 모험가 길드에 이름을 올려 두면 잘 데랑 끼니는 어떻게든 돼. 구경은 걸어가면서!","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_006","speaker":"나","text":"등록이라고 하니까 왠지 입사 서류 생각나는데.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_007","speaker":"엠버","text":"그런 것보단 훨씬 간단해. 아마.","map":"MAP_MOND_CITY"}]},{"label":"구경은 천천히 하고, 모험가 등록부터 할래. 여기서 살려면 그게 먼저지.","keep":"ISK_M01_KT004","items":[{"k":"line","id":"PRO_M01_성문_008","speaker":"엠버","text":"그렇게 생각하는 게 맞아. 길드에 가자. 거기서 등록하면 성 안에서 할 수 있는 일도 알려 줘.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_009","speaker":"나","text":"살려면, 이라고 말하니까 좀 처절하네. 사실이긴 한데.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_010","speaker":"엠버","text":"처절한 건 오늘까지만! 내일부터는 좀 나아질 거야.","map":"MAP_MOND_CITY"}]}]},{"k":"line","id":"PRO_M01_성문_011","speaker":"","text":"광장 한쪽, 게시판 앞에 사람들이 모여 있다. 접수대 뒤에서 머리를 단정하게 묶은 접수원이 똑같은 각도로 인사한다. 그 각도까지 알고 있다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_012","speaker":"캐서린","text":"별과 심연을 향해! 모험가 길드에 온 걸 환영해. 등록하러 왔구나? 엠버가 데려오는 사람은 오래간만이네.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_013","speaker":"엠버","text":"길에서 만났어. 성 안에서 할 일부터 찾아 주고 싶어서.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_014","speaker":"캐서린","text":"그럼 몇 가지 적어 둘게. 할 수 있는 일, 해 본 일, 피하고 싶은 일. 솔직하게 말해 주면 그만큼 맞는 의뢰를 골라 줄 수 있어.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M01_성문_015","options":[{"label":"물건 세고 정리하는 건 자신 있어. 엉킨 수량 맞추는 일이면 더.","keep":"ISK_M01_EX_K_GUILD_C1","items":[{"k":"line","id":"PRO_M01_성문_016","speaker":"캐서린","text":"그런 일은 늘 있어. 창고 정리, 배송 수량 확인. 위험하지 않고 끼니도 챙길 수 있지.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_017","speaker":"나","text":"전 직장에서 제일 많이 한 게 그거였거든. 복사기 다음으로.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_018","speaker":"캐서린","text":"복사기가 뭔지는 모르지만, 손이 빠르다는 얘기로 들을게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_019","speaker":"엠버","text":"그럼 당분간은 그런 일부터 하자. 길 익히면서!","map":"MAP_MOND_CITY"}]},{"label":"절차만 좀 알아. 실력까지 경력자로 보면 곤란해.","keep":"ISK_M01_EX_K_GUILD_C2","items":[{"k":"line","id":"PRO_M01_성문_020","speaker":"캐서린","text":"절차를 안다는 것만으로도 접수가 빨라져. 실력은 의뢰를 하면서 보면 돼. 처음부터 어려운 걸 주진 않아.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_021","speaker":"나","text":"다행이다. 어려운 거 주면 바로 도망칠 생각이었어.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_022","speaker":"캐서린","text":"도망치기 전에 접수대에 말해 줘. 의뢰 취소 처리는 해 줘야 하니까.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_023","speaker":"엠버","text":"캐서린, 진지하게 받으면 안 돼. 이 사람 농담이야. …농담이지?","map":"MAP_MOND_CITY"}]}]},{"k":"keep","id":"ISK_M01_KT_REG"},{"k":"line","id":"PRO_M01_성문_024","speaker":"","text":"등록증에 이름이 적혔다. 종이 한 장인데 손에 무게가 느껴졌다. 캐서린이 초보자용 외투와 작은 주머니를 내밀었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_025","speaker":"캐서린","text":"길드 지원품이야. 새 모험가는 다 받아. 외투 끈은 이렇게 묶는 거야. 돌아올 때 그대로 입고 있으면 합격.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_026","speaker":"엠버","text":"자, 등록 끝! 그럼 성 안 좀 돌아보자. 어디가 어디인지 알아야 내일부터 혼자 다닐 수 있잖아.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_027","speaker":"","text":"엠버는 분수에서 성당 계단까지, 대장간에서 선술집까지 손으로 가리키며 걸었다. 다 아는 길이었다. 다 처음 걷는 길이기도 했다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_028","speaker":"나","text":"저기, 저 골목 끝에 선술집 있지? 고양이 간판.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_029","speaker":"엠버","text":"캣테일! 어떻게 알았어… 아, 게임. 그렇구나. 그럼 저기 주인이 누군지도 알아?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_030","speaker":"나","text":"알아. 그리고 그 사람한테 술 얘기 하면 혼난다는 것도 알아.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_031","speaker":"엠버","text":"정확해.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_032","speaker":"","text":"웃으려던 순간, 광장의 비둘기들이 한꺼번에 날아올랐다. 바람이 바뀌었다. 종이들이 하늘로 솟고, 사람들이 똑같은 방향을 올려다봤다.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M01_KT015","text":"지붕 너머로 그림자가 지나갔다. 날개. 알고 있는 날개다. 비명이 터지기 전에 다리가 먼저 움직였다. 어디로 가야 하는지 알고 있었다. 고양이 간판 아래, 문."},{"k":"line","id":"PRO_M01_성문_033","speaker":"나","text":"엠버, 캣테일로! 저 바람은 밖에서 못 버텨!","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_034","speaker":"엠버","text":"…알았어! 사람들, 이쪽으로! 유리에서 떨어져!","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_035","speaker":"","text":"문을 밀고 들어가자 작은 그림자가 카운터 뒤에서 튀어 올랐다. 고양이 귀, 짜증 난 얼굴.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_036","speaker":"디오나","text":"문 부서지면 네가 고치는 거다! …뭐야, 엠버? 또 용이야?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_037","speaker":"엠버","text":"또 용이야. 미안, 디오나. 잠깐만 빌릴게!","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_038","speaker":"","text":"문에 의자를 받쳤다. 바람이 문틈으로 비명처럼 밀려들었다. 유리잔이 흔들리고, 천장의 등이 춤을 췄다. 알고 있던 장면이다. 그런데 소리는 몰랐다. 이렇게 큰 줄은.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_039","speaker":"디오나","text":"거기 너, 처음 보는 얼굴. 바닥에 앉아. 서 있다가 넘어지면 내 잔 깨진다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_040","speaker":"나","text":"…네. 네, 앉을게요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_041","speaker":"","text":"바닥에 앉아 벽에 등을 붙였다. 밖에서 무언가 무너지는 소리가 났다. 손이 떨렸다. 화면 속에서 드발린이 지나갈 때 나는 간식을 먹고 있었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_042","speaker":"","text":"바람이 잦아들었다. 엠버가 문틈으로 밖을 확인하고, 디오나가 깨지지 않은 잔을 세었다. 하나도 깨지지 않았다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_043","speaker":"디오나","text":"다 멀쩡해. 운 좋네. 물 마실래? 술은 없어. 있어도 안 줘.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_044","speaker":"엠버","text":"고마워, 디오나. 다친 사람 없는지 보고 올게. 너는 여기 있어.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_045","speaker":"","text":"엠버가 나간 문 너머에서 사람들의 목소리가 들렸다. 디오나가 내민 물컵을 받았다. 손이 아직 떨려서 물이 조금 넘쳤다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_046","speaker":"디오나","text":"흘렸잖아. 뭐, 물이니까 봐준다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_047","speaker":"","text":"얼마 뒤 엠버가 돌아왔다. 겉옷에 돌가루가 묻어 있었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_048","speaker":"엠버","text":"크게 다친 사람은 없어. 성벽 한 군데가 좀 무너졌고. 너, 괜찮아? 아까 엄청 빨랐어. 내가 말하기도 전에 여기로 뛰었잖아.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M01_성문_049","options":[{"label":"첫 의뢰도 안 받았는데, 하루가 너무 알차네.","keep":"ISK_M01_KT025","items":[{"k":"line","id":"PRO_M01_성문_050","speaker":"엠버","text":"알차다고 할 일이야?! …아니, 뭐, 그렇게 받아 주면 나도 좀 편하긴 하다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_051","speaker":"디오나","text":"알찬 하루라니. 손님 중에 제일 이상한 소리 하네.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_052","speaker":"나","text":"칭찬으로 들을게.","map":"MAP_MOND_CITY"}]},{"label":"살았다… 둘 다 고마워. 진짜로.","keep":"ISK_M01_KT026","items":[{"k":"line","id":"PRO_M01_성문_053","speaker":"엠버","text":"뭘. 네가 먼저 뛰어 준 덕분에 사람들도 따라왔어.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_054","speaker":"디오나","text":"고맙다는 말은 물 한 잔 값으로 충분해. 더는 안 받아.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_055","speaker":"","text":"더 길게 말하려다 그만뒀다. 물이나 마셨다.","map":"MAP_MOND_CITY"}]},{"label":"알던 장면하고 달라. 기억만 믿으면 안 되겠어.","keep":"ISK_M01_KT027","items":[{"k":"line","id":"PRO_M01_성문_056","speaker":"엠버","text":"달라? 뭐가?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_057","speaker":"나","text":"순서가. 이렇게 빨리 올 줄 몰랐어. 그리고 이렇게 시끄러운 줄도.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_058","speaker":"엠버","text":"그럼 다음부턴 네 기억이랑 내 눈, 둘 다 쓰자. 하나보단 둘이 낫잖아.","map":"MAP_MOND_CITY"}]}]},{"k":"line","id":"PRO_M01_성문_059","speaker":"","text":"디오나가 빈 컵을 거둬 갔다. 엠버가 의자에 걸터앉아 나를 봤다. 아까보다 조금 진지한 얼굴이었다.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M01_KT034","text":"네가 말한 그 게임에선, 저 용 다음에 뭐가 와? 아니, 말하기 어려우면 안 해도 돼. 그냥… 알고도 저렇게 손이 떨리는 거면, 아는 것도 꽤 무거운 거구나 싶어서."},{"k":"keep","id":"ISK_M01_KT035","text":"이름만 안다고 했지? 그 이름이 저 용이었던 거야? …알았어. 다음엔 이름 말고 다른 것도 떠오르면 말해 줘."},{"k":"keep","id":"ISK_M01_EX_K_META_DEFER","text":"아까 어디서 들었는지 나중에 말한다고 했지? 오늘은 안 물을게. 다만 저 용에 대해서 뭔가 알면, 그것만은 내일이라도 말해 줘."},{"k":"line","id":"PRO_M01_성문_060","speaker":"","text":"대답 대신 고개를 끄덕였다. 엠버는 그걸로 됐다는 얼굴을 했다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_061","speaker":"엠버","text":"그래서 말인데. 나, 당분간 너랑 같이 다닐까 해. 순찰 겸, 안내 겸. 네가 아는 길이랑 내가 아는 길을 같이 맞춰 보는 거야. 어때?","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M01_성문_062","options":[{"label":"좋아. 아는 길도 실제로 같이 확인하자. 대신 내가 틀려도 비웃지 마.","keep":"ISK_M01_KT038","items":[{"k":"line","id":"PRO_M01_성문_063","speaker":"엠버","text":"비웃긴 왜 비웃어. 틀리면 고치면 되지. 나도 처음 순찰 땐 성문 반대쪽으로 갔었어.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_064","speaker":"나","text":"그건 좀 웃어도 되지 않아?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_065","speaker":"엠버","text":"그건 웃어도 돼.","map":"MAP_MOND_CITY"}]},{"label":"같이 가자. 오늘은 젤리한테도 질 뻔했는데, 다음에도 혼자면 진짜 질 것 같아.","keep":"ISK_M01_KT039","items":[{"k":"line","id":"PRO_M01_성문_066","speaker":"엠버","text":"슬라임한테는 다들 한 번씩 져. 괜찮아. 다음부터는 내가 앞에 서 있을게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_067","speaker":"나","text":"그럼 나는 뒤에서 응원할게. 그게 내 특기야.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M01_성문_068","speaker":"엠버","text":"응원도 소리 크게 해야 돼!","map":"MAP_MOND_CITY"}]}]},{"k":"keep","id":"ISK_M01_T_JOIN"},{"k":"line","id":"PRO_M01_성문_069","speaker":"","text":"엠버가 손을 내밀었다. 잡았다. 활시위를 당기는 손이라 생각보다 단단했다. 화면 속에서는 수없이 봤던 얼굴이 처음으로 내 쪽을 보고 웃었다.","map":"MAP_MOND_CITY","cond":"FLAG_ISK_META_KNOWLEDGE=KNOWN"},{"k":"keep","id":"ISK_M01_T_K_CLOSE","text":"다음에 올 땐 문짝이랑 씨름하지 말고 그냥 들어와. …술 마시러 오라는 뜻은 아니야! 물은 또 줄 테니까."},{"k":"keep","id":"ISK_M01_EX_K_GOODBYE_01","text":"고마웠어, 디오나. 다음엔 조용히 들어올게. 용 없이."},{"k":"keep","id":"ISK_M01_EX_K_GOODBYE_02","text":"용은 네가 데려오는 게 아니잖아. 그리고 너, 처음 보는 얼굴. 앉으라고 했을 때 바로 앉은 건 잘했어. 그것뿐이야."},{"k":"keep","id":"ISK_M01_EX_K_GOODBYE_03","text":"빈 컵을 카운터 끝에 놓았다. 디오나는 컵을 가져가면서 끝까지 이쪽을 보지 않았다. 귀만 조금 움직였다. 엠버가 문을 열자 저녁 빛이 들어왔다. 광장에서는 사람들이 쓰러진 천막을 다시 세우고 있었다."},{"k":"keep","id":"ISK_M01_T_U_CLOSE","text":"오늘은 많이 했어. 기사단에서 얘기했고, 길드에 이름도 올렸고, 새 외투도 제대로 입었고! 나머지까지 오늘 다 해치우려고 하진 말자."},{"k":"keep","id":"ISK_M01_EX_U_GOODBYE_01","text":"멀리 기사가 막아 둔 골목으로 짐수레가 돌아갔다. 하늘은 다시 맑은데 사람들은 아직 지붕을 올려다봤다. 이 도시의 문제는 끝나지 않았다. 그래도 지금 앉은 자리까지 바람이 오지는 않았다."},{"k":"keep","id":"ISK_M01_EX_U_GOODBYE_02","text":"숨 좀 돌아왔어? 그러면 일어날까. 이번엔 뛰지 말고, 천천히 가자."},{"k":"keep","id":"ISK_M01_T_K_FINAL","text":"들어올 때는 문 너머까지 살아서 가는 것만 생각했다. 나갈 때는 내일 할 일이 생겼다. 등록증, 외투, 옆에서 걷는 사람. 알고 있던 몬드는 생각보다 넓고, 생각보다 시끄럽고, 생각보다 사람이 많다. 문을 나서기 전에 한 번 길게 숨을 내쉬었다. 알람은 여전히 울리지 않았다."},{"k":"keep","id":"ISK_M01_T_U_FINAL","text":"남은 모라를 주머니 깊이 넣고 일어났다. 돌아가는 방법은 여전히 모른다. 하늘에 용이 나타나면 어떻게 견뎌야 하는지도 모른다. 그래도 이름을 불러 줄 사람이 생겼고, 내일 갈 곳이 생겼다. 엠버의 보폭에 맞춰 한 걸음 뗐다. 새 외투 자락이 바람에 흔들렸다. 알람은 여전히 울리지 않았다."},{"k":"keep","id":"ISK_M01_T_END"}],"edits":[],"pre":""},{"id":"ISK_M02","entry":"ISK_M02_ENTRY_K","items":[{"k":"keep","id":"ISK_M02_ENTRY_K","text":"다음 날 아침, 캣테일 문 앞의 의자는 치워졌지만 사람들은 여전히 지붕부터 올려다보며 걸었다. 엠버는 바람에 떨어진 안내판을 벽에 기대 놓고 돌아왔다. 어제 밤새 생각했다. 알고 있는 이야기를 어디까지 말할지. 결론은 못 냈다. 다만 입을 다물고 있다가 누가 다치는 쪽보다는 나을 것 같았다."},{"k":"keep","id":"ISK_M02_ENTRY_U","text":"다음 날 아침. 새 외투 끈을 혼자 묶는 데 세 번 걸렸다. 광장에서는 사람들이 어제 떨어진 간판을 다시 거는데, 아무도 하늘 얘기는 하지 않았다. 엠버가 게시판과 시장이 갈리는 길목에서 걸음을 늦췄다."},{"k":"choice","group":"G_PRO_M02_아침_001","options":[{"label":"기사단에 드발린 이야기를 해야겠어.","keep":"ISK_M02_ENTRY_K_C1","items":[{"k":"line","id":"PRO_M02_아침_002","speaker":"엠버","text":"용 이름만 아는 게 아니구나. 알았어, 진 단장한테 가자. 대신 어제 본 거랑 네가 알고 있던 거, 나눠서 말해 줘. 섞이면 나도 헷갈려.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_아침_003","speaker":"나","text":"나도 헷갈려. 그래서 가는 거야.","map":"MAP_MOND_CITY"}]},{"label":"도움 될 기억이 있어. 틀린 부분까지 숨길 생각은 없으니까, 기사단에서 한번 들어 봤으면 해.","keep":"ISK_M02_ENTRY_K_C2","items":[{"k":"line","id":"PRO_M02_아침_004","speaker":"엠버","text":"틀릴 수 있다는 말까지 같이 전하면 돼. 혼자 붙들고 있다가 위험한 데 들어가지만 마. 내가 옆에서 같이 들을게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_아침_005","speaker":"나","text":"옆에서 들어 주는 사람이 있으면 거짓말도 덜 하게 되지. 좋은 생각이야.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_아침_006","speaker":"엠버","text":"…거짓말할 생각이었어?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_아침_007","speaker":"나","text":"농담이야. 반쯤.","map":"MAP_MOND_CITY"}]},{"label":"등록도 했으니, 성 안에서 할 일부터 찾자.","keep":"ISK_M02_ENTRY_U_C1","items":[{"k":"line","id":"PRO_M02_아침_008","speaker":"엠버","text":"처음부터 성 밖으로 나갈 필요는 없어. 다친 사람이 맡기고 간 짐도 있고, 가게마다 다시 정리할 물건도 많거든. 부탁받으면 어디까지 하는 일인지 꼭 물어봐.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_아침_009","speaker":"나","text":"「어디까지」를 안 물어봤다가 야근한 적이 백 번은 돼. 이번엔 물어볼게.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M02_U_DAY_BEGIN","text":"그 뒤 사흘 동안 몬드의 하루에 조금씩 끼어들었다. 가게에서 짐 정리와 청소를 거들고 끼니와 뒷방 잠자리를 얻었다. 돈 쓸 일이 생기면 가격부터 두 번 물었다. 엠버는 순찰 나가기 전이나 돌아온 뒤에 들렀다."},{"k":"line","id":"PRO_M02_사흘_001","speaker":"","text":"첫날에는 빵을 받으러 나갔다가 길드 앞까지 돌아갔다. 둘째 날에는 짐표의 숫자와 상자 수가 안 맞는 걸 찾아내 주인에게 말했다. 주인이 놀랐다. 나는 안 놀랐다. 이런 건 전 직장에서 매일 했다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_사흘_002","speaker":"","text":"셋째 날에는 길 묻는 사람에게 골목을 가리켜 줬다. 맞게 알려 줬는지 모퉁이를 돌 때까지 지켜봤다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_사흘_003","speaker":"엠버","text":"또 골목 끝까지 보고 있네. 맞게 알려 줬어. 저 사람은 오른쪽으로 가면 돼.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_사흘_004","speaker":"","text":"엠버가 빈 상자를 뒤집어 앉았다. 내 앞에는 오늘 일 끝내고 받은 빵이 있었다. 이제 엠버가 활을 내려놓는 위치만 봐도 금방 다시 나갈 건지, 얘기할 틈이 있는지 안다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_사흘_005","speaker":"엠버","text":"처음엔 가게마다 길을 묻더니 오늘은 남한테 알려 줬잖아. 꽤 빨라. 외투 끈도 혼자 잘 묶었고.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_사흘_006","speaker":"","text":"매듭을 내려다봤다. 아직 활 잡는 자세는 어색하고, 바람 소리가 커지면 몸부터 굳는다. 그래도 아침마다 어디로 가야 하는지는 안다. 돌아갈 방법을 모르는 것과 오늘 할 일을 모르는 건 다른 문제였다.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M02_사흘_007","options":[{"label":"일 끝나고 밥 먹으니까 좀 사는 것 같다.","keep":"ISK_M02_U_DAILY_C1","items":[{"k":"line","id":"PRO_M02_사흘_008","speaker":"엠버","text":"그치? 나도 순찰 끝내고 먹는 게 제일 좋아. 그런데 내일 여기 일 전부 받아 버리진 마. 같이 돌아볼 길도 있잖아.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_사흘_009","speaker":"나","text":"걱정 마. 일 더 받는 건 내 특기가 아니야. 피하는 게 특기지.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_사흘_010","speaker":"엠버","text":"그 특기, 여기선 의외로 쓸모 있을지도.","map":"MAP_MOND_CITY"}]},{"label":"오늘은 길 안 잃었어. 이 정도면 승진 아닌가.","keep":"ISK_M02_U_DAILY_C2","items":[{"k":"line","id":"PRO_M02_사흘_011","speaker":"엠버","text":"그럼 내일부터 길 안내도 맡길까? 아, 성문 반대쪽까지 데려다주면 안 돼. 그건 승진 취소야.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_사흘_012","speaker":"나","text":"승진 하루 만에 취소당하는 건 익숙해. 전 직장에서도 그랬거든.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_사흘_013","speaker":"","text":"엠버가 진지한 얼굴로 골목 세 곳을 가리키더니 먼저 웃었다. 웃을 때 주변 눈치부터 보지 않은 건 몬드에 온 뒤 처음이었다.","map":"MAP_MOND_CITY"}]},{"label":"너도 좀 앉아. 네 일도 바쁜데 내 쪽까지 들르는 거잖아.","keep":"ISK_M02_U_DAILY_C3","items":[{"k":"line","id":"PRO_M02_사흘_014","speaker":"엠버","text":"바쁜 건 맞지. 그래서 지금 앉았잖아! 네가 혼자 길 찾고 끈 묶는 것만 해도 내 일이 꽤 줄었어.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_사흘_015","speaker":"나","text":"줄었다고 하지 말고 「도움이 됐다」고 해 줘. 그래야 내일도 일어나지.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_사흘_016","speaker":"엠버","text":"도움이 됐어. 많이. 됐지?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_사흘_017","speaker":"","text":"엠버는 손목 끈을 다시 조이며 다음 순찰 길을 봤다. 쉬지도 않고 나만 돌본 게 아니라, 자기 일 하는 틈에 시간을 내 온 거였다.","map":"MAP_MOND_CITY"}]}]},{"k":"line","id":"PRO_M02_활_연습_001","speaker":"엠버","text":"그래서 말인데, 내일 아침엔 성문 밖으로 잠깐 나가자. 활은 성 안에서 못 당기잖아. 내 순찰 길 끝에 조용한 데가 있어.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_활_연습_002","speaker":"","text":"다음 날 아침, 성문 밖 언덕. 엠버가 과녁 대신 나무 그루터기를 골랐다. 시위를 당기자 팔이 떨렸다. 화살은 그루터기 왼쪽 풀밭에 박혔다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M02_활_연습_003","speaker":"엠버","text":"좋아, 땅은 맞췄어! 다음은 나무. 팔꿈치 더 올리고. 숨 멈추지 말고.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M02_활_연습_004","speaker":"나","text":"땅 맞췄다고 칭찬받는 건 처음이야.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M02_활_연습_005","speaker":"","text":"세 발째가 그루터기에 박히는 순간, 엠버가 손을 들어 나를 멈췄다. 언덕 아래에서 가면 쓴 것들이 올라오고 있었다. 화살 소리를 듣고 온 모양이다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M02_활_연습_006","speaker":"엠버","text":"연습 끝. 실전은 아직 아니야. 내 뒤로. 뛰라고 하면 성문 쪽으로 뛰어.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M02_활_연습_007","speaker":"나","text":"그건 사흘 전에 배웠어.","map":"MAP_MOND_PLAINS"},{"k":"combat","id":"PRO_M02_활_연습_008","group":"EG_MOND_HILI_PATROL","text":"활 소리에 몰려온 츄츄족. 엠버가 앞을 막는다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M02_활_연습_009","speaker":"","text":"엠버가 마지막 녀석을 쫓아내고 돌아와 내 활을 봤다. 시위가 당겨진 채였다. 화살은 없었다. 어디로 날아갔는지 둘 다 못 봤다.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M02_활_연습_010","speaker":"엠버","text":"…한 발 쐈네. 어디 맞았는지는 모르겠지만, 쐈어. 그거면 됐어. 돌아가자.","map":"MAP_MOND_PLAINS"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_001","speaker":"","text":"돌아오는 길에 빈 상자를 반납하고 길드로 갔다. 게시판 앞에서 사람들은 종이 읽는 시간보다 창구에 묻는 시간이 더 길었다. 성 밖 의뢰 몇 장에는 「접수 중단」 표시가 붙어 있었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_002","speaker":"캐서린","text":"별과 심연을 향해! {PLAYER_NAME}, 오늘은 어떤 일을 찾고 있어? 성 밖으로 나갈 생각이면 먼저 나한테 확인해 줘.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_003","speaker":"엠버","text":"아직 바로 나가려는 건 아니야. 성 안에서 할 일을 좀 알아보려고. 며칠 전보다 할 수 있는 게 늘었거든.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_004","speaker":"나","text":"늘긴 늘었어요. 끈 묶기, 상자 세기, 땅 맞히기.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_005","speaker":"캐서린","text":"…마지막 건 뭔지 모르겠지만, 적어 둘게.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M02_U_GUILD_05","text":"등록할 때 위험한 일은 피하고 싶다고 했지? 그럼 오늘도 성 안에서 할 수 있는 일부터 볼게. 맡을 분량은 전보다 늘려도 돼."},{"k":"keep","id":"ISK_M02_U_GUILD_06","text":"처음엔 내가 칸마다 설명했는데, 이제 익숙한 건 네가 먼저 봐도 되겠다. 새로 나오는 장소나 조건만 여기서 물어봐."},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_006","speaker":"","text":"캐서린이 비교해 보라고 꺼낸 의뢰서 위로 큰 그림자가 지나갔다. 광장의 사람들이 거의 동시에 하늘을 봤다. 엠버가 내 팔을 잡고 벽 안쪽으로 끌어당겼다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_007","speaker":"엠버","text":"안으로! 유리 있는 쪽에서 떨어져!","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_008","speaker":"","text":"문 안으로 몸을 밀어 넣자 창밖의 천막이 한 번 크게 들렸다. 지붕 너머로 날개와 흩어지는 새 떼. 사흘 동안 바람이 거세질 때마다 끊기던 대화가 이번에도 끝나지 못했다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_009","speaker":"","text":"벽에 등을 붙였다. 지난번보다는 덜 떨렸다. 그게 자랑스럽지는 않았다. 익숙해졌다는 건 그만큼 자주 있었다는 뜻이니까.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_010","speaker":"","text":"바람이 잦아든 뒤에도 엠버는 한동안 문을 열어 주지 않았다. 순찰 인원이 길을 확인하고서야 사람들이 하나씩 나갔다. 게시판에는 접수 중단 표시 위로 새 종이가 더 붙었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_011","speaker":"캐서린","text":"오늘 바로 수락할 필요는 없어. 접수 가능한 일은 다시 정리해 둘게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_012","speaker":"엠버","text":"본부에 다녀와야겠어. 네가 묵는 데까지 먼저 같이 가자.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_013","speaker":"","text":"돌아가는 길에 엠버는 넘어진 표지판을 피해 길을 바꿨다. 며칠 사이 익혀 둔 길 하나가 또 막혔다. 조금씩 넓어지던 몬드가 드발린이 지나갈 때마다 안전한 방 하나만큼 좁아졌다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_014","speaker":"엠버","text":"여기까지는 괜찮네. 오늘은 이 골목 안에서 지내. 본부에서 소식 들으면 내가 와서 알려 줄게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_015","speaker":"나","text":"소식이 좋은 거면 뛰어오고, 나쁜 거면 걸어와. 마음의 준비는 해야 하니까.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_길드_그리고_또_바람_016","speaker":"엠버","text":"…알았어. 그렇게 할게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_001","speaker":"","text":"며칠 뒤 광장에 기사단 공고가 붙었다. 드발린 토벌대를 편성한다는 내용이었다. 모인 사람들 사이에서 안도와 걱정이 한꺼번에 나왔다. 엠버는 걸어왔다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_002","speaker":"엠버","text":"…본부에서 직접 듣자. 가자.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_003","speaker":"","text":"본부에 들어서자 처음 피신했던 안쪽 벽이 보였다. 그때는 창밖을 지나간 게 뭔지도 몰랐다. 지금은 용의 이름과 경보 소리를 안다. 단장실에서 나온 진이 두 사람을 보고 걸음을 멈췄다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_004","speaker":"나","text":"공고 보고 왔어요. 이제 성 안에서 길 좀 찾겠다 싶으니까 또 경보더군요. 계속 이럴 순 없다는 건 저도 알겠어요. 그래도 이유는 직접 듣고 싶어서요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_005","speaker":"진","text":"생활은 조금 익숙해지셨나요? 다시 위험한 일을 겪게 해서 마음이 무겁습니다.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M02_U_ANNOUNCE_04","text":"드발린의 공격은 계속되고 있습니다. 시민들이 매번 피신하는 것만으로 버티게 할 수는 없습니다. 기사단은 토벌대를 편성해 출정합니다."},{"k":"line","id":"PRO_M02_공고_006","speaker":"엠버","text":"나도 참가해. 앞길을 살피고, 대원이 흩어지지 않게 움직이는 일이 필요하니까.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_007","speaker":"진","text":"엠버, 출정 준비와 함께 성 안에 남을 사람에게 인계할 일도 정리해 줘. 길이 통제되면 외부 의뢰를 맡은 모험가들도 돌아와야 해.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_008","speaker":"엠버","text":"네. 캐서린에게도 제가 아는 위험 구간을 전할게요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_009","speaker":"","text":"엠버는 지시를 받고도 바로 가지 않았다. 복도 한쪽 벽에 지도를 폈다. 성문 안쪽에서 끝나던 선이 이번에는 한참 바깥까지 이어졌다. 그 선을 따라가다 고개를 들자 엠버도 설명을 멈추고 눈을 맞췄다.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M02_공고_010","options":[{"label":"토벌이면 드발린을 죽여서라도 멈추겠다는 뜻이야? 쫓아내러 가는 건지, 처음부터 그걸 목표로 나가는 건지 제대로 알고 싶어.","keep":"ISK_M02_U_ASK_C1","items":[{"k":"line","id":"PRO_M02_공고_011","speaker":"엠버","text":"응. 죽여서라도 공격을 멈추겠다는 작전이야. 나도 가볍게 생각하지 않아. 그렇지만 다음에도 그냥 물러가 주길 기다릴 수는 없으니까.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_012","speaker":"","text":"엠버는 용을 잡을 수 있다는 자신감으로 말을 덮지 않았다. 며칠 동안 안전한 길만 알려 주던 사람이, 안전하다고 부를 수 없는 길로 나갈 준비를 하고 있었다.","map":"MAP_MOND_CITY"}]},{"label":"네가 돌아올 길까지 챙기는 건 봤어. 그래도 그 바람 속으로 다시 나간다니 걱정은 되네. 괜찮냐고 묻는데 괜찮다는 말만 하고 넘어가지는 마.","keep":"ISK_M02_U_ASK_C2","items":[{"k":"line","id":"PRO_M02_공고_013","speaker":"엠버","text":"괜찮다고 약속할 순 없어. 그래서 같이 나가는 사람들하고 준비하는 거야. 보이는 곳, 물러날 길, 신호가 안 들릴 때 만날 곳까지.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_014","speaker":"","text":"엠버가 지도에서 짚는 건 이기고 돌아올 길만이 아니었다. 위험하면 어디로 물러날지도 손끝을 따라 드러났다. 밝은 말투가 위험을 모른다는 뜻은 아니었다.","map":"MAP_MOND_CITY"}]}]},{"k":"line","id":"PRO_M02_공고_015","speaker":"엠버","text":"너는 어떻게 할 거야? 성에 남으면 길드에서 할 일을 찾아도 돼. 내 옆에서 계속 배우고 싶으면 같이 가겠다고 할 수도 있고. 다만 이번엔 산책이나 짐 옮기는 일이 아니야.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_016","speaker":"진","text":"동행하실 의사가 있다면 말씀해 주세요. 바로 전투 인원으로 취급하지는 않겠습니다. 남으셔도 지원받은 일 때문에 의무를 지는 것은 아닙니다.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M02_U_DECIDE_03","text":"밥 먹고 잘 곳부터 걱정했던 거, 여기서 갑자기 다 내려놓을 필요는 없어. 어느 쪽이든 네가 정해."},{"k":"keep","id":"ISK_M02_U_DECIDE_04","text":"처음에 싸워 본 적 없다고 했던 거 나도 기억해. 같이 가더라도 곧장 용 앞에 세울 생각은 없어. 그래도 위험한 길인 건 맞으니까, 내 눈치 보느라 대답하지는 마."},{"k":"line","id":"PRO_M02_공고_017","speaker":"","text":"책상 너머로 활과 보급품이 보이고, 반대쪽 창밖에는 의뢰 게시판으로 이어지는 거리가 있었다. 서기가 빈 명단을 펼쳤다가 진의 손짓에 펜을 내려놓았다. 엠버가 자기 짐을 의자 아래로 밀어 넣어 옆자리를 비웠다. 아직 어느 명단에도 내 이름은 없었다.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M02_공고_018","options":[{"label":"나도 같이 갈게. 물자든 길 확인이든 할 수 있는 일부터 맡겨 줘. 구경만 하러 가진 않을게.","keep":"ISK_M02_U_COMMIT_EXPEDITION","items":[{"k":"line","id":"PRO_M02_공고_019","speaker":"엠버","text":"알겠어. 그럼 준비할 때부터 같이 하자. 모르는 건 그때그때 물어봐. 혼자 괜찮은 척하다가 뒤처지는 건 안 돼.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_020","speaker":"진","text":"알겠습니다. 우선 지원 인원으로 준비를 함께 확인하겠습니다. 다룰 수 있는 도구와 익숙한 일을 알려 주세요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_021","speaker":"나","text":"다룰 수 있는 도구… 펜이요. 익숙한 일은 숫자 세기. 토벌대에 경리 자리 있어요?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_022","speaker":"진","text":"…있습니다. 지금 만들었습니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_023","speaker":"","text":"며칠 전에는 어디로 가야 할지 몰라 엠버를 따라왔다. 이번에는 위험하다는 말을 듣고도 같은 쪽으로 가기로 했다. 왜인지는 나도 잘 모르겠다. 아마 저 사람이 걸어오는 걸 보고 싶지 않아서일 것이다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_024","speaker":"엠버","text":"그럼 여기 앉아. 짐부터 같이 보자. 들 수 있는 것부터 맡고, 너무 무거우면 처음부터 말해.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M02_U_GATE_EXPEDITION","text":"토벌대의 출정 준비를 마쳤다. 준비가 되면 이야기를 이어 가자."}]},{"label":"난 성에 남을게. 길드에서 할 수 있는 일을 찾아야겠어. 지금 내가 설 자리는 그쪽인 것 같아.","keep":"ISK_M02_U_COMMIT_GUILD","items":[{"k":"line","id":"PRO_M02_공고_025","speaker":"엠버","text":"응, 그렇게 하자. 캐서린에게 지금 맡을 수 있는 일을 물어봐. 성 밖 의뢰가 다시 열려도 길이 안전한지 먼저 확인하고.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_026","speaker":"진","text":"출정 중에도 성 안의 방위와 길드 연락은 이어집니다. 곤란한 일이 생기면 남아 있는 기사에게 말씀하세요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_027","speaker":"","text":"엠버는 복도 입구까지 배웅했다. 며칠 동안 헤어질 때마다 다음에 어디서 만날지 알려 주던 사람이, 이번에는 언제 돌아온다는 말을 덧붙이지 못했다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_028","speaker":"엠버","text":"가게 쪽 길은 아직 열려 있어. 오늘은 그쪽으로 돌아가. 나도 준비 끝나면 출정 전에 얼굴 보러 갈게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_029","speaker":"나","text":"걸어오지 말고 뛰어와. 좋은 소식 들고.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_030","speaker":"엠버","text":"…응. 뛰어올게.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_031","speaker":"","text":"본부 계단을 내려갔다. 길드로 가는 골목은 이제 혼자서도 찾는다. 익숙해졌다는 사실이 조금 전까지와 다른 무게로 남았다.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M02_U_GATE_GUILD","text":"모험가 길드에서 새 의뢰를 알아보는 중이다. 준비가 되면 이야기를 이어 가자."}]}]}]},{"label":"길부터 익히자. 매번 엠버 이름만 부를 순 없잖아.","keep":"ISK_M02_ENTRY_U_C2","items":[{"k":"line","id":"PRO_M02_공고_032","speaker":"엠버","text":"불러도 되지만, 내가 순찰 중이면 바로 못 올 때도 있으니까. 길드랑 기사단, 대피할 곳부터 보자. 맛있는 냄새만 따라가면 엉뚱한 골목으로 들어가거든.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_033","speaker":"나","text":"냄새 따라가는 건 내 길 찾기 방식인데. 회사도 그렇게 찾았어.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_034","speaker":"엠버","text":"그래서 어디로 갔는데?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_035","speaker":"나","text":"빵집.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_공고_036","speaker":"","text":"엠버는 지붕 색보다 교차로의 우물과 풍차를 기준으로 길을 알려 줬다. 같은 골목을 반대쪽에서 한 번 더 걷고 나서야 성문 방향을 혼자 짚었다.","map":"MAP_MOND_CITY"},{"k":"goto","id":"ISK_M02_U_DAY_BEGIN"}]}]},{"k":"line","id":"PRO_M02_본부_K__001","speaker":"","text":"기사단 본부 복도에는 어제 무너진 성벽과 통제 중인 길이 표시된 지도가 걸려 있었다. 엠버가 문 앞에서 짧게 보고하고 단장실 문을 열었다. 책상 뒤에 금발의 기사가 앉아 있었다. 알고 있는 얼굴. 알고 있는 것보다 피곤한 얼굴.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__002","speaker":"진","text":"페보니우스 기사단 단장 대행, 진입니다. 엠버에게 어제 일은 들었습니다. 몸은 괜찮으신가요? 드발린에 관해 전할 이야기가 있다고요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__003","speaker":"나","text":"괜찮습니다. 바닥에 앉아 있었던 것치고는요. 그리고… 네. 있어요. 다만 먼저 말씀드릴 게 있는데, 제 이야기는 반쯤은 틀릴 수 있습니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__004","speaker":"진","text":"틀릴 수 있다는 걸 미리 말씀해 주시는 분은 드뭅니다. 들어 보겠습니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__005","speaker":"엠버","text":"캣테일로 들어가자고 먼저 판단한 게 이 사람이에요. 바람을 못 버틴다는 걸 바로 알았고요. 그런데 그 용을 보기 전부터 몬드에 대해서 아는 게 있었어요. 어디서 어떻게 아는지는 본인이 말할 거예요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__006","speaker":"진","text":"알겠습니다. 드발린에 대해 먼저 말씀해 주세요. 몬드가 지금 당장 할 수 있는 일이 있다면 듣겠습니다.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M02_본부_K__007","options":[{"label":"드발린과 대화를 시도해 봐야 해요. 사람 말을 알아들어요.","keep":"ISK_M02_K_REPORT_C1","items":[{"k":"line","id":"PRO_M02_본부_K__008","speaker":"진","text":"드발린은 한때 몬드를 지킨 사풍 수호입니다. 우리도 그를 마물로만 보지는 않습니다. 하지만 지금은 다가가는 것조차 어렵고, 말을 전할 방법도 모릅니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__009","speaker":"나","text":"방법은 제가 알아요. 아마도요. 그게 문제인데… 「아마도」가 자꾸 붙네요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__010","speaker":"진","text":"「아마도」가 붙은 이야기도 듣겠습니다. 지금은 확실한 이야기가 하나도 없으니까요.","map":"MAP_MOND_CITY"}]},{"label":"드발린을 멈출 다른 방법이 기억나요. 다만 확인은 필요해요.","keep":"ISK_M02_K_REPORT_C2","items":[{"k":"line","id":"PRO_M02_본부_K__011","speaker":"진","text":"가능성으로 듣겠습니다. 기억과 다른 부분이 생기면 즉시 알려 주세요. 확인되지 않은 이야기에 사람을 보내지는 않을 겁니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__012","speaker":"나","text":"사람을 안 보내시는 건 찬성이에요. 저도 사람이라서.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__013","speaker":"진","text":"…네. 그래서 더 신중하게 듣겠습니다.","map":"MAP_MOND_CITY"}]}]},{"k":"line","id":"PRO_M02_본부_K__014","speaker":"","text":"지도 앞에 섰다. 손가락으로 성당을 짚었다. 화면에서는 몇 번이고 들어갔던 곳이다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__015","speaker":"나","text":"성당에 천공의 하프가 있죠. 제가 아는 이야기에서는 그 하프로 드발린한테 다시 말을 걸었어요. 연주할 사람도 있어요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__016","speaker":"진","text":"천공의 하프라면 성당의 보물입니다. 쓰려면 목적과 책임을 분명히 해야 해요. 연주자는 누구를 생각하고 계신가요?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__017","speaker":"","text":"벽 너머에서 바쁜 발소리가 오갔다. 여기서 이름과 정체를 같이 말하면 엠버뿐 아니라 문밖까지 들린다.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M02_본부_K__018","options":[{"label":"진 단장에게만 잠깐 말씀드려도 될까요?","keep":"ISK_M02_K_PRIVATE_C1","items":[{"k":"line","id":"PRO_M02_본부_K__019","speaker":"진","text":"엠버, 잠시 복도에서 기다려 줘. 다음 보고는 내가 부른 뒤에 받겠다고 전해 줘.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__020","speaker":"엠버","text":"네. …나중에 꼭 알려 줘야 돼.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__021","speaker":"나","text":"알려 줄 수 있는 건 알려 줄게. 그게 얼마나 될지는 모르겠지만.","map":"MAP_MOND_CITY"}]},{"label":"사람 하나의 비밀이 걸렸어요. 둘이서 얘기하고 싶어요.","keep":"ISK_M02_K_PRIVATE_C2","items":[{"k":"line","id":"PRO_M02_본부_K__022","speaker":"진","text":"그렇다면 여기서 이름을 꺼내지 마세요. 엠버, 잠시 자리를 비워 줘.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__023","speaker":"엠버","text":"알겠어요. 급한 일 생기면 문 두드릴게요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__024","speaker":"","text":"엠버는 묻지 않고 나갔다. 묻고 싶은 얼굴이었다.","map":"MAP_MOND_CITY"}]}]},{"k":"line","id":"PRO_M02_본부_K__025","speaker":"","text":"문이 닫혔다. 진은 창문도 닫았다. 그리고 먼저 이름을 짐작해 말하지 않았다.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M02_본부_K__026","options":[{"label":"벤티라는 음유시인, 그 사람이 바르바토스예요.","keep":"ISK_M02_K_IDENTITY_C1","items":[{"k":"line","id":"PRO_M02_본부_K__027","speaker":"","text":"진의 펜이 종이 위에서 멎었다. 다음 질문이 바로 나오지 않았다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__028","speaker":"나","text":"네. 그런데 지금 어디 있는지까지는 몰라요. 놀라실 만하죠. 저도 말해 놓고 보니 그렇네요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__029","speaker":"진","text":"…놀랐습니다. 그리고, 믿고 싶다는 이유로 확인하지 않은 이야기를 사실로 삼지는 않겠습니다. 다만 이 방 밖으로는 나가지 않을 겁니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__030","speaker":"나","text":"그거면 돼요. 저도 「믿어 주세요」라고 말할 생각은 없었어요. 믿기 힘든 얘기인 거 아니까.","map":"MAP_MOND_CITY"}]},{"label":"제가 아는 바로는 벤티가 바르바토스예요. 이건 단장만 알아 주세요.","keep":"ISK_M02_K_IDENTITY_C2","items":[{"k":"line","id":"PRO_M02_본부_K__031","speaker":"","text":"바르바토스라는 이름이 나오자 진의 시선이 내 얼굴에 머물렀다. 그녀는 작게 들이쉰 숨을 천천히 내쉬었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__032","speaker":"진","text":"정말… 그분이 아직 우리 곁에 계실지도 모른다는 거군요. 이 방 밖에는 알리지 않겠습니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__033","speaker":"나","text":"확인은 해야죠. 비밀을 안다고 친한 사이가 되는 건 아니니까. 그분을 찾는 건 그분 사정이고, 우리는 우리가 할 수 있는 일부터요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__034","speaker":"진","text":"네. 그 말씀이 맞습니다.","map":"MAP_MOND_CITY"}]}]},{"k":"line","id":"PRO_M02_본부_K__035","speaker":"","text":"진이 종이를 덮었다. 벤티의 이름은 적지 않았다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_본부_K__036","speaker":"진","text":"하프부터 확인하죠. 성당에 가겠습니다. 엠버도 같이요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_성당_001","speaker":"","text":"성당 지하 보관실 앞에서 집사 달리아가 기다리고 있었다. 평소의 부드러운 미소가 아니었다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_성당_002","speaker":"달리아","text":"단장님. 와 주셔서 다행입니다. 어젯밤의 바람 때문에 보관실을 점검하다가… 직접 보시는 편이 빠르겠군요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_성당_003","speaker":"","text":"받침대가 비어 있었다. 덮개 아래로 움푹 팬 자국만 남아 있다. 알고 있는 장면이다. 다만 알고 있는 이야기에서는 「우리가 가져가야 할」 하프였다. 누가 먼저 가져갈 줄은 몰랐다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_성당_004","speaker":"달리아","text":"자물쇠는 멀쩡하고, 창문도 그대로입니다. 어젯밤 바람이 심할 때 모두 피신해 있었으니, 그 사이였겠지요.","map":"MAP_MOND_CITY"},{"k":"choice","group":"G_PRO_M02_성당_005","options":[{"label":"빠져나간 방향은 알아요? 지금 따라갈 수 있게요.","keep":"ISK_M02_K_LYRE_C1","items":[{"k":"line","id":"PRO_M02_성당_006","speaker":"달리아","text":"가져간 이들이 성문 밖에서 목격됐다는 연락이 하나 있었습니다. 성 안쪽은 제가 더 알아보겠습니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_성당_007","speaker":"나","text":"마지막으로 본 데가 지금 있는 데는 아니겠죠. 그래도 거기서 다음 발자국은 찾을 수 있을 거예요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_성당_008","speaker":"엠버","text":"발자국 찾는 건 내 일이야. 맡겨 줘.","map":"MAP_MOND_CITY"}]},{"label":"하프가 없으면 계획부터 막히겠네요. 되찾을 방법을 찾아야죠.","keep":"ISK_M02_K_LYRE_C2","items":[{"k":"line","id":"PRO_M02_성당_009","speaker":"달리아","text":"가져간 이들이 성문 밖에서 목격됐다는 연락이 있어요. 그쪽을 확인해 주십시오. 저는 더 들어오는 소식이 없는지 알아보겠습니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_성당_010","speaker":"나","text":"제가 아는 수색 장소가 있긴 해요. 그런데 거기 가면 빈방만 구경할 가능성이 커요. 오늘 실제로 본 사람이 있다는 게 다행이네요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_성당_011","speaker":"진","text":"기억보다 목격담을 따르겠습니다. 동의하시죠?","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_성당_012","speaker":"나","text":"네. 제 기억은 어제부터 신용 등급이 많이 떨어졌어요.","map":"MAP_MOND_CITY"}]}]},{"k":"keep","id":"ISK_M02_K_CHURCH_09","text":"마지막 목격 지점은 서풍 매의 사당 인근입니다. 회수조를 준비하겠습니다. 엠버, 길을 맡아 줘. 당신도 동행해 주시겠습니까? 기억이 틀리더라도, 틀렸다는 걸 아는 사람이 현장에 있는 편이 낫습니다."},{"k":"line","id":"PRO_M02_성당_013","speaker":"나","text":"갈게요. 틀렸다고 말하는 건 잘하니까요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_성당_014","speaker":"엠버","text":"그건 자랑이 아니야!","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M02_K_FALCON_01","text":"회수조가 성문을 나서 사당에 닿을 때까지 엠버는 갈림길마다 먼저 뛰어가 길을 확인했다. 들판은 조용했다. 조용한 게 더 불안했다. 사당 입구에 다다르자 진이 손을 들어 대열을 세웠다. 안쪽에서 아무 소리도 나지 않았다."},{"k":"keep","id":"CRPG_ISK_K_FALCON_COMBAT","text":"사당 바깥의 낮은 계단에서 마물들이 기척을 알아챈다. 안쪽을 보기 전에 밖부터 정리해야 한다."},{"k":"line","id":"PRO_M02_서풍_매의_사당_001","speaker":"","text":"마물들이 흩어진 뒤에도 사당 안에서는 아무 소리가 나지 않았다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_002","speaker":"","text":"입구의 돌기둥 뒤에 우인단의 외투가 보였다. 한 벌이 아니었다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_003","speaker":"엠버","text":"진 단장… 전부 쓰러져 있어요. 숨 쉬는 사람이 없어요.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_004","speaker":"","text":"싸운 흔적이 없었다. 무기는 허리에 꽂힌 그대로였고, 벽에도 바닥에도 긁힌 자리 하나 없었다. 서 있던 자리에서 그대로 주저앉은 것처럼, 사람들만 조용히 쓰러져 있었다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_005","speaker":"","text":"알고 있는 이야기에서는 여기서 우리가 그들과 싸웠다. 그들이 먼저, 아무 이유도 없이 죽어 있는 장면은 어디에도 없었다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"keep","id":"ISK_M02_K_FALCON_05","text":"측랑과 안쪽 방까지 확인한 사람들이 돌아왔다. 사당 안의 우인단은 전원 사망. 상처도, 다툰 자리도 없었다. 하프는 없었다. 하프를 넣었던 것으로 보이는 빈 상자만 바닥에 뒹굴었다. 진이 조용히 숫자를 세고, 엠버는 입을 다물고 있었다."},{"k":"choice","group":"G_PRO_M02_서풍_매의_사당_006","options":[{"label":"전부……? 더 안쪽에라도 살아 있는 사람은 없어?","keep":"ISK_M02_K_DEAD_C1","items":[{"k":"line","id":"PRO_M02_서풍_매의_사당_007","speaker":"엠버","text":"없어. 안쪽 방까지 봤어. 전부… 전부야.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_008","speaker":"","text":"농담이 떠오르지 않았다. 처음이었다.","map":"MAP_MOND_TEMPLE_FALCON"}]},{"label":"이건 내가 알던 일과 달라. 하프도 여기 있다고 못 하겠어.","keep":"ISK_M02_K_DEAD_C2","items":[{"k":"line","id":"PRO_M02_서풍_매의_사당_009","speaker":"진","text":"알겠습니다. 여기서부터는 현장을 보고 움직이겠습니다. 제 시야 안에 계세요.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_010","speaker":"","text":"진은 추궁하지 않고 조사 인원을 다시 나눴다. 기억에 있을 법한 방을 가리키려던 손을 내렸다. 그럴듯한 짐작 하나가 누군가를 더 위험한 곳으로 보낼 수 있다.","map":"MAP_MOND_TEMPLE_FALCON"}]}]},{"k":"line","id":"PRO_M02_서풍_매의_사당_011","speaker":"","text":"측랑 쪽을 살피던 중 머리 위에서 사슬이 울렸다. 낡은 철문이 내려앉으며 통로를 막았다. 안쪽에 나와 엠버, 바깥에 진과 회수조.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_012","speaker":"진","text":"엠버, 문 옆 장치를 확인해! 이쪽 기둥은 내가 받친다!","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_013","speaker":"엠버","text":"쇠막대는 여기 있어. 벽에 손잡이가 있는데, 추가 사슬에 걸려 있어. 너는 뭐가 보여?","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_014","speaker":"","text":"손잡이, 사슬, 추. 추 아래에 나무 조각이 끼어 있다. 창살 너머로 진의 뒤쪽 대원들이 보인다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"choice","group":"G_PRO_M02_서풍_매의_사당_015","options":[{"label":"추 밑에 나무가 끼었어. 아래로 들어가지 말고 그것부터 빼자.","keep":"REV01_ISK_K_GATE_C1","items":[{"k":"line","id":"PRO_M02_서풍_매의_사당_016","speaker":"","text":"엠버에게 나무 조각의 위치를 짚어 줬다. 그녀가 쇠막대로 조각을 밀어내자 추가 내려앉고 철문이 천천히 올라갔다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_017","speaker":"엠버","text":"잘 봤어. 문만 당겼으면 사슬이 더 조였을 거야. 어떻게 알았어?","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_018","speaker":"나","text":"집에서 서랍 고칠 때 비슷한 거 봤어. 서랍보다 많이 크긴 한데.","map":"MAP_MOND_TEMPLE_FALCON"}]},{"label":"후미가 비었는지 내가 확인할게. 대원들이 다 빠지면 진 단장에게 신호하자.","keep":"REV01_ISK_K_GATE_C2","items":[{"k":"line","id":"PRO_M02_서풍_매의_사당_019","speaker":"","text":"창살 가까이에서 마지막 대원이 지나가는 것을 확인했다. 손을 들어 진에게 빈 퇴로를 가리켰다. 진이 기둥을 눕히고 철문을 들어 올렸다. 엠버가 막대를 빼내고 나를 먼저 내보냈다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_020","speaker":"진","text":"신호 확인했습니다. 두 분 다 다친 곳은 없나요? 사람을 확인해 주신 덕분에 기둥을 놓을 수 있었습니다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_021","speaker":"나","text":"숫자 세는 건 특기예요. 복사기 다음으로.","map":"MAP_MOND_TEMPLE_FALCON"}]},{"label":"손잡이부터 돌려 볼게. 조금만 더 움직이면 걸린 데가 풀릴지도 몰라.","keep":"REV01_ISK_K_GATE_C3","items":[{"k":"line","id":"PRO_M02_서풍_매의_사당_022","speaker":"","text":"손잡이에 힘을 주자 사슬이 짧게 울렸다. 추는 내려가지 않고, 철문이 비스듬히 틀어지며 틈이 더 좁아졌다. 엠버가 내 손을 손잡이에서 떼어 냈다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_023","speaker":"엠버","text":"손 놔! 네 힘이 모자란 게 아니야. 저 추가 아래로 못 내려가고 있어. 내가 나무 조각을 밀어낼 테니까 넌 진 단장한테 문이 기울었다고 알려!","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_024","speaker":"","text":"뒤틀린 철문은 끝까지 올라가지 않았다. 엠버가 안전한 틈을 확인해 나를 먼저 내보내고 뒤따랐다. 손잡이를 잡았던 손에 아직 힘이 들어가 있었다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_025","speaker":"나","text":"…미안. 힘으로 되는 줄 알았어.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_026","speaker":"엠버","text":"됐어. 나왔잖아.","map":"MAP_MOND_TEMPLE_FALCON"}]}]},{"k":"keep","id":"ISK_M02_K_SEARCH_02","text":"회수조는 전원 확인됐습니다. 하프도, 행선지를 알 자료도 없습니다. 흔적은 여기서 끊깁니다. 다른 사당을 무작정 뒤질 수는 없어요."},{"k":"line","id":"PRO_M02_서풍_매의_사당_027","speaker":"","text":"진이 펼친 지도에는 사당 이름이 여러 개였다. 하프가 있다는 표시는 어디에도 없다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_028","speaker":"나","text":"하프는 끊겼네요. …잠깐만요. 숨 좀 돌리고요. 뒤에 오는 사람이 저 때문에 서 있잖아요.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_029","speaker":"진","text":"천천히 하세요.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"choice","group":"G_PRO_M02_서풍_매의_사당_030","options":[{"label":"드발린의 눈물을 찾아봐요. 오염된 결정을 남겼을 수도 있어요.","keep":"ISK_M02_K_TEAR_PLAN_C1","items":[{"k":"line","id":"PRO_M02_서풍_매의_사당_031","speaker":"진","text":"눈물이라면 드발린이 남긴 것을 말씀하시는 거군요. 장소를 짐작할 근거가 있어야 합니다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_032","speaker":"나","text":"하프 대신 쓸 물건은 아니에요. 제가 아는 눈물은 붉은 결정이었고, 드발린을 괴롭히는 것이 거기 남아 있었어요. 드발린이 낮게 날아간 자리에서 그런 걸 봤다는 보고가 있나요?","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_033","speaker":"엠버","text":"있어. 남풍 사자의 사당 외벽. 순찰 때 붉은 게 박혀 있는 걸 봤어. 그때는 뭔지 몰랐는데.","map":"MAP_MOND_TEMPLE_FALCON"}]},{"label":"하프 쪽은 끊겼네요. 눈물이라도 찾아서 직접 확인해 보고 싶어요.","keep":"ISK_M02_K_TEAR_PLAN_C2","items":[{"k":"line","id":"PRO_M02_서풍_매의_사당_034","speaker":"진","text":"눈물이라면 드발린이 남긴 것을 뜻하나요? 다른 사당이라고 무작정 들어갈 수는 없습니다.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_035","speaker":"나","text":"어느 사당에나 하나씩 있을 거라고 믿고 전부 뒤지는 건 저도 사양이에요. 목격담이 있는 곳부터요. 기억 속에선 붉은 결정이었어요.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"line","id":"PRO_M02_서풍_매의_사당_036","speaker":"엠버","text":"붉은 결정이면… 남풍 사자의 사당 외벽에서 봤어. 순찰 때 뭔가 박혀 있었는데, 그때는 그냥 넘어갔어.","map":"MAP_MOND_TEMPLE_FALCON"}]}]},{"k":"line","id":"PRO_M02_서풍_매의_사당_037","speaker":"진","text":"그럼 그곳입니다. 가 보죠.","map":"MAP_MOND_TEMPLE_FALCON"},{"k":"keep","id":"ISK_M02_K_LION_01","text":"남풍 사자의 사당에 닿자 엠버가 본 외벽이 먼저 보였다. 돌 틈에 붉은 결정이 박혀 있었다. 가까이 가자 공기가 무거워졌다. 화면 너머에서 보던 색과 같았다. 다만 화면에서는 냄새가 나지 않았다."},{"k":"keep","id":"CRPG_ISK_K_LION_COMBAT","text":"외벽의 틈으로 가는 길에서 슬라임이 솟고 츄츄족이 달려온다. 결정에 손을 대기 전에 주변부터 정리한다."},{"k":"line","id":"PRO_M02_남풍_사자의_사당_001","speaker":"엠버","text":"여기도 모여 있었네. 결정 때문인가. 뒤로 물러서! 아니, 내 뒤로!","map":"MAP_MOND_TEMPLE_LION"},{"k":"line","id":"PRO_M02_남풍_사자의_사당_002","speaker":"나","text":"네 뒤가 어느 쪽인지부터 말해 줘!","map":"MAP_MOND_TEMPLE_LION"},{"k":"keep","id":"ISK_M02_K_LION_03","text":"진이 주변을 확인하는 동안 회수조는 천을 댄 도구로 결정을 떼어 냈다. 상자에 넣자 붉은빛이 천을 통해 비쳤다. 알고 있는 이야기에서는 여기서 여행자가 손을 대면 빛이 걷혔다."},{"k":"line","id":"PRO_M02_남풍_사자의_사당_003","speaker":"엠버","text":"네 얼굴이 이상해. 뭔가 알지?","map":"MAP_MOND_TEMPLE_LION"},{"k":"line","id":"PRO_M02_남풍_사자의_사당_004","speaker":"나","text":"알아. 아는 이야기에서는 이걸 「그 사람」이 만지면 정화됐어. 그런데 그 사람은 내가 아니야.","map":"MAP_MOND_TEMPLE_LION"},{"k":"line","id":"PRO_M02_남풍_사자의_사당_005","speaker":"진","text":"그 사람이 누구인지는 묻지 않겠습니다. 다만 시도해 보시겠습니까? 위험하다고 판단되면 바로 멈추겠습니다.","map":"MAP_MOND_TEMPLE_LION"},{"k":"choice","group":"G_PRO_M02_남풍_사자의_사당_006","options":[{"label":"그 사람처럼 될지는 모르겠어요. 그래도 한번 만져 볼게요. 이상하면 바로 뗄 테니까요.","keep":"ISK_M02_K_TOUCH_C1","items":[{"k":"line","id":"PRO_M02_남풍_사자의_사당_007","speaker":"엠버","text":"손만 대. 꽉 쥐지 말고. 내가 옆에 있을게.","map":"MAP_MOND_TEMPLE_LION"},{"k":"line","id":"PRO_M02_남풍_사자의_사당_008","speaker":"","text":"엠버가 소매를 정리해 줬다. 숨을 고르고 손가락을 뻗었다. 기대와 별개로 손끝은 떨렸다.","map":"MAP_MOND_TEMPLE_LION"}]},{"label":"정화하던 건 그 사람이었죠. 그래도 제 손에는 반응하는지 한번 보고 싶어요. 조금만 만져 볼 테니, 이상하면 바로 말해 줘요.","keep":"ISK_M02_K_TOUCH_C2","items":[{"k":"line","id":"PRO_M02_남풍_사자의_사당_009","speaker":"엠버","text":"알았어. 하지만 안 되면 바로 말해. 뭔가 보여 줘야 한다고 생각해서 버티지는 마.","map":"MAP_MOND_TEMPLE_LION"},{"k":"line","id":"PRO_M02_남풍_사자의_사당_010","speaker":"","text":"진은 바로 옆에서 접촉을 지켜봤다. 숨을 가다듬고 손가락을 뻗었다. 손끝이 조금 떨렸다.","map":"MAP_MOND_TEMPLE_LION"}]}]},{"k":"line","id":"PRO_M02_남풍_사자의_사당_011","speaker":"","text":"결정은 차가웠다. 그뿐이었다. 빛은 걷히지 않았고, 소리도 나지 않았다. 다른 면도 만져 봤다. 똑같았다.","map":"MAP_MOND_TEMPLE_LION"},{"k":"choice","group":"G_PRO_M02_남풍_사자의_사당_012","options":[{"label":"손은 괜찮아. 그런데 결정은 꿈쩍도 안 하네. 다른 면도 만져 봤는데 똑같고.","keep":"ISK_M02_K_FAIL_03_SAY","items":[{"k":"line","id":"PRO_M02_남풍_사자의_사당_013","speaker":"","text":"손을 뗐다. 엠버가 내 손을 잡아 뒤집어 보았다. 상처는 없었다. 결과를 받아들이는 데에는 손을 대던 때보다 더 오래 걸렸다.","map":"MAP_MOND_TEMPLE_LION"},{"k":"line","id":"PRO_M02_남풍_사자의_사당_014","speaker":"진","text":"알겠습니다. 상자는 봉인해서 성으로 가져가겠습니다. 시도하신 것만으로도 확인된 것이 있습니다.","map":"MAP_MOND_TEMPLE_LION"}]}]},{"k":"line","id":"PRO_M02_남풍_사자의_사당_015","speaker":"","text":"상자 뚜껑이 닫혔다. 붉은빛이 사라지자 사당 안이 갑자기 어두워진 것처럼 느껴졌다.","map":"MAP_MOND_TEMPLE_LION"},{"k":"choice","group":"G_PRO_M02_남풍_사자의_사당_016","options":[{"label":"방법만 알면 될 줄 알았네요. 저는 그 사람이 아닌데.","keep":"ISK_M02_K_FAILURE_C1","items":[{"k":"line","id":"PRO_M02_남풍_사자의_사당_017","speaker":"엠버","text":"그 사람이 아니라서 다행인 것도 있어. 넌 어제 캣테일로 뛰었잖아. 그건 그 사람이 한 게 아니라 네가 한 거야.","map":"MAP_MOND_TEMPLE_LION"},{"k":"line","id":"PRO_M02_남풍_사자의_사당_018","speaker":"","text":"대답하지 못했다. 고개만 끄덕였다.","map":"MAP_MOND_TEMPLE_LION"}]},{"label":"안 돼요. 계속 만져도 똑같아요. 여기서 멈출게요.","keep":"ISK_M02_K_FAILURE_C2","items":[{"k":"line","id":"PRO_M02_남풍_사자의_사당_019","speaker":"진","text":"멈추는 판단도 중요합니다. 잘하셨어요.","map":"MAP_MOND_TEMPLE_LION"},{"k":"line","id":"PRO_M02_남풍_사자의_사당_020","speaker":"","text":"엠버는 내가 완전히 물러난 걸 보고 나서야 도구를 정리했다.","map":"MAP_MOND_TEMPLE_LION"}]}]},{"k":"keep","id":"ISK_M02_K_CITY_END_01","text":"성으로 돌아오자 보수 중인 성문 위에서 망치 소리가 들렸다. 상자를 든 대원이 먼저 본부로 들어갔다. 엠버가 옆에서 걸음을 맞췄다. 말을 걸지 않았다. 그게 고마웠다."},{"k":"keep","id":"REV01_ISK_K_CALLBACK_OBSERVE","text":"사당에서 추 밑의 나무를 먼저 본 건 당신이었죠. 그 눈은 쓸모가 있습니다. 오늘은 그걸로 충분합니다."},{"k":"keep","id":"REV01_ISK_K_CALLBACK_SIGNAL","text":"후미가 비었는지 끝까지 세고 계셨죠. 그런 건 아무나 하지 않습니다. 오늘은 그걸로 충분합니다."},{"k":"keep","id":"REV01_ISK_K_CALLBACK_FORCE","text":"문 손잡이 돌리던 손, 아직 힘 들어가 있지? 풀어. 다음엔 나한테 먼저 물어. 혼내는 거 아니야."},{"k":"line","id":"PRO_M02_귀환_001","speaker":"","text":"본부 앞에서 진이 돌아섰다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_귀환_002","speaker":"진","text":"오늘 확인된 것만 정리하겠습니다. 하프는 도난됐고, 우인단은 사당에서 죽어 있었고, 눈물은 변하지 않았습니다. 기사단의 다음 연락을 기다려 주세요. 쉬십시오. 그건 부탁이 아니라 지시입니다.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_귀환_003","speaker":"나","text":"지시라면 따라야죠. 쉬는 건 제가 제일 잘하는 일이에요.","map":"MAP_MOND_CITY"},{"k":"line","id":"PRO_M02_귀환_004","speaker":"엠버","text":"그 말, 오늘은 반만 믿을게.","map":"MAP_MOND_CITY"},{"k":"keep","id":"ISK_M02_K_GATE","text":"기사단의 다음 연락을 기다리는 중이다. 준비가 되면 이야기를 이어 가자."}],"edits":[],"pre":""},{"id":"ISK_M03_A","entry":"ISK_M03_A_061","items":[{"k":"keep","id":"ISK_M03_A_061","text":"출정한 토벌대는 성 밖 넓은 길에서 대열을 다시 맞췄다. 엠버는 앞을 확인하러 갔고, 나는 보급 수레 옆에서 걷고 있었다. 맡은 일은 상자 수 세기. 적성에 맞았다. 수레가 바퀴에 낀 돌을 빼느라 멈췄을 때, 누가 소매 끝을 잡았다."},{"k":"line","id":"PRO_M03A_출정_001","speaker":"벤티","text":"잠깐, 이쪽에서 얘기할 수 있을까? 오래 붙들진 않을게. 네가 가는 곳에 있는 친구 얘기야."},{"k":"line","id":"PRO_M03A_출정_002","speaker":"","text":"초록 옷에 모자를 쓴 소년이었다. 등에 하프. 토벌대 복장이 아니다. 길에서 몇 걸음 벗어난 바위 뒤로 끌려가면서도 행렬의 깃발은 보였다."},{"k":"line","id":"PRO_M03A_출정_003","speaker":"나","text":"옷은 놓고 얘기하자. 나 지금 대열에서 빠진 사람 찾으러 가는 줄 알았는데, 설마 그 빠진 사람이 내가 되는 거야?"},{"k":"line","id":"PRO_M03A_출정_004","speaker":"벤티","text":"그렇게 만들 생각은 없었어. 미안, 어디로 가는지만 먼저 말하면 네가 돌아서 버릴까 봐. 나는 벤티. 음유시인이야. 드발린을 오래전부터 알아."},{"k":"line","id":"PRO_M03A_출정_005","speaker":"나","text":"…용을 안다고. 아는 사이라고."},{"k":"line","id":"PRO_M03A_출정_006","speaker":"벤티","text":"응. 친구야. 그 애가 몬드를 공격하는 걸 멈추고 싶은 건 나도 같아. 다만 죽이는 것 말고 다른 방법을 찾고 싶어."},{"k":"line","id":"PRO_M03A_출정_007","speaker":"","text":"벤티가 가리킨 것은 대열이 가는 길이 아니라 멀리 남은 몬드의 성벽이었다. 거기서 머리를 감싸고 떨어지는 간판을 피하던 사람들이 떠올랐다. 그 용을 친구라고 부르는 사람이 눈앞에 있었다."},{"k":"choice","group":"G_PRO_M03A_출정_008","options":[{"label":"잠깐만. 친구라는 게 그 용이야? 나를 끌고 와서 할 얘기가 그거였어?","id":"PRO_M03A_출정_009","items":[{"k":"line","id":"PRO_M03A_출정_010","speaker":"벤티","text":"응. 놀랄 만하지. 네가 성에서 본 일을 없던 일로 하자는 게 아니야. 먼저 왜 이런 일이 생겼는지 들어 줘."},{"k":"line","id":"PRO_M03A_출정_011","speaker":"나","text":"듣기는 할게. 대신 수레 출발하면 나 간다. 상자 세는 사람이 없으면 저쪽이 곤란해."},{"k":"line","id":"PRO_M03A_출정_012","speaker":"벤티","text":"그 정도면 충분해."}]},{"label":"친구가 아프다는 얘기면 빨리 해. 남 얘기 듣는 건 잘해. 월급은 안 나오지만.","id":"PRO_M03A_출정_013","items":[{"k":"line","id":"PRO_M03A_출정_014","speaker":"벤티","text":"월급은 못 주지만 노래는 한 곡 줄게. 그래, 아파. 그 애는 지금 아파서 저러는 거야."},{"k":"line","id":"PRO_M03A_출정_015","speaker":"나","text":"아파서 도시를 부순다. 그건 사람으로 치면 어느 정도야?"},{"k":"line","id":"PRO_M03A_출정_016","speaker":"벤티","text":"열이 나서 자기 집 벽을 치는 정도. 다만 손이 저만큼 크고."}]}]},{"k":"line","id":"PRO_M03A_출정_017","speaker":"벤티","text":"그 애는 저 도시를 지켰어. 아주 오래전부터. 사람들이 하늘을 올려다보고 도망치는 대신 안심하던 때도 있었지. 오래전 싸움에서 남은 독이 그 애를 계속 괴롭혔어. 아파하는 동안 혼자 남았고, 지금은 그 고통을 더 깊게 파고드는 말까지 듣고 있어."},{"k":"line","id":"PRO_M03A_출정_018","speaker":"나","text":"누가 옆에서 부추긴다는 거야? 그럼 그놈부터 떼어 놓으면… 아니, 사람인지는 모르겠지만."},{"k":"line","id":"PRO_M03A_출정_019","speaker":"벤티","text":"그것만으로 몸에 남은 독까지 사라지진 않아. 난 그 애가 내 말을 들어야 한다고 생각했는데, 먼저 그 애가 무슨 말을 듣고 있었는지 알아야 했어."},{"k":"line","id":"PRO_M03A_출정_020","speaker":"나","text":"그럼 넌 그동안 어디 있었는데? 오래된 친구라면서."},{"k":"line","id":"PRO_M03A_출정_021","speaker":"","text":"묻고 나서야 말이 거칠었다는 걸 알았다. 벤티는 웃음으로 받아넘기지 않았다."},{"k":"line","id":"PRO_M03A_출정_022","speaker":"벤티","text":"그 애가 기다렸을 때 곁에 있지 못했어. 사정이 있었다는 말로 그 시간을 없앨 수는 없겠지. 그래서 이번에도 늦었다고 말하고 싶지는 않아."},{"k":"line","id":"PRO_M03A_출정_023","speaker":"벤티","text":"고통받는 친구를 멈추는 것과 친구를 없애는 건 같지 않잖아. 말이 닿을 틈을 만들고 싶어. 그래서 그 애가 흘린 눈물을 찾고 있어."},{"k":"line","id":"PRO_M03A_출정_024","speaker":"나","text":"눈물을 찾으면 용을 멈출 수 있다고? 미안한데, 중간이 한참 빠진 것 같아."},{"k":"line","id":"PRO_M03A_출정_025","speaker":"벤티","text":"눈물에는 드발린의 힘이 남아 있어. 천공의 하프에 그 힘을 되돌릴 수 있다면 내 노래도 더 멀리 닿겠지. 다만 눈물에 남은 오염까지 해결해야 해. 찾기만 하면 끝난다는 뜻은 아니야."},{"k":"line","id":"PRO_M03A_출정_026","speaker":"나","text":"근데 왜 나야? 저쪽엔 진짜 기사도 있고, 네 말을 바로 알아들을 사람도 있을 텐데. 난 방금 네가 한 말도 반은 못 따라갔어."},{"k":"line","id":"PRO_M03A_출정_027","speaker":"벤티","text":"네가 행렬에서 무기를 어떻게 쥐어야 하는지 옆 사람한테 묻는 걸 봤어. 누굴 쓰러뜨리러 가는 데 익숙한 사람 같지 않았거든. 내 얘기를 들을 시간은 조금 줄 것 같았어."},{"k":"line","id":"PRO_M03A_출정_028","speaker":"나","text":"그건 판단이 너무 후한데. 그냥 제일 만만해 보였다는 뜻으로도 들려."},{"k":"line","id":"PRO_M03A_출정_029","speaker":"벤티","text":"그렇게 들렸다면 내가 말을 잘못했네. 용을 고칠 특별한 사람이라서 붙잡은 건 아니야. 같이 방법을 생각해 줄 사람이 필요했어."},{"k":"line","id":"PRO_M03A_출정_030","speaker":"나","text":"용 고치는 재주는 확실히 없어. 대신 설명이 빠졌다 싶으면 계속 물어볼 거야. 듣기 좋은 질문만 나오진 않을 텐데, 그건 감수해."},{"k":"line","id":"PRO_M03A_출정_031","speaker":"벤티","text":"응, 감수할게. 방금 어디 있었냐는 질문은 조금 아팠지만… 네가 안 물었으면 나도 대충 넘어갔을지 몰라. 내가 말 돌리면 다시 붙잡아 줘."},{"k":"line","id":"PRO_M03A_출정_032","speaker":"","text":"수레가 다시 움직이기 시작했다. 돌아갈 수 있었다. 이야기를 다 납득할 만큼 아는 건 없었다. 다만 토벌대가 도착한 뒤에는, 지금 해 볼 수 있는 일도 못 해 보게 될 것 같았다."},{"k":"choice","group":"G_PRO_M03A_출정_033","options":[{"label":"다 이해한 건 아니야. 그래도 죽이지 않을 방법이면 찾아보자.","id":"PRO_M03A_출정_034","items":[{"k":"line","id":"PRO_M03A_출정_035","speaker":"벤티","text":"그 정도면 충분해. 모르는 건 물어봐. 모르는 채로 목숨 맡겨 달라고 할 생각은 없어."},{"k":"line","id":"PRO_M03A_출정_036","speaker":"나","text":"목숨은 맡기지 마. 그건 나도 하나뿐이라."}]},{"label":"엠버한테는 알려야 해. 내가 사라지면 찾으러 올 거야. 그런 사람이야.","id":"PRO_M03A_출정_037","items":[{"k":"line","id":"PRO_M03A_출정_038","speaker":"벤티","text":"맞아. 아무 말 없이 데려가면 안 되지. 친구를 구하겠다고 또 다른 친구를 걱정시킬 순 없으니까."},{"k":"line","id":"PRO_M03A_출정_039","speaker":"나","text":"친구… 뭐, 아직 며칠짜리긴 한데."},{"k":"line","id":"PRO_M03A_출정_040","speaker":"벤티","text":"며칠이면 충분히 친구야."}]}]},{"k":"line","id":"PRO_M03A_출정_041","speaker":"","text":"가까이 있던 기사에게 엠버를 불러 달라고 부탁했다. 앞에서 돌아온 엠버는 낯선 음유시인과 나를 번갈아 봤다. 벤티가 목적부터 설명했다. 눈물을 찾아 대화를 시도하겠다고."},{"k":"line","id":"PRO_M03A_출정_042","speaker":"엠버","text":"그게 정말 가능한지는 나도 모르겠어. 진 단장한테는 전할게. 우린 먼저 출발해야 해. 길목 확보하러 가는 사람들까지 여기서 기다리게 할 순 없거든."},{"k":"line","id":"PRO_M03A_출정_043","speaker":"엠버","text":"솔직히 말하면, 난 네가 우리랑 같이 왔으면 좋겠어. 같이 가자고 했을 때부터 내가 볼 수 있는 데 있을 거라고 생각했거든. 갑자기 모르는 길로 간다니까 걱정되는 것도 맞고."},{"k":"line","id":"PRO_M03A_출정_044","speaker":"나","text":"나도 내가 여기서 갈라질 줄은 몰랐어. 들을수록 「됐다」보다 「아직 안 됐다」가 많아서 더 애매해졌고."},{"k":"line","id":"PRO_M03A_출정_045","speaker":"엠버","text":"그래서 가 보고 싶은 거야? 그럼 그렇게 말해. 나는 걱정돼서 붙잡고 싶은데, 네가 내 눈치만 보니까 더 모르겠어. 네 얘기 듣고 나서 잔소리할게."},{"k":"line","id":"PRO_M03A_출정_046","speaker":"벤티","text":"내가 먼저 붙잡았어. 설명도 이제야 겨우 했고. 이 사람이 너한테 변명하게 만들고 싶진 않아."},{"k":"line","id":"PRO_M03A_출정_047","speaker":"엠버","text":"그럼 벤티, 당신한테도 묻겠어. 눈물만 찾으면 해결된다는 건 아니지? 중간에 막히면 이 사람한테도 바로 말해 줘. 다 정해 놓고 따라오라고 하기 없기야."},{"k":"line","id":"PRO_M03A_출정_048","speaker":"벤티","text":"응. 못 찾은 답은 못 찾았다고 말할게."},{"k":"line","id":"PRO_M03A_출정_049","speaker":"","text":"엠버는 벤티의 대답을 듣고도 잠시 나를 봤다. 뒤에서 수레가 움직였다. 그녀는 할 말이 남은 얼굴로 짐끈을 붙잡았다가, 자기가 서 있던 자리를 옆으로 조금 비켜 줬다."},{"k":"line","id":"PRO_M03A_출정_050","speaker":"나","text":"같이 간다고 해 놓고 미안해. 그래도 해 보고 싶어. 돌아갈 곳을 정해 두자."},{"k":"line","id":"PRO_M03A_출정_051","speaker":"엠버","text":"성으로 돌아오면 본부에 알려 줘. 우리 쪽으로 오게 되면 앞에서 소리부터 지르지 말고 경계하는 기사한테 이름을 말해. 못 찾겠으면 더 깊이 들어오지 말고."},{"k":"line","id":"PRO_M03A_출정_052","speaker":"나","text":"응. 성에 먼저 돌아가면 본부에 내 이름 남길게. 너 돌아왔는데 어디 갔는지 모르게 하진 않을게."},{"k":"line","id":"PRO_M03A_출정_053","speaker":"엠버","text":"좋아. 그리고 좋은 방법 찾았으면 꼭 알려 줘. 나도 활 쏘는 것 말고 할 수 있는 게 있으면 알고 싶어. 나랑 다르게 가는 거지, 나 몰래 하는 일은 아니잖아."},{"k":"line","id":"PRO_M03A_출정_054","speaker":"나","text":"그렇게 말하니까 조금 덜 미안하다. 아까는 같이 안 간다고 말하는 게 너 혼자 보내는 것 같아서."},{"k":"line","id":"PRO_M03A_출정_055","speaker":"엠버","text":"나 혼자 아니거든? 저기 사람 수 봐. 걱정할 거면 돌아왔을 때 내가 얘기할 시간이나 남겨 둬. 오늘 있었던 일 다 물어볼 거니까."},{"k":"line","id":"PRO_M03A_출정_056","speaker":"","text":"엠버의 말끝에 평소의 빠른 웃음이 돌아왔다. 하지만 내 짐에서 토벌대 공용 물품을 꺼내 수레에 실을 때, 매듭을 한 번 잘못 잡았다. 그녀는 풀린 끈을 다시 감고 아무 일 없었던 것처럼 당겼다."},{"k":"line","id":"PRO_M03A_출정_057","speaker":"엠버","text":"이 사람 아직 이런 일에 익숙하지 않아. 무리하게 끌고 다니지 말아 줘."},{"k":"line","id":"PRO_M03A_출정_058","speaker":"벤티","text":"응. 같이 돌아올 수 있게 할게."},{"k":"line","id":"PRO_M03A_출정_059","speaker":"","text":"엠버는 한 번 더 뒤를 돌아보고 대열로 뛰어갔다. 붉은 옷이 깃발 사이에 가려지고 나서야 벤티에게 물을 틈이 생겼다."},{"k":"line","id":"PRO_M03A_출정_060","speaker":"나","text":"그래서 눈물은 어디 있는데? 설마 지금부터 바닥 보고 찾는 건 아니지?"},{"k":"keep","id":"ISK_M03_A_086","text":"그렇게 찾기엔 몬드가 너무 넓지. 든든한 친구한테 물어보자. 들리는 얘기가 많은 사람이거든. 다이루크라고 해."},{"k":"line","id":"PRO_M03A_출정_061","speaker":"나","text":"친구가 많네. 용도 친구, 그 사람도 친구."},{"k":"line","id":"PRO_M03A_출정_062","speaker":"벤티","text":"음유시인이 친구 없으면 누가 노래를 들어 주겠어."},{"k":"keep","id":"ISK_M03_A_087","text":"다운 와이너리. 포도밭 한가운데 큰 저택이었다. 문이 열리자 벤티는 제집처럼 손을 들었다. 붉은 머리의 남자는 그 뒤에 선 나와 먼지 묻은 짐까지 차례로 봤다. 인사가 끝나기도 전에, 용건부터 말하라는 시선이 벤티에게 돌아갔다."},{"k":"line","id":"PRO_M03A_다운_와이너리_001","speaker":"벤티","text":"다이루크 어르신, 오랜만이야. 오늘은 든든한 동료도 데려왔어. 부탁할 일이 조금 있는데, 드발린의 눈물이 떨어진 곳을 찾고 있거든."},{"k":"choice","group":"G_PRO_M03A_다운_와이너리_002","options":[{"label":"먼저 이름부터 듣지. 그리고 어디까지 알고 왔는지도.","keep":"ISK_M03_A_089","items":[{"k":"line","id":"PRO_M03A_다운_와이너리_003","speaker":"나","text":"{PLAYER_NAME}이야. 아는 건… 용이 아프고, 눈물을 찾아야 한다는 데까지. 솔직히 아는 것보다 물어볼 게 더 많아."},{"k":"line","id":"PRO_M03A_다운_와이너리_004","speaker":"다이루크","text":"모르는 걸 모른다고 하는군. 그건 좋다."}]},{"label":"자네였군. 와이너리 장부 일 이후로 처음이군. 이번엔 벤티와 함께라니, 어디까지 알고 왔는지부터 듣지.","keep":"ISK_M03_A_V143_089K","items":[{"k":"line","id":"PRO_M03A_다운_와이너리_005","speaker":"나","text":"용이 아프고, 눈물을 찾아야 한다는 데까지. 솔직히 아는 것보다 물어볼 게 더 많아. 장부 때랑 똑같지."},{"k":"line","id":"PRO_M03A_다운_와이너리_006","speaker":"다이루크","text":"그때도 숫자는 틀리지 않았지. 앉아."}]}]},{"k":"line","id":"PRO_M03A_다운_와이너리_007","speaker":"벤티","text":"내가 말한 든든한 친구가 바로 이분이야. 몬드에서 무슨 일이 일어나는지 나보다 빨리 듣는 때도 있으니까."},{"k":"line","id":"PRO_M03A_다운_와이너리_008","speaker":"다이루크","text":"그런 소개로 설명을 끝낼 생각은 아니겠지. 무슨 일을 맡기려고 데려왔나?"},{"k":"line","id":"PRO_M03A_다운_와이너리_009","speaker":"나","text":"맡겨졌다기보단 같이 해 보자고 해서 온 거야. 근데 나한테는 「친구」라고 했고 여기 와선 「동료」라고 하네. 소개가 조금씩 좋아져."},{"k":"line","id":"PRO_M03A_다운_와이너리_010","speaker":"다이루크","text":"그건 일을 끝낸 뒤에 정하면 된다. 앉아. 서서 지도를 내려다보면 보이는 것도 놓쳐."},{"k":"line","id":"PRO_M03A_다운_와이너리_011","speaker":"","text":"다이루크는 내 앞에 물잔을 놓고 자기 의자를 조금 옆으로 밀었다. 벤티가 기대하는 눈으로 보자 같은 물병을 벤티 앞에도 놓았다. 포도주는 아니었다."},{"k":"line","id":"PRO_M03A_다운_와이너리_012","speaker":"벤티","text":"아직 노래도 안 불렀는데 목부터 축이게 해 주네. 역시 친구를 잘 찾아왔어."},{"k":"line","id":"PRO_M03A_다운_와이너리_013","speaker":"다이루크","text":"목을 축였으면 처음부터 설명해. 모르는 게 있다는 건 알겠다. 그럼 직접 본 것부터 말해. 드발린이 성을 공격했을 때 어디 있었지? 벤티한테 들은 얘기는 그다음이다."},{"k":"line","id":"PRO_M03A_다운_와이너리_014","speaker":"","text":"기사단 본부 복도, 창문 없는 벽, 붙잡았던 소매. 설명하다가 바람이 어느 방향이었는지 헷갈려 멈추자 다이루크가 지도를 돌려 줬다. 벤티는 내가 말을 마칠 때까지 끼어들지 않았다."},{"k":"line","id":"PRO_M03A_다운_와이너리_015","speaker":"다이루크","text":"도시에 있었군. 그 일을 겪고도 벤티를 따라온 이유가 있나? 용한테 사정이 있다는 얘기만으로 마음을 정하긴 어려웠을 텐데."},{"k":"line","id":"PRO_M03A_다운_와이너리_016","speaker":"나","text":"솔직히 그 얘기만 들었으면 안 왔을지도 몰라. 그런데 곧 죽으러 간다니까, 나중에 다른 방법도 있었다고 알게 되는 게 싫었어. 용을 이해했다는 뜻은 아니고. 아직 무서워."},{"k":"line","id":"PRO_M03A_다운_와이너리_017","speaker":"벤티","text":"내가 부탁한 것도 거기까지야. 당장 드발린 편이 되라고는 안 했어."},{"k":"line","id":"PRO_M03A_다운_와이너리_018","speaker":"다이루크","text":"그렇다면 시간을 낭비하지 말아야겠군. 사당 근처에서 이상한 결정이 발견됐다는 보고는 있다. 다만 소문이 한 목격담에서 갈라진 건지, 서로 다른 물건을 본 건지는 확인해야 해."},{"k":"line","id":"PRO_M03A_다운_와이너리_019","speaker":"나","text":"보고까지 있어? 난 지금부터 사람 붙잡고 「용 눈물 보셨어요」 하고 다녀야 하는 줄 알았는데."},{"k":"line","id":"PRO_M03A_다운_와이너리_020","speaker":"다이루크","text":"그렇게 묻고 다니면 하루 안에 몬드 전체에 자네 얘기가 퍼지겠지. 답을 들을 수 있을지는 별개고."},{"k":"line","id":"PRO_M03A_다운_와이너리_021","speaker":"벤티","text":"그 노래는 조금 곤란하겠다. 드발린을 만나기도 전에 우리가 명물이 되면 숨어서 움직이기 어려우니까."},{"k":"line","id":"PRO_M03A_다운_와이너리_022","speaker":"","text":"다이루크가 쪽지를 밖으로 보냈다. 기다리는 동안 벤티는 지도의 사당 표식을 짚었다. 서풍 매의 사당, 북풍 늑대의 사당, 남풍 사자의 사당. 이름을 하나씩 되물었다. 다 처음 듣는 이름이었다. 외우는 건 자신 있었다. 회의록 쓰던 사람이니까."},{"k":"line","id":"PRO_M03A_다운_와이너리_023","speaker":"","text":"첫 쪽지에는 같은 사당을 두 이름으로 부른 목격담이 있었다. 다이루크가 두 쪽지를 포개자 지명 아래의 방향 표시가 반대였다."},{"k":"line","id":"PRO_M03A_다운_와이너리_024","speaker":"나","text":"여기는 「들어가서 왼쪽」이고 저쪽은 「나와서 오른쪽」이래. 둘 다 같은 자리 얘기 아니야?"},{"k":"line","id":"PRO_M03A_다운_와이너리_025","speaker":"다이루크","text":"그렇겠군. 이쪽 문을 썼다면 맞아. 자네는 위치를 하나 줄였어."},{"k":"line","id":"PRO_M03A_다운_와이너리_026","speaker":"벤티","text":"벌써 지도가 우리 말을 조금씩 듣기 시작하네. 아까까지만 해도 지명 들을 때마다 지도부터 돌렸는데."},{"k":"line","id":"PRO_M03A_다운_와이너리_027","speaker":"나","text":"그건 다이루크가 자기 쪽에서 읽기 좋게 펴 놔서 그래. 내가 몬드 지리를 거꾸로 배운 게 아니고."},{"k":"line","id":"PRO_M03A_다운_와이너리_028","speaker":"","text":"다이루크는 말없이 지도를 가운데로 밀었다. 벤티가 웃자 펜을 건넸다. 구경할 거면 그만큼은 하라는 뜻을 알아들은 벤티가 확인된 사당에 동그라미를 그렸다."},{"k":"line","id":"PRO_M03A_다운_와이너리_029","speaker":"다이루크","text":"하나 더 들어오면 출발하겠다. 그동안 천과 등불을 챙겨. 결정이 빛난다고 주변 길까지 보여 주는 건 아닐 테니."},{"k":"line","id":"PRO_M03A_다운_와이너리_030","speaker":"나","text":"같이 와 주는 거야? 정보를 줬으니 이쪽 할 일 끝이라고 해도 고마워했을 텐데."},{"k":"line","id":"PRO_M03A_다운_와이너리_031","speaker":"다이루크","text":"성 밖에서 무슨 일이 벌어지는지 보고만 받을 생각은 없다. 자네를 따라가는 게 아니라 같은 일 때문에 가는 거야."},{"k":"line","id":"PRO_M03A_다운_와이너리_032","speaker":"벤티","text":"그래도 같이 가는 건 맞지. 아까 소개가 조금 더 정확해졌네."},{"k":"line","id":"PRO_M03A_다운_와이너리_033","speaker":"다이루크","text":"아직 출발도 안 했다. 수색할 곳은 세 군데로 좁혔어. 누가 봤는지도 확인했다. 물건이 아직 남아 있는지는 가서 봐야 해."},{"k":"choice","group":"G_PRO_M03A_다운_와이너리_034","options":[{"label":"이렇게 빨리 알아낼 수 있으면 처음부터 여기 올 걸 그랬네.","id":"PRO_M03A_다운_와이너리_035","items":[{"k":"line","id":"PRO_M03A_다운_와이너리_036","speaker":"다이루크","text":"소문을 모으는 것과 답을 얻는 건 달라. 지금부터 직접 확인해야 한다. 자네 몫도 남아 있어."},{"k":"line","id":"PRO_M03A_다운_와이너리_037","speaker":"나","text":"내 몫이 뭔데? 설마 등불."},{"k":"line","id":"PRO_M03A_다운_와이너리_038","speaker":"다이루크","text":"등불이다."}]},{"label":"도움받는 대신 내가 할 수 있는 일은 뭐야?","id":"PRO_M03A_다운_와이너리_039","items":[{"k":"line","id":"PRO_M03A_다운_와이너리_040","speaker":"다이루크","text":"찾은 것의 위치와 상태를 기억해 둬. 위험한 물건에 먼저 손대지 말고. 그 두 가지만 지켜도 수색은 빨라진다."},{"k":"line","id":"PRO_M03A_다운_와이너리_041","speaker":"나","text":"기억하는 건 잘해. 손 안 대는 건… 노력할게."},{"k":"line","id":"PRO_M03A_다운_와이너리_042","speaker":"벤티","text":"「노력」이 들어가는 게 조금 걱정되는데."}]}]},{"k":"keep","id":"ISK_M03_A_101","text":"서풍 매의 사당 안으로 들어서자 발소리가 생각보다 멀리 울렸다. 등불을 돌릴 때마다 낡은 벽에 그림자가 크게 흔들렸다. 붉은 반사가 벽 틈에 잠깐 나타났다가 사라졌다. 보고된 자리는 가까운 것 같았는데, 그대로 걸어가자 반대편 바닥에서 다시 빛이 보였다."},{"k":"keep","id":"CRPG_ISK_A_FALCON_COMBAT","text":"벽 틈의 붉은 빛을 향해 다가가자 젖은 석판 사이에서 슬라임이 솟는다. 뒤쪽의 츄츄족까지 통로를 막아선다. 결정을 살피기 전에 길부터 연다."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_001","speaker":"","text":"다이루크의 검이 지나간 자리에 불이 남았다. 벤티는 바람으로 슬라임을 벽에 붙였다. 나는 등불을 들고 뒤에 서 있었다. 그것도 일이라고 두 사람이 말해 줬다. 믿기로 했다."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_002","speaker":"나","text":"움직이는 거 아니야? 저기 있던 게 왜 이쪽에 있어. 눈물도 도망가?"},{"k":"line","id":"PRO_M03A_서풍_매의_사당_003","speaker":"다이루크","text":"등불을 멈춰 봐. 자네가 손을 움직일 때만 위치가 바뀌고 있다."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_004","speaker":"벤티","text":"아래쪽을 비춰 줄래? 그래, 거기서 조금만 옆으로. 빛이 돌아오는 곳과 물건이 있는 곳이 다른 모양이야."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_005","speaker":"","text":"셋이 한꺼번에 몸을 옮기다 어깨가 부딪혔다."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_006","speaker":"나","text":"나머지 두 사람은 그냥 있어. 내가 돌릴게. 동시에 움직이니까 누가 뭘 본 건지 하나도 모르겠어."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_007","speaker":"다이루크","text":"좋아. 거기서 멈춰. 틈 안에 있다."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_008","speaker":"","text":"다이루크가 돌을 치우자 안쪽에서 결정 하나가 드러났다. 벤티의 표정이 먼저 바뀌었다. 손을 뻗었다가, 내 등불 앞에서 멈췄다."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_009","speaker":"벤티","text":"맞아. 드발린의 눈물이야. 하지만 이 색은…. 오염이 깊어. 맨손으로 잡지 마."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_010","speaker":"나","text":"찾기는 찾았네. 그런데 이러면 가져가도 되는 거야?"},{"k":"line","id":"PRO_M03A_서풍_매의_사당_011","speaker":"벤티","text":"따로 싸서 가져가자. 얼마나 남아 있는지 살펴봐야 해. 이걸 깨끗하다고 생각하고 하프에 대면 안 돼."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_012","speaker":"다이루크","text":"그럼 상태가 다른 게 있는지도 확인해야겠군. 하나 찾았다고 나머지를 생략하진 않겠다."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_013","speaker":"나","text":"난 눈물이라고 해서 물병 같은 걸 가져와야 하나 했어. 이렇게 단단한 걸 보니 얼마나 아팠는지 더 모르겠네."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_014","speaker":"벤티","text":"굳어 버리면 멈춘 것처럼 보이지. 하지만 안에 남은 힘이 편안하지 않아. 손에 올려놓고 그냥 예쁜 돌이라고 말할 수 없는 이유야."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_015","speaker":"다이루크","text":"계속 들고 있지는 마. 나머지를 찾는 동안 네가 지치면 하프가 돌아와도 소용없어."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_016","speaker":"벤티","text":"걱정해 주는 거야, 다이루크 어르신?"},{"k":"line","id":"PRO_M03A_서풍_매의_사당_017","speaker":"다이루크","text":"감쌀 천이 더 필요한지나 말해."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_018","speaker":"","text":"벤티는 천 한 장을 더 받아 결정을 감쌌다. 돌아서는 길에 또 붉은 반사가 보였다. 이번에는 손부터 뻗지 않고 벤티를 불렀다. 같은 결정의 빛이 깨진 돌에 비친 거였다."},{"k":"keep","id":"ISK_M03_A_107","text":"잘 불렀어. 헷갈릴 수 있지. 우리가 찾는 게 얼마나 작아 보이는지도 이제 알았고."},{"k":"line","id":"PRO_M03A_서풍_매의_사당_019","speaker":"나","text":"손 안 댔다. 봤지? 노력했어."},{"k":"keep","id":"ISK_M03_A_108","text":"두 번째 사당으로 가는 길은 보고받은 길과 달랐다. 무너진 벽 때문에 돌아가야 했고, 안쪽에서는 마물들이 통로를 차지하고 있었다. 다이루크가 앞을 정리하는 동안 벤티는 나를 기둥 뒤에 세웠다."},{"k":"keep","id":"CRPG_ISK_A_WOLF_COMBAT","text":"다이루크가 정리한 앞길 너머에서 남은 마물들이 몰려온다. 좁은 물길 양쪽에 활을 든 츄츄족과 슬라임. 더 들어가기 전에 통로를 확보한다."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_001","speaker":"다이루크","text":"이쪽은 비었어. 바닥을 확인하고 와. 어두운 곳에 손부터 넣지는 마."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_002","speaker":"","text":"북풍 늑대의 사당 안쪽은 통로가 막혀 있었다. 무너진 돌 위로 지나갈 수는 있는데 등불이 먼저 걸렸다. 옆으로 비집고 들어가려 하자 다이루크가 반대편에서 손을 내밀었다."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_003","speaker":"다이루크","text":"등불부터 줘. 몸을 돌린 채 짐까지 지키려고 하면 그 틈에 끼인다."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_004","speaker":"나","text":"내가 끼면 끌어낼 수는 있지? 지금이라도 물어봐야 할 것 같아서."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_005","speaker":"다이루크","text":"가능하면 그런 일은 만들지 말고. 왼쪽 어깨부터 빼."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_006","speaker":"","text":"돌을 긁으며 빠져나왔다. 외투 어깨가 찢어졌다. 엠버가 끈 묶는 법을 가르쳐 준 외투다. 나중에 혼날 거다."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_007","speaker":"벤티","text":"찾은 것 같아. 그런데 안쪽이 너무 어두워. 등불을 낮춰 줘. 이번엔 빛을 쫓아갈 필요는 없겠네."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_008","speaker":"나","text":"등불 담당은 조금 익숙해졌어. 여기서 갑자기 전문 지식을 물으면 아직 안 되고."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_009","speaker":"벤티","text":"지금은 안 물을게. 나도 네가 딱 맞는 높이에서 빛을 멈춰 주는 게 더 반가우니까."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_010","speaker":"","text":"두 번째 눈물은 낮은 돌턱 뒤에 끼어 있었다. 등불에 비추자 첫 번째와 같은 붉은 기운. 꾸러미를 하나 더 내밀었다. 찾았다는 기쁨보다 같은 문제가 반복된다는 걱정이 먼저 왔다."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_011","speaker":"벤티","text":"이것도 같네. 드발린이 아팠다는 흔적을 모으고 있는 기분이야."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_012","speaker":"","text":"벤티가 천을 접는 속도가 첫 사당보다 느려졌다."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_013","speaker":"나","text":"깨끗한 걸 하나라도 찾으면 조금 달라질까 싶었는데. 그래도 두 개면 한 개보다는 낫겠지?"},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_014","speaker":"벤티","text":"두 개가 됐는데도 오염은 그대로네. 세 번째까지 같으면… 하프 앞에서도 지금 같은 얼굴을 하게 될까 봐, 그게 걱정이야."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_015","speaker":"다이루크","text":"세 번째는 아직 안 봤어. 거기까지 확인하지. 같은 걸 두 번 들여다보다 해가 지게 할 수는 없으니까."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_016","speaker":"나","text":"나도 좋은 말이 안 나오네. 그래도 마지막은 보고 가자. 두 군데나 뒤졌는데 여기서 돌아가긴 싫어."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_017","speaker":"","text":"밖으로 나오자 멀리 토벌대가 갈 길의 능선이 보였다. 저절로 그쪽을 봤다."},{"k":"line","id":"PRO_M03A_북풍_늑대의_사당_018","speaker":"나","text":"이걸 모으는 동안 토벌대도 계속 가고 있겠지?"},{"k":"keep","id":"ISK_M03_A_113","text":"그렇겠지. 그렇다고 확인을 빼먹으면 돌아갈 이유도 없어진다. 남은 곳을 마저 보자."},{"k":"keep","id":"ISK_M03_A_114","text":"남풍 사자의 사당에서는 천장 틈으로 흰빛이 내려왔다. 마지막 목격 지점을 찾았을 때 세 사람의 그림자가 같은 바닥에 겹쳤다. 벤티는 곧장 결정을 집지 않았다. 다이루크가 주변을 비우고 내가 등불을 낮춰 주기를 기다렸다. 말하지 않아도 순서가 생겼다."},{"k":"keep","id":"CRPG_ISK_A_LION_COMBAT","text":"등불이 낮아지자 무너진 받침 아래의 물결이 움직인다. 숨어 있던 슬라임과 츄츄족이 다가온다. 마지막 결정을 옮기기 전에 주변부터 막는다."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_001","speaker":"벤티","text":"저기 있어. 세 번째야. 이걸 가져가면 보고받은 곳은 모두 확인한 거네."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_002","speaker":"나","text":"이번에도 색이 같네. 안 묻고 싶었는데, 빨갛게 보이는 게 그냥 등불 탓인 건 아니지?"},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_003","speaker":"벤티","text":"응. 햇빛에서도 같아. 잘못 본 게 아니야."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_004","speaker":"","text":"벤티가 마지막 결정을 천 위에 내려놓았다. 빈 꾸러미가 더 없는지 짐을 뒤지다가, 세 장을 다 썼다는 걸 떠올리고 멈췄다. 「다 찾았다」는 말을 가장 듣고 싶었던 순간에, 그 말만으로는 기뻐할 수 없게 됐다."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_005","speaker":"다이루크","text":"수색은 끝났어. 다음에 할 일을 정하지. 같은 자리에 서서 결정의 색이 바뀌길 기다릴 시간은 없으니까."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_006","speaker":"나","text":"우리가 아직 못 찾은 데가 있는 건 아닐까? 더 깨끗한 눈물이 다른 사당에 있다거나."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_007","speaker":"다이루크","text":"지금 그런 보고는 없어. 아쉬워서 다시 시작하는 거라면, 다른 필요한 물건을 먼저 찾는 편이 낫다."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_008","speaker":"벤티","text":"맞아. 눈물을 더 모으는 것만으로 해결되는 문제는 아니겠지. 이번에는 하프를 되찾아 보자."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_009","speaker":"다이루크","text":"이제 하프 차례군. 성당에서 가져간 자들이 물건을 두었다는 곳은 따로 확인해 뒀다. 눈물을 찾는 동안 들어온 보고야."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_010","speaker":"나","text":"하프도 도둑맞았다고? 필요한 것마다 전부 없네. 누가 목록 보고 치운 것처럼."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_011","speaker":"벤티","text":"원래 자리에 그대로 있었다면 좋았겠지. 그래도 이번엔 찾아갈 곳이 있어. 눈물은 내가 계속 갖고 있을게."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_012","speaker":"나","text":"그 하프는 원래 누구 거야? 우리도 허락 없이 가져오면 일이 하나 더 생기는 거 아닌가 해서."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_013","speaker":"벤티","text":"성당에서 보관하던 천공의 하프야. 지금은 누가 훔쳐 갔고. 되찾으면 사라진 곳에 돌아갔다는 설명까지 해야겠지."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_014","speaker":"다이루크","text":"우인단이 보관처로 쓰는 사당이다. 여태까지처럼 빈 방에서 결정만 찾는다고 생각하지 마. 들키면 우리가 뭘 찾는지도 알게 될 테니."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_015","speaker":"나","text":"우인단이 뭔데?"},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_016","speaker":"다이루크","text":"스네즈나야의 사절단. 외교관 행세를 하지만 하는 일은 외교가 아니다. 그 정도만 알아 둬."},{"k":"line","id":"PRO_M03A_남풍_사자의_사당_017","speaker":"나","text":"외교관 행세. 알았어. 우리 회사에도 그런 부서 있었어."},{"k":"keep","id":"ISK_M03_A_118","text":"비어 있는 꾸러미를 접어 넣었다. 다이루크가 마지막으로 주변을 확인하고 밖으로 나갔다. 벤티는 눈물을 하나씩 다시 감싼 뒤 한동안 손을 떼지 않았다. 셋이 길을 나설 때, 나는 하프를 찾으면 소리가 날 거라고 막연히 생각했다."},{"k":"keep","id":"ISK_M03_A_119","text":"하프가 옮겨졌다는 사당에는 입구를 지키는 사람이 없었다. 다이루크가 먼저 걸음을 멈췄다. 안쪽에 떨어진 횃불 하나가 거의 꺼져 가고 있었다. 그 너머로 우인단 복장의 사람들이 쓰러져 있었다."},{"k":"line","id":"PRO_M03A_우인단의_사당_001","speaker":"","text":"처음에는 잠든 사람이라고 생각하려 했다. 기대어 앉은 자세는 그럴듯했다. 하지만 발소리에도 고개가 돌아오지 않았다. 벤티가 한 걸음 앞을 가로막았다."},{"k":"line","id":"PRO_M03A_우인단의_사당_002","speaker":"벤티","text":"여기 잠깐 있어 줘. 다이루크가 먼저 보고 올 거야."},{"k":"line","id":"PRO_M03A_우인단의_사당_003","speaker":"나","text":"다 들을 만큼 크게 들어왔는데 아무도 안 움직이네. 저 사람… 우리 쪽을 보고 있는 거야?"},{"k":"line","id":"PRO_M03A_우인단의_사당_004","speaker":"","text":"벤티는 대답 대신 내 시선 앞에서 몸을 조금 옮겼다. 다이루크가 첫 번째 사람 옆에 무릎을 꿇었다가 일어났다."},{"k":"line","id":"PRO_M03A_우인단의_사당_005","speaker":"다이루크","text":"뒤에 있어. 살아 있는 사람이 있는지 내가 확인하겠다."},{"k":"line","id":"PRO_M03A_우인단의_사당_006","speaker":"","text":"대답은 없었다. 다이루크가 방을 차례로 확인하고 돌아왔다. 벤티는 바닥에 닿지 않게 눈물 꾸러미를 끌어안고 있었다."},{"k":"line","id":"PRO_M03A_우인단의_사당_007","speaker":"다이루크","text":"이곳에 있던 우인단은 모두 죽었어. 싸운 흔적이 없다. 무기는 전부 칼집에 들어 있고, 벽에도 바닥에도 긁힌 자리 하나 없어. 앉은 자리에서 그대로 멎은 것처럼."},{"k":"line","id":"PRO_M03A_우인단의_사당_008","speaker":"벤티","text":"그럼… 왜?"},{"k":"line","id":"PRO_M03A_우인단의_사당_009","speaker":"다이루크","text":"모른다. 누가 한 일인지도, 무엇이 한 일인지도. 아직 안 본 통로로 들어가지 마."},{"k":"line","id":"PRO_M03A_우인단의_사당_010","speaker":"나","text":"싸울 수도 있다고 생각했는데… 이렇게 있는 건 상상을 못 했어."},{"k":"line","id":"PRO_M03A_우인단의_사당_011","speaker":"다이루크","text":"더 가까이 볼 필요는 없어. 벽 쪽을 보고 숨부터 쉬게. 다리에 힘이 풀리면 거기 앉아 있어."},{"k":"line","id":"PRO_M03A_우인단의_사당_012","speaker":"벤티","text":"바깥에서 기다릴래? 나도 같이 나가 있을 수 있어."},{"k":"line","id":"PRO_M03A_우인단의_사당_013","speaker":"나","text":"잠깐만. 조금만 여기서 숨 돌릴게. 밖으로 나가면 너희가 부르는 소리를 못 들을 것 같아."},{"k":"line","id":"PRO_M03A_우인단의_사당_014","speaker":"","text":"벽을 짚었다. 손바닥이 차가웠다. 농담이 하나도 떠오르지 않았다. 조금 전까지는 물건을 모으면 돌아갈 수 있는 일처럼 여겼다. 이제는 사당 문을 나간 뒤에도 이 방이 떠오를 것 같았다. 벤티는 재촉하지 않고 같은 자리에 머물렀다."},{"k":"choice","group":"G_PRO_M03A_우인단의_사당_015","options":[{"label":"우리가 너무 늦게 온 거야?","id":"PRO_M03A_우인단의_사당_016","items":[{"k":"line","id":"PRO_M03A_우인단의_사당_017","speaker":"다이루크","text":"그 말로 설명할 수 있는 상황인지도 아직 몰라. 분명한 건 우리가 도착하기 전에 벌어졌다는 것뿐이다."}]},{"label":"하프를 가져간 사람도 여기 있는 거야?","id":"PRO_M03A_우인단의_사당_018","items":[{"k":"line","id":"PRO_M03A_우인단의_사당_019","speaker":"다이루크","text":"옷차림만으로 누가 직접 가져갔는지는 알 수 없어. 물건부터 확인하겠다. 자네는 벤티 곁에 있어."}]}]},{"k":"line","id":"PRO_M03A_우인단의_사당_020","speaker":"","text":"옆방의 낮은 받침 위에 천을 덮은 물건이 있었다. 다이루크가 천을 걷자 하프의 윤곽이 드러났다. 멀쩡했다. 줄 하나 끊어지지 않았다. 벤티는 바로 손을 뻗지 않고 줄과 틀을 하나씩 확인했다."},{"k":"line","id":"PRO_M03A_우인단의_사당_021","speaker":"벤티","text":"천공의 하프야. 여기 남아 있었네…. 찾았다고 기뻐하기가 어렵다."},{"k":"line","id":"PRO_M03A_우인단의_사당_022","speaker":"나","text":"하프 찾으러 왔다가 이런 걸 보게 될 줄은 몰랐어. 훔쳐 간 사람들은 그대로 죽어 있고, 훔친 물건은 그대로 남아 있고."},{"k":"line","id":"PRO_M03A_우인단의_사당_023","speaker":"다이루크","text":"하프를 가져가지 않은 이유도 알아봐야겠군. 돌아가면 그 위치까지 전하겠다. 자네는 그 천을 잡고 있어."},{"k":"line","id":"PRO_M03A_우인단의_사당_024","speaker":"벤티","text":"이 하프가 대답해 주면 좋겠는데. 오래된 노래는 많이 기억해도, 여기서 무슨 일이 있었는지는 들려주지 않네."},{"k":"line","id":"PRO_M03A_우인단의_사당_025","speaker":"","text":"벤티는 줄을 튕기려다 손을 멈췄다. 내가 천을 들고 기다리는 걸 보고서야 하프를 받침에서 들어 올렸다. 목재가 돌에서 떨어지는 작은 소리가 방 안에 크게 울렸다."},{"k":"line","id":"PRO_M03A_우인단의_사당_026","speaker":"나","text":"지금 연주하지 않아도 돼. 밖에서 소리 나는지 들어 보자. 여기는… 무슨 소리가 나도 더 오래 남을 것 같아."},{"k":"line","id":"PRO_M03A_우인단의_사당_027","speaker":"벤티","text":"응. 그러자. 천을 조금만 더 펴 줘."},{"k":"line","id":"PRO_M03A_우인단의_사당_028","speaker":"다이루크","text":"물건이 남아 있다고 단순한 다툼이 되는 건 아니야. 사망자와 하프의 위치는 따로 기록하겠다. 돌아가면 기사단에 알리지."},{"k":"line","id":"PRO_M03A_우인단의_사당_029","speaker":"나","text":"응. 그냥 없었던 일로 하고 나가지는 말자. 지금은 하프부터 가져가더라도."},{"k":"keep","id":"ISK_M03_A_132","text":"다이루크는 위치를 적은 종이를 접어 넣고 출입문을 다시 확인했다. 시신의 소지품에는 손대지 않았다. 벤티가 하프를 들어 올릴 수 있도록 빈 천을 펼쳤다. 나갈 때도 아무도 뒤에서 우리를 부르지 않았다."},{"k":"keep","id":"ISK_M03_A_133","text":"바다가 보이는 절벽에 올랐을 때는 옷 안쪽까지 바람이 스며들었다. 벤티는 하프를 내려놓고 눈물 꾸러미를 펼쳤다. 붉은 결정 세 개가 천 위에 놓였다. 다이루크는 내려갈 길을 확인한 뒤 돌아왔다."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_001","speaker":"","text":"셋은 절벽 위에서 한동안 말이 없었다. 사당의 냄새는 바닷바람에 사라졌는데, 나는 여전히 손을 옷에 문지르고 있었다. 다이루크가 물을 건넸다. 이번에는 손을 씻는 대신 마셨다."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_002","speaker":"나","text":"토벌대에서 빠져나올 때는 지금쯤 알아낸 게 더 많을 줄 알았어. 눈물도 하프도 찾았는데, 설명 못 하는 것만 늘어난 느낌이야."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_003","speaker":"다이루크","text":"눈물과 하프는 찾았어. 사당에서 본 일은 내가 기사단에 전하겠다. 지금은 이 둘로 드발린을 불러낼 수 있는지 확인하지. 벤티, 시작할 수 있겠나?"},{"k":"line","id":"PRO_M03A_별을_따는_절벽_004","speaker":"벤티","text":"노래 한 곡에 너무 많은 걸 부탁하는 것 같아도, 드발린에게 닿을 수 있는 소리를 찾고 싶어."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_005","speaker":"나","text":"어떤 노래를 좋아하는데? 내가 아는 노래냐고 묻는 건 아니야. 용이 뭘 좋아할지 전혀 모르겠어서."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_006","speaker":"벤티","text":"높이 멀리 뻗는 소리. 바람이 길을 막지 않는 곳에서 끝까지 듣곤 했어. 끝난 다음에 한참 아무 말도 안 하면, 난 한 곡 더 듣고 싶다는 뜻으로 받아들였지."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_007","speaker":"다이루크","text":"그건 네가 부르고 싶었던 것 아닌가?"},{"k":"line","id":"PRO_M03A_별을_따는_절벽_008","speaker":"벤티","text":"그럴 때도 있었겠지. 그래서 이번에는 혼자 결론 내리지 않고 물어보려고. 듣고 싶니, 여기 있어도 되니, 그다음에는… 아프니."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_009","speaker":"","text":"벤티의 마지막 말은 바람에 섞여 작아졌다. 다이루크는 물통을 닫고 하프 앞의 결정을 봤다."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_010","speaker":"다이루크","text":"불러내는 데 성공하면 우리가 말할 시간은 있겠나?"},{"k":"line","id":"PRO_M03A_별을_따는_절벽_011","speaker":"벤티","text":"약속할 수는 없어. 눈물은 아직 오염돼 있어. 하프를 온전히 회복시키지도, 드발린의 고통을 없애지도 못했어. 그래도 내 목소리에 잠깐 귀를 기울여 준다면… 그 틈을 놓치고 싶지 않아."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_012","speaker":"나","text":"부르는 것까진 할 수 있어도, 구하는 방법은 아직 없다는 거네."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_013","speaker":"벤티","text":"응. 그 둘이 같은 일인 것처럼 말하고 싶지는 않아. 멀리 떨어져 있어 줘. 드발린이 나를 알아보지 못할 수도 있어."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_014","speaker":"다이루크","text":"하프에 이상이 생기면 거기서 중지해. 드발린을 불러 놓고 소리가 끊기는 상황도 감당해야 한다."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_015","speaker":"벤티","text":"알아. 너희는 안쪽에 있어 줘. 그 애가 화를 낸다면 먼저 나한테 할 말이 있을 거야."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_016","speaker":"나","text":"그렇다고 혼자 다 맞겠다는 말처럼 들리게 하지는 마. 들을 수 있는 데 있을게. 네가 멈추면 나도 물러날 거고."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_017","speaker":"","text":"벤티는 대답하려다 하프 쪽으로 눈을 내렸다. 지킬 수 있을지 모르는 약속을 해 버렸다. 그사이 바람이 달라졌다. 절벽 아래에서 올라오던 바람이 멀리 바다 쪽으로 길게 빠져나갔다."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_018","speaker":"","text":"벤티는 눈물에 남은 힘을 하프에 이어 보려 했다. 흐릿한 빛이 줄을 따라 번지다가 곧 붉은 기운이 섞여 흔들렸다. 그는 손을 멈췄다가 자기 바람을 더해 첫 음을 냈다. 맑게 뻗어야 할 소리에 낮은 떨림이 남았다."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_019","speaker":"벤티","text":"드발린, 나야. 네 말을 들으러 왔어. 잠깐만 여기 있어 줘."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_020","speaker":"","text":"바다 위의 구름이 갈라지고 커다란 날개가 절벽을 스쳤다. 드발린이 고개를 낮추자 바람이 풀을 뿌리째 눕혔다. 벤티는 물러서지 않고 다시 줄을 튕겼다. 눈물 안의 붉은 빛이 따라 떨릴 뿐, 용의 몸에 남은 오염은 달라지지 않았다."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_021","speaker":"","text":"드발린의 눈이 하프를 향했다. 아주 잠깐, 알아본 거라고 생각했다. 벤티도 같은 생각을 했는지 다음 음을 천천히 이었다. 그러나 붉은 결정이 떨릴 때마다 소리가 거칠게 갈라졌다. 드발린의 목이 팽팽해지고 발톱이 절벽을 긁었다."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_022","speaker":"벤티","text":"기억나? 이렇게 바람이 많은 날이면 네가 멀리 날아갔다 돌아오곤 했지. 지금 당장 가까이 오지 않아도 돼. 여기서 들을 수 있으면…."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_023","speaker":"","text":"다음 날갯짓에 말이 끊겼다. 바닥에 짚은 손을 밀려오는 자갈에서 빼내며 하프를 봤다. 사당에서 싸 온 천들이 옆으로 날렸다. 눈물의 붉은색은 처음 발견했을 때와 같았다."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_024","speaker":"다이루크","text":"벤티, 손을 멈춰. 더 힘을 보태도 같은 소리다."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_025","speaker":"","text":"벤티는 마지막 줄을 누른 채 놓지 못했다. 드발린이 고개를 낮추자 손끝의 빛이 크게 흔들렸다. 뭐라도 말해야 할 것 같았다. 그 거대한 얼굴 앞에서 목이 말라붙었다."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_026","speaker":"벤티","text":"안 돼…. 이 소리로는 닿지 않아."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_027","speaker":"","text":"드발린이 몸을 비틀었다. 하프의 떨림은 노래가 되지 못하고 끊겼다. 용이 고통스럽게 날개를 내리치는 순간 다이루크가 벤티를 절벽 안쪽으로 끌어당겼다."},{"k":"line","id":"PRO_M03A_별을_따는_절벽_028","speaker":"다이루크","text":"물러서! 여기선 더 못 버틴다!"},{"k":"keep","id":"ISK_M03_A_144","text":"내가 서 있던 바위 아래로 거대한 등이 지나갔다. 뻗은 등줄기를 붙잡을 수 있는 거리는 지금뿐이었다. 뒤에서 다이루크가 돌아오라고 불렀다. 드발린은 이미 절벽을 떠나려 하고 있었다."},{"k":"choice","group":"G_PRO_M03A_별을_따는_절벽_029","options":[{"label":"드발린! 기다려!","keep":"ISK_M03_A_145","items":[{"k":"line","id":"PRO_M03A_드발린의_등_AA__001","speaker":"","text":"뒤에서 뻗어 오는 손 대신 눈앞을 지나가는 등을 향해 몸을 던졌다. 거친 비늘이 팔꿈치를 긁고 지나갔다. 두 손이 돌출된 등줄기를 붙잡았다. 몸이 바깥으로 쏠리는 순간 아래에서 바람이 한 번 받쳐 올렸다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__002","speaker":"벤티","text":"몸을 낮춰! 손 놓지 마!"},{"k":"line","id":"PRO_M03A_드발린의_등_AA__003","speaker":"","text":"벤티의 목소리가 순식간에 멀어졌다. 드발린이 날개를 펴자 절벽과 사람들이 발아래로 밀려났다. 비늘 사이에 무릎을 붙이고 엎드렸다. 내려 달라고 말할 자세도, 그렇게 해 줄 거라는 믿음도 없었다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__004","speaker":"나","text":"으아아아아악! 잠깐, 잠깐만! 이렇게 빨리 갈 줄은 몰랐어!"},{"k":"line","id":"PRO_M03A_드발린의_등_AA__005","speaker":"","text":"비명은 입을 떠나자마자 뒤로 찢겨 나갔다. 드발린의 등은 평평한 바닥이 아니었다. 날갯짓마다 비늘의 각도가 바뀌고, 발을 놓을 틈이라고 생각한 곳이 허공을 향했다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__006","speaker":"","text":"눈을 감았다가 더 무서워져 다시 떴다. 절벽에서 몸을 던진 그 짧은 순간에는 따라가야 한다는 생각밖에 없었다. 따라간 다음에 어떻게 할지는 그때도 없었고, 지금도 없다. 왜 뛰었는지도 모르겠다. 팔을 당겨 몸을 더 붙이는 데 남은 생각을 전부 썼다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__007","speaker":"","text":"아래를 보지 않으려 해도 지면이 시야를 가로질렀다. 나무가 점으로 작아지고, 조금 전까지 걸었던 길이 선처럼 누웠다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__008","speaker":"","text":"거대한 등이 천천히 오르내렸다. 바람이 잦아드는 아주 짧은 틈에 그 움직임이 날갯짓과 다른 박자라는 걸 알았다. 드발린이 숨을 쉬고 있었다. 몸속 깊은 곳에서 울리는 거친 진동이 비늘을 타고 손바닥까지 왔다. 아픈 사람의 숨소리였다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__009","speaker":"나","text":"나도 지금 엄청 무섭거든. 널 어떻게 해 보려고 올라온 건 아니야. 그러니까… 흔들어서 떼어 내지는 말아 줘."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__010","speaker":"","text":"대답은 없었다. 알아들었는지도 알 수 없었다. 비늘을 어루만지려다 잡은 힘만 약해져 급하게 다시 움켜쥐었다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__011","speaker":"","text":"멀리 무너진 탑이 보였다. 드발린은 그쪽으로 방향을 틀었다. 토벌대가 향한다던 폐허. 바로 그곳이었다."},{"k":"keep","id":"ISK_M03_AA_152","text":"폐허 입구에 깃발이 보였다. 드발린이 낮게 선회하자 기사들이 흩어져 엄폐하고 활이 하늘을 향했다. 한 팔을 들려다 몸이 미끄러져 다시 붙잡았다. 엠버를 부르는 소리는 날갯짓에 묻혔다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__012","speaker":"나","text":"쏘지 마! 등에 사람 있어! 나 여기 있어!"},{"k":"line","id":"PRO_M03A_드발린의_등_AA__013","speaker":"","text":"아래에서는 드발린의 포효와 돌 무너지는 소리만 들렸다. 고개를 들 때마다 등이 솟아올라 몸을 다시 짓눌렀다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__014","speaker":"나","text":"엠버! 나야, {PLAYER_NAME}! 여기 있다고! 아니, 활은 이쪽으로 돌리지 말고!"},{"k":"line","id":"PRO_M03A_드발린의_등_AA__015","speaker":"","text":"너무 멀어서 붉은 옷이 엠버인지도 확신할 수 없었다. 아래쪽 사람이 팔을 들자 나도 손을 들려 했다. 그 순간 등이 기울어 얼굴이 비늘에 눌렸다. 사람이라는 사실 하나만 전하면 될 것 같았다. 그 쉬운 말이 닿지 않았다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__016","speaker":"엠버","text":"잠깐, 등에 뭔가 있어요! 사격 각도 바꾸지 말아요. 먼저 확인해요!"},{"k":"line","id":"PRO_M03A_드발린의_등_AA__017","speaker":"진","text":"전원 엄폐 유지! 신호 전까지 발사하지 마!"},{"k":"line","id":"PRO_M03A_드발린의_등_AA__018","speaker":"","text":"사격은 멈췄지만 드발린이 탑 위로 물러나자 나도 시야에서 사라졌다. 드발린은 높은 잔해에 앞발을 걸고 거칠게 숨을 쉬었다. 등줄기 뒤에 엎드려 버텼다. 그사이 토벌대는 무너진 회랑 뒤로 자리를 옮겨 그를 포위했다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__019","speaker":"","text":"시간이 지나면서 바람보다 손가락이 더 무서워졌다. 한쪽을 풀면 다른 쪽이 몸무게를 전부 받아야 했다. 손가락 두 개를 폈다가 다시 잡았다. 아래에서 들리던 말은 어느새 소리의 높낮이만 남았다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__020","speaker":"엠버","text":"진 단장, 사람인 건 맞는 것 같아요. 등이 움직일 때마다 따로 붙잡고 있어요. 저대로 두면 떨어질지도 몰라요."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__021","speaker":"진","text":"확인했어. 하지만 지금 접근하면 드발린이 어떻게 반응할지 몰라. 엠버, 시야에서 놓치면 바로 말해 줘."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__022","speaker":"엠버","text":"…네. 계속 볼게요. 이번에는 어느 쪽에 있는지 놓치지 않을게요."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__023","speaker":"","text":"그 대화는 나에게 들리지 않았다. 시야 아래에 나타났다 사라지는 붉은 색만 보였다. 그 색이 멈춰 있는 동안은 적어도 누군가 위를 보고 있다는 생각으로 버텼다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__024","speaker":"","text":"해가 기울 무렵 폐허 바깥 길에서 두 사람이 경계선으로 들어왔다. 다이루크와 벤티. 땅으로 쫓아온 탓에 늦었다. 다이루크가 앞을 막은 기사에게 이름을 밝히고 진을 찾았다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__025","speaker":"다이루크","text":"등 위에 탄 사람은 우리와 함께 있던 모험가다. 용을 부리는 게 아니야. 내려오지 못하고 있어. 공격을 멈춰."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__026","speaker":"진","text":"다이루크 선배? 함께 계셨던 겁니까? 엠버가 사람을 본 것 같다고 했습니다. 무슨 일이 있었는지 말씀해 주세요."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__027","speaker":"벤티","text":"내가 드발린을 불렀어. 그 애를 구하려고 했지만 실패했어. 저 사람은 떠나는 드발린의 등에 뛰어들었고…. 지금은 먼저 내려오게 해야 해."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__028","speaker":"다이루크","text":"우리가 시도한 건 토벌이 아니라 정화다. 그 설명이 사격 명령보다 먼저 도착했어야 했는데, 늦었군."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__029","speaker":"진","text":"정화가 목적이었다는 건 들었습니다. 하지만 선배, 이미 실패한 시도를 이유로 토벌대를 물릴 수는 없습니다. 위에 있는 분을 구한 뒤 드발린이 다시 공격하면 어떻게 하실 겁니까?"},{"k":"line","id":"PRO_M03A_드발린의_등_AA__030","speaker":"다이루크","text":"전체를 물리라는 말이 아니다. 지금 저 등을 향해 공격하면 우리 쪽 사람부터 죽는다. 탈출할 틈을 만들 동안 사격을 멈추고 거리를 벌려."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__031","speaker":"벤티","text":"내가 앞에 있을게. 다시 하프를 연주하지는 않을 거야. 그 애가 사람들 쪽으로 몸을 돌리면 먼저 나를 보게 하겠어."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__032","speaker":"진","text":"벤티 씨 혼자 감당하시겠다는 말만으로 명령할 수는 없습니다. 저 위에서 내려올 길을 실제로 만들어 주세요. 엠버, 오른쪽 잔해를 거쳐 내려올 수 있겠어?"},{"k":"line","id":"PRO_M03A_드발린의_등_AA__033","speaker":"엠버","text":"아래쪽 두 군데는 제가 갈 수 있어요. 높은 틈만 건너오면 돼요. 바람이 조금만 잠잠해지면요."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__034","speaker":"다이루크","text":"그 틈 아래는 내가 받겠다. 발 디딜 돌이 무너지지 않게 먼저 치우지."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__035","speaker":"","text":"진은 드발린의 앞발과 엠버가 가리킨 길을 번갈아 봤다. 그녀가 한 걸음 앞으로 나서자 흔들리던 시선들이 모였다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__036","speaker":"진","text":"전원, 구조가 끝날 때까지 공격 중지. 드발린을 자극하지 않도록 간격을 넓혀. 후방은 퇴로를 유지한다. 벤티 씨, 준비가 되면 신호해 주세요."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__037","speaker":"","text":"벤티가 위로 올라가며 드발린의 이름을 불렀다. 처음으로, 바람 사이에서 알아들을 수 있는 사람의 목소리가 닿았다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__038","speaker":"","text":"진이 검을 낮추고 엠버에게 신호했다. 엠버는 활을 내린 채 높은 돌 위로 올라가 나를 향해 양팔을 크게 벌렸다. 이번에는 나도 그녀를 볼 수 있었다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__039","speaker":"엠버","text":"지금은 안 쏴! 들리면 움직이지 말고 있어! 내려올 길부터 만들게!"},{"k":"line","id":"PRO_M03A_드발린의_등_AA__040","speaker":"","text":"벤티가 탑을 타고 오르는 바람을 골랐다. 다이루크는 아래에서 무너질 돌을 치우고, 엠버가 건너올 자리를 가리켰다. 드발린이 몸을 크게 들썩이지 않는 틈을 기다려 손을 옮겼다. 마지막 몇 걸음은 걷는 것보다 바위에 매달리는 쪽에 가까웠다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__041","speaker":"","text":"마지막 높이를 내려설 때 땅이 올라오는 것처럼 느꼈다. 발을 댔는데도 무게를 싣지 못하고 돌 모서리를 붙잡았다. 엠버가 무릎을 굽혀 같은 높이에서 얼굴을 봤다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__042","speaker":"엠버","text":"내가 보이지? 여기는 움직이지 않아. 발밑에 돌이 있어. 한 발씩 내려놔. 서두르지 말고, 응."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__043","speaker":"","text":"발바닥 전체가 땅에 닿고 나서도 손은 펴지지 않았다. 손가락이 잡고 있던 모양을 멍하니 봤다. 엠버는 그 손을 억지로 떼어 내지 않고 곁에 서 있었다."},{"k":"choice","group":"G_PRO_M03A_드발린의_등_AA__044","options":[{"label":"나, 이제 땅에 서 있는 거 맞지?","id":"PRO_M03A_드발린의_등_AA__045","items":[{"k":"line","id":"PRO_M03A_드발린의_등_AA__046","speaker":"엠버","text":"맞아. 내려왔어. 손은 아직 그 모양인데, 잡고 있던 건 놓아도 돼. 천천히 펴 봐. 내가 여기 있을게."}]},{"label":"내 말이 하나도 안 들렸어? 그렇게 소리쳤는데.","id":"PRO_M03A_드발린의_등_AA__047","items":[{"k":"line","id":"PRO_M03A_드발린의_등_AA__048","speaker":"엠버","text":"바람 때문에 거의 안 들렸어. 네가 맞는지도 제대로 못 봤고. 정말 놀랐잖아. 지금은 여기서 말해. 이제 들리니까."}]}]},{"k":"line","id":"PRO_M03A_드발린의_등_AA__049","speaker":"엠버","text":"내가 무슨 말을 했었는지 기억해? 토벌대에 오면 경계하는 사람한테 네 이름부터 말하라고 했잖아. 네가 하늘에서 용이랑 같이 올 거라고는 생각 못 했어."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__050","speaker":"나","text":"나도 이런 뜻으로 합류하려던 건 아니었어. 눈앞을 지나가는데, 지금 놓치면 다시 못 만날 것 같아서… 뛰고 나서야 잘못됐다는 생각이 들었어."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__051","speaker":"엠버","text":"그때 했어야지. 뛰기 전에! 네가 맞는 것 같아서 활을 못 들겠는데, 아니라면 다른 사람들이 위험할 수도 있고…. 나 정말 모르겠더라."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__052","speaker":"","text":"엠버는 나에게서 시선을 돌려 드발린을 봤다. 말을 크게 하는 것보다 숨을 고르는 데 더 애를 쓰는 것 같았다. 사과를 급하게 끝내지 않고 그녀가 다시 돌아볼 때까지 기다렸다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__053","speaker":"나","text":"미안해. 변명은 안 할게. 손이 아직 안 펴져."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__054","speaker":"엠버","text":"알았어. 그런데 지금 바로 괜찮다고는 못 하겠어. 조금만 숨 돌리자. 손 그 모양으로 물통은 열겠어? 내가 열어 줄게. 나도 목이 다 말랐어."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__055","speaker":"벤티","text":"엠버, 나도 미안해. 같이 돌아오겠다고 네게 말했는데, 이 사람을 먼저 보내 버렸어."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__056","speaker":"엠버","text":"약속이 그렇게 된 건 둘이 따로 얘기해. 지금은… 둘 다 내 앞에 있어서 다행이야. 그다음 얘기는 조금 있다가 할래."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__057","speaker":"","text":"엠버가 내민 물통을 두 손으로 받았다. 그녀는 평소처럼 놀리지 않았다. 멀리서 용이 몸을 옮기는 소리가 나자 셋은 동시에 그쪽을 돌아봤다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__058","speaker":"","text":"낮은 돌에 앉자 무릎이 한꺼번에 떨렸다. 용은 높은 잔해에 남아 있었다. 거리를 둔 채 무기를 내렸다고 해서 고통까지 멎은 건 아니었다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__059","speaker":"진","text":"당장의 공격은 중지했습니다. 하지만 계속 이 상태로 둘 수는 없습니다. 정화가 목적이었다면, 시도한 방법과 실패한 이유부터 알아야 합니다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__060","speaker":"벤티","text":"눈물에 남은 힘으로 하프를 회복시키려 했어. 하지만 오염은 지우지 못했지. 노래를 들려줄 수는 있어도, 그 애를 아프게 하는 것까지 없애지는 못했어."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__061","speaker":"나","text":"셋 다 같은 색이었어요. 다른 사당에서 찾으면 다를까 싶어서 끝까지 갔는데, 절벽에서도 안 바뀌었어요. 하프 소리는 났는데… 그걸 듣는 드발린은 계속 아파 보였고요."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__062","speaker":"진","text":"직접 보신 내용을 말씀해 주셔서 감사합니다. 그럼 눈물의 수가 부족해서 실패했다고 단정할 수는 없겠군요."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__063","speaker":"벤티","text":"응. 오염을 해결하지 못한 채 같은 노래를 더 크게 들려줘도 그 애가 편해지지는 않아."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__064","speaker":"엠버","text":"부르는 건 됐는데, 도와주지는 못한 거구나. 그럼 저 위에서 아파하고 있는 동안 우리가 할 수 있는 건…."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__065","speaker":"","text":"엠버가 말을 끝내지 못했다. 진의 명령을 듣고 낮아진 무기들이 눈에 들어왔다. 죽이지 말자는 말 뒤에 놓일 답을 찾지 못한 사람은 나만이 아니었다."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__066","speaker":"다이루크","text":"같은 일을 반복할 이유는 없다. 시간을 벌었으면 다음에는 다른 답이 있어야 해."},{"k":"line","id":"PRO_M03A_드발린의_등_AA__067","speaker":"나","text":"정화하자는 데까지는 나도 동의해. 그런데… 그걸 어떻게 해야 하지?"},{"k":"line","id":"PRO_M03A_드발린의_등_AA__068","speaker":"","text":"아무도 곧바로 대답하지 않았다. 벤티가 감싼 천 사이로 붉은 눈물이 보였다. 그 빛을 보다가 높은 잔해 위의 드발린을 올려다봤다. 토벌을 멈추게 하는 데에는 성공했다. 이제 그 결정을 지킬 방법이 필요했다."},{"k":"keep","id":"ISK_M03_AA_178","text":"정화 방법을 찾아야 한다."}]},{"label":"……다이루크, 지금 그쪽으로 갈게!","keep":"ISK_M03_A_146","items":[{"k":"line","id":"PRO_M03A_절벽에_남아_AB__001","speaker":"","text":"절벽 끝에서 발을 거두고 다이루크 쪽으로 돌아섰다. 바로 뒤에서 드발린의 날개가 바람을 밀어 올렸다. 몸이 흔들렸지만 이번에는 디딜 땅이 남아 있었다. 다이루크가 팔을 붙잡아 안쪽으로 당겼다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__002","speaker":"다이루크","text":"잘 버텼어. 고개 숙여. 돌이 아직 날아온다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__003","speaker":"","text":"날개 소리가 멀어진 뒤 벤티가 몸을 일으켰다. 하프도 눈물도 곁에 남아 있었다. 그는 흩어진 천을 주워 결정을 감쌌다. 드발린이 사라진 방향을 보고도 더 따라가지 않았다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__004","speaker":"벤티","text":"떠났네. 내 노래를 듣게 하는 것만으로는 부족했어."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__005","speaker":"","text":"절벽 끝의 자리를 돌아봤다. 발이 미끄러진 자국이 남아 있었다. 다이루크가 놓아준 팔목은 아직 잡혀 있는 것처럼 묵직했다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__006","speaker":"나","text":"나 순간적으로 올라탈 생각을 했어. 지나가는 등이 닿을 것 같아서. 근데 발이 안 떨어졌어."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__007","speaker":"다이루크","text":"떨어졌다면 지금 여기 없었겠지. 등에 붙는 데 성공했더라도 내려오는 건 다른 문제고."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__008","speaker":"벤티","text":"네가 거기서 멈춰서 다행이야. 내가 부른 용 때문에 너까지 저 하늘에 매달릴 뻔했네."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__009","speaker":"나","text":"멈춘 건 내가 고른 거야. 올라탈 자신도 없었고, 올라가서 뭘 할지도 몰랐어. 그래도 보내고 나니까 속이 시원하지는 않네. 아직 저쪽을 보고 있는 너도 그렇고."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__010","speaker":"벤티","text":"나도 그래. 떠나면 붙잡고 싶은데, 다시 다가오면 너희부터 밀어내게 되네. 하프는 여기 있는데 말이야."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__011","speaker":"","text":"용이 떠난 자리는 생각보다 빨리 평범한 하늘이 됐다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__012","speaker":"나","text":"토벌대로 돌아가야 하지 않을까? 지금 본 건 알려야 해. 엠버도 그쪽에 있고."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__013","speaker":"다이루크","text":"여기서 따라잡기엔 거리가 멀어. 어두워진 뒤 폐허로 들어가면 알릴 사람보다 경계하는 무기를 먼저 만나겠지."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__014","speaker":"나","text":"그래도 뛰면 조금은 가까워지잖아. 성으로 돌아가면 반대 방향이고. 엠버가 저쪽에 있다는 걸 아니까 가만히 있기가 싫어."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__015","speaker":"다이루크","text":"자네가 닿았을 때 전할 말은 있겠지. 거기까지 어떻게 가서, 누구에게 처음 보일 건지는 정했나? 피곤한 몸으로 길을 헤매면 그 말도 전달하지 못해."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__016","speaker":"나","text":"그걸 다 정하고 움직일 상황이냐고 말하고 싶은데, 길을 모르는 건 맞네. 그럼 성에서 연락하는 쪽이 정말 더 빨라?"},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__017","speaker":"다이루크","text":"성에는 연락을 맡은 사람이 남아 있어. 도착하면 본부부터 간다. 그건 미루지 않겠어."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__018","speaker":"벤티","text":"난 드발린이 간 방향을 조금 더 살펴볼게. 너희를 데리고 쫓아가지는 않을 거야. 알아낸 게 있으면 성으로 소식을 보낼게."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__019","speaker":"다이루크","text":"우리는 몬드로 간다. 본부에 보고를 남기고 토벌대와 연락할 방법을 찾겠어. 기다린다는 건 아무것도 하지 않는다는 뜻이 아니야."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__020","speaker":"나","text":"벤티, 네 쪽에서 알게 되는 게 있으면 좋은 소식 아니어도 보내 줘. 아무 말 없으면 우리 마음대로 생각하게 될 것 같아."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__021","speaker":"벤티","text":"응. 네가 먼저 성에 도착하면 내가 아직 포기한 건 아니라고 전해 줘. 그렇다고 잘되고 있다고 대신 말하지는 말고."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__022","speaker":"다이루크","text":"하프와 눈물은 네가 가지고 있어. 내게 필요한 건 네가 어디 있는지 알 수 있는 연락이다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__023","speaker":"벤티","text":"알았어, 다이루크 어르신. 오늘은 노래에 숨겨 보내지 않을게. 너희도 성에 닿으면 쉬어. 특히 이 사람, 아까부터 한쪽 무릎에만 힘을 주고 있어."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__024","speaker":"","text":"나도 모르게 반대쪽 발로 무게를 옮겼다. 벤티가 작게 웃었다. 갈림길에서 초록 망토가 다른 쪽으로 멀어지자, 길 위에는 다이루크와 내 발소리만 남았다."},{"k":"choice","group":"G_PRO_M03A_절벽에_남아_AB__025","options":[{"label":"돌아가자. 나 혼자 뛰어가 봐야 길부터 잃겠네.","id":"PRO_M03A_절벽에_남아_AB__026","items":[{"k":"line","id":"PRO_M03A_절벽에_남아_AB__027","speaker":"다이루크","text":"자네 상태부터 아는 편이 낫지. 보고할 내용은 걸으면서 정리해. 본 것과 벤티에게 들은 것은 구분하고."}]},{"label":"엠버한테 소식이 닿았는지는 꼭 확인하고 싶어.","id":"PRO_M03A_절벽에_남아_AB__028","items":[{"k":"line","id":"PRO_M03A_절벽에_남아_AB__029","speaker":"다이루크","text":"전달했다고 확인되지 않은 일을 전달됐다고 하지는 않겠다. 본부의 연락망부터 확인하지."}]}]},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__030","speaker":"","text":"내려오는 길은 올라갈 때보다 길었다. 다이루크는 말없이 걷다가 가끔 속도를 늦췄다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__031","speaker":"다이루크","text":"묻고 싶은 게 있으면 물어. 자꾸 걸음을 멈추면 내 쪽에서 길을 잘못 들었나 확인하게 된다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__032","speaker":"나","text":"조금만 천천히 가 줘. 네 보폭 따라잡느라 질문할 숨이 없었어. 저기서 잠깐 쉬었다 가자."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__033","speaker":"다이루크","text":"그러지. 저 돌까지 가서 쉬자. 보폭을 줄였는데도 자네한테는 빠른 모양이군."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__034","speaker":"","text":"돌 위에 앉기도 전에 다이루크가 손을 들었다. 길 아래 덤불에서 횃불이 흔들렸다. 가면들이었다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__035","speaker":"다이루크","text":"쉬는 건 조금 뒤로 미루지. 뒤에 있어."},{"k":"combat","id":"PRO_M03A_절벽에_남아_AB__036","group":"EG_MOND_HILI_PATROL","text":"어두워진 길목에서 츄츄족이 횃불을 들고 올라온다. 다이루크가 앞을 맡는다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__037","speaker":"","text":"횃불이 전부 꺼지자 다이루크가 검을 거뒀다. 숨 한 번 흐트러지지 않았다. 나는 돌 위에 앉았다. 앉자마자 못 일어날 것 같았다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__038","speaker":"나","text":"처음에 와이너리에서 물었잖아. 왜 벤티를 따라왔냐고. 나중에 다른 방법이 있었다는 걸 알게 되는 게 싫다고 했는데, 지금도 다른 방법은 못 찾았네."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__039","speaker":"다이루크","text":"그래서 그 선택을 없었던 일로 하고 싶나?"},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__040","speaker":"나","text":"아니. 사당에서 본 것도 있고, 벤티가 왜 그렇게 말했는지도 조금 알겠어. 근데 그게 용을 살리는 데 도움이 됐냐고 물으면 대답을 못 하겠어서."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__041","speaker":"다이루크","text":"지금 대답할 수 없는 걸 여기서 끝까지 결정하려고 하지 마. 돌아가서 할 일은 남았다. 오늘 본 것을 기억하는 사람도 필요하고."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__042","speaker":"","text":"다이루크는 다시 걷기 전에 내가 일어나는 걸 기다렸다. 「도움이 됐다」고 쉽게 말해 주지는 않았다. 대신 다음 갈림길에서도 같은 쪽으로 걸었다. 그 사실에 기대어 발을 옮겼다."},{"k":"keep","id":"ISK_M03_AB_192","text":"성문으로 돌아왔을 때 경비병은 두 사람의 얼굴보다 먼지 묻은 짐을 먼저 살폈다. 다이루크가 이름과 용건을 밝히자 본부로 가는 길이 열렸다. 문 안으로 들어온 뒤에야 어깨를 내렸다. 익숙해진 거리가 아직 그대로 있었다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__043","speaker":"","text":"본부에서 하프를 회수한 장소와 사당의 사망자들, 별을 따는 절벽에서 실패한 시도를 차례로 전했다. 담당 기사는 토벌대에 전달할 보고를 받았다고 답했다. 현지에서 읽었다는 회신까지 온 것은 아니었다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__044","speaker":"","text":"보고를 받아 적던 기사가 사당 위치를 한 번 더 물었다. 지도를 돌려 놓고 길을 짚었다. 이번에는 어디로 들어가 어느 문으로 나왔는지 끝까지 설명할 수 있었다. 하루 만에 는 게 그거였다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__045","speaker":"나","text":"본부에 내 이름 남기겠다고 했거든. 엠버한테. 여기 써 두면 돌아왔을 때 볼 수 있겠지?"},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__046","speaker":"다이루크","text":"그 약속은 지킬 수 있겠군. 지금 머무를 곳도 함께 적어. 이름만 보고 성 전체를 뒤지게 할 필요는 없으니까."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__047","speaker":"","text":"종이를 당겨 이름을 적었다. 도중에 손이 멈추자 다이루크가 자기 연락처를 옆에 더했다. 기사는 두 이름을 확인한 뒤 보고서 맨 위에 올려놓았다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__048","speaker":"나","text":"이름 쓴 것뿐인데 조금 낫네. 방금까지는 돌아왔다는 말을 아무한테도 못 한 것 같았어."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__049","speaker":"다이루크","text":"이제 남겼어. 보고도 남겼고. 회신을 기다린다. 그사이 내가 확인하는 일에 동행해도 좋다. 오늘처럼 자네가 직접 본 것을 말해 주면 돼."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__050","speaker":"나","text":"그건 조사에 목격자가 옆에 있으면 편하다는 뜻이야, 아니면 앞으로도 같이 움직여 보자는 뜻이야? 혼자 크게 받아들이는 건 싫어서."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__051","speaker":"다이루크","text":"앞으로도 협력할 수 있다는 뜻이다. 오늘 자네가 모르는 걸 숨기지 않은 점은 도움이 됐어. 급할 때 계속 그렇게 할 수 있는지는 더 봐야겠지만."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__052","speaker":"나","text":"하루 같이 다녔다고 평가가 끝난 건 아니지? 나도 무슨 일인지 듣고 고를 거야. 아까처럼 설명 없이 지도부터 펴 놓으면 또 돌려 볼 수밖에 없어."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__053","speaker":"다이루크","text":"지도는 자네 쪽에서도 보이게 놓지. 다만 같은 대답을 두 번 듣고 싶어서 묻는 거라면, 두 번째는 그리 길게 설명하지 않겠다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__054","speaker":"","text":"다이루크는 말하며 손에 든 지도의 방향을 한 번 바꿨다. 그걸 보고서야 웃었다. 와이너리에서는 내 쪽으로 당기기도 눈치 보이던 종이가, 이제 두 사람 사이에서 반쯤 기울어 있었다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__055","speaker":"나","text":"함께 움직여도 된다는 거지? 이번엔 갑자기 용이 날아오르는 일은 없었으면 좋겠는데."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__056","speaker":"다이루크","text":"약속할 수 없는 건 약속하지 않겠어. 다만 위험한 곳으로 갈 때 이유도 설명하지 않고 데려가진 않는다. 자네도 무리라면 말해."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__057","speaker":"","text":"계단을 내려가던 다이루크가 멈춰 서서 나를 돌아봤다. 멀리 성문이 보였고, 토벌대를 맞으러 뛰어가는 사람은 아직 없었다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__058","speaker":"다이루크","text":"오늘처럼 함께 움직일 생각이라면 내게 직접 말해. 의뢰 하나를 끝냈다고 모든 일을 함께해야 하는 건 아니야."},{"k":"choice","group":"G_PRO_M03A_절벽에_남아_AB__059","options":[{"label":"그럼 같이 가자. 내가 아는 건 빠뜨리지 않고 말할게. 아는 게 적어서 금방 끝나겠지만.","id":"PRO_M03A_절벽에_남아_AB__060","items":[{"k":"line","id":"PRO_M03A_절벽에_남아_AB__061","speaker":"다이루크","text":"좋아. 먼저 쉬면서 정리해. 급하다고 기억까지 서두를 필요는 없어."}]},{"label":"잘 부탁할게. 지도는 네가 챙겨. 난 등불이랑 짐부터 다시 볼게. 다음엔 어디로 가는지 알고 따라가고 싶으니까, 출발 전에 불러 주고.","id":"PRO_M03A_절벽에_남아_AB__062","items":[{"k":"line","id":"PRO_M03A_절벽에_남아_AB__063","speaker":"다이루크","text":"알겠다. 출발 전에 알리지. 자네 짐도 잠깐 두고 쉬어. 오늘 본 걸 다시 이야기할 때까지 계속 들고 있을 필요는 없어."}]}]},{"k":"keep","id":"ISK_M03_AB_202"},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__064","speaker":"","text":"성벽 위에서 교대 종이 울렸다. 계단 끝에는 아직 문을 연 가게가 보였다. 토벌대가 돌아올 길 쪽을 한 번 더 봤다. 드발린의 행방도, 엠버의 소식도 아직 오지 않았다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__065","speaker":"다이루크","text":"연락이 오면 알려 주겠다. 그전까지는 몬드에 머무르지. 내가 따로 살펴보던 운송 기록도 있어. 원한다면 그 일부터 함께 확인해도 돼."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__066","speaker":"나","text":"운송 기록 보는 일도 용이랑 관련된 거야? 지금은 종이만 보면 전부 같은 일로 이어질 것 같아서."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__067","speaker":"다이루크","text":"별개로 확인하던 일이다. 내 장부에 설명되지 않는 부분이 있어서 직접 살펴보려는 거지. 준비되면 찾아와."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__068","speaker":"나","text":"장부라면 내 전문이야. 다만 오늘 당장은 못 해. 앉으면 생각보다 오래 못 일어날 것 같아."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__069","speaker":"다이루크","text":"그럼 오늘은 앉아 있어. 연락 올 곳을 남겼으니 계속 성문 앞에 서 있을 필요는 없다."},{"k":"line","id":"PRO_M03A_절벽에_남아_AB__070","speaker":"","text":"길 건너 가게에서 누가 의자를 끌어냈다. 평범한 소리가 너무 또렷했다. 오늘 해결하지 못한 일은 그대로 남아 있었다. 대신 다음에 문을 두드릴 곳과 함께 움직일 사람이 하나 늘었다."},{"k":"keep","id":"ISK_M03_AB_206","text":"몬드에서 토벌대의 소식을 기다린다. 그동안 다이루크를 찾아가 볼 수도 있다."}]}]}],"edits":[],"pre":""},{"id":"ISK_M03_B","entry":"ISK_M03_B_207","items":[{"k":"keep","id":"ISK_M03_B_207","text":"엠버가 출정한 뒤 게시판 앞에 서는 일은 조금 달라졌다. 모르는 지명이 나오면 옆을 보면 됐는데, 이제 옆에는 아무도 없다. 익숙한 운반 의뢰 사이에 작은 봉투 하나를 붙인 종이가 있었다. 목적지는 드래곤 스파인. 물건을 보내는 것보다 가는 길에 본 것을 빠짐없이 적어 달라는 조건이 더 길었다."},{"k":"line","id":"PRO_M03B_게시판_001","speaker":"","text":"지명을 읽다가 또 옆을 봤다. 빈자리를 확인하고서야 접수처로 갔다. 캐서린은 종이보다 내가 방금 본 빈자리를 먼저 봤다."},{"k":"line","id":"PRO_M03B_게시판_002","speaker":"캐서린","text":"설산 쪽 의뢰를 보고 있었구나. 평소보다 오래 읽길래 다른 조건을 찾는 줄 알았어."},{"k":"line","id":"PRO_M03B_게시판_003","speaker":"나","text":"이 지명이 어디냐고 물어보려고 옆을 봤어. 엠버 없다는 걸 매번 새로 기억하네. 물어보는 게 습관이 됐나 봐."},{"k":"line","id":"PRO_M03B_게시판_004","speaker":"캐서린","text":"길 안내는 나한테 물어도 돼. 누구한테 물을지 고민하는 시간만큼 마감이 빨라지진 않으니까 천천히 읽어."},{"k":"line","id":"PRO_M03B_게시판_005","speaker":"나","text":"그럼 이 조건부터. 이상한 게 안 보이면 빈칸으로 내도 된다면서, 빈칸도 꼭 작성하라고 적혀 있어. 뭘 적으라는 거야?"},{"k":"line","id":"PRO_M03B_게시판_006","speaker":"캐서린","text":"아무것도 못 봤다고 적으면 돼. 관찰했는데 못 본 건지, 관찰을 안 한 건지 알 수 있게. 의뢰인이 그 구분을 부탁했어."},{"k":"line","id":"PRO_M03B_게시판_007","speaker":"나","text":"아, 빈칸인 이유를 적는 칸이구나. 갑자기 낯이 익네. 전에 다니던 데서 매주 쓰던 거야. 「특이사항 없음, 사유: 특이한 일이 없었음.」"},{"k":"line","id":"PRO_M03B_게시판_008","speaker":"캐서린","text":"그 양식이면 바로 쓸 수 있겠네. 별과 심연을 향해! 설산 연구 거점에 밀봉한 기록과 관측 도구를 전달하는 일이야. 가는 길에 이상한 빛이나 소리를 보면 장소와 시각도 기억해 달래."},{"k":"choice","group":"G_PRO_M03B_게시판_009","options":[{"label":"짐 배달인데 관찰 일지도 쓰라는 거네. 내가 알아볼 수 있는 건 맞아?","id":"PRO_M03B_게시판_010","items":[{"k":"line","id":"PRO_M03B_게시판_011","speaker":"캐서린","text":"해석할 필요는 없어. 못 봤으면 못 봤다고 전하면 돼. 추측으로 빈칸을 채우지 않는 게 조건이야."},{"k":"line","id":"PRO_M03B_게시판_012","speaker":"나","text":"그건 자신 있어. 추측으로 빈칸 채우다가 혼난 적이 많거든."}]},{"label":"이상한 걸 보라고 적혀 있으면 괜히 뭐 하나 찾아야 할 것 같잖아. 바람 소리도 그냥 바람인지 특별한 바람인지 고민할 것 같고.","id":"PRO_M03B_게시판_013","items":[{"k":"line","id":"PRO_M03B_게시판_014","speaker":"캐서린","text":"그 고민도 그대로 전하면 돼. 의뢰인이 알고 싶은 건 네가 붙인 이름이 아니라 지나오는 길에서 겪은 일이야."},{"k":"line","id":"PRO_M03B_게시판_015","speaker":"나","text":"「바람 소리, 바람인지 특별한 바람인지 모름.」 벌써 한 줄 썼네."}]}]},{"k":"line","id":"PRO_M03B_게시판_016","speaker":"","text":"캐서린이 의뢰서 뒷면을 보여 줬다. 산기슭까지 동행할 운반 인력, 인계할 장소, 돌아오지 못할 때 연락할 거점. 정상에 올라가라는 말은 없었다. 그 점이 마음에 들었다."},{"k":"line","id":"PRO_M03B_게시판_017","speaker":"캐서린","text":"방한 장비와 안내는 의뢰 준비에 포함돼. 빌린 장비는 돌아올 때 반납하고. 물건은 알베도에게 직접 전달하면 돼. 현장에서 일을 더 부탁받으면 그건 따로 판단해."},{"k":"line","id":"PRO_M03B_게시판_018","speaker":"나","text":"알베도라는 사람은 설명을 오래 해야 알아듣는 쪽이야, 짧게 해야 알아듣는 쪽이야? 보고할 게 없는 보고를 할 생각에 벌써 긴장돼."},{"k":"line","id":"PRO_M03B_게시판_019","speaker":"캐서린","text":"필요한 부분은 그쪽에서 다시 물어볼 거야. 네가 먼저 다 이해하고 갈 필요는 없어. 전달할 물건과 네가 겪은 일만 구분해서 말하면 돼."},{"k":"line","id":"PRO_M03B_게시판_020","speaker":"나","text":"좋네. 보통 그 말 뒤에 「그래도 어느 정도는 알아서」가 붙는데, 이번엔 없어서."},{"k":"line","id":"PRO_M03B_게시판_021","speaker":"캐서린","text":"의뢰서에 없는 조건을 내가 붙이진 않을게. 궁금한 건 현장에서 물어봐. 이번 의뢰는 그 사람을 만나야 끝나는 일이니까."},{"k":"choice","group":"G_PRO_M03B_게시판_022","options":[{"label":"그럼 맡을게. 본 것만 적고, 모르는 건 물어보면 되겠지.","id":"PRO_M03B_게시판_023","items":[{"k":"line","id":"PRO_M03B_게시판_024","speaker":"캐서린","text":"응. 봉인이 풀려 있으면 도착해서 바로 알려 줘. 궁금하다고 중간에 열어 보지는 말고."},{"k":"line","id":"PRO_M03B_게시판_025","speaker":"나","text":"안 열어. 열어 봐도 뭔지 모를 거라서."}]},{"label":"토벌대 따라가는 건 못 하겠더니, 이제 설산이네. 그래도 해 볼게.","id":"PRO_M03B_게시판_026","items":[{"k":"line","id":"PRO_M03B_게시판_027","speaker":"캐서린","text":"그럼 설산 쪽으로 준비할게. 토벌대와는 장비부터 다르니까 목록을 다시 봐 줘. 여분 장갑도 빼놓지 말고. 산에 가서야 추운 줄 알았다고 하면 내가 건네줄 수가 없어."},{"k":"line","id":"PRO_M03B_게시판_028","speaker":"나","text":"장갑 두 켤레. 적었어. 「사유: 캐서린이 무서워서.」"},{"k":"line","id":"PRO_M03B_게시판_029","speaker":"캐서린","text":"그 사유는 지워도 돼."}]}]},{"k":"keep","id":"ISK_M03_B_217"},{"k":"keep","id":"ISK_M03_B_218","text":"산기슭에서 길을 바꾼 뒤부터 땅의 감촉이 달라졌다. 흙이 묻던 신발 밑에 눈이 뭉치고, 들이마신 공기가 목 안을 차갑게 훑었다. 동행한 운반 인력은 마지막 표식까지 안내하고 연구 거점 쪽으로 나를 넘겼다. 천막 안에서 불빛과 유리병의 반사가 함께 흔들리고 있었다."},{"k":"line","id":"PRO_M03B_드래곤_스파인_001","speaker":"","text":"천막 앞까지 오자 종이 한 장이 바람에 날렸다. 짐을 든 채 발로 막으려다 종이 대신 내 짐끈을 밟았다. 몸이 휘청하는 사이 천막에서 나온 청년이 종이를 집었다."},{"k":"line","id":"PRO_M03B_드래곤_스파인_002","speaker":"알베도","text":"잡으려던 거구나. 고마워. 다만 네 짐까지 넘어졌으면 종이보다 유리병을 먼저 주워야 했을 거야. 발밑 끈이 풀렸어."},{"k":"line","id":"PRO_M03B_드래곤_스파인_003","speaker":"나","text":"보고서에 「도착 직전에 넘어질 뻔함」도 적어야 해? 관찰 기록에 어디까지 넣는지 아직 감을 못 잡았어."},{"k":"line","id":"PRO_M03B_드래곤_스파인_004","speaker":"알베도","text":"내가 직접 봤으니까 그건 다시 설명하지 않아도 돼. 종이가 여기까지 날아온 건 바람 방향이 바뀌었다는 뜻이라 적어 둘 생각이고."},{"k":"line","id":"PRO_M03B_드래곤_스파인_005","speaker":"","text":"농담을 못 알아들은 것 같지는 않았다. 종이에 묻은 눈을 털며 입가가 아주 조금 움직였다. 그는 입구를 더 걷어 올리고 짐 놓을 자리부터 비워 줬다."},{"k":"line","id":"PRO_M03B_드래곤_스파인_006","speaker":"알베도","text":"길드에서 왔구나. 난 알베도야. 짐은 여기 놓아 줘. 먼저 손을 녹이는 게 좋겠어. 끈은 그다음에 풀어도 돼."},{"k":"line","id":"PRO_M03B_드래곤_스파인_007","speaker":"나","text":"{PLAYER_NAME}이야. 봉투는 안 열었어. 손은… 내가 생각한 것보다 말을 잘 안 듣네."},{"k":"line","id":"PRO_M03B_드래곤_스파인_008","speaker":"알베도","text":"끈이 젖어서 더 굳었네. 손이 녹으면 내가 한쪽을 잡아 줄게. 오는 길 이야기는 그동안 들어도 괜찮겠어? 기억하는 순서대로 말해 줘."},{"k":"line","id":"PRO_M03B_드래곤_스파인_009","speaker":"","text":"길에서 본 것과 보지 못한 것을 순서대로 말했다. 특별한 빛은 없었다. 바람이 통로를 지날 때 소리가 달라졌지만 그게 의뢰서의 「이상 현상」인지는 모르겠다고 덧붙였다. 알베도는 그 말까지 적었다."},{"k":"line","id":"PRO_M03B_드래곤_스파인_010","speaker":"알베도","text":"소리가 달라졌다는 통로를 조금 더 설명해 줄래? 들어간 뒤부터 들린 거야, 아니면 계속 들리던 소리가 바뀐 거야?"},{"k":"choice","group":"G_PRO_M03B_드래곤_스파인_011","options":[{"label":"들어간 뒤부터. 뒤에서 누가 따라오는 줄 알고 돌아봤는데 아무도 없었어. 바람이 멎을 때 같이 멎어서 바람이겠거니 했고.","id":"PRO_M03B_드래곤_스파인_012","items":[{"k":"line","id":"PRO_M03B_드래곤_스파인_013","speaker":"알베도","text":"네가 돌아봤다는 부분이 도움이 돼. 발소리와 헷갈릴 정도였다는 뜻이니까. 어느 쪽에서 들렸는지 다음에 비교해 볼 수 있겠어."}]},{"label":"내가 너무 긴장해서 크게 들은 걸 수도 있잖아. 다른 사람은 그냥 지나갈 소리였을지도 모르고.","id":"PRO_M03B_드래곤_스파인_014","items":[{"k":"line","id":"PRO_M03B_드래곤_스파인_015","speaker":"알베도","text":"그 가능성도 있지. 그렇다고 네가 들은 일을 지우면 비교할 기회까지 사라져. 내가 확인하고 싶은 건 네가 예민했는지가 아니야."}]}]},{"k":"line","id":"PRO_M03B_드래곤_스파인_016","speaker":"","text":"알베도는 기록 옆에 짧게 표시를 남겼다. 헷갈렸다고 말했는데 답을 다시 고르라는 소리를 듣지 않았다. 그게 따뜻해지는 손끝만큼 천천히 실감 났다."},{"k":"keep","id":"ISK_M03_B_224","text":"손끝의 감각이 돌아온 뒤 봉투와 도구를 인계했다. 알베도는 봉인을 확인하고 수량을 세어 길드에 돌려보낼 인수 기록을 썼다. 내가 들고 온 빈 짐끈은 그새 말라 있었다."},{"k":"line","id":"PRO_M03B_드래곤_스파인_017","speaker":"나","text":"보상보다 지금은 따뜻한 의자가 더 반갑네."},{"k":"line","id":"PRO_M03B_드래곤_스파인_018","speaker":"알베도","text":"그럼 의자부터 빌려줄게. 난 한동안 서서 일할 거라 괜찮아. 마실 물은 오른쪽 주전자에 있어. 잔은… 잠깐, 새 걸 꺼내 줄게. 그쪽은 실험에 쓰는 것들이 섞여 있거든."},{"k":"line","id":"PRO_M03B_드래곤_스파인_019","speaker":"나","text":"방금 그 「잠깐」이 오늘 들은 말 중에 제일 중요했던 것 같아."},{"k":"keep","id":"ISK_M03_B_229"},{"k":"line","id":"PRO_M03B_천막_001","speaker":"","text":"앉고 나자 짐을 내려놓았다는 사실이 뒤늦게 몸 전체로 퍼졌다. 알베도는 물을 따르고도 바로 연구대로 돌아가지 않고 맞은편 낮은 상자에 앉았다. 내려온 길 상태를 몇 가지 더 묻고는 질문을 멈췄다."},{"k":"line","id":"PRO_M03B_천막_002","speaker":"나","text":"혹시 지금 내가 쉬는 것도 관찰하는 중이야? 뭘 말하면 하나씩 적으니까 괜히 자세를 똑바로 하게 되네."},{"k":"line","id":"PRO_M03B_천막_003","speaker":"알베도","text":"지금은 차가 너무 뜨겁지 않은지 보고 있었어. 급하게 마실 것 같아서. 관찰이라면 관찰이지만, 그 자세를 기록할 생각은 없어."},{"k":"line","id":"PRO_M03B_천막_004","speaker":"나","text":"다행이다. 「배달원, 의자에 앉은 뒤 의욕 급감」 같은 문장으로 남으면 좀 억울해서."},{"k":"line","id":"PRO_M03B_천막_005","speaker":"알베도","text":"추운 길을 걸어온 뒤 쉬고 있다고 적으면 덜 억울할까? 같은 모습에도 이유를 어떻게 붙이느냐에 따라 다른 사람이 되는군."},{"k":"line","id":"PRO_M03B_천막_006","speaker":"","text":"알베도는 그렇게 말하고 잠깐 생각에 잠겼다. 내가 잔을 내려놓자 고개를 들며 작게 웃었다."},{"k":"line","id":"PRO_M03B_천막_007","speaker":"나","text":"방금 웃었지? 네 표정은 조금 늦게 봐야 하는구나. 혼자 떠드는 줄 알고 다음 농담은 접어 둘 뻔했어."},{"k":"line","id":"PRO_M03B_천막_008","speaker":"알베도","text":"응, 방금 건 재밌었어. 그다음 농담까지 미리 통했다고 치지는 말고."},{"k":"line","id":"PRO_M03B_천막_009","speaker":"","text":"천막 천을 때리던 바람이 한 번 크게 불었다. 알베도는 입구를 확인하고 돌아와 마른 천을 내 곁에 놓았다. 젖은 소매가 손목에 붙어 있는 걸 본 것이다. 이번에는 설명을 붙이지 않았다."},{"k":"line","id":"PRO_M03B_천막_010","speaker":"","text":"바람이 거세져 귀환을 기다리는 동안 알베도는 펼쳐 둔 기록의 추를 고쳐 놓았다. 한쪽 종이가 접히자 빈 병으로 눌러 줬다."},{"k":"line","id":"PRO_M03B_천막_011","speaker":"알베도","text":"거기면 돼. 날짜를 가리지 않게 해 줘. 같은 위치를 그린 그림도 언제 그렸는지 모르면 비교하기 어려워지거든."},{"k":"line","id":"PRO_M03B_천막_012","speaker":"나","text":"아, 이거 날짜였구나. 그림 모서리에 서명한 건 줄 알았어. 기록용 그림도 이렇게 잘 그려야 하는 거야?"},{"k":"line","id":"PRO_M03B_천막_013","speaker":"알베도","text":"잘 그리는 것과 필요한 걸 남기는 건 조금 달라. 보기에 완성됐어도 관찰하려던 부분이 빠지면 기록으로는 곤란해. 반대로 몇 줄만 있어도 다시 찾을 수 있다면 도움이 되고."},{"k":"line","id":"PRO_M03B_천막_014","speaker":"나","text":"그러면 나도 못 그리는 걸 기록용이라고 우길 수는 있겠네. 사람 그리면 본인이 못 알아봐서 문제지."},{"k":"line","id":"PRO_M03B_천막_015","speaker":"알베도","text":"그 사람만 못 알아보는 건지, 다른 사람도 못 알아보는 건지에 따라 이유가 다를 것 같아. 하지만 지금 당장 그림으로 증명하라고 하지는 않을게."},{"k":"line","id":"PRO_M03B_천막_016","speaker":"","text":"알베도가 종이 한 장을 옆으로 빼냈다. 눈 쌓인 능선 아래 천막이 작게 그려져 있었다. 지형보다 천막 앞에 늘어진 끈이 먼저 보였다. 내가 방금 밟을 뻔한 자리였다."},{"k":"choice","group":"G_PRO_M03B_천막_017","options":[{"label":"이건 의뢰에 필요한 그림이야? 아니면 그냥 그리고 싶어서 그린 거야?","id":"PRO_M03B_천막_018","items":[{"k":"line","id":"PRO_M03B_천막_019","speaker":"알베도","text":"처음에는 그냥 그렸어. 한동안 밖에서 보기 어려운 날씨여서 내가 머무는 곳을 한 번 보고 싶었거든. 처음부터 모든 선에 용도를 정하지는 않아."},{"k":"line","id":"PRO_M03B_천막_020","speaker":"나","text":"집 그림이네. 그럼 이 끈은 「집 앞에 널어 둔 빨래」 같은 거고."}]},{"label":"이건 전부 같은 데를 그린 거야? 처음엔 똑같은 그림인 줄 알았는데, 여긴 조금 다르네.","id":"PRO_M03B_천막_021","items":[{"k":"line","id":"PRO_M03B_천막_022","speaker":"알베도","text":"눈이 쌓인 양이 달라. 그 아래 형태가 변했는지 보려면 눈 때문에 달라 보이는 부분부터 구분해야 해. 눈이 그친 뒤 위쪽 관측 지점에서 다시 확인할 생각이야."}]}]},{"k":"line","id":"PRO_M03B_천막_023","speaker":"나","text":"나는 눈이 늘어난 것보다 그림자가 옮겨 간 게 먼저 보여. 그래서 바위가 한쪽으로 기운 줄 알았어. 여기, 검은 부분이 길어졌잖아."},{"k":"line","id":"PRO_M03B_천막_024","speaker":"알베도","text":"그렇게 볼 수도 있겠네. 그건 내가 같은 시각에 그리지 못해서 생긴 차이야. 네가 잘못 본 게 아니라 내가 비교하기 불편하게 남긴 거지."},{"k":"line","id":"PRO_M03B_천막_025","speaker":"나","text":"그럼 네 그림 탓도 조금 있었네. 괜히 아는 척했다고 물러설 뻔했어. 그림자 선을 따로 표시하면 어떨까? 적어도 나는 어느 쪽이 바위인지 덜 헷갈릴 것 같은데."},{"k":"line","id":"PRO_M03B_천막_026","speaker":"알베도","text":"그림자와 모서리를 따로 표시해 볼게. 그다음에 다시 봐 줘. 고친 사람이 혼자 알아보기 쉽다고 해 봐야 소용없으니까."},{"k":"line","id":"PRO_M03B_천막_027","speaker":"","text":"알베도가 옆에 작은 윤곽선을 덧그렸다. 어떤 선을 고치고 어떤 선을 남기는지 보고 있으니, 대단한 그림이라는 감탄보다 손이 움직이는 과정에 더 눈이 갔다."},{"k":"line","id":"PRO_M03B_천막_028","speaker":"나","text":"종이에는 금방 고치네. 나는 틀린 거 찾으면 처음부터 다시 할 생각부터 드는데. 그러다 손대기 싫어지고."},{"k":"line","id":"PRO_M03B_천막_029","speaker":"알베도","text":"처음부터 다시 그리면 방금 헷갈렸던 자리도 또 찾아야 하잖아. 지금은 이 선 하나면 돼. 말리는 동안 가장자리만 잡아 줘."},{"k":"line","id":"PRO_M03B_천막_030","speaker":"","text":"종이를 날짜순으로 놓는 일을 도왔다. 순서가 바뀐 두 장을 찾았을 때 알베도는 날짜만 고치지 않고 그날 왜 같은 자리를 다시 그렸는지 설명했다. 두 사람이 같은 종이를 보며 고개를 숙이는 시간이 길어졌다."},{"k":"line","id":"PRO_M03B_천막_031","speaker":"","text":"알베도가 작게 포장한 음식을 꺼내 빈자리에 놓았다. 기록 위에 부스러기가 떨어질까 봐 의자를 뒤로 당기자, 그는 종이부터 다른 쪽으로 옮겼다."},{"k":"line","id":"PRO_M03B_천막_032","speaker":"알베도","text":"네가 계속 물러나면 천막 밖에서 먹게 될 것 같아. 여기서 먹어도 괜찮아. 나도 정리를 잠깐 멈추려던 참이었어."},{"k":"line","id":"PRO_M03B_천막_033","speaker":"나","text":"네가 안 쉬니까 나도 돕다가 슬쩍 빠지기 애매했어. 일 좋아하는 사람 옆에 있으면 내 쉬는 시간이 내가 빠지는 시간처럼 보이더라. 전 직장에서 배운 거야."},{"k":"line","id":"PRO_M03B_천막_034","speaker":"알베도","text":"그랬구나. 나는 네가 그림에 관심이 있어서 계속 보고 싶은 줄 알았어. 흥미로운 일이어도 쉬는 건 따로 필요한데, 내가 말을 안 했네."},{"k":"line","id":"PRO_M03B_천막_035","speaker":"나","text":"관심은 있어. 신기하기도 하고. 근데 계속 처음 보는 것만 있으니까 머리가 좀 꽉 차. 지금 그 안에 음식 이름까지 넣으면 하나는 떨어뜨릴 것 같고."},{"k":"line","id":"PRO_M03B_천막_036","speaker":"알베도","text":"그럼 이름은 나중에 말할게. 마음에 들면 물어봐. 외우고 먹어야 하는 건 아니니까."},{"k":"line","id":"PRO_M03B_천막_037","speaker":"","text":"내가 웃자 알베도도 조금 늦게 웃었다. 바람은 여전히 불었지만 천막 안에서 말을 멈추는 일이 덜 어색해졌다."},{"k":"line","id":"PRO_M03B_천막_038","speaker":"나","text":"너는 여기서 이렇게 지내는 게 좋아? 내가 온 뒤로 눈이 그친 걸 못 봐서, 혼자 있으면 엄청 조용하겠다는 생각밖에 안 들어."},{"k":"line","id":"PRO_M03B_천막_039","speaker":"알베도","text":"좋아하는 부분이 있어. 같은 곳을 다시 봐도 조금씩 다른 게 보이니까. 혼자면 집중하기 좋고. 하지만 오늘은 네가 다르게 보는 걸 들을 수 있어서 좋았어."},{"k":"line","id":"PRO_M03B_천막_040","speaker":"나","text":"내 감상은 꽤 솔직했지. 다음에는 설명하기 전에 그림부터 보여 줘. 네가 정답을 말하고 나면 나도 괜히 그쪽만 보게 돼."},{"k":"line","id":"PRO_M03B_천막_041","speaker":"알베도","text":"좋아. 날짜만 보이게 두고 먼저 건네줄게. 대신 숨은 정답을 맞히는 시험은 아니야. 내가 그리다 빠뜨린 게 나올 수도 있으니까."},{"k":"line","id":"PRO_M03B_천막_042","speaker":"","text":"밖의 바람 소리가 조금 낮아졌다. 알베도가 입구를 확인하러 일어났다가, 마저 먹어도 된다는 듯 손을 가볍게 내렸다."},{"k":"line","id":"PRO_M03B_천막_043","speaker":"알베도","text":"바람이 잦아들고 있어. 이따 위쪽 관측 지점에 가 볼 생각인데, 괜찮다면 같이 갈래? 기록판을 맡아 주면 도움이 되고… 방금 같이 본 풍경을 실제로 보면 네가 뭐라고 할지도 궁금해."},{"k":"line","id":"PRO_M03B_천막_044","speaker":"나","text":"배달 끝나니까 업무가 하나 더 생겼네. 어디까지 올라가는 건데?"},{"k":"line","id":"PRO_M03B_천막_045","speaker":"알베도","text":"정상 쪽이야. 아래에서 보는 것과는 다른 걸 확인할 수 있어. 위험한 구간은 내가 먼저 살피고, 날씨가 나빠지면 돌아올 거야. 여기서 기다려도 괜찮아."},{"k":"line","id":"PRO_M03B_천막_046","speaker":"나","text":"원래 의뢰는 여기서 끝난 거지? 갑자기 정상까지 가야 도장 찍어 주는 건 아니고."},{"k":"line","id":"PRO_M03B_천막_047","speaker":"알베도","text":"인수 기록은 아까 작성했어. 네가 여기서 돌아가도 그걸 바꾸지 않아. 지금은 내가 개인적으로 같이 가자고 묻는 거야."},{"k":"line","id":"PRO_M03B_천막_048","speaker":"","text":"알베도는 말하면서 장비를 둘 곳을 나눴다. 혼자 갈 때 하던 동작을 멈추고 기록판 끈의 길이를 나에게 맞춰 봤다. 그걸 보고서야 초대가 예의상 나온 말이 아니라는 생각이 들었다."},{"k":"choice","group":"G_PRO_M03B_천막_049","options":[{"label":"같이 가 볼게. 대신 올라가는 속도는 좀 봐줘.","id":"PRO_M03B_천막_050","items":[{"k":"line","id":"PRO_M03B_천막_051","speaker":"알베도","text":"물론이야. 네가 내 걸음에 맞출 필요는 없어. 숨이 차거나 손의 감각이 떨어지면 바로 말해. 그때 쉬는 게 결국 더 빨라."},{"k":"line","id":"PRO_M03B_천막_052","speaker":"나","text":"그 말, 내려올 때까지 기억하고 있을게. 내가 아니라 네가."}]},{"label":"기록판은 맡을게. 대신 처음 듣는 말은 천천히 불러 줘. 못 받아 적고 있는데 다음 항목으로 넘어가면 나중에 둘 다 이게 무슨 글씨냐고 하게 될걸.","id":"PRO_M03B_천막_053","items":[{"k":"line","id":"PRO_M03B_천막_054","speaker":"알베도","text":"한 항목씩 말하고 네가 적은 걸 확인한 뒤 넘어갈게. 나중에 네 기록을 해독하는 연구까지 시작할 생각은 없으니까."},{"k":"line","id":"PRO_M03B_천막_055","speaker":"나","text":"그 연구는 아무도 성공 못 해. 나도 못 읽거든."}]}]},{"k":"keep","id":"ISK_M03_B_242"},{"k":"line","id":"PRO_M03B_관측_지점으로_001","speaker":"","text":"바람이 약해진 뒤 두 사람은 거점을 나섰다. 알베도는 발 놓을 곳을 먼저 확인하고 짧게 말했고, 나는 같은 자리를 밟으며 따라갔다. 높이 올라갈수록 한 문장을 끝내는 데 숨이 더 필요했다."},{"k":"line","id":"PRO_M03B_관측_지점으로_002","speaker":"","text":"천막이 능선 아래로 가려지자 그림에서 보던 길이 발밑에 놓였다. 종이 위에서 손가락 한 마디였던 구간이 한참을 걸어도 끝나지 않았다."},{"k":"line","id":"PRO_M03B_관측_지점으로_003","speaker":"나","text":"네 그림이 조금 원망스러워졌어. 아까는 바로 옆인 것처럼 보였는데, 종이에 작게 그려졌다고 가까운 건 아니었네."},{"k":"line","id":"PRO_M03B_관측_지점으로_004","speaker":"알베도","text":"그림에는 걷는 시간이 안 들어가 있으니까. 지금 어느 구간인지 보여 줄까?"},{"k":"line","id":"PRO_M03B_관측_지점으로_005","speaker":"나","text":"조금 뒤에. 지금 확인했는데 아직 반도 안 왔다고 하면 표정 관리가 안 될 것 같아."},{"k":"line","id":"PRO_M03B_관측_지점으로_006","speaker":"알베도","text":"알겠어. 그럼 저 바위까지만 보자. 거기서는 바람을 조금 피할 수 있어."},{"k":"line","id":"PRO_M03B_관측_지점으로_007","speaker":"","text":"바위에 닿기 전에 알베도가 손을 들었다. 눈 위에 발자국이 아닌 자국이 있었다. 둥글게 미끄러진 자국. 바위 뒤에서 푸른빛이 번졌다."},{"k":"line","id":"PRO_M03B_관측_지점으로_008","speaker":"알베도","text":"뒤로. 기록판은 가슴에 안고 있어. 이쪽은 내가 볼게."},{"k":"combat","id":"PRO_M03B_관측_지점으로_009","group":"EG_DRAGON_CRYO","text":"바위 뒤에서 얼음 슬라임이 굴러 나오고, 능선 위에서 얼음 활을 든 츄츄족이 내려다본다. 좁은 눈길에서 길을 연다."},{"k":"line","id":"PRO_M03B_관측_지점으로_010","speaker":"","text":"마지막 슬라임이 눈 속으로 꺼지자 알베도는 손에 남은 빛을 털었다. 기록판을 안은 팔이 저렸다. 떨어뜨리지 않은 게 오늘 한 일 중 제일 잘한 일 같았다."},{"k":"line","id":"PRO_M03B_관측_지점으로_011","speaker":"나","text":"이것도 적어? 「바위 앞, 슬라임, 시각은 모름. 사유: 시계가 없음.」"},{"k":"line","id":"PRO_M03B_관측_지점으로_012","speaker":"알베도","text":"적어 둬. 시각은 해 위치로 내가 보탤게. 숨 고르고 나서."},{"k":"line","id":"PRO_M03B_관측_지점으로_013","speaker":"알베도","text":"여기서 쉬자. 조금 전부터 대답하는 간격이 길어졌어. 위쪽은 바람을 피할 곳이 더 적으니까 지금 숨을 돌리는 편이 좋아."},{"k":"line","id":"PRO_M03B_관측_지점으로_014","speaker":"나","text":"괜찮다고 할 뻔했는데, 먼저 알아보네. 잠깐만 쉬자."},{"k":"line","id":"PRO_M03B_관측_지점으로_015","speaker":"","text":"바위에 기대어 고개를 끄덕였다. 알베도는 나를 계속 살피는 대신 기록판을 꺼냈다. 지친 사람 앞에서 빨리 회복하기를 기다리는 표정을 하지 않는 점이 고마웠다."},{"k":"line","id":"PRO_M03B_관측_지점으로_016","speaker":"","text":"숨을 고르는 동안 알베도는 능선의 모양을 짧게 그렸다. 내가 몸을 기울이자 기록판을 가운데로 옮겨 줬다. 같이 올라온 길은 종이 위에서 훨씬 짧아 보였다."},{"k":"line","id":"PRO_M03B_관측_지점으로_017","speaker":"알베도","text":"여기 꺾인 선이 방금 올라온 곳이야. 네가 그림을 원망했던 바위도 이쯤이고. 쉬어 간 자리를 표시해 두는 편이 네가 알아보기 쉽겠네."},{"k":"line","id":"PRO_M03B_관측_지점으로_018","speaker":"나","text":"나는 경치보다 저 바위 모양이 더 잘 기억날 것 같아. 넘어가면 평지인 줄 알았는데 또 오르막 나와서 되게 서운했거든."},{"k":"line","id":"PRO_M03B_관측_지점으로_019","speaker":"알베도","text":"그런 이유로 기억하는 지형도 있구나. 나는 윤곽이나 돌의 결을 먼저 봤어. 네 설명을 듣고 보니 이름을 붙이지 않아도 어느 바위인지 알겠네."},{"k":"line","id":"PRO_M03B_관측_지점으로_020","speaker":"나","text":"그러면 내려갈 때는 「배신한 바위」에서 왼쪽이야? 알베도의 정확한 지도에 내 개인 감정이 들어가고 있는데."},{"k":"line","id":"PRO_M03B_관측_지점으로_021","speaker":"알베도","text":"네가 알아들을 수 있다면 길을 설명하는 데는 도움이 되겠지. 공식 기록에는 다른 표식을 쓸 거고. 그 바위가 일부러 오르막을 숨긴 건 아닐 테니까."},{"k":"line","id":"PRO_M03B_관측_지점으로_022","speaker":"","text":"웃다가 찬 공기를 들이마시고 기침했다. 알베도는 웃음을 거두지 않은 채 물을 건넸다. 천막에서는 알아보기 어려웠던 작은 표정 변화가 이제는 전보다 빨리 보였다."},{"k":"line","id":"PRO_M03B_관측_지점으로_023","speaker":"나","text":"정상까지 올라가면, 네가 처음 봤을 때 무슨 생각 했는지도 말해 줘. 설명서에 나올 말 말고. 나만 계속 감상평 내는 것 같아서."},{"k":"line","id":"PRO_M03B_관측_지점으로_024","speaker":"알베도","text":"좋아. 다만 기억을 잘 고르려면 잠깐 생각할 수는 있어. 그때 네가 먼저 말해도 괜찮아."},{"k":"line","id":"PRO_M03B_한천의_못_001","speaker":"","text":"다시 걷기 시작하자 눈앞을 가리던 능선이 낮아졌다. 바위 너머로 길고 거대한 구조물이 나타났다. 주변의 오래된 돌과도 다른 모양이었다. 처음에는 그게 얼마나 가까운지 가늠하지 못했다."},{"k":"line","id":"PRO_M03B_한천의_못_002","speaker":"알베도","text":"한천의 못이야. 여기서 보면 아래쪽 구조도 살필 수 있어. 오늘 확인하려던 대상이지."},{"k":"line","id":"PRO_M03B_한천의_못_003","speaker":"나","text":"못이라고 부르기엔 너무 큰데…. 저게 지금 떠 있는 거야?"},{"k":"line","id":"PRO_M03B_한천의_못_004","speaker":"","text":"못의 끝을 올려다보다가 몸이 뒤로 젖혀져 있다는 걸 알았다. 구름이 움직여도 그 거대한 구조물은 같은 자리에 남아 있었다. 무거운 물건은 떨어진다는 평범한 생각이 눈앞의 풍경과 맞지 않았다."},{"k":"choice","group":"G_PRO_M03B_한천의_못_005","options":[{"label":"설명 듣기 전에 소감부터 말하면, 여기까지 올라온 것보다 저게 저기 있는 게 더 이해가 안 돼. 바람에 버티는 모양도 아닌데.","id":"PRO_M03B_한천의_못_006","items":[{"k":"line","id":"PRO_M03B_한천의_못_007","speaker":"알베도","text":"나도 처음에는 어떻게 떠 있는지보다, 왜 이곳에 이런 형태로 남아 있는지가 먼저 궁금했어. 가까이서 볼수록 주변의 다른 유적과 한 가지 방식으로 묶기 어렵거든."},{"k":"line","id":"PRO_M03B_한천의_못_008","speaker":"나","text":"생각보다 감상도 연구랑 가깝네. 난 그냥 「너무 크다」에서 막혔어. 그 뒤 문장이 아직 안 나와."},{"k":"line","id":"PRO_M03B_한천의_못_009","speaker":"알베도","text":"너무 크다는 것도 맞는 말이지. 처음 느낀 것을 급하게 그럴듯한 문장으로 바꾸지 않아도 돼."}]},{"label":"그럼 지금은 그냥 볼게. 아까 그 그림을 보고 올라오길 잘했다는 생각은 들어. 종이에서는 떠 있다는 게 이렇게 이상하지 않았거든.","id":"PRO_M03B_한천의_못_010","items":[{"k":"line","id":"PRO_M03B_한천의_못_011","speaker":"알베도","text":"그 말은 적어 둘게. 그림이 전하지 못한 걸 네가 하나 알려 줬어."}]}]},{"k":"line","id":"PRO_M03B_한천의_못_012","speaker":"","text":"알베도는 내가 구조물을 바라보는 동안 기록판을 펴지 않았다. 조금 뒤 내가 먼저 손을 내밀자 그제야 판을 넘겨줬다. 차가운 공기 속에서 둘의 숨이 잠깐 같은 방향으로 흩어졌다."},{"k":"line","id":"PRO_M03B_한천의_못_013","speaker":"알베도","text":"그럼 지금 보이는 부분부터 같이 남겨 보자. 아래쪽 모서리부터 볼게. 그림에서 본 선과 다르게 보이는 곳이 있으면 말해 줘."},{"k":"keep","id":"ISK_M03_B_252","text":"기록판을 가슴 높이로 들고 고개를 올렸다. 알베도가 첫 항목을 말하려던 순간 구조물 밑에서 가느다란 가루가 떨어졌다. 바람에 흩날리는 눈과는 무게가 달랐다."},{"k":"line","id":"PRO_M03B_한천의_못_014","speaker":"알베도","text":"뒤로 와. 기록판은 내려놔!"},{"k":"line","id":"PRO_M03B_한천의_못_015","speaker":"","text":"공중에 있던 구조물이 기울었다. 조금씩 낮아지는 정도가 아니었다. 알베도가 내 팔을 잡아 바위 뒤로 끌어당기는 동안 한천의 못이 아래로 떨어졌다. 눈과 돌이 함께 솟구치고, 뒤늦게 충격음이 산비탈을 타고 번졌다."},{"k":"line","id":"PRO_M03B_한천의_못_016","speaker":"","text":"얼굴을 가린 팔 위로 작은 파편이 떨어졌다. 바닥에 무릎을 붙인 채 소리가 잦아들기를 기다렸다. 알베도는 내 어깨를 눌러 아직 일어나지 못하게 했다. 거대한 구조물은 이미 여러 조각으로 부서져 있었다."},{"k":"line","id":"PRO_M03B_한천의_못_017","speaker":"","text":"충격이 지나간 자리에 곧장 정적이 오지는 않았다. 위에서 굴러내린 돌이 다른 돌을 건드리는 소리가 한동안 이어졌다. 방금 전까지 함께 올려다보던 것이 이제 바닥에서 소리를 내고 있었다."},{"k":"line","id":"PRO_M03B_한천의_못_018","speaker":"알베도","text":"다친 데 있어? 지금 바로 일어나지 마. 위에서 더 떨어지는 게 없는지 확인할게."},{"k":"line","id":"PRO_M03B_한천의_못_019","speaker":"","text":"손발을 하나씩 움직여 봤다. 답하려고 입을 열었을 때, 아주 가까운 곳에서 속삭임이 들렸다. 눈보라를 거치지도, 귀에 닿기까지 거리를 지나지도 않은 것 같은 목소리였다."},{"k":"line","id":"PRO_M03B_한천의_못_020","speaker":"","text":"「넌 내 거야.」"},{"k":"keep","id":"ISK_M03_B_259","text":"고개를 돌려도 말을 건 사람이 보이지 않았다. 알베도는 위쪽 사면을 살피고 있었다. 방금 들은 말을 붙잡으려 했지만 소리는 더 이어지지 않았다. 무엇의 목소리인지, 어디서 들렸는지 알 수 없었다."},{"k":"choice","group":"G_PRO_M03B_한천의_못_021","options":[{"label":"알베도, 방금 무슨 말 했어?","id":"PRO_M03B_한천의_못_022","items":[{"k":"line","id":"PRO_M03B_한천의_못_023","speaker":"알베도","text":"다친 곳이 있는지 물었어. 그 뒤로는 말하지 않았어. 네가 들은 건 다른 말이었구나. 어떤 목소리였는지 설명할 수 있겠어?"}]},{"label":"누가 말을 걸었어. 가까이 있었는데 아무도 안 보여.","id":"PRO_M03B_한천의_못_024","items":[{"k":"line","id":"PRO_M03B_한천의_못_025","speaker":"알베도","text":"난 네가 들었다는 목소리는 못 들었어. 지금 보이는 사람도 우리 둘뿐이고. 하지만 내가 못 들은 걸 없었다고 할 수는 없겠지. 네가 기억하는 말은 그대로 남겨 두자."}]}]},{"k":"keep","id":"ISK_M03_B_264"},{"k":"line","id":"PRO_M03B_한천의_못_026","speaker":"","text":"천막에서 바람 소리를 설명하던 일이 떠올랐다. 그때는 발소리와 헷갈렸다고 말할 수 있었다. 이번에는 무엇과 헷갈렸는지를 말할 수 없었다. 무너지는 소리 속에서도 그 한마디만 또렷했다."},{"k":"line","id":"PRO_M03B_한천의_못_027","speaker":"나","text":"방향을 모르겠어. 귀에 가까웠는데, 고개를 돌리니까 가까운 데 사람이 없었어. 아까 길에서 들었다던 소리랑은 달라."},{"k":"line","id":"PRO_M03B_한천의_못_028","speaker":"알베도","text":"알겠어. 같은 소리라고 생각하지 않을게. 설명하기 어려운 부분은 그대로 두자. 우선 내 목소리는 여기서 들리고 있지?"},{"k":"line","id":"PRO_M03B_한천의_못_029","speaker":"","text":"알베도가 서 있는 쪽을 봤다. 입술이 움직이고, 말이 끝난 뒤 바람 소리가 다시 들어왔다. 방금 전의 목소리에는 그런 틈이 없었다. 기억을 붙잡으려 할수록 그 차이만 더 선명해졌다."},{"k":"line","id":"PRO_M03B_한천의_못_030","speaker":"","text":"눈먼지가 가라앉았다. 알베도가 떨어질 돌이 없는지 확인하고 앞으로 나서자 나도 바위 뒤에서 몸을 일으켰다. 한천의 못이 있던 자리에 거대한 잔해가 흩어져 있었다. 그 가운데, 다른 조각들과 달리 둥근 물체 하나가 작은 틈에 남아 있었다."},{"k":"line","id":"PRO_M03B_한천의_못_031","speaker":"나","text":"저기 가운데. 작은 구슬 같은 게 있어."},{"k":"line","id":"PRO_M03B_한천의_못_032","speaker":"알베도","text":"봤어. 아직 손대지 마. 주변이 더 무너지지 않는지부터 볼게."},{"k":"line","id":"PRO_M03B_한천의_못_033","speaker":"","text":"수정구슬은 손안에 들어갈 만큼 작아 보였다. 거대한 잔해 사이에 있어서 오히려 눈에 잘 띄지 않았다. 조금 전의 목소리를 떠올리며 그 둥근 표면을 봤다. 구슬이 말을 한 건지, 목소리와 아무 관련이 없는 건지 알 수 없었다. 다만 무너진 한천의 못 가운데 그것이 남아 있었다."},{"k":"keep","id":"ISK_M03_B_269","text":"한천의 못의 잔해 가운데 작은 수정구슬을 발견했다."}],"edits":[],"pre":""},{"id":"ISK_M03_K","entry":"ISK_M03_K_001","items":[{"k":"keep","id":"ISK_M03_K_001","text":"이틀 동안 기사단에서 온 연락은 짧았다. 새로 확인된 것은 없다는 말, 눈물은 그대로라는 말. 사흘째 아침에 엠버가 직접 찾아왔다. 지도도 보고서도 들지 않은 손으로."},{"k":"line","id":"PRO_M03K_사흘째_아침_001","speaker":"엠버","text":"진 단장이 기다리고 있어. 음유시인도 한 명 와 있고. 네가 말한 벤티, 맞지? 오는 길에 노래를 부르더라. 본부 앞에서는 좀 조용해졌지만."},{"k":"line","id":"PRO_M03K_사흘째_아침_002","speaker":"나","text":"노래를 부르면서 왔다니 벤티가 맞네. 그 사람은 장례식에 가도 노래할 거야."},{"k":"line","id":"PRO_M03K_사흘째_아침_003","speaker":"엠버","text":"그런 농담은 본부 안에서는 하지 마. …그리고 먼저 말해 두는데, 누가 널 혼내려고 부른 건 아니야. 그 눈물이 네 손에서 안 바뀐 거, 아무도 네 탓이라고 안 해."},{"k":"line","id":"PRO_M03K_사흘째_아침_004","speaker":"나","text":"알아. 그래서 더 민망한 거야. 아는 척했는데 틀렸잖아."},{"k":"line","id":"PRO_M03K_사흘째_아침_005","speaker":"엠버","text":"틀렸다고 말할 수 있는 사람은 다음에 덜 틀려. 가자."},{"k":"line","id":"PRO_M03K_단장실_001","speaker":"","text":"단장실에는 케이아와 진, 그리고 창가에 선 초록 옷의 음유시인이 있었다. 벤티는 책상 위의 상자를 보고 있었다. 뚜껑이 열려 있었고, 안에는 내가 바꾸지 못한 눈물이 있었다."},{"k":"line","id":"PRO_M03K_단장실_002","speaker":"벤티","text":"네가 찾아온 거구나. 고마워. 이걸 들고 오는 동안 좋은 일만 있지는 않았겠네."},{"k":"line","id":"PRO_M03K_단장실_003","speaker":"나","text":"인사는 받을게. 고생은 했으니까. 그런데 미리 말해 두는데, 내 손에서는 꿈쩍도 안 했어. 기대했다가 실망하는 건 한 번으로 충분해서."},{"k":"line","id":"PRO_M03K_단장실_004","speaker":"벤티","text":"그럼 가져온 수고부터 고마워할게. 이건 내 친구가 남긴 거니까."},{"k":"line","id":"PRO_M03K_단장실_005","speaker":"케이아","text":"그 인사는 받아 둬. 오늘 이 방에서 쉽게 얻을 수 있는 말은 그 정도일 테니까. 나머지는 질문이 좀 길어질 예정이야."},{"k":"line","id":"PRO_M03K_단장실_006","speaker":"엠버","text":"케이아 선배, 들어오자마자 겁주지 마세요. 오는 길에 겨우 어깨 펴고 왔는데."},{"k":"line","id":"PRO_M03K_단장실_007","speaker":"케이아","text":"그랬어? 그럼 의자부터 권해야겠네. 단장 대행님, 오늘은 서서 보고받으실 생각은 아니시죠?"},{"k":"line","id":"PRO_M03K_단장실_008","speaker":"진","text":"앉으세요. 모두요."},{"k":"line","id":"PRO_M03K_단장실_009","speaker":"","text":"케이아가 의자 하나를 발끝으로 빼 줬다. 장난스럽게 말하는 사람이 둘이나 있었는데, 아무도 상자를 가운데에서 치우지는 않았다."},{"k":"line","id":"PRO_M03K_단장실_010","speaker":"진","text":"벤티 씨, 말씀드린 대로 눈물에는 변화가 없습니다. 하프의 행방도 찾지 못했습니다. 사당의 우인단은 전원 사망한 상태였습니다."},{"k":"line","id":"PRO_M03K_단장실_011","speaker":"벤티","text":"드발린을 부를 악기를 찾으러 갔는데, 거기 있던 사람들이 먼저 죽어 있었다라…. 누군가 우리가 가려는 길을 미리 알고 있었던 걸까."},{"k":"choice","group":"G_PRO_M03K_단장실_012","options":[{"label":"내가 하프 얘기를 꺼낸 뒤에 이렇게 됐어. 자꾸 연결해서 생각하게 돼.","id":"PRO_M03K_단장실_013","items":[{"k":"line","id":"PRO_M03K_단장실_014","speaker":"케이아","text":"자네가 그 말을 하기 전에도 하프는 이미 없어졌어. 그 뒤의 죽음까지 같은 사람의 계획인지는 별개고. 모든 화살표를 자기 발밑에서 시작할 필요는 없어."},{"k":"line","id":"PRO_M03K_단장실_015","speaker":"나","text":"화살표를 제 발밑에서 시작하는 게 버릇이라서요. 회사에서도 그랬어요. 다 제 탓 같고."},{"k":"line","id":"PRO_M03K_단장실_016","speaker":"케이아","text":"그 버릇은 여기서 고치지. 자네 탓으로 돌리면 범인이 편해져."}]},{"label":"우인단 안에서 다른 명령이 있었을 수도 있잖아요. 집행관들은 서로 사이가 좋지 않아요.","id":"PRO_M03K_단장실_017","items":[{"k":"line","id":"PRO_M03K_단장실_018","speaker":"케이아","text":"가능성으로 적어 두지. 다만 우리가 여기서 확인한 우인단은 시뇨라의 부하들뿐이야. 다른 병력이 들어왔다는 보고는 없어."},{"k":"line","id":"PRO_M03K_단장실_019","speaker":"엠버","text":"그럼 이름 대신 「다른 명령을 받은 사람이 있었는지」를 물으면 되지 않을까요?"},{"k":"line","id":"PRO_M03K_단장실_020","speaker":"케이아","text":"좋은 질문이야. 소문에 사람 얼굴을 붙이는 것보다 훨씬 낫지."}]}]},{"k":"line","id":"PRO_M03K_단장실_021","speaker":"진","text":"시뇨라 측에 설명을 요구하겠습니다. 자기 부하들이 죽은 일에 무엇을 알고 있는지 답해야 할 겁니다. 다만 답을 기다리는 동안 손을 놓고 있지는 않겠습니다."},{"k":"line","id":"PRO_M03K_단장실_022","speaker":"벤티","text":"내가 걱정하는 건 그사이의 드발린이야. 하프가 없다고 여기서 기다리기만 할 수는 없어. 그 애가 내 목소리를 들어 준다면, 적어도 지금 무슨 일이 일어나고 있는지는 물을 수 있을 거야."},{"k":"line","id":"PRO_M03K_단장실_023","speaker":"진","text":"눈물도 하프도 없습니다. 정화가 가능해졌다고 판단한 건 아니라는 걸 모두 알고 출발해야 합니다. 현장에서 후퇴를 결정하면 따라 주시겠습니까?"},{"k":"line","id":"PRO_M03K_단장실_024","speaker":"벤티","text":"응. 네가 데려간 사람들을 지켜야 한다는 건 알아. 그래도 한 번은 이름을 불러 주고 싶어. 다들 그 애를 쓰러뜨릴 방법만 말하기 전에."},{"k":"line","id":"PRO_M03K_단장실_025","speaker":"","text":"진의 시선이 잠깐 부드러워졌다. 그녀는 책상 끝의 보고서를 밀어 빈자리를 만들고, 상자 대신 지도를 놓았다."},{"k":"line","id":"PRO_M03K_단장실_026","speaker":"벤티","text":"그리고 너한테도 부탁이 있어. 드발린에 대해 기억하는 게 있어도, 그 애를 만났을 땐 내가 먼저 말할 기회를 줘."},{"k":"line","id":"PRO_M03K_단장실_027","speaker":"나","text":"그래. 내 기억은 최근 성적이 안 좋아서, 어차피 먼저 나설 생각 없었어."},{"k":"line","id":"PRO_M03K_단장실_028","speaker":"벤티","text":"그런 뜻으로 말한 건 아닌데. …고마워."},{"k":"line","id":"PRO_M03K_단장실_029","speaker":"진","text":"기사단 인원만으로는 폐허까지 길을 열기 어렵습니다. 길드에 협조를 요청하겠습니다. 제가 동행하고, 케이아는 성 안의 경계와 조사를 맡아 줘."},{"k":"line","id":"PRO_M03K_단장실_030","speaker":"케이아","text":"알겠습니다, 단장 대행님. 돌아오셨을 때 보고서 더미가 너무 높지 않게 해 보죠. 엠버, 바깥 상황도 보내 줘."},{"k":"line","id":"PRO_M03K_단장실_031","speaker":"엠버","text":"네, 케이아 선배. 돌아오는 길까지 확인해 둘게요."},{"k":"line","id":"PRO_M03K_단장실_032","speaker":"케이아","text":"참, 자네. 도움을 드리겠다는 말은 이렇게 조심해서 해야 해. 방금 단장 대행님이 스스로 일을 하나 더 맡으신 거 봤지?"},{"k":"line","id":"PRO_M03K_단장실_033","speaker":"나","text":"조언이 한 박자 늦었네요. 저는 이미 사흘 전에 돕겠다고 했어요."},{"k":"line","id":"PRO_M03K_단장실_034","speaker":"케이아","text":"그럼 돌아와서 얼마나 늘어났는지 비교나 하지. 서류에 적을 수 없는 이야기면 더 좋고."},{"k":"line","id":"PRO_M03K_길드_001","speaker":"","text":"길드 접수처에는 임시로 닫힌 길이 표시된 종이가 붙어 있었다. 캐서린은 진의 요청서를 읽은 뒤, 평소 의뢰를 놓는 칸과 다른 자리에 내려놓았다."},{"k":"line","id":"PRO_M03K_길드_002","speaker":"캐서린","text":"별과 심연을 향해! 지원 요청이구나. 목적지는 바람 드래곤의 폐허, 임무는 접근로 확보와 현장 지원…. 드발린을 처치하는 의뢰는 아닌 거지?"},{"k":"line","id":"PRO_M03K_길드_003","speaker":"나","text":"아니야. 만나서 확인할 게 있어. 위험한 건 숨기지 말아 줘. 내가 안전을 보장할 수는 없으니까."},{"k":"line","id":"PRO_M03K_길드_004","speaker":"캐서린","text":"그 조건대로 안내할게. 위험 구역 경험이 있는 모험가들에게 먼저 물어볼 거야. 지원할지는 각자가 정해."},{"k":"line","id":"PRO_M03K_길드_005","speaker":"","text":"지원자는 한꺼번에 모이지 않았다. 지도를 펴 보는 사람, 들것을 챙기는 사람, 요청서를 읽고 돌려주는 사람. 지도를 보던 모험가 하나가 물었다. 용이 덤비면 어떻게 하느냐고. 죽이지 말라는 조건 때문에 자기 목숨을 걸어야 하느냐고."},{"k":"line","id":"PRO_M03K_길드_006","speaker":"진","text":"몸을 지키기 위한 대응을 막지는 않겠습니다. 접근이 어렵다고 판단하면 후퇴할 겁니다. 부탁드리는 건 제가 드발린과 마주할 때 뒤쪽 길을 지켜 주시는 일입니다."},{"k":"line","id":"PRO_M03K_길드_007","speaker":"","text":"모험가는 잠시 진을 보다가, 자기 지도에서 빠진 길을 손가락으로 짚었다. 그 길이 무너졌다는 말을 들었다고 했다. 처음 듣는 이야기였다."},{"k":"line","id":"PRO_M03K_길드_008","speaker":"나","text":"저 사람 지도, 우리 거랑 다른데. 같이 안 가더라도 길 얘기는 듣고 싶어. 사람만 모으면 되는 줄 알고 서둘렀네."},{"k":"line","id":"PRO_M03K_길드_009","speaker":"캐서린","text":"응. 다른 모험가들 지도와도 비교해 보자. 의뢰를 맡겠다는 뜻으로 받지는 않을 테니 가서 물어봐."},{"k":"line","id":"PRO_M03K_길드_010","speaker":"벤티","text":"나도 들어야겠네. 벌써 첫 소절은 떠올렸는데, 길을 잘못 들어 노래를 중단할 수는 없잖아."},{"k":"choice","group":"G_PRO_M03K_길드_011","options":[{"label":"그 노래, 출발하기도 전에 쓰고 있었어? 제목부터 비장하면 좀 부담스러운데.","id":"PRO_M03K_길드_012","items":[{"k":"line","id":"PRO_M03K_길드_013","speaker":"벤티","text":"아직 제목은 없어. 자꾸 앞부분만 떠올라서. 끝을 같이 보고 나면 네가 하나 골라 줘도 좋고."},{"k":"line","id":"PRO_M03K_길드_014","speaker":"엠버","text":"그러면 무사히 돌아오는 걸로 끝내자. 제목은 그다음에 싸워도 되잖아. 난 노래보다 먼저 배고파질 것 같지만!"},{"k":"line","id":"PRO_M03K_길드_015","speaker":"나","text":"그럼 제목은 「돌아와서 밥」으로 하자."},{"k":"line","id":"PRO_M03K_길드_016","speaker":"벤티","text":"…후보에 넣어 둘게."}]},{"label":"내가 맡을 일부터 정해 줘. 뒤에 따라오라고만 하면 뭘 들고 어디까지 가야 하는지도 모르잖아.","id":"PRO_M03K_길드_017","items":[{"k":"line","id":"PRO_M03K_길드_018","speaker":"엠버","text":"그럼 넌 뒤쪽 인원하고 물품을 확인해 줘. 캐서린이 말한 숫자 세기, 이번엔 정말 중요하거든. 앞은 내가 볼게."},{"k":"line","id":"PRO_M03K_길드_019","speaker":"나","text":"숫자 세기. 좋아. 그건 자신 있어."},{"k":"line","id":"PRO_M03K_길드_020","speaker":"벤티","text":"나도 세어 줘. 가끔 노래에 섞여서 대답할지도 모르지만."},{"k":"line","id":"PRO_M03K_길드_021","speaker":"엠버","text":"그러니까 그걸 하지 말라는 거야!"}]}]},{"k":"keep","id":"ISK_M03_K_040","text":"성문 밖에서 마지막으로 인원을 셌다. 일행이 출발했다. 뒤에서는 수레 바퀴 소리, 앞에서는 엠버가 풀숲을 살피는 소리. 멀리 보이는 폐허는 한참을 걸어도 쉽게 가까워지지 않았다."},{"k":"line","id":"PRO_M03K_폐허로_001","speaker":"","text":"성벽 그림자가 등 뒤로 멀어지자 엠버가 대열 사이로 돌아왔다. 명단을 쥔 손을 보고 그녀가 웃었다."},{"k":"line","id":"PRO_M03K_폐허로_002","speaker":"엠버","text":"너 지금 사람 이름 외우는 게 아니라 종이로 검 만들고 있는 것 같은데. 그렇게 꽉 쥐면 나중에 읽지도 못해."},{"k":"line","id":"PRO_M03K_폐허로_003","speaker":"나","text":"이름 잘못 불렀다가 모르는 사람 하나 더 데려오면 어떡해. 아까부터 한 줄이 자꾸 두 줄로 보여."},{"k":"line","id":"PRO_M03K_폐허로_004","speaker":"벤티","text":"한 명이 두 명으로 보이면 합창단에는 좋은 재능인데. 출석 확인엔 좀 곤란하겠다."},{"k":"line","id":"PRO_M03K_폐허로_005","speaker":"엠버","text":"벤티, 놀리지만 말고 네 이름 부르면 먼저 대답해. 아까는 노래에 섞어서 대답해서 이 사람이 두 번 셌단 말이야."},{"k":"line","id":"PRO_M03K_폐허로_006","speaker":"벤티","text":"아, 그랬어? 다음엔 아주 평범하게 할게. 여기 있어."},{"k":"line","id":"PRO_M03K_폐허로_007","speaker":"","text":"평범한 대답을 듣고서야 명단의 표시 하나가 제자리를 찾았다. 엠버가 앞으로 뛰어가다가, 갑자기 몸을 낮췄다."},{"k":"line","id":"PRO_M03K_폐허로_008","speaker":"엠버","text":"길 왼쪽에 마물! 뒤쪽 사람들, 바위 안으로! 내가 시선을 돌릴게!"},{"k":"combat","id":"PRO_M03K_폐허로_009","group":"EG_MOND_HILI_ELITE","text":"폐허로 가는 길목을 막은 츄츄족 무리. 수레와 뒤쪽 사람들을 지키며 길을 연다."},{"k":"line","id":"PRO_M03K_폐허로_010","speaker":"","text":"마지막 녀석이 쓰러지자 손이 밧줄을 놓고도 당기는 모양으로 굳어 있었다."},{"k":"line","id":"PRO_M03K_폐허로_011","speaker":"나","text":"아까 「왼쪽으로」라고 한 거, 나한테 한 말이었어? 난 계속 수레 왼쪽만 보고 있었는데."},{"k":"line","id":"PRO_M03K_폐허로_012","speaker":"엠버","text":"내 왼쪽! 아… 네 쪽에서는 반대였겠다. 다음에는 바위나 나무를 짚어 줄게. 너도 못 알아들으면 바로 다시 물어봐."},{"k":"line","id":"PRO_M03K_폐허로_013","speaker":"나","text":"물어보고 싶었는데 창이 먼저 왔어. 다음엔 「어느 왼쪽」부터 크게 말할게."},{"k":"line","id":"PRO_M03K_폐허로_014","speaker":"엠버","text":"손 펴 봐. 짐 들라는 게 아니고, 손가락이 붙어 버린 것 같아서."},{"k":"line","id":"PRO_M03K_폐허로_015","speaker":"","text":"엠버가 자기 손을 펴 보이며 기다렸다. 따라 했다. 뒤에서 이름 하나를 불렀다. 수레 아래 빠진 물통을 꺼내던 모험가가 손을 들었다."},{"k":"line","id":"PRO_M03K_폐허로_016","speaker":"진","text":"확인했습니다. 모두 모였군요. 폐허의 바람이 가까워졌습니다. 벤티 씨?"},{"k":"line","id":"PRO_M03K_폐허로_017","speaker":"벤티","text":"여기서부터는 내 뒤로 와. 흩어지면 목소리가 닿지 않을 거야."},{"k":"line","id":"PRO_M03K_폐허로_018","speaker":"","text":"폐허를 둘러싼 바람 앞에서 대열이 멈췄다. 벤티는 악기를 들었다가 잠시 내려다봤다. 천공의 하프는 끝내 돌아오지 않았다. 그는 손을 내밀어 휘몰아치는 기류 사이에 좁은 틈을 만들었다. 진이 사람들을 재촉하고, 틈이 닫히기 전에 마지막 짐이 넘어왔다."},{"k":"keep","id":"ISK_M03_K_047","text":"바람 너머에는 지붕 없는 건물과 끊어진 계단들이 겹쳐 있었다. 높은 탑 둘레를 돌던 먼지가 잠깐 걷히자 오래된 장치가 드러났다. 알고 있는 장치다. 화면에서는 빛을 세 번 돌려놓으면 끝났다. 여기서는 그 세 번이 전부 계단과 절벽이었다."},{"k":"line","id":"PRO_M03K_폐허_001","speaker":"엠버","text":"위쪽 길은 이어져 있어요. 하지만 한 번에 올라가면 좁아요. 장치를 확인할 사람부터 가요."},{"k":"line","id":"PRO_M03K_폐허_002","speaker":"벤티","text":"저 빛을 제자리로 돌려놓으면 가운데로 갈 수 있을 거야. 드발린을 부를 자리는 그곳이면 되겠어."},{"k":"line","id":"PRO_M03K_폐허_003","speaker":"","text":"첫 장치 아래에는 무너진 돌이 쌓여 있었다. 엠버가 위에서 가리키는 곳이 아래에서는 돌기둥에 가려 보이지 않았다. 같은 기둥을 두 번 돌았다."},{"k":"line","id":"PRO_M03K_폐허_004","speaker":"나","text":"잠깐, 엠버. 네 손은 보이는데 네가 가리키는 건 안 보여. 여기서 더 오른쪽으로 가면 발밑이 없어져."},{"k":"line","id":"PRO_M03K_폐허_005","speaker":"엠버","text":"그쪽 말고… 아, 또 내 쪽을 기준으로 말했네! 네 앞에 부러진 기둥 보여? 그 아래로 돌아가. 내가 내려갈게."},{"k":"line","id":"PRO_M03K_폐허_006","speaker":"벤티","text":"위에서 보면 가까운 길이 아래에서는 막혀 있기도 하지. 서두르다가 벽에 인사하게 되면 노래로 변명해 주기는 어려워."},{"k":"line","id":"PRO_M03K_폐허_007","speaker":"나","text":"벽에는 이미 두 번 인사했어. 다음에 이 지도 그릴 사람은 높낮이도 좀 넣어 줬으면 좋겠다."},{"k":"line","id":"PRO_M03K_폐허_008","speaker":"","text":"빛이 자리를 찾자 장치가 낮게 울렸다. 소리에 반응한 마물들이 잔해에서 일어났고, 진이 앞을 막는 사이 모험가들이 양옆으로 벌어졌다. 장치를 보고 있다가 엠버에게 팔을 붙잡혀 뒤로 끌려났다."},{"k":"line","id":"PRO_M03K_폐허_009","speaker":"엠버","text":"네가 장치 대신 맞을 필요는 없어! 켜진 건 확인했어. 저쪽 사람들 따라가."},{"k":"line","id":"PRO_M03K_폐허_010","speaker":"","text":"두 번째 장치로 가는 계단은 중간이 끊겨 있었다. 바로 위에 보이는 목적지를 두고 아래층까지 돌아 내려갔다. 쉴 때마다 앞 장치의 빛을 찾아봤다. 멀어졌다가 다른 틈에서 다시 보이는 빛이, 길을 잃지 않았다는 표시 같았다."},{"k":"choice","group":"G_PRO_M03K_폐허_011","options":[{"label":"벤티, 여기 예전엔 어떤 곳이었어? 계단 모서리가 닳은 걸 보면 사람이 살았던 것 같은데.","id":"PRO_M03K_폐허_012","items":[{"k":"line","id":"PRO_M03K_폐허_013","speaker":"벤티","text":"사람들이 오가던 곳이었지. 지금 우리처럼 어디로 가야 하는지 몰라서 두 번 도는 사람도 있었을 거야. 이 벽이 처음부터 폐허였던 건 아니니까."},{"k":"line","id":"PRO_M03K_폐허_014","speaker":"나","text":"그 사람들도 벽에 인사했을까."},{"k":"line","id":"PRO_M03K_폐허_015","speaker":"벤티","text":"아마. 그리고 아마 그 사람들도 그걸 농담으로 넘겼을 거야."}]},{"label":"벤티는 안 힘들어? 계속 웃고 있어서 잘 모르겠어.","id":"PRO_M03K_폐허_016","items":[{"k":"line","id":"PRO_M03K_폐허_017","speaker":"벤티","text":"나도 돌아가는 길을 생각하고 있어. 오늘은 데려오고 싶은 친구가 한 명 더 있으니까. 그 애가 우리 옆을 걸을 수는 없겠지만, 적어도 같은 방향으로 가면 좋겠네."},{"k":"line","id":"PRO_M03K_폐허_018","speaker":"","text":"그 말에 대답할 농담이 없었다. 물통을 넘겨줬다."}]}]},{"k":"line","id":"PRO_M03K_폐허_019","speaker":"진","text":"돌이 많이 약해졌습니다. 가장자리는 피해 주세요. 마지막 장치는 저 위입니다."},{"k":"line","id":"PRO_M03K_폐허_020","speaker":"","text":"마지막 빛을 돌려놓자 흩어져 있던 장치들의 울림이 하나로 겹쳤다. 돌아 내려갔던 계단과 싸웠던 통로가 높은 곳에서 한눈에 들어왔다. 모두의 신발이 흰 먼지에 덮여 있었다. 아무도 환호하지 않았다. 벤티가 한 걸음 앞으로 나서자 길이 비었다."},{"k":"line","id":"PRO_M03K_폐허_021","speaker":"진","text":"후방과 연락은 이어져 있습니다. 돌아갈 길도 확보했습니다. 벤티 씨, 준비되셨나요?"},{"k":"line","id":"PRO_M03K_폐허_022","speaker":"벤티","text":"응. 다들 조금만 뒤로 물러나 줘. 내 친구가 낯선 얼굴을 보고 놀라지 않게."},{"k":"line","id":"PRO_M03K_폐허_023","speaker":"","text":"탑의 가장자리에서 한 걸음 물러섰다. 여기까지 오면 무언가 달라질 거라고 생각했다. 하프를 잃고 눈물을 정화하지 못했어도, 적어도 드발린은 만나게 될 거라고."},{"k":"choice","group":"G_PRO_M03K_폐허_024","options":[{"label":"드발린한테 직접 물어볼 수 있으면 좋겠네. 이번엔 내가 기억하는 답 말고.","id":"PRO_M03K_폐허_025","items":[{"k":"line","id":"PRO_M03K_폐허_026","speaker":"벤티","text":"나도 듣고 싶어. 그 애가 지금 어떤 말을 하고 싶은지."}]},{"label":"뭐라고 할 거야? 오랜만에 만나는 친구한테.","id":"PRO_M03K_폐허_027","items":[{"k":"line","id":"PRO_M03K_폐허_028","speaker":"벤티","text":"처음에는 뭐라고 할지 많이 생각했는데, 막상 여기까지 오니까 이름밖에 안 떠오르네. 그래도 내 이름보다 자기 이름을 먼저 들려주는 게 좋겠지."},{"k":"line","id":"PRO_M03K_폐허_029","speaker":"나","text":"응. 대답하면 그다음 말을 생각하자. 모르는 건 물어보기로 했잖아."}]}]},{"k":"line","id":"PRO_M03K_폐허_030","speaker":"","text":"벤티는 악기의 줄에 손을 얹고도 바로 연주하지 않았다. 길드 앞에서 노래 제목을 고르라던 얼굴이 잠깐 떠올랐다. 지금 벤티는 관객을 향해 서 있지 않았다. 엠버는 활을 내리고, 진은 앞으로 나가려던 모험가를 손짓으로 멈췄다. 발소리가 사라지자 탑 위에는 바람과 첫 음을 기다리는 침묵만 남았다."},{"k":"line","id":"PRO_M03K_폐허_031","speaker":"","text":"벤티가 하늘을 향해 드발린의 이름을 불렀다."},{"k":"line","id":"PRO_M03K_폐허_032","speaker":"","text":"무너진 탑을 감싸던 바람이 길게 울고, 구름 위에 커다란 그림자가 비쳤다. 엠버가 먼저 고개를 들었다."},{"k":"line","id":"PRO_M03K_폐허_033","speaker":"","text":"날개가 움직이지 않았다."},{"k":"line","id":"PRO_M03K_폐허_034","speaker":"엠버","text":"물러나요! 모두 탑 안쪽으로!"},{"k":"line","id":"PRO_M03K_폐허_035","speaker":"","text":"거대한 몸이 하늘에서 떨어져 광장을 짓눌렀다. 돌바닥이 갈라지고 먼지가 얼굴을 덮쳤다. 진이 앞을 막아서는 동안 기둥 뒤로 밀려났다. 돌조각이 굴러가는 소리가 잦아들어도, 날개가 바닥을 긁는 소리는 나지 않았다."},{"k":"line","id":"PRO_M03K_폐허_036","speaker":"","text":"드발린의 목이 무너진 돌 위에 늘어져 있었다. 푸른 비늘 사이로 오가던 빛도, 가까이 있기만 해도 몸을 밀어내던 숨결도 없었다."},{"k":"line","id":"PRO_M03K_폐허_037","speaker":"","text":"알고 있는 이야기의 어디에도 이 장면은 없었다."},{"k":"line","id":"PRO_M03K_폐허_038","speaker":"","text":"벤티의 손끝에서 다음 음이 나오지 않았다."},{"k":"keep","id":"ISK_M03_K_060","text":"광장에 무거운 정적이 내려앉는다."}],"edits":[]},{"id":"ISK_M04_AA","entry":"ISK_M04_AA_001","items":[{"k":"keep","id":"ISK_M04_AA_001","text":"정화할 방법을 묻는 말에 대답이 돌아오기 전에, 머리 위에서 무언가 떨어졌다. 처음에는 무너진 탑의 잔해라고 생각했다. 그런데 바람에 벌어진 옷자락과 힘없이 늘어진 팔이 보였다. 사람이었다."},{"k":"line","id":"PRO_M04AA_떨어진_것_001","speaker":"엠버","text":"위에 사람! 드발린 쪽으로 떨어져요!"},{"k":"line","id":"PRO_M04AA_떨어진_것_002","speaker":"","text":"다이루크가 고개를 들어 궤적을 쫓았다. 벤티가 손을 뻗었지만 늦었다. 떨어진 몸이 드발린의 등 가까이에 부딪쳤고, 닿은 자리에서 어두운 빛이 퍼졌다. 용이 몸을 뒤틀자 사람의 형체는 날개 아래에 걸렸다가 잔해 사이로 미끄러져 내려갔다."},{"k":"line","id":"PRO_M04AA_떨어진_것_003","speaker":"","text":"처음 보는 얼굴이었다. 누구인지, 어디서 떨어졌는지 알 수 없었다. 다만 떨어진 사람이 살아 움직이지 않는다는 것은 알아볼 수 있었다. 그 몸이 닿은 자리에서 드발린의 울음이 터졌다."},{"k":"line","id":"PRO_M04AA_떨어진_것_004","speaker":"나","text":"방금 사람 맞죠? 내려가서 봐야… 드발린이 왜 저래? 닿자마자 저렇게 된 거예요?"},{"k":"line","id":"PRO_M04AA_떨어진_것_005","speaker":"진","text":"접촉한 뒤에 반응이 시작됐습니다. 하지만 지금 앞으로 나가면 안 됩니다. 엠버, 잔해 아래로 접근할 길이 있는지 봐 줘. 무리해서 들어가지는 마."},{"k":"line","id":"PRO_M04AA_떨어진_것_006","speaker":"벤티","text":"드발린! 움직이지 말라는 게 아니야, 여기 사람들을 밟지 않게 고개를 이쪽으로 돌려 줘. 나를 봐. 조금만…."},{"k":"line","id":"PRO_M04AA_떨어진_것_007","speaker":"","text":"드발린이 앞발을 들었다가 내려찍었다. 벤티의 말은 포효에 묻혔다. 비늘 틈에서 번진 검붉은 흔적이 한 번 부풀었다가 떨어져 나갔다. 손에 남은 등줄기의 감촉이 떠올랐다. 내가 매달렸을 때와는 다른 반응이었다."},{"k":"line","id":"PRO_M04AA_떨어진_것_008","speaker":"다이루크","text":"지금은 다가갈 수 없어. 용을 물러서게 해서 공간부터 만들어야 한다. 진, 사람들을 뒤로 빼."},{"k":"line","id":"PRO_M04AA_떨어진_것_009","speaker":"엠버","text":"아래쪽 길은 무너졌어요! 저 사람에게 가려면 드발린 앞을 가로질러야 해요."},{"k":"line","id":"PRO_M04AA_떨어진_것_010","speaker":"벤티","text":"잠깐. 떨어져 나오는 걸 봐 줘. 저건 그 애 몸의 일부가 아니야. 안쪽에 붙어 있던 오염이 흔들리고 있어. 아까 하프 앞에서는 없었던 반응이야."},{"k":"line","id":"PRO_M04AA_떨어진_것_011","speaker":"나","text":"좋아지고 있는데 저렇게 아픈 거야? 그러면 막아야 하는지 기다려야 하는지도 모르겠잖아!"},{"k":"line","id":"PRO_M04AA_떨어진_것_012","speaker":"벤티","text":"나도 편안하게 끝날 거라고는 말할 수 없어. 하지만 저 반응을 끊으려고 무작정 베어서는 안 돼. 그 애가 우리를 공격하는 동안에도 오염이 떨어질 틈을 지켜야 해."},{"k":"line","id":"PRO_M04AA_떨어진_것_013","speaker":"진","text":"공격에 대응하되 목적은 드발린을 죽이는 것이 아니다. 움직임을 제압하고 사람들을 지킨다. 벤티 씨, 변화가 보이면 바로 알려 주세요."},{"k":"line","id":"PRO_M04AA_떨어진_것_014","speaker":"","text":"드발린의 몸 아래를 다시 봤다. 움직이지 않는 팔이 잠깐 보였다가 날개의 그림자에 가려졌다. 당장 달려가면 구할 수 있다는 장면은 아니었다. 그걸 받아들이기도 전에 용의 시선이 이쪽으로 돌아왔다."},{"k":"choice","group":"G_PRO_M04AA_떨어진_것_015","options":[{"label":"알겠어. 내가 움직이면 어디로 가는지부터 외칠게. 아까처럼 내가 어디 있는지도 모른 채 싸우게 두지는 않을게.","id":"PRO_M04AA_떨어진_것_016","items":[{"k":"line","id":"PRO_M04AA_떨어진_것_017","speaker":"엠버","text":"응. 이번에는 네 목소리가 들려. 내가 옮겨야 할 자리를 알려 줄게. 혼자 용 쪽으로 뛰지만 않으면 돼."},{"k":"line","id":"PRO_M04AA_떨어진_것_018","speaker":"나","text":"그건 하루에 한 번만 하는 거야. 오늘 할당량 다 썼어."}]},{"label":"나 무기 쥐는 법 어제 배웠는데. 뒤에서 돌 던지는 역할은 없어?","id":"PRO_M04AA_떨어진_것_019","items":[{"k":"line","id":"PRO_M04AA_떨어진_것_020","speaker":"엠버","text":"있어. 내 옆에서 「저기!」라고 외치는 역할. 그거 진짜 중요해. 눈이 두 쌍이 되니까."},{"k":"line","id":"PRO_M04AA_떨어진_것_021","speaker":"나","text":"그건 할 수 있어. 소리치는 건 아까 하늘에서 충분히 연습했거든."}]}]},{"k":"keep","id":"ISK_M04_AA_018","text":"엠버가 활을 들었다. 진과 다이루크가 무너진 회랑 양쪽으로 벌어지고, 벤티는 용의 얼굴이 보이는 곳에 남았다. 조금 전까지 공격을 멈추게 하려던 사람들이 이제는 정화를 끝낼 시간을 벌기 위해 맞서야 했다."},{"k":"keep","id":"ISK_M04_AA_COMBAT"},{"k":"line","id":"PRO_M04AA_멈춘_숨_001","speaker":"","text":"드발린이 마지막 공세를 멈췄다. 몸을 감싸던 어두운 흔적이 비늘에서 떨어져 나와 바람 속에서 흩어졌다. 이번에는 다른 흔적이 그 자리를 채우지 않았다. 용은 앞발로 몸을 지탱하고 길게 숨을 내쉬었다."},{"k":"line","id":"PRO_M04AA_멈춘_숨_002","speaker":"벤티","text":"멈췄어. 오염이 더 붙어 있지 않아. 드발린, 이제 내 목소리가 들리지?"},{"k":"line","id":"PRO_M04AA_멈춘_숨_003","speaker":"","text":"벤티는 하프를 들지 않았다. 빈손으로 한 걸음 다가갔다가 드발린이 눈을 뜨자 멈춰 섰다. 누구도 더 가까이 가라고 재촉하지 않았다."},{"k":"line","id":"PRO_M04AA_멈춘_숨_004","speaker":"드발린","text":"…바르바토스. 네 목소리였구나. 계속 들리고 있었는데, 같은 목소리라고 생각할 수가 없었다."},{"k":"line","id":"PRO_M04AA_멈춘_숨_005","speaker":"벤티","text":"응, 나야. 이번에는 네가 대답할 때까지 듣고 있을게. 급하게 다시 날아오르지 않아도 돼."},{"k":"line","id":"PRO_M04AA_멈춘_숨_006","speaker":"드발린","text":"몸을 움직일 때마다 아팠다. 멈추면 고통이 더 가까워졌고, 날면 어디든 벗어날 수 있을 것 같았지. 그런데 어느 쪽으로 가도 그 소리가 따라왔다."},{"k":"line","id":"PRO_M04AA_멈춘_숨_007","speaker":"","text":"무기를 조금 내렸다. 등 위에서는 드발린의 숨이 얼마나 거칠었는지만 알 수 있었다. 그 숨을 쉬던 존재가 겪은 일을 이제야 말로 듣고 있었다. 엠버도 활시위를 놓고 진을 봤다."},{"k":"line","id":"PRO_M04AA_멈춘_숨_008","speaker":"진","text":"공격 중지. 전원, 현재 위치에서 대기한다. 부상자는 뒤쪽에서 확인하겠다. 드발린에게 접근하지 말고 거리를 유지해."},{"k":"line","id":"PRO_M04AA_멈춘_숨_009","speaker":"다이루크","text":"아직 움직일 수 있는 사람부터 길을 비워. 전투가 끝났다고 부서진 바닥까지 돌아오는 건 아니니까."},{"k":"line","id":"PRO_M04AA_멈춘_숨_010","speaker":"나","text":"지금은… 괜찮은 거야? 아까도 조용해졌다가 바로 다시 움직여서, 그냥 끝났다고 생각하기가 겁나네."},{"k":"line","id":"PRO_M04AA_멈춘_숨_011","speaker":"벤티","text":"몸에 남은 오염은 완전히 사라졌어. 그건 분명히 말할 수 있어. 다만 드발린이 편하게 숨을 고를 때까지 조금만 기다려 주자. 오랫동안 자기 몸조차 뜻대로 움직이지 못했으니까."},{"k":"line","id":"PRO_M04AA_멈춘_숨_012","speaker":"드발린","text":"네가 내 등에 있었던 인간인가. 바람 속에서도 끊임없이 누군가를 부르더군. 내가 조금만 더 몸을 틀었다면 너는 떨어졌을 것이다."},{"k":"choice","group":"G_PRO_M04AA_멈춘_숨_013","options":[{"label":"응, 등에 매달려 있던 그 사람이야. 태워 줘서 고맙다고 하면 네가 허락한 것처럼 되겠지? 그럼 안 떨어뜨려 줘서 고맙다고 할게.","id":"PRO_M04AA_멈춘_숨_014","items":[{"k":"line","id":"PRO_M04AA_멈춘_숨_015","speaker":"드발린","text":"널 지키려고 자세를 고른 것은 아니다. 그럴 여유도 없었다. 그래도 살아서 그 이야기를 하고 있으니 다행이군."},{"k":"line","id":"PRO_M04AA_멈춘_숨_016","speaker":"나","text":"나도 이렇게 땅에서 인사하는 쪽이 훨씬 좋네. 다음엔 땅에서만 하자."}]},{"label":"그래. 아까 비명 지른 것도 나야. 미안, 귀 아팠지?","id":"PRO_M04AA_멈춘_숨_017","items":[{"k":"line","id":"PRO_M04AA_멈춘_숨_018","speaker":"드발린","text":"네 비명보다 큰 소리가 내 안에 있었다. 들리지 않았다."},{"k":"line","id":"PRO_M04AA_멈춘_숨_019","speaker":"나","text":"…그건 다행인데 조금 섭섭하네. 꽤 열심히 질렀는데."}]}]},{"k":"line","id":"PRO_M04AA_멈춘_숨_020","speaker":"엠버","text":"둘 다 살아서 얘기하고 있다는 게 지금은 제일 다행이에요. 저 사람에게 왜 올라갔느냐고 묻는 건 제가 이미 했어요. 답도 들었고요."},{"k":"line","id":"PRO_M04AA_멈춘_숨_021","speaker":"","text":"엠버를 보자 그녀는 이번에는 작게 웃었다. 아까의 화가 없었던 일은 아니었다. 다만 그 말을 계속 붙잡고 있어야 할 만큼 두렵지는 않아진 얼굴이었다."},{"k":"line","id":"PRO_M04AA_사라진_사람_001","speaker":"","text":"다이루크가 용의 옆을 돌아 잔해 아래를 확인했다. 조금 전까지 사람의 몸이 걸려 있던 곳이었다. 그는 멈춰 서서 다른 틈도 살피고, 가까이 오는 기사를 손짓으로 불렀다."},{"k":"line","id":"PRO_M04AA_사라진_사람_002","speaker":"다이루크","text":"시신이 없어. 전투 중에 누가 옮겼나?"},{"k":"line","id":"PRO_M04AA_사라진_사람_003","speaker":"진","text":"구조에 들어간 인원은 없습니다. 엠버가 확인한 뒤에는 모두 전투 위치를 지켰어요. 다른 쪽으로 밀려 내려간 흔적은?"},{"k":"line","id":"PRO_M04AA_사라진_사람_004","speaker":"다이루크","text":"지금 보이는 곳에는 없다. 멀리 굴러갔다면 이어질 자국이 있어야 할 텐데, 그것도 없어."},{"k":"line","id":"PRO_M04AA_사라진_사람_005","speaker":"나","text":"분명히 여기야. 날개 아래에 팔이 보였어. 엠버, 네가 본 자리도 이쪽이지?"},{"k":"line","id":"PRO_M04AA_사라진_사람_006","speaker":"엠버","text":"응, 이쪽 맞아. 나도 날개 아래로 미끄러지는 걸 봤어. 아래쪽 틈을 다시 볼게. 너는 여기서 위치를 짚어 줘."},{"k":"line","id":"PRO_M04AA_사라진_사람_007","speaker":"","text":"두어 걸음 더 내려갔다가 멈췄다. 시신이 사라졌다고 해서 떨어진 순간까지 없었던 일이 되지는 않았다. 벤티가 가까이 와서 돌 사이를 살폈지만 무언가를 찾아냈다고 말하지는 않았다."},{"k":"line","id":"PRO_M04AA_사라진_사람_008","speaker":"벤티","text":"그 사람이 드발린에게 닿은 뒤에 변화가 시작됐어. 하지만 왜 그런 반응이 났는지, 지금 어디로 사라졌는지는 알 수 없어. 구했다고 말할 사람도 여기에는 없고."},{"k":"line","id":"PRO_M04AA_사라진_사람_009","speaker":"나","text":"드발린을 살렸으니까 잘됐다고만 하고 떠나면 안 될 것 같아. 저 사람은 이미 죽어 있었는데, 누구였는지도 모르잖아."},{"k":"line","id":"PRO_M04AA_사라진_사람_010","speaker":"진","text":"유해가 떨어진 위치와 접촉 뒤의 반응을 남기겠습니다. 수색도 계속하겠습니다. 드발린을 구한 일과 별개로, 그 사람이 누구였고 어떻게 이곳에 떨어졌는지는 알아내야 합니다."},{"k":"line","id":"PRO_M04AA_사라진_사람_011","speaker":"드발린","text":"나 역시 그 존재가 누구였는지는 말해 줄 수 없다. 닿았을 때 고통이 거세졌고, 그 뒤에 붙들고 있던 것이 갈라졌다. 그 사이의 기억은 끊겨 있다."},{"k":"keep","id":"ISK_M04_AA_047","text":"용의 대답을 들은 뒤에야 잔해에서 눈을 떼었다. 고통을 겪은 당사자에게도 빈틈이 남아 있었다. 모두가 원하는 답을 한 사람에게서 꺼낼 수는 없었다. 진은 수색을 맡을 인원에게 위치를 직접 가리켰다."},{"k":"line","id":"PRO_M04AA_바르바토스_001","speaker":"","text":"벤티는 드발린이 고개를 돌릴 수 있는 쪽으로 걸어갔다. 하프를 감싼 천은 여전히 어깨에 걸려 있었다. 용이 조금 전에 부른 이름이 머리에 남아 있었다."},{"k":"line","id":"PRO_M04AA_바르바토스_002","speaker":"나","text":"바르바토스라고 했지. 그게 네 이름이야? 성에서 사람들이 말하는 바람의 신도 그 이름이었던 것 같은데."},{"k":"line","id":"PRO_M04AA_바르바토스_003","speaker":"벤티","text":"응. 그 이름으로 나를 부르는 사람들이 있어. 드발린에게는 아주 오래전부터 그랬고. 네가 알던 벤티도 나야. 설명을 먼저 해 주지 못했네."},{"k":"choice","group":"G_PRO_M04AA_바르바토스_004","options":[{"label":"지금 놀랄 게 너무 많아서 어디부터 놀라야 할지 모르겠다. 그래서 용이 친구라고 할 때 그렇게 자연스러웠구나.","id":"PRO_M04AA_바르바토스_005","items":[{"k":"line","id":"PRO_M04AA_바르바토스_006","speaker":"벤티","text":"오래된 친구라는 말은 정말이었어. 네가 알던 벤티도 없어지는 건 아니고. 다음에 불러도 돌아볼 이름은 그쪽이니까."},{"k":"line","id":"PRO_M04AA_바르바토스_007","speaker":"나","text":"신한테 「어디 있었냐」고 따진 사람이 됐네, 나. 어제 일인데."},{"k":"line","id":"PRO_M04AA_바르바토스_008","speaker":"벤티","text":"그 질문은 신한테도 해야 하는 질문이었어. 취소하지 마."}]},{"label":"아니, 어제 나한테 물 얻어 마시던 사람이 신이라고? 다이루크, 알고 있었어?","id":"PRO_M04AA_바르바토스_009","items":[{"k":"line","id":"PRO_M04AA_바르바토스_010","speaker":"다이루크","text":"짐작은 했다. 묻지 않았을 뿐이야. 물은 신이라도 마셔야지."},{"k":"line","id":"PRO_M04AA_바르바토스_011","speaker":"벤티","text":"설명을 늦춘 건 미안해. 궁금한 건 물어봐. 오늘 못 다 한 이야기도 남아 있으니."}]}]},{"k":"line","id":"PRO_M04AA_바르바토스_012","speaker":"드발린","text":"바르바토스, 나는 네가 또 명령하러 온 줄 알았다. 몬드를 위해 해야 할 일이 남았으니 다시 싸우라고 말할 것이라고."},{"k":"line","id":"PRO_M04AA_바르바토스_013","speaker":"벤티","text":"지금 부탁하고 싶은 건 네가 어디로 가고 싶은지 말해 달라는 거야. 내가 듣고 싶은 답을 고를 필요는 없어. 몬드의 하늘을 지킨 시간만큼 네가 쉬어도 되는 하늘도 있어야 하잖아."},{"k":"line","id":"PRO_M04AA_바르바토스_014","speaker":"드발린","text":"멀리 가고 싶다. 몸이 아직 자유롭게 움직이는지, 저 소리가 정말 따라오지 않는지 확인하고 싶어. 혼자 날 수도 있겠지만… 네가 함께 와 주겠나?"},{"k":"line","id":"PRO_M04AA_바르바토스_015","speaker":"벤티","text":"응. 이번에는 네가 가는 방향으로 같이 가자. 노래는 네가 듣고 싶다고 할 때 부를게."},{"k":"line","id":"PRO_M04AA_바르바토스_016","speaker":"","text":"드발린이 목을 조금 낮췄다. 벤티는 그 움직임을 기다렸다가 다가갔다. 절벽에서 몸을 던진 순간이 떠올라 발끝을 내려다봤다. 이번에는 드발린이 단단히 버티고 서 있었다. 벤티가 오르는 동안 날개의 각도도 천천히 바꿨다."},{"k":"line","id":"PRO_M04AA_바르바토스_017","speaker":"진","text":"성에는 드발린이 정화되었고 당장의 공격 위험이 멎었다고 알리겠습니다. 사람들의 상처와 두려움이 하루에 사라지지는 않겠지만, 저도 이곳에서 확인한 사실을 전하겠어요."},{"k":"line","id":"PRO_M04AA_바르바토스_018","speaker":"드발린","text":"몬드 사람들이 나를 두려워하는 이유는 알고 있다. 그 두려움을 잊으라고 요구하지 않겠다. 오늘 무기를 멈춘 일은 기억하마."},{"k":"line","id":"PRO_M04AA_바르바토스_019","speaker":"다이루크","text":"그걸 기억한다면 돌아올 때 도시 위를 너무 낮게 날지는 마. 오늘 같은 그림자를 또 보면 설명보다 경보가 먼저 울릴 테니."},{"k":"line","id":"PRO_M04AA_바르바토스_020","speaker":"","text":"벤티가 가볍게 웃었다. 길 위에서 사람들을 안심시키려고 만들던 웃음과는 조금 달랐다. 드발린도 다이루크의 말에 화를 내지 않았다. 날개를 펼치기 전에, 그는 내가 있는 쪽으로 고개를 돌렸다."},{"k":"line","id":"PRO_M04AA_바르바토스_021","speaker":"드발린","text":"그리고 너. 다음에 나를 만나려거든 땅에서 먼저 불러라. 날개 위에서는 네 말이 잘 들리지 않는다."},{"k":"choice","group":"G_PRO_M04AA_바르바토스_022","options":[{"label":"그러려고. 다음에는 정말 이름부터 부를게. 대답하기 전에 날아가 버리지만 마.","id":"PRO_M04AA_바르바토스_023","items":[{"k":"line","id":"PRO_M04AA_바르바토스_024","speaker":"드발린","text":"들을 수 있는 곳에 있다면 대답하겠다. 오늘처럼 목숨을 걸고 내 등에 오를 필요는 없다."},{"k":"line","id":"PRO_M04AA_바르바토스_025","speaker":"엠버","text":"들었지? 나만 하는 말 아니야. 다음에 또 그러면 용한테도 혼나는 거야."}]},{"label":"나도 다시 올라탈 생각은 없어. 대신 멀쩡할 때 한 번쯤은 태워 달라고 부탁할 수는 있겠네.","id":"PRO_M04AA_바르바토스_026","items":[{"k":"line","id":"PRO_M04AA_바르바토스_027","speaker":"벤티","text":"벌써 다음 부탁을 생각할 힘이 돌아왔네. 그때는 드발린에게 먼저 물어봐. 이번처럼 허락보다 출발이 빠르면 나도 따라가기 힘드니까."},{"k":"line","id":"PRO_M04AA_바르바토스_028","speaker":"드발린","text":"그때의 바람을 보고 정하지. 오늘의 대답까지 네가 대신 정해 두지는 마라."}]}]},{"k":"keep","id":"ISK_M04_AA_069"},{"k":"line","id":"PRO_M04AA_바르바토스_029","speaker":"","text":"벤티는 마지막으로 나에게 손을 흔들었다. 하프와 눈물 꾸러미는 그가 가지고 있었다. 드발린이 날개를 움직이자 먼지가 일었지만, 이번에는 누구도 무기를 들지 않았다. 거대한 몸이 탑 위로 올라가고 벤티의 초록 망토가 햇빛 속에서 작아졌다."},{"k":"keep","id":"ISK_M04_AA_071","text":"엠버는 두 그림자가 폐허 위를 벗어날 때까지 고개를 들고 있었다. 나도 같은 방향을 봤다. 누군가 떠나는 모습을 보고도 당장 뒤쫓아야 한다고 생각하지 않아도 되는 순간이 처음으로 왔다."},{"k":"line","id":"PRO_M04AA_구슬_001","speaker":"","text":"용이 떠난 자리의 먼지가 걷히자 작은 반사가 눈에 들어왔다. 조금 전 시신이 있던 잔해 가까이에 수정구슬 하나가 놓여 있었다. 큰 돌에 가려져 있던 것인지, 언제부터 거기 있었는지는 알 수 없었다. 내가 멈춰 서자 엠버도 곁으로 왔다."},{"k":"line","id":"PRO_M04AA_구슬_002","speaker":"엠버","text":"또 뭔가 있어? 그 작은 건… 유리구슬 같기도 한데. 아까는 못 봤어."},{"k":"line","id":"PRO_M04AA_구슬_003","speaker":"나","text":"나도 못 봤어. 아까 사람이 떨어졌던 자리 근처잖아. 먼저 어디 있었는지 표시하자. 주워 놓고 나서 「어디서 나왔더라」 하고 서로 쳐다보면 곤란해."},{"k":"line","id":"PRO_M04AA_구슬_004","speaker":"다이루크","text":"그래. 다만 시신이 사라진 곳과 가깝다는 것만으로 둘이 이어진 일이라고 결론 내리지는 마. 구슬 주변에 다른 흔적이 없는지부터 보겠다."},{"k":"line","id":"PRO_M04AA_구슬_005","speaker":"진","text":"다른 사람들은 잠시 떨어져 주세요. 당신도 바로 손대실 필요는 없습니다. 현장을 살핀 뒤 보관 방법을 정해도 돼요."},{"k":"line","id":"PRO_M04AA_구슬_006","speaker":"","text":"구슬을 봤다. 조금 전까지 용의 숨소리로 가득했던 장소에서 그 작은 물건만 아무 일도 없었던 것처럼 조용했다. 집어 들면 더 많은 것을 알게 될지, 그냥 다음 질문을 손에 쥐게 될지 알 수 없었다."},{"k":"choice","group":"G_PRO_M04AA_구슬_007","options":[{"label":"천으로 감싸서 주워 보자. 그냥 놓고 가기에는 너무 신경 쓰여.","keep":"ISK_M04_AA_078","items":[{"k":"line","id":"PRO_M04AA_구슬_008","speaker":"","text":"펼친 천으로 구슬을 감싸 들어 올렸다. 손바닥보다 작은 무게가 얹혔다. 무언가를 보여 주거나 말을 거는 일은 없었다. 엠버가 손이 떨리지 않는지 살피고, 진이 발견된 자리를 확인했다."},{"k":"line","id":"PRO_M04AA_구슬_009","speaker":"엠버","text":"잡았네. 손에 이상한 느낌이 오면 바로 말해 줘. 난 이게 놓여 있던 자리를 기억해 둘게."},{"k":"line","id":"PRO_M04AA_구슬_010","speaker":"나","text":"이상한 느낌… 지금은 「차갑다」밖에 없어. 그건 돌이면 다 그렇겠지."}]},{"label":"안 주울래. 지금은 여기 두고, 조사할 사람들이 확인하게 하자.","keep":"ISK_M04_AA_081","items":[{"k":"line","id":"PRO_M04AA_구슬_011","speaker":"","text":"손을 거두고 돌아섰다. 몇 걸음 뒤 옷자락 안쪽에서 단단한 것이 몸에 닿았다. 주머니를 짚자 조금 전 바닥에 두고 온 것과 같은 크기의 둥근 물체가 잡혔다. 멈춰 선 나를 보고 엠버가 뒤를 돌아봤다. 바닥의 구슬은 사라져 있었다."},{"k":"line","id":"PRO_M04AA_구슬_012","speaker":"나","text":"나 안 집었어. 방금 너도 봤지? 손도 안 댔는데, 왜 내 주머니에 있어?"},{"k":"line","id":"PRO_M04AA_구슬_013","speaker":"엠버","text":"봤어. 네가 돌아서는 것까지 봤어. 진 단장, 이쪽 좀 봐 주세요. 저 물건이 옮겨진 걸 설명할 수가 없어요."},{"k":"line","id":"PRO_M04AA_구슬_014","speaker":"","text":"손바닥을 폈다. 구슬은 그 위에 놓여 있었다. 내가 고른 건 분명히 주워 가지 않는 쪽이었다. 결과만 바뀌어 있었다. 진도 다이루크도 내가 몰래 집어 들었다고 말하지 않았다. 그게 더 무서웠다."}]}]},{"k":"keep","id":"ISK_M04_AA_086"},{"k":"line","id":"PRO_M04AA_구슬_015","speaker":"진","text":"구슬이 발견된 자리와 당신께서 소지하게 된 경위는 모두 함께 확인했습니다. 우선 지금 상태로 보관해 주세요. 변화가 생기면 바로 알려 주시고요. 돌아가서 수색 기록과 함께 정리하겠습니다."},{"k":"line","id":"PRO_M04AA_구슬_016","speaker":"나","text":"그럼 돌아가서 설명할 때 세 분도 같이 계셔 주세요. 혼자 설명하다가 더 수상해지고 싶지는 않아요. 저 그런 데 재능이 있어서."},{"k":"line","id":"PRO_M04AA_구슬_017","speaker":"다이루크","text":"설명할 때 빠뜨리지 않으면 된다. 주워 들었든 원치 않게 가지게 됐든, 그 차이까지 네가 말할 수 있지. 구슬이 모든 질문의 답이라는 생각부터 하지는 마."},{"k":"line","id":"PRO_M04AA_구슬_018","speaker":"엠버","text":"돌아가면 앉아서 얘기하자. 처음에 어디로 가겠다고 했는지부터, 용 등에 왜 올라갔는지까지. 나 오늘 질문할 시간이 아주 많이 필요하거든."},{"k":"line","id":"PRO_M04AA_구슬_019","speaker":"나","text":"그건 각오하고 있어. 대신 걷는 동안에는 쉬운 질문부터 해 줘. 지금 다리가 아직도 탑 위에 있는 줄 아는 것 같아서."},{"k":"line","id":"PRO_M04AA_구슬_020","speaker":"엠버","text":"좋아. 첫 질문. 혼자 걸을 수 있어, 아니면 옆에 있어 줄까? 이건 잘 대답해야 해. 괜찮다고만 하면 내가 또 물을 거니까."},{"k":"choice","group":"G_PRO_M04AA_구슬_021","options":[{"label":"옆에 있어 줘. 걷는 건 할 수 있는데 다리가 멀쩡한 척까지는 못 하겠어. 오늘만 성문까지 나 좀 봐 줘.","id":"PRO_M04AA_구슬_022","items":[{"k":"line","id":"PRO_M04AA_구슬_023","speaker":"엠버","text":"합격. 또 어디로 새지만 마."},{"k":"line","id":"PRO_M04AA_구슬_024","speaker":"나","text":"샐 힘도 없어."}]},{"label":"혼자 걸을 수 있어. …라고 하면 또 물을 거지? 그럼 옆에 있어 줘.","id":"PRO_M04AA_구슬_025","items":[{"k":"line","id":"PRO_M04AA_구슬_026","speaker":"엠버","text":"두 번째 답으로 할게. 첫 번째 답은 못 들은 거야."}]}]},{"k":"line","id":"PRO_M04AA_구슬_027","speaker":"","text":"엠버는 더 놀리지 않고 걸음을 맞췄다. 진이 사람들을 모아 귀환 준비를 시작했고, 다이루크는 수색을 계속할 이들에게 방금 본 자리를 다시 알려 줬다. 하늘을 올려다봐야만 서로의 위치를 찾던 시간은 끝났다."},{"k":"line","id":"PRO_M04AA_구슬_028","speaker":"","text":"품 안의 구슬이 제자리에 있는지 한 번 확인했다. 누가 떨어뜨렸는지, 왜 남았는지는 알 수 없었다. 하지만 드발린을 죽이지 않고 돌려보냈다는 것과, 땅 위에서 함께 돌아갈 사람들이 있다는 것은 분명했다. 그 두 가지를 붙잡고 폐허의 계단을 내려갔다."},{"k":"keep","id":"ISK_M04_AA_END","text":"드발린은 완전히 정화되어 바르바토스와 떠났다. 수정구슬을 소지한 채 일행과 귀환을 준비한다."}],"edits":[],"pre":""},{"id":"ISK_M04_AB","entry":"ISK_M04_AB_001","items":[{"k":"keep","id":"ISK_M04_AB_001","text":"몬드에 남은 며칠 동안 본부에 들를 이유를 조금씩 바꿨다. 처음에는 회신이 왔는지 물으러 갔고, 다음에는 내 연락처가 제대로 남아 있는지 확인했다. 같은 답을 두 번 듣고 나서는 길드에서 가까운 일을 마친 뒤 돌아오는 길에 들렀다. 묻는 횟수를 줄였다고 기다리는 시간이 짧아지지는 않았다."},{"k":"line","id":"PRO_M04AB_기다림_001","speaker":"","text":"다이루크와는 짧은 확인을 여러 번 주고받았다. 길을 나서기 전에 짐끈이 걸리지 않는지 보는 일, 좁은 길에서 옆 사람이 지나갈 자리를 남기는 일, 돌아온 뒤 본 것을 처음부터 빠뜨리지 않고 말하는 일. 세상을 알게 된 건 아니었지만 매번 같은 실수에서 멈추지는 않게 됐다."},{"k":"line","id":"PRO_M04AB_기다림_002","speaker":"다이루크","text":"오늘은 네가 먼저 멈췄군. 앞에서 짐이 흔들리는 걸 봤나?"},{"k":"line","id":"PRO_M04AB_기다림_003","speaker":"나","text":"응. 저대로 지나가면 내 쪽 끈도 걸리겠다 싶어서. 처음에는 네가 왜 자꾸 뒤를 보는지 몰랐는데, 이제 내가 보는 쪽에서도 걸릴 게 보이네."},{"k":"line","id":"PRO_M04AB_기다림_004","speaker":"다이루크","text":"그렇다면 다음에는 멈췄다고 말해. 뒤에 있는 사람도 이유를 알아야 같은 자리에 쌓이지 않지."},{"k":"line","id":"PRO_M04AB_기다림_005","speaker":"나","text":"잠깐만. 방금 건 칭찬 맞지? 다음에 할 일은 할 테니까 잘했다는 말부터 챙기자. 예전에는 걸린 다음에야 멈췄어."},{"k":"line","id":"PRO_M04AB_기다림_006","speaker":"다이루크","text":"맞아. 그래서 다음 얘기를 하는 거다."},{"k":"line","id":"PRO_M04AB_기다림_007","speaker":"","text":"그 대답을 듣고 짐을 다시 들었다. 잘한다는 긴 말보다 다음 일을 함께 이야기한다는 사실이 더 오래 남았다. 하지만 본부의 문이 보이면 시선은 여전히 먼저 그쪽으로 갔다."},{"k":"choice","group":"G_PRO_M04AB_기다림_008","options":[{"label":"내가 매번 들르는 게 답을 빨리 오게 하지는 않는다는 건 알아. 그런데 안 들렀다가 그 사이에 소식이 왔을 것 같아서.","id":"PRO_M04AB_기다림_009","items":[{"k":"line","id":"PRO_M04AB_기다림_010","speaker":"다이루크","text":"가고 싶다면 들르자. 다만 소식이 없으면 오늘 확인은 거기까지다. 연락이 오면 전해 달라고 이미 부탁해 뒀어."}]},{"label":"엠버도 내 이름을 보겠지. 돌아왔을 때 내가 여기 있었다는 건 알 수 있으니까.","id":"PRO_M04AB_기다림_011","items":[{"k":"line","id":"PRO_M04AB_기다림_012","speaker":"다이루크","text":"그 종이는 내가 확인했다. 아직 맨 위에 있어."}]}]},{"k":"line","id":"PRO_M04AB_기다림_013","speaker":"","text":"그날도 본부 앞을 지났다. 접수대 앞에 모인 사람들의 목소리가 평소보다 낮았다. 누군가 안도한 얼굴로 숨을 내쉬었고, 다른 사람은 자세한 내용을 되물었다. 길드 쪽 게시판에는 막 붙인 공지가 바람에 들썩이고 있었다."},{"k":"line","id":"PRO_M04AB_기다림_014","speaker":"캐서린","text":"새로 도착한 소식을 보러 왔구나. 토벌대에서 드발린을 쓰러뜨렸다는 보고가 왔어. 성으로 돌아올 인원은 아직 정리 중이고, 개인별 귀환 소식은 따로 확인해야 해."},{"k":"line","id":"PRO_M04AB_기다림_015","speaker":"나","text":"드발린이… 죽었다는 거야? 물러났다는 게 아니라?"},{"k":"line","id":"PRO_M04AB_기다림_016","speaker":"캐서린","text":"보고에는 토벌이 끝났다고 적혀 있어. 지금 안내할 수 있는 건 그 내용이야. 네가 기다리던 사람들의 상태까지 그 말에 포함해서 알려 줄 수는 없어."},{"k":"line","id":"PRO_M04AB_기다림_017","speaker":"","text":"공지의 같은 줄을 다시 읽었다. 며칠 동안 바란 건 소식이 오는 일이었다. 막상 도착하자, 어떤 내용이 오기를 바랐는지 뒤늦게 알았다."},{"k":"line","id":"PRO_M04AB_기다림_018","speaker":"다이루크","text":"같이 가자. 여기서 서 있을 필요는 없어."},{"k":"line","id":"PRO_M04AB_기다림_019","speaker":"나","text":"벤티는 알고 있을까? 소식을 보내겠다고 했는데, 먼저 이런 공지를 보게 됐네."},{"k":"line","id":"PRO_M04AB_기다림_020","speaker":"다이루크","text":"그건 현장에 있었던 사람에게 들어야 한다. 우리가 절벽에서 실패한 뒤의 일까지 짐작으로 채울 수는 없어."},{"k":"line","id":"PRO_M04AB_기다림_021","speaker":"나","text":"내가 그때 더 따라갔으면 달라졌을까, 그런 생각이 제일 먼저 드는 게 좀 싫다. 어디로 갈지도 모르면서 따라가겠다고 했던 건데, 지금 와서 대단한 방법이 있었던 것처럼 생각하게 돼."},{"k":"line","id":"PRO_M04AB_기다림_022","speaker":"다이루크","text":"그때 네가 가진 방법은 지금도 우리가 알고 있는 그 방법뿐이다. 벤티의 노래가 닿지 않았고, 눈물은 정화되지 않았지. 뒤늦게 생긴 죄책감을 그때 없던 능력으로 바꾸지는 마."},{"k":"line","id":"PRO_M04AB_기다림_023","speaker":"","text":"다이루크는 공지에서 시선을 떼고 나를 봤다. 위로하려고 말을 부드럽게 고르는 얼굴은 아니었다. 그래서 나도 괜찮다고 대답하지 않았다."},{"k":"line","id":"PRO_M04AB_기다림_024","speaker":"나","text":"알겠어. 그래도 오늘은 좀 아쉬워할래. 구해 보겠다고 사당을 그렇게 돌아다녔는데, 마지막에 남은 말이 「토벌 완료」인 건 너무 허무하잖아."},{"k":"line","id":"PRO_M04AB_기다림_025","speaker":"다이루크","text":"아쉬울 수밖에 없지. 살리려고 찾아 나섰으니까. 다만 아직 끝나지 않은 일도 있다. 우리가 그 사당에서 본 시신들에 대해서는 아무 설명도 듣지 못했어."},{"k":"keep","id":"ISK_M04_AB_025","text":"그 일 때문에 두 사람에게 전달할 의뢰가 있어. 기사단과 길드가 함께 현장을 다시 확인하려고 해. 최초로 보고한 사람이 동행해 주면 좋겠다는 요청이 왔어."},{"k":"line","id":"PRO_M04AB_기다림_026","speaker":"","text":"캐서린은 우인단이 있던 사당의 위치가 표시된 의뢰서를 내밀었다. 지도보다 먼저 그 방의 바닥이 떠올랐다. 하프를 들고 나올 때 아무도 뒤에서 부르지 않았던 기억."},{"k":"line","id":"PRO_M04AB_기다림_027","speaker":"캐서린","text":"목적은 사망 사건의 경위 조사야. 두 사람이 처음 봤던 배치와 지금 현장을 비교하고, 확인한 내용을 길드에 전달하는 것부터 부탁하고 있어. 사망자의 소속만 보고 범인을 정하라는 의뢰는 아니야."},{"k":"line","id":"PRO_M04AB_기다림_028","speaker":"나","text":"거기 다시 가면 그때 놓친 걸 볼 수 있을까? 처음에는 하프를 찾는 것 말고는 제대로 생각도 못 했는데."},{"k":"line","id":"PRO_M04AB_기다림_029","speaker":"다이루크","text":"위치를 기억하는 사람이 필요하다. 그때 보지 못한 것을 지금 봤다고 말할 필요는 없어. 내가 함께 가겠다."},{"k":"line","id":"PRO_M04AB_기다림_030","speaker":"캐서린","text":"그럼 두 사람을 조사 동행자로 기록할게. 현장 확인 뒤에는 성으로 돌아와 보고해 줘. 새로운 사실이 없어도, 그대로였는지 달라졌는지는 알아야 하니까."},{"k":"choice","group":"G_PRO_M04AB_기다림_031","options":[{"label":"맡을게. 내가 본 사람들이 어떻게 된 건지는 알고 싶어. 이번에는 들어가기 전에 마음부터 좀 정리할게.","id":"PRO_M04AB_기다림_032","items":[{"k":"line","id":"PRO_M04AB_기다림_033","speaker":"다이루크","text":"출발을 서두르지는 않겠다. 필요한 짐을 챙겨. 그때와 같은 문으로 들어가서 기억하는 곳부터 보자."}]},{"label":"같이 가자. 혼자 다시 들어갈 자신은 없지만, 아무도 모르는 일처럼 남겨 두고 싶지도 않아.","id":"PRO_M04AB_기다림_034","items":[{"k":"line","id":"PRO_M04AB_기다림_035","speaker":"다이루크","text":"혼자 가라고 한 적 없다. 먼저 어디를 봤는지 네가 말해 줘. 그다음은 내가 확인하지."}]}]},{"k":"keep","id":"ISK_M04_AB_035"},{"k":"keep","id":"ISK_M04_AB_036","text":"사당 입구에 닿았을 때 지난번보다 먼저 걸음을 멈췄다. 그때는 다이루크가 멈춘 뒤에야 이상함을 알아차렸다. 이번에는 안쪽에서 아무 소리가 나지 않는다는 사실이 익숙해서 멈췄다. 다이루크는 나를 앞질러 문 가까이 섰다."},{"k":"line","id":"PRO_M04AB_빈_사당_001","speaker":"다이루크","text":"문은 열려 있다. 내가 먼저 보지. 네가 기억하는 첫 위치가 어디였나?"},{"k":"line","id":"PRO_M04AB_빈_사당_002","speaker":"나","text":"문 들어가서 오른쪽. 벽에 기대어 있었어. 무기는 칼집에 그대로 있었고…. 잠깐, 아무것도 없는데?"},{"k":"line","id":"PRO_M04AB_빈_사당_003","speaker":"","text":"비어 있었다. 첫 번째 자리만 그런 줄 알고 안쪽을 더 봤다. 사람들이 쓰러져 있던 곳에는 시신 하나 없었다. 바닥은 말끔했고, 거의 꺼져 가던 횃불도 없었다. 다이루크가 확인했던 방들도 같은 상태였다."},{"k":"line","id":"PRO_M04AB_빈_사당_004","speaker":"나","text":"여기 맞아. 저 문으로 들어갔고, 저쪽 방에서 하프를 찾았어. 바닥도 기억나. 우리가 다른 사당으로 온 건 아니야."},{"k":"line","id":"PRO_M04AB_빈_사당_005","speaker":"다이루크","text":"맞아. 같은 사당이다. 문도, 하프가 있던 방도 그대로야. 달라진 건 그 안에 있던 것들이군. 기억하는 자리를 짚어 줘. 내가 바닥을 확인하겠다."},{"k":"line","id":"PRO_M04AB_빈_사당_006","speaker":"","text":"다이루크는 낮은 받침 앞에 섰다. 하프를 덮었던 천도 없었다. 구석의 먼지를 손끝으로 살피고, 문턱과 바닥이 이어지는 곳까지 확인했다. 시신이 없다는 데 안도해야 할지 더 불안해야 할지 정할 수 없었다."},{"k":"choice","group":"G_PRO_M04AB_빈_사당_007","options":[{"label":"기사단이 먼저 수습했을 수도 있잖아. 사람을 그대로 둘 수는 없으니까. 그런데 그랬으면 우리한테 여기 오라고 하기 전에 말해 줬을 것 같고.","id":"PRO_M04AB_빈_사당_008","items":[{"k":"line","id":"PRO_M04AB_빈_사당_009","speaker":"다이루크","text":"출발 전에 확인한 내용에는 수습이 끝났다는 보고가 없었다. 돌아가서 다시 물을 이유는 생겼군. 하지만 확인하기 전까지는 누가 했다고 말하지 않겠다."}]},{"label":"그때는 사람들이 있어서 무서웠는데, 지금은 없어서 더 이상하네. 우리가 본 일을 통째로 치워 놓은 것 같아.","id":"PRO_M04AB_빈_사당_010","items":[{"k":"line","id":"PRO_M04AB_빈_사당_011","speaker":"다이루크","text":"누군가 치웠다면 드나든 흔적이 남았을 수 있어. 문턱과 방 구석부터 확인하자. 누가 무슨 의도로 그랬는지는 그다음이다."}]}]},{"k":"line","id":"PRO_M04AB_빈_사당_012","speaker":"","text":"두 사람은 처음 들어왔던 순서를 되짚었다. 다이루크는 내가 기억한 위치를 고치지 않고 자신이 본 자리를 따로 말해 줬다. 두 기억은 같은 방에서 맞아떨어졌다. 바뀐 것은 그 안에 있어야 할 것들이었다."},{"k":"line","id":"PRO_M04AB_빈_사당_013","speaker":"나","text":"하프는 우리가 가져갔으니까 없는 이유를 설명할 수 있어. 그런데 나머지는 아니네. 「없어졌다」는 말만 들고 돌아가는 건 또 허무한데."},{"k":"line","id":"PRO_M04AB_빈_사당_014","speaker":"다이루크","text":"나도 더 얻고 싶었다. 누군가를 따라갈 흔적이나 살아 있는 증언자라도. 지금 확보한 것은 현장이 정리됐다는 사실뿐이군."},{"k":"keep","id":"ISK_M04_AB_050","text":"다이루크는 종이를 접으려다가 방 안을 한 번 더 봤다. 표정은 크게 달라지지 않았지만, 접은 종이 모서리를 다시 펴는 손에서 아쉬움이 보였다. 나도 나갈 준비를 하다가 입구 쪽 발소리에 돌아섰다."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_001","speaker":"","text":"사당 안으로 들어온 사람은 무기를 앞세우지 않았다. 다이루크를 확인한 뒤 곁에 선 나에게 시선을 옮겼다. 손에는 작은 상자 하나. 빈 방에 물건을 들고 들어온 그 모습부터 경계하게 됐다."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_002","speaker":"알베도","text":"다이루크 씨. 여기 계셨군요. 길드에서 두 사람이 이쪽으로 출발했다고 들었어. 나는 알베도야. 혹시 네 이름이 {PLAYER_NAME} 맞아?"},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_003","speaker":"나","text":"맞아. 그런데 누가 찾는지부터 알아도 될까? 지금은 내 이름을 알고 찾아오는 사람이 평소보다 조금 더 수상해 보여서."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_004","speaker":"다이루크","text":"그럴 만한 상황이지. 알베도, 이곳에서 무엇을 하려는 건지 먼저 말해 줘. 우리가 들어왔을 때는 이미 이렇게 정리되어 있었다."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_005","speaker":"알베도","text":"이 사당을 조사하러 온 건 아니야. 전달을 부탁받은 물건이 있어. 앨리스 아줌마가 이 구슬을 네게 주라고 했거든."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_006","speaker":"","text":"알베도가 상자를 열었다. 안쪽 천 위에 작은 수정구슬이 놓여 있었다. 사당의 빈 바닥과 달리 그것은 분명히 눈앞에 있었다. 이름을 한 번 되물은 뒤, 물건 대신 알베도의 얼굴을 봤다."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_007","speaker":"나","text":"앨리스라는 사람이 내가 여기 있을 줄 알고 보낸 거야? 나는 그 사람을 만난 기억이 없는데. 나 여기 온 지 열흘도 안 됐어."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_008","speaker":"알베도","text":"네 이름과 전해 달라는 부탁을 받았어. 오늘 여기 있을 거라는 말은 없었고. 나는 네가 몬드에 머물고 있다는 걸 확인한 뒤 길드에 물어서 찾아왔지."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_009","speaker":"다이루크","text":"언제부터 네가 갖고 있었나? 이 사당에서 생긴 일과 연결해서 생각할 만한 설명도 받았어?"},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_010","speaker":"알베도","text":"내가 전달을 맡았을 때 이 물건을 받았어. 사당이나 사망 사건과 관련된 설명은 없었어. 그 일을 알고 보냈는지까지는 내가 대신 말할 수 없고."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_011","speaker":"나","text":"그럼 구슬이 뭔지는? 예쁜 선물이라고 받고 넘어가기에는 오는 장소가 너무 안 좋네. 방금까지 없어진 시신 찾고 있었거든."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_012","speaker":"","text":"알베도의 시선이 방 안으로 옮겨 갔다. 처음부터 전부 알고 온 사람처럼 굴지는 않았다. 내가 가리킨 자리와 다이루크의 기록을 본 뒤 상자를 조금 낮췄다."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_013","speaker":"알베도","text":"그렇다면 경계할 만하네. 내가 확실히 아는 건 전달을 부탁한 사람과 받는 사람의 이름이야. 용도는 설명받지 못했어. 모르는 부분은 나도 확인해야겠어."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_014","speaker":"나","text":"알베도는 그 사람을 믿어? 「부탁받았으니 줬고 끝」이라고 할 만큼 모르는 사이는 아닌 것 같은데."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_015","speaker":"알베도","text":"오래 알고 지낸 사람이야. 내게 중요한 사람이고. 하지만 그 사람이 하는 일을 언제나 미리 이해하는 건 아니지. 의심할 필요 없다는 말로 넘기기는 어렵겠네. 나도 이 구슬의 용도가 궁금해."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_016","speaker":"다이루크","text":"앨리스를 오래 안다는 건 알겠어. 그래도 물건 자체를 살펴봐야겠군. 네가 아는 게 더 생기면 바로 알려 줘."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_017","speaker":"알베도","text":"동의해. 그럼 지금 전해 주는 상태부터 함께 확인해 두자. 여기서는 빛이나 움직임이 없으니, 나중에 달라지면 그 차이부터 알려 줘."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_018","speaker":"","text":"상자 안을 다시 봤다. 구슬은 특별한 빛을 내지 않았다. 받는 사람이 나라는 것 말고는 평범한 물건과 구별할 게 거의 없었다. 그 이름 하나 때문에 지나칠 수 없었다."},{"k":"choice","group":"G_PRO_M04AB_앨리스의_구슬_019","options":[{"label":"받을게. 앨리스라는 사람을 만나게 되면, 설명도 같이 보내 줬으면 좋겠다고 전해 줘.","id":"PRO_M04AB_앨리스의_구슬_020","items":[{"k":"line","id":"PRO_M04AB_앨리스의_구슬_021","speaker":"알베도","text":"그 말도 전할게. 다만 어떤 답이 돌아올지는 약속하지 못하겠네. 구슬은 천으로 감싸 두면 움직이다 잃어버리지는 않을 거야."},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_022","speaker":"나","text":"설명서 없는 선물은 처음이 아니라서 괜찮아. 가구 조립도 그렇게 했어."}]},{"label":"우선 내가 가지고 있을게. 대신 이상한 반응이 생기면 알베도에게 바로 물어볼 거야. 전달한 사람이라고 모른 척하기 없기다.","id":"PRO_M04AB_앨리스의_구슬_023","items":[{"k":"line","id":"PRO_M04AB_앨리스의_구슬_024","speaker":"알베도","text":"내가 본 데까지는 같이 설명할게. 모르는 부분을 알아내는 일도 도울 수 있어. 그 부탁까지 받았다는 말로 이해하면 되겠네."}]}]},{"k":"keep","id":"ISK_M04_AB_073"},{"k":"line","id":"PRO_M04AB_앨리스의_구슬_025","speaker":"","text":"구슬을 감싼 천을 품 안에 넣었다. 빈손으로 돌아가겠다고 생각했는데 전혀 다른 물건을 들게 됐다. 세 사람은 각각 다른 질문을 가진 채 문으로 향했다."},{"k":"line","id":"PRO_M04AB_하늘_001","speaker":"","text":"사당 밖으로 나오자 햇빛이 눈에 들어왔다. 손을 들어 눈을 가리는 순간, 머리 위로 큰 그림자가 지나갔다. 알베도가 먼저 하늘을 봤고 다이루크의 손이 무기로 향했다."},{"k":"line","id":"PRO_M04AB_하늘_002","speaker":"나","text":"드발린…? 아니, 오늘 공지에는 분명히…."},{"k":"line","id":"PRO_M04AB_하늘_003","speaker":"","text":"거대한 용이 사당 위를 지나 몬드 방향으로 날았다. 죽었다던 드발린이었다. 보고를 잘못 이해한 것도, 멀리서 다른 날개를 본 것도 아니었다. 성벽 쪽 하늘이 바람에 뒤틀리고, 잠시 뒤 경보가 멀리서 울리기 시작했다."},{"k":"line","id":"PRO_M04AB_하늘_004","speaker":"다이루크","text":"몬드로 간다. 저 방향이면 성벽 밖 길에서 먼저 마주칠 수 있어. 알베도, 함께 올 수 있나?"},{"k":"line","id":"PRO_M04AB_하늘_005","speaker":"알베도","text":"갈게. 저 날개가 지나간 뒤부터 바람이 불규칙해졌어. 길에서도 위를 보면서 움직여야 해."},{"k":"line","id":"PRO_M04AB_하늘_006","speaker":"나","text":"이번에는 갈 길이 보이네. 뒤에서 또 공지만 읽고 싶지는 않아. 같이 가자. 내가 따라갈 자리도 알려 줘."},{"k":"line","id":"PRO_M04AB_하늘_007","speaker":"다이루크","text":"그래. 하지만 용만 보고 달리지는 마. 네 앞의 길과 옆의 사람도 봐. 지난 며칠 동안 네가 익힌 건 지금도 쓸 수 있어."},{"k":"keep","id":"ISK_M04_AB_082","text":"짐끈을 당겨 품 안의 구슬이 흔들리지 않게 했다. 겁이 사라진 건 아니었다. 다만 무엇부터 봐야 하는지 몰라 그 자리에 굳어 있지는 않았다. 세 사람은 경보가 들리는 쪽으로 달렸다."},{"k":"keep","id":"ISK_M04_AB_083","text":"성벽으로 이어지는 길목에는 안으로 들어가려는 사람들과 짐을 치우는 사람들이 뒤섞여 있었다. 드발린이 낮게 선회할 때마다 바람이 길을 훑었다. 다이루크가 열린 길을 가리키고 알베도가 내 속도를 맞췄다. 이번에는 용을 따라잡는 게 아니라 사람들이 빠져나갈 틈으로 들어가는 일이었다."},{"k":"line","id":"PRO_M04AB_하늘_008","speaker":"다이루크","text":"문 쪽으로 밀리지 마. 우리가 이쪽에 남아 있어야 저 날개가 사람들을 따라 돌지 않는다. 자네는 오른쪽을 봐."},{"k":"line","id":"PRO_M04AB_하늘_009","speaker":"나","text":"보고 있어. 이번에는 네 오른쪽이 아니라 내 오른쪽 맞지? 여기 낮은 돌 있는 쪽으로 갈게."},{"k":"line","id":"PRO_M04AB_하늘_010","speaker":"다이루크","text":"맞아. 이제 알아듣는 속도는 빨라졌군."},{"k":"line","id":"PRO_M04AB_하늘_011","speaker":"","text":"몸을 옮기자 지나간 자리에 돌조각이 떨어졌다. 그 순간 품 안에서 빛이 새어 나왔다. 알베도가 구슬 쪽을 보고 손을 들었다. 천 사이로 번지는 빛은 드발린이 가까워질 때 더 또렷해졌다."},{"k":"line","id":"PRO_M04AB_하늘_012","speaker":"알베도","text":"잠깐, 그 물건이 반응하고 있어. 던지지는 말고 천을 조금만 열어 봐. 내가 옆에서 볼게."},{"k":"line","id":"PRO_M04AB_하늘_013","speaker":"나","text":"용이 올 때만 이러는 것 같은데. 설명서가 빠졌다고 했더니 지금 몸으로 배우라는 건가?"},{"k":"line","id":"PRO_M04AB_하늘_014","speaker":"","text":"천을 벌리자 드발린의 목 아래에서 아주 가는 어둠의 조각이 들떴다. 구슬의 빛이 흔들리면 조각도 다시 붙었다. 걸음을 멈추려다 다이루크의 손짓을 보고 옆으로 더 움직였다."},{"k":"line","id":"PRO_M04AB_하늘_015","speaker":"알베도","text":"빛이 닿을 때 붙어 있는 것이 흔들렸어. 저 오염에 영향을 주는 것 같아. 하지만 네가 가만히 서 있으면 먼저 공격을 받아. 다이루크 씨, 고개가 돌아오는 시간을 조금 벌 수 있겠어?"},{"k":"line","id":"PRO_M04AB_하늘_016","speaker":"다이루크","text":"해 보지. 자네는 구슬만 보고 있지 마. 우리 목소리도 들어. 힘이 있어도 쓸 자리를 잃으면 소용없다."},{"k":"choice","group":"G_PRO_M04AB_하늘_017","options":[{"label":"좋아. 내가 빛을 비출 때 먼저 말할게. 신호는 크게 줘. 용이 소리를 다 차지해서 듣기가 힘드네.","id":"PRO_M04AB_하늘_018","items":[{"k":"line","id":"PRO_M04AB_하늘_019","speaker":"다이루크","text":"크게 주겠다. 자네도 크게 해. 하늘에서 지른 만큼은 아니어도."}]},{"label":"내가 손전등이 된 기분인데, 알겠어. 비출 때 말할게. 둘이 앞을 맡아 줘.","id":"PRO_M04AB_하늘_020","items":[{"k":"line","id":"PRO_M04AB_하늘_021","speaker":"알베도","text":"손전등이 뭔지는 나중에 물을게. 지금은 그 역할로 충분해."}]}]},{"k":"keep","id":"ISK_M04_AB_094","text":"드발린이 방향을 틀었다. 성을 향하던 시선이 구슬의 빛과 그 빛을 든 사람에게로 옮겨 왔다. 내가 용을 상대하게 됐다는 걸 알아차렸다. 그러나 이번에는 뒤에 사람이 있다는 것도 함께 알고 있었다."},{"k":"keep","id":"ISK_M04_AB_COMBAT"},{"k":"line","id":"PRO_M04AB_긴_숨_001","speaker":"","text":"구슬의 빛이 흔들리던 어둠을 끝까지 따라갔다. 드발린이 고개를 꺾으며 몸을 낮췄고, 검게 번지던 기운이 한꺼번에 흩어졌다. 쓰러졌다고 생각하며 한 걸음 다가가려다 멈췄다. 가슴이 움직이고 있었다. 이번에는 거친 바람이 아닌 긴 숨이 비늘 사이를 지나갔다."},{"k":"line","id":"PRO_M04AB_긴_숨_002","speaker":"알베도","text":"오염 반응이 멎었어. 숨은 이어지고 있고. 공격을 더할 필요는 없어. 지금은 거리를 두고 보자."},{"k":"line","id":"PRO_M04AB_긴_숨_003","speaker":"다이루크","text":"무기를 내려. 하지만 발밑은 계속 봐. 마지막에 무너진 돌이 아직 굴러온다."},{"k":"line","id":"PRO_M04AB_긴_숨_004","speaker":"나","text":"살아 있네. 내가 쓰러뜨린 건… 저걸 아프게 하던 쪽이었던 거지? 또 죽었다는 말을 듣는 건 아니지?"},{"k":"line","id":"PRO_M04AB_긴_숨_005","speaker":"알베도","text":"그래. 우리가 확인한 건 살아 있는 드발린과 사라진 오염이야. 구슬이 작용한 끝에 그렇게 되었어. 어떻게 죽음에서 돌아왔는지까지 같은 설명으로 묶을 수는 없지만."},{"k":"line","id":"PRO_M04AB_긴_숨_006","speaker":"","text":"천으로 구슬을 다시 감쌌다. 손에 힘이 들어가 있어서 접힌 모서리를 펴는 데 시간이 걸렸다. 다이루크가 그 모습을 보고 대신 가져가지는 않았다. 내가 매듭을 마칠 때까지 옆에서 기다렸다."},{"k":"line","id":"PRO_M04AB_긴_숨_007","speaker":"다이루크","text":"이번에는 끝까지 네 자리를 지켰군. 움직여야 할 때도 말했고. 덕분에 네가 어디로 갈지 보고 맞출 수 있었다."},{"k":"line","id":"PRO_M04AB_긴_숨_008","speaker":"나","text":"나도 계속 너희가 어디 있는지 봤어. 며칠 전이었으면 용만 보다가 아무 소리도 못 들었을 거야. 지금도 무서운 건 똑같네."},{"k":"line","id":"PRO_M04AB_긴_숨_009","speaker":"다이루크","text":"그래도 이번에는 내 말을 들었지. 겁이 나더라도 그렇게 서로 맞출 수 있으면 다음 행동을 고를 수 있어. 오늘은 그걸 해냈군."},{"k":"line","id":"PRO_M04AB_긴_숨_010","speaker":"","text":"알베도가 드발린 쪽으로 돌아섰다. 용은 눈을 뜨고 성벽을 봤다가, 자신의 앞발과 사람들 사이의 거리를 살폈다. 다시 공격하려고 고개를 낮추지는 않았다."},{"k":"line","id":"PRO_M04AB_긴_숨_011","speaker":"드발린","text":"나는… 다시 이곳을 공격했군. 가까이 오지 마라. 몸이 지금 내 뜻을 따르고 있는지 조금 더 확인하고 싶다."},{"k":"line","id":"PRO_M04AB_긴_숨_012","speaker":"나","text":"알겠어. 우리는 여기서 기다릴게. 성문 쪽 사람들도 네 날개만 보고 있을 거야. 움직일 수 있겠으면 먼저 말해 줘."},{"k":"line","id":"PRO_M04AB_긴_숨_013","speaker":"드발린","text":"네 손에 있던 빛을 보았다. 고통 속에서도 그것이 닿을 때는 다른 소리가 잠깐 멀어졌다. 네가 나를 붙잡아 둔 것인가?"},{"k":"line","id":"PRO_M04AB_긴_숨_014","speaker":"나","text":"응. 구슬을 비춘 건 나야. 다이루크와 알베도가 자리를 만들어 줘서 끝까지 들고 있을 수 있었어. 그전까지는 나도 무슨 물건인지 몰랐는데, 네가 반응하는 걸 보고 이번 기회는 놓치기 싫더라."},{"k":"line","id":"PRO_M04AB_긴_숨_015","speaker":"","text":"드발린은 두 사람도 차례로 봤다. 다이루크는 짧게 고개를 끄덕였고, 알베도는 용의 호흡을 살피던 시선을 잠시 나에게 돌렸다. 그제야 손바닥에 남은 땀을 옷에 닦았다. 혼자 해냈다고 우길 필요도, 구슬이 한 일이라며 내 몫을 전부 밀어낼 필요도 없었다."},{"k":"choice","group":"G_PRO_M04AB_긴_숨_016","options":[{"label":"묻고 싶은 게 있어. 네가 죽었다는 소식을 들었어. 그런데 사당에서 나오니까 다시 하늘에 있었고. 그사이에 무슨 일이 있었는지 기억해?","id":"PRO_M04AB_긴_숨_017","items":[{"k":"line","id":"PRO_M04AB_긴_숨_018","speaker":"드발린","text":"끊긴 기억이 있다. 고통과 소리가 한꺼번에 멀어졌고, 다시 눈을 떴을 때는 몸이 먼저 움직였다. 네 질문에 줄 수 있는 답은 거기까지다. 내가 원해서 이곳으로 돌아온 것은 아니었다."}]},{"label":"너 죽었다고 공지까지 났었어. 그거 보고 나 꽤… 아니, 됐어. 살아 있으면 됐어.","id":"PRO_M04AB_긴_숨_019","items":[{"k":"line","id":"PRO_M04AB_긴_숨_020","speaker":"드발린","text":"죽었다는 것이 무엇인지 나도 모른다. 고통이 멀어졌고, 눈을 떴을 때 몸이 먼저 움직였다. 그 사이는 비어 있다."}]}]},{"k":"line","id":"PRO_M04AB_긴_숨_021","speaker":"다이루크","text":"토벌대의 보고가 없었던 일이 되는 건 아니군. 죽음을 확인했던 현장에 대해 다시 묻겠다. 우리가 지금 본 건 돌아온 드발린이야. 그사이에 빠진 일은 따로 찾아야겠어."},{"k":"line","id":"PRO_M04AB_긴_숨_022","speaker":"알베도","text":"구슬을 전해 받은 뒤 곧바로 이런 일이 생겼다는 점도 기록하겠어. 다만 앨리스 아줌마가 이 일을 일으켰다거나 예견했다고 단정하지는 않을 거야. 그건 아직 묻지 못한 질문이니까."},{"k":"line","id":"PRO_M04AB_긴_숨_023","speaker":"나","text":"나도 그 사람한테 묻고 싶어. 왜 나한테 보냈는지. 이걸 안 받았으면 오늘 어떻게 됐을지 생각하면 고맙기는 한데, 모르는 채로 갖고 있으라는 건 좀 어렵네."},{"k":"line","id":"PRO_M04AB_긴_숨_024","speaker":"알베도","text":"내가 다시 연락할 수 있게 되면 네 질문을 전할게. 오늘은 물건을 전달한 뒤에도 곁에 남아 있길 잘했다는 생각이 들어."},{"k":"line","id":"PRO_M04AB_긴_숨_025","speaker":"드발린","text":"바르바토스는 어디 있지? 그가 나를 부르던 목소리가 기억난다. 이번에는 그 목소리를 잘못 알아듣고 싶지 않다."},{"k":"line","id":"PRO_M04AB_긴_숨_026","speaker":"나","text":"바르바토스? 혹시 너를 찾아다니던 음유시인 말하는 거야? 초록색 옷을 입고, 친구를 구하고 싶다고 했던…."},{"k":"line","id":"PRO_M04AB_긴_숨_027","speaker":"드발린","text":"그렇다. 너도 그와 함께 있었군. 그가 지금 어디로 갔는지 아느냐?"},{"k":"line","id":"PRO_M04AB_긴_숨_028","speaker":"나","text":"지금 어디 있는지는 몰라. 마지막에는 널 찾아보겠다고 했어. 만날 수 있다면… 살아 있고, 이제 아프게 하던 건 사라졌다고 직접 말해 줘. 우리가 대신 전하는 것보다 네가 말하는 게 좋을 것 같아."},{"k":"line","id":"PRO_M04AB_긴_숨_029","speaker":"드발린","text":"그렇게 하겠다. 이곳의 사람들에게도 내가 물러난다는 것을 전해라. 당장 가까이 와서 믿으라고 요구하지 않겠다."},{"k":"line","id":"PRO_M04AB_긴_숨_030","speaker":"","text":"드발린은 성벽과 반대 방향으로 고개를 돌렸다. 날개를 펼치자 문 앞에 있던 사람들이 다시 몸을 낮췄다. 그는 곧장 성 위로 날지 않고 넓은 들판 쪽으로 거리를 벌렸다. 그 방향을 확인한 뒤에야 길게 숨을 내쉬었다."},{"k":"line","id":"PRO_M04AB_긴_숨_031","speaker":"다이루크","text":"성으로 돌아가지. 이번에는 우리가 전할 소식이 있다."},{"k":"choice","group":"G_PRO_M04AB_긴_숨_032","options":[{"label":"응. 이번 소식은 내가 직접 보고 말할 수 있네. 「토벌됐다」는 공지만 읽고 서 있던 때와는 다르게.","keep":"ISK_M04_AB_124","items":[]}]},{"k":"keep","id":"ISK_M04_AB_125","text":"성문 안으로 들어올 때 먼저 내 이름을 말했다. 경비병이 세 사람의 얼굴을 확인하고 본부 쪽으로 길을 안내했다. 같은 보고를 몇 번 되풀이해야 했지만, 드발린을 죽이지 않고 정화했다는 대목은 되풀이할 때마다 조금 덜 떨렸다."},{"k":"line","id":"PRO_M04AB_보고_001","speaker":"","text":"길드에서는 캐서린이 사당 재조사 보고와 용의 재습격 보고를 다른 종이에 받았다. 시신이 없었다는 이야기부터 했다. 알베도는 자신이 물건을 전달한 경위를 보탰고, 다이루크는 최초 현장과 달라진 부분을 짚었다."},{"k":"line","id":"PRO_M04AB_보고_002","speaker":"캐서린","text":"사당 조사 내용은 접수했어. 시신이 사라지고 현장이 정리된 사실은 확인됐지만, 사건의 진상이 밝혀진 건 아니네. 이 의뢰는 추가 확인을 기다리는 상태로 남겨 둘게."},{"k":"line","id":"PRO_M04AB_보고_003","speaker":"나","text":"응. 구슬을 받았고 드발린을 막았다고 해서, 그 방에서 죽은 사람들이 왜 죽었는지 알게 된 건 아니니까. 그건 따로 물어봐 줘."},{"k":"line","id":"PRO_M04AB_보고_004","speaker":"캐서린","text":"그렇게 전할게. 드발린을 정화했다는 내용도 목격자들의 보고와 함께 넘기겠어. 이번에는 두 사람이 소식을 기다리러 온 게 아니라 가져왔구나."},{"k":"line","id":"PRO_M04AB_보고_005","speaker":"","text":"그 말에 접수대 앞에서 잠깐 멈췄다. 같은 자리에 며칠 동안 서 있었는데, 이번에는 더 물을 내용을 찾느라 머무르는 게 아니었다. 내가 말한 이야기가 종이 위에 남는 걸 보고 있었다."},{"k":"line","id":"PRO_M04AB_보고_006","speaker":"다이루크","text":"보고는 끝났어. 이제 쉬자. 오늘은 내가 물어볼게. 더 들를 곳이 있나?"},{"k":"choice","group":"G_PRO_M04AB_보고_007","options":[{"label":"성문을 한 번 더 보러 갈까 했는데… 오늘은 됐어. 내가 안 보고 있어도 새 소식이 오면 알려 주겠지. 대신 앉아서 물부터 마시고 싶어.","id":"PRO_M04AB_보고_008","items":[{"k":"line","id":"PRO_M04AB_보고_009","speaker":"알베도","text":"그동안 구슬은 네가 보관해. 더 조사하고 싶기는 하지만 지금 물건부터 가져가고 싶지는 않아. 네가 직접 겪은 일을 들을 시간도 필요하니까."}]},{"label":"없어. 오늘은 의자 있는 데. 알베도, 아까 그 상자 들고 온 거 보고 「수상한 사람」이라고 생각한 거 사과할게. 반쯤.","id":"PRO_M04AB_보고_010","items":[{"k":"line","id":"PRO_M04AB_보고_011","speaker":"알베도","text":"반은 남겨 두는 거구나. 그럼 그 반은 다음에 평범한 그림을 보여 주고 받아 갈게. 구슬은 그동안 네가 보관해."}]}]},{"k":"line","id":"PRO_M04AB_보고_012","speaker":"나","text":"좋아. 다음에는 제대로 앉아서 얘기하자. 오늘은 얼굴 보고 인사하자마자 뛰기부터 했잖아. 알베도, 네가 장소를 골라 줘. 들어가기 전에 의자가 있는지만 먼저 알려 주고."},{"k":"line","id":"PRO_M04AB_보고_013","speaker":"알베도","text":"그럼 다음 장소는 내가 고를게. 의자가 있는지는 먼저 확인해 두지."},{"k":"keep","id":"ISK_M04_AB_136","text":"내가 웃자 다이루크는 가게 쪽으로 먼저 걸음을 옮겼다. 따라오라는 말을 하지 않아도 셋이 같은 방향으로 움직였다. 품 안의 구슬은 조용했고, 성벽 위에서는 평소의 교대 종이 울렸다. 여전히 밝혀야 할 일이 남아 있었지만, 오늘 몬드로 돌아온 용은 더 이상 사람들을 공격하지 않았다."},{"k":"keep","id":"ISK_M04_AB_END","text":"구슬의 힘으로 드발린을 정화하고 몬드로 돌아왔다. 사당 사건은 미해결로 남고, 구슬은 내가 보관한다."}],"edits":[],"pre":""},{"id":"ISK_M04_B","entry":"ISK_M04_B_001","items":[{"k":"keep","id":"ISK_M04_B_001","text":"부서진 한천의 못이 있던 자리에서 손을 펴 봤다. 손가락이 떨리는 게 추위 때문인지 방금 들은 목소리 때문인지 알기 어려웠다. 알베도가 옆에 무릎을 꿇고 구슬이 놓인 자리를 먼저 살폈다. 그 뒤로 같은 속삭임은 들려오지 않았다."},{"k":"line","id":"PRO_M04B_구슬_001","speaker":"알베도","text":"주변의 파편과는 떨어져 있어. 내가 천을 줄게. 만져 보기로 한다면 맨손보다는 그쪽이 낫겠어. 어떤 물건인지 설명해 줄 수 없다는 점은 먼저 말해야겠네."},{"k":"line","id":"PRO_M04B_구슬_002","speaker":"나","text":"아까 그 말, 나한테 한 말 같았어. 대답도 안 했는데 왜 벌써 자기 거야? 이걸 두고 가면 끝나는 건지, 가져가면 더 엮이는 건지도 모르겠네."},{"k":"line","id":"PRO_M04B_구슬_003","speaker":"알베도","text":"그렇게 느꼈다는 건 기억해 둘게. 하지만 물건이 너를 소유한다는 결론까지 받아들일 필요는 없어. 지금 확인할 수 있는 건 네가 말을 들었고, 여기에 구슬이 있다는 사실이야."},{"k":"line","id":"PRO_M04B_구슬_004","speaker":"나","text":"좋아. 아직 아무 일도 안 일어났는데 혼자 뒷이야기를 붙이고 있었네. 만지면 큰일 난다, 두고 가면 쫓아온다…. 둘 중 하나를 꼭 골라야 하는 것도 아닌데."},{"k":"line","id":"PRO_M04B_구슬_005","speaker":"","text":"알베도가 접은 천을 내밀었다. 구슬을 천 가운데로 옮겼다. 뜨겁지도 차갑지도 않았다. 손바닥에 온전히 올라왔다는 사실이 오히려 이상했다. 조금 전까지 하늘에 있던 거대한 구조물이 무너졌는데, 지금 가지고 내려갈 것은 이 작은 물건이었다."},{"k":"choice","group":"G_PRO_M04B_구슬_006","options":[{"label":"일단 내가 가지고 갈게. 네가 옆에 있을 때 살펴보고 싶어. 주머니에 넣었다가 숙소에서 혼자 꺼내 보는 건 별로 하고 싶지 않아서.","id":"PRO_M04B_구슬_007","items":[{"k":"line","id":"PRO_M04B_구슬_008","speaker":"알베도","text":"좋아. 천이 풀리지 않게 두 번 묶자. 내려가는 동안 빛이 나거나 소리가 들리면 바로 말해 줘. 이 길에서는 손보다 발을 먼저 살펴야 하니까."}]},{"label":"네가 가져갈래? 연구하는 사람이잖아. 「넌 내 거」라는 말을 들은 사람이 들고 가는 건 좀….","id":"PRO_M04B_구슬_009","items":[{"k":"line","id":"PRO_M04B_구슬_010","speaker":"알베도","text":"네가 들은 말이고, 네 앞에 놓여 있었어. 내가 가져가면 그 둘을 떼어 놓게 돼. 지금은 네가 들고, 내가 옆에서 보는 쪽이 기록으로는 정확해. 무서우면 내가 매듭을 묶을게."},{"k":"line","id":"PRO_M04B_구슬_011","speaker":"나","text":"묶어 줘. 두 번."}]}]},{"k":"keep","id":"ISK_M04_B_009","text":"구슬을 품 안에 넣고 같은 자리를 손으로 한 번 더 눌렀다. 알베도는 그 행동을 재촉하지 않았다. 두 사람이 몸을 일으켰을 때, 정상에 남은 것은 부서진 돌과 조금 전보다 낮아진 하늘뿐이었다."},{"k":"line","id":"PRO_M04B_하산_001","speaker":"","text":"내려가는 길이라고 다리가 편해지지는 않았다. 올라갈 때는 눈앞의 바위만 보면 됐지만 내려갈 때는 그 아래가 함께 보였다. 알베도가 먼저 발을 놓은 자리를 따라갔다. 두 번 미끄러진 뒤에는 괜찮다고 먼저 말하는 대신 그가 돌아볼 때까지 기다렸다."},{"k":"line","id":"PRO_M04B_하산_002","speaker":"알베도","text":"오른쪽 발을 조금 안쪽으로 옮겨. 그래, 거기. 손은 이쪽으로. 잡은 뒤에 움직여도 늦지 않아."},{"k":"line","id":"PRO_M04B_하산_003","speaker":"나","text":"올라갈 때는 네가 그림 그리느라 멈추면 왜 저기서 멈추나 했는데. 이제는 한 장 더 그려 달라고 하고 싶네. 내가 쉬자는 말을 하기 전에 멈출 구실이 생기니까."},{"k":"line","id":"PRO_M04B_하산_004","speaker":"알베도","text":"그럼 쉬자. 그림이 없어도 괜찮아. 네가 쉬어야 한다는 설명을 작품으로 제출할 필요는 없으니까."},{"k":"line","id":"PRO_M04B_하산_005","speaker":"","text":"알베도가 바람이 덜 닿는 바위 옆에 자리를 잡았다. 그가 펼친 수첩에는 올라오며 본 능선과 한천의 못의 윤곽이 남아 있었다. 눈앞의 풍경에서는 이미 사라진 선들이었다."},{"k":"line","id":"PRO_M04B_하산_006","speaker":"나","text":"그림이 먼저 남았네. 이제 네가 그린 게 없으면 내가 뭘 봤는지 설명하기도 어렵겠다."},{"k":"line","id":"PRO_M04B_하산_007","speaker":"알베도","text":"그래서 관찰할 때의 그림은 완성도가 조금 낮아도 남겨 두는 편이야. 다시 와서 고치겠다고 미루면 그동안 변할 수 있으니까. 오늘은 변하는 정도가 예상보다 컸지만."},{"k":"line","id":"PRO_M04B_하산_008","speaker":"나","text":"다음 그림에는 나도 있어? 있으면 조금 덜 지친 사람처럼 그려 줘. 지금 얼굴로 남으면 나중에 이 산 얘기할 때마다 웃을 것 같아."},{"k":"line","id":"PRO_M04B_하산_009","speaker":"알베도","text":"그 표정을 보고 네가 웃을 수 있다면 한 장 남겨도 되겠네. 다만 지금처럼 입을 벌리고 숨을 고르는 모습을 모른 척하기는 조금 어려워."},{"k":"line","id":"PRO_M04B_하산_010","speaker":"","text":"대꾸하려다 웃었다. 품 안에 손을 넣어 매듭을 확인하자 알베도가 수첩을 덮었다. 무엇이 느껴졌느냐고 묻는 대신 조금 더 쉬어도 된다고 말했다."},{"k":"line","id":"PRO_M04B_하산_011","speaker":"나","text":"이걸 연구하고 싶지는 않아? 아까부터 나보다 더 침착해서 그래. 보통 이런 건 연구하는 사람이 자기가 보관하겠다고 할 것 같았거든."},{"k":"line","id":"PRO_M04B_하산_012","speaker":"알베도","text":"궁금해. 한천의 못이 무너진 일과 관련이 있는지도 알고 싶고. 하지만 꼭 내 손에 있어야만 관찰할 수 있는 건 아니야. 네가 보관하는 동안 달라지는 점을 알려 줘."},{"k":"line","id":"PRO_M04B_하산_013","speaker":"나","text":"그럼 들리는 대로 말할게. 내가 알아서 평범한 말로 고쳤다가 네가 엉뚱한 걸 조사하면 둘 다 곤란하잖아. 이상한 부분은 각오하고 들어."},{"k":"line","id":"PRO_M04B_하산_014","speaker":"알베도","text":"각오하고 들을게. 익숙한 것만 보려고 이 산에 온 건 아니니까. 자, 조금 더 내려가자. 다음 쉼터에서는 따뜻한 걸 마실 수 있어."},{"k":"keep","id":"ISK_M04_B_024","text":"먼저 일어나려다 뻐근한 다리 때문에 다시 앉았다. 알베도가 내민 손을 이번에는 바로 잡았다. 두 사람은 정상으로 향할 때보다 말이 많아진 채 산길을 내려왔다."},{"k":"line","id":"PRO_M04B_길_앞의_사람_001","speaker":"","text":"눈이 얇아지고 길가에 흙이 보일 무렵, 알베도가 걸음을 늦췄다. 길 앞에 누군가 서 있었다. 초록 옷자락이 바람에 흔들렸다. 길을 물으러 나온 모습으로 보기에는 시선이 두 사람의 뒤와 하늘을 너무 자주 오갔다."},{"k":"line","id":"PRO_M04B_길_앞의_사람_002","speaker":"벤티","text":"찾았다. 너희가 이쪽으로 내려오기를 기다렸어. 산 위로 올라가자니 어디서 엇갈릴지 몰라서…. 다친 데는 없어? 걸을 수 있지?"},{"k":"line","id":"PRO_M04B_길_앞의_사람_003","speaker":"나","text":"걸을 수는 있는데… 일단 누구야? 방금 내려온 사람한테 제일 먼저 그걸 물으면 보통 또 걸을 일이 있더라."},{"k":"line","id":"PRO_M04B_길_앞의_사람_004","speaker":"벤티","text":"아, 소개부터 해야 했는데. 나는 벤티, 몬드의 음유시인이야. 알베도가 이 산에 있다는 걸 알고 찾아왔어. 부탁할 일이 있어서. 네가 같이 올라갔다는 얘기도 거점에서 들었고."},{"k":"line","id":"PRO_M04B_길_앞의_사람_005","speaker":"알베도","text":"서로 소개부터 할 시간이 충분하지 않은 것 같네. 무슨 일이야? 네가 뒤를 돌아보는 이유부터 듣고 싶어."},{"k":"line","id":"PRO_M04B_길_앞의_사람_006","speaker":"","text":"벤티는 웃으려다 말았다. 바람이 잦아든 틈에 뒤쪽 숲에서 나뭇가지가 꺾이는 소리가 났다. 소리의 높이가 사람이 지나는 자리보다 훨씬 위였다. 고개를 들어 나무 사이로 움직이는 푸른 비늘을 봤다."},{"k":"line","id":"PRO_M04B_길_앞의_사람_007","speaker":"벤티","text":"드발린을 데려왔어. 토벌대가 곧 움직인다는 소식을 들었거든. 내가 그 애를 만나서 얘기할 시간을 기다려 주지는 않을 것 같았어. 그래서 먼저 찾았고… 여기까지 데려왔어."},{"k":"line","id":"PRO_M04B_길_앞의_사람_008","speaker":"나","text":"잠깐. 네 뒤에 있는 저게 드발린이라고? 성에서 간판 떨어뜨리던 그 용? 여기로 오겠다고 한 거야, 아니면 네가 끌고 온 거야?"},{"k":"line","id":"PRO_M04B_길_앞의_사람_009","speaker":"벤티","text":"내가 오게 했어. 그 애가 고른 길은 아니야. 바람으로 길을 돌리고, 내 목소리를 쫓게 했어. 멈추고 얘기할 수 있을 줄 알았는데 가까이 갈 때마다 고통스러워했어. 그냥 토벌대가 기다리는 쪽으로 보내지는 못하겠더라."},{"k":"line","id":"PRO_M04B_길_앞의_사람_010","speaker":"","text":"드발린의 날개가 나무 위로 솟았다. 날개 끝에서 쏟아진 눈이 길을 덮었다. 벤티의 목소리를 쫓아 여기까지 온 용은, 지금은 그 목소리를 들을 때마다 더 거칠게 몸을 뒤틀고 있었다."},{"k":"line","id":"PRO_M04B_길_앞의_사람_011","speaker":"알베도","text":"다친 용을 데려온 이유는 알겠어. 하지만 이곳에도 사람이 있어. 일단 길에서 떨어뜨려야 해. 설명은 움직이면서 하자. 너는 바람을 어느 쪽으로 돌릴 수 있지?"},{"k":"line","id":"PRO_M04B_길_앞의_사람_012","speaker":"벤티","text":"저 앞의 빈 비탈 쪽. 사람 있는 거점으로는 가지 않게 할 수 있어. 다만 오랫동안 붙잡지는 못해. 계속 억지로 끌면 그 애가 더 버티려고 해."},{"k":"line","id":"PRO_M04B_길_앞의_사람_013","speaker":"나","text":"아까부터 「억지로」라는 말이 자꾸 나오잖아. 도와줄게. 그런데 이번에는 우리한테도 뭘 하려는지 먼저 말해 줘. 용이 뒤에 나타난 다음에 설명 들으면 생각할 시간이 없어."},{"k":"line","id":"PRO_M04B_길_앞의_사람_014","speaker":"벤티","text":"미안해. 맞아, 먼저 말했어야 했어. 내가 바람으로 비탈 쪽까지 길을 만들게. 알베도, 너희가 지나갈 발판을 부탁해도 될까?"},{"k":"line","id":"PRO_M04B_길_앞의_사람_015","speaker":"알베도","text":"그렇게 하자. 너도 혼자 용 가까이로 돌아가지는 마. 우리가 움직였는지 확인한 뒤에 바람을 옮겨 줘."},{"k":"keep","id":"ISK_M04_B_040","text":"벤티가 손을 들자 눈가루가 길 한쪽으로 밀렸다. 그제야 길을 볼 수 있었다. 알베도가 먼저 바위를 딛고 팔을 내밀었다. 산에서는 내려왔지만 아직 쉬어도 되는 곳에 도착한 건 아니었다."},{"k":"choice","group":"G_PRO_M04B_길_앞의_사람_016","options":[{"label":"구하려고 데려왔으면 구할 방법도 같이 찾아보자. 나도 도울게. 대신 저 용이랑 우리만 있는 곳부터 잡자. 거점 사람들까지 끌려 나오게 할 수는 없잖아.","id":"PRO_M04B_길_앞의_사람_017","items":[{"k":"line","id":"PRO_M04B_길_앞의_사람_018","speaker":"벤티","text":"응. 부탁하려던 말인데, 네가 먼저 해 줬네. 그 애를 구하고 싶어. 그 마음 때문에 다른 사람이 다쳐도 괜찮다는 뜻은 아니야."},{"k":"line","id":"PRO_M04B_길_앞의_사람_019","speaker":"알베도","text":"서로 원하는 바는 알았어. 이제 같은 방향으로 움직이면 돼. 발을 놓을 자리를 먼저 볼게."}]},{"label":"나 지금 산 하나 내려온 사람이야. 용을 막아 본 적도 없고. 그러니까 할 수 있는 일을 정확히 나눠 줘.","id":"PRO_M04B_길_앞의_사람_020","items":[{"k":"line","id":"PRO_M04B_길_앞의_사람_021","speaker":"알베도","text":"알겠어. 넌 내 왼쪽에 있어. 내가 자리를 바꾸라고 하면 바뀔 곳도 함께 가리킬게. 네가 혼자 용의 시선을 붙잡을 필요는 없어."},{"k":"line","id":"PRO_M04B_길_앞의_사람_022","speaker":"벤티","text":"나는 드발린의 머리가 돌아오는 방향을 볼게. 숨을 들이마시기 시작하면 먼저 알려 줄 수 있어. 내가 부르면 그쪽을 봐 줘."}]}]},{"k":"keep","id":"ISK_M04_B_047"},{"k":"line","id":"PRO_M04B_빈_비탈_001","speaker":"","text":"빈 비탈에 다다르자 드발린이 몸을 틀며 고개를 낮췄다. 알베도가 세운 바위꽃이 발밑에서 솟았다. 높아진 시야에 놀라 아래부터 봤다가, 다가오는 날개를 보고 다시 앞을 봤다. 벤티가 바람을 옆으로 돌려 세 사람이 용의 정면에서 벗어날 자리를 만들었다."},{"k":"line","id":"PRO_M04B_빈_비탈_002","speaker":"나","text":"높이 바꿀 때도 말해 줘! 바닥이 올라오는 걸 보고 내가 떨어지는 줄 알았어!"},{"k":"line","id":"PRO_M04B_빈_비탈_003","speaker":"알베도","text":"미안해. 다음에는 미리 말할게. 그 자리에서는 내려오지 마. 내가 다시 낮출 때까지 옆의 바위를 잡고 있어."},{"k":"line","id":"PRO_M04B_빈_비탈_004","speaker":"","text":"몸을 붙잡으려고 품을 누르는 순간 손가락 사이로 빛이 샜다. 처음에는 눈에 반사된 햇빛이라고 생각했다. 그러나 천이 겹친 곳에서도 같은 빛이 번졌다. 드발린이 가까워질수록 더 선명해졌다."},{"k":"line","id":"PRO_M04B_빈_비탈_005","speaker":"나","text":"알베도, 이거 봐. 아까 산에서는 이러지 않았어. 여기로 내려오고 나서, 아니, 저 용이 다가오니까…."},{"k":"line","id":"PRO_M04B_빈_비탈_006","speaker":"알베도","text":"천을 조금 열어 봐. 내가 네 앞을 볼게. 빛이 나오는 동안 무슨 변화가 생기는지 확인하자."},{"k":"line","id":"PRO_M04B_빈_비탈_007","speaker":"","text":"천의 가장자리가 풀리자 빛이 드발린의 목 가까이에 닿았다. 어둡게 엉겨 있던 것이 잠시 갈라졌다. 용이 움찔하며 고개를 물렸고, 벤티가 그 움직임을 따라 한 걸음 나가려 했다. 알베도가 손을 뻗어 앞을 막았다."},{"k":"line","id":"PRO_M04B_빈_비탈_008","speaker":"알베도","text":"지금 다가가지는 마. 통증이 멎은 건지 다른 자극을 받은 건지부터 봐야 해. 같은 반응이 한 번 더 나타나는지 확인할 수 있어?"},{"k":"line","id":"PRO_M04B_빈_비탈_009","speaker":"나","text":"움직이는 걸 계속 비추기는 어려워. 잡고 있을게. 대신 어느 쪽으로 피해야 하는지는 말해 줘. 이것만 보다가는 못 볼 것 같아."},{"k":"line","id":"PRO_M04B_빈_비탈_010","speaker":"벤티","text":"그 애를 아프게 하는 기운이 빛이 닿을 때 흐트러졌어. 나도 봤어. 조금만 더 가까이 닿게 할 수 있다면…. 아니, 먼저 네가 서 있을 자리를 만들게. 천천히 해도 돼."},{"k":"line","id":"PRO_M04B_빈_비탈_011","speaker":"","text":"벤티가 말을 고쳐 하는 걸 들었다. 용의 목소리가 숲을 뒤흔드는 동안에도 그 짧은 수정이 귀에 남았다. 알베도가 고개를 끄덕이고 발판을 가리켰다. 이번에는 높이가 바뀌기 전에 나도 무릎을 굽혔다."},{"k":"line","id":"PRO_M04B_빈_비탈_012","speaker":"알베도","text":"지금부터 조금 올릴게. 너무 몸을 내밀지 않아도 돼. 빛이 닿을 길은 우리가 같이 찾자."},{"k":"keep","id":"ISK_M04_B_060","text":"드발린이 크게 날개를 펼쳤다. 눈과 돌이 한꺼번에 일어났다. 구슬을 품에 고정한 손과 몸을 지탱할 손을 나누고, 두 사람이 있는 방향을 확인했다. 도망칠 길을 찾던 시선이 이번에는 함께 움직일 길을 찾았다."},{"k":"keep","id":"ISK_M04_B_COMBAT"},{"k":"line","id":"PRO_M04B_이름_001","speaker":"","text":"마지막까지 드발린에게 붙어 있던 어둠이 구슬의 빛 속에서 풀렸다. 흩어진 기운은 다시 비늘에 달라붙지 않았다. 용이 땅 가까이 몸을 낮추자 세 사람도 함께 멈췄다. 눈가루가 가라앉은 너머로 큰 가슴이 천천히 오르내리는 게 보였다."},{"k":"line","id":"PRO_M04B_이름_002","speaker":"알베도","text":"반응이 잦아들고 있어. 구슬을 조금 내려도 될 것 같아. 갑자기 놓지는 말고, 천으로 다시 감싸자."},{"k":"line","id":"PRO_M04B_이름_003","speaker":"나","text":"손이 말을 잘 안 들어. 계속 쥐고 있어서 그런가 봐. 매듭은 조금 있다가 해도 되지? 지금 잘못 묶으면 다시 풀지도 못하겠어."},{"k":"line","id":"PRO_M04B_이름_004","speaker":"알베도","text":"그럼 천 끝만 내가 잡을게. 네 손은 천천히 펴. 됐어. 물건은 그대로 네게 있으니까 서두르지 않아도 돼."},{"k":"line","id":"PRO_M04B_이름_005","speaker":"","text":"벤티는 두 사람에게서 몇 걸음 떨어진 곳에 서 있었다. 드발린이 고개를 들자 앞으로 움직이려다 멈췄다. 이번에는 먼저 부르지 않았다."},{"k":"line","id":"PRO_M04B_이름_006","speaker":"드발린","text":"바르바토스…. 네 목소리였군. 줄곧 들렸다. 그런데 가까이 갈수록 네가 나를 몰아세운다고 생각했다. 그 소리와 네 목소리를 가를 수가 없었어."},{"k":"line","id":"PRO_M04B_이름_007","speaker":"벤티","text":"응, 나였어. 널 데려오려고 계속 불렀어. 멈추면 토벌대가 있는 곳으로 돌아갈까 봐, 네가 아프다는 것도 알면서…. 미안해, 드발린. 널 만나고 싶어서 너를 계속 움직이게 했어."},{"k":"line","id":"PRO_M04B_이름_008","speaker":"드발린","text":"그러지 않았다면 내가 다른 이들을 다치게 했을 수도 있겠지. 하지만 네 목소리를 쫓는 동안에도 내 뜻으로 가고 있다는 느낌은 들지 않았다."},{"k":"line","id":"PRO_M04B_이름_009","speaker":"","text":"벤티는 변명하지 못한 채 고개를 끄덕였다. 구슬을 싸던 내 손도 잠시 멎었다. 살아서 같은 말을 나눌 수 있게 됐다고 해서, 그 말이 모두 듣기 쉬워지는 건 아니었다."},{"k":"line","id":"PRO_M04B_이름_010","speaker":"벤티","text":"알아. 다음에는 네가 대답할 때까지 기다릴게. 지금도 그래. 내가 여기 있어도 괜찮을까?"},{"k":"line","id":"PRO_M04B_이름_011","speaker":"드발린","text":"있어라. 지금은 네가 무슨 말을 하는지 들린다. 나도 내 대답을 고를 수 있고."},{"k":"line","id":"PRO_M04B_이름_012","speaker":"","text":"그제야 벤티의 어깨가 내려갔다. 드발린이 고개를 조금 낮추자 벤티는 손을 뻗어 비늘에 얹었다. 이번에는 붙잡기 위해 부르는 이름이 없었다."},{"k":"line","id":"PRO_M04B_이름_013","speaker":"드발린","text":"네 손에 있던 빛이 고통을 걷어 냈다. 내가 너를 공격하는 동안에도 놓지 않았군. 네 이름을 들을 수 있겠느냐?"},{"k":"line","id":"PRO_M04B_이름_014","speaker":"나","text":"{PLAYER_NAME}. 그게 내 이름이야. 지금 말해 두면 다음에 만났을 때는 서로 이름을 부를 수 있겠네."},{"k":"line","id":"PRO_M04B_이름_015","speaker":"","text":"용이 이름을 다시 불러 줄 때는 낯선 세계에서 처음 이름을 말했을 때와 다른 기분이었다. 내가 여기 있다는 걸 설명하기 위한 말이 아니라, 방금 함께한 일을 기억할 사람이 받아 가는 이름이었다."},{"k":"choice","group":"G_PRO_M04B_이름_016","options":[{"label":"응, 끝까지 내가 쥐고 있었어. 다만 알베도가 자리를 잡아 주고 벤티가 방향을 알려 줬지. 혼자였으면 빛을 어디로 향할지 보기도 전에 날아갔을걸. 고맙다는 말은 셋 다 들을게.","id":"PRO_M04B_이름_017","items":[{"k":"line","id":"PRO_M04B_이름_018","speaker":"드발린","text":"그들의 도움도 잊지 않겠다. 그러나 빛을 놓지 않은 손은 네 것이었지. 네 이름과 함께 기억하마. 알베도, 네가 세운 발판도 보았다."}]},{"label":"살아서 대답하는 걸 보니까 이제야 끝난 것 같아. 조금 전에는 도와주겠다고 말해 놓고도 어떻게 할지 몰랐거든.","id":"PRO_M04B_이름_019","items":[{"k":"line","id":"PRO_M04B_이름_020","speaker":"벤티","text":"나도 그랬어. 여기로 오면 다른 방법을 찾을 수 있을 거라고 믿었지만, 어떻게 해야 할지는 대답하지 못했지. 네가 그 자리에서 같이 생각해 줬어."},{"k":"line","id":"PRO_M04B_이름_021","speaker":"드발린","text":"나를 막으면서도 무엇이 나를 괴롭게 하는지 살폈군. 앞으로도 지켜보아라. 다시 너희에게 발톱을 세우지는 않겠다."}]}]},{"k":"line","id":"PRO_M04B_이름_022","speaker":"알베도","text":"네가 사람들을 공격하지 않는 상태로 돌아와서 다행이야. 무엇이 너를 그렇게 만들었는지도 알아보고 싶지만, 지금은 질문을 줄일게. 몸을 움직이는 데 불편한 곳이 있다면 그것부터 알려 줘."},{"k":"line","id":"PRO_M04B_이름_023","speaker":"드발린","text":"고통은 사라졌다. 오랫동안 다른 것이 내 몸에 남아 있었던 듯한 감각은 있지만…. 지금 이 몸을 움직이는 것은 나다."},{"k":"line","id":"PRO_M04B_이름_024","speaker":"벤티","text":"그럼 잠깐 쉬자. 여기까지 온 길을 지금 바로 되짚어 날 필요는 없어. 나도 곁에 앉아 있을게."},{"k":"line","id":"PRO_M04B_이름_025","speaker":"나","text":"토벌대 쪽에도 알려야 하지 않아? 네가 여기로 데려왔다는 걸 모르고 계속 찾고 있으면 다시 마주칠 수도 있잖아."},{"k":"line","id":"PRO_M04B_이름_026","speaker":"벤티","text":"맞아. 드발린이 정화됐다는 소식을 전해야 해. 내가 직접 설명할게. 더 이상 아무 말도 없이 그 애를 다른 곳으로 데려가지는 않을 거야."},{"k":"line","id":"PRO_M04B_이름_027","speaker":"알베도","text":"거점에서 기사단에 연락을 보낼 수 있어. 네 설명에 내가 본 일과 구슬의 반응도 함께 붙이자."},{"k":"line","id":"PRO_M04B_이름_028","speaker":"","text":"다시 묶은 구슬을 품에 넣었다. 힘이 있다는 걸 확인한 물건이었지만, 손을 떼자 무슨 생각을 하는지 알 수 없는 작은 구슬로 돌아갔다. 알베도는 물건에서 내 얼굴로 시선을 옮겼다."},{"k":"line","id":"PRO_M04B_이름_029","speaker":"알베도","text":"산 위에서 들은 말이 다시 들리지는 않았어?"},{"k":"line","id":"PRO_M04B_이름_030","speaker":"나","text":"아니. 이번에는 아무 말도 없었어. 그래서 더 모르겠어. 나를 자기 거라고 하던 목소리하고, 이걸로 누굴 구할 수 있다는 일이 어떻게 이어지는지."},{"k":"line","id":"PRO_M04B_이름_031","speaker":"알베도","text":"오늘은 이어진다고 정하지 말자. 목소리를 들은 일과 구슬로 정화한 일을 둘 다 남겨 두면 돼. 지금 억지로 설명을 붙이지 않은 기록이 나중에 도움이 될 거야."},{"k":"line","id":"PRO_M04B_이름_032","speaker":"벤티","text":"그 말은 나도 기억해 둘게. 오늘 네가 해 준 일에 대해서는 내가 아는 만큼 확실하게 말할 수 있어. 내 친구를 구하는 데 함께해 줬어. 고마워."},{"k":"choice","group":"G_PRO_M04B_이름_033","options":[{"label":"그럼 다음에 나를 찾을 때는 네 뒤에 뭐가 있는지부터 말해 줘. 오늘처럼 소개받으면 심장에 안 좋아.","id":"PRO_M04B_이름_034","items":[{"k":"line","id":"PRO_M04B_이름_035","speaker":"벤티","text":"알겠어. 다음에는 뒤에 용이 있는지부터 알려 줄게."},{"k":"line","id":"PRO_M04B_이름_036","speaker":"알베도","text":"용이 아니라도 알려 주는 편이 좋겠어. 오늘 약속을 너무 좁게 정해 두고 싶지는 않네."},{"k":"line","id":"PRO_M04B_이름_037","speaker":"벤티","text":"아하하… 그래. 놀랄 만한 친구를 데려오면 먼저 소개할게."}]},{"label":"친구라는 게 용이었다는 건 오늘 알았고. 다른 친구는 또 뭐야? 미리 말해 줘. 마음의 준비는 해 두게.","id":"PRO_M04B_이름_038","items":[{"k":"line","id":"PRO_M04B_이름_039","speaker":"벤티","text":"음… 지금 바로 떠오르는 건 없어. 아마도. 다음에 데려올 때는 먼저 소개할게."},{"k":"line","id":"PRO_M04B_이름_040","speaker":"알베도","text":"「아마도」가 걸리네. 기록해 둘게."}]}]},{"k":"line","id":"PRO_M04B_이름_041","speaker":"","text":"내가 고개를 끄덕이자 드발린이 낮게 숨을 내쉬었다. 아까 같은 위협적인 소리가 아니어서, 이번에는 누구도 몸을 낮추지 않았다."},{"k":"keep","id":"ISK_M04_B_099"},{"k":"line","id":"PRO_M04B_떠나는_날개_001","speaker":"","text":"드발린이 날개를 천천히 펼쳤다. 벤티는 반사적으로 손을 들었다가 내렸다. 길을 만들 필요가 없었다. 드발린은 바람이 불어오는 쪽을 살피고 자신이 몸을 돌릴 방향을 정했다."},{"k":"line","id":"PRO_M04B_떠나는_날개_002","speaker":"드발린","text":"바르바토스, 나는 먼저 사람이 없는 곳에서 쉬겠다. 다음에 네가 찾아오면 오늘 들은 이름들을 다시 이야기해 줘. 고통 속에서 지나간 날들 대신 기억할 이야기가 필요하다."},{"k":"line","id":"PRO_M04B_떠나는_날개_003","speaker":"벤티","text":"응. 오늘은 끝까지 들려줄 수 있는 이야기가 생겼네. 네가 모르는 장면도 있으니까 잘 기억해 둘게."},{"k":"line","id":"PRO_M04B_떠나는_날개_004","speaker":"나","text":"내가 발판 올라갈 때 소리 지른 건 빼 줘. 그건 내가 위험해서라기보다 바닥이 예고 없이 움직여서 그랬던 거야."},{"k":"line","id":"PRO_M04B_떠나는_날개_005","speaker":"알베도","text":"그 부분은 나도 설명해야겠네. 기록에는 내가 미리 말하지 않았다는 사실을 같이 남길게."},{"k":"line","id":"PRO_M04B_떠나는_날개_006","speaker":"벤티","text":"두 사람 다 자기 대목을 고치려고 하면 노래가 길어지겠는데. 좋아, 급히 짧게 끝내지는 않을게."},{"k":"line","id":"PRO_M04B_떠나는_날개_007","speaker":"","text":"드발린이 먼저 날아올랐다. 바람은 눈을 일으켰지만 길가의 거점으로 꺾여 들어오지 않았다. 몸이 움츠러드는 걸 느끼면서도 고개를 들고 끝까지 봤다. 용이 멀리 날아가는 동안 경보도, 뒤따르는 공격도 없었다."},{"k":"line","id":"PRO_M04B_떠나는_날개_008","speaker":"벤티","text":"나는 기사단에 소식을 전하고 그 애를 찾아갈게. 너희는 좀 쉬어. 이번에는 돌아오는 길에 뭘 더 부탁하지 않을 테니까."},{"k":"line","id":"PRO_M04B_떠나는_날개_009","speaker":"나","text":"그렇게 말하면 오히려 의심부터 하게 되는데. 알았어, 이번에는 믿을게. 기사단에는 우리가 거점에서 쉰다는 말도 전해 줘. 질문할 사람은 여기로 오라고 하고. 내 다리는 오늘 더 부려 먹기 어렵겠어."},{"k":"line","id":"PRO_M04B_떠나는_날개_010","speaker":"벤티","text":"그럴게. 설명을 남기고 움직이겠다는 약속, 바로 지켜야지. 알베도, 나중에 너희 기록도 부탁해."},{"k":"line","id":"PRO_M04B_떠나는_날개_011","speaker":"알베도","text":"준비해 둘게. 네가 드발린을 처음 만난 장소와 이동한 경로도 나중에 들려줘. 오늘은 서로 본 부분이 다르니까."},{"k":"keep","id":"ISK_M04_B_111","text":"벤티가 떠난 뒤에도 하늘을 조금 더 봤다. 알베도는 먼저 걷지 않고 곁에서 같은 방향을 바라봤다. 초록 옷자락마저 보이지 않게 되자 그는 거점 쪽 길을 가리켰다. 내가 고개를 내린 뒤에야 두 사람이 함께 움직였다."},{"k":"line","id":"PRO_M04B_거점의_탁자_001","speaker":"","text":"거점의 탁자 앞에 앉았을 때 의자에 등을 기댄 채 한동안 움직이지 않았다. 알베도가 따뜻한 물이 든 잔을 놓았다. 컵 손잡이는 구슬보다 훨씬 익숙한 모양이었다. 두 손으로 잔을 감싸고 천천히 숨을 내쉬었다."},{"k":"line","id":"PRO_M04B_거점의_탁자_002","speaker":"나","text":"나 원래 오늘 뭐 하러 왔었지? 길드 의뢰 때문에 산에 왔고, 너를 만나고…. 처음 얘기했던 일이 너무 멀리 있는 것 같아."},{"k":"line","id":"PRO_M04B_거점의_탁자_003","speaker":"알베도","text":"맞아. 길드 의뢰로 이 산까지 왔지. 그다음에는 함께 정상에 갔고, 내려오는 길에 벤티를 만났어. 처음 계획한 일과 도중에 생긴 일을 나눠 적자. 빠진 순서가 있으면 말해 줘."},{"k":"line","id":"PRO_M04B_거점의_탁자_004","speaker":"나","text":"의뢰서에는 용이 없었잖아. 하늘에 뜬 거대한 못이 부서진다는 말도 없었고. 이런 날을 다녀왔다고 하면 캐서린이 먼저 어느 부분부터 물어볼까?"},{"k":"line","id":"PRO_M04B_거점의_탁자_005","speaker":"알베도","text":"네가 다친 곳은 없는지부터 묻게 하고 싶네. 그다음에는 내가 쓴 관찰 기록을 함께 내면 될 거야."},{"k":"line","id":"PRO_M04B_거점의_탁자_006","speaker":"나","text":"「특이사항 있음. 사유: 전부.」"},{"k":"line","id":"PRO_M04B_거점의_탁자_007","speaker":"알베도","text":"그 사유는 조금 더 길게 쓰자."},{"k":"line","id":"PRO_M04B_거점의_탁자_008","speaker":"","text":"알베도는 수첩을 탁자 위에 펼쳤다. 올라갈 때 그린 한천의 못 옆에 무너진 뒤의 윤곽을 그렸다. 나는 그림 가장자리를 가리키며 구슬을 처음 본 위치를 말했다. 알베도는 그 부분을 지우지 않고 작은 표식으로 더했다."},{"k":"choice","group":"G_PRO_M04B_거점의_탁자_009","options":[{"label":"용을 구할 수 있다는 건 알아냈네. 사용법 하나 배웠는데 정체는 더 모르겠어. 구슬을 주운 건지 질문 뭉치를 주운 건지…. 그래도 오늘 이걸 놓치지 않은 건 잘한 것 같아.","id":"PRO_M04B_거점의_탁자_010","items":[{"k":"line","id":"PRO_M04B_거점의_탁자_011","speaker":"알베도","text":"할 수 있는 일을 하나 알게 된 거야. 정체를 모두 안다는 뜻은 아니지만, 아무것도 몰랐던 때와 같지도 않아. 네가 느낀 변화도 그렇게 남겨 두자."}]},{"label":"아까 산에서 들은 말까지 쓰면 종이가 좀 무서울 것 같은데. 네 수첩에 이상한 말 남겨도 괜찮아?","id":"PRO_M04B_거점의_탁자_012","items":[{"k":"line","id":"PRO_M04B_거점의_탁자_013","speaker":"알베도","text":"내가 들은 말처럼 쓰지 않으면 괜찮아. 네가 내게 이야기한 내용으로 남길게. 설명할 때 곁에 있었으니까 그건 내가 본 일이기도 하잖아."}]}]},{"k":"line","id":"PRO_M04B_거점의_탁자_014","speaker":"","text":"고개를 끄덕였다. 내가 들은 말을 누군가에게 옮겼고, 그 누군가는 그것을 장난으로 지우거나 진실 전부로 부풀리지 않았다. 알베도가 글을 쓰는 동안 품 안의 구슬은 아무 빛도 내지 않았다."},{"k":"line","id":"PRO_M04B_거점의_탁자_015","speaker":"알베도","text":"그리고 아까 부탁한 그림 말인데. 지금이면 덜 지친 얼굴로 그릴 수 있을 것 같아. 웃고 있는 모습을 남길까, 컵을 꼭 잡고 있는 모습을 남길까?"},{"k":"line","id":"PRO_M04B_거점의_탁자_016","speaker":"나","text":"둘 다 같은 얼굴일 것 같은데. 일단 그려 봐. 내가 다시 산에 오겠다고 하면 그걸 보여 줘. 오늘 얼마나 힘들었는지 잊어버릴 수도 있으니까."},{"k":"line","id":"PRO_M04B_거점의_탁자_017","speaker":"알베도","text":"힘들었던 것만 떠올리는 그림이 되지는 않았으면 해. 다음에는 거점에서 그림만 보고 가도 돼. 이 탁자에서도 그릴 건 꽤 많으니까."},{"k":"keep","id":"ISK_M04_B_126","text":"컵 너머로 웃었다. 알베도가 새 장을 넘겼다. 정상에서 사라진 거대한 형태도, 바람 속에서 몸부림치던 용도 없는 페이지였다. 그 위에 처음 그어진 것은 의자에 앉은 사람의 어깨와, 탁자 위에 놓인 두 개의 잔이었다."},{"k":"keep","id":"ISK_M04_B_END","text":"살아 있던 드발린을 구슬의 힘으로 정화했다. 벤티는 소식을 전하러 떠났고, 나와 알베도는 거점에서 오늘의 일을 기록한다. 구슬은 내가 보관한다."}],"edits":[],"pre":""},{"id":"ISK_M04_K","entry":"ISK_M04_K_001","items":[{"k":"keep","id":"ISK_M04_K_001","text":"먼지가 가라앉은 뒤에도 진은 한동안 누구도 광장 가운데로 다가가지 못하게 했다. 부러진 돌이 아직 비늘 위로 굴러내렸지만, 그 아래 거대한 몸은 움직이지 않았다. 벤티만이 드발린의 얼굴 가까이 서 있었다."},{"k":"line","id":"PRO_M04K_광장_001","speaker":"엠버","text":"진 단장, 뒤쪽 사람들은 다 모였어요. 크게 다친 사람은 없고요. 드발린은… 아직 한 번도 움직이지 않았어요."},{"k":"line","id":"PRO_M04K_광장_002","speaker":"진","text":"알겠어. 사람들을 조금 더 뒤로. 나는 벤티 씨와 함께 확인하겠다."},{"k":"line","id":"PRO_M04K_광장_003","speaker":"","text":"벤티는 손을 뻗어 드발린의 이마에 얹었다. 길을 열고 바람을 다루던 손이었다. 이번에는 바람이 손끝을 따라오지 않았다."},{"k":"line","id":"PRO_M04K_광장_004","speaker":"벤티","text":"드발린. 여기까지 왔어. 네가 얼굴을 돌리지 않아도 볼 수 있는 곳에 있으니까… 내 목소리가 들리면, 조금만."},{"k":"line","id":"PRO_M04K_광장_005","speaker":"","text":"끝맺지 못한 말이 탑 사이로 흩어졌다. 용의 가슴이 오르내리는지 보려고 자리를 옮겼다. 먼지가 움직일 때마다 비늘도 움직인 것 같았지만, 바람이 멎으면 그대로였다."},{"k":"line","id":"PRO_M04K_광장_006","speaker":"나","text":"기절한 건 아닌가요? 너무 크게 떨어져서… 용은 사람하고 다르니까, 우리가 잘못 보고 있을 수도 있잖아요."},{"k":"line","id":"PRO_M04K_광장_007","speaker":"진","text":"저도 그 가능성을 생각하고 확인했습니다. 살아 있다고 판단할 반응이 없습니다."},{"k":"line","id":"PRO_M04K_광장_008","speaker":"벤티","text":"죽었어. 깊이 잠든 것도, 우리를 피하려고 가만히 있는 것도 아니야. 내가 아는 그 애의 숨결이 여기에는 없어."},{"k":"line","id":"PRO_M04K_광장_009","speaker":"","text":"벤티가 말을 마친 뒤에야 내가 기다리던 대답이 무엇이었는지 알았다. 아직 모른다거나, 조금 더 기다리자는 말이었다. 그 말을 가장 하고 싶었을 사람이 먼저 죽음을 인정했다."},{"k":"line","id":"PRO_M04K_광장_010","speaker":"나","text":"…"},{"k":"line","id":"PRO_M04K_광장_011","speaker":"","text":"농담이 하나도 떠오르지 않았다. 떠올랐어도 하지 않았을 것이다."},{"k":"line","id":"PRO_M04K_광장_012","speaker":"엠버","text":"벤티…. 내가 여기 있어도 될까? 뭘 해야 할지는 모르겠지만, 혼자 두고 뒤로 가기는 싫어서."},{"k":"line","id":"PRO_M04K_광장_013","speaker":"벤티","text":"응. 있어 줘. 지금은 노래를 부탁해도 못 부를 것 같으니까, 그냥 같이 있어 줘."},{"k":"line","id":"PRO_M04K_광장_014","speaker":"","text":"엠버가 활을 등에 걸고 내 옆에 섰다. 길드 앞에서 정하지 못한 노래 제목을 떠올렸다. 「돌아와서 밥」. 그 말을 기억하는 것조차 미안해서 입술을 다물었다."},{"k":"line","id":"PRO_M04K_광장_015","speaker":"진","text":"오늘 확인한 일은 제가 직접 보고하겠습니다. 토벌에 성공했다는 보고로 올리지는 않겠어요. 우리가 도착했을 때 드발린은 이미 죽어 있었습니다. 누가, 어떤 방법으로 죽였는지는 아직 모릅니다."},{"k":"line","id":"PRO_M04K_광장_016","speaker":"나","text":"우인단 사당도 그랬어요. 우리가 갔을 땐 이미…. 자꾸 뒤늦게 도착하는 것 같아요."},{"k":"line","id":"PRO_M04K_광장_017","speaker":"진","text":"저도 같은 생각을 하고 있습니다. 하지만 누군가 먼저 움직였다는 느낌만으로 범인을 정할 수는 없습니다. 이번에는 죽음을 직접 확인한 사람이 여럿입니다. 그 사실부터 놓치지 않겠습니다."},{"k":"keep","id":"ISK_M04_K_019","text":"진은 드발린에게 다시 시선을 돌렸다. 기억 속에서는 여기서 드발린과 이야기를 나눴다. 그다음까지 이어지던 이야기가, 눈앞에서는 끝나 있었다."},{"k":"line","id":"PRO_M04K_속삭임_001","speaker":"","text":"시선을 내리는 순간, 누군가 귀 가까이에서 낮게 말했다. 바람이 아닌 말이었다."},{"k":"line","id":"PRO_M04K_속삭임_002","speaker":"","text":"「드래곤 스파인….」"},{"k":"line","id":"PRO_M04K_속삭임_003","speaker":"","text":"옆을 돌아봤다. 엠버는 벤티 곁에 있었고, 진은 뒤쪽 기사에게 지시를 내리고 있었다. 가까이 지나간 사람은 없었다. 같은 말을 다시 들으려고 숨을 멈췼지만 돌이 굴러가는 소리만 났다."},{"k":"line","id":"PRO_M04K_속삭임_004","speaker":"나","text":"방금 드래곤 스파인이라고 한 사람 있어요? 제 바로 옆에서 들렸는데. 엠버, 너는 아니지?"},{"k":"line","id":"PRO_M04K_속삭임_005","speaker":"엠버","text":"아니. 난 아무 말도 안 했어. 어느 쪽에서 들렸는데? 뒤쪽 사람들한테도 물어볼게."},{"k":"line","id":"PRO_M04K_속삭임_006","speaker":"","text":"엠버가 사람들을 돌아보며 같은 질문을 전했다. 벤티도 드발린에게 얹은 손을 거두고 고개를 들었다. 곁에 있던 모두가 이야기를 들었고, 그 말을 했다는 사람은 없었다."},{"k":"line","id":"PRO_M04K_속삭임_007","speaker":"진","text":"들린 말은 그 지명뿐이었습니까? 가라는 말이나, 누가 기다린다는 말은 없었고요?"},{"k":"line","id":"PRO_M04K_속삭임_008","speaker":"나","text":"네. 그 이름만요. 이상하게 또렷해서 잘못 들었다고 넘기기가 어려워요. 그리고… 누가 말했는지도 모르는데 벌써 거기 가 봐야겠다는 생각이 들어요."},{"k":"line","id":"PRO_M04K_속삭임_009","speaker":"벤티","text":"나한테는 들리지 않았어. 바람이 전해 준 말이라고 설명해 주고 싶지만, 그렇게 말할 수는 없겠네."},{"k":"line","id":"PRO_M04K_속삭임_010","speaker":"엠버","text":"드발린을 이렇게 만든 사람이 부른 거면 어떡해? 우리가 따라올 줄 알고 기다리는 걸 수도 있잖아."},{"k":"line","id":"PRO_M04K_속삭임_011","speaker":"나","text":"나도 그게 걸려. 그런데 못 들은 셈 치고 돌아가면, 돌아가서도 계속 생각날 것 같아. 거기 가면 살릴 수 있다는 말은 아니야. 나도 그 말까지 들은 건 아니니까."},{"k":"line","id":"PRO_M04K_속삭임_012","speaker":"","text":"「살릴 수 있다」는 말에 벤티의 시선이 잠깐 움직였다. 내가 어떤 기대를 건드렸는지 뒤늦게 깨달았다."},{"k":"line","id":"PRO_M04K_속삭임_013","speaker":"나","text":"미안. 그 얘기를 꺼내면 안 됐는데."},{"k":"line","id":"PRO_M04K_속삭임_014","speaker":"벤티","text":"알아. 너도 답을 찾고 싶은 거지. 그 마음까지 미안해하지는 마. 다만 살아날 거라는 약속을 가지고 떠나지는 말아 줘. 나도 지금 그 약속을 받으면 놓기 어려울 것 같아서."},{"k":"line","id":"PRO_M04K_속삭임_015","speaker":"진","text":"설산에는 알베도의 연구 거점이 있습니다. 현장 이야기를 전달하고 함께 확인할 사람이 있어요. 목적도 길도 없이 목소리만 따라갈 필요는 없습니다."},{"k":"line","id":"PRO_M04K_속삭임_016","speaker":"엠버","text":"진 단장, 그럼 조사대를 따로 보내실 건가요? 저는 모험가들을 먼저 돌려보내고 따라가도…."},{"k":"line","id":"PRO_M04K_속삭임_017","speaker":"진","text":"엠버, 오늘 온 사람들을 성까지 부탁한다. 네가 모두를 데리고 돌아왔다는 보고를 먼저 듣고 싶다."},{"k":"keep","id":"ISK_M04_K_037","text":"엠버는 나를 보았다가 뒤에서 기다리는 사람들을 돌아봤다. 길에서 이름을 세고 수레를 밀던 사람들이었다. 그녀가 맡은 일은 그들을 여기까지 데려오는 것으로 끝나지 않았다."},{"k":"choice","group":"G_PRO_M04K_속삭임_018","options":[{"label":"진 단장님, 저도 가겠습니다. 혼자 가는 게 무모하다는 건 알아요. 그래도 직접 확인하고 싶어요.","id":"PRO_M04K_속삭임_019","items":[{"k":"line","id":"PRO_M04K_속삭임_020","speaker":"진","text":"그렇다면 혼자 보내지는 않겠습니다. 제가 동행하죠. 저도 이번 일을 보고서로만 받아 보고 끝낼 생각은 없습니다."},{"k":"line","id":"PRO_M04K_속삭임_021","speaker":"엠버","text":"그럼 성까지 가는 동안은 같이 걷자. 바로 산 쪽으로 혼자 빠질 생각은 하지 말고."},{"k":"line","id":"PRO_M04K_속삭임_022","speaker":"나","text":"혼자 빠질 체력도 없어."}]},{"label":"저 목소리를 믿는 건 아니에요. 그렇지만 설산까지 확인하지 않고는 오늘 일을 덮을 수가 없겠어요.","id":"PRO_M04K_속삭임_023","items":[{"k":"line","id":"PRO_M04K_속삭임_024","speaker":"진","text":"저도 목소리를 신뢰해서 움직이는 것은 아닙니다. 확인해야 할 단서가 생겼고, 그 단서를 들은 분이 여기 계시니까요. 제가 함께 가겠습니다."},{"k":"line","id":"PRO_M04K_속삭임_025","speaker":"벤티","text":"그 말이면 됐어. 설산에 가는 이유를 내 친구에게 줄 약속으로 만들지는 말아 줘. 돌아왔을 때, 실제로 본 이야기를 들려주면 좋겠어."}]}]},{"k":"line","id":"PRO_M04K_속삭임_026","speaker":"","text":"진이 귀환할 인원과 현장에 남을 인원을 나눴다. 벤티는 자신이 남겠다고 먼저 말했다."},{"k":"line","id":"PRO_M04K_속삭임_027","speaker":"벤티","text":"여기서 또 혼자 두고 싶지는 않아. 조사가 끝날 때까지 곁에 있을게. 그리고… 노래 제목 생각하라는 부탁은 잠깐 미뤄 두자. 아직 끝이라고 부르고 싶지 않아."},{"k":"line","id":"PRO_M04K_속삭임_028","speaker":"","text":"그가 같은 약속을 기억하고 있었다는 사실에 목이 막혔다. 대답 대신 고개를 끄덕였다. 엠버가 떨어진 명단을 펴 내밀었다. 한 귀퉁이에 흰 먼지가 묻어 있었다."},{"k":"line","id":"PRO_M04K_속삭임_029","speaker":"엠버","text":"돌아갈 사람부터 같이 세자. 네가 부르면 내가 뒤에서 확인할게."},{"k":"line","id":"PRO_M04K_속삭임_030","speaker":"","text":"첫 이름을 읽었다. 대답이 들린 뒤 다음 이름으로 넘어갔다. 오늘은 누구도 노래에 섞어 대답하지 않았다."},{"k":"keep","id":"ISK_M04_K_052","text":"본부에 돌아왔을 때 케이아는 진의 뒤에서 벤티를 찾았다. 아무도 먼저 설명하지 않자 그가 문을 닫았다. 보고를 듣는 동안 펜은 움직였지만, 드발린의 죽음을 확인했다는 대목에서는 멎었다."},{"k":"line","id":"PRO_M04K_본부_001","speaker":"케이아","text":"토벌대가 쓰러뜨린 것도 아니고, 도착했을 때 이미 죽어 있었다는 거군요. 성에는 어떤 말부터 전하실 생각입니까?"},{"k":"line","id":"PRO_M04K_본부_002","speaker":"진","text":"확인한 사실부터. 당장 공격이 오지 않는다고 안심시킬 수는 있어도, 원인이 해결됐다고 발표하지는 않겠어. 드발린의 죽음을 축하할 일처럼 다루지 않도록 부탁한다."},{"k":"line","id":"PRO_M04K_본부_003","speaker":"케이아","text":"알겠습니다. 시뇨라 쪽에서 듣고 싶은 이야기도 아닐 수 있겠군요. 따로 질문할 이유가 하나 더 생겼습니다."},{"k":"line","id":"PRO_M04K_본부_004","speaker":"나","text":"그리고 제가 목소리를 들었어요. 드래곤 스파인이라는 말이었고요. 현장 사람들한테 전부 물었는데, 자기가 말했다는 사람은 없었어요."},{"k":"line","id":"PRO_M04K_본부_005","speaker":"케이아","text":"그 말을 듣고 설산에 가겠다고 했나? 자네 표정을 보니 길을 묻기 위해 온 건 아닌 것 같군."},{"k":"line","id":"PRO_M04K_본부_006","speaker":"나","text":"네. 진 단장님도 같이 가신다고 했고요. 제가 몰래 모시고 나가는 건 아니니까 그렇게 보지는 마세요. 저도 처음엔 놀랐으니까요."},{"k":"line","id":"PRO_M04K_본부_007","speaker":"진","text":"내가 결정한 일이다. 알베도에게 현장 조사를 부탁하고 직접 확인하겠다. 자리를 비우는 동안 성의 경계와 보고 수신은 네게 맡긴다."},{"k":"line","id":"PRO_M04K_본부_008","speaker":"케이아","text":"일을 두고 가시는 건 익숙하지만, 이번에는 책상에 놓아두지 않으셨으면 합니다. 제게 필요한 보고부터 따로 주시죠."},{"k":"line","id":"PRO_M04K_본부_009","speaker":"","text":"진은 서류를 세 묶음으로 나눴다. 당장 처리할 일, 답을 기다리는 일, 현장과 관련된 일. 케이아가 두 묶음을 받았다. 엠버도 귀환 명단을 자기 보고 아래에 끼웠다."},{"k":"line","id":"PRO_M04K_본부_010","speaker":"엠버","text":"진 단장이 없는 동안 성 밖 길은 제가 더 볼게요. 이번에는 저희가 돌아올 곳을 지키고 있을게요."},{"k":"line","id":"PRO_M04K_본부_011","speaker":"나","text":"그 말, 조금 전엔 내가 했어야 하는 거 같은데. 또 먼저 듣네."},{"k":"line","id":"PRO_M04K_본부_012","speaker":"엠버","text":"응. 그러니까 설산에서는 단장님보다 먼저 뛰어나가지 마."},{"k":"line","id":"PRO_M04K_본부_013","speaker":"케이아","text":"그건 단장 대행님께도 부탁해야 할 것 같은데. 두 분 다 뭔가 보이면 혼자 먼저 확인하려는 표정이라서 말이야."},{"k":"line","id":"PRO_M04K_본부_014","speaker":"진","text":"이번에는 서로 확인하겠다."},{"k":"line","id":"PRO_M04K_본부_015","speaker":"","text":"진은 서류를 넘긴 뒤에도 곧바로 문으로 향하지 않았다. 비어 있는 의자를 한 번 보고, 내가 있는 쪽으로 걸어왔다."},{"k":"line","id":"PRO_M04K_본부_016","speaker":"진","text":"앞으로 이번 일을 조사하는 동안 당신과 함께 움직이고 싶습니다. 목소리를 들은 사람을 지켜보겠다는 뜻만은 아닙니다. 폐허까지 가는 길에서 당신이 한 일을 봤고, 앞으로도 서로 필요한 말을 나눌 수 있다고 생각해요."},{"k":"choice","group":"G_PRO_M04K_본부_017","options":[{"label":"좋아요. 다만 제가 아는 얘기를 전부 맞는 말로 받아들이시면 곤란해요. 오늘도 크게 틀렸잖아요.","id":"PRO_M04K_본부_018","items":[{"k":"line","id":"PRO_M04K_본부_019","speaker":"진","text":"그래서 틀렸다고 말할 수 있는지도 보았습니다. 저는 옆에서 그런 말을 해 줄 동료가 필요합니다. 물론 제가 앞서가는 때에도 멈춰 달라고 말씀하셔야 해요."},{"k":"line","id":"PRO_M04K_본부_020","speaker":"나","text":"그건 좀 어려운 부탁이네요. 단장님한테 「잠깐만요, 그건 아닌 것 같은데요」 하면 주변 기사들부터 저를 볼 텐데."},{"k":"line","id":"PRO_M04K_본부_021","speaker":"진","text":"그때는 제가 먼저 듣겠습니다. 직함 때문에 필요한 말이 늦어지는 건 원하지 않아요."}]},{"label":"함께 가요. 대신 둘 다 멀쩡한 척하다가 쓰러지는 건 금지예요.","id":"PRO_M04K_본부_022","items":[{"k":"line","id":"PRO_M04K_본부_023","speaker":"진","text":"좋은 약속이군요. 저도 지키도록 하겠습니다. 먼저 말씀드리면, 떠나기 전에 잠깐 앉아 쉬고 싶어요."},{"k":"line","id":"PRO_M04K_본부_024","speaker":"나","text":"저도요. 사실 폐허에서부터 그 말 하고 싶었어요."}]}]},{"k":"keep","id":"ISK_M04_K_077"},{"k":"line","id":"PRO_M04K_본부_025","speaker":"","text":"진은 실제로 의자에 앉았다. 맞은편에 앉아 짐끈을 풀었다. 아무도 대단한 각오를 덧붙이지 않았다. 함께 가겠다는 말이 먼저 있었고, 그 말을 한 두 사람이 같은 자리에서 숨을 돌렸다."},{"k":"keep","id":"ISK_M04_K_079","text":"설산의 연구 거점에 도착했을 때 알베도는 천막 앞에서 기록판을 거두고 있었다. 진을 보고 자리를 비워 준 그는, 내 눈이 낯선 도구들 사이를 옮겨 다니는 것을 보고 입구 곁에 의자도 하나 꺼내 놓았다."},{"k":"line","id":"PRO_M04K_설산_001","speaker":"알베도","text":"진 단장, 보고는 읽었습니다. 현장에 함께 계셨던 분이군요. 난 알베도야. 따뜻한 물부터 줄게. 올라오는 동안 말하기 어려웠던 이야기가 있다면 여기서 해도 돼."},{"k":"line","id":"PRO_M04K_설산_002","speaker":"나","text":"{PLAYER_NAME}이야. 길에서 계속 생각했는데 설명할 게 더 생기지는 않더라. 드발린이 죽은 걸 봤고, 그 뒤에 설산 이름을 들었어. 그게 다야."},{"k":"line","id":"PRO_M04K_설산_003","speaker":"알베도","text":"네가 직접 들은 건 그 한마디구나. 보고에 적힌 설명과 네 설명 사이에 차이가 없는지 묻고 싶었어. 지금은 같아 보이네. 목소리에 다른 소리가 겹치지는 않았어?"},{"k":"line","id":"PRO_M04K_설산_004","speaker":"나","text":"다들 움직이고 있었는데, 그 말만 바로 옆에서 한 것처럼 들렸어. 소리 크기는 기억나는데 목소리 주인이 어떻게 생겼을지는 전혀 모르겠고."},{"k":"line","id":"PRO_M04K_설산_005","speaker":"진","text":"이곳에서 비슷한 현상이 보고된 적이 있나?"},{"k":"line","id":"PRO_M04K_설산_006","speaker":"알베도","text":"지명만 속삭였다는 사례는 제 기록에 없습니다. 다만 정상 부근의 구조물은 계속 관측하고 있어요. 직접 확인할 지점은 있습니다."},{"k":"line","id":"PRO_M04K_설산_007","speaker":"나","text":"정상이라는 말이 나오니까 갑자기 의자가 더 편해지네. 여기 오는 것도 꽤 올라온 줄 알았는데."},{"k":"line","id":"PRO_M04K_설산_008","speaker":"알베도","text":"많이 올라온 건 맞아. 그래서 여기서 몸을 풀고 출발하는 게 좋아. 말로 길게 설명하는 것보다 내가 그려 둔 기록을 보는 편이 빠르겠어."},{"k":"line","id":"PRO_M04K_설산_009","speaker":"","text":"알베도가 펼친 종이에는 같은 능선이 다른 빛 아래서 그려져 있었다. 진은 기록된 시각을 읽었고, 나는 그림의 모양을 먼저 봤다."},{"k":"line","id":"PRO_M04K_설산_010","speaker":"나","text":"같은 데를 여러 번 그렸네. 변한 곳을 찾으려는 거야?"},{"k":"line","id":"PRO_M04K_설산_011","speaker":"알베도","text":"그래서 날짜를 적어 둬. 기억만으로 비교하면 내가 보고 싶었던 모습을 실제로 본 것처럼 느낄 때가 있어."},{"k":"line","id":"PRO_M04K_설산_012","speaker":"","text":"폐허에서 머릿속의 이야기를 되짚던 내 모습을 떠올렸다. 진도 같은 생각을 했는지 시선이 잠깐 마주쳤다."},{"k":"line","id":"PRO_M04K_설산_013","speaker":"나","text":"나는 기억하고 있던 게 맞을 거라고 너무 오래 생각했어. 틀린 게 나와도 조금 다르게 이어지는 건가 하고. 오늘은 그게 통하지 않는 장면까지 본 거고."},{"k":"line","id":"PRO_M04K_설산_014","speaker":"알베도","text":"그 기억이 어떤 것이었는지는 지금 다 설명하지 않아도 돼. 네가 기대했던 모습과 실제로 본 모습을 구분해서 말해 주면 들을 수 있어. 그림을 두 장 나란히 놓는 것처럼."},{"k":"line","id":"PRO_M04K_설산_015","speaker":"진","text":"기대했던 쪽을 지워 버릴 필요도 없겠군. 차이가 어디서 생겼는지 확인하는 데 도움이 될 수 있으니."},{"k":"line","id":"PRO_M04K_설산_016","speaker":"나","text":"그럼 내가 기억하는 얘기는 옆에 놓고, 지금 그림에 있는 길부터 보자. 이번에는 답부터 정해 놓고 현장을 거기에 끼워 맞추고 싶지는 않아."},{"k":"line","id":"PRO_M04K_설산_017","speaker":"알베도","text":"이 구간까지는 기존 길을 따라갈 수 있어. 그 위에서는 내가 먼저 발 디딜 곳을 볼게. 기록판은 네가 들어 줄 수 있을까?"},{"k":"line","id":"PRO_M04K_설산_018","speaker":"나","text":"그건 할 수 있어. 그림을 더 그리라고 하는 것만 아니면. 내가 그리면 돌이랑 사람 구분부터 새로 설명해야 할걸."},{"k":"line","id":"PRO_M04K_설산_019","speaker":"알베도","text":"돌과 사람을 헷갈리게 그리는 이유는 나중에 물어볼게. 지금은 판을 어느 쪽으로 잡아야 덜 흔들리는지만 같이 보자."},{"k":"line","id":"PRO_M04K_설산_020","speaker":"","text":"처음으로 작은 웃음이 세 사람 사이에 돌았다. 웃고 나서 잠깐 죄책감을 느꼈다. 진은 그 얼굴을 보고도 웃음을 거두라고 하지 않았다."},{"k":"line","id":"PRO_M04K_등반_001","speaker":"","text":"정상으로 향하는 길에서는 이야기를 길게 하기 어려웠다. 알베도는 앞에서 지형을 살폈고, 진은 내 뒤에서 기록판이 바위에 걸리지 않도록 봐 줬다. 고맙다는 말을 하려다 숨이 차서 고개만 돌렸다."},{"k":"line","id":"PRO_M04K_등반_002","speaker":"진","text":"지금은 대답하지 않으셔도 됩니다. 앞의 바위까지 가서 쉬죠. 저도 잠깐 짐을 내려놓고 싶습니다."},{"k":"line","id":"PRO_M04K_등반_003","speaker":"나","text":"진짜요? 저 때문에 쉬자고 하시는 거면 그냥 그렇게 말해도 돼요."},{"k":"line","id":"PRO_M04K_등반_004","speaker":"진","text":"정말입니다. 제가 계속 괜찮다고만 말하지 않기로 했잖아요. 그 약속을 지키기에는 산길이 꽤 좋은 장소군요."},{"k":"line","id":"PRO_M04K_등반_005","speaker":"","text":"눈 위에서 무언가 움직였다. 알베도가 손을 들었다."},{"k":"line","id":"PRO_M04K_등반_006","speaker":"알베도","text":"바위 뒤에 뭔가 있어. 심연 쪽 기운이야. 두 사람 다 내 옆으로."},{"k":"combat","id":"PRO_M04K_등반_007","group":"EG_MOND_ABYSS_MAGE","text":"눈보라 속에서 나타난 심연 메이지. 좁은 능선에서 세 사람이 맞선다."},{"k":"line","id":"PRO_M04K_등반_008","speaker":"","text":"마지막 방패가 깨지자 알베도가 기록판을 돌려받아 눈을 털어 냈다."},{"k":"line","id":"PRO_M04K_등반_009","speaker":"알베도","text":"그 바위 뒤는 바람이 덜 불어. 두 사람 다 거기서 기다려 줘. 바로 위가 끊기지 않았는지만 보고 돌아올게."},{"k":"line","id":"PRO_M04K_등반_010","speaker":"","text":"알베도가 살피러 간 동안 진은 짐을 내려놓았다. 그녀도 손바닥을 펴서 끈이 눌린 자리를 문지르는 것을 봤다. 본부에서는 늘 다음 보고를 받을 준비가 된 사람처럼 보였는데, 여기서는 같은 오르막을 올라온 사람이었다."},{"k":"line","id":"PRO_M04K_등반_011","speaker":"나","text":"본부에 두고 온 일이 자꾸 생각나시죠? 저는 지금도 엠버가 돌아가서 뭐라고 보고했을지 궁금한데."},{"k":"line","id":"PRO_M04K_등반_012","speaker":"진","text":"생각납니다. 하지만 맡긴 일을 계속 제 머릿속에서 다시 처리하면, 케이아에게 맡긴 의미가 없어지겠죠. 쉽지는 않네요."},{"k":"line","id":"PRO_M04K_등반_013","speaker":"나","text":"그럼 본부 쪽 걱정은 잠깐 두시고, 뒤쪽은 제가 볼게요. 제가 멈추면 두 분도 세워도 되는 거죠? 산 위에서까지 씩씩한 척하다가 혼자 남고 싶지는 않으니까요."},{"k":"line","id":"PRO_M04K_등반_014","speaker":"진","text":"그것이면 충분합니다. 저도 당신이 힘들어 보이면 먼저 묻겠습니다. 단장실에서보다 여기서 듣기 편한 대답도 있을 테니까요."},{"k":"keep","id":"ISK_M04_K_113","text":"알베도가 돌아와 길이 이어져 있다고 알렸다. 기록판에 쉰 자리를 작게 표시했다. 진이 그 표시를 보고 같은 곳을 기억해 두겠다고 말했다. 내려오는 길에도 세 사람이 함께 이 자리를 지날 것이라고, 그때는 자연스럽게 생각했다."},{"k":"line","id":"PRO_M04K_한천의_못_001","speaker":"","text":"능선을 벗어나자 거대한 구조물이 시야를 차지했다. 먼저 끝을 올려다보고, 그 뒤에야 그것이 어디에도 닿지 않고 떠 있다는 것을 알아차렸다."},{"k":"line","id":"PRO_M04K_한천의_못_002","speaker":"알베도","text":"한천의 못이야. 오늘 확인하려던 구조물이지. 아래에서 보던 기록과 실제 모습이 다른 부분이 있으면 여기서부터 살펴보자."},{"k":"line","id":"PRO_M04K_한천의_못_003","speaker":"나","text":"이름은 못인데 크기는 건물이네. 저게 떠 있는 걸 아래에서 보고 살면 하늘 볼 때마다 신경 쓰일 것 같아."},{"k":"line","id":"PRO_M04K_한천의_못_004","speaker":"진","text":"저도 직접 보니 거리감이 다릅니다. 이곳에서 목소리가 다시 들리거나 몸에 이상이 느껴지면 바로 말씀해 주세요."},{"k":"line","id":"PRO_M04K_한천의_못_005","speaker":"나","text":"지금은 아무 소리도 안 들려요. 바람 말고는요. 귀를 기울이면 또 들릴 것 같아서 계속 기다리고 있긴 했는데."},{"k":"line","id":"PRO_M04K_한천의_못_006","speaker":"알베도","text":"기다린다고 같은 현상이 반복되지는 않을 수 있어. 지금은 들리지 않는다는 것까지 함께 기억하자. 못 아래쪽부터 볼게. 판을 조금만…."},{"k":"line","id":"PRO_M04K_한천의_못_007","speaker":"","text":"알베도가 말을 멈췼다. 그가 보는 곳에서 작은 가루가 떨어지고 있었다. 바람에 날리는 눈과 달리 곧게 떨어졌다. 진이 내 어깨를 잡아당기는 것과 거대한 구조물이 기울어지는 일이 거의 동시에 일어났다."},{"k":"line","id":"PRO_M04K_한천의_못_008","speaker":"진","text":"뒤로! 알베도, 이쪽으로!"},{"k":"line","id":"PRO_M04K_한천의_못_009","speaker":"","text":"한천의 못이 추락했다. 땅에 닿은 부분부터 균열이 번지고, 긴 몸체가 여러 조각으로 부서졌다. 기록판을 놓치며 몸을 숙였다. 진이 앞을 막았고 알베도가 팔을 잡았다. 충격이 바위에 부딪쳐 되돌아오는 동안 누구도 일어서지 않았다."},{"k":"line","id":"PRO_M04K_한천의_못_010","speaker":"","text":"소리가 멎어 갈 때 이를 악물고 귀를 기울였다. 이번에도 누군가 말할 것 같은 두려움이 먼저 들었다. 속삭임은 없었다."},{"k":"line","id":"PRO_M04K_한천의_못_011","speaker":"알베도","text":"큰 파편은 멈췼어. 몸을 움직일 수 있겠어? 진 단장, 위쪽 사면을 봐 주세요. 아래 잔해는 제가 확인하겠습니다."},{"k":"line","id":"PRO_M04K_한천의_못_012","speaker":"나","text":"잠깐. 가운데에 뭐가 있어. 깨진 돌 사이에 둥근 게 보여. 저것도 원래 안에 있던 거야?"},{"k":"keep","id":"ISK_M04_K_126","text":"손안에 들어갈 만큼 작은 수정구슬이 잔해 가운데 드러나 있었다. 알베도는 곧장 손을 뻗지 않고 멀리서 모양을 살폈다. 진이 내 곁에 서자, 구슬 뒤쪽의 눈 위로 거대한 그림자가 지나갔다."},{"k":"line","id":"PRO_M04K_한천의_못_013","speaker":"","text":"처음에는 한천의 못의 다른 파편이 떨어지는 줄 알았다. 그러나 그림자가 바위의 방향과 다르게 움직였고, 눈밭 위로 바람이 밀려왔다. 거대한 날개가 눈먼지를 가르며 펼쳐졌다."},{"k":"line","id":"PRO_M04K_한천의_못_014","speaker":"","text":"드발린이었다."},{"k":"line","id":"PRO_M04K_한천의_못_015","speaker":"나","text":"…진 단장님. 저기 있는 거, 저만 보고 있는 거 아니죠?"},{"k":"line","id":"PRO_M04K_한천의_못_016","speaker":"진","text":"저도 보고 있습니다. 제 뒤로 오세요. 알베도, 가까운 퇴로가 어디지?"},{"k":"line","id":"PRO_M04K_한천의_못_017","speaker":"","text":"폐허에서 확인했던 얼굴과 날개였다. 광장에 늘어져 있던 목이 이번에는 살아 있는 힘으로 움직였고, 가슴이 크게 부풀었다."},{"k":"line","id":"PRO_M04K_한천의_못_018","speaker":"알베도","text":"오른쪽 바위 뒤로 이어집니다. 하지만 저 몸으로 길을 막으면 내려가는 건 어려워요. 보고하신 드발린이 맞습니까?"},{"k":"line","id":"PRO_M04K_한천의_못_019","speaker":"진","text":"맞아. 현장에서 죽음을 확인했다. 그 판단을 철회할 상황이 아니다. 지금 우리가 보고 있는 건, 죽었던 드발린이 다시 움직이고 있다는 일이야."},{"k":"line","id":"PRO_M04K_한천의_못_020","speaker":"나","text":"기절해 있었던 거라고 말해 주면 차라리 이해하겠는데. 벤티가 했던 말도, 우리가 본 것도 전부… 아니. 그건 없어지는 게 아니지."},{"k":"line","id":"PRO_M04K_한천의_못_021","speaker":"","text":"드발린이 머리를 낮췄다. 살아 있다는 사실을 기뻐할 시간은 없었다. 시선은 세 사람에게 고정되어 있었고, 포효에 밀린 눈이 발목을 덮었다. 알베도가 나를 잔해에서 떨어뜨렸다. 수정구슬은 손에 들어오지 않은 채 무너진 구조물 가운데 남았다."},{"k":"line","id":"PRO_M04K_한천의_못_022","speaker":"알베도","text":"저쪽 눈은 이미 무너지고 있어. 발판이 갈라지면 뒤로만 물러서지 말고 옆으로 옮겨."},{"k":"line","id":"PRO_M04K_한천의_못_023","speaker":"진","text":"제가 앞을 맡겠습니다. 함께 움직이기로 한 약속은 그대로예요. 살아 돌아온 이유는 이 공격을 넘긴 뒤에 물어야 합니다."},{"k":"line","id":"PRO_M04K_한천의_못_024","speaker":"나","text":"알겠어요. 옆으로 피할 자리부터 볼게요. 드발린이 왜 돌아왔는지는 살아서 따져야죠. 두 분도 제가 부르면 돌아봐 주세요. 혼자 용 앞에 남는 건 사양할게요."},{"k":"keep","id":"ISK_M04_K_138","text":"거대한 숨결이 바위 위의 눈을 걷어 냈다. 진이 검을 들고, 알베도가 무너지는 발판과 드발린의 움직임을 번갈아 봤다. 두 사람의 위치를 확인한 뒤 몸을 낮췼다. 폐허에서 끝났다고 생각한 날갯짓이 설산 위에서 다시 시작되었다."},{"k":"keep","id":"ISK_M04_K_COMBAT","text":"되살아난 드발린이 공격해 온다. 진·알베도와 함께 첫 공세에 대응한다."},{"k":"keep","id":"ISK_M04_K_END","text":"싸움은 아직 끝나지 않았다. 숨을 고르고 다음 이야기로 넘어가자."}],"edits":[]},{"id":"ISK_M05_AA","entry":"ISK_M05_AA_001","items":[{"k":"keep","id":"ISK_M05_AA_001"},{"k":"keep","id":"ISK_M05_AA_002","text":"몬드의 성문이 보이자 엠버가 먼저 손을 들어 보였다. 성벽 위의 기사가 신호를 알아보고 아래쪽에 소리쳤다. 문이 열리는 소리를 들으며 보폭을 조금 줄였다. 폐허에서는 저만큼 큰 소리가 날 때마다 하늘부터 확인해야 했다. 여기서는 쇠붙이가 제자리에서 움직이고 있을 뿐이었다."},{"k":"line","id":"PRO_M05AA_귀환_001","speaker":"엠버","text":"도착했어. 이제는 그렇게 고개 들고 걷지 않아도 돼. 계속 그러면 성문보다 네 목이 먼저 삐걱거리겠어."},{"k":"line","id":"PRO_M05AA_귀환_002","speaker":"나","text":"확인 중이야. 저 지붕이 날아가지 않고 가만히 있는 게 생각보다 마음에 드네."},{"k":"line","id":"PRO_M05AA_귀환_003","speaker":"엠버","text":"몬드의 지붕들은 대체로 얌전한 편이지. 바람이 심한 날은 빼고. 오늘은 나도 가만있는 지붕이 좋다."},{"k":"line","id":"PRO_M05AA_귀환_004","speaker":"","text":"문 안쪽에는 귀환 소식을 기다리던 사람들이 모여 있었다. 누군가는 일행 뒤에서 용의 그림자를 찾았고, 누군가는 들것의 숫자를 먼저 셌다. 진은 짐을 내려놓고 그들 앞에 섰다. 환호를 부탁하는 연설 대신 드발린이 정화되었으며 공격이 멈췄다는 사실부터 차분히 전했다."},{"k":"line","id":"PRO_M05AA_귀환_005","speaker":"진","text":"당장의 습격 위험은 멎었습니다. 다만 외곽의 피해 확인과 부상자 치료는 계속하겠습니다. 가족이 아직 돌아오지 않았다는 분은 저쪽 접수처에 성함을 남겨 주십시오."},{"k":"line","id":"PRO_M05AA_귀환_006","speaker":"","text":"사람들 사이에서 안도하는 숨이 번졌다. 모두가 곧바로 웃지는 않았다. 부서진 수레를 세우던 상인은 손을 멈췄고, 붕대를 맨 기사는 옆 사람의 어깨에 이마를 잠깐 댔다. 내가 돌아왔다는 말을 누구에게 해야 할지 생각하다가 엠버와 눈이 마주쳤다."},{"k":"line","id":"PRO_M05AA_귀환_007","speaker":"엠버","text":"왜? 어디 두고 온 거 있어?"},{"k":"line","id":"PRO_M05AA_귀환_008","speaker":"나","text":"아니. 그냥, 돌아왔다고 한 번 말해 보고 싶었어."},{"k":"line","id":"PRO_M05AA_귀환_009","speaker":"엠버","text":"응. 잘 돌아왔어. 나는 같이 걸어왔으니까 제대로 증언해 줄 수 있지."},{"k":"line","id":"PRO_M05AA_귀환_010","speaker":"다이루크","text":"물통은 열어 봤나? 폐허에서부터 목소리는 쉬지 않던데. 돌아왔다는 인사까지 끝냈으니 이제 물 마실 틈은 있겠지."},{"k":"line","id":"PRO_M05AA_귀환_011","speaker":"나","text":"한쪽에서는 무사히 왔다고 반겨 주고, 다른 쪽에서는 물통 검사야? 알았어, 마실게. 내가 말하다 멈추면 그때 어디 아프냐고 묻지는 마."},{"k":"line","id":"PRO_M05AA_귀환_012","speaker":"다이루크","text":"물 마실 때만 조용해진다면 그건 나도 알아보겠어."},{"k":"line","id":"PRO_M05AA_귀환_013","speaker":"","text":"진이 그 말에 잠깐 입가를 풀었다. 그러나 기사 하나가 미귀환 인원의 명단을 건네자 다시 서류로 시선을 옮겼다. 폐허에 남은 수색은 끝났다는 통보가 아직 없었다. 품 안의 구슬을 천 너머로 짚었다. 살아 돌아온 사람을 세는 도시에서, 돌아오지 못한 사람의 얼굴이 떠올랐다. 그 얼굴에는 아직 이름이 없었다."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_001","speaker":"","text":"벤티는 해가 낮아질 무렵 성당 아래 계단에서 일행을 불렀다. 드발린의 등에서 내린 뒤 도시 밖에서 걸어 들어왔다고 했다. 망토 자락에는 마른 풀이 붙어 있었고, 어깨에는 하프 꾸러미가 그대로 걸려 있었다."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_002","speaker":"벤티","text":"드발린은 바람이 잘 통하는 곳에 자리를 잡았어. 내가 언제까지 옆에 있어야 하느냐고 물었더니, 내가 먼저 언제까지 이야기할 생각이냐고 묻더라."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_003","speaker":"나","text":"그래서 쫓겨난 거야?"},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_004","speaker":"벤티","text":"쉬고 싶은 친구에게 평온한 시간을 마련해 준 거지. 굳이 그렇게 요약하면 시인이 할 일이 없어지잖아."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_005","speaker":"엠버","text":"다친 곳이나 오염이 다시 나타나지는 않았어?"},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_006","speaker":"벤티","text":"응. 오염은 돌아오지 않았어. 날개도 자기 뜻대로 움직였고. 다만 눈을 감을 때마다 한 번씩 주위를 확인하더라. 오늘은 그 애가 그러고 싶을 만큼 그러게 두려 해."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_007","speaker":"","text":"벤티는 꾸러미를 고쳐 멨다. 하프와 함께 챙겨 온 눈물은 따로 싸여 있었다. 드발린이 정화되었다고 해서 앞서 모은 눈물까지 저절로 달라진 건 아니었다."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_008","speaker":"벤티","text":"하프도 돌려놓고 설명해야겠지. 하프 덕분에 모든 일이 잘 풀렸다고 말하면 멋진 이야기야. 그렇지만 그건 우리가 겪은 이야기하고는 조금 다르니까."},{"k":"choice","group":"G_PRO_M05AA_하프를_돌려놓다_009","options":[{"label":"그 설명은 네가 앞장서 줘. 나는 하프가 왜 안 되는지도 모르고 여기저기 뛰어다녔으니까. 성당 문 앞에서 갑자기 유능한 조수인 척하라고 해도 이번에는 못 해.","id":"PRO_M05AA_하프를_돌려놓다_010","items":[{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_011","speaker":"벤티","text":"알았어. 이번 설명은 내 차례. 네가 용 등에 타고 비명을 질렀다는 대목은 빼 줄게."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_012","speaker":"엠버","text":"그 대목은 내가 진 단장께 이미 보고했어. 너무 큰 소리가 나서 그냥 빼기에는 설명이 안 되더라고."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_013","speaker":"나","text":"그렇게 신속한 보고가 꼭 내 비명에서 빛을 발해야 했을까. 다음에는 착지한 뒤에도 멀쩡히 말하고 있었다는 대목까지 붙여 줘."}]},{"label":"하프는 결국 쓸모가 있었던 거야? 아니면 그냥 무거운 짐이었어? 솔직하게.","id":"PRO_M05AA_하프를_돌려놓다_014","items":[{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_015","speaker":"벤티","text":"둘 다. 소리는 닿았고, 고치지는 못했어. 성당에는 그렇게 말할 거야. 짐이었다는 부분은 빼고."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_016","speaker":"나","text":"그 부분은 내가 기억해 둘게. 사당 세 군데 등불 들고 다닌 사람으로서."}]}]},{"k":"keep","id":"ISK_M05_AA_029","text":"성당에서는 바바라가 하프를 받아 상태를 살폈다. 진의 정식 보고가 이어질 예정이라는 말을 듣고, 그녀는 꾸러미를 조심스럽게 안쪽 탁자에 내려놓았다."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_017","speaker":"벤티","text":"눈물에는 아직 오염이 남아 있어. 이것까지 성당에 맡길 수는 없으니 내가 따로 보관할게."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_018","speaker":"","text":"문턱에 기대지 않고 서 있으려다 자세를 고쳐 잡았다. 바바라는 그 작은 움직임을 놓치지 않았다."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_019","speaker":"바바라","text":"하프 이야기는 잠깐 뒤에도 할 수 있어요. 그전에, 어디 다치셨어요? 아까부터 한쪽 발을 자꾸 빼고 계세요."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_020","speaker":"나","text":"조금 전에 용에서 내려서요. 아직 땅하고 합의가 덜 됐어요."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_021","speaker":"바바라","text":"그럼 땅하고 합의가 끝날 때까지 여기 앉아 계세요. 어느 쪽 발인지 보여 주시고요. 농담은 잘 들었으니까, 이제 제가 그 발이 하는 말도 조금 들어 볼게요."},{"k":"line","id":"PRO_M05AA_하프를_돌려놓다_022","speaker":"벤티","text":"들었지? 우리 둘 다 설명할 게 생겼네."},{"k":"line","id":"PRO_M05AA_골목_001","speaker":"","text":"상태를 확인하고 밖으로 나왔을 때, 엠버는 성당 앞에서 기다리던 기사에게 불려갔다. 엠버는 아래 계단에서 만나자고 말했고, 벤티와 나는 광장을 가로지르는 사람들을 피해 성당 옆길로 접어들었다."},{"k":"line","id":"PRO_M05AA_골목_002","speaker":"","text":"처음에는 빗물이 얼어붙은 줄 알았다. 신발 밑에서 가느다란 소리가 났다. 발을 떼려는 순간 하얀 서리가 구두 옆면을 타고 올라왔다. 벤티가 돌아서며 팔을 뻗었지만, 양옆 골목에서 나타난 우인단 병사들이 길을 막았다."},{"k":"line","id":"PRO_M05AA_골목_003","speaker":"벤티","text":"내 뒤로 와. 발부터 무리해서 빼려 하지 말고…!"},{"k":"line","id":"PRO_M05AA_골목_004","speaker":"","text":"바람이 골목의 먼지를 일으켰다. 그 바람 가운데를 가르며 긴 망토의 여자가 걸어왔다. 손끝을 움직이자 벽면에 얼음이 번졌고, 일어난 바람이 좁은 길 안에서 갈라졌다. 벤티 쪽으로 몸을 틀자 등 뒤에서 팔을 잡아 비트는 손이 붙었다."},{"k":"line","id":"PRO_M05AA_골목_005","speaker":"시뇨라","text":"도시를 한 바퀴 돌아다니느라 바빴나 봐. 기다리는 쪽도 조금은 생각해 줬어야지."},{"k":"line","id":"PRO_M05AA_골목_006","speaker":"벤티","text":"약속을 한 기억은 없는데. 시뇨라, 사람을 기다리는 방법이 무척 차갑구나."},{"k":"line","id":"PRO_M05AA_골목_007","speaker":"시뇨라","text":"아직도 그런 말로 시간을 벌 수 있다고 생각해?"},{"k":"line","id":"PRO_M05AA_골목_008","speaker":"나","text":"찾는 사람이 이쪽이면 다른 사람부터 놓고 말씀하시죠. 길을 이렇게 막아 놓고 뭘…!"},{"k":"line","id":"PRO_M05AA_골목_009","speaker":"","text":"말을 마치기 전에 어깨가 벽에 부딪쳤다. 시야가 흔들렸다. 얼음이 발목을 붙잡고 있었다. 눈앞에서 벤티가 한 걸음 밀려났다. 내 손은 그 망토 끝에도 닿지 못했다."},{"k":"line","id":"PRO_M05AA_골목_010","speaker":"벤티","text":"그 사람은 놔줘. 네 용건에 끼워 넣을 이유가 없잖아."},{"k":"line","id":"PRO_M05AA_골목_011","speaker":"시뇨라","text":"그렇게 아끼는 사람이라면 네가 움직이지 않는 편이 낫겠지."},{"k":"line","id":"PRO_M05AA_골목_012","speaker":"","text":"여자의 손이 벤티의 가슴께로 향했다. 옷감을 붙잡으려는 거라고 생각했다. 그러나 손끝이 닿은 자리에서 빛이 일었고, 벤티의 몸이 크게 굳었다. 이내 그녀의 손에 작은 물체가 들려 나왔다. 장식품이라고 하기에는 그 물건을 빼앗긴 사람의 숨이 너무 거칠었다."},{"k":"line","id":"PRO_M05AA_골목_013","speaker":"벤티","text":"…그걸 가져가서, 네가 원하는 걸 전부 얻을 수 있을 것 같아?"},{"k":"line","id":"PRO_M05AA_골목_014","speaker":"시뇨라","text":"네 걱정을 들어 주러 온 건 아니야."},{"k":"line","id":"PRO_M05AA_골목_015","speaker":"","text":"시뇨라가 손을 거두자 벤티의 무릎이 바닥에 닿았다. 반사적으로 몸을 던졌지만 붙잡힌 팔만 더 아프게 당겨졌다. 골목 입구에서 누군가 달려오는 발소리가 났다."},{"k":"line","id":"PRO_M05AA_골목_016","speaker":"엠버","text":"거기서 뭐 하는 거야! 둘한테서 떨어져!"},{"k":"line","id":"PRO_M05AA_골목_017","speaker":"시뇨라","text":"볼일은 끝났어. 쓸데없는 소동은 더 만들지 마."},{"k":"keep","id":"ISK_M05_AA_053","text":"차가운 안개가 시야를 가렸다. 나를 누르던 손이 놓였을 때는 몸이 이미 앞으로 기울어 있었다. 엠버가 붙들어 주지 않았다면 그대로 얼음 위에 넘어졌을 것이다. 안개가 걷힌 골목 끝에 여자는 없었다. 벤티는 한 손으로 벽을 짚고 숨을 골랐다."},{"k":"line","id":"PRO_M05AA_골목_018","speaker":"나","text":"벤티. 고개 들어 봐. 방금 그 사람이 뭘 가져간 거야? 네 몸에서 뭘…."},{"k":"keep","id":"ISK_M05_AA_055","text":"신의 심장이야. 조금… 앉아서 말해도 될까? 지금 서서 멋있게 설명하면 중간에 넘어질 것 같거든."},{"k":"line","id":"PRO_M05AA_골목_019","speaker":"엠버","text":"설명은 나중에 해도 돼. 여기서 나가자. 내가 사람을 불렀어. 네가 걸을 수 있는지는 네 말보다 내가 보고 정할 거야."},{"k":"line","id":"PRO_M05AA_골목_020","speaker":"","text":"벤티는 웃으려다 숨을 삼켰다. 얼음에서 풀린 발로 그 옆에 쪼그려 앉았다. 조금 전까지 용을 떠나보내며 안심하던 손이, 이제는 눈앞의 사람에게 닿아도 되는지 망설이고 있었다."},{"k":"line","id":"PRO_M05AA_빈_방_001","speaker":"","text":"기사단 본부의 빈 방에는 진과 다이루크가 먼저 와 있었다. 바바라가 벤티의 상태를 살핀 뒤 잠깐 나갔고, 엠버가 문을 닫았다. 창문은 바깥 소리를 들을 만큼만 열어 두었다."},{"k":"line","id":"PRO_M05AA_빈_방_002","speaker":"진","text":"성당 인근에서 외교 사절의 수행원들이 시민을 붙잡고 폭력을 행사했습니다. 그 사실에 대해서는 기사단이 대응하겠습니다. 두 분께서 상황을 스스로 해결하지 못했다고 책임을 느끼실 일이 아닙니다."},{"k":"line","id":"PRO_M05AA_빈_방_003","speaker":"다이루크","text":"교섭 문구를 준비하는 동안 저들은 이미 다음 수를 고르겠지. 이동 경로부터 확인하겠다. 다만 지금 뒤쫓아가서 같은 일을 한 번 더 당할 이유도 없어."},{"k":"line","id":"PRO_M05AA_빈_방_004","speaker":"나","text":"신의 심장이라는 게… 이름만 그런 거야? 아니면 지금 네 안에 진짜 있어야 하는 걸 가져간 거야?"},{"k":"line","id":"PRO_M05AA_빈_방_005","speaker":"벤티","text":"내가 지금 네게 대답하고 있잖아. 그걸 빼앗겼다고 내가 곧 사라지는 건 아니야. 그러니 우선 그 표정부터 조금 풀어도 돼."},{"k":"line","id":"PRO_M05AA_빈_방_006","speaker":"나","text":"농담인지 안심시키는 건지 구분이 안 돼서 그래. 아까도 그렇게 말하다가 네가 쓰러졌어."},{"k":"line","id":"PRO_M05AA_빈_방_007","speaker":"","text":"벤티는 곧바로 대꾸하지 않았다. 탁자 위의 물잔을 두 손으로 감싸고 한참 표면을 내려다봤다. 그 침묵이 길어지자 질문을 더 보태려던 입을 다물었다."},{"k":"line","id":"PRO_M05AA_빈_방_008","speaker":"벤티","text":"안심시키려고 한 말이야. 하지만 내가 멀쩡하다는 뜻으로 들렸다면 잘못 말했네. 빼앗긴 건 사실이고, 아팠어. 네가 붙잡혀 있는 걸 보고도 풀어 주지 못한 것도 사실이고."},{"k":"line","id":"PRO_M05AA_빈_방_009","speaker":"나","text":"나도 네 바로 옆에 있었는데 아무것도 못 했어. 조금 전까지 용이랑 싸웠다고, 뭐라도 할 수 있을 줄 알았나 봐."},{"k":"line","id":"PRO_M05AA_빈_방_010","speaker":"다이루크","text":"용과 싸울 때와는 달랐지. 저들은 둘을 떨어뜨리고 발부터 묶었어. 네가 왜 못 움직였는지까지 혼자 짐작하고 있을 필요는 없어."},{"k":"line","id":"PRO_M05AA_빈_방_011","speaker":"엠버","text":"내가 계단 반대편에만 안 갔어도… 아니. 이 말부터 하면 우리 다 같은 자리에서 맴돌겠네. 다음에 너희가 어디 있는지 확인하는 방법부터 바꿀게."},{"k":"line","id":"PRO_M05AA_빈_방_012","speaker":"진","text":"벤티 씨, 쉬셔야 하는 상황에 죄송하지만 현장에서 빼앗긴 물건과 공개해도 되는 정보의 범위를 말씀해 주실 수 있겠습니까?"},{"k":"line","id":"PRO_M05AA_빈_방_013","speaker":"벤티","text":"응. 신의 심장에 관한 이야기는 이 방 안에서 먼저 하자. 도시 사람들이 드발린 소식을 겨우 받아들인 날이야."},{"k":"line","id":"PRO_M05AA_빈_방_014","speaker":"","text":"벤티는 천천히 설명을 시작했다. 전부 이해한 건 아니었다. 다만 신의 눈과 같은 물건이 아니며, 시뇨라가 노리고 빼앗아 갔다는 것만은 분명했다. 내 품 안에도 설명하지 못하는 물건이 있다는 사실을 떠올렸다."},{"k":"line","id":"PRO_M05AA_빈_방_015","speaker":"","text":"구슬을 싸 둔 천이 느슨해져 있었다. 골목에서 붙잡히는 동안 매듭이 풀린 듯했다. 다시 묶으려다 손을 멈췄다. 투명하던 표면 안쪽에 가느다란 그림자가 보였다. 물에 담긴 실처럼 구부러져 있던 것이 서서히 곧아졌다."},{"k":"line","id":"PRO_M05AA_빈_방_016","speaker":"나","text":"잠깐. 이거 좀 봐 줘. 안쪽에 뭐가 있는데… 아까까지는 없었어."},{"k":"line","id":"PRO_M05AA_빈_방_017","speaker":"","text":"진이 탁자 가운데를 비웠다. 구슬을 천 위에 내려놓았다. 누군가 손을 대기도 전에 빛이 표면을 벗어나 바닥에 길게 드리웠다. 사람 하나가 누울 만한 길이였다."},{"k":"line","id":"PRO_M05AA_빈_방_018","speaker":"엠버","text":"뒤로 물러나! 벤티, 움직이지 말고 거기 있어."},{"k":"line","id":"PRO_M05AA_빈_방_019","speaker":"","text":"빛의 가장자리에서 옷자락이 드러났다. 그다음에는 힘없이 놓인 손. 폐허에서 떨어졌던 사람과 같은 옷, 같은 얼굴이었다. 하늘에서 또 떨어진 것이 아니었다. 비어 있던 바닥 위에 이미 누워 있던 몸의 윤곽이 잠깐 드러난 것처럼 보였다. 숨을 들이마신 채 그 모습을 봤다."},{"k":"line","id":"PRO_M05AA_빈_방_020","speaker":"다이루크","text":"그때의 시신이야. 움직이지 마. 문은 내가 보고 있어."},{"k":"line","id":"PRO_M05AA_빈_방_021","speaker":"나","text":"저 사람… 찾고 있었잖아. 분명히 없어졌는데. 지금까지 대체 어디에…."},{"k":"line","id":"PRO_M05AA_빈_방_022","speaker":"","text":"진이 한 걸음 다가갔다. 손을 뻗기 전에 멈춘 것은 유해의 옷자락이 구슬 쪽으로 당겨지는 모습을 봤기 때문이었다. 사람의 몸을 구겨 넣는 움직임은 아니었다. 멀어지는 풍경처럼 형체가 작아졌고, 그 줄어드는 방향 끝에 구슬이 놓여 있었다."},{"k":"line","id":"PRO_M05AA_빈_방_023","speaker":"진","text":"접촉하지 마십시오. 무엇이 일어나는지 아직 모릅니다. 벤티 씨, 저 반응을 멈출 수 있습니까?"},{"k":"line","id":"PRO_M05AA_빈_방_024","speaker":"벤티","text":"…모르겠어. 지금 힘을 부딪치면 저 유해에 무슨 일이 생길지도 알 수 없어."},{"k":"keep","id":"ISK_M05_AA_082","text":"마지막으로 손의 윤곽이 표면을 지났다. 방 안에 드리웠던 빛이 짧아졌다. 아무도 유해를 들어 옮기지 않았는데 바닥은 다시 비어 있었다. 구슬 안쪽에는 작은 사람의 형체가 남았다. 눈을 감고, 처음 봤을 때와 같은 자세로 움직이지 않는 형체였다."},{"k":"line","id":"PRO_M05AA_빈_방_025","speaker":"","text":"한동안 아무도 말하지 않았다. 엠버가 먼저 탁자 옆의 빈 바닥을 보고 구슬을 봤다. 다이루크는 닫힌 문을 다시 확인한 뒤 손잡이에서 손을 놓았다. 진은 의자를 끌어 내 가까이에 놓았지만 앉으라는 말까지 바로 이어 가지는 못했다."},{"k":"line","id":"PRO_M05AA_빈_방_026","speaker":"엠버","text":"우리… 같은 걸 본 거지? 지금 저 안으로 들어간 거 맞지?"},{"k":"line","id":"PRO_M05AA_빈_방_027","speaker":"다이루크","text":"들어가는 모습을 봤어. 적어도 이 방을 나간 건 아니다."},{"k":"line","id":"PRO_M05AA_빈_방_028","speaker":"나","text":"잠깐만. 그러면 내가 이걸 품에 넣고 여기까지 왔을 때도… 아니, 그건 아직 모르지. 방금 들어갔어. 우리가 본 건 방금이야."},{"k":"line","id":"PRO_M05AA_빈_방_029","speaker":"진","text":"맞습니다. 폐허에서 사라진 뒤 어디에 있었는지는 아직 모릅니다. 지금 눈앞에 드러났고 구슬 안으로 들어갔다는 사실을 나누어 기록하겠습니다."},{"k":"line","id":"PRO_M05AA_빈_방_030","speaker":"","text":"구슬에 손을 대려다 주먹을 쥐었다. 말을 걸면 혹시 대답할 것 같다는 생각이 잠깐 들었다. 하지만 안쪽의 형체는 숨 쉬지도, 이쪽을 보지도 않았다. 그 앞에서 함부로 이름을 지어 부르는 일조차 망설여졌다."},{"k":"line","id":"PRO_M05AA_빈_방_031","speaker":"나","text":"이 사람한테 일어난 일을 누가 설명할 수 있어? 벤티, 너는… 네가 신이라고 했잖아. 이런 걸 본 적이 있어?"},{"k":"line","id":"PRO_M05AA_빈_방_032","speaker":"","text":"벤티는 탁자 가까이로 의자를 옮겼다. 구슬을 들여다볼 때는 조금 전까지 숨기려 하던 피로가 그대로 얼굴에 드러났다. 한쪽 손을 구슬 옆에 놓았다가, 만지지 않은 채 거뒀다."},{"k":"line","id":"PRO_M05AA_빈_방_033","speaker":"벤티","text":"없어. 닮았다고 쉽게 꺼낼 이야기도 없어. 오래 살았다는 게 세상에서 일어나는 일을 전부 안다는 뜻은 아니거든. 신인 나도 이건 알 수 없어."},{"k":"line","id":"PRO_M05AA_빈_방_034","speaker":"나","text":"드발린을 정화한 것도 이 사람 때문이고, 사라졌다가 여기 들어온 것도 이 사람이잖아. 둘이 이어진 일이기는 한 거야?"},{"k":"line","id":"PRO_M05AA_빈_방_035","speaker":"벤티","text":"이어져 보이지만 무엇으로 이어졌는지 모르겠어. 접촉한 뒤 드발린의 오염이 흔들렸다는 건 봤지. 그렇다고 이 구슬이 그 모든 일을 처음부터 일으켰다고 말할 수는 없어. 모르겠다는 말을 자꾸 하게 돼서 미안해."},{"k":"choice","group":"G_PRO_M05AA_빈_방_036","options":[{"label":"솔직히 조금은 기대했어. 네가 「아, 그거」 하고 설명해 주면 좋겠다고. 그래도 아무 답이나 붙잡고 또 뛰어다니기는 싫어. 지금은 모른다는 데서 시작할게.","id":"PRO_M05AA_빈_방_037","items":[{"k":"line","id":"PRO_M05AA_빈_방_038","speaker":"엠버","text":"그럼 아는 사람을 더 찾아보자. 여기서 대답이 안 나왔다고 더는 물을 곳이 없는 건 아니잖아."}]},{"label":"신도 모르는 걸 내가 들고 다니고 있었네. 이럴 줄 알았으면 폐허에서 안 주웠… 아니, 그래도 주머니로 들어왔겠지.","id":"PRO_M05AA_빈_방_039","items":[{"k":"line","id":"PRO_M05AA_빈_방_040","speaker":"엠버","text":"아마도. 그러니까 네 탓은 아니야. 아는 사람을 더 찾아보자. 여기서 대답이 안 나왔다고 더는 물을 곳이 없는 건 아니잖아."}]}]},{"k":"line","id":"PRO_M05AA_빈_방_041","speaker":"","text":"벤티가 그 말에 고개를 들었다. 잠깐 생각하던 그는 창문 바깥의 하늘을 봤다. 아직 저녁빛이 남아 있었다."},{"k":"line","id":"PRO_M05AA_빈_방_042","speaker":"벤티","text":"모락스를 만나 보는 건 어떨까. 리월의 바위 신이야. 나보다 오래 보고, 나와 다른 일들을 겪어 온 존재지. 그라면 내가 알아보지 못한 점을 짚어 줄 수도 있어."},{"k":"line","id":"PRO_M05AA_빈_방_043","speaker":"나","text":"그쪽에서도 신은 평소에 노래 부르다가 골목에서 만날 수 있는 거야? 가서 어디부터 찾아야 하는지도 모르는데."},{"k":"line","id":"PRO_M05AA_빈_방_044","speaker":"벤티","text":"그런 신은 흔하지 않을걸? 내 나름대로 희소성이 있거든. 모락스는 리월 사람들이 제 나라의 신을 찾는 방식부터 알아보는 게 좋겠어. 내가 예전에 그를 알았다는 이유로 지금 만날 장소까지 약속할 수는 없으니까."},{"k":"line","id":"PRO_M05AA_빈_방_045","speaker":"다이루크","text":"찾아갈 이유와 만날 수 있다는 보장은 다른 이야기군. 그래도 이 물건을 가지고 몬드의 같은 사람만 계속 찾아다니는 것보다는 다음 방향이 생겼어."},{"k":"line","id":"PRO_M05AA_빈_방_046","speaker":"진","text":"기사단이 확인한 경위는 문서로 정리해 드리겠습니다. 낯선 나라에서 혼자 납득하기 어려운 사건을 처음부터 증명하실 필요는 없도록요."},{"k":"line","id":"PRO_M05AA_빈_방_047","speaker":"나","text":"리월에 가 볼게요. 이 사람이 누구였는지도 모르는데, 그냥 이상한 물건 하나 얻었다고 넘기기는 싫어요. 적어도 내가 본 게 뭔지는 더 알아보고 싶어요."},{"k":"keep","id":"ISK_M05_AA_103","text":"응. 아는 만큼 도울게. 네가 들고 온 질문을 전부 리월에 떠넘기고 손 털 생각은 없어. 나도 여기서 더 살펴볼 테니까, 답을 찾든 못 찾든 다시 와 줘."},{"k":"line","id":"PRO_M05AA_빈_방_048","speaker":"","text":"천을 다시 펼쳐 구슬을 감쌌다. 겉으로 보이는 크기와 무게는 조금도 달라지지 않았다. 바로 그 점이 더 낯설었다. 주머니에 들어가는 작은 물건을 다루면서, 한 사람이 남겨 놓은 마지막 자리까지 함께 옮기는 기분이 들었다."},{"k":"line","id":"PRO_M05AA_빈_방_049","speaker":"진","text":"출발 준비는 내일 다시 이야기합시다. 오늘은 저희도 당신도 너무 많은 일을 겪었습니다. 지금은 몸을 추스를 곳부터 찾으세요."},{"k":"line","id":"PRO_M05AA_빈_방_050","speaker":"나","text":"네. 오늘은 땅에 붙어 있는 침대부터 찾아볼게요. 창문으로 용이 불러도 못 들은 척할 수 있을 것 같아요."},{"k":"line","id":"PRO_M05AA_빈_방_051","speaker":"엠버","text":"그건 나도 찬성이야. 그리고 용이 정말 찾아오면 내가 문으로 오라고 할게."},{"k":"keep","id":"ISK_M05_AA_108","text":"명예기사 칭호 수여는 본부의 사람들이 일을 멈출 수 있는 시간을 골라 마련되었다. 큰 축제를 서둘러 여는 대신, 현장에 있었던 사람들과 도시를 지킨 사람들이 한 방에 모였다. 빌려 입은 듯 어색하게 옷깃을 만졌다. 엠버가 옆에서 그 손을 보고 웃었다."},{"k":"line","id":"PRO_M05AA_명예기사_001","speaker":"엠버","text":"거기 아무것도 안 묻었어. 다섯 번째 확인 중이야."},{"k":"line","id":"PRO_M05AA_명예기사_002","speaker":"나","text":"용 앞에서는 옷깃에 뭐가 묻어도 아무도 안 봤거든. 여기서는 다들 나만 보잖아. 오늘은 등에 매달려 있지도 않은데 왜 이렇게 손 둘 데가 없지?"},{"k":"line","id":"PRO_M05AA_명예기사_003","speaker":"케이아","text":"그렇다고 여기서도 등을 타고 입장하려고 하지는 마. 천장이 낮아서 멋진 장면이 나오기 어렵거든."},{"k":"line","id":"PRO_M05AA_명예기사_004","speaker":"진","text":"케이아."},{"k":"line","id":"PRO_M05AA_명예기사_005","speaker":"케이아","text":"긴장을 풀어 드리는 중이었습니다, 단장 대행님. 효과는 있는 것 같군요."},{"k":"line","id":"PRO_M05AA_명예기사_006","speaker":"","text":"어깨가 조금 내려갔다. 진은 모두가 앞을 본 것을 확인한 뒤 준비한 문서를 들었다. 그녀가 읽는 이름은 이미 여러 차례 불렸던 이름이었다. 그런데 직함과 함께 들으니 낯선 나라의 서류 한가운데 내가 자리를 얻는 느낌이 들었다."},{"k":"line","id":"PRO_M05AA_명예기사_007","speaker":"진","text":"당신은 몬드를 떠날 수도 있는 상황에서 남아 주셨습니다. 드발린과 맞서는 자리에서는 그를 살리려는 목적을 지켰고, 위험 속에서도 동료들의 말에 귀를 기울였습니다. 페보니우스 기사단은 그 도움에 감사를 표하며, 당신께 명예기사의 칭호를 드립니다."},{"k":"choice","group":"G_PRO_M05AA_명예기사_008","options":[{"label":"감사합니다. 그럼 용 등에 매달려 소리 지른 얘기 옆에 명예기사라는 말도 꼭 붙여 주세요. 앞부분만 퍼지면 제가 조금 억울할 것 같거든요.","id":"PRO_M05AA_명예기사_009","items":[{"k":"line","id":"PRO_M05AA_명예기사_010","speaker":"진","text":"그때 당신이 그 위에 있었다는 사실도, 끝까지 드발린을 살리려 했다는 사실도 함께 전하겠습니다. 다만 비명에 관한 이야기는 제가 칭호를 드리는 것으로 막아 드리기는 어렵겠군요."},{"k":"line","id":"PRO_M05AA_명예기사_011","speaker":"엠버","text":"들었지? 멋있는 뒷부분까지 생겼잖아. 그다음에 어떻게 내려왔는지까지 제대로 말해 줄게."}]},{"label":"감사합니다. 저, 전 직장에서는 표창 한 번 못 받았거든요. 용을 타야 받는 거였나 봐요.","id":"PRO_M05AA_명예기사_012","items":[{"k":"line","id":"PRO_M05AA_명예기사_013","speaker":"케이아","text":"그 직장은 기준이 꽤 높았나 보군. 자네, 여기선 그 정도면 충분해."},{"k":"line","id":"PRO_M05AA_명예기사_014","speaker":"진","text":"케이아. …맞는 말이지만."}]}]},{"k":"line","id":"PRO_M05AA_명예기사_015","speaker":"케이아","text":"벌써 증인까지 확보했군. 몬드 생활에 금방 적응하겠어. 그럼 나는 그 이야기를 들을 시간이 언제쯤 생기는지만 알아보면 되겠네."},{"k":"line","id":"PRO_M05AA_명예기사_016","speaker":"다이루크","text":"그 농담은 네 야근부터 끝내고 해도 늦지 않을 텐데."},{"k":"keep","id":"ISK_M05_AA_121","text":"방 안에 웃음이 번졌다. 진에게서 칭호를 인정하는 문서를 받았다. 손에 잡히는 건 얇은 종이였지만, 폐허에서 누군가 내 목소리를 알아듣고 돌아봐 주던 순간들이 그 안에 함께 묶이는 기분이었다."},{"k":"line","id":"PRO_M05AA_명예기사_017","speaker":"진","text":"리월에 가져가실 경위서는 준비하겠습니다. 돌아오시면 기사단에도 들러 주세요. 오늘처럼 보고만 길게 받지는 않겠습니다."},{"k":"line","id":"PRO_M05AA_명예기사_018","speaker":"나","text":"그 약속은 기억해 둘게요. 돌아오자마자 밤새 보고하는 건 피하고 싶거든요. 그래도 제가 찾아낸 건 제 입으로 말씀드릴게요. 빈손으로 와도 얼굴까지 숨기지는 않을 거고요."},{"k":"line","id":"PRO_M05AA_명예기사_019","speaker":"진","text":"좋습니다. 돌아왔다는 인사를 먼저 듣고 나서 다음 이야기를 청하겠습니다. 무사히 다녀오십시오."},{"k":"line","id":"PRO_M05AA_떠나기_전_001","speaker":"","text":"기사단 문을 나서자 엠버가 남쪽 길이 표시된 지도를 건넸다. 갈 곳과 챙길 물건은 정해졌다. 다만 구슬에 관해 적은 기록을 공방에 맡길지 잠시 망설였다. 알베도는 출발을 늦출 필요는 없다고 전해 왔다."},{"k":"choice","group":"G_PRO_M05AA_떠나기_전_002","options":[{"label":"출발 전에 알베도한테 구슬 기록부터 맡기고 가자.","keep":"ISK_M05_AA_126","items":[{"k":"line","id":"PRO_M05AA_떠나기_전_003","speaker":"","text":"공방 안에서는 알베도가 기사단에서 받은 보고서를 읽고 있었다. 내가 꺼낸 기록을 탁자 위에 펼치고, 실제로 본 부분에만 표시를 부탁했다. 구슬은 가방 속에 그대로 두었다."},{"k":"line","id":"PRO_M05AA_떠나기_전_004","speaker":"알베도","text":"이 기록이면 네가 없는 동안에도 살펴볼 수 있겠어. 구슬을 두고 갈 필요는 없어. 네가 직접 본 일과 다른 사람에게 들은 일만 구분해 주겠니?"},{"k":"line","id":"PRO_M05AA_떠나기_전_005","speaker":"나","text":"바로 열어 보자는 말이 안 나와서 다행이네. 나도 뚜껑이 있는 물건인지부터 모르겠거든."},{"k":"line","id":"PRO_M05AA_떠나기_전_006","speaker":"알베도","text":"뚜껑만 열면 되는 문제였다면 나도 반가웠겠지. 지금은 네 설명부터 듣는 편이 낫겠어. 그 자리에 있던 사람들이 남긴 기록도 있으니, 서로 같은 장면을 어떻게 봤는지 대조할 수 있어."},{"k":"line","id":"PRO_M05AA_떠나기_전_007","speaker":"","text":"빛을 본 순간과 유해를 발견한 순간을 따로 적었다. 알베도는 종이를 넘기다 두 군데에 작은 물음표를 남겼다. 당장 답을 내리거나 구슬을 열어 보자고 하지는 않았다."},{"k":"line","id":"PRO_M05AA_떠나기_전_008","speaker":"알베도","text":"리월에서 다른 설명을 듣게 되면 알려 줘. 내 생각과 맞지 않아도 괜찮아. 그 차이가 단서일 수 있으니까. 이 사본은 내가 보관할게."},{"k":"line","id":"PRO_M05AA_떠나기_전_009","speaker":"","text":"기록의 사본을 맡기고 공방을 나왔다. 질문은 여전히 남아 있었지만, 떠나기 전에 해야 할 일은 하나 줄었다. 엠버가 성문 쪽으로 손을 들어 보였다."}]},{"label":"기록은 돌아와서 전하자. 오늘은 바로 성문으로 가야겠어.","keep":"ISK_M05_AA_DEPART_DIRECT","items":[{"k":"line","id":"PRO_M05AA_떠나기_전_010","speaker":"","text":"지도를 접어 넣었다. 알베도에게는 돌아와서 직접 설명하기로 했다. 엠버가 성문 쪽으로 손을 들어 보였다."}]}]},{"k":"line","id":"PRO_M05AA_떠나기_전_011","speaker":"","text":"성문으로 향하는 길에서 다이루크를 만났다. 와이너리로 돌아가는 수레 옆에서 짐을 확인하던 그는 내 가방을 보고 고개를 들었다."},{"k":"line","id":"PRO_M05AA_떠나기_전_012","speaker":"다이루크","text":"이제 떠나는 건가."},{"k":"line","id":"PRO_M05AA_떠나기_전_013","speaker":"나","text":"응. 그런데 너한테 인사는 하고 가야 할 것 같아서. 처음에는 네 정보망을 빌리면 눈물 찾는 일이 전부 끝날 줄 알았는데, 여기까지 올 줄은 몰랐네."},{"k":"line","id":"PRO_M05AA_떠나기_전_014","speaker":"다이루크","text":"나도 같은 생각이야. 하프를 되찾으면 문제가 얼마나 풀릴지 따지던 때와는 상황이 달라졌지. 그래도 네가 드발린의 등에서 살아 내려왔다는 사실은 달라질 필요가 없겠군."},{"k":"line","id":"PRO_M05AA_떠나기_전_015","speaker":"나","text":"그 얘기는 몬드를 떠나도 따라오겠다. 리월에서 멀쩡히 다녀왔다는 이야기 하나쯤 새로 만들어 볼게. 도와줘서 고마웠어."},{"k":"line","id":"PRO_M05AA_떠나기_전_016","speaker":"다이루크","text":"돌아오면 천사의 몫으로 와. 내가 없으면 직원에게 이름을 남기고. 용의 등에서 들려온 비명보다 듣기 편한 이야기를 기대하겠어."},{"k":"line","id":"PRO_M05AA_떠나기_전_017","speaker":"나","text":"거기 가면 물 말고 다른 것도 주는 거지?"},{"k":"line","id":"PRO_M05AA_떠나기_전_018","speaker":"다이루크","text":"돌아온 다음에 보자."},{"k":"line","id":"PRO_M05AA_떠나기_전_019","speaker":"","text":"다이루크가 먼저 길을 비켰다. 수레는 와이너리 쪽으로, 나는 엠버와 성문 쪽으로 향했다. 처음 사당에 갔을 때와 달리, 이번에는 내가 어디로 가려는지 알고 있었다."},{"k":"line","id":"PRO_M05AA_떠나기_전_020","speaker":"","text":"성문 밖으로 몇 걸음 나왔을 때 벤티가 다리 난간에서 몸을 일으켰다. 평소처럼 뛰어내리려다 멈추고, 발 디딜 곳을 골라 천천히 내려왔다."},{"k":"line","id":"PRO_M05AA_떠나기_전_021","speaker":"나","text":"이번에는 네가 얌전히 내려오는 걸 내가 확인하네."},{"k":"line","id":"PRO_M05AA_떠나기_전_022","speaker":"벤티","text":"아쉽게도 오늘은 관객을 놀라게 할 묘기를 준비하지 않았거든. 대신 제대로 된 작별 인사 한 번. 잘 다녀와. 모락스를 만날 방법을 찾더라도, 그를 안다는 사람의 말만으로 다 믿지는 말고."},{"k":"line","id":"PRO_M05AA_떠나기_전_023","speaker":"나","text":"네가 추천한 신을 찾으러 가면서 네가 준 충고로 그 신을 안다는 사람들을 의심해야 하네. 생각보다 복잡한 여행이야."},{"k":"line","id":"PRO_M05AA_떠나기_전_024","speaker":"벤티","text":"그렇게 들으니 그렇네. 그래도 네가 질문을 잘한다는 건 알아. 마음에 걸리는 대답을 들었을 때 그냥 넘기지는 않을 테니까."},{"k":"line","id":"PRO_M05AA_떠나기_전_025","speaker":"","text":"벤티의 시선이 내 가방에 잠깐 머물렀다. 구슬 이야기는 꺼내지 않았다. 그는 내 얼굴을 다시 보고 평소보다 낮은 목소리로 덧붙였다."},{"k":"line","id":"PRO_M05AA_떠나기_전_026","speaker":"벤티","text":"그리고 드발린은 네가 살아 돌아왔다는 소식을 들었어. 이번에는 하늘에서 확인하러 오지 않아도 된다고 말해 뒀지. 그 애도 나도, 그날 네가 해 준 일을 기억하고 있어."},{"k":"line","id":"PRO_M05AA_떠나기_전_027","speaker":"나","text":"그 말이면 충분해. 둘 다 좀 쉬어. 돌아와서 만났을 때도 오늘처럼 멀쩡히 말하고 있으면 좋겠어."},{"k":"line","id":"PRO_M05AA_떠나기_전_028","speaker":"벤티","text":"응. 이번에는 그 약속을 가볍게 말하지 않을게."},{"k":"line","id":"PRO_M05AA_떠나기_전_029","speaker":"","text":"벤티는 두 사람이 마저 인사할 수 있게 조금 떨어졌다. 엠버는 성문 쪽으로 한 번 돌아봤다가 내 어깨 끈을 가리켰다. 뒤집힌 부분을 바로잡자 가방이 덜 흔들렸다. 그녀는 손을 떼고도 곧장 돌아서지 않았다."},{"k":"line","id":"PRO_M05AA_떠나기_전_030","speaker":"엠버","text":"이제 정말 가네. 솔직히 말하면, 내가 못 보는 데서 또 용 등에 올라탈까 봐 걱정돼."},{"k":"choice","group":"G_PRO_M05AA_떠나기_전_031","options":[{"label":"리월에서 용을 만나면 우선 땅에서 부를게. 그 약속은 이미 두 번이나 했으니까 이번에는 기억할 수 있을 것 같아.","id":"PRO_M05AA_떠나기_전_032","items":[{"k":"line","id":"PRO_M05AA_떠나기_전_033","speaker":"엠버","text":"세 번째야. 방금 나한테도 했으니까. …농담이야. 약속을 많이 받아 두면 나도 조금 덜 걱정할까 했지. 네가 가고 나면 남쪽 하늘을 자꾸 볼 것 같네. 그러니까 소식은 꼭 전해 줘."},{"k":"line","id":"PRO_M05AA_떠나기_전_034","speaker":"나","text":"응. 그리고 너한테도 소식 보낼게. 오늘은 누구랑 땅 위에서 인사했는지 그런 것부터."},{"k":"line","id":"PRO_M05AA_떠나기_전_035","speaker":"엠버","text":"좋아. 별일 없었다는 편지도 환영이야. 다음에 돌아오면 내가 먼저 발견할지도 몰라. 정찰 기사는 성문 밖도 보거든."}]},{"label":"리월에는 용이 없기를 빌어 줘. 있으면… 그래, 땅에서 부를게. 토끼 백작 걸고.","id":"PRO_M05AA_떠나기_전_036","items":[{"k":"line","id":"PRO_M05AA_떠나기_전_037","speaker":"엠버","text":"토끼 백작을 걸었으면 진짜야. 깨면 내가 몰라. 소식은 꼭 전해 줘. 별일 없었다는 편지도 환영이야."}]}]},{"k":"keep","id":"ISK_M05_AA_232","text":"엠버를 향해 손을 들었다. 그녀가 같은 높이로 손을 들어 답했다. 처음 이 땅에서 길을 몰라 누군가를 따라갔던 걸음과는 달랐다. 이번에는 남쪽으로 가려는 이유를 알고 있었고, 되돌아올 때 누구의 이름을 불러야 할지도 알고 있었다."},{"k":"line","id":"PRO_M05AA_떠나기_전_038","speaker":"","text":"가방 안의 구슬은 조용했다. 안에 있는 유해는 말을 걸지도, 길을 알려 주지도 않았다. 리월의 바위 신을 찾아가 다시 물어야 할 일, 아직 이름조차 모르는 사람. 몬드의 문을 뒤로하는 동안에도 그 두 가지를 따로 기억했다. 다리 끝에서 한 번 돌아봤을 때, 엠버의 손은 아직 올라가 있었다."},{"k":"keep","id":"ISK_M05_AA_END","text":"몬드에서의 큰 고비를 넘겼다. 남은 의뢰를 마치거나 동료들과 시간을 보낼 수 있다. 준비가 되면 메인 임무에서 리월로 향하자."}],"edits":[],"pre":""},{"id":"ISK_M05_AB","entry":"ISK_M05_AB_001","items":[{"k":"keep","id":"ISK_M05_AB_001"},{"k":"keep","id":"ISK_M05_AB_002","text":"다음 날 길드에 들렀을 때 캐서린은 어제 받은 보고서를 펼쳤다. 사당의 위치 아래에는 두 사람의 이름이 나란히 적혀 있었다. 드발린에 관한 보고는 다른 서류에 끼워져 있었다."},{"k":"line","id":"PRO_M05AB_보고_001","speaker":"캐서린","text":"어제 보고는 잘 전달했어. 오늘은 조사 의뢰를 어떻게 남겨 둘지 알려 주려고 불렀어."},{"k":"line","id":"PRO_M05AB_보고_002","speaker":"나","text":"그럼 처음부터 다시 말할 필요는 없는 거지? 어젯밤에는 빠뜨린 말이 있는 것 같아서 잠이 잘 안 오더라."},{"k":"line","id":"PRO_M05AB_보고_003","speaker":"캐서린","text":"새로 떠오른 게 있으면 보태면 돼. 같은 내용을 더 길게 설명한다고 없던 단서가 생기지는 않으니까."},{"k":"line","id":"PRO_M05AB_보고_004","speaker":"다이루크","text":"시신을 수습했다는 연락은?"},{"k":"line","id":"PRO_M05AB_보고_005","speaker":"캐서린","text":"아직 없어. 기사단에서도 그 사당을 정리한 인원을 찾지 못했대. 사망 경위와 시신의 행방을 모두 확인하지 못한 상태야."},{"k":"line","id":"PRO_M05AB_보고_006","speaker":"","text":"접수대의 나뭇결을 손가락으로 쓸었다. 사당에서는 여기로 돌아오면 무슨 설명이라도 들을 줄 알았다."},{"k":"line","id":"PRO_M05AB_보고_007","speaker":"나","text":"조사에 실패했다고 적히겠네. 용이 다시 나타나는 바람에 중간에 그만둔 것도 맞고."},{"k":"line","id":"PRO_M05AB_보고_008","speaker":"캐서린","text":"이번 현장 조사로 진상을 밝히지는 못했어. 그 결과는 그대로 남길 거야. 다만 네가 어디까지 조사했는지와 중단한 이유도 함께 전달했어."},{"k":"line","id":"PRO_M05AB_보고_009","speaker":"다이루크","text":"그 안에서 더 기다렸어도 달라질 건 없었다. 몬드 쪽에서 경보가 들리는데 빈 방을 붙들고 있을 이유도 없었지."},{"k":"line","id":"PRO_M05AB_보고_010","speaker":"나","text":"알아. 그래도 누군가는 그 사람들이 왜 죽었는지 알아야 하잖아. 우리가 처음 봤으니까, 그 누군가가 우리였으면 했나 봐."},{"k":"line","id":"PRO_M05AB_보고_011","speaker":"캐서린","text":"계속 확인할 수 있도록 남겨 둘게. 새로운 단서가 나오면 알려 줄 테니 연락할 곳도 적어 줘."},{"k":"line","id":"PRO_M05AB_보고_012","speaker":"나","text":"응. 사당에서는 더 알아낸 게 없었다고 적어 줘. 괜히 잘한 척하면 나중에 더 곤란하니까. 대신 드발린 쪽은 확실히 성공이야. 어제 그 앞에 서 있었던 것까지 실패로 묶이면 나도 항의할 거거든."},{"k":"keep","id":"ISK_M05_AB_015","text":"항의할 일은 없을 거야. 드발린이 정화되어 떠났다는 보고는 따로 전달했어. 네가 직접 확인한 내용과 함께 말이야. 사당 쪽에 새 단서가 생기면, 그때는 지금 덮어 두는 이 보고를 이어 가자."},{"k":"line","id":"PRO_M05AB_벤치_001","speaker":"","text":"길드 옆 벤치에서 알베도가 수첩을 치우고 자리를 내줬다. 내가 앉자 다이루크는 물병을 건넸다."},{"k":"line","id":"PRO_M05AB_벤치_002","speaker":"알베도","text":"이번에는 의자가 있는 곳을 골랐어. 그림을 보여 주겠다는 약속까지 한꺼번에 지키려 했는데, 지금은 그보다 물이 먼저인 것 같네."},{"k":"line","id":"PRO_M05AB_벤치_003","speaker":"나","text":"확실히 지난번보다 낫다. 네 얼굴 봐도 빈 사당부터 떠오르는 건 조금 덜하네. 아직 아예 안 떠오르는 건 아니고."},{"k":"line","id":"PRO_M05AB_벤치_004","speaker":"알베도","text":"그럼 오늘은 이 그림도 기억해 둬. 네가 내 얼굴을 볼 때마다 한 장면만 떠올리면 나도 좀 곤란하니까."},{"k":"line","id":"PRO_M05AB_벤치_005","speaker":"","text":"수첩에는 들판 쪽으로 몸을 돌린 드발린이 그려져 있었다. 목 아래에는 지워진 선이 여러 겹 남았다."},{"k":"line","id":"PRO_M05AB_벤치_006","speaker":"나","text":"저기서 구슬이 빛났지. 어제는 너무 정신없어서 내가 제대로 들고 있었는지도 잘 기억 안 났는데, 그림으로 보니까 좀 알겠다."},{"k":"line","id":"PRO_M05AB_벤치_007","speaker":"알베도","text":"네가 빛을 놓친 때도 있었어. 그때마다 다시 맞췄고. 한 번에 잘했다고 그리면 네가 실제로 한 일과 달라져."},{"k":"line","id":"PRO_M05AB_벤치_008","speaker":"나","text":"잘 그렸는데, 내가 휘청댄 것까지 그렇게 정확할 필요는 없지 않아? 기왕이면 남한테 보여 줄 때 조금 덜 변명해도 되는 그림이면 좋겠는데."},{"k":"line","id":"PRO_M05AB_벤치_009","speaker":"알베도","text":"그 손은 그대로 두는 편이 그림이 더 좋아. 빛을 다시 맞추려는 움직임이 보이거든."},{"k":"choice","group":"G_PRO_M05AB_벤치_010","options":[{"label":"알베도. 구슬을 준 사람이 왜 나를 골랐는지 물어봐 준다는 건 아직 부탁해도 되는 거지?","id":"PRO_M05AB_벤치_011","items":[{"k":"line","id":"PRO_M05AB_벤치_012","speaker":"알베도","text":"앨리스 아줌마에게 전할 질문은 적어 뒀어. 답을 기다리는 동안에도 구슬의 변화를 함께 살펴볼 수 있어."},{"k":"line","id":"PRO_M05AB_벤치_013","speaker":"나","text":"고맙다고 전할 말도 넣어 줘. 설명을 안 해 줬다고 투덜거리기만 한 사람처럼 보이기는 싫어. 실제로 도움이 됐으니까."},{"k":"line","id":"PRO_M05AB_벤치_014","speaker":"알베도","text":"고맙다는 말을 먼저 적고, 다음 줄에 왜 하필 너였는지 물을게."}]},{"label":"그 앨리스라는 사람, 내 이름을 어떻게 알았을까. 나 여기 와서 이름 말한 데가 본부랑 길드랑 가게 하나뿐인데.","id":"PRO_M05AB_벤치_015","items":[{"k":"line","id":"PRO_M05AB_벤치_016","speaker":"알베도","text":"그것도 물어볼게. 답이 「그냥 알았다」일 가능성은 미리 말해 둬야겠지만."},{"k":"line","id":"PRO_M05AB_벤치_017","speaker":"나","text":"그 답이 제일 무서운데."}]}]},{"k":"line","id":"PRO_M05AB_벤치_018","speaker":"다이루크","text":"알베도, 그 그림에는 뒤쪽 성문도 남겨 둬. 저 친구가 어디를 막고 있었는지 보이게. 기껏 버텨 놓고 구슬 자랑만 하는 그림이 되면 섭섭할 테니."},{"k":"line","id":"PRO_M05AB_벤치_019","speaker":"나","text":"뭐야, 두 사람이 미리 짜고 날 달래는 중이었어? 이 정도로 신경 써 주면 나도 좀 우쭐해지고 싶은데. 그렇게 풀이 죽어 보였나?"},{"k":"line","id":"PRO_M05AB_벤치_020","speaker":"다이루크","text":"물을 반 병 마실 동안 한숨을 네 번 쉬더군."},{"k":"line","id":"PRO_M05AB_벤치_021","speaker":"알베도","text":"나는 세 번부터 세었어. 처음부터 세었다면 다이루크 씨 쪽이 정확하겠네."},{"k":"line","id":"PRO_M05AB_벤치_022","speaker":"나","text":"그런 건 둘이 기록 맞추지 마. 이제 쉬는 것도 측정당하는 것 같잖아."},{"k":"line","id":"PRO_M05AB_벤치_023","speaker":"","text":"알베도가 수첩을 덮었다. 두 사람 사이에 조금 더 앉아 있었다. 본부에서 온 기사가 이름을 부를 때는 무슨 일인지 먼저 물어볼 여유가 생겨 있었다."},{"k":"line","id":"PRO_M05AB_명예_기사_001","speaker":"","text":"본부에서는 진이 방 가운데에서 기다리고 있었다. 엠버가 문을 열어 줬고, 내 뒤로 다이루크와 알베도가 들어왔다."},{"k":"line","id":"PRO_M05AB_명예_기사_002","speaker":"엠버","text":"왔구나! 몸은 좀 어때? 어제 소식 듣고 바로 찾아가려고 했는데, 이번에는 내가 보고 붙잡혀 있었어."},{"k":"line","id":"PRO_M05AB_명예_기사_003","speaker":"나","text":"나도 보고하다가 하루가 끝난 것 같아. 용이랑 싸운 얘기를 세 번쯤 했더니, 네 번째에는 내가 용보다 말할 기운이 없겠더라."},{"k":"line","id":"PRO_M05AB_명예_기사_004","speaker":"엠버","text":"그럼 오늘은 우리가 말할게. 넌 조금만 서 있어. 아니, 힘들면 앉아도 되고!"},{"k":"line","id":"PRO_M05AB_명예_기사_005","speaker":"진","text":"짧게 말씀드리겠습니다. 어제 성 앞에서 드발린을 막고 정화해 주신 일에, 몬드와 페보니우스 기사단을 대표하여 감사를 전합니다."},{"k":"line","id":"PRO_M05AB_명예_기사_006","speaker":"","text":"진은 내가 성문 밖에서 시간을 벌어 준 덕분에 사람들이 대피할 수 있었다고 말했다. 용을 보느라 확인하지 못했던 뒤쪽의 이야기를 그제야 들었다."},{"k":"line","id":"PRO_M05AB_명예_기사_007","speaker":"진","text":"그리고 앞으로도 저희와 뜻을 나눌 동료로서, 당신을 페보니우스 기사단의 명예 기사로 맞이하고 싶습니다."},{"k":"line","id":"PRO_M05AB_명예_기사_008","speaker":"나","text":"저를요? 그… 잠깐만요. 아까 길드에서는 조사 실패했다고 얘기하고 왔는데, 여기서는 명예 기사가 된다고 하니까 머리가 잘 안 따라오네요."},{"k":"line","id":"PRO_M05AB_명예_기사_009","speaker":"진","text":"사당 조사가 미완이라는 사실은 알고 있습니다. 하지만 당신이 몬드를 위해 한 일도 분명히 있어요."},{"k":"line","id":"PRO_M05AB_명예_기사_010","speaker":"다이루크","text":"자네가 잘못 들은 건 아니다. 나도 같은 말을 들었어."},{"k":"choice","group":"G_PRO_M05AB_명예_기사_011","options":[{"label":"다이루크한테 물어보려던 건데 미리 대답해 버리네. 그럼… 제가 내일부터 당직표 같은 데 들어가는 건 아니죠?","id":"PRO_M05AB_명예_기사_012","items":[{"k":"line","id":"PRO_M05AB_명예_기사_013","speaker":"엠버","text":"첫 질문이 그거야? 나중에 몰래 빠져나갈 방법부터 묻는 건 아니라서 다행인가!"},{"k":"line","id":"PRO_M05AB_명예_기사_014","speaker":"진","text":"오늘부터 생활을 모두 바꾸실 필요는 없습니다. 몬드에 도움이 필요할 때 다시 부탁드리고 싶어요."}]},{"label":"명예 기사는 월급 나와요? 아니, 안 나와도 받을 건데, 나중에 「그런 얘기 없었다」고 하면 제가 민망해서요.","id":"PRO_M05AB_명예_기사_015","items":[{"k":"line","id":"PRO_M05AB_명예_기사_016","speaker":"진","text":"…월급은 없습니다. 솔직하게 말씀드리는 편이 나을 것 같아서요."},{"k":"line","id":"PRO_M05AB_명예_기사_017","speaker":"엠버","text":"대신 본부 식당은 쓸 수 있어. 그건 내가 보증해."}]}]},{"k":"line","id":"PRO_M05AB_명예_기사_018","speaker":"나","text":"그렇다면 받을게요. 도움이 필요하면 불러 주세요. 저도 일이 꼬이면 몬드에 아는 기사들이 있다고 큰소리 좀 칠 생각이거든요. 그때 찾아왔는데 누구냐고 하시면 정말 곤란해요."},{"k":"line","id":"PRO_M05AB_명예_기사_019","speaker":"","text":"진이 내 이름을 또박또박 불렀다. 엠버가 웃는 얼굴로 한 걸음 옆으로 비켜섰고, 나는 진이 내민 손을 잡았다. 손바닥에 힘이 너무 들어갔다는 걸 알아차렸을 때 진은 먼저 부드럽게 악수를 마쳤다."},{"k":"keep","id":"ISK_M05_AB_052","text":"환영합니다, 명예 기사. 당신의 이름으로 남을 공적입니다."},{"k":"line","id":"PRO_M05AB_명예_기사_020","speaker":"나","text":"감사합니다. 그런데 엠버, 지금 웃는 건 축하하는 거지? 내 어깨가 너무 굳어 있는 게 웃긴 건 아니지?"},{"k":"line","id":"PRO_M05AB_명예_기사_021","speaker":"엠버","text":"둘 다! 축하해. 어깨는 이제 내려도 돼. 이름 붙였다고 갑옷 무게가 늘어난 건 아니잖아."},{"k":"line","id":"PRO_M05AB_명예_기사_022","speaker":"","text":"숨을 내쉬자 웃음이 돌았다. 다이루크가 고개를 끄덕였고, 알베도는 내 펴진 어깨를 보며 수첩을 두드렸다."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_001","speaker":"","text":"축하가 끝날 무렵 노크 소리가 들렸다. 진의 대답에 낯선 여성이 들어와 인사를 건넸다."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_002","speaker":"각청","text":"중요한 자리였나 보네요. 기다릴 수 있었는데, 방해했다면 미안해요."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_003","speaker":"진","text":"막 이야기를 마쳤습니다. 이분이 말씀드린 명예 기사입니다. 이쪽은 리월 칠성의 옥형성, 각청 님이세요."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_004","speaker":"각청","text":"각청이야. 만나서 반가워. 네가 돌아오면 이야기하고 싶어서 기다렸어. 몬드를 지킨 일에 대해서는 나도 전해 들었고."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_005","speaker":"나","text":"{PLAYER_NAME}이야. 기다렸다는 말부터 들으니까 조금 긴장되는데. 리월에서도 용 때문에 온 건 아니지?"},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_006","speaker":"각청","text":"용이면 내가 직접 처리했지. 여기까지 올 일이 아니야. 내가 온 건 다른 일 때문이야. 리월에서 일부 천암군이 기억을 잃는 일이 생겼어."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_007","speaker":"","text":"엠버가 문 곁에서 자세를 바로잡았다. 각청은 서류를 펼쳐 놓고 자기 말로 설명했다."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_008","speaker":"각청","text":"모든 천암군에게 생긴 일은 아니야. 지금은 당사자들을 쉬게 하면서 치료와 조사를 함께 진행하고 있어."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_009","speaker":"나","text":"기억을 잃었다는 건… 자기 이름도 모른다거나, 방금 한 일을 기억 못 한다거나, 그런 뜻이야?"},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_010","speaker":"각청","text":"아직 그 범위를 확인하는 중이야. 같은 기억상실이라고 묶어 놓으면 놓치는 게 생겨. 당사자들을 만나서 말을 듣고, 지금 가진 기록과 맞춰 볼 손이 필요해. 네가 도울 수 있는 건 그쪽이야."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_011","speaker":"알베도","text":"치료를 받는 사람들의 관찰 기록도 공유받을 수 있을까? 기억이 달라지는 시점과 몸의 변화가 함께 있었는지부터 비교해 보고 싶어."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_012","speaker":"각청","text":"공유할 수 있는 범위는 확인해서 보내 드릴게요. 당사자가 말하기 어려워하는 내용까지 아무 데나 옮기지는 않을 거예요."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_013","speaker":"나","text":"그런데 왜 나야? 사람을 만나서 얘기하는 건 할 수 있어도, 기억을 돌려놓는 방법은 몰라. 구슬도 용한테 썼던 게 전부고."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_014","speaker":"각청","text":"바로 그걸 직접 묻고 싶었어. 몬드에서 도착한 소식에는 용을 막아 낸 결과가 먼저였거든. 네가 무엇을 보고 어떻게 움직였는지 들으면 우리 쪽 기록과 비교할 수 있어. 모르는 사용법까지 내놓으라는 뜻은 아니야."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_015","speaker":"다이루크","text":"구슬을 사람에게 사용하겠다는 요청인가?"},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_016","speaker":"각청","text":"아니. 당사자들의 뜻부터 확인해야지. 실제로 사용할지는 물건을 살피고 치료를 맡은 사람들과 상의한 뒤에 결정할 일이야."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_017","speaker":"","text":"각청은 그제야 서류를 탁자에 놓았다. 아무도 구슬을 꺼내 놓으라고 하지 않았다. 품 안으로 가려던 손을 내리고, 펼쳐진 종이 쪽으로 의자를 조금 당겼다."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_018","speaker":"나","text":"리월에 가서도 원인을 못 알아내면? 멀리까지 갔다가 또 빈손으로 돌아올 수도 있잖아."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_019","speaker":"각청","text":"그럼 어디까지 봤고 어디서 막혔는지 내게 말해. 거기서 다른 방법을 찾을 테니까. 네가 혼자 원인까지 밝혀 오길 기다리면서 손 놓고 있을 생각은 없어. 그럴 거면 내가 여기까지 안 왔지."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_020","speaker":"진","text":"저희도 도울 수 있는 조사 자료를 정리하겠습니다. 다만 오늘 바로 출발하실 필요는 없습니다. 휴식과 준비가 먼저예요."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_021","speaker":"각청","text":"동의해요. 직접 이야기하려고 온 거예요. 지친 사람을 끌고 돌아갈 생각은 없어요."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_022","speaker":"나","text":"내가 대답할 때까지 기다려 주는 건 좋네. 솔직히 짐은 언제 쌀 거냐는 말부터 나올 줄 알았거든."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_023","speaker":"각청","text":"그랬다면 처음부터 그렇게 말했겠지. 네 생각도 들어야 함께할 일을 정할 수 있잖아. 그리고 짐은… 빨리 싸는 편이 좋긴 해. 이건 그냥 참고로."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_024","speaker":"알베도","text":"진, 사본은 오늘 안에 넘길게. 각청, 구슬을 전달받은 과정도 넣어 둘게. 이 사람에게 같은 설명을 처음부터 다시 시키지 않아도 될 거야."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_025","speaker":"나","text":"그건 부탁할게. 앨리스라는 사람을 만난 적이 없다는 것도 써 줘. 내가 그 사람한테 비밀 사용법을 따로 배운 것처럼 되면 곤란하니까."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_026","speaker":"각청","text":"알겠어요. 그리고 너는 모르는 사람 이름이 나오면 바로 물어봐. 나도 리월 사람을 다 알지는 못하니까."},{"k":"choice","group":"G_PRO_M05AB_리월에서_온_사람_027","options":[{"label":"좋아, 갈게. 내가 본 일은 내가 설명하고, 사람들 얘기도 들어 볼게. 대신 모르는 건 바로 물을 거야. 리월까지 가서 아는 척만 하다 오면 내 다리가 아까우니까.","keep":"ISK_M05_AB_083","items":[]}]},{"k":"keep","id":"ISK_M05_AB_084","text":"그렇게 해. 나도 현장을 보여 주면서 설명할게. 혼자 추측해서 잘못된 곳으로 뛰어가는 것보다 그게 빠르니까."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_028","speaker":"엠버","text":"또 다른 나라라니. 네가 처음 성에 왔을 때는 여기 길도 하나씩 물어봤는데."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_029","speaker":"나","text":"그건 아직도 가끔 물어봐. 어제도 본부에서 내려오다가 길 하나 잘못 들었어."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_030","speaker":"다이루크","text":"그 길 끝에 가게가 있더군."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_031","speaker":"나","text":"그건 잠깐 본 거야. 길을 잘못 든 김에 본 거지, 가게를 보려고 잘못 든 건 아니고."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_032","speaker":"각청","text":"그럼 길 안내는 필요한 만큼 부탁해도 되겠네. 대신 출발할 때는 가게마다 멈추지 말자. 나 그런 거 세는 편이야."},{"k":"line","id":"PRO_M05AB_리월에서_온_사람_033","speaker":"","text":"엠버는 지도를 가지러 갔다. 진과 각청은 남은 문서를 확인했고, 알베도도 기록의 사본을 받기로 했다. 나와 다이루크는 밖에서 기다리기로 하고 나갔다."},{"k":"line","id":"PRO_M05AB_계단_아래_001","speaker":"","text":"본부 밖으로 나오자 벤티가 계단 아래에서 손을 흔들었다. 다이루크는 옆 골목에서 짐을 내리던 수레 쪽을 봤다. 우인단 병사가 사람들의 길을 막고 있었다."},{"k":"line","id":"PRO_M05AB_계단_아래_002","speaker":"벤티","text":"드디어 나왔네. 네가 해 준 일에 고맙다고 말하려면 보고가 끝나기를 기다려야 한다더니, 이번에는 축하할 일이 하나 더 생겼어?"},{"k":"line","id":"PRO_M05AB_계단_아래_003","speaker":"나","text":"벤티! 너한테 할 말이… 잠깐, 뒤에 있는 사람은 누구야?"},{"k":"line","id":"PRO_M05AB_계단_아래_004","speaker":"","text":"벤티의 뒤에서 흰 서리가 바닥을 훑었다. 내가 계단 끝을 밟기도 전에 냉기가 벤티의 부츠를 돌바닥에 붙잡았다. 옆 골목에서는 수레가 기울었고 다이루크가 병사의 팔을 쳐 내며 상인을 길 밖으로 밀어냈다. 시뇨라는 그 소란을 돌아보지 않고 벤티의 앞으로 걸어 나왔다."},{"k":"line","id":"PRO_M05AB_계단_아래_005","speaker":"시뇨라","text":"한참 기다리게 했어. 이제 노래는 그만 부르고, 내 용건부터 들어."},{"k":"line","id":"PRO_M05AB_계단_아래_006","speaker":"벤티","text":"초대받지 않은 손님치고는 자리를 참 크게 쓰네. 다른 사람들은 비켜 주지 그래?"},{"k":"line","id":"PRO_M05AB_계단_아래_007","speaker":"","text":"벤티의 손끝에서 바람이 일었다. 발목을 붙든 얼음이 갈라졌지만 시뇨라는 물러나지 않았다. 옆에서 달려드는 병사의 공격을 막으며 몸을 돌렸다. 시뇨라의 옷과 병사들의 차림을 잇는 순간, 빈 사당이 떠올랐다."},{"k":"line","id":"PRO_M05AB_계단_아래_008","speaker":"나","text":"우인단이죠? 당신 부하들이 죽은 건 알아요? 사당에서 전부 죽어 있는 걸 봤어요. 다시 갔을 땐 시체까지 없어졌고!"},{"k":"line","id":"PRO_M05AB_계단_아래_009","speaker":"시뇨라","text":"내 부하들이 죽었다고? 헛소리하지 마. 네가 무슨 시체를 봤는지까지 내가 설명해 줘야 해? 비켜."},{"k":"line","id":"PRO_M05AB_계단_아래_010","speaker":"","text":"시뇨라가 손을 뻗었다. 내가 앞으로 나서자 병사의 무기가 다시 길을 막았다. 금속이 부딪친 소리 사이로 벤티의 짧은 숨이 새어 나왔다. 다음 순간 시뇨라의 손에는 작은 물건이 들려 있었다. 벤티의 몸에서 뽑아낸 것이었다."},{"k":"keep","id":"ISK_M05_AB_101","text":"이게 신의 심장이라니. 손에 넣고 나니 더 시시해."},{"k":"line","id":"PRO_M05AB_계단_아래_011","speaker":"나","text":"벤티!"},{"k":"line","id":"PRO_M05AB_계단_아래_012","speaker":"","text":"밀려오는 공격을 비껴 내며 벤티에게 닿았다. 벤티의 무게가 팔 위로 실렸다. 등 뒤에서 문이 열리고 보랏빛 섬광이 계단을 가로질렀다. 각청은 사람들 위로 떨어지던 얼음 조각을 끊어 내고 앞을 막은 병사의 무기를 쳐 떨어뜨렸다."},{"k":"line","id":"PRO_M05AB_계단_아래_013","speaker":"각청","text":"계단에서 내려오지 마! 다친 사람부터 안쪽으로 옮겨!"},{"k":"line","id":"PRO_M05AB_계단_아래_014","speaker":"다이루크","text":"시뇨라! 거기 멈춰!"},{"k":"line","id":"PRO_M05AB_계단_아래_015","speaker":"","text":"다이루크가 수레를 넘어 길목을 좁혔다. 우인단의 후위가 물러서며 시야를 가렸고, 시뇨라는 그 틈으로 돌아섰다. 각청이 곧바로 뒤를 쫓았으나 계단 아래 쓰러진 사람과 골목으로 달아나는 인원이 갈라졌다. 그녀는 공격해 오는 병사를 먼저 밀어내 사람들에게 열린 길을 지켰다."},{"k":"line","id":"PRO_M05AB_계단_아래_016","speaker":"","text":"진과 기사들이 문을 나왔을 때 강탈은 이미 끝나 있었다. 벤티를 받친 팔을 놓지 못한 채 두 사람의 얼굴부터 봤다."},{"k":"line","id":"PRO_M05AB_계단_아래_017","speaker":"","text":"벤티를 안으로 옮기는 동안 그의 모자가 한쪽으로 흘러내렸다. 그것을 잡으려 손을 옮기자 벤티가 약하게 고개를 저었다."},{"k":"line","id":"PRO_M05AB_계단_아래_018","speaker":"벤티","text":"모자는 나중에…. 지금 잡아 주는 쪽은 놓지 말아 줘. 다리에 힘이 조금 덜 들어가네."},{"k":"line","id":"PRO_M05AB_계단_아래_019","speaker":"나","text":"말하지 마. 아니, 대답은 해 줘. 내가 지금 뭘 먼저 해야 할지 모르겠어. 어디가 제일 아픈지부터 말해 봐."},{"k":"line","id":"PRO_M05AB_계단_아래_020","speaker":"벤티","text":"그 질문이면 대답할 수 있겠네. 가슴 쪽. 하지만 네가 생각하는 것처럼 몸속에 구멍이 난 건 아니야. 조금만 기대 있을게."},{"k":"line","id":"PRO_M05AB_계단_아래_021","speaker":"","text":"의자 옆에 무릎을 댔다. 벤티의 손은 차가웠지만 잡는 힘은 남아 있었다."},{"k":"line","id":"PRO_M05AB_계단_아래_022","speaker":"나","text":"신의 심장이라고 했어. 드발린은 너를 바르바토스라고 불렀고. 그때도 이상했는데, 지금까지 내가 그냥 못 알아들은 거야?"},{"k":"keep","id":"ISK_M05_AB_114","text":"응. 그 이름도 나야. 바르바토스, 몬드 사람들이 바람의 신이라고 부르는 존재. 네 앞에서 노래하던 벤티도 다른 사람은 아니고."},{"k":"line","id":"PRO_M05AB_계단_아래_023","speaker":"나","text":"그런 건 의자에 앉아서 먼저 알려 줄 수 있잖아. 지금 이렇게 앉아서 말하라는 뜻은 아니고!"},{"k":"line","id":"PRO_M05AB_계단_아래_024","speaker":"벤티","text":"맞아. 조금 더 좋은 자리에서 이야기할 기회가 있었지. 지금은 농담으로 넘기지 않을게. 놀라게 해서 미안해."},{"k":"line","id":"PRO_M05AB_계단_아래_025","speaker":"","text":"다이루크가 눈썹을 아주 조금 찌푸린 채 벤티를 봤다. 평소라면 곧바로 다음 질문을 던졌을 그도 잠깐 말을 골랐다."},{"k":"line","id":"PRO_M05AB_계단_아래_026","speaker":"다이루크","text":"바르바토스… 네가? …정체 얘기는 나중에 해도 돼. 방금 빼앗긴 것 때문에 몸 상태가 더 나빠지는지부터 말해."},{"k":"line","id":"PRO_M05AB_계단_아래_027","speaker":"벤티","text":"저걸 빼앗겼다고 지금 이 자리에서 숨이 멎는 건 아니야. 몸이 받은 충격부터 가라앉혀야겠어."},{"k":"line","id":"PRO_M05AB_계단_아래_028","speaker":"나","text":"그 말을 먼저 하지. 아까부터 네가 갑자기 멈출까 봐…. 구슬을 꺼내 볼까? 드발린한테는 됐잖아."},{"k":"line","id":"PRO_M05AB_계단_아래_029","speaker":"알베도","text":"지금은 드발린을 붙들던 오염과 다른 문제야. 곧바로 비추지는 말자. 치료를 도울 사람을 불렀으니 먼저 상태를 살펴야겠어."},{"k":"line","id":"PRO_M05AB_계단_아래_030","speaker":"벤티","text":"구슬은 잘 가지고 있어. 오늘 네가 내게 해 준 일은 이미 있어. 바닥에 얼굴부터 닿을 뻔했는데, 꽤 급하게 받아 줬잖아."},{"k":"line","id":"PRO_M05AB_계단_아래_031","speaker":"나","text":"그걸 웃으면서 말하지 마. 나 지금 고맙다는 말 들을 기분이 아니니까."},{"k":"line","id":"PRO_M05AB_계단_아래_032","speaker":"벤티","text":"알았어. 그럼 기대 있게 해 달라는 부탁만 할게."},{"k":"line","id":"PRO_M05AB_계단_아래_033","speaker":"","text":"벤티의 어깨를 받쳤다. 신이라는 말보다 기대 있겠다는 부탁이 당장은 이해하기 쉬웠다."},{"k":"line","id":"PRO_M05AB_남은_질문_001","speaker":"","text":"진은 현장 확인을 마치고 돌아와 문을 닫았다. 각청의 장갑에는 녹은 서리가 묻어 있었고, 다이루크는 손등에 걸린 얼음 조각을 털어 냈다. 누구도 방에 들어오면서 괜찮다고 말하지 않았다."},{"k":"line","id":"PRO_M05AB_남은_질문_002","speaker":"진","text":"우인단에 정식으로 항의하고 신병과 경위를 요구하겠습니다. 벤티 씨, 지금 자세한 진술을 하실 필요는 없어요."},{"k":"line","id":"PRO_M05AB_남은_질문_003","speaker":"각청","text":"밖에서 움직이는 낌새를 더 빨리 알아챘어야 했어. 문을 나왔을 때는 이미 빼앗긴 뒤였고. 뒤쫓아간 기사들의 보고는 아직 들어오지 않았어."},{"k":"line","id":"PRO_M05AB_남은_질문_004","speaker":"나","text":"몇 걸음밖에 안 떨어져 있었어. 다이루크도 옆 골목에 있었고. 사람이 그렇게 많은데도 저렇게 빼앗아 갈 수 있는 거야?"},{"k":"line","id":"PRO_M05AB_남은_질문_005","speaker":"다이루크","text":"처음부터 용건을 끝내고 빠질 생각으로 자리를 잡았다. 자네가 못 움직인 건 아니야. 앞을 막은 놈을 넘겼을 때, 저쪽 손이 먼저 닿은 거다."},{"k":"line","id":"PRO_M05AB_남은_질문_006","speaker":"나","text":"알아. 나도 아예 서 있지는 않았어. 그런데 그 말로 덜 화가 나지는 않네. 조금만 빨랐으면 손목이라도 잡았을 것 같아서."},{"k":"line","id":"PRO_M05AB_남은_질문_007","speaker":"각청","text":"그 생각은 나도 해. 그렇다고 다음번에 사람들을 밀쳐 두고 무조건 앞만 쫓지는 않을 거야. 오늘 길목에 있던 사람들도 무사히 돌려보내야 했으니까."},{"k":"choice","group":"G_PRO_M05AB_남은_질문_008","options":[{"label":"시뇨라한테 사당 얘기도 물었어. 자기 부하들이 죽었다는 말을 헛소리라며 잘라 버렸어.","id":"PRO_M05AB_남은_질문_009","items":[{"k":"line","id":"PRO_M05AB_남은_질문_010","speaker":"다이루크","text":"나도 봤어. 빈 사당에 들어가기 전 그 방이 어땠는지는 자네 혼자 증명할 일이 아니다. 기사단에는 내가 함께 진술하지. 시뇨라가 부인했다는 말도 빠짐없이 넣고."}]},{"label":"우리가 본 사람들이 없었던 일처럼 말하니까 더 화가 났어. 누가 죽였는지도, 어디로 옮겼는지도 모르는 사람들이잖아.","id":"PRO_M05AB_남은_질문_011","items":[{"k":"line","id":"PRO_M05AB_남은_질문_012","speaker":"다이루크","text":"그 방이 어땠는지는 자네 혼자 증명할 일이 아니다. 기사단에는 내가 함께 진술하지. 시뇨라가 부인했다는 말도 빠짐없이 넣고."}]}]},{"k":"line","id":"PRO_M05AB_남은_질문_013","speaker":"진","text":"제가 듣겠습니다. 질문한 말과 돌아온 답을 기억나는 대로 말씀해 주세요. 강탈에 대한 조사와, 사당에서 일어난 일도 함께 살피겠습니다."},{"k":"line","id":"PRO_M05AB_남은_질문_014","speaker":"벤티","text":"나 때문에 네 질문까지 사라지게 하지는 마. 그 사람들이 누구였는지, 왜 죽었는지는 여전히 알아봐야 할 일이야."},{"k":"line","id":"PRO_M05AB_남은_질문_015","speaker":"나","text":"너 때문에 그런 거 아니야. 그러니까 그 말까지 네가 가져가지 마. 지금은 네 물건도 빼앗겼잖아. 좀 억울하다고 해도 되지 않아?"},{"k":"line","id":"PRO_M05AB_남은_질문_016","speaker":"","text":"벤티는 나를 보다가 시선을 내렸다. 길게 대답할 것처럼 숨을 들이쉬었지만, 나온 말은 짧았다."},{"k":"line","id":"PRO_M05AB_남은_질문_017","speaker":"벤티","text":"응. 억울하네. 오늘은 친구가 무사하다는 이야기를 듣고, 같이 웃고 싶었는데."},{"k":"line","id":"PRO_M05AB_남은_질문_018","speaker":"","text":"의자 등받이에 걸린 모자를 집어 벤티의 옆에 놓았다. 방 안에서 처음으로 아무도 다음 설명을 서두르지 않았다."},{"k":"line","id":"PRO_M05AB_창가_001","speaker":"","text":"벤티가 쉴 수 있도록 방을 옮긴 뒤, 복도 창문 앞에 섰다. 아래에서는 얼음에 젖은 바닥을 치우고 있었다. 각청이 다가와 두 걸음쯤 떨어져 섰다."},{"k":"line","id":"PRO_M05AB_창가_002","speaker":"각청","text":"리월로 가는 약속 때문에 바로 움직여야 한다고 생각하지는 마. 오늘 일이 있었으니 출발 준비는 다시 맞추자."},{"k":"line","id":"PRO_M05AB_창가_003","speaker":"나","text":"혹시 나 데려가겠다고 한 거 후회하는 줄 알았네. 바깥에 나가자마자 저 난리가 났잖아. 가서도 늘 저럴 거라고 생각하면 좀 억울한데."},{"k":"line","id":"PRO_M05AB_창가_004","speaker":"각청","text":"후회할 일이면 여기서 말했겠지. 나 그런 거 돌려 말하는 성격 아니야. 아까 부탁한 일은 달라지지 않았어. 다친 친구를 확인하고 떠날 수 있도록 시간을 다시 정하자는 거야."},{"k":"line","id":"PRO_M05AB_창가_005","speaker":"나","text":"나도 가겠다는 마음은 그대로야. 그런데 여기서 바로 떠나면 벤티를 놔두고 가는 느낌일 것 같아. 전에도 소식만 기다려야 했는데, 또 그러는 건 싫고."},{"k":"line","id":"PRO_M05AB_창가_006","speaker":"각청","text":"그럼 상태를 확인하고 떠나. 일정은 조정할 수 있어. 내가 조정 못 하는 건 리월 쪽 회의뿐이고, 그건 내 문제야."},{"k":"line","id":"PRO_M05AB_창가_007","speaker":"","text":"각청은 내가 창밖에서 눈을 돌릴 때까지 기다렸다. 먼저 몸을 돌리거나 다음 용건을 꺼내지는 않았다."},{"k":"line","id":"PRO_M05AB_창가_008","speaker":"나","text":"리월에 가면 기억을 잃은 사람들부터 만나는 거지. 그 사람들이 우리한테 별로 말하고 싶지 않을 수도 있겠다."},{"k":"line","id":"PRO_M05AB_창가_009","speaker":"각청","text":"그래. 먼저 만나겠다는 사람들을 확인해 둘게. 네가 들은 이야기는 내게도 전해 줘. 서로 따로 움직이다가 같은 질문만 반복하지 않도록 하자."},{"k":"line","id":"PRO_M05AB_창가_010","speaker":"나","text":"좋아. 내 쪽도 그 순서라면 해 볼 수 있겠어. 가서 첫날부터 구슬 들고 줄 세워 보라고 하는 건 좀 무서웠거든."},{"k":"line","id":"PRO_M05AB_창가_011","speaker":"각청","text":"그런 일정은 없어. 줄 세우는 건 내가 하는 일이고, 그것도 서류한테만 해."},{"k":"line","id":"PRO_M05AB_창가_012","speaker":"","text":"각청은 연락할 곳이 있다며 먼저 돌아섰다. 복도 끝에는 다이루크와 엠버가 기다리고 있었다. 엠버가 들고 있던 지도 꾸러미를 흔들었다."},{"k":"line","id":"PRO_M05AB_짐_001","speaker":"","text":"짐을 펼친 탁자 앞에서 엠버는 지도와 내 물건을 번갈아 봤다. 길을 걷는 동안 바로 꺼낼 것과 숙소에 닿은 뒤 꺼낼 것을 나누어 놓자 가방 모양이 조금 달라졌다. 다이루크는 내가 직접 묶은 끈을 한 번 당겨 보고 손을 뗐다."},{"k":"line","id":"PRO_M05AB_짐_002","speaker":"엠버","text":"처음엔 모험가 길드가 어디 있는지 알려 주면 하루치 안내가 끝날 줄 알았는데. 벌써 리월까지 설명하게 되네."},{"k":"line","id":"PRO_M05AB_짐_003","speaker":"나","text":"나도 처음에는 오늘 잘 곳만 알면 된다고 생각했어. 그다음엔 무기, 그다음엔 의뢰…. 계속 한 가지씩만 알면 될 줄 알았는데 여기까지 왔네."},{"k":"line","id":"PRO_M05AB_짐_004","speaker":"엠버","text":"그래도 다음에 돌아오면 길드 위치는 안 물어봐도 되잖아. 나한테 할 질문이 조금 줄었겠네?"},{"k":"line","id":"PRO_M05AB_짐_005","speaker":"나","text":"대신 네가 잘 지냈는지는 물어봐야지. 이번에는 내 얘기만 하느라 네가 어디 다녔는지도 제대로 못 들었어."},{"k":"line","id":"PRO_M05AB_짐_006","speaker":"","text":"엠버는 지도 모서리를 누르던 손을 멈췄다. 곧 평소처럼 웃었지만 대답은 장난보다 조금 느렸다."},{"k":"line","id":"PRO_M05AB_짐_007","speaker":"엠버","text":"그럼 그 질문은 돌아왔을 때 다시 해 줘. 나도 얘기할 거 모아 둘게. 네가 없는 동안 아무 일도 안 하고 기다릴 생각은 없으니까."},{"k":"line","id":"PRO_M05AB_짐_008","speaker":"알베도","text":"기록은 여기 있어. 네가 구슬을 받은 경위와 정화 당시의 관찰을 나눠 적었어. 읽다가 네 기억과 다른 부분이 있으면 출발 전에 알려 줘."},{"k":"line","id":"PRO_M05AB_짐_009","speaker":"나","text":"정말 의자 있는 데서 다시 만나고, 그림도 보고, 이제는 자료까지 받네. 첫 만남이 조금 정상적이었으면 덜 기억에 남았을 것 같기도 해."},{"k":"line","id":"PRO_M05AB_짐_010","speaker":"알베도","text":"다음에는 조용한 배경을 골라야겠어. 오늘 하다 만 건 내가 보관할게. 돌아오면 먼저 앉아서 그걸 같이 보자."},{"k":"line","id":"PRO_M05AB_짐_011","speaker":"진","text":"연락은 기사단에서도 이어 가겠습니다. 사당 조사에 변화가 있으면 알려 드릴게요. 돌아오셨을 때 처음부터 다시 신분을 설명하실 필요도 없습니다, 명예 기사."},{"k":"line","id":"PRO_M05AB_짐_012","speaker":"나","text":"아직 그 호칭 들으면 제 뒤부터 볼 것 같네요. 그래도… 돌아올 때 인사할 곳이 하나 늘었다고 생각할게요."},{"k":"line","id":"PRO_M05AB_짐_013","speaker":"진","text":"돌아오시면 오늘 이야기가 어떻게 이어졌는지 듣고 싶습니다. 그때도 직접 찾아와 주세요."},{"k":"line","id":"PRO_M05AB_짐_014","speaker":"","text":"떠날 채비를 마친 뒤 벤티를 다시 찾았다. 그는 모자를 무릎에 올려놓고 앉아 있었다. 나도 짐을 내려놓고 맞은편에 앉았다."},{"k":"line","id":"PRO_M05AB_짐_015","speaker":"벤티","text":"멀리 갈 짐이네. 이번에는 길 중간에 누가 데려가겠다고 해도 목적지를 먼저 물어봐."},{"k":"line","id":"PRO_M05AB_짐_016","speaker":"나","text":"이번 목적지는 리월이야. 각청이 부탁했고, 나도 가겠다고 했어. 네 상태만 한 번 더 보고 싶었어."},{"k":"line","id":"PRO_M05AB_짐_017","speaker":"벤티","text":"아까보다는 나아. 혼자 앉아 있을 수도 있고, 네 얼굴에 걱정이 몇 개쯤 남았는지도 셀 수 있어."},{"k":"line","id":"PRO_M05AB_짐_018","speaker":"나","text":"그걸 세어서 뭐 하려고. 한 개당 노래 한 곡이면 오늘 못 떠날 텐데."},{"k":"line","id":"PRO_M05AB_짐_019","speaker":"벤티","text":"그럼 노래는 돌아왔을 때로 미뤄야겠네. 네가 드발린에게 무슨 말을 했는지도 자세히 듣고 싶고."},{"k":"line","id":"PRO_M05AB_짐_020","speaker":"나","text":"네가 찾아다닌다고 전했어. 살아 있고 정화됐다는 말은 네가 직접 듣는 게 좋을 것 같다고도 했고. 그런데 우리가 다시 만난 게 하필 그렇게 돼서… 제대로 말을 못 했네."},{"k":"line","id":"PRO_M05AB_짐_021","speaker":"","text":"벤티가 모자챙을 천천히 쓸었다."},{"k":"line","id":"PRO_M05AB_짐_022","speaker":"벤티","text":"고마워. 그 애가 자기 목소리로 대답했다는 이야기만으로도 듣고 싶었던 소식이야. 네가 떠나기 전에 들을 수 있어서 좋네."},{"k":"choice","group":"G_PRO_M05AB_짐_023","options":[{"label":"돌아오면 네 얘기도 해 줘. 바르바토스라는 이름도, 신의 심장도. 한꺼번에 다 말하라는 건 아닌데, 이번처럼 남의 입으로 듣고 맞춰 보는 건 좀 싫어.","id":"PRO_M05AB_짐_024","items":[{"k":"line","id":"PRO_M05AB_짐_025","speaker":"벤티","text":"내가 말할 수 있는 이야기부터 해 줄게. 다만 나를 부르는 이름은 벤티로 해 줘. 문을 열자마자 너무 엄숙해지면 노래 고르기 어려워지거든."},{"k":"line","id":"PRO_M05AB_짐_026","speaker":"나","text":"걱정 마. 난 아직 하프 들고 드발린을 부르던 모습이 먼저 떠올라. 다음에는 어디로 갔는지 소식부터 남겨 줘."}]},{"label":"신한테 「술은 아니야」 하고 물 준 사람이 됐네, 나. 돌아오면 그건 좀 봐줘.","id":"PRO_M05AB_짐_027","items":[{"k":"line","id":"PRO_M05AB_짐_028","speaker":"벤티","text":"그건 안 봐줄 거야. 신한테 물 준 사람으로 노래를 만들 거거든. 다만 나를 부르는 이름은 벤티로 해 줘. 노래가 너무 엄숙해지면 곤란하니까."}]}]},{"k":"line","id":"PRO_M05AB_짐_029","speaker":"벤티","text":"응. 너도 리월에 무사히 닿으면 소식 보내 줘. 이번에는 내가 기다리는 쪽이네."},{"k":"line","id":"PRO_M05AB_짐_030","speaker":"","text":"밖에서는 각청이 내 짐이 전부 모였는지 확인하고 있었다. 다이루크는 고친 매듭 하나를 가리킨 뒤 가방을 넘겼다. 더 익숙한 손으로 대신 들어 주지는 않았다."},{"k":"line","id":"PRO_M05AB_짐_031","speaker":"다이루크","text":"이제 걸어 보게. 어깨가 당기면 여기서 다시 고치면 된다."},{"k":"line","id":"PRO_M05AB_짐_032","speaker":"나","text":"괜찮아. 잠깐… 오른쪽이 좀 당기네. 이거 하나만 옮기면 되겠어."},{"k":"line","id":"PRO_M05AB_짐_033","speaker":"","text":"가방을 내려놓고 물건 하나의 자리를 바꿨다. 다시 어깨에 올려 보니 무게가 한쪽으로 쏠리지 않았다. 다이루크를 보며 고개를 끄덕이자 각청도 지도를 접었다."},{"k":"line","id":"PRO_M05AB_짐_034","speaker":"각청","text":"됐어? 그럼 준비는 끝났네. 리월에서 만나야 할 사람들에 관한 이야기는 길에서 조금 더 해 줄게."},{"k":"choice","group":"G_PRO_M05AB_짐_035","options":[{"label":"응, 준비 끝. 길은 네가 잘 아니까 처음에는 믿고 따라갈게. 대신 도착하고 나면 나도 금세 익힐 거야. 계속 뒤에서 「저 사람 어디 갔냐」고 찾게 만들 생각은 없거든.","keep":"ISK_M05_AB_186","items":[]}]},{"k":"line","id":"PRO_M05AB_짐_036","speaker":"","text":"가방을 멘 채 본부 쪽을 돌아봤다. 빈 사당의 의문도, 신의 심장을 빼앗긴 일도 끝나지 않았다. 품 안의 구슬을 확인한 뒤 다시 앞을 봤다. 리월로 떠날 준비가 끝났다."},{"k":"keep","id":"ISK_M05_AB_END","text":"몬드에서의 큰 고비를 넘겼다. 남은 의뢰를 마치거나 동료들과 시간을 보낼 수 있다. 준비가 되면 메인 임무에서 리월로 향하자."}],"edits":[],"pre":""},{"id":"ISK_M05_B","entry":"ISK_M05_B_001","items":[{"k":"keep","id":"ISK_M05_B_001"},{"k":"line","id":"PRO_M05B_거점을_떠나며_001","speaker":"","text":"알베도가 수첩을 덮었다. 식어 가는 물을 마시고도 일어나지 않았다. 산을 오르고 용을 마주한 하루가 이제야 다리로 내려오는 중이었다."},{"k":"line","id":"PRO_M05B_거점을_떠나며_002","speaker":"나","text":"나 지금 일어나면 다시 산을 올라가라는 말은 안 하지? 그냥 확인하는 거야. 오늘은 이야기가 끝났다고 생각할 때마다 하나씩 더 나왔거든."},{"k":"line","id":"PRO_M05B_거점을_떠나며_003","speaker":"알베도","text":"지금 일어나면 먼저 문까지 가면 돼. 그다음에는 몬드로 내려가는 길이고. 이번에는 목적지를 바꿀 계획이 없어."},{"k":"line","id":"PRO_M05B_거점을_떠나며_004","speaker":"나","text":"좋네. 문. 길. 몬드. 그 사이에 용이나 하늘에서 떨어지는 건 없고."},{"k":"line","id":"PRO_M05B_거점을_떠나며_005","speaker":"알베도","text":"그 부분까지 약속할 수는 없지만, 새로운 조사에 널 데려가지는 않을게."},{"k":"line","id":"PRO_M05B_거점을_떠나며_006","speaker":"","text":"알베도는 배달품 인수 확인서와 관찰 기록의 사본을 나란히 놓았다. 구슬에 관한 기록은 공개 의뢰 보고와 구분해 접어 두었다."},{"k":"line","id":"PRO_M05B_거점을_떠나며_007","speaker":"알베도","text":"길드에는 전달을 마쳤다는 확인서를 먼저 내면 돼. 정상의 변화와 길의 위험은 이쪽 기록으로 설명하고. 네가 개인적으로 들은 말까지 접수처에서 모두 읽을 필요는 없어."},{"k":"line","id":"PRO_M05B_거점을_떠나며_008","speaker":"나","text":"고맙다. 사람들 앞에서 그 말까지 따라 하려니까 좀 그랬거든. 나도 아직 누구한테 들은 건지 모르는데."},{"k":"line","id":"PRO_M05B_거점을_떠나며_009","speaker":"알베도","text":"진 단장에게는 따로 전해 줘. 네게만 들렸다는 점까지. 나는 그 목소리를 듣지 못했으니 직접 인용할 수 없고, 구슬과 관련 있는지도 아직 몰라."},{"k":"line","id":"PRO_M05B_거점을_떠나며_010","speaker":"","text":"알베도는 동행을 하산길의 큰 갈림목까지로 정했다. 그가 챙기는 수첩을 가리켰다. 두 개의 잔이 그려진 장이 잠깐 다시 보였다."},{"k":"choice","group":"G_PRO_M05B_거점을_떠나며_011","options":[{"label":"내 얼굴, 너무 초췌하게 남기지는 않았지? 다음에 와서 보고 딴 사람이라고 우기기 전에 물어보는 거야.","id":"PRO_M05B_거점을_떠나며_012","items":[{"k":"line","id":"PRO_M05B_거점을_떠나며_013","speaker":"알베도","text":"네가 웃고 있을 때 그렸어. 컵을 놓지 않았다는 건 조금 더 잘 보이게 그렸고."},{"k":"line","id":"PRO_M05B_거점을_떠나며_014","speaker":"나","text":"그건 정확하네. 오늘 제일 믿음직한 물건이었거든."}]},{"label":"그 그림, 길드에 제출하는 건 아니지? 「배달원 상태 보고」 같은 걸로.","id":"PRO_M05B_거점을_떠나며_015","items":[{"k":"line","id":"PRO_M05B_거점을_떠나며_016","speaker":"알베도","text":"제출 안 해. 이건 내 거야. 보고서에는 「배달원, 무사 귀환」이면 충분해."}]}]},{"k":"line","id":"PRO_M05B_거점을_떠나며_017","speaker":"","text":"갈림목에서 알베도는 길이 보이는 곳까지 함께 걸어 나와 줬다. 두어 걸음 가다 돌아봤다. 그가 먼저 작별을 끝내고 등을 돌렸을 거라고 생각했는데, 여전히 그 자리에 있었다."},{"k":"line","id":"PRO_M05B_거점을_떠나며_018","speaker":"나","text":"다음에는 진짜 그림만 보러 올 수도 있어. 배달할 게 없어도."},{"k":"line","id":"PRO_M05B_거점을_떠나며_019","speaker":"알베도","text":"응. 그때도 네가 앉을 자리는 있을 거야. 조심해서 내려가."},{"k":"line","id":"PRO_M05B_거점을_떠나며_020","speaker":"","text":"산기슭에서 눈이 끝나는 자리에 이르자 다리가 조금 가벼워졌다. 그 틈을 노린 것처럼 덤불에서 보물 사냥단이 튀어나왔다. 혼자 내려오는 사람으로 보였을 것이다. 맞는 말이긴 했다."},{"k":"combat","id":"PRO_M05B_거점을_떠나며_021","group":"EG_TREASURE_PATROL","text":"산기슭 길목에서 보물 사냥단이 짐을 노린다. 배달 확인서와 구슬이 든 짐을 지킨다."},{"k":"line","id":"PRO_M05B_거점을_떠나며_022","speaker":"","text":"마지막 한 명이 도망간 뒤 짐끈부터 확인했다. 확인서도, 천에 싼 구슬도 그대로였다. 「배달원, 무사 귀환」을 지키기 위해 생각보다 많은 일을 했다."},{"k":"keep","id":"ISK_M05_B_018","text":"접수처의 의뢰서 모서리가 바람에 들렸다. 그 평범한 모습이 이상하게 안심이 됐다. 익숙한 안내원의 얼굴을 확인하고 다가갔다."},{"k":"line","id":"PRO_M05B_길드_001","speaker":"캐서린","text":"별과 심연을 향해! 돌아왔구나. 알베도에게 전달할 물건은 잘 전했니?"},{"k":"line","id":"PRO_M05B_길드_002","speaker":"나","text":"응. 받았다는 확인서도 여기 있어. 그런데 그 뒤에 일이 좀 많았어. 배달 끝났다는 얘기랑 그 얘기를 한꺼번에 하면 나도 순서가 헷갈릴 것 같은데."},{"k":"line","id":"PRO_M05B_길드_003","speaker":"캐서린","text":"그럼 전달 확인부터 할게. 다친 데는 없어? 오래 서 있기 어려우면 의자를 가져다줄 수 있어."},{"k":"line","id":"PRO_M05B_길드_004","speaker":"나","text":"지금 앉으면 얘기가 길어질 것 같아. 아니, 얘기는 어차피 길어질 것 같으니까 앉을래."},{"k":"line","id":"PRO_M05B_길드_005","speaker":"","text":"캐서린은 옆에 있던 의자를 돌려 줬다. 보고가 시작되자 그녀의 펜이 몇 번 멈췄다. 한천의 못이 무너진 대목에서는 알베도의 기록을 펼쳤고, 드발린을 정화했다는 말에서는 내 얼굴을 다시 봤다."},{"k":"line","id":"PRO_M05B_길드_006","speaker":"캐서린","text":"드발린이 살아서 떠났고, 지금은 사람들을 공격하지 않는 상태라는 거지?"},{"k":"line","id":"PRO_M05B_길드_007","speaker":"나","text":"응. 직접 말을 나누고 헤어졌어. 벤티가 기사단에 먼저 전하러 갔으니까 그쪽에도 확인할 수 있을 거야. 내가 용을 봤다는 정도로 끝나는 얘기는 아니어서."},{"k":"keep","id":"ISK_M05_B_026","text":"알겠어. 산길의 위험 정보와 그 소식은 따로 전달할게. 그리고 네가 맡았던 배달 의뢰는 이걸로 완료야. 약속한 보수는 12,000모라야."},{"k":"line","id":"PRO_M05B_길드_008","speaker":"","text":"캐서린이 정산한 보수를 건넸다. 손에 쥐고 한 번 내려다봤다. 낯선 세계에 온 뒤 그저 버티는 데 급급했던 시간 사이에, 내가 맡아 끝낸 일의 몫이 놓여 있었다. 구슬과 달리 이쪽은 무엇 때문에 손에 들어왔는지 분명했다."},{"k":"choice","group":"G_PRO_M05B_길드_009","options":[{"label":"이 보수는 배달한 값이지? 산이 무너지고 용이 따라온 건 정말 별도였고. 돈을 손에 쥐니까 이제야 실감 나네. 물건은 제대로 가져다줬는데 돌아올 때 짐이 너무 많이 붙었어.","id":"PRO_M05B_길드_010","items":[{"k":"line","id":"PRO_M05B_길드_011","speaker":"캐서린","text":"정산은 배달 의뢰 기준이야. 확인서도 물품도 맞으니 여기서는 빠진 게 없어. 산에서 생긴 일은 알베도의 기록과 함께 전달할게."}]},{"label":"첫 월급이네. 아니, 월급은 아니지. 첫… 뭐라고 하지. 아무튼 처음으로 내가 번 거야.","id":"PRO_M05B_길드_012","items":[{"k":"line","id":"PRO_M05B_길드_013","speaker":"캐서린","text":"「보수」라고 해. 그리고 축하해. 처음 번 돈은 어디에 쓸 건지 다들 한 번쯤 고민하더라."},{"k":"line","id":"PRO_M05B_길드_014","speaker":"나","text":"고민 끝. 저녁."}]}]},{"k":"line","id":"PRO_M05B_길드_015","speaker":"나","text":"좋아. 적어도 배달비는 손에 넣었네. 물건 가져갔다, 받았다, 돌아왔다. 오늘 일을 이 세 줄로 끝낼 수 있는 게 하나쯤 있으니까 얼마나 편한지 모르겠어."},{"k":"line","id":"PRO_M05B_길드_016","speaker":"캐서린","text":"그 세 가지를 확인한 건 길드에서도 반가운 일이야. 돌아왔다는 연락부터 전하고, 다음 의뢰는 그 뒤에 보러 와."},{"k":"line","id":"PRO_M05B_돌아온_사람들_001","speaker":"","text":"의뢰판 쪽으로 가던 시선을 거뒀다. 그때 성문 쪽에서 소란이 번졌다. 환호라고 하기에는 목소리가 짧았고, 마차가 지나갈 자리를 비워 달라는 외침이 그 뒤를 덮었다."},{"k":"line","id":"PRO_M05B_돌아온_사람들_002","speaker":"","text":"성문을 통과한 첫 수레에는 보급 상자 대신 사람들이 타고 있었다. 팔을 천으로 고정한 기사 옆에 모험가가 몸을 기대고 있었다. 드발린을 토벌하러 떠났던 원정부대였다. 들어오는 길에서 누구도 승전 소식을 먼저 외치지 않았다."},{"k":"line","id":"PRO_M05B_돌아온_사람들_003","speaker":"엠버","text":"왼쪽으로 비켜 주세요! 걸을 수 있는 분들도 여기서는 잠깐 멈춰 주세요. 수레부터 안쪽으로 보낼게요!"},{"k":"line","id":"PRO_M05B_돌아온_사람들_004","speaker":"","text":"엠버는 나를 알아보자 눈을 크게 떴지만 달려오지는 않았다. 한 손이 수레 옆판을 붙잡고 있었다. 나도 인사 대신 길에 쓰러진 빈 나무통부터 옆으로 굴렸다. 수레바퀴가 그 자리를 지나고 나서야 서로 마주 봤다."},{"k":"line","id":"PRO_M05B_돌아온_사람들_005","speaker":"엠버","text":"돌아왔구나. 설산에 갔다는 얘기는 들었어. 할 얘기 많지? 나도 그런데, 지금은 저 문 좀 잡아 줄래?"},{"k":"line","id":"PRO_M05B_돌아온_사람들_006","speaker":"나","text":"응. 어디까지 열면 돼? 사람들이 다 지나갈 때까지 여기 있을게."},{"k":"keep","id":"ISK_M05_B_038","text":"문을 잡고 있는 내 앞으로 젖은 붕대와 찢어진 망토가 차례로 지나갔다. 누군가는 스스로 걷겠다며 내밀어진 팔을 밀어냈다가 계단 앞에서 다시 그 팔을 잡았다. 살아 돌아온 것과 무사히 돌아온 것이 같은 말이 아니라는 걸 그 행렬이 보여 줬다."},{"k":"line","id":"PRO_M05B_돌아온_사람들_007","speaker":"엠버","text":"토벌은 실패했어. 접근하는 길에서 마물들에게 계속 막혔고, 다친 사람들 때문에 부대를 나눌 수도 없었대. 드발린을 쫓을 준비를 하던 중에 방향이 바뀌었고…. 결국 후퇴했어."},{"k":"line","id":"PRO_M05B_돌아온_사람들_008","speaker":"나","text":"설산 쪽으로 온 드발린은 우리가 만났어. 벤티한테 들었어? 지금은 괜찮아. 정화됐어."},{"k":"line","id":"PRO_M05B_돌아온_사람들_009","speaker":"엠버","text":"응. 단장님께 전해졌어. 돌아오는 부대에도 가능한 한 빨리 알렸고. 그래도 네 입으로 듣고 싶었어. 진짜로, 이제 괜찮은 거지?"},{"k":"line","id":"PRO_M05B_돌아온_사람들_010","speaker":"나","text":"적어도 우리가 헤어질 때는 자기 말로 어디로 갈지 정했어. 누가 끌고 가는 게 아니라."},{"k":"line","id":"PRO_M05B_돌아온_사람들_011","speaker":"","text":"문 안쪽에 앉아 있던 대원이 고개를 들었다. 정화한 사람이 당신이냐는 물음에 고개를 끄덕였다. 대원은 웃음 같은 숨을 내쉬다가 입가를 굳혔다."},{"k":"line","id":"PRO_M05B_돌아온_사람들_012","speaker":"나","text":"나 혼자 한 건 아니에요. 알베도도 있었고, 벤티도 도와줬어요. 여기까지 돌아오는 길에 다시 마주칠 걱정은 하지 않으셔도 될 것 같아요."},{"k":"line","id":"PRO_M05B_돌아온_사람들_013","speaker":"","text":"대원은 그거면 됐다고 말했다. 그러고는 부목을 댄 제 다리를 내려다봤다. 곁에 있던 다른 사람이 작게 중얼거렸다. 자신들은 대체 무엇을 하고 돌아온 거냐고. 엠버가 곧장 말을 막지 않았다. 잠시 뒤 그 사람이 먼저 나에게 한 말은 아니었다며 고개를 저었다."},{"k":"line","id":"PRO_M05B_돌아온_사람들_014","speaker":"나","text":"알아요. 지금 괜찮다고 듣는다고 해서 다친 데까지 안 아파지는 건 아니잖아요. 제가 뭐라고 위로해야 할지도 잘 모르겠어요. 필요한 거 있으면 가져올게요."},{"k":"line","id":"PRO_M05B_돌아온_사람들_015","speaker":"","text":"그는 잠깐 입술을 달싹이다 물을 부탁했다. 가장 가까운 물통을 찾았다. 정화했다는 말을 한 뒤에도 해야 할 일은 남아 있었다."},{"k":"line","id":"PRO_M05B_돌아온_사람들_016","speaker":"","text":"기사단의 임시 진료 공간에는 침상을 더 들이고 있었다. 진은 통로 한쪽에서 보고를 받다가 붕대가 풀린 대원을 발견하고 먼저 의자를 당겼다. 돌아온 인원과 후송 순서를 확인하는 목소리는 차분했지만, 같은 명단을 짚는 손끝이 종이를 세게 누르고 있었다."},{"k":"line","id":"PRO_M05B_돌아온_사람들_017","speaker":"진","text":"걸어서 들어온 사람도 반드시 확인을 받게 해. 상처를 숨기고 복귀하는 일이 없도록. 엠버, 성문 쪽 인계가 끝나면 남은 수레의 위치를 알려 줘."},{"k":"line","id":"PRO_M05B_돌아온_사람들_018","speaker":"엠버","text":"네. 그리고 여기, 설산에서 돌아왔어요. 아까부터 문 잡는 거랑 물 나르는 걸 도와줬고요."},{"k":"line","id":"PRO_M05B_돌아온_사람들_019","speaker":"진","text":"돌아오셨군요. 엠버, 이분까지 일을 맡겼어? 아니, 먼저 손부터 보여 주세요. 산에서 내려온 분에게 물동이부터 들게 할 수는 없죠."},{"k":"line","id":"PRO_M05B_돌아온_사람들_020","speaker":"나","text":"다리는 좀 풀렸고, 손도 아직 뻐근해요. 그래도 먼저 기다리는 분들부터 봐 주세요. 저까지 괜찮은 척할 생각은 없으니까 제 차례에는 말할게요."},{"k":"line","id":"PRO_M05B_돌아온_사람들_021","speaker":"진","text":"도와주신 건 고맙습니다. 이제 이쪽에 앉아 계세요. 엠버도 잠깐 물 마시고. 둘 다 괜찮다는 대답부터 하지 말고요."},{"k":"line","id":"PRO_M05B_돌아온_사람들_022","speaker":"","text":"벤티는 안쪽 창가에 서 있었다. 눈이 마주치자 손을 들었지만, 평소 같은 큰 인사는 하지 않았다. 붕대 냄새와 젖은 흙냄새가 바람에 섞였다."},{"k":"line","id":"PRO_M05B_돌아온_사람들_023","speaker":"벤티","text":"네가 오는 길은 어땠어? 알베도는 거점으로 돌아갔고?"},{"k":"line","id":"PRO_M05B_돌아온_사람들_024","speaker":"나","text":"응. 길은 멀쩡했어. 보물 사냥단 빼면. 나도 그렇게 대답할 수 있어서 다행이네. 여기 와 보니까."},{"k":"line","id":"PRO_M05B_돌아온_사람들_025","speaker":"벤티","text":"드발린이 공격하지 않을 거라고 전했어. 그런데 진은 축하할 시간이 없더라. 돌아오는 사람들 이름을 먼저 찾고 있었거든. 나도 명단을 같이 봤어."},{"k":"line","id":"PRO_M05B_돌아온_사람들_026","speaker":"나","text":"나한테 했던 말 그대로?"},{"k":"line","id":"PRO_M05B_돌아온_사람들_027","speaker":"벤티","text":"응. 기다릴 수가 없어서, 그 애 뜻을 묻지 않고 움직였다는 것까지. 네가 나한테 했던 말도 기억하고 있어."},{"k":"line","id":"PRO_M05B_돌아온_사람들_028","speaker":"","text":"진은 마지막 지시를 마친 뒤 두 사람에게 다가왔다. 정화의 경위부터 한 번 더 들었다. 나는 구슬이 빛났던 순간과 내가 한 일을 구분해 말했다. 산 위의 목소리는 곁에 있던 사람들에게만 낮게 전했다."},{"k":"line","id":"PRO_M05B_돌아온_사람들_029","speaker":"진","text":"당신도 산에서 본 일을 들려주시면 됩니다. 토벌대의 일까지 대신 설명하실 필요는 없어요."},{"k":"line","id":"PRO_M05B_돌아온_사람들_030","speaker":"나","text":"아까 어떤 분은 고맙다고 하다가 다리부터 보셨어요. 두 기분이 같이 오는 것 같더라고요. 저도 그 앞에서 그냥 다 잘됐다고는 못 하겠던데."},{"k":"line","id":"PRO_M05B_돌아온_사람들_031","speaker":"진","text":"그분들을 이곳에 보낸 사람으로서 제가 들어야 할 말입니다. 오늘 귀환한 이름을 확인한 것으로 제 일이 끝났다고 생각하지는 않아요."},{"k":"line","id":"PRO_M05B_명예기사_001","speaker":"","text":"소란이 조금 잦아든 뒤, 진은 나를 기사단 안쪽의 작은 회의 공간으로 안내했다. 문은 닫지 않았다. 거창한 의식이 열릴 만한 시간은 아니었지만, 그 때문에 미루고 싶지 않은 말이 있었다."},{"k":"line","id":"PRO_M05B_명예기사_002","speaker":"진","text":"드발린을 정화해 몬드의 위협을 멈추고, 그가 자신의 뜻으로 살아갈 수 있게 해 주셨습니다. 당신이 이곳에 머문 시간이 짧다는 사실은 그 공을 줄이지 않습니다. 페보니우스 기사단을 대표해, 당신을 명예기사로 맞이하고 싶습니다."},{"k":"line","id":"PRO_M05B_명예기사_003","speaker":"나","text":"명예기사요? 저, 방금까지 길드에서 배달비 받고 왔는데요. 여기 와서 문 잡아 달라는 부탁을 받을 줄은 알았어도 그건 예상 못 했어요."},{"k":"line","id":"PRO_M05B_명예기사_004","speaker":"벤티","text":"문을 아주 훌륭하게 잡았나 봐. 역시 기본기가 중요하다니까."},{"k":"line","id":"PRO_M05B_명예기사_005","speaker":"진","text":"벤티 씨."},{"k":"line","id":"PRO_M05B_명예기사_006","speaker":"벤티","text":"알았어. 중요한 순간이지. 나도 알고 있어."},{"k":"line","id":"PRO_M05B_명예기사_007","speaker":"","text":"벤티는 두 손을 작게 들며 물러섰다. 웃음이 잠깐 방 안을 지나갔다. 진은 웃음이 잦아든 뒤 대답을 기다렸다."},{"k":"choice","group":"G_PRO_M05B_명예기사_008","options":[{"label":"받을게요. 배달하러 나간 사람이 이렇게 돌아올 줄은 저도 몰랐네요. 나중에 오늘 얘기를 하면 아무도 안 믿을 것 같은데, 적어도 몬드에서는 제 이름과 같이 기억해 주겠죠.","keep":"ISK_M05_B_071","items":[]}]},{"k":"keep","id":"ISK_M05_B_072","text":"잊지 않겠습니다. 설산에서 살아 돌아오신 일도, 돌아오자마자 다친 대원들을 위해 문을 잡아 주신 일도요. 오늘 이 자리를 크게 마련하지는 못했지만, 감사하는 마음을 직접 전할 수 있어 기쁩니다."},{"k":"line","id":"PRO_M05B_명예기사_009","speaker":"","text":"진이 정식으로 호칭을 건넸다. 내 이름 뒤에 붙은 새로운 말을 소리 없이 되풀이해 봤다. 옷에 묻은 흙은 그대로였지만, 이 도시에서 나를 부를 말이 하나 늘어났다."},{"k":"line","id":"PRO_M05B_명예기사_010","speaker":"나","text":"그럼 다음에 누가 배달하러 온 사람이냐고 물으면 명예기사도 겸하고 있다고 해도 되겠네요. 표정은 적당히 해 볼게요. 너무 신나 보여서 칭호부터 의심받으면 곤란하니까."},{"k":"line","id":"PRO_M05B_명예기사_011","speaker":"진","text":"그 점은 제가 보증하겠습니다. 방금 직접 드린 칭호를 당신이 기뻐하신다고 거두지는 않아요."},{"k":"line","id":"PRO_M05B_명예기사_012","speaker":"벤티","text":"그럼 오늘 첫 노래의 제목은 정했네. 산에 배달 갔다가 명예기사가 되어 돌아온 사람."},{"k":"line","id":"PRO_M05B_명예기사_013","speaker":"나","text":"길어. 부르는 동안 내가 또 산에 다녀오겠다. 그리고 술값 내 달라는 내용은 넣지 마."},{"k":"line","id":"PRO_M05B_명예기사_014","speaker":"벤티","text":"아직 첫 소절도 안 썼는데 벌써 검열이야?"},{"k":"line","id":"PRO_M05B_명예기사_015","speaker":"","text":"진이 이번에는 확실히 웃었다. 그때 복도에서 면담 신청을 알리는 소리가 들렸다. 우인단의 시뇨라가 방문했다는 말에 그녀의 웃음이 가라앉았다."},{"k":"line","id":"PRO_M05B_명예기사_016","speaker":"진","text":"드발린 사건에 관한 면담입니다. 먼저 정리하고 돌아오겠습니다. 무슨 일이 있으면 곧바로 경비에게 알려 주세요."},{"k":"line","id":"PRO_M05B_명예기사_017","speaker":"","text":"벤티는 열린 문 너머를 봤다. 방금 지어낸 노래의 다음 소절은 나오지 않았다."},{"k":"line","id":"PRO_M05B_접견실_001","speaker":"","text":"시뇨라는 기사단 안으로 들어오면서도 분주한 복도를 비켜 주기 위해 걸음을 늦추지 않았다. 진은 이들을 환자들이 쉬는 쪽에서 떨어진 접견실로 안내하고, 수행원은 바깥 통로에서 기다리게 했다."},{"k":"line","id":"PRO_M05B_접견실_002","speaker":"진","text":"부상자 이송이 진행 중입니다. 수행원은 이쪽에서 기다리십시오. 면담은 제가 직접 받겠습니다."},{"k":"line","id":"PRO_M05B_접견실_003","speaker":"시뇨라","text":"마침 바쁜가 보지. 몬드의 용 문제는 정리됐다고 들었는데, 돌아온 병사들 꼴은 영 다르던걸."},{"k":"line","id":"PRO_M05B_접견실_004","speaker":"진","text":"토벌대의 피해를 수습하고 있습니다. 드발린은 정화되었고 추가 공격도 멈췄습니다. 확인하실 사안이 무엇입니까?"},{"k":"line","id":"PRO_M05B_접견실_005","speaker":"","text":"두 사람이 접견실에 들어가고 문이 반쯤 닫혔다. 벤티는 반대쪽 복도를 잠깐 살폈다. 옆의 짧은 통로 끝에 접견실의 높은 덧창이 있었다. 열린 틈으로 목소리가 흘러나왔다. 그가 그쪽을 가리키자 눈을 가늘게 떴다."},{"k":"line","id":"PRO_M05B_접견실_006","speaker":"나","text":"지금 저기 가서 듣자는 거지? 명예기사 된 지 얼마나 됐다고 벌써 몰래 엿듣게 해."},{"k":"line","id":"PRO_M05B_접견실_007","speaker":"벤티","text":"공식 손님으로 들어가면 내 노래를 청할 것 같지가 않아서. 무슨 말을 꺼내는지 확인하고 싶어."},{"k":"line","id":"PRO_M05B_접견실_008","speaker":"나","text":"농담하는 얼굴이 아닌데 농담으로 설명하면 더 수상해져. 나도 갈게. 대신 무슨 일이면 이번에는 먼저 말해 줘."},{"k":"line","id":"PRO_M05B_접견실_009","speaker":"벤티","text":"알았어. 가까이 붙을 필요는 없어. 이 안쪽에서 듣자."},{"k":"line","id":"PRO_M05B_접견실_010","speaker":"","text":"둘은 접견실 옆의 통로로 들어갔다. 이쪽에는 사람이 없었다. 벤티를 따라 벽 옆에 멈췄다."},{"k":"line","id":"PRO_M05B_접견실_011","speaker":"시뇨라","text":"토벌에는 실패하고, 이름도 생소한 외부인의 도움으로 해결했다. 꽤 편리한 설명이야. 기사단이 보장할 수 있는 건 뭐지?"},{"k":"line","id":"PRO_M05B_접견실_012","speaker":"진","text":"그가 한 일을 외부인이라는 이유로 깎아내릴 수는 없습니다. 정화 여부는 현장에서 확인되었고, 관련 보고도 받고 있습니다. 우인단이 요구하는 조치가 있다면 구체적으로 말씀하십시오."},{"k":"line","id":"PRO_M05B_접견실_013","speaker":"시뇨라","text":"구체적인 것이라면 곧 보여 주지."},{"k":"line","id":"PRO_M05B_접견실_014","speaker":"","text":"방 안에서 의자가 움직였다. 들킨 줄 알고 벤티를 봤다. 벤티의 손이 먼저 내 팔에 닿았다. 뒤로 물러서라는 뜻이었다. 발을 떼기도 전에 덧창의 틈에 희게 성에가 번졌다."},{"k":"line","id":"PRO_M05B_접견실_015","speaker":"시뇨라","text":"쥐새끼가 있어."},{"k":"line","id":"PRO_M05B_접견실_016","speaker":"","text":"얼음이 덧창을 터뜨리며 좁은 통로로 뻗었다. 벤티가 나를 뒤로 밀고 바람을 일으켰지만, 발밑으로 번진 냉기가 두 사람 사이를 갈랐다. 벽에 어깨를 부딪쳤다. 손을 뻗자 얼음이 손목과 옷자락을 함께 붙잡았다."},{"k":"line","id":"PRO_M05B_접견실_017","speaker":"나","text":"벤티, 뒤에…!"},{"k":"line","id":"PRO_M05B_접견실_018","speaker":"","text":"경고는 끝나지 못했다. 시뇨라가 접견실의 옆문을 밀치고 나왔다. 벤티의 몸이 얼음에 붙들려 뒤로 꺾였다. 팔을 당길수록 벽에 붙은 옷감만 팽팽해졌다. 시뇨라는 나에게 시선을 한 번 주고는 곧바로 벤티에게 다가갔다."},{"k":"line","id":"PRO_M05B_접견실_019","speaker":"진","text":"시뇨라! 당장 손을 떼십시오!"},{"k":"line","id":"PRO_M05B_접견실_020","speaker":"","text":"진이 뒤따라 옆문으로 몸을 돌렸다. 검이 가로막힌 얼음을 갈랐다. 부서진 조각이 복도로 쏟아지는 순간, 문밖에서 이송되던 들것이 한쪽으로 기울었다. 진은 바람으로 파편을 밀어내며 들것이 벽에 부딪히지 않게 받쳤다."},{"k":"line","id":"PRO_M05B_접견실_021","speaker":"진","text":"기사단 안에서 사람을 습격하다니. 이 행위를 외교라는 말로 덮을 수 있다고 생각합니까!"},{"k":"line","id":"PRO_M05B_접견실_022","speaker":"시뇨라","text":"애초에 관리가 미숙한 건 그쪽 탓 아니야?"},{"k":"line","id":"PRO_M05B_접견실_023","speaker":"","text":"그녀는 진의 대답을 기다리지 않았다. 벤티가 바람을 모으자 얼음이 그의 목 가까이까지 조여들었다. 시뇨라의 손이 벤티의 가슴을 향했다. 눈앞의 빛이 손가락 사이로 끌려 나오는 순간, 내가 보고 있는 일이 무엇인지 이해하지 못한 채 숨부터 멈췄다."},{"k":"line","id":"PRO_M05B_접견실_024","speaker":"벤티","text":"그 손… 치워."},{"k":"line","id":"PRO_M05B_접견실_025","speaker":"","text":"벤티의 목소리에서 웃음이 완전히 사라져 있었다. 시뇨라는 그를 붙들던 손을 거두며 작은 형체를 들어 보였다. 내 품 안의 구슬과는 다른 물건이었다."},{"k":"keep","id":"ISK_M05_B_107","text":"이건 담보야."},{"k":"line","id":"PRO_M05B_접견실_026","speaker":"","text":"진이 다시 거리를 좁혔다. 검과 얼음이 부딪치는 소리가 좁은 공간을 울렸다. 시뇨라는 얻으려던 것을 쥔 채 몸을 빼며 통로 입구를 얼음으로 가로막았다. 진이 장벽을 뚫었을 때는 벤티를 묶었던 얼음이 함께 갈라지며 그의 몸이 바닥으로 떨어지고 있었다."},{"k":"line","id":"PRO_M05B_접견실_027","speaker":"진","text":"경비, 바깥 동선을 확인해! 환자들이 있는 통로로 몰아넣지 마라! 엠버, 성문 쪽에 알려!"},{"k":"line","id":"PRO_M05B_접견실_028","speaker":"","text":"진은 벤티를 받치고 내 손목을 붙잡은 얼음을 깼다. 시뇨라는 추적이 좁혀 오기 전에 현장을 벗어났다. 남은 통로에는 깨진 덧창과 얼음, 그리고 조금 전까지 따뜻했던 방으로 스며드는 찬 공기만 있었다."},{"k":"line","id":"PRO_M05B_접견실_029","speaker":"","text":"자유로워진 손목을 한동안 움직이지 못했다. 잡혔던 자리가 아픈 것보다, 움직이겠다고 마음먹은 동안 실제로는 아무 데도 가지 못했다는 감각이 남아 있었다. 벤티는 벽에 등을 기댄 채 앉아 숨을 골랐다."},{"k":"line","id":"PRO_M05B_접견실_030","speaker":"나","text":"방금 가져간 거, 뭐야? 네 몸에서 나온 것처럼 보였어. 벤티, 나 보고 얘기해 봐. 지금 말할 수 있어?"},{"k":"line","id":"PRO_M05B_접견실_031","speaker":"벤티","text":"말할 수 있어. 조금 천천히 해야겠지만. 네 손은 어때?"},{"k":"line","id":"PRO_M05B_접견실_032","speaker":"나","text":"내 손은 여기 붙어 있어. 그 얘기는 잠깐 뒤에 하자. 네가 빼앗긴 게 뭔지부터 알아야겠어."},{"k":"line","id":"PRO_M05B_접견실_033","speaker":"","text":"진이 차가워진 벤티의 손에 천을 덮었다. 입을 다물고 대답을 기다렸다."},{"k":"line","id":"PRO_M05B_접견실_034","speaker":"벤티","text":"신의 심장이야. 그게 이름이야. 내게서 빼앗아 간 건… 응, 너희가 본 그대로 내 것이었어."},{"k":"line","id":"PRO_M05B_접견실_035","speaker":"나","text":"심장이라고 하면 겁부터 나잖아. 지금 네가 살아 있는 데 필요한 게 없어졌다는 뜻이야?"},{"k":"line","id":"PRO_M05B_접견실_036","speaker":"벤티","text":"내가 여기서 너와 얘기할 수 없게 되는 건 아니야. 하지만 대수롭지 않은 물건이라고 말하면 거짓말이겠지."},{"k":"line","id":"PRO_M05B_접견실_037","speaker":"나","text":"드발린이 너를 바르바토스라고 불렀지. 설마 그게… 내가 이 도시에 와서 계속 들었던 바람의 신 이름이야?"},{"k":"keep","id":"ISK_M05_B_120","text":"응. 바르바토스도 나고, 너와 여기까지 같이 온 벤티도 나야. 언젠가 제대로 말하려 했는데, 이런 자리에서 듣게 했네."},{"k":"choice","group":"G_PRO_M05B_접견실_038","options":[{"label":"지금까지 몰랐던 걸 한꺼번에 알아듣기는 좀 어려워. 그래도 네가 다쳤다는 건 알아. 나머지는 네가 숨 좀 편하게 쉰 다음에 얘기하자.","id":"PRO_M05B_접견실_039","items":[{"k":"line","id":"PRO_M05B_접견실_040","speaker":"","text":"진은 벤티를 바라본 채 몇 초 동안 아무 말도 하지 못했다."},{"k":"line","id":"PRO_M05B_접견실_041","speaker":"진","text":"바르바토스 님이… 정말 당신이셨군요. …하지만 지금은 다친 분부터 지켜야 합니다. 담보라는 건 시뇨라가 멋대로 붙인 이름이에요. 기사단은 어떤 담보도 인정하지 않습니다."}]},{"label":"신한테 물 갖다주고, 신이랑 엿듣고… 오늘 하루 치고 너무 많다. 일단 숨부터 쉬어. 나머지는 나중에.","id":"PRO_M05B_접견실_042","items":[{"k":"line","id":"PRO_M05B_접견실_043","speaker":"벤티","text":"그 순서로 노래를 만들면 되겠네. 물, 엿듣기, 그다음은…. 응, 숨부터 쉴게."},{"k":"line","id":"PRO_M05B_접견실_044","speaker":"진","text":"바르바토스 님이… 정말 당신이셨군요. …하지만 지금은 다친 분부터 지켜야 합니다. 담보라는 건 시뇨라가 멋대로 붙인 이름이에요. 기사단은 어떤 담보도 인정하지 않습니다."}]}]},{"k":"line","id":"PRO_M05B_접견실_045","speaker":"","text":"진이 마지막 말을 할 때 손에 쥔 천이 조금 구겨졌다. 밖에서는 깨진 유리를 치우는 소리가 났다. 부상자들을 들였던 사람들 위로 또 다른 소란을 얹었다는 사실이 그녀의 얼굴에 남아 있었다."},{"k":"line","id":"PRO_M05B_접견실_046","speaker":"나","text":"쫓아가야 하는 거 아니냐는 생각이 자꾸 드는데, 막상 나가면 어디로 뛰어야 할지도 모르겠어요. 아까도 움직이려고만 했지 아무것도 못 했고."},{"k":"line","id":"PRO_M05B_접견실_047","speaker":"진","text":"추적은 이미 지시했습니다. 지금 뒤따라 나가시면 당신까지 찾아야 해요. 두 분은 이곳에 계셔 주세요. 기사단 안에서 이런 공격을 허용했다는 사실을 저도 받아들이기 어렵습니다."},{"k":"line","id":"PRO_M05B_접견실_048","speaker":"벤티","text":"진, 네가 들것을 받치는 걸 봤어. 저 사람은 네가 사람들을 그냥 지나치지 않을 거라는 걸 이용한 거야. 그걸 잘못이었다고 말하지 마."},{"k":"line","id":"PRO_M05B_접견실_049","speaker":"","text":"진은 곧바로 대답하지 않았다. 깨진 덧창 너머를 봤다. 들것이 기울었던 자리는 이미 비어 있었다."},{"k":"line","id":"PRO_M05B_접견실_050","speaker":"나","text":"나도 봤어요. 그 사람들은 넘어지지 않았어요. 그건 분명히 말할 수 있어요."},{"k":"line","id":"PRO_M05B_복도_001","speaker":"","text":"상처를 살핀 뒤 복도로 나왔을 때, 아까 물을 가져다준 대원과 다시 마주쳤다. 그는 손목에 감긴 천을 보고 무슨 일이 있었느냐고 물었다. 갑작스러운 습격을 당했다고 짧게 설명했다. 명예기사가 됐다는 이야기는 뒤늦게 따라 나왔다."},{"k":"line","id":"PRO_M05B_복도_002","speaker":"나","text":"순서가 좀 우습죠. 축하받고 나왔는데 이젠 제가 옆자리에 앉았네요. 방금 받은 칭호도 손목에 감아 둘 수는 없더라고요."},{"k":"line","id":"PRO_M05B_복도_003","speaker":"","text":"대원은 잠깐 웃다가 입술을 눌렀다. 웃으면 다친 데가 당긴다고 했다. 나도 웃음을 거두고 그 옆에 앉았다."},{"k":"line","id":"PRO_M05B_복도_004","speaker":"나","text":"아까 가져온 물, 너무 차갑지는 않았어요? 지금에서야 손이 좀 풀려서 생각났네요. 오늘은 저도 이 복도에서 멀리 갈 것 같지는 않으니까."},{"k":"line","id":"PRO_M05B_복도_005","speaker":"","text":"그는 물이면 됐다고 답했다. 잠시 뒤, 드발린이 정말 자신들의 뒤를 쫓아오지 않겠느냐고 다시 물었다."},{"k":"line","id":"PRO_M05B_복도_006","speaker":"나","text":"자기 이름을 말했고, 제 이름도 물었어요. 쉬러 가겠다고 했고요. 누가 공격하라고 몰아붙이는 모습은 아니었어요. 우리가 억지로 묶어 놓은 상태도 아니었고요."},{"k":"line","id":"PRO_M05B_복도_007","speaker":"","text":"대원이 벽에 머리를 기댔다. 아까는 정화했다는 말을 듣고 자신들이 쓸모없어졌다고 생각했다면서, 고개를 조금 숙였다. 이제는 내일도 그 용을 쫓아 나가지 않아도 된다는 쪽이 먼저 떠오른다고 했다."},{"k":"line","id":"PRO_M05B_복도_008","speaker":"나","text":"저도 내일 또 용을 쫓으라고 하면 아주 솔직하게 싫다고 할 거예요. 오늘 일은 한동안 생각나겠지만, 적어도 드발린이 뒤쫓아올 걱정은 같이 내려놔도 될 것 같아요."},{"k":"line","id":"PRO_M05B_복도_009","speaker":"","text":"엠버가 두 사람 앞에 와서 멈췄다. 옮길 침상이 정해졌다며 대원에게 팔을 내밀고, 나에게는 그가 들고 있던 짐을 부탁했다. 이번에는 도와도 되는지 물을 필요가 없었다."},{"k":"line","id":"PRO_M05B_복도_010","speaker":"엠버","text":"아까 성문에서 너 봤을 때, 하고 싶은 말이 하나 있었어. 계속 다음 일이 생겨서 못 했는데."},{"k":"line","id":"PRO_M05B_복도_011","speaker":"나","text":"설마 짐 하나 더 있다는 말은 아니지?"},{"k":"line","id":"PRO_M05B_복도_012","speaker":"엠버","text":"돌아와서 다행이라고. 그 말."},{"k":"line","id":"PRO_M05B_복도_013","speaker":"","text":"짐끈을 고쳐 잡았다. 누군가를 구했다는 말보다 그 짧은 인사가 더 깊이 와 닿았다. 돌아온 사람들의 이름을 부르는 소리가 복도 안쪽에서 이어졌다."},{"k":"line","id":"PRO_M05B_벤치_001","speaker":"","text":"저녁 무렵 벤티는 기사단 앞 벤치에 앉아 있었다. 음료가 든 잔 두 개를 들고 그 옆으로 갔다. 벤티가 하나를 받으며 냄새부터 맡았다. 기대한 향이 아니라는 게 얼굴에 그대로 드러났다."},{"k":"line","id":"PRO_M05B_벤치_002","speaker":"벤티","text":"따뜻하네. 아주… 건강한 향이야."},{"k":"line","id":"PRO_M05B_벤치_003","speaker":"나","text":"술은 아니야. 방금 그런 일을 당해 놓고 당연히 술일 줄 알았으면 그건 네 잘못이고."},{"k":"line","id":"PRO_M05B_벤치_004","speaker":"벤티","text":"당연하다고 생각한 건 아니야. 아주 작은 희망 정도였지."},{"k":"line","id":"PRO_M05B_벤치_005","speaker":"","text":"그는 잔을 두 손으로 감싸고 한 모금 마셨다. 그 모습을 확인하고 나서 내 잔을 들었다. 알베도와 앉아 있던 탁자가 생각났다. 지금은 옆에 있는 사람도 손이 떨리는 이유도 달라져 있었다."},{"k":"line","id":"PRO_M05B_벤치_006","speaker":"나","text":"산에서부터 자꾸 네가 내 대답을 기다려 줬잖아. 오늘 낮에 또 엿듣자고 했을 때도. 그런데 막상 일이 터지니까 대답이고 뭐고 그냥 붙잡히더라. 좀 화가 나."},{"k":"line","id":"PRO_M05B_벤치_007","speaker":"벤티","text":"나한테도?"},{"k":"line","id":"PRO_M05B_벤치_008","speaker":"나","text":"조금. 나한테도 나고, 그 여자한테는 많이 나고. 네가 웃으면서 별일 아니었다고 하면 아마 너한테 더 날 것 같아."},{"k":"line","id":"PRO_M05B_벤치_009","speaker":"","text":"벤티는 잔을 내려다봤다. 늘 빨리 돌아오던 농담이 이번에는 한동안 없었다. 바람이 모자 끝을 움직였지만 그는 잡으려고 손을 들지도 않았다."},{"k":"line","id":"PRO_M05B_벤치_010","speaker":"벤티","text":"별일이었어. 나도 아직 손을 뻗던 순간이 생각나. 네가 옆에 붙들려 있었는데도 떼어 주지 못했고. 웃으면 좀 나아질 줄 알았는데, 네 앞에서까지 다 지난 일처럼 굴 수는 없겠네."},{"k":"line","id":"PRO_M05B_벤치_011","speaker":"나","text":"응. 나한테 다 설명하라는 건 아니야. 그냥 지금 여기 앉아서 같이 화도 좀 내고 그러자. 혼자 먼저 아무렇지도 않아지지 말고."},{"k":"line","id":"PRO_M05B_벤치_012","speaker":"벤티","text":"알았어. 오늘은 다음 노래를 서두르지 않을게."},{"k":"line","id":"PRO_M05B_벤치_013","speaker":"","text":"광장에서는 사람들이 천막을 걷고 있었다. 원정부대가 돌아왔다는 소식을 들은 가족들이 기사단으로 향했고, 다친 이들에게 전할 음식이 담긴 바구니가 문 안으로 들어갔다. 도시는 하나의 기분으로만 움직이지 않았다."},{"k":"choice","group":"G_PRO_M05B_벤치_014","options":[{"label":"드발린은 지금 어디서 쉬고 있을까.","id":"PRO_M05B_벤치_015","items":[{"k":"line","id":"PRO_M05B_벤치_016","speaker":"벤티","text":"사람의 목소리가 조금 덜 들리는 곳일지도. 어디인지 꼭 알아내서 데리러 갈 생각은 없어. 쉬고 싶다고 했으니까."},{"k":"line","id":"PRO_M05B_벤치_017","speaker":"나","text":"다음에 만나면 오늘 일도 말할 거야?"},{"k":"line","id":"PRO_M05B_벤치_018","speaker":"벤티","text":"그 애가 먼저 알아보겠지. 오래된 친구 눈을 속이는 데는 영 소질이 없거든. 물으면 대답할게."}]},{"label":"신이라면서 왜 나한테 물 얻어 마셔. 신은 원래 그래?","id":"PRO_M05B_벤치_019","items":[{"k":"line","id":"PRO_M05B_벤치_020","speaker":"벤티","text":"몬드의 신은 원래 그래. 다른 나라 신은… 음, 가 보면 알겠지. 대신 노래는 공짜야."},{"k":"line","id":"PRO_M05B_벤치_021","speaker":"나","text":"그건 알아. 세 번 들었어."}]}]},{"k":"line","id":"PRO_M05B_벤치_022","speaker":"","text":"품 안의 구슬을 겉에서 가볍게 눌렀다. 아무 목소리도, 새 빛도 돌아오지 않았다. 그 침묵에 오늘의 답을 대신 요구하지 않기로 했다. 손을 거두자 주머니에 넣어 둔 보수의 무게가 느껴졌다. 내일 먹을 것을 고를 수 있는, 작고 분명한 무게였다."},{"k":"line","id":"PRO_M05B_벤치_023","speaker":"나","text":"다음에 어디로 갈지는 아직 모르겠어. 오늘은 여기서 밥 먹고 발 쭉 뻗고 잘 거야. 정산도 받았으니 저녁만큼은 내 마음대로 고를래. 내일 누가 또 용 얘기로 깨우면 한 번쯤은 못 들은 척하고 싶네."},{"k":"line","id":"PRO_M05B_벤치_024","speaker":"벤티","text":"좋네. 마지막 이야기는 드발린한테 전하지 않을게. 대신 메뉴를 고를 때는 내 의견도 들어 줘. 노래는 오늘 쉬기로 했지만, 네 옆에서 조용히 배고파할 자신까지 있는 건 아니거든."},{"k":"line","id":"PRO_M05B_벤치_025","speaker":"나","text":"술집 이름부터 말하면 네 의견은 기각이야."},{"k":"line","id":"PRO_M05B_벤치_026","speaker":"벤티","text":"아직 아무 말도 안 했는데! 너, 명예기사가 되더니 판단이 너무 빨라졌어."},{"k":"keep","id":"ISK_M05_B_164","text":"이번에는 내가 먼저 웃었다. 아픈 곳도 분한 마음도 남아 있었고, 빼앗긴 것은 돌아오지 않았다. 그래도 잔이 식기 전에 마실 수 있었고, 옆 사람의 농담에 대답할 수 있었다. 광장을 건너온 바람이 두 사람 사이를 지났다. 누구를 쫓으라고 등을 떠밀지도, 갈 곳을 대신 정해 주지도 않는 바람이었다."},{"k":"keep","id":"ISK_M05_B_END","text":"몬드에서의 일이 일단락되었다. 떠날 때와 남을 때는 내가 정할 수 있다. 남은 의뢰와 동료들의 이야기를 살피고, 준비가 되면 메인 임무에서 다음 여정을 시작하자."}],"edits":[],"pre":""},{"id":"ISK_M05_K","entry":"ISK_M05_K_001","items":[{"k":"keep","id":"ISK_M05_K_001"},{"k":"line","id":"PRO_M05K_눈_위의_용_001","speaker":"","text":"마지막으로 일어난 검은 바람이 눈 위에서 풀렸다. 드발린은 날개를 펴려다 그대로 내려놓았다. 비늘 사이로 새어 나오던 어둠이 눈먼지와 함께 흩어졌다."},{"k":"line","id":"PRO_M05K_눈_위의_용_002","speaker":"진","text":"아직 다가가지 마십시오. 날개 아래에서 벗어나고, 제 목소리가 들리는 곳에 계세요."},{"k":"line","id":"PRO_M05K_눈_위의_용_003","speaker":"알베도","text":"등 쪽에 남아 있던 탁한 기운이 사라지고 있어. 다시 모이지는 않아. 호흡도 돌아왔고."},{"k":"line","id":"PRO_M05K_눈_위의_용_004","speaker":"","text":"드발린의 눈꺼풀이 움직였다. 용은 고개를 들다가 입을 다물었다. 자신이 어디에 있는지 모르는 눈이었다."},{"k":"line","id":"PRO_M05K_눈_위의_용_005","speaker":"드발린","text":"들린다. 조금… 멀리 떨어져 있어라. 아직 내 몸이 어디까지 움직이는지 모르겠다."},{"k":"line","id":"PRO_M05K_눈_위의_용_006","speaker":"나","text":"응. 여기 있을게. 더 가까이 안 갈 테니까 천천히 말해도 돼. 우리를 알아보겠어?"},{"k":"line","id":"PRO_M05K_눈_위의_용_007","speaker":"드발린","text":"너희는 나를 막았다. 그 전에는… 눈이 있었나. 아니, 돌이…. 기억이 끊겨 있다."},{"k":"line","id":"PRO_M05K_눈_위의_용_008","speaker":"진","text":"드발린. 싸움은 끝났습니다. 몬드를 공격하실 이유도 이제는 없다고 생각합니다."},{"k":"line","id":"PRO_M05K_눈_위의_용_009","speaker":"드발린","text":"내가 지키던 곳을… 또 공격하려 했다는 건가."},{"k":"line","id":"PRO_M05K_눈_위의_용_010","speaker":"나","text":"하려고 했던 건 알아. 그런데 끝까지 하지는 못했어. 우리가 막았고, 지금은 네가 우리 말을 듣고 있잖아. 그러면 된 거 아니야?"},{"k":"line","id":"PRO_M05K_눈_위의_용_011","speaker":"","text":"드발린의 시선이 내 손으로 내려갔다. 손가락은 아직 검자루 모양으로 굳어 있었다. 손을 펴 보였다. 폐허에서 엠버가 가르쳐 준 대로."},{"k":"line","id":"PRO_M05K_눈_위의_용_012","speaker":"드발린","text":"바르바토스는 어디 있지?"},{"k":"choice","group":"G_PRO_M05K_눈_위의_용_013","options":[{"label":"너를 기다리고 있어. 폐허에서, 네 곁에서. 혼자 두고 가고 싶지 않다고 했어.","id":"PRO_M05K_눈_위의_용_014","items":[{"k":"line","id":"PRO_M05K_눈_위의_용_015","speaker":"드발린","text":"…그 애가. 내 옆에."},{"k":"line","id":"PRO_M05K_눈_위의_용_016","speaker":"","text":"용은 한참 아무 말도 하지 않았다. 바람이 비늘 위를 지나갔다. 이번에는 바람이 용을 따라 움직였다."}]},{"label":"폐허에 있어. 네 노래를 부르다가 멈췼어. 끝까지 부르고 싶다고 했으니까, 가서 들어 줘.","id":"PRO_M05K_눈_위의_용_017","items":[{"k":"line","id":"PRO_M05K_눈_위의_용_018","speaker":"드발린","text":"그 애가 멈췄다면 내가 멈추게 한 거다. 끝까지 들을 수 있을지는… 가서 알아봐야겠지."}]}]},{"k":"line","id":"PRO_M05K_눈_위의_용_019","speaker":"드발린","text":"갈 수 있을 것 같다. 날개가 말을 듣기 시작했다."},{"k":"line","id":"PRO_M05K_눈_위의_용_020","speaker":"알베도","text":"바로 날지는 마. 한쪽 날개가 다른 쪽보다 늦게 펴지고 있어. 두 번만 더 접고 펴 봐."},{"k":"line","id":"PRO_M05K_눈_위의_용_021","speaker":"드발린","text":"…사람이 용에게 날개 쓰는 법을 가르치는 날이 올 줄은 몰랐다."},{"k":"line","id":"PRO_M05K_눈_위의_용_022","speaker":"나","text":"사람이 용한테 맞아 죽을 뻔한 날도 왔는데, 그 정도는 참아 줘."},{"k":"line","id":"PRO_M05K_눈_위의_용_023","speaker":"","text":"날개가 두 번 접히고 펴졌다. 세 번째에 눈이 사방으로 밀려났다. 드발린은 한 번 뒤를 돌아보고 폐허 쪽으로 날아갔다. 하늘에 남은 자국이 사라질 때까지 세 사람 모두 올려다보고 있었다."},{"k":"line","id":"PRO_M05K_설산_거점_001","speaker":"","text":"거점으로 돌아와 앉았을 때, 진이 일어서려다 다시 앉았다."},{"k":"line","id":"PRO_M05K_설산_거점_002","speaker":"진","text":"이제 괜찮다고 말하려고 했는데, 다리가 저보다 먼저 반대하네요. 조금만 더 앉아 있어도 되겠습니까."},{"k":"line","id":"PRO_M05K_설산_거점_003","speaker":"나","text":"이래 봬도 끝까지 서 있었는데. 보고서에 한 줄만 잘 써 주세요. 나중에 이 얘기할 때는 다리 떨린 부분은 빼고요."},{"k":"line","id":"PRO_M05K_설산_거점_004","speaker":"진","text":"떨린 부분은 제 다리 이야기로 바꿔 두겠습니다."},{"k":"line","id":"PRO_M05K_설산_거점_005","speaker":"알베도","text":"두 사람 다 쉬어. 기록은 내가 정리할게. 그 전에 하나만 묻자. 폐허에서 죽음을 확인했다는 기록은 그대로 두는 거지?"},{"k":"line","id":"PRO_M05K_설산_거점_006","speaker":"나","text":"그대로 두는 거죠? 제가 괜히 고집부리는 걸 수도 있는데… 아까 살아 있는 걸 봤다고 그때 본 걸 없던 일로 하고 싶지는 않아요."},{"k":"line","id":"PRO_M05K_설산_거점_007","speaker":"진","text":"그대로 둡니다. 우리가 본 순서대로 적어야 뒤에 읽는 사람이 어디서 무엇이 바뀌었는지 알 수 있습니다."},{"k":"line","id":"PRO_M05K_설산_거점_008","speaker":"알베도","text":"그러면 두 장을 나란히 두는 거네. 죽어 있던 드발린과 살아 있는 드발린. 그 사이에 한천의 못과 이 구슬이 있어."},{"k":"line","id":"PRO_M05K_설산_거점_009","speaker":"","text":"알베도가 천으로 감은 수정구슬을 탁자에 올렸다. 잔해에서 꺼내 온 것이었다. 구슬은 아무 빛도 내지 않았다."},{"k":"line","id":"PRO_M05K_설산_거점_010","speaker":"나","text":"혹시 제가 아는 이야기대로 돌아왔다고 좋아해도 되는 건가 싶었어요. 그런데 중간에 있던 건 제가 아는 이야기에 하나도 없어요. 저건 뭐예요?"},{"k":"line","id":"PRO_M05K_설산_거점_011","speaker":"알베도","text":"모르겠어. 그래서 가져온 거야. 이건 내가 맡아서 조사할게. 네가 들고 다니기에는 어디로 열리는 물건인지 아무도 몰라."},{"k":"line","id":"PRO_M05K_설산_거점_012","speaker":"나","text":"그래. 설명서도 없는 물건에 내 목숨을 또 걸기는 싫어. 대신 알아내는 게 있으면 나한테도 알려 줘. 어차피 내가 들은 속삭임하고 엮여 있을 테니까."},{"k":"line","id":"PRO_M05K_설산_거점_013","speaker":"알베도","text":"약속할게. 그리고 하나 더. 올라오는 길에 네가 든 기록판, 그 뒷면에 서명해 줄래? 현장에 있던 사람으로."},{"k":"line","id":"PRO_M05K_설산_거점_014","speaker":"나","text":"그걸 이제 말해? 내가 사인한 종이가 아니라 날씨 기록인 줄 알았겠네. 앞면에 눈 그림만 있던데."},{"k":"line","id":"PRO_M05K_설산_거점_015","speaker":"알베도","text":"눈 그림 아래가 관측 기록이야. 사람과 돌을 구분 못 하는 사람에겐 그렇게 보일 수 있지."},{"k":"line","id":"PRO_M05K_설산_거점_016","speaker":"나","text":"그 얘기 아직 안 끝났어?"},{"k":"line","id":"PRO_M05K_설산_거점_017","speaker":"","text":"진이 웃음을 참지 못했다. 떨리던 다리는 그 사이에 멈췄다."},{"k":"line","id":"PRO_M05K_설산_거점_018","speaker":"","text":"다음 날 아침, 거점 아래 눈길에서 우인단의 발자국이 발견됐다. 거점을 멀리서 지켜본 흔적이었다. 내려가는 길에 그들과 마주쳤다."},{"k":"combat","id":"PRO_M05K_설산_거점_019","group":"EG_FATUI_PATROL","text":"설산을 내려가는 길목에 우인단 정찰대. 기록과 구슬을 지키며 길을 뚫는다."},{"k":"line","id":"PRO_M05K_설산_거점_020","speaker":"알베도","text":"우리를 쫓아온 게 아니라 여기서 기다렸던 거야. 저들도 저 구조물을 보고 있었어."},{"k":"line","id":"PRO_M05K_설산_거점_021","speaker":"진","text":"기억해 두겠습니다. 시뇨라에게 던질 질문이 하나 더 늘었군요."},{"k":"line","id":"PRO_M05K_설산_거점_022","speaker":"나","text":"질문 목록 꽤 길어졌네요. 그분이 다 대답해 줄 것 같지는 않지만."},{"k":"keep","id":"ISK_M05_K_042","text":"설산 거점에서 조사 기록을 정리한 뒤, 진·알베도와 함께 몬드로 돌아왔다. 성문이 보이자 엠버가 먼저 달려왔다. 준비한 질문이 많은 얼굴이었는데, 그녀가 처음 한 일은 짐을 위아래로 훑어보는 것이었다."},{"k":"line","id":"PRO_M05K_몬드성_001","speaker":"엠버","text":"다 돌아왔네. 셋 다. 가방끈 또 그렇게 묶었어? 내가 가르쳐 준 매듭은 어디 갔어."},{"k":"line","id":"PRO_M05K_몬드성_002","speaker":"나","text":"인사는 안 받아도 짐 검사는 통과해야 들어갈 수 있는 거야?"},{"k":"line","id":"PRO_M05K_몬드성_003","speaker":"엠버","text":"응! …아니, 거짓말. 그냥 어디부터 봐야 할지 몰라서 가방 봤어. 얼굴 보니까 괜찮네. 잘 돌아왔어."},{"k":"line","id":"PRO_M05K_몬드성_004","speaker":"","text":"엠버가 어깨를 한 번 치고 물러섰다. 성 안쪽에서 벤티가 걸어왔다. 노래는 부르지 않았고, 걸음은 전보다 가벼웠다."},{"k":"line","id":"PRO_M05K_몬드성_005","speaker":"벤티","text":"만났어. 드발린이 폐허로 돌아왔어. 내 이름을 부르면서."},{"k":"line","id":"PRO_M05K_몬드성_006","speaker":"나","text":"만났구나. 그 말을 직접 들으려고 오는 내내 생각했는데… 먼저 들으니까 좀 살 것 같다."},{"k":"line","id":"PRO_M05K_몬드성_007","speaker":"벤티","text":"그 애가 너희 얘기를 했어. 손을 펴 보인 사람이 있었다고. 그게 너지?"},{"k":"line","id":"PRO_M05K_몬드성_008","speaker":"나","text":"그거 엠버가 가르쳐 준 거야. 나는 손이 안 펴져서 따라 한 거고."},{"k":"line","id":"PRO_M05K_몬드성_009","speaker":"엠버","text":"뭐? 내가 뭘 가르쳤는데? …아, 그거!"},{"k":"line","id":"PRO_M05K_몬드성_010","speaker":"벤티","text":"그럼 제대로 만난 거네. 우리한테도 바르바토스가 어디 있냐고 물었어. 네가 기다리고 있다고 했지."},{"k":"line","id":"PRO_M05K_몬드성_011","speaker":"벤티","text":"고마워. 설산에서 있었던 일은 진이 적은 대로 들을게. 지금은 그냥… 기뻐."},{"k":"line","id":"PRO_M05K_몬드성_012","speaker":"나","text":"나도 기뻐. 네가 다시 만났다는 말을 들으니까 이제 좀 실감 나. 산 위에서는 살아서 내려오는 생각만 했거든."},{"k":"line","id":"PRO_M05K_몬드성_013","speaker":"","text":"노래 제목 이야기는 아무도 꺼내지 않았다. 아직 끝나지 않은 노래라는 것을 모두 알고 있었다."},{"k":"line","id":"PRO_M05K_명예기사_001","speaker":"","text":"본부에서 진은 보고서를 내려놓고, 다른 문서 하나를 꺼냈다."},{"k":"line","id":"PRO_M05K_명예기사_002","speaker":"진","text":"당신이 한 일을 기사단의 이름으로 기록해 두고 싶습니다. 폐허까지의 길, 설산의 밤, 드발린 앞에서 한 말. 명예기사의 이름을 받아 주시겠습니까."},{"k":"line","id":"PRO_M05K_명예기사_003","speaker":"케이아","text":"거절해도 서류는 이미 작성됐어. 단장 대행님은 이런 일에 빠르시거든."},{"k":"line","id":"PRO_M05K_명예기사_004","speaker":"나","text":"그렇게 말씀해 주시니 산에서 구른 보람이 있네요. 그러면 오늘은 저도 좀 으쓱해도 되죠?"},{"k":"line","id":"PRO_M05K_명예기사_005","speaker":"진","text":"오늘 하루는 허락합니다."},{"k":"choice","group":"G_PRO_M05K_명예기사_006","options":[{"label":"받을게요. 처음 왔을 때는 어디에 이름을 적어야 하는지도 몰랐는데, 이제 제 이름을 기억해 주는 사람이 이렇게 많네요.","keep":"ISK_M05_K_069","items":[{"k":"line","id":"PRO_M05K_명예기사_007","speaker":"","text":"진은 내 이름이 적힌 문서를 건넸다. 양손으로 받자 엠버가 먼저 박수를 쳤고, 벤티가 낮은 음으로 한 소절을 흥얼거렸다."},{"k":"line","id":"PRO_M05K_명예기사_008","speaker":"벤티","text":"너무 점잖았나? 분위기에 맞춰 낮은 음으로 준비했는데."},{"k":"line","id":"PRO_M05K_명예기사_009","speaker":"진","text":"지금 부르셔도 괜찮습니다. 다만 이 자리에서 처음 듣는 노래라면 제가 박자를 못 맞출 겁니다."},{"k":"line","id":"PRO_M05K_명예기사_010","speaker":"나","text":"제 이름보다 노래가 먼저 유명해지는 건 좀 억울할 것 같은데. 오늘은 박수까지만 받을게요."},{"k":"line","id":"PRO_M05K_명예기사_011","speaker":"케이아","text":"현명한 선택이야. 벤티의 노래는 한 번 퍼지면 서류보다 오래 남거든."},{"k":"line","id":"PRO_M05K_명예기사_012","speaker":"엠버","text":"진 단장, 저도 한마디만요. 이 사람, 설산에서 단장님보다 먼저 뛰어나가지 않았죠?"},{"k":"line","id":"PRO_M05K_명예기사_013","speaker":"진","text":"약속은 지켜졌습니다. 서로 확인하며 움직였습니다."},{"k":"line","id":"PRO_M05K_명예기사_014","speaker":"나","text":"저도 혼자 가겠다고 우겼으면 지금 여기 없었을 거예요. 다음에 같이 갈 때도 그렇게 할게요."},{"k":"line","id":"PRO_M05K_명예기사_015","speaker":"엠버","text":"다음에 간다는 말은 들었어. 그때는 나도 끼워 줘."},{"k":"line","id":"PRO_M05K_명예기사_016","speaker":"나","text":"나도 돌아와서 좋아. 그 말은 가방끈보다 늦어도 괜찮아."},{"k":"line","id":"PRO_M05K_명예기사_017","speaker":"엠버","text":"가방끈 얘기는 그만해!"}]}]},{"k":"line","id":"PRO_M05K_남쪽_소식_001","speaker":"","text":"길드 앞에서 캐서린이 남쪽에서 온 공지를 붙이고 있었다. 리월항의 청신의례. 날짜가 가까웠다."},{"k":"line","id":"PRO_M05K_남쪽_소식_002","speaker":"캐서린","text":"별과 심연을 향해! 리월 소식이야. 청신의례가 곧 열린다고 해. 모험가들 사이에서도 가 보려는 사람이 많아."},{"k":"line","id":"PRO_M05K_남쪽_소식_003","speaker":"나","text":"청신의례가… 곧이라고?"},{"k":"line","id":"PRO_M05K_남쪽_소식_004","speaker":"캐서린","text":"응. 매년 열리는 행사지만 올해는 특히 사람이 몰릴 거라고 해. 무슨 일 있어?"},{"k":"line","id":"PRO_M05K_남쪽_소식_005","speaker":"","text":"알고 있는 이야기가 다시 머릿속에서 움직였다. 청신의례, 그 뒤에 일어날 일. 몬드에서 한 번 크게 틀렸던 기억이 그 옆에 나란히 섰다."},{"k":"line","id":"PRO_M05K_남쪽_소식_006","speaker":"나","text":"가 봐야겠어. 구경하고 싶어서라기보다… 그곳에도 무슨 일이 생길 것 같아서. 틀릴 수도 있는데, 그래도 가서 봐야 할 것 같아."},{"k":"line","id":"PRO_M05K_남쪽_소식_007","speaker":"캐서린","text":"그러면 리월 지부에 네 등록을 넘겨 둘게. 남쪽 길은 기사단에 물어봐. 최근 보고가 있을 거야."},{"k":"line","id":"PRO_M05K_남쪽_소식_008","speaker":"","text":"진은 책상에서 내 얼굴을 보고 먼저 의자를 가리켰다."},{"k":"line","id":"PRO_M05K_남쪽_소식_009","speaker":"나","text":"청신의례가 곧 열린다고 들었어요. 제가 알고 있던 이야기에서는 그때 리월에 큰일이 생겨요. 몬드에서처럼 제 기억이 틀릴 수도 있지만… 가 보고 싶어요."},{"k":"line","id":"PRO_M05K_남쪽_소식_010","speaker":"진","text":"가셔야겠군요. 몬드에서처럼 혼자 확인하려 하지는 않으시리라 믿습니다."},{"k":"line","id":"PRO_M05K_남쪽_소식_011","speaker":"나","text":"몬드에서는 제가 먼저 답을 알고 있다고 생각했거든요. 그런데 실제로 본 건 다 달랐어요. 이번에는 아는 척부터 하지 않을게요."},{"k":"line","id":"PRO_M05K_남쪽_소식_012","speaker":"진","text":"그것으로 충분합니다. 리월에서 어려운 일이 생기면 몬드의 명예기사라는 이름을 쓰세요. 기사단이 보증합니다."},{"k":"line","id":"PRO_M05K_남쪽_소식_013","speaker":"나","text":"그건 잊지 않을게요. 가서 막히면 몬드 명예기사라고 큰소리부터 칠게요. 효과가 없으면 단장님 이름도 빌릴 거예요."},{"k":"keep","id":"ISK_M05_K_099","text":"진은 짧게 웃고 남쪽 도로에 관한 보고를 찾아 주었다. 책상에서 물러나기 전에 명예기사 문서를 다시 접어 넣었다. 처음 받은 소속이 이 도시에 묶어 두는 끈처럼 느껴지지는 않았다. 돌아올 곳이 생긴 것에 가까웠다."},{"k":"line","id":"PRO_M05K_성당_앞_001","speaker":"","text":"성당 앞 계단에서 벤티를 만난 것은 해가 기울 무렵이었다. 그는 난간에 앉아 발을 흔들고 있었다."},{"k":"line","id":"PRO_M05K_성당_앞_002","speaker":"벤티","text":"노래 제목 생각하러 왔어? 이번에는 끝까지 부를 수 있을 것 같아."},{"k":"line","id":"PRO_M05K_성당_앞_003","speaker":"나","text":"그것도 있고, 리월로 갈 생각이라고 말하러 왔어. 청신의례가 곧이래."},{"k":"line","id":"PRO_M05K_성당_앞_004","speaker":"벤티","text":"그래? 그럼 노래는 네가 돌아올 때까지 미뤄도 되겠네. 끝이 길어지는 건 나쁘지 않아."},{"k":"line","id":"PRO_M05K_성당_앞_005","speaker":"나","text":"그리고 너한테 미리 말해야 할 게 있어. 내가 기억하는 이야기에서는, 네가 어떤 걸 잃어. 그게 언제인지, 여기서도 그런지는 모르겠어. 몬드에서 이미 한 번 틀렸으니까."},{"k":"line","id":"PRO_M05K_성당_앞_006","speaker":"벤티","text":"…그렇게 말해 줘서 고마워. 무엇을 잃는지는 묻지 않을게. 네가 틀렸을 때 네가 더 아플 테니까."},{"k":"line","id":"PRO_M05K_성당_앞_007","speaker":"나","text":"그렇게 받아 주면 더 미안해지는데."},{"k":"line","id":"PRO_M05K_성당_앞_008","speaker":"벤티","text":"그럼 미안한 채로 같이 걷자. 성문까지. 네 신발이 네 대신 인사를 받는 거 보고 싶어."},{"k":"line","id":"PRO_M05K_성당_앞_009","speaker":"나","text":"내 신발이 나보다 인사를 많이 받네. 알았어, 초소에 가서 좀 자랑하자."},{"k":"line","id":"PRO_M05K_성당_앞_010","speaker":"","text":"벤티가 첫 계단을 내려갔다. 그가 아래쪽 돌을 밟는 순간 계단 아래쪽에서 찬 공기가 올라왔다. 등 뒤의 불빛이 흔들렸다."},{"k":"line","id":"PRO_M05K_성당_앞_011","speaker":"시뇨라","text":"떠날 준비를 하고 있었나 봐. 그 전에 받아 갈 것이 있다."},{"k":"line","id":"PRO_M05K_성당_앞_012","speaker":"","text":"시뇨라가 계단 옆에서 모습을 드러냈다. 양쪽 통로로 우인단 병사들이 들어섰다. 벤티의 발밑에서 얼음이 올라와 발목을 붙들었다."},{"k":"line","id":"PRO_M05K_성당_앞_013","speaker":"벤티","text":"약속을 잡으려면 길드 앞에서 기다리는 편이 나았을 텐데. 여기서는 환영받기 어려워."},{"k":"line","id":"PRO_M05K_성당_앞_014","speaker":"시뇨라","text":"아직도 환영받을 자리를 고를 처지라고 생각하나."},{"k":"line","id":"PRO_M05K_성당_앞_015","speaker":"","text":"벤티를 붙들고 있는 얼음을 보았다. 시뇨라의 시선이 나에게 돌아오면 짧게라도 시간이 생긴다. 그 생각만 했다."},{"k":"line","id":"PRO_M05K_성당_앞_016","speaker":"나","text":"잠깐만요. 부하들이 죽은 건 알고 계세요? 사당에서 봤어요. 한두 명이 아니었어요."},{"k":"line","id":"PRO_M05K_성당_앞_017","speaker":"","text":"시뇨라의 시선이 나에게 돌아왔다. 그녀는 얼굴을 자세히 보려는 듯 잠깐 멈췄다가, 흥미를 잃은 눈으로 돌아갔다."},{"k":"line","id":"PRO_M05K_성당_앞_018","speaker":"시뇨라","text":"무슨 헛소리지. 처음 보는 자가 확인도 되지 않은 이야기를 떠드는구나."},{"k":"line","id":"PRO_M05K_성당_앞_019","speaker":"나","text":"확인 안 하고 하는 말이 아니에요. 제가 직접 봤고, 기사단도 알아요. 그쪽끼리 모르는 일이 있는 것 같은데요."},{"k":"line","id":"PRO_M05K_성당_앞_020","speaker":"시뇨라","text":"그 헛소리는 기사단에 가서 계속해라. 내 시간을 빼앗을 만한 이야기는 아니다."},{"k":"line","id":"PRO_M05K_성당_앞_021","speaker":"","text":"그녀의 대답에는 놀랐다는 말도, 부하를 잃은 분노도 없었다. 그 태도가 가장 차가웠다. 얼음이 벤티의 무릎까지 올라왔다."},{"k":"line","id":"PRO_M05K_성당_앞_022","speaker":"나","text":"벤티, 뒤로!"},{"k":"line","id":"PRO_M05K_성당_앞_023","speaker":"","text":"경고가 끝나기 전에 벤티의 등이 난간에 부딪혔다. 시뇨라가 그의 가슴 앞에 손을 뻗었다. 병사들이 내 팔을 붙잡았다."},{"k":"line","id":"PRO_M05K_성당_앞_024","speaker":"시뇨라","text":"겨우 이걸 지키려고 그렇게 오래 끌었나. 기대했던 것보다는 초라하다."},{"k":"line","id":"PRO_M05K_성당_앞_025","speaker":"벤티","text":"남의 물건을 가져가면서 감상까지 남겨 주다니… 예의가 아주 독특하구나."},{"k":"keep","id":"ISK_M05_K_123"},{"k":"line","id":"PRO_M05K_성당_앞_026","speaker":"","text":"벤티가 계단에 주저앉았다. 붙잡고 있던 손이 풀리자 뛰어갔다. 뭐라고 불러야 하는지 몰라서 그냥 이름을 불렀다."},{"k":"line","id":"PRO_M05K_성당_앞_027","speaker":"나","text":"벤티. 나 봐. 들려?"},{"k":"line","id":"PRO_M05K_성당_앞_028","speaker":"벤티","text":"…들려. 조금 안 좋은 소식이 있는데, 들을래?"},{"k":"line","id":"PRO_M05K_성당_앞_029","speaker":"나","text":"이미 충분히 안 좋아. 더 나빠져도 되니까 말해."},{"k":"line","id":"PRO_M05K_성당_앞_030","speaker":"벤티","text":"가져간 건 신의 심장이야. 바르바토스의. 네가 말한 「잃는 것」이 이거였나 봐."},{"k":"line","id":"PRO_M05K_성당_앞_031","speaker":"나","text":"…"},{"k":"line","id":"PRO_M05K_성당_앞_032","speaker":"","text":"네가 말한. 그 말이 가슴에 박혔다. 알고 있었다. 알고 있다고 말해 놓고도 막지 못했다."},{"k":"line","id":"PRO_M05K_성당_앞_033","speaker":"벤티","text":"미안. 네가 미리 말해 줬는데 내가 더 조심하지 않았어."},{"k":"line","id":"PRO_M05K_성당_앞_034","speaker":"나","text":"네가 사과할 일이 아니야. 그리고 나는… 그 사람이 오늘 올 줄은 몰랐어. 아는 게 아니었어. 아는 척이었어."},{"k":"line","id":"PRO_M05K_성당_앞_035","speaker":"벤티","text":"그래도 네 덕에 한 가지는 알았어. 저 사람은 자기 부하가 죽은 걸 몰랐거나, 알고도 아무렇지 않은 사람이야."},{"k":"line","id":"PRO_M05K_성당_앞_036","speaker":"나","text":"그 부하들 이야기도요. 시뇨라는 헛소리라고 했어요. 진 단장님께 그대로 전할게요."},{"k":"line","id":"PRO_M05K_성당_앞_037","speaker":"","text":"벤티는 난간을 잡고 일어섰다. 다리가 흔들렸다. 손을 내밀자 그가 잡았다. 설산에서 진이 내게 그랬던 것처럼."},{"k":"line","id":"PRO_M05K_성당_앞_038","speaker":"나","text":"리월에 가겠다고 방금 이야기했는데, 이런 일을 두고 가는 게 맞나 모르겠어."},{"k":"line","id":"PRO_M05K_성당_앞_039","speaker":"벤티","text":"가. 저 사람이 다음에 갈 곳이 어디일지, 네가 나보다 잘 알지도 몰라. 틀려도 돼. 가서 보는 사람이 있어야 해."},{"k":"line","id":"PRO_M05K_성당_앞_040","speaker":"나","text":"그건 알겠는데, 적어도 오늘은 여기 있어. 내가 보고 있을 테니까 그냥 앉아 있어."},{"k":"line","id":"PRO_M05K_성당_앞_041","speaker":"벤티","text":"…그럴게. 오늘은 네가 보고 있어 줘."},{"k":"keep","id":"ISK_M05_K_142"},{"k":"line","id":"PRO_M05K_다음_날_001","speaker":"케이아","text":"다 끝났어. 이제 내가 자네에게 남길 말은 하나야. 리월에 도착하면 도착했다고 적어 보내. 길어야 두 줄."},{"k":"line","id":"PRO_M05K_다음_날_002","speaker":"나","text":"알겠어요. 첫 줄에 잘 도착했다고 크게 써 둘게요. 둘째 줄에 신발도 아직 멀쩡하다고 쓰면 되죠?"},{"k":"line","id":"PRO_M05K_다음_날_003","speaker":"케이아","text":"그 정도면 엠버가 가장 먼저 읽어도 괜찮겠군."},{"k":"line","id":"PRO_M05K_다음_날_004","speaker":"","text":"알베도는 마지막 현장 도면의 사본을 보관하겠다고 했다. 설산의 구슬에 관한 기록은 그가 맡기로 했다."},{"k":"line","id":"PRO_M05K_다음_날_005","speaker":"알베도","text":"이제 날씨 기록으로 분류할 일은 없겠어. 확인할 내용이 생기면 보내 줄게. 네가 틀렸다고 생각한 것들도 적어 두면 좋아."},{"k":"line","id":"PRO_M05K_다음_날_006","speaker":"나","text":"틀린 걸 모아 놓으면 꽤 두꺼운 책이 될 것 같은데."},{"k":"line","id":"PRO_M05K_다음_날_007","speaker":"알베도","text":"그 책 덕분에 같은 실수를 줄일 수 있다면 들고 다닐 가치는 있겠지. 너는 이미 한 권 들고 있고."},{"k":"line","id":"PRO_M05K_다음_날_008","speaker":"","text":"성문 근처에서는 엠버가 길을 기다리고 있었다. 그녀는 이번에도 가방끈부터 보고, 매듭을 다시 묶어 줬다."},{"k":"line","id":"PRO_M05K_다음_날_009","speaker":"엠버","text":"좋아, 이제 내 일 하나 줄었네. 돌아오면 그 매듭 그대로 보여 줘. 그동안 한 번도 안 풀었다는 뜻이니까."},{"k":"line","id":"PRO_M05K_다음_날_010","speaker":"나","text":"출발하는 사람한테 숙제까지 내줘? 좋아. 대신 돌아오면 네가 먼저 풀 수 있는지 보자. 이 매듭 나도 못 풀어."},{"k":"line","id":"PRO_M05K_다음_날_011","speaker":"엠버","text":"좋아, 약속했어! 내가 먼저 풀면 그동안 어디서 뭘 했는지 실컷 들려주기. 빠뜨리지 말고!"},{"k":"line","id":"PRO_M05K_다음_날_012","speaker":"","text":"진은 손을 내밀었다. 산에서 일어나게 해 줄 때와 같은 손이었다."},{"k":"line","id":"PRO_M05K_다음_날_013","speaker":"진","text":"다시 도움이 필요하면 연락하십시오. 함께 조사하겠다는 약속은 장소가 달라져도 그대로입니다."},{"k":"line","id":"PRO_M05K_다음_날_014","speaker":"나","text":"네. 저도 돌아왔을 때 어떤 일이 있었는지 제 입으로 설명할 수 있도록 다녀올게요. 이번에는 아는 척 말고, 본 걸로요."},{"k":"line","id":"PRO_M05K_다음_날_015","speaker":"","text":"마지막으로 벤티가 성문 안쪽에서 손을 들었다. 그는 전날보다 천천히 걸었지만, 웃고 있었다."},{"k":"line","id":"PRO_M05K_다음_날_016","speaker":"벤티","text":"생각해 봤는데, 아직 제목을 정하지 않아도 될 것 같아. 네가 돌아와서 끝을 들려주면 그때 정하자."},{"k":"line","id":"PRO_M05K_다음_날_017","speaker":"나","text":"그러면 돌아올 이유가 하나 더 생기네. 대신 내가 늦는다고 마음대로 슬픈 노래로 끝내지는 마."},{"k":"line","id":"PRO_M05K_다음_날_018","speaker":"벤티","text":"약속할게. 너도 길 위에서 겪은 일을 혼자 끝이라고 부르지 말고."},{"k":"keep","id":"ISK_M05_K_161"},{"k":"keep","id":"ISK_M05_K_END"}],"edits":[]}]};})(globalThis);
